Theorem Aumann_agreement_modal : forall n m phi,
  |- Iff phi phi /\
  |- Impl (Box n phi) (Box (Nat.max n m) phi) /\
  |- Impl (Box m phi) (Box (Nat.max n m) phi).
Proof.
  intros n m phi. split; [|split].
