  pose proof (licensing_consistency_concrete (Nat.max n m) phi Hmaxphi) as Hcons.
  split.
  - exact Hcons.
  - intro Hneg.
    apply (meta_no_contradiction (Nat.max n m) phi).
    split; [exact Hmaxphi | exact Hneg].
Qed.

