Lemma FOdelta0_FODMONS1 : forall cs B ct dt c1 d1 c2 d2 c3 d3 cr dr
    len c d,
  tbl_below B ct dt c1 d1 c2 d2 c3 d3 cr dr len ->
  FOmax_var_tm d < B ->
  FOdelta0 (FODMONS1 B ct dt c1 d1 c2 d2 c3 d3 cr dr len c cs d).
