Lemma step4_sem_ext : forall L L' x sc pc r,
  (forall a b c d f, L a b c d f <-> L' a b c d f) ->
  (step4_sem L x sc pc r <-> step4_sem L' x sc pc r).
Proof.
  intros L L' x sc pc r HL. unfold step4_sem.
  split; intro H;
    destruct H as [H|[H|[H|[H|H]]]];
    [left | right; left | right; right; left
    | right; right; right; left | right; right; right; right
    | left | right; left | right; right; left
    | right; right; right; left | right; right; right; right];
    try exact H.
  - destruct H as [p [H1 [H2 [pa [H3 [pb [H4 [H5 H6]]]]]]]].
    exists p. split; [exact H1|]. split; [exact H2|].
    exists pa. split; [exact H3|]. exists pb. split; [exact H4|].
    split; [exact H5|].
    destruct H6 as [[Ha Hb]|[Ha Hb]].
    + left. split; [rewrite <- (HL 4 x sc pa 0); exact Ha | exact Hb].
    + right. split; [rewrite <- (HL 4 x sc pa 1); exact Ha
                    |rewrite <- (HL 4 x sc pb r); exact Hb].
  - destruct H as [p [H1 [H2 [y [H3 [pb [H4 [H5 H6]]]]]]]].
    exists p. split; [exact H1|]. split; [exact H2|].
    exists y. split; [exact H3|]. exists pb. split; [exact H4|].
    split; [exact H5|].
    destruct H6 as [H6|[Ha H6]]; [left; exact H6|].
    right. split; [exact Ha|].
    destruct H6 as [[Hb Hc]|[Hb H6]].
    + left. split; [rewrite <- (HL 1 x pb 0 0); exact Hb | exact Hc].
    + right. split; [rewrite <- (HL 1 x pb 0 1); exact Hb|].
      destruct H6 as [[Hd He]|[Hd He]].
      * left. split; [rewrite <- (HL 0 y sc 0 1); exact Hd | exact He].
      * right. split; [rewrite <- (HL 0 y sc 0 0); exact Hd
                      |rewrite <- (HL 4 x sc pb r); exact He].
  - destruct H as [p [H1 [H2 [y [H3 [pb [H4 [H5 H6]]]]]]]].
    exists p. split; [exact H1|]. split; [exact H2|].
    exists y. split; [exact H3|]. exists pb. split; [exact H4|].
    split; [exact H5|].
    destruct H6 as [H6|[Ha H6]]; [left; exact H6|].
    right. split; [exact Ha|].
    destruct H6 as [[Hb Hc]|[Hb H6]].
    + left. split; [rewrite <- (HL 1 x pb 0 0); exact Hb | exact Hc].
    + right. split; [rewrite <- (HL 1 x pb 0 1); exact Hb|].
      destruct H6 as [[Hd He]|[Hd He]].
      * left. split; [rewrite <- (HL 0 y sc 0 1); exact Hd | exact He].
      * right. split; [rewrite <- (HL 0 y sc 0 0); exact Hd
                      |rewrite <- (HL 4 x sc pb r); exact He].
  - destruct H as [p [H1 [H2 [pa [H3 [pb [H4 [H5 H6]]]]]]]].
    exists p. split; [exact H1|]. split; [exact H2|].
    exists pa. split; [exact H3|]. exists pb. split; [exact H4|].
    split; [exact H5|].
    destruct H6 as [[Ha Hb]|[Ha Hb]].
    + left. split; [rewrite (HL 4 x sc pa 0); exact Ha | exact Hb].
    + right. split; [rewrite (HL 4 x sc pa 1); exact Ha
                    |rewrite (HL 4 x sc pb r); exact Hb].
  - destruct H as [p [H1 [H2 [y [H3 [pb [H4 [H5 H6]]]]]]]].
    exists p. split; [exact H1|]. split; [exact H2|].
    exists y. split; [exact H3|]. exists pb. split; [exact H4|].
    split; [exact H5|].
    destruct H6 as [H6|[Ha H6]]; [left; exact H6|].
    right. split; [exact Ha|].
    destruct H6 as [[Hb Hc]|[Hb H6]].
    + left. split; [rewrite (HL 1 x pb 0 0); exact Hb | exact Hc].
    + right. split; [rewrite (HL 1 x pb 0 1); exact Hb|].
      destruct H6 as [[Hd He]|[Hd He]].
      * left. split; [rewrite (HL 0 y sc 0 1); exact Hd | exact He].
      * right. split; [rewrite (HL 0 y sc 0 0); exact Hd
                      |rewrite (HL 4 x sc pb r); exact He].
  - destruct H as [p [H1 [H2 [y [H3 [pb [H4 [H5 H6]]]]]]]].
    exists p. split; [exact H1|]. split; [exact H2|].
    exists y. split; [exact H3|]. exists pb. split; [exact H4|].
    split; [exact H5|].
    destruct H6 as [H6|[Ha H6]]; [left; exact H6|].
    right. split; [exact Ha|].
    destruct H6 as [[Hb Hc]|[Hb H6]].
    + left. split; [rewrite (HL 1 x pb 0 0); exact Hb | exact Hc].
    + right. split; [rewrite (HL 1 x pb 0 1); exact Hb|].
      destruct H6 as [[Hd He]|[Hd He]].
      * left. split; [rewrite (HL 0 y sc 0 1); exact Hd | exact He].
      * right. split; [rewrite (HL 0 y sc 0 0); exact Hd
                      |rewrite (HL 4 x sc pb r); exact He].
Qed.

Lemma step5_sem_ext : forall L L' a1 r,
  (forall a b c d f, L a b c d f <-> L' a b c d f) ->
  (step5_sem L a1 r <-> step5_sem L' a1 r).
Proof.
  intros L L' a1 r HL. unfold step5_sem.
  split; intro H; destruct H as [H|H]; [left; exact H | right
                                       |left; exact H | right];
    destruct H as [k' [H1 [H2 [r' [H3 [H4 H5]]]]]];
    exists k'; (split; [exact H1|]); (split; [exact H2|]);
    exists r'; (split; [exact H3|]).
  - split; [rewrite <- (HL 5 k' 0 0 r'); exact H4 | exact H5].
  - split; [rewrite (HL 5 k' 0 0 r'); exact H4 | exact H5].
Qed.

Lemma FOsat_FOSTEPDISPATCH : forall e B ct dt c1 d1 c2 d2 c3 d3 cr dr
    len j,
  tbl_below B ct dt c1 d1 c2 d2 c3 d3 cr dr len ->
  FOmax_var_tm j < B ->
  (FOsat e (FOSTEPDISPATCH B ct dt c1 d1 c2 d2 c3 d3 cr dr len j)
   <-> dispatch_sem
         (fun tg x1 x2 x3 rr => exists j', j' < FOeval e len /\
            beta (FOeval e ct) (FOeval e dt) j' = tg /\
            beta (FOeval e c1) (FOeval e d1) j' = x1 /\
            beta (FOeval e c2) (FOeval e d2) j' = x2 /\
            beta (FOeval e c3) (FOeval e d3) j' = x3 /\
            beta (FOeval e cr) (FOeval e dr) j' = rr)
         (FOeval e ct) (FOeval e dt) (FOeval e c1) (FOeval e d1)
         (FOeval e c2) (FOeval e d2) (FOeval e c3) (FOeval e d3)
         (FOeval e cr) (FOeval e dr) (FOeval e j)).
Proof.
  intros e B ct dt c1 d1 c2 d2 c3 d3 cr dr len j Htb Hj.
  pose proof Htb as Htb'.
  destruct Htb' as [Hct [Hdt [Hc1 [Hd1 [Hc2 [Hd2 [Hc3 [Hd3
    [Hcr [Hdr Hlen]]]]]]]]]].
  assert (Htb30 : tbl_below (B+30) ct dt c1 d1 c2 d2 c3 d3 cr dr len)
    by (unfold tbl_below; lia).
  assert (E02 : Nat.eqb B (B+2) = false) by (apply Nat.eqb_neq; lia).
  assert (E04 : Nat.eqb B (B+4) = false) by (apply Nat.eqb_neq; lia).
  assert (E06 : Nat.eqb B (B+6) = false) by (apply Nat.eqb_neq; lia).
  assert (E08 : Nat.eqb B (B+8) = false) by (apply Nat.eqb_neq; lia).
  assert (E24 : Nat.eqb (B+2) (B+4) = false) by (apply Nat.eqb_neq; lia).
  assert (E26 : Nat.eqb (B+2) (B+6) = false) by (apply Nat.eqb_neq; lia).
  assert (E28 : Nat.eqb (B+2) (B+8) = false) by (apply Nat.eqb_neq; lia).
  assert (E46 : Nat.eqb (B+4) (B+6) = false) by (apply Nat.eqb_neq; lia).
  assert (E48 : Nat.eqb (B+4) (B+8) = false) by (apply Nat.eqb_neq; lia).
  assert (E68 : Nat.eqb (B+6) (B+8) = false) by (apply Nat.eqb_neq; lia).
  unfold FOSTEPDISPATCH, dispatch_sem.
  rewrite (FOsat_FOBexC e B (FOSucc ct) _
             (FOin_tm_above (FOSucc ct) B ltac:(cbn; lia))
             (FOin_tm_above (FOSucc ct) (S B) ltac:(cbn; lia))).
  assert (Es0 : FOeval e (FOSucc ct) = S (FOeval e ct)) by reflexivity.
  rewrite Es0.
  apply Morphisms_Prop.ex_iff_morphism. intro tg.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  set (e1 := FOupdate e B tg).
  assert (Eu1 : forall t0, FOmax_var_tm t0 < B ->
      FOeval e1 t0 = FOeval e t0).
  { intros t0 Ht0. unfold e1. exact (FOeval_upd_above t0 e B tg Ht0). }
  rewrite (FOsat_FOBexC e1 (B+2) (FOSucc c1) _
             (FOin_tm_above (FOSucc c1) (B+2) ltac:(cbn; lia))
             (FOin_tm_above (FOSucc c1) (S (B+2)) ltac:(cbn; lia))).
  assert (Es1 : FOeval e1 (FOSucc c1) = S (FOeval e c1)).
  { change (S (FOeval e1 c1) = S (FOeval e c1)).
    rewrite (Eu1 c1 Hc1). reflexivity. }
  rewrite Es1.
  apply Morphisms_Prop.ex_iff_morphism. intro a1.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  set (e2 := FOupdate e1 (B+2) a1).
  assert (Eu2 : forall t0, FOmax_var_tm t0 < B ->
      FOeval e2 t0 = FOeval e t0).
  { intros t0 Ht0. unfold e2.
    rewrite (FOeval_upd_above t0 _ (B+2) a1 ltac:(lia)).
    exact (Eu1 t0 Ht0). }
  rewrite (FOsat_FOBexC e2 (B+4) (FOSucc c2) _
             (FOin_tm_above (FOSucc c2) (B+4) ltac:(cbn; lia))
             (FOin_tm_above (FOSucc c2) (S (B+4)) ltac:(cbn; lia))).
  assert (Es2 : FOeval e2 (FOSucc c2) = S (FOeval e c2)).
  { change (S (FOeval e2 c2) = S (FOeval e c2)).
    rewrite (Eu2 c2 Hc2). reflexivity. }
  rewrite Es2.
  apply Morphisms_Prop.ex_iff_morphism. intro a2.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  set (e3 := FOupdate e2 (B+4) a2).
  assert (Eu3 : forall t0, FOmax_var_tm t0 < B ->
      FOeval e3 t0 = FOeval e t0).
  { intros t0 Ht0. unfold e3.
    rewrite (FOeval_upd_above t0 _ (B+4) a2 ltac:(lia)).
    exact (Eu2 t0 Ht0). }
  rewrite (FOsat_FOBexC e3 (B+6) (FOSucc c3) _
             (FOin_tm_above (FOSucc c3) (B+6) ltac:(cbn; lia))
             (FOin_tm_above (FOSucc c3) (S (B+6)) ltac:(cbn; lia))).
  assert (Es3 : FOeval e3 (FOSucc c3) = S (FOeval e c3)).
  { change (S (FOeval e3 c3) = S (FOeval e c3)).
    rewrite (Eu3 c3 Hc3). reflexivity. }
  rewrite Es3.
  apply Morphisms_Prop.ex_iff_morphism. intro a3.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  set (e4 := FOupdate e3 (B+6) a3).
  assert (Eu4 : forall t0, FOmax_var_tm t0 < B ->
      FOeval e4 t0 = FOeval e t0).
  { intros t0 Ht0. unfold e4.
    rewrite (FOeval_upd_above t0 _ (B+6) a3 ltac:(lia)).
    exact (Eu3 t0 Ht0). }
  rewrite (FOsat_FOBexC e4 (B+8) (FOSucc cr) _
             (FOin_tm_above (FOSucc cr) (B+8) ltac:(cbn; lia))
             (FOin_tm_above (FOSucc cr) (S (B+8)) ltac:(cbn; lia))).
  assert (Es4 : FOeval e4 (FOSucc cr) = S (FOeval e cr)).
  { change (S (FOeval e4 cr) = S (FOeval e cr)).
    rewrite (Eu4 cr Hcr). reflexivity. }
  rewrite Es4.
  apply Morphisms_Prop.ex_iff_morphism. intro rr.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  set (e5 := FOupdate e4 (B+8) rr).
  assert (Eu5 : forall t0, FOmax_var_tm t0 < B ->
      FOeval e5 t0 = FOeval e t0).
  { intros t0 Ht0. unfold e5.
    rewrite (FOeval_upd_above t0 _ (B+8) rr ltac:(lia)).
    exact (Eu4 t0 Ht0). }
  assert (EvB : FOeval e5 (FOVar B) = tg).
  { unfold e5, e4, e3, e2, e1. cbn. unfold FOupdate.
    rewrite E08, E06, E04, E02, Nat.eqb_refl. reflexivity. }
  assert (EvB2 : FOeval e5 (FOVar (B+2)) = a1).
  { unfold e5, e4, e3, e2. cbn. unfold FOupdate.
    rewrite E28, E26, E24, Nat.eqb_refl. reflexivity. }
  assert (EvB4 : FOeval e5 (FOVar (B+4)) = a2).
  { unfold e5, e4, e3. cbn. unfold FOupdate.
    rewrite E48, E46, Nat.eqb_refl. reflexivity. }
  assert (EvB6 : FOeval e5 (FOVar (B+6)) = a3).
  { unfold e5, e4. cbn. unfold FOupdate.
    rewrite E68, Nat.eqb_refl. reflexivity. }
  assert (EvB8 : FOeval e5 (FOVar (B+8)) = rr).
  { unfold e5. cbn. unfold FOupdate.
    rewrite Nat.eqb_refl. reflexivity. }
  rewrite (FOsat_FOAnd e5 _ _).
  rewrite (FOsat_FObetaF e5 (B+10) ct dt j (FOVar B)
             ltac:(lia) ltac:(lia) ltac:(lia) ltac:(cbn; lia)).
  rewrite (Eu5 ct Hct), (Eu5 dt Hdt), (Eu5 j Hj), EvB.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  rewrite (FOsat_FOAnd e5 _ _).
  rewrite (FOsat_FObetaF e5 (B+14) c1 d1 j (FOVar (B+2))
             ltac:(lia) ltac:(lia) ltac:(lia) ltac:(cbn; lia)).
  rewrite (Eu5 c1 Hc1), (Eu5 d1 Hd1), (Eu5 j Hj), EvB2.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  rewrite (FOsat_FOAnd e5 _ _).
  rewrite (FOsat_FObetaF e5 (B+18) c2 d2 j (FOVar (B+4))
             ltac:(lia) ltac:(lia) ltac:(lia) ltac:(cbn; lia)).
  rewrite (Eu5 c2 Hc2), (Eu5 d2 Hd2), (Eu5 j Hj), EvB4.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  rewrite (FOsat_FOAnd e5 _ _).
  rewrite (FOsat_FObetaF e5 (B+22) c3 d3 j (FOVar (B+6))
             ltac:(lia) ltac:(lia) ltac:(lia) ltac:(cbn; lia)).
  rewrite (Eu5 c3 Hc3), (Eu5 d3 Hd3), (Eu5 j Hj), EvB6.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  rewrite (FOsat_FOAnd e5 _ _).
  rewrite (FOsat_FObetaF e5 (B+26) cr dr j (FOVar (B+8))
             ltac:(lia) ltac:(lia) ltac:(lia) ltac:(cbn; lia)).
  rewrite (Eu5 cr Hcr), (Eu5 dr Hdr), (Eu5 j Hj), EvB8.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  rewrite (FOsat_FOOr e5 _ _).
  apply Morphisms_Prop.or_iff_morphism.
  { rewrite (FOsat_FOAnd e5 _ _).
    change (FOsat e5 (FOEq (FOVar B) FOZero))
      with (FOeval e5 (FOVar B) = FOeval e5 FOZero).
    change (FOeval e5 FOZero) with 0.
    rewrite EvB.
    apply Morphisms_Prop.and_iff_morphism; [tauto|].
    rewrite (FOsat_FOSTEP0 e5 (B+30) ct dt c1 d1 c2 d2 c3 d3 cr dr len
               (FOVar (B+2)) (FOVar (B+4)) (FOVar (B+8)) Htb30
               ltac:(cbn; lia) ltac:(cbn; lia) ltac:(cbn; lia)).
    rewrite EvB2, EvB4, EvB8.
    apply step0_sem_ext.
    intros a b c d f.
    setoid_rewrite (Eu5 len Hlen).
    setoid_rewrite (Eu5 ct Hct). setoid_rewrite (Eu5 dt Hdt).
    setoid_rewrite (Eu5 c1 Hc1). setoid_rewrite (Eu5 d1 Hd1).
    setoid_rewrite (Eu5 c2 Hc2). setoid_rewrite (Eu5 d2 Hd2).
    setoid_rewrite (Eu5 c3 Hc3). setoid_rewrite (Eu5 d3 Hd3).
    setoid_rewrite (Eu5 cr Hcr). setoid_rewrite (Eu5 dr Hdr).
    reflexivity. }
  rewrite (FOsat_FOOr e5 _ _).
  apply Morphisms_Prop.or_iff_morphism.
  { rewrite (FOsat_FOAnd e5 _ _).
    change (FOsat e5 (FOEq (FOVar B) (FOnumeral 1)))
      with (FOeval e5 (FOVar B) = FOeval e5 (FOnumeral 1)).
    rewrite EvB, FOeval_numeral.
    apply Morphisms_Prop.and_iff_morphism; [tauto|].
    rewrite (FOsat_FOSTEP1 e5 (B+30) ct dt c1 d1 c2 d2 c3 d3 cr dr len
               (FOVar (B+2)) (FOVar (B+4)) (FOVar (B+8)) Htb30
               ltac:(cbn; lia) ltac:(cbn; lia) ltac:(cbn; lia)).
    rewrite EvB2, EvB4, EvB8.
    apply step1_sem_ext.
    intros a b c d f.
    setoid_rewrite (Eu5 len Hlen).
    setoid_rewrite (Eu5 ct Hct). setoid_rewrite (Eu5 dt Hdt).
    setoid_rewrite (Eu5 c1 Hc1). setoid_rewrite (Eu5 d1 Hd1).
    setoid_rewrite (Eu5 c2 Hc2). setoid_rewrite (Eu5 d2 Hd2).
    setoid_rewrite (Eu5 c3 Hc3). setoid_rewrite (Eu5 d3 Hd3).
    setoid_rewrite (Eu5 cr Hcr). setoid_rewrite (Eu5 dr Hdr).
    reflexivity. }
  rewrite (FOsat_FOOr e5 _ _).
  apply Morphisms_Prop.or_iff_morphism.
  { rewrite (FOsat_FOAnd e5 _ _).
    change (FOsat e5 (FOEq (FOVar B) (FOnumeral 2)))
      with (FOeval e5 (FOVar B) = FOeval e5 (FOnumeral 2)).
    rewrite EvB, FOeval_numeral.
    apply Morphisms_Prop.and_iff_morphism; [tauto|].
    rewrite (FOsat_FOSTEP2 e5 (B+30) ct dt c1 d1 c2 d2 c3 d3 cr dr len
               (FOVar (B+2)) (FOVar (B+4)) (FOVar (B+6)) (FOVar (B+8))
               Htb30 ltac:(cbn; lia) ltac:(cbn; lia) ltac:(cbn; lia)
               ltac:(cbn; lia)).
    rewrite EvB2, EvB4, EvB6, EvB8.
    apply step2_sem_ext.
    intros a b c d f.
    setoid_rewrite (Eu5 len Hlen).
    setoid_rewrite (Eu5 ct Hct). setoid_rewrite (Eu5 dt Hdt).
    setoid_rewrite (Eu5 c1 Hc1). setoid_rewrite (Eu5 d1 Hd1).
    setoid_rewrite (Eu5 c2 Hc2). setoid_rewrite (Eu5 d2 Hd2).
    setoid_rewrite (Eu5 c3 Hc3). setoid_rewrite (Eu5 d3 Hd3).
    setoid_rewrite (Eu5 cr Hcr). setoid_rewrite (Eu5 dr Hdr).
    reflexivity. }
  rewrite (FOsat_FOOr e5 _ _).
  apply Morphisms_Prop.or_iff_morphism.
  { rewrite (FOsat_FOAnd e5 _ _).
    change (FOsat e5 (FOEq (FOVar B) (FOnumeral 3)))
      with (FOeval e5 (FOVar B) = FOeval e5 (FOnumeral 3)).
    rewrite EvB, FOeval_numeral.
    apply Morphisms_Prop.and_iff_morphism; [tauto|].
    rewrite (FOsat_FOSTEP3 e5 (B+30) ct dt c1 d1 c2 d2 c3 d3 cr dr len
               (FOVar (B+2)) (FOVar (B+4)) (FOVar (B+6)) (FOVar (B+8))
               Htb30 ltac:(cbn; lia) ltac:(cbn; lia) ltac:(cbn; lia)
               ltac:(cbn; lia)).
    rewrite EvB2, EvB4, EvB6, EvB8.
    apply step3_sem_ext.
    intros a b c d f.
    setoid_rewrite (Eu5 len Hlen).
    setoid_rewrite (Eu5 ct Hct). setoid_rewrite (Eu5 dt Hdt).
    setoid_rewrite (Eu5 c1 Hc1). setoid_rewrite (Eu5 d1 Hd1).
    setoid_rewrite (Eu5 c2 Hc2). setoid_rewrite (Eu5 d2 Hd2).
    setoid_rewrite (Eu5 c3 Hc3). setoid_rewrite (Eu5 d3 Hd3).
    setoid_rewrite (Eu5 cr Hcr). setoid_rewrite (Eu5 dr Hdr).
    reflexivity. }
  rewrite (FOsat_FOOr e5 _ _).
  apply Morphisms_Prop.or_iff_morphism.
  { rewrite (FOsat_FOAnd e5 _ _).
    change (FOsat e5 (FOEq (FOVar B) (FOnumeral 4)))
      with (FOeval e5 (FOVar B) = FOeval e5 (FOnumeral 4)).
    rewrite EvB, FOeval_numeral.
    apply Morphisms_Prop.and_iff_morphism; [tauto|].
    rewrite (FOsat_FOSTEP4 e5 (B+30) ct dt c1 d1 c2 d2 c3 d3 cr dr len
               (FOVar (B+2)) (FOVar (B+4)) (FOVar (B+6)) (FOVar (B+8))
               Htb30 ltac:(cbn; lia) ltac:(cbn; lia) ltac:(cbn; lia)
               ltac:(cbn; lia)).
    rewrite EvB2, EvB4, EvB6, EvB8.
    apply step4_sem_ext.
    intros a b c d f.
    setoid_rewrite (Eu5 len Hlen).
    setoid_rewrite (Eu5 ct Hct). setoid_rewrite (Eu5 dt Hdt).
    setoid_rewrite (Eu5 c1 Hc1). setoid_rewrite (Eu5 d1 Hd1).
    setoid_rewrite (Eu5 c2 Hc2). setoid_rewrite (Eu5 d2 Hd2).
    setoid_rewrite (Eu5 c3 Hc3). setoid_rewrite (Eu5 d3 Hd3).
    setoid_rewrite (Eu5 cr Hcr). setoid_rewrite (Eu5 dr Hdr).
    reflexivity. }
  { rewrite (FOsat_FOAnd e5 _ _).
    change (FOsat e5 (FOEq (FOVar B) (FOnumeral 5)))
      with (FOeval e5 (FOVar B) = FOeval e5 (FOnumeral 5)).
    rewrite EvB, FOeval_numeral.
    apply Morphisms_Prop.and_iff_morphism; [tauto|].
    rewrite (FOsat_FOSTEP5 e5 (B+30) ct dt c1 d1 c2 d2 c3 d3 cr dr len
               (FOVar (B+2)) (FOVar (B+8)) Htb30
               ltac:(cbn; lia) ltac:(cbn; lia)).
    rewrite EvB2, EvB8.
    apply step5_sem_ext.
    intros a b c d f.
    setoid_rewrite (Eu5 len Hlen).
    setoid_rewrite (Eu5 ct Hct). setoid_rewrite (Eu5 dt Hdt).
    setoid_rewrite (Eu5 c1 Hc1). setoid_rewrite (Eu5 d1 Hd1).
    setoid_rewrite (Eu5 c2 Hc2). setoid_rewrite (Eu5 d2 Hd2).
    setoid_rewrite (Eu5 c3 Hc3). setoid_rewrite (Eu5 d3 Hd3).
    setoid_rewrite (Eu5 cr Hcr). setoid_rewrite (Eu5 dr Hdr).
    reflexivity. }
Qed.

Lemma dispatch_sem_ext : forall L L' vct vdt vc1 vd1 vc2 vd2 vc3 vd3
    vcr vdr vj,
  (forall a b c d f, L a b c d f <-> L' a b c d f) ->
  (dispatch_sem L vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vj
   <-> dispatch_sem L' vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vj).
Proof.
  intros L L' vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vj HL.
  unfold dispatch_sem.
  apply Morphisms_Prop.ex_iff_morphism. intro tg.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  apply Morphisms_Prop.ex_iff_morphism. intro a1.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  apply Morphisms_Prop.ex_iff_morphism. intro a2.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  apply Morphisms_Prop.ex_iff_morphism. intro a3.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  apply Morphisms_Prop.ex_iff_morphism. intro rr.
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  apply Morphisms_Prop.and_iff_morphism; [tauto|].
  apply Morphisms_Prop.or_iff_morphism.
  { apply Morphisms_Prop.and_iff_morphism; [tauto|].
    apply step0_sem_ext. exact HL. }
  apply Morphisms_Prop.or_iff_morphism.
  { apply Morphisms_Prop.and_iff_morphism; [tauto|].
    apply step1_sem_ext. exact HL. }
  apply Morphisms_Prop.or_iff_morphism.
  { apply Morphisms_Prop.and_iff_morphism; [tauto|].
    apply step2_sem_ext. exact HL. }
  apply Morphisms_Prop.or_iff_morphism.
  { apply Morphisms_Prop.and_iff_morphism; [tauto|].
    apply step3_sem_ext. exact HL. }
  apply Morphisms_Prop.or_iff_morphism.
  { apply Morphisms_Prop.and_iff_morphism; [tauto|].
    apply step4_sem_ext. exact HL. }
  { apply Morphisms_Prop.and_iff_morphism; [tauto|].
    apply step5_sem_ext. exact HL. }
Qed.

Lemma FOdelta0_FOTBLVALID : forall B ct dt c1 d1 c2 d2 c3 d3 cr dr len,
  tbl_below B ct dt c1 d1 c2 d2 c3 d3 cr dr len ->
  FOdelta0 (FOTBLVALID B ct dt c1 d1 c2 d2 c3 d3 cr dr len).
Proof.
  intros B ct dt c1 d1 c2 d2 c3 d3 cr dr len Htb.
  pose proof Htb as Htb'.
  destruct Htb' as [Hct [Hdt [Hc1 [Hd1 [Hc2 [Hd2 [Hc3 [Hd3
    [Hcr [Hdr Hlen]]]]]]]]]].
  assert (Htb2 : tbl_below (B+2) ct dt c1 d1 c2 d2 c3 d3 cr dr len)
    by (unfold tbl_below; lia).
  unfold FOTBLVALID.
  apply FOdelta0_FOBallC;
    [apply FOin_tm_above; lia | apply FOin_tm_above; lia |].
  apply FOdelta0_FOSTEPDISPATCH; [exact Htb2 | cbn; lia].
Qed.

(** ** The derivation checker is Delta_0; the matrix is Sigma_1. *)

Lemma FOdelta0_FOGUARDC : forall B ct dt c1 d1 c2 d2 c3 d3 cr dr len
    cs ds i,
  tbl_below B ct dt c1 d1 c2 d2 c3 d3 cr dr len ->
  FOmax_var_tm cs < B -> FOmax_var_tm ds < B -> FOmax_var_tm i < B ->
  FOdelta0 (FOGUARDC B ct dt c1 d1 c2 d2 c3 d3 cr dr len cs ds i).
Proof.
  intros B ct dt c1 d1 c2 d2 c3 d3 cr dr len cs ds i Htb Hcs Hds Hi.
  pose proof Htb as [Hct [Hdt [Hc1 [Hd1 [Hc2 [Hd2 [Hc3 [Hd3
    [Hcr [Hdr Hlen]]]]]]]]]].
  unfold FOGUARDC.
  apply FOdelta0_FOBexC;
    [apply FOin_tm_above; cbn; lia | apply FOin_tm_above; cbn; lia |].
  apply FOdelta0_and.
  - apply FOdelta0_FObetaF; cbn; lia.
  - apply FOdelta0_FOBexC;
      [apply FOin_tm_above; cbn; lia
      |apply FOin_tm_above; cbn; lia |].
    apply FOdelta0_FOlookup;
      [unfold tbl_below; repeat split; lia
      |cbn; lia | cbn; lia | cbn; lia | cbn; lia | cbn; lia].
Qed.

Lemma FOdelta0_FOPRDER : forall cores, FOdelta0 (FOPRDER cores).
Proof.
  intro cores. unfold FOPRDER.
  apply FOdelta0_and.
  { apply FOdelta0_FOTBLVALID.
    unfold tbl_below; repeat split; cbn; lia. }
  apply FOdelta0_and.
  { apply FOdelta0_FOBexC; [reflexivity | reflexivity |].
    apply FOdelta0_and; [apply FOd0_eq|].
    apply FOdelta0_FObetaF; cbn; lia. }
  apply FOdelta0_and.
  { apply FOdelta0_FOBallC; [reflexivity | reflexivity |].
    apply FOdelta0_FOJUSTCK;
      [unfold tbl_below; repeat split; cbn; lia
      |cbn; lia | cbn; lia | cbn; lia | cbn; lia | cbn; lia]. }
  { apply FOdelta0_FOBallC; [reflexivity | reflexivity |].
    apply FOdelta0_FOGUARDC;
      [unfold tbl_below; repeat split; cbn; lia
      |cbn; lia | cbn; lia | cbn; lia]. }
Qed.

Lemma FOsigma1_FOPRMAT : forall cores, FOsigma1 (FOPRMAT cores).
Proof.
  intro cores. unfold FOPRMAT.
  do 16 apply FOs1_ex.
  apply FOs1_d0. apply FOdelta0_FOPRDER.
Qed.

Lemma FOsigma1_FOProvSentence : forall n A,
  FOsigma1 (FOProvSentence n A).
Proof.
  intros n A. unfold FOProvSentence.
  apply FOsigma1_subst_num. apply FOsigma1_subst_num.
  apply FOsigma1_FOPRMAT.
Qed.

Lemma FOsat_FOTBLVALID : forall e B ct dt c1 d1 c2 d2 c3 d3 cr dr len,
  tbl_below B ct dt c1 d1 c2 d2 c3 d3 cr dr len ->
  (FOsat e (FOTBLVALID B ct dt c1 d1 c2 d2 c3 d3 cr dr len)
   <-> forall vj, vj < FOeval e len ->
       dispatch_sem
         (fun tg x1 x2 x3 rr => exists j', j' < FOeval e len /\
            beta (FOeval e ct) (FOeval e dt) j' = tg /\
            beta (FOeval e c1) (FOeval e d1) j' = x1 /\
            beta (FOeval e c2) (FOeval e d2) j' = x2 /\
            beta (FOeval e c3) (FOeval e d3) j' = x3 /\
            beta (FOeval e cr) (FOeval e dr) j' = rr)
         (FOeval e ct) (FOeval e dt) (FOeval e c1) (FOeval e d1)
         (FOeval e c2) (FOeval e d2) (FOeval e c3) (FOeval e d3)
         (FOeval e cr) (FOeval e dr) vj).
Proof.
  intros e B ct dt c1 d1 c2 d2 c3 d3 cr dr len Htb.
  pose proof Htb as Htb'.
  destruct Htb' as [Hct [Hdt [Hc1 [Hd1 [Hc2 [Hd2 [Hc3 [Hd3
    [Hcr [Hdr Hlen]]]]]]]]]].
  assert (Htb2 : tbl_below (B+2) ct dt c1 d1 c2 d2 c3 d3 cr dr len)
    by (unfold tbl_below; lia).
  unfold FOTBLVALID.
  rewrite (FOsat_FOBallC e B len _
             (FOin_tm_above len B ltac:(lia))
             (FOin_tm_above len (S B) ltac:(lia))).
  apply Morphisms_Prop.all_iff_morphism. intro vj.
  apply Morphisms_Prop.iff_iff_iff_impl_morphism; [tauto|].
  set (e1 := FOupdate e B vj).
  assert (Eu1 : forall t0, FOmax_var_tm t0 < B ->
      FOeval e1 t0 = FOeval e t0).
  { intros t0 Ht0. unfold e1. exact (FOeval_upd_above t0 e B vj Ht0). }
  assert (EvB : FOeval e1 (FOVar B) = vj).
  { unfold e1. cbn. unfold FOupdate.
    rewrite Nat.eqb_refl. reflexivity. }
  rewrite (FOsat_FOSTEPDISPATCH e1 (B+2) ct dt c1 d1 c2 d2 c3 d3 cr dr
             len (FOVar B) Htb2 ltac:(cbn; lia)).
  rewrite (Eu1 ct Hct), (Eu1 dt Hdt), (Eu1 c1 Hc1), (Eu1 d1 Hd1),
    (Eu1 c2 Hc2), (Eu1 d2 Hd2), (Eu1 c3 Hc3), (Eu1 d3 Hd3),
    (Eu1 cr Hcr), (Eu1 dr Hdr), EvB.
  apply dispatch_sem_ext.
  intros a b c d f.
  setoid_rewrite (Eu1 len Hlen).
  reflexivity.
Qed.

(** ** Decode equations on paired codes. *)

Lemma cunpair_bound : forall n,
  fst (cunpair n) + snd (cunpair n) <= n.
Proof.
  intro n. pose proof (cpair_cunpair n) as H.
  pose proof (cpair_bound (fst (cunpair n)) (snd (cunpair n))) as Hb.
  lia.
Qed.

Lemma FOdecode_tm_b_stable : forall c d d',
  c < d -> c < d' ->
  FOdecode_tm_b d c = FOdecode_tm_b d' c.
Proof.
  intro c. induction c as [c IH] using lt_wf_ind. intros d d' Hd Hd'.
  destruct d as [|d]; [lia|]. destruct d' as [|d']; [lia|].
  cbn [FOdecode_tm_b].
  pose proof (cunpair_bound c) as Hcb.
  pose proof (cunpair_bound (snd (cunpair c))) as Hpb.
  destruct (fst (cunpair c)) as [|[|[|[|[|t5]]]]] eqn:Etag.
  - reflexivity.
  - reflexivity.
  - f_equal. apply IH; lia.
  - f_equal; apply IH; lia.
  - f_equal; apply IH; lia.
  - reflexivity.
Qed.

Lemma FOdecode_tm_var : forall y, FOdecode_tm (cpair 0 y) = FOVar y.
Proof.
  intro y. unfold FOdecode_tm. cbn [FOdecode_tm_b].
  rewrite cunpair_cpair. reflexivity.
Qed.

Lemma FOdecode_tm_zero : forall z, FOdecode_tm (cpair 1 z) = FOZero.
Proof.
  intro z. unfold FOdecode_tm. cbn [FOdecode_tm_b].
  rewrite cunpair_cpair. reflexivity.
Qed.

Lemma FOdecode_tm_succ : forall p,
  FOdecode_tm (cpair 2 p) = FOSucc (FOdecode_tm p).
Proof.
  intro p. unfold FOdecode_tm at 1. cbn [FOdecode_tm_b].
  rewrite cunpair_cpair. cbn [fst snd].
  f_equal. unfold FOdecode_tm.
  apply FOdecode_tm_b_stable.
  - pose proof (cpair_bound 2 p). lia.
  - lia.
Qed.

Lemma FOdecode_tm_b_plus_step : forall d a b,
  FOdecode_tm_b (S d) (cpair 3 (cpair a b))
  = FOPlus (FOdecode_tm_b d a) (FOdecode_tm_b d b).
Proof.
  intros d a b. cbn [FOdecode_tm_b].
  rewrite cunpair_cpair. cbn [fst snd].
  rewrite cunpair_cpair. cbn [fst snd].
  reflexivity.
Qed.

Lemma FOdecode_tm_plus : forall a b,
  FOdecode_tm (cpair 3 (cpair a b))
  = FOPlus (FOdecode_tm a) (FOdecode_tm b).
Proof.
  intros a b. unfold FOdecode_tm.
  rewrite FOdecode_tm_b_plus_step.
  pose proof (cpair_bound 3 (cpair a b)).
  pose proof (cpair_bound a b).
  f_equal; apply FOdecode_tm_b_stable; lia.
Qed.

Lemma FOdecode_tm_b_mult_step : forall d a b,
  FOdecode_tm_b (S d) (cpair 4 (cpair a b))
  = FOMult (FOdecode_tm_b d a) (FOdecode_tm_b d b).
Proof.
  intros d a b. cbn [FOdecode_tm_b].
  rewrite cunpair_cpair. cbn [fst snd].
  rewrite cunpair_cpair. cbn [fst snd].
  reflexivity.
Qed.

Lemma FOdecode_tm_mult : forall a b,
  FOdecode_tm (cpair 4 (cpair a b))
  = FOMult (FOdecode_tm a) (FOdecode_tm b).
Proof.
  intros a b. unfold FOdecode_tm.
  rewrite FOdecode_tm_b_mult_step.
  pose proof (cpair_bound 4 (cpair a b)).
  pose proof (cpair_bound a b).
  f_equal; apply FOdecode_tm_b_stable; lia.
Qed.

Lemma FOdecode_f_b_stable : forall c d d',
  c < d -> c < d' ->
  FOdecode_f_b d c = FOdecode_f_b d' c.
Proof.
  intro c. induction c as [c IH] using lt_wf_ind. intros d d' Hd Hd'.
  destruct d as [|d]; [lia|]. destruct d' as [|d']; [lia|].
  cbn [FOdecode_f_b].
  pose proof (cunpair_bound c) as Hcb.
  pose proof (cunpair_bound (snd (cunpair c))) as Hpb.
  destruct (fst (cunpair c)) as [|[|[|[|[|t5]]]]] eqn:Etag.
  - reflexivity.
  - reflexivity.
  - f_equal; apply IH; lia.
  - f_equal; apply IH; lia.
  - f_equal; apply IH; lia.
  - reflexivity.
Qed.

Lemma FOdecode_f_eq : forall a b,
  FOdecode_f (cpair 0 (cpair a b))
  = FOEq (FOdecode_tm a) (FOdecode_tm b).
Proof.
  intros a b. unfold FOdecode_f. cbn [FOdecode_f_b].
  rewrite cunpair_cpair. cbn [fst snd].
  rewrite cunpair_cpair. reflexivity.
Qed.

Lemma FOdecode_f_false : forall z, FOdecode_f (cpair 1 z) = FOFalseF.
Proof.
  intro z. unfold FOdecode_f. cbn [FOdecode_f_b].
  rewrite cunpair_cpair. reflexivity.
Qed.

Lemma FOdecode_f_b_impl_step : forall d a b,
  FOdecode_f_b (S d) (cpair 2 (cpair a b))
  = FOImplF (FOdecode_f_b d a) (FOdecode_f_b d b).
Proof.
  intros d a b. cbn [FOdecode_f_b].
  rewrite cunpair_cpair. cbn [fst snd].
  rewrite cunpair_cpair. cbn [fst snd].
  reflexivity.
Qed.

Lemma FOdecode_f_impl : forall a b,
  FOdecode_f (cpair 2 (cpair a b))
  = FOImplF (FOdecode_f a) (FOdecode_f b).
Proof.
  intros a b. unfold FOdecode_f.
  rewrite FOdecode_f_b_impl_step.
  pose proof (cpair_bound 2 (cpair a b)).
  pose proof (cpair_bound a b).
  f_equal; apply FOdecode_f_b_stable; lia.
Qed.

Lemma FOdecode_f_b_forall_step : forall d y b,
  FOdecode_f_b (S d) (cpair 3 (cpair y b))
  = FOForall y (FOdecode_f_b d b).
Proof.
  intros d y b. cbn [FOdecode_f_b].
  rewrite cunpair_cpair. cbn [fst snd].
  rewrite cunpair_cpair. cbn [fst snd].
  reflexivity.
Qed.

Lemma FOdecode_f_forall : forall y b,
  FOdecode_f (cpair 3 (cpair y b)) = FOForall y (FOdecode_f b).
Proof.
  intros y b. unfold FOdecode_f.
  rewrite FOdecode_f_b_forall_step.
  pose proof (cpair_bound 3 (cpair y b)).
  pose proof (cpair_bound y b).
  f_equal. apply FOdecode_f_b_stable; lia.
Qed.

Lemma FOdecode_f_b_exists_step : forall d y b,
  FOdecode_f_b (S d) (cpair 4 (cpair y b))
  = FOExists y (FOdecode_f_b d b).
Proof.
  intros d y b. cbn [FOdecode_f_b].
  rewrite cunpair_cpair. cbn [fst snd].
  rewrite cunpair_cpair. cbn [fst snd].
  reflexivity.
Qed.

Lemma FOdecode_f_exists : forall y b,
  FOdecode_f (cpair 4 (cpair y b)) = FOExists y (FOdecode_f b).
Proof.
  intros y b. unfold FOdecode_f.
  rewrite FOdecode_f_b_exists_step.
  pose proof (cpair_bound 4 (cpair y b)).
  pose proof (cpair_bound y b).
  f_equal. apply FOdecode_f_b_stable; lia.
Qed.

Lemma cpair_inj : forall a b c d,
  cpair a b = cpair c d -> a = c /\ b = d.
Proof.
  intros a b c d H.
  pose proof (cunpair_cpair a b) as Ha.
  pose proof (cunpair_cpair c d) as Hc.
  rewrite H in Ha. rewrite Hc in Ha.
  injection Ha. intros. split; congruence.
Qed.

(** The per-tag specification a sound table entry meets: at genuine
    codes, the result is the represented function's value. *)

Definition mspec (tg a1 a2 a3 r : nat) : Prop :=
  match tg with
  | 0 => forall t, a2 = FOcode_tm t ->
         r = (if FOin_tm a1 t then 1 else 0)
  | 1 => forall A, a2 = FOcode_f A ->
         r = (if FOfree_in a1 A then 1 else 0)
  | 2 => forall s t, a2 = FOcode_tm s -> a3 = FOcode_tm t ->
         r = FOcode_tm (FOsubst_t a1 s t)
  | 3 => forall s A, a2 = FOcode_tm s -> a3 = FOcode_f A ->
         r = FOcode_f (FOsubst_f a1 s A)
  | 4 => forall s A, a2 = FOcode_tm s -> a3 = FOcode_f A ->
         r = (if FOsubst_ok a1 s A then 1 else 0)
  | 5 => r = FOcode_tm (FOnumeral a1)
  | _ => True
  end.

Definition tblL (vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen : nat)
    : nat -> nat -> nat -> nat -> nat -> Prop :=
  fun tg a1 a2 a3 r => exists j, j < vlen /\
    beta vct vdt j = tg /\ beta vc1 vd1 j = a1 /\
    beta vc2 vd2 j = a2 /\ beta vc3 vd3 j = a3 /\
    beta vcr vdr j = r.

Definition mw (tg : nat) : nat :=
  match tg with
  | 1 => 1
  | 3 => 1
  | 4 => 1
  | _ => 0
  end.

Ltac mlia :=
  repeat match goal with
         | H : context[mw _] |- _ => cbn [mw] in H
         end;
  cbn [mw]; lia.

Theorem tbl_sound : forall vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr
    vlen,
  (forall j, j < vlen ->
     dispatch_sem (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
       vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr j) ->
  forall tg a1 a2 a3 r,
    tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen tg a1 a2 a3 r ->
    mspec tg a1 a2 a3 r.
Proof.
  intros vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen Hvalid.
  assert (MAIN : forall m tg a1 a2 a3 r,
      a1 + a2 + a3 + mw tg < m ->
      tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen tg a1 a2 a3 r ->
      mspec tg a1 a2 a3 r).
  { induction m as [|m IHm].
    { intros; lia. }
    intros tg a1 a2 a3 r Hm Hmem.
    destruct Hmem as [j [Hj Hf]].
    pose proof (Hvalid j Hj) as Hd.
    unfold dispatch_sem in Hd.
    destruct Hd as [tg' [Htgb [a1' [Ha1b [a2' [Ha2b [a3' [Ha3b [rr'
      [Hrrb [Hbt [Hb1 [Hb2 [Hb3 [Hbr Hsw]]]]]]]]]]]]]]].
    destruct Hf as [Hft [Hf1 [Hf2 [Hf3 Hfr]]]].
    assert (Etg : tg' = tg) by congruence.
    assert (Ea1 : a1' = a1) by congruence.
    assert (Ea2 : a2' = a2) by congruence.
    assert (Ea3 : a3' = a3) by congruence.
    assert (Err : rr' = r) by congruence.
    clear Hbt Hb1 Hb2 Hb3 Hbr Hft Hf1 Hf2 Hf3 Hfr Htgb Ha1b Ha2b Ha3b
      Hrrb Hj.
    subst tg' a1' a2' a3' rr'.
    destruct Hsw as [[-> Hst]|[[-> Hst]|[[-> Hst]|[[-> Hst]|[[-> Hst]
      |[-> Hst]]]]]].
    - (* occurrence *)
      cbn [mspec]. intros t Ht2.
      unfold step0_sem in Hst.
      destruct Hst as [C|[C|[C|[C|C]]]].
      + destruct C as [y [Hyb [Hcp Hca]]].
        rewrite Ht2 in Hcp.
        destruct t as [v0| |t'|t1 t2|t1 t2]; cbn [FOcode_tm] in Hcp;
          apply cpair_inj in Hcp; destruct Hcp as [Hcp1 Hcp2];
          try discriminate Hcp1.
        subst v0.
        cbn [FOin_tm].
        destruct Hca as [[-> ->]|[Hne ->]].
        * rewrite Nat.eqb_refl. reflexivity.
        * rewrite (proj2 (Nat.eqb_neq y a1) Hne). reflexivity.
      + destruct C as [Hcp ->].
        rewrite Ht2 in Hcp.
        destruct t as [v0| |t'|t1 t2|t1 t2]; cbn [FOcode_tm] in Hcp;
          apply cpair_inj in Hcp; destruct Hcp as [Hcp1 _];
          try discriminate Hcp1.
        reflexivity.
      + destruct C as [tc' [Htcb [Hcp HL]]].
        rewrite Ht2 in Hcp.
        destruct t as [v0| |t'|t1 t2|t1 t2]; cbn [FOcode_tm] in Hcp;
          apply cpair_inj in Hcp; destruct Hcp as [Hcp1 Hcp2];
          try discriminate Hcp1.
        assert (Hbnd : 2 + tc' <= a2).
        { rewrite Ht2. cbn [FOcode_tm]. rewrite Hcp2.
          apply cpair_bound. }
        pose proof (IHm 0 a1 tc' 0 r ltac:(mlia) HL) as IH1.
        cbn [mspec] in IH1.
        specialize (IH1 t' Hcp2).
        cbn [FOin_tm]. exact IH1.
      + destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp Hca]]]]]]]].
        rewrite Ht2 in Hcp.
        destruct t as [v0| |t'|t1 t2|t1 t2]; cbn [FOcode_tm] in Hcp;
          apply cpair_inj in Hcp; destruct Hcp as [Hcp1 Hcp2];
          try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hta Htb].
        assert (Hba : ta + tb < a2).
        { rewrite Ht2. cbn [FOcode_tm]. rewrite Hta, Htb.
          pose proof (cpair_bound 3
            (cpair (FOcode_tm t1) (FOcode_tm t2))).
          pose proof (cpair_bound (FOcode_tm t1) (FOcode_tm t2)).
          lia. }
        cbn [FOin_tm].
        destruct Hca as [[HL ->]|[HL0 HLr]].
        * pose proof (IHm 0 a1 ta 0 1 ltac:(mlia) HL) as IH1.
          cbn [mspec] in IH1.
          specialize (IH1 t1 Hta).
          destruct (FOin_tm a1 t1) eqn:E1; [|discriminate IH1].
          reflexivity.
        * pose proof (IHm 0 a1 ta 0 0 ltac:(mlia) HL0) as IH0.
          pose proof (IHm 0 a1 tb 0 r ltac:(mlia) HLr) as IHr.
          cbn [mspec] in IH0, IHr.
          specialize (IH0 t1 Hta). specialize (IHr t2 Htb).
          destruct (FOin_tm a1 t1) eqn:E1; [discriminate IH0|].
          exact IHr.
      + destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp Hca]]]]]]]].
        rewrite Ht2 in Hcp.
        destruct t as [v0| |t'|t1 t2|t1 t2]; cbn [FOcode_tm] in Hcp;
          apply cpair_inj in Hcp; destruct Hcp as [Hcp1 Hcp2];
          try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hta Htb].
        assert (Hba : ta + tb < a2).
        { rewrite Ht2. cbn [FOcode_tm]. rewrite Hta, Htb.
          pose proof (cpair_bound 4
            (cpair (FOcode_tm t1) (FOcode_tm t2))).
          pose proof (cpair_bound (FOcode_tm t1) (FOcode_tm t2)).
          lia. }
        cbn [FOin_tm].
        destruct Hca as [[HL ->]|[HL0 HLr]].
        * pose proof (IHm 0 a1 ta 0 1 ltac:(mlia) HL) as IH1.
          cbn [mspec] in IH1.
          specialize (IH1 t1 Hta).
          destruct (FOin_tm a1 t1) eqn:E1; [|discriminate IH1].
          reflexivity.
        * pose proof (IHm 0 a1 ta 0 0 ltac:(mlia) HL0) as IH0.
          pose proof (IHm 0 a1 tb 0 r ltac:(mlia) HLr) as IHr.
          cbn [mspec] in IH0, IHr.
          specialize (IH0 t1 Hta). specialize (IHr t2 Htb).
          destruct (FOin_tm a1 t1) eqn:E1; [discriminate IH0|].
          exact IHr.
    - (* free occurrence *)
      cbn [mspec]. intros A HA2.
      unfold step1_sem in Hst.
      destruct Hst as [C|[C|[C|[C|C]]]].
      + destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp Hca]]]]]]]].
        rewrite HA2 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hta Htb].
        assert (Hba : ta + tb <= a2).
        { rewrite HA2. cbn [FOcode_f]. rewrite Hta, Htb.
          pose proof (cpair_bound 0
            (cpair (FOcode_tm t1) (FOcode_tm t2))).
          pose proof (cpair_bound (FOcode_tm t1) (FOcode_tm t2)).
          lia. }
        cbn [FOfree_in].
        destruct Hca as [[HL ->]|[HL0 HLr]].
        * pose proof (IHm 0 a1 ta 0 1 ltac:(mlia) HL) as IH1.
          cbn [mspec] in IH1.
          specialize (IH1 t1 Hta).
          destruct (FOin_tm a1 t1) eqn:E1; [|discriminate IH1].
          reflexivity.
        * pose proof (IHm 0 a1 ta 0 0 ltac:(mlia) HL0) as IH0.
          pose proof (IHm 0 a1 tb 0 r ltac:(mlia) HLr) as IHr.
          cbn [mspec] in IH0, IHr.
          specialize (IH0 t1 Hta). specialize (IHr t2 Htb).
          destruct (FOin_tm a1 t1) eqn:E1; [discriminate IH0|].
          exact IHr.
      + destruct C as [Hcp ->].
        rewrite HA2 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 _]; try discriminate Hcp1.
        reflexivity.
      + destruct C as [p [Hpb [Hcp [pa [Hpab [pb [Hpbb [Hp Hca]]]]]]]].
        rewrite HA2 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hpa Hpb'].
        assert (Hba : pa + pb < a2).
        { rewrite HA2. cbn [FOcode_f]. rewrite Hpa, Hpb'.
          pose proof (cpair_bound 2
            (cpair (FOcode_f A1) (FOcode_f A2))).
          pose proof (cpair_bound (FOcode_f A1) (FOcode_f A2)).
          lia. }
        cbn [FOfree_in].
        destruct Hca as [[HL ->]|[HL0 HLr]].
        * pose proof (IHm 1 a1 pa 0 1 ltac:(mlia) HL) as IH1.
          cbn [mspec] in IH1.
          specialize (IH1 A1 Hpa).
          destruct (FOfree_in a1 A1) eqn:E1; [|discriminate IH1].
          reflexivity.
        * pose proof (IHm 1 a1 pa 0 0 ltac:(mlia) HL0) as IH0.
          pose proof (IHm 1 a1 pb 0 r ltac:(mlia) HLr) as IHr.
          cbn [mspec] in IH0, IHr.
          specialize (IH0 A1 Hpa). specialize (IHr A2 Hpb').
          destruct (FOfree_in a1 A1) eqn:E1; [discriminate IH0|].
          exact IHr.
      + destruct C as [p [Hpb [Hcp [y [Hyb [pb [Hpbb [Hp Hca]]]]]]]].
        rewrite HA2 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hy Hpb'].
        subst y0.
        assert (Hba : pb < a2).
        { rewrite HA2. cbn [FOcode_f]. rewrite Hpb'.
          pose proof (cpair_bound 3 (cpair y (FOcode_f A'))).
          pose proof (cpair_bound y (FOcode_f A')).
          lia. }
        cbn [FOfree_in].
        destruct Hca as [[-> ->]|[Hne HL]].
        * rewrite Nat.eqb_refl. reflexivity.
        * rewrite (proj2 (Nat.eqb_neq y a1) Hne).
          pose proof (IHm 1 a1 pb 0 r ltac:(mlia) HL) as IHr.
          cbn [mspec] in IHr.
          exact (IHr A' Hpb').
      + destruct C as [p [Hpb [Hcp [y [Hyb [pb [Hpbb [Hp Hca]]]]]]]].
        rewrite HA2 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hy Hpb'].
        subst y0.
        assert (Hba : pb < a2).
        { rewrite HA2. cbn [FOcode_f]. rewrite Hpb'.
          pose proof (cpair_bound 4 (cpair y (FOcode_f A'))).
          pose proof (cpair_bound y (FOcode_f A')).
          lia. }
        cbn [FOfree_in].
        destruct Hca as [[-> ->]|[Hne HL]].
        * rewrite Nat.eqb_refl. reflexivity.
        * rewrite (proj2 (Nat.eqb_neq y a1) Hne).
          pose proof (IHm 1 a1 pb 0 r ltac:(mlia) HL) as IHr.
          cbn [mspec] in IHr.
          exact (IHr A' Hpb').
    - (* term substitution *)
      cbn [mspec]. intros s t Hs2 Ht3.
      unfold step2_sem in Hst.
      destruct Hst as [C|[C|[C|[C|C]]]].
      + destruct C as [y [Hyb [Hcp Hca]]].
        rewrite Ht3 in Hcp.
        destruct t as [v0| |t'|t1 t2|t1 t2]; cbn [FOcode_tm] in Hcp;
          apply cpair_inj in Hcp; destruct Hcp as [Hcp1 Hcp2];
          try discriminate Hcp1.
        subst v0.
        cbn [FOsubst_t].
        destruct Hca as [[-> ->]|[Hne ->]].
        * rewrite Nat.eqb_refl. exact Hs2.
        * rewrite (proj2 (Nat.eqb_neq y a1) Hne).
          cbn [FOcode_tm]. exact Ht3.
      + destruct C as [Hcp ->].
        rewrite Ht3 in Hcp.
        destruct t as [v0| |t'|t1 t2|t1 t2]; cbn [FOcode_tm] in Hcp;
          apply cpair_inj in Hcp; destruct Hcp as [Hcp1 _];
          try discriminate Hcp1.
        cbn [FOsubst_t FOcode_tm]. exact Ht3.
      + destruct C as [tc' [Htcb [Hcp [r' [Hr'b [HL Hr]]]]]].
        rewrite Ht3 in Hcp.
        destruct t as [v0| |t'|t1 t2|t1 t2]; cbn [FOcode_tm] in Hcp;
          apply cpair_inj in Hcp; destruct Hcp as [Hcp1 Hcp2];
          try discriminate Hcp1.
        assert (Hbnd : 2 + tc' <= a3).
        { rewrite Ht3. cbn [FOcode_tm]. rewrite Hcp2.
          apply cpair_bound. }
        pose proof (IHm 2 a1 a2 tc' r' ltac:(mlia) HL) as IH1.
        cbn [mspec] in IH1.
        specialize (IH1 s t' Hs2 Hcp2).
        cbn [FOsubst_t FOcode_tm].
        rewrite <- IH1. symmetry. exact Hr.
      + destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
          [rb [Hrbb [HLa [HLb [q [Hqb [Hq Hr]]]]]]]]]]]]]]]]].
        rewrite Ht3 in Hcp.
        destruct t as [v0| |t'|t1 t2|t1 t2]; cbn [FOcode_tm] in Hcp;
          apply cpair_inj in Hcp; destruct Hcp as [Hcp1 Hcp2];
          try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hta Htb].
        assert (Hba : ta + tb < a3).
        { rewrite Ht3. cbn [FOcode_tm]. rewrite Hta, Htb.
          pose proof (cpair_bound 3
            (cpair (FOcode_tm t1) (FOcode_tm t2))).
          pose proof (cpair_bound (FOcode_tm t1) (FOcode_tm t2)).
          lia. }
        pose proof (IHm 2 a1 a2 ta ra ltac:(mlia) HLa) as IHa.
        pose proof (IHm 2 a1 a2 tb rb ltac:(mlia) HLb) as IHb.
        cbn [mspec] in IHa, IHb.
        specialize (IHa s t1 Hs2 Hta). specialize (IHb s t2 Hs2 Htb).
        cbn [FOsubst_t FOcode_tm].
        rewrite <- IHa, <- IHb, Hq. symmetry. exact Hr.
      + destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
          [rb [Hrbb [HLa [HLb [q [Hqb [Hq Hr]]]]]]]]]]]]]]]]].
        rewrite Ht3 in Hcp.
        destruct t as [v0| |t'|t1 t2|t1 t2]; cbn [FOcode_tm] in Hcp;
          apply cpair_inj in Hcp; destruct Hcp as [Hcp1 Hcp2];
          try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hta Htb].
        assert (Hba : ta + tb < a3).
        { rewrite Ht3. cbn [FOcode_tm]. rewrite Hta, Htb.
          pose proof (cpair_bound 4
            (cpair (FOcode_tm t1) (FOcode_tm t2))).
          pose proof (cpair_bound (FOcode_tm t1) (FOcode_tm t2)).
          lia. }
        pose proof (IHm 2 a1 a2 ta ra ltac:(mlia) HLa) as IHa.
        pose proof (IHm 2 a1 a2 tb rb ltac:(mlia) HLb) as IHb.
        cbn [mspec] in IHa, IHb.
        specialize (IHa s t1 Hs2 Hta). specialize (IHb s t2 Hs2 Htb).
        cbn [FOsubst_t FOcode_tm].
        rewrite <- IHa, <- IHb, Hq. symmetry. exact Hr.
    - (* formula substitution *)
      cbn [mspec]. intros s A Hs2 HA3.
      unfold step3_sem in Hst.
      destruct Hst as [C|[C|[C|[C|C]]]].
      + destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
          [rb [Hrbb [HLa [HLb [q [Hqb [Hq Hr]]]]]]]]]]]]]]]]].
        rewrite HA3 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hta Htb].
        assert (Hba : ta + tb <= a3).
        { rewrite HA3. cbn [FOcode_f]. rewrite Hta, Htb.
          pose proof (cpair_bound 0
            (cpair (FOcode_tm t1) (FOcode_tm t2))).
          pose proof (cpair_bound (FOcode_tm t1) (FOcode_tm t2)).
          lia. }
        pose proof (IHm 2 a1 a2 ta ra ltac:(mlia) HLa) as IHa.
        pose proof (IHm 2 a1 a2 tb rb ltac:(mlia) HLb) as IHb.
        cbn [mspec] in IHa, IHb.
        specialize (IHa s t1 Hs2 Hta). specialize (IHb s t2 Hs2 Htb).
        cbn [FOsubst_f FOcode_f].
        rewrite <- IHa, <- IHb, Hq. symmetry. exact Hr.
      + destruct C as [Hcp ->].
        rewrite HA3 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 _]; try discriminate Hcp1.
        cbn [FOsubst_f FOcode_f]. exact HA3.
      + destruct C as [p [Hpb [Hcp [pa [Hpab [pb [Hpbb [Hp [ra [Hrab
          [rb [Hrbb [HLa [HLb [q [Hqb [Hq Hr]]]]]]]]]]]]]]]]].
        rewrite HA3 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hpa Hpb'].
        assert (Hba : pa + pb < a3).
        { rewrite HA3. cbn [FOcode_f]. rewrite Hpa, Hpb'.
          pose proof (cpair_bound 2
            (cpair (FOcode_f A1) (FOcode_f A2))).
          pose proof (cpair_bound (FOcode_f A1) (FOcode_f A2)).
          lia. }
        pose proof (IHm 3 a1 a2 pa ra ltac:(mlia) HLa) as IHa.
        pose proof (IHm 3 a1 a2 pb rb ltac:(mlia) HLb) as IHb.
        cbn [mspec] in IHa, IHb.
        specialize (IHa s A1 Hs2 Hpa). specialize (IHb s A2 Hs2 Hpb').
        cbn [FOsubst_f FOcode_f].
        rewrite <- IHa, <- IHb, Hq. symmetry. exact Hr.
      + destruct C as [p [Hpb [Hcp [y [Hyb [pb [Hpbb [Hp Hca]]]]]]]].
        rewrite HA3 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hy Hpb'].
        subst y0.
        assert (Hba : pb < a3).
        { rewrite HA3. cbn [FOcode_f]. rewrite Hpb'.
          pose proof (cpair_bound 3 (cpair y (FOcode_f A'))).
          pose proof (cpair_bound y (FOcode_f A')).
          lia. }
        cbn [FOsubst_f].
        destruct Hca as [[-> ->]|[Hne [rb [Hrbb [HL [q [Hqb
          [Hq Hr]]]]]]]].
        * rewrite Nat.eqb_refl. exact HA3.
        * rewrite (proj2 (Nat.eqb_neq y a1) Hne).
          pose proof (IHm 3 a1 a2 pb rb ltac:(mlia) HL) as IHr.
          cbn [mspec] in IHr.
          specialize (IHr s A' Hs2 Hpb').
          cbn [FOcode_f].
          rewrite <- IHr, Hq. symmetry. exact Hr.
      + destruct C as [p [Hpb [Hcp [y [Hyb [pb [Hpbb [Hp Hca]]]]]]]].
        rewrite HA3 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hy Hpb'].
        subst y0.
        assert (Hba : pb < a3).
        { rewrite HA3. cbn [FOcode_f]. rewrite Hpb'.
          pose proof (cpair_bound 4 (cpair y (FOcode_f A'))).
          pose proof (cpair_bound y (FOcode_f A')).
          lia. }
        cbn [FOsubst_f].
        destruct Hca as [[-> ->]|[Hne [rb [Hrbb [HL [q [Hqb
          [Hq Hr]]]]]]]].
        * rewrite Nat.eqb_refl. exact HA3.
        * rewrite (proj2 (Nat.eqb_neq y a1) Hne).
          pose proof (IHm 3 a1 a2 pb rb ltac:(mlia) HL) as IHr.
          cbn [mspec] in IHr.
          specialize (IHr s A' Hs2 Hpb').
          cbn [FOcode_f].
          rewrite <- IHr, Hq. symmetry. exact Hr.
    - (* capture test *)
      cbn [mspec]. intros s A Hs2 HA3.
      unfold step4_sem in Hst.
      destruct Hst as [C|[C|[C|[C|C]]]].
      + destruct C as [p [Hpb [Hcp ->]]].
        rewrite HA3 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 _]; try discriminate Hcp1.
        reflexivity.
      + destruct C as [Hcp ->].
        rewrite HA3 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 _]; try discriminate Hcp1.
        reflexivity.
      + destruct C as [p [Hpb [Hcp [pa [Hpab [pb [Hpbb [Hp Hca]]]]]]]].
        rewrite HA3 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hpa Hpb'].
        assert (Hba : pa + pb < a3).
        { rewrite HA3. cbn [FOcode_f]. rewrite Hpa, Hpb'.
          pose proof (cpair_bound 2
            (cpair (FOcode_f A1) (FOcode_f A2))).
          pose proof (cpair_bound (FOcode_f A1) (FOcode_f A2)).
          lia. }
        cbn [FOsubst_ok].
        destruct Hca as [[HL ->]|[HL1 HLr]].
        * pose proof (IHm 4 a1 a2 pa 0 ltac:(mlia) HL) as IH0.
          cbn [mspec] in IH0.
          specialize (IH0 s A1 Hs2 Hpa).
          destruct (FOsubst_ok a1 s A1) eqn:E1; [discriminate IH0|].
          reflexivity.
        * pose proof (IHm 4 a1 a2 pa 1 ltac:(mlia) HL1) as IH1.
          pose proof (IHm 4 a1 a2 pb r ltac:(mlia) HLr) as IHr.
          cbn [mspec] in IH1, IHr.
          specialize (IH1 s A1 Hs2 Hpa).
          specialize (IHr s A2 Hs2 Hpb').
          destruct (FOsubst_ok a1 s A1) eqn:E1; [|discriminate IH1].
          exact IHr.
      + destruct C as [p [Hpb [Hcp [y [Hyb [pb [Hpbb [Hp Hca]]]]]]]].
        rewrite HA3 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hy Hpb'].
        subst y0.
        assert (Hba : y + pb + 3 <= a3).
        { rewrite HA3. cbn [FOcode_f]. rewrite Hpb'.
          pose proof (cpair_bound 3 (cpair y (FOcode_f A'))).
          pose proof (cpair_bound y (FOcode_f A')).
          lia. }
        cbn [FOsubst_ok].
        destruct Hca as [[-> ->]|[Hne Hca]].
        * rewrite Nat.eqb_refl. reflexivity.
        * rewrite (proj2 (Nat.eqb_neq y a1) Hne).
          destruct Hca as [[HLf ->]|[HLf Hca]].
          -- pose proof (IHm 1 a1 pb 0 0 ltac:(mlia) HLf) as IHf.
             cbn [mspec] in IHf.
             specialize (IHf A' Hpb').
             destruct (FOfree_in a1 A') eqn:Ef; [discriminate IHf|].
             reflexivity.
          -- pose proof (IHm 1 a1 pb 0 1 ltac:(mlia) HLf) as IHf.
             cbn [mspec] in IHf.
             specialize (IHf A' Hpb').
             destruct (FOfree_in a1 A') eqn:Ef; [|discriminate IHf].
             destruct Hca as [[HLg ->]|[HLg HLr]].
             ++ pose proof (IHm 0 y a2 0 1 ltac:(mlia) HLg) as IHg.
                cbn [mspec] in IHg.
                specialize (IHg s Hs2).
                destruct (FOin_tm y s) eqn:Eg; [|discriminate IHg].
                reflexivity.
             ++ pose proof (IHm 0 y a2 0 0 ltac:(mlia) HLg) as IHg.
                pose proof (IHm 4 a1 a2 pb r ltac:(mlia) HLr) as IHr.
                cbn [mspec] in IHg, IHr.
                specialize (IHg s Hs2).
                specialize (IHr s A' Hs2 Hpb').
                destruct (FOin_tm y s) eqn:Eg; [discriminate IHg|].
                exact IHr.
      + destruct C as [p [Hpb [Hcp [y [Hyb [pb [Hpbb [Hp Hca]]]]]]]].
        rewrite HA3 in Hcp.
        destruct A as [t1 t2| |A1 A2|y0 A'|y0 A']; cbn [FOcode_f]
          in Hcp; apply cpair_inj in Hcp;
          destruct Hcp as [Hcp1 Hcp2]; try discriminate Hcp1.
        rewrite Hcp2 in Hp.
        apply cpair_inj in Hp. destruct Hp as [Hy Hpb'].
        subst y0.
        assert (Hba : y + pb + 3 <= a3).
        { rewrite HA3. cbn [FOcode_f]. rewrite Hpb'.
          pose proof (cpair_bound 4 (cpair y (FOcode_f A'))).
          pose proof (cpair_bound y (FOcode_f A')).
          lia. }
        cbn [FOsubst_ok].
        destruct Hca as [[-> ->]|[Hne Hca]].
        * rewrite Nat.eqb_refl. reflexivity.
        * rewrite (proj2 (Nat.eqb_neq y a1) Hne).
          destruct Hca as [[HLf ->]|[HLf Hca]].
          -- pose proof (IHm 1 a1 pb 0 0 ltac:(mlia) HLf) as IHf.
             cbn [mspec] in IHf.
             specialize (IHf A' Hpb').
             destruct (FOfree_in a1 A') eqn:Ef; [discriminate IHf|].
             reflexivity.
          -- pose proof (IHm 1 a1 pb 0 1 ltac:(mlia) HLf) as IHf.
             cbn [mspec] in IHf.
             specialize (IHf A' Hpb').
             destruct (FOfree_in a1 A') eqn:Ef; [|discriminate IHf].
             destruct Hca as [[HLg ->]|[HLg HLr]].
             ++ pose proof (IHm 0 y a2 0 1 ltac:(mlia) HLg) as IHg.
                cbn [mspec] in IHg.
                specialize (IHg s Hs2).
                destruct (FOin_tm y s) eqn:Eg; [|discriminate IHg].
                reflexivity.
             ++ pose proof (IHm 0 y a2 0 0 ltac:(mlia) HLg) as IHg.
                pose proof (IHm 4 a1 a2 pb r ltac:(mlia) HLr) as IHr.
                cbn [mspec] in IHg, IHr.
                specialize (IHg s Hs2).
                specialize (IHr s A' Hs2 Hpb').
                destruct (FOin_tm y s) eqn:Eg; [discriminate IHg|].
                exact IHr.
    - (* numeral coding *)
      cbn [mspec].
      unfold step5_sem in Hst.
      destruct Hst as [[-> Hr]|[k' [Hk'b [-> [r' [Hr'b [HL Hr]]]]]]].
      + cbn [FOnumeral FOcode_tm]. symmetry. exact Hr.
      + pose proof (IHm 5 k' 0 0 r' ltac:(mlia) HL) as IH1.
        cbn [mspec] in IH1.
        cbn [FOnumeral FOcode_tm].
        rewrite <- IH1. symmetry. exact Hr.
  }
  intros tg a1 a2 a3 r Hmem.
  exact (MAIN (S (a1 + a2 + a3 + mw tg)) tg a1 a2 a3 r
           (Nat.lt_succ_diag_r _) Hmem).
Qed.

(** ** Genuineness from table rows.

    The step relations are partial: a substitution row exists only
    when the recursion completes through valid constructor tags.  A
    term-substitution row therefore forces its input to be a genuine
    term code.  A formula-substitution row forces its input to be a
    genuine formula code provided the substitution variable exceeds
    the input code, since every binder payload inside the code is
    below the code itself and the shadowing stop can never fire. *)

Lemma tbl_genuine_tm : forall vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr
    vlen,
  (forall j, j < vlen ->
     dispatch_sem (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
       vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr j) ->
  forall x sc tc r,
    tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen 2 x sc tc r ->
    exists t, tc = FOcode_tm t.
Proof.
  intros vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen Hvalid.
  assert (MAIN : forall m x sc tc r,
      tc < m ->
      tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen 2 x sc tc r ->
      exists t, tc = FOcode_tm t).
  { induction m as [|m IHm].
    { intros; lia. }
    intros x sc tc r Hm Hmem.
    destruct Hmem as [j [Hj Hf]].
    pose proof (Hvalid j Hj) as Hd.
    unfold dispatch_sem in Hd.
    destruct Hd as [tg' [Htgb [a1' [Ha1b [a2' [Ha2b [a3' [Ha3b [rr'
      [Hrrb [Hbt [Hb1 [Hb2 [Hb3 [Hbr Hsw]]]]]]]]]]]]]]].
    destruct Hf as [Hft [Hf1 [Hf2 [Hf3 Hfr]]]].
    assert (Etg : tg' = 2) by congruence.
    assert (Ea1 : a1' = x) by congruence.
    assert (Ea2 : a2' = sc) by congruence.
    assert (Ea3 : a3' = tc) by congruence.
    assert (Err : rr' = r) by congruence.
    clear Hbt Hb1 Hb2 Hb3 Hbr Hft Hf1 Hf2 Hf3 Hfr Htgb Ha1b Ha2b
      Ha3b Hrrb Hj.
    subst tg' a1' a2' a3' rr'.
    destruct Hsw as [[E _]|[[E _]|[[_ Hst]|[[E _]|[[E _]|[E _]]]]]];
      try discriminate E.
    unfold step2_sem in Hst.
    destruct Hst as [C|[C|[C|[C|C]]]].
    - destruct C as [y [Hyb [Hcp Hca]]].
      exists (FOVar y). cbn [FOcode_tm]. symmetry. exact Hcp.
    - destruct C as [Hcp Hr].
      exists FOZero. cbn [FOcode_tm]. symmetry. exact Hcp.
    - destruct C as [tc' [Htcb [Hcp [r' [Hr'b [Hsub Hcr]]]]]].
      pose proof (cpair_bound 2 tc') as Hgrow. rewrite Hcp in Hgrow.
      destruct (IHm x sc tc' r' ltac:(lia) Hsub) as [t' Ht'].
      exists (FOSucc t'). cbn [FOcode_tm].
      rewrite <- Ht', Hcp. reflexivity.
    - destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
        [rb [Hrbb [Hsa [Hsb [q [Hqb [Hq Hcr]]]]]]]]]]]]]]]]].
      pose proof (cpair_bound 3 p) as Hg1. rewrite Hcp in Hg1.
      pose proof (cpair_bound ta tb) as Hg2. rewrite Hp in Hg2.
      destruct (IHm x sc ta ra ltac:(lia) Hsa) as [t1 Ht1].
      destruct (IHm x sc tb rb ltac:(lia) Hsb) as [t2 Ht2].
      exists (FOPlus t1 t2). cbn [FOcode_tm].
      rewrite <- Ht1, <- Ht2, Hp, Hcp. reflexivity.
    - destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
        [rb [Hrbb [Hsa [Hsb [q [Hqb [Hq Hcr]]]]]]]]]]]]]]]]].
      pose proof (cpair_bound 4 p) as Hg1. rewrite Hcp in Hg1.
      pose proof (cpair_bound ta tb) as Hg2. rewrite Hp in Hg2.
      destruct (IHm x sc ta ra ltac:(lia) Hsa) as [t1 Ht1].
      destruct (IHm x sc tb rb ltac:(lia) Hsb) as [t2 Ht2].
      exists (FOMult t1 t2). cbn [FOcode_tm].
      rewrite <- Ht1, <- Ht2, Hp, Hcp. reflexivity. }
  intros x sc tc r Hmem.
  exact (MAIN (S tc) x sc tc r (Nat.lt_succ_diag_r tc) Hmem).
Qed.

Lemma tbl_genuine_f : forall vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr
    vlen,
  (forall j, j < vlen ->
     dispatch_sem (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
       vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr j) ->
  forall x sc pc r,
    tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen 3 x sc pc r ->
    pc < x ->
    exists A, pc = FOcode_f A.
Proof.
  intros vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen Hvalid.
  assert (MAIN : forall m x sc pc r,
      pc < m -> pc < x ->
      tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen 3 x sc pc r ->
      exists A, pc = FOcode_f A).
  { induction m as [|m IHm].
    { intros; lia. }
    intros x sc pc r Hm Hx Hmem.
    destruct Hmem as [j [Hj Hf]].
    pose proof (Hvalid j Hj) as Hd.
    unfold dispatch_sem in Hd.
    destruct Hd as [tg' [Htgb [a1' [Ha1b [a2' [Ha2b [a3' [Ha3b [rr'
      [Hrrb [Hbt [Hb1 [Hb2 [Hb3 [Hbr Hsw]]]]]]]]]]]]]]].
    destruct Hf as [Hft [Hf1 [Hf2 [Hf3 Hfr]]]].
    assert (Etg : tg' = 3) by congruence.
    assert (Ea1 : a1' = x) by congruence.
    assert (Ea2 : a2' = sc) by congruence.
    assert (Ea3 : a3' = pc) by congruence.
    assert (Err : rr' = r) by congruence.
    clear Hbt Hb1 Hb2 Hb3 Hbr Hft Hf1 Hf2 Hf3 Hfr Htgb Ha1b Ha2b
      Ha3b Hrrb Hj.
    subst tg' a1' a2' a3' rr'.
    destruct Hsw as [[E _]|[[E _]|[[E _]|[[_ Hst]|[[E _]|[E _]]]]]];
      try discriminate E.
    unfold step3_sem in Hst.
    destruct Hst as [C|[C|[C|[C|C]]]].
    - destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
        [rb [Hrbb [Hsa [Hsb [q [Hqb [Hq Hcr]]]]]]]]]]]]]]]]].
      destruct (tbl_genuine_tm vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr
                  vdr vlen Hvalid x sc ta ra Hsa) as [t1 Ht1].
      destruct (tbl_genuine_tm vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr
                  vdr vlen Hvalid x sc tb rb Hsb) as [t2 Ht2].
      exists (FOEq t1 t2). cbn [FOcode_f].
      rewrite <- Ht1, <- Ht2, Hp, Hcp. reflexivity.
    - destruct C as [Hcp Hr].
      exists FOFalseF. cbn [FOcode_f]. symmetry. exact Hcp.
    - destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
        [rb [Hrbb [Hsa [Hsb [q [Hqb [Hq Hcr]]]]]]]]]]]]]]]]].
      pose proof (cpair_bound 2 p) as Hg1. rewrite Hcp in Hg1.
      pose proof (cpair_bound ta tb) as Hg2. rewrite Hp in Hg2.
      destruct (IHm x sc ta ra ltac:(lia) ltac:(lia) Hsa) as [B1 HB1].
      destruct (IHm x sc tb rb ltac:(lia) ltac:(lia) Hsb) as [B2 HB2].
      exists (FOImplF B1 B2). cbn [FOcode_f].
      rewrite <- HB1, <- HB2, Hp, Hcp. reflexivity.
    - destruct C as [p [Hpb [Hcp [y [Hyb [pb [Hpbb [Hp Hcase]]]]]]]].
      pose proof (cpair_bound 3 p) as Hg1. rewrite Hcp in Hg1.
      pose proof (cpair_bound y pb) as Hg2. rewrite Hp in Hg2.
      destruct Hcase as [[Exy Hr]|[Hneq [rb [Hrbb [Hsub Hq]]]]].
      { exfalso. lia. }
      destruct (IHm x sc pb rb ltac:(lia) ltac:(lia) Hsub) as [B HB].
      exists (FOForall y B). cbn [FOcode_f].
      rewrite <- HB, Hp, Hcp. reflexivity.
    - destruct C as [p [Hpb [Hcp [y [Hyb [pb [Hpbb [Hp Hcase]]]]]]]].
      pose proof (cpair_bound 4 p) as Hg1. rewrite Hcp in Hg1.
      pose proof (cpair_bound y pb) as Hg2. rewrite Hp in Hg2.
      destruct Hcase as [[Exy Hr]|[Hneq [rb [Hrbb [Hsub Hq]]]]].
      { exfalso. lia. }
      destruct (IHm x sc pb rb ltac:(lia) ltac:(lia) Hsub) as [B HB].
      exists (FOExists y B). cbn [FOcode_f].
      rewrite <- HB, Hp, Hcp. reflexivity. }
  intros x sc pc r Hmem Hx.
  exact (MAIN (S pc) x sc pc r (Nat.lt_succ_diag_r pc) Hx Hmem).
Qed.

(** ** Substitution-row inversion and the substitution witness.

    A validated table makes every tag-2 and tag-3 row satisfy its
    step relation.  At genuine input and output codes, a substitution
    row either touches no occurrence — the variable is not free and
    the output equals the input — or it places the substituted code
    into the output, forcing it to be a genuine term code. *)

Lemma tblL_step2 : forall vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr
    vlen,
  (forall j, j < vlen ->
     dispatch_sem (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
       vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr j) ->
  forall x sc tc r,
    tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen 2 x sc tc r ->
    step2_sem (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
      x sc tc r.
Proof.
  intros vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen Hvalid
    x sc tc r Hmem.
  destruct Hmem as [j [Hj Hf]].
  pose proof (Hvalid j Hj) as Hd.
  unfold dispatch_sem in Hd.
  destruct Hd as [tg' [Htgb [a1' [Ha1b [a2' [Ha2b [a3' [Ha3b [rr'
    [Hrrb [Hbt [Hb1 [Hb2 [Hb3 [Hbr Hsw]]]]]]]]]]]]]]].
  destruct Hf as [Hft [Hf1 [Hf2 [Hf3 Hfr]]]].
  assert (Etg : tg' = 2) by congruence.
  assert (Ea1 : a1' = x) by congruence.
  assert (Ea2 : a2' = sc) by congruence.
  assert (Ea3 : a3' = tc) by congruence.
  assert (Err : rr' = r) by congruence.
  clear Hbt Hb1 Hb2 Hb3 Hbr Hft Hf1 Hf2 Hf3 Hfr Htgb Ha1b Ha2b
    Ha3b Hrrb Hj.
  subst tg' a1' a2' a3' rr'.
  destruct Hsw as [[E _]|[[E _]|[[_ Hst]|[[E _]|[[E _]|[E _]]]]]];
    try discriminate E.
  exact Hst.
Qed.

Lemma tblL_step3 : forall vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr
    vlen,
  (forall j, j < vlen ->
     dispatch_sem (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
       vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr j) ->
  forall x sc pc r,
    tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen 3 x sc pc r ->
    step3_sem (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
      x sc pc r.
Proof.
  intros vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen Hvalid
    x sc pc r Hmem.
  destruct Hmem as [j [Hj Hf]].
  pose proof (Hvalid j Hj) as Hd.
  unfold dispatch_sem in Hd.
  destruct Hd as [tg' [Htgb [a1' [Ha1b [a2' [Ha2b [a3' [Ha3b [rr'
    [Hrrb [Hbt [Hb1 [Hb2 [Hb3 [Hbr Hsw]]]]]]]]]]]]]]].
  destruct Hf as [Hft [Hf1 [Hf2 [Hf3 Hfr]]]].
  assert (Etg : tg' = 3) by congruence.
  assert (Ea1 : a1' = x) by congruence.
  assert (Ea2 : a2' = sc) by congruence.
  assert (Ea3 : a3' = pc) by congruence.
  assert (Err : rr' = r) by congruence.
  clear Hbt Hb1 Hb2 Hb3 Hbr Hft Hf1 Hf2 Hf3 Hfr Htgb Ha1b Ha2b
    Ha3b Hrrb Hj.
  subst tg' a1' a2' a3' rr'.
  destruct Hsw as [[E _]|[[E _]|[[E _]|[[_ Hst]|[[E _]|[E _]]]]]];
    try discriminate E.
  exact Hst.
Qed.

Lemma tbl_subst_tm_witness : forall vct vdt vc1 vd1 vc2 vd2 vc3 vd3
    vcr vdr vlen,
  (forall j, j < vlen ->
     dispatch_sem (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
       vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr j) ->
  forall t' r' x sc,
    tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen 2 x sc
      (FOcode_tm t') (FOcode_tm r') ->
    (FOin_tm x t' = false /\ FOcode_tm r' = FOcode_tm t')
    \/ (exists s, sc = FOcode_tm s).
Proof.
  intros vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen Hvalid.
  induction t' as [y| |t1 IH|t1 IH1 t2 IH2|t1 IH1 t2 IH2];
    intros r' x sc Hrow;
    apply (tblL_step2 _ _ _ _ _ _ _ _ _ _ _ Hvalid) in Hrow;
    unfold step2_sem in Hrow;
    cbn [FOcode_tm] in Hrow;
    destruct Hrow as [C|[C|[C|[C|C]]]].
  - destruct C as [y0 [Hyb [Hcp Hca]]].
    apply cpair_inj in Hcp. destruct Hcp as [_ Hy0]. subst y0.
    destruct Hca as [[Exy Hr]|[Hne Hr]].
    + right. exists r'. symmetry. exact Hr.
    + left. split.
      * cbn [FOin_tm]. exact (proj2 (Nat.eqb_neq y x) Hne).
      * cbn [FOcode_tm]. exact Hr.
  - destruct C as [Hcp _].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [tc' [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [y0 [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [_ Hr].
    left. split; [reflexivity|]. exact Hr.
  - destruct C as [tc' [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [y0 [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [Hcp _].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [tc' [Htcb [Hcp [rsub [Hrb [Hsubrow Hcr]]]]]].
    apply cpair_inj in Hcp. destruct Hcp as [_ Htc']. subst tc'.
    destruct r' as [ry| |r1|r1 r2|r1 r2]; cbn [FOcode_tm] in Hcr;
      apply cpair_inj in Hcr; destruct Hcr as [Ecr Hrs];
      try discriminate Ecr.
    subst rsub.
    destruct (IH r1 x sc Hsubrow) as [[Hin Heq]|Hgen].
    + left. split.
      * cbn [FOin_tm]. exact Hin.
      * cbn [FOcode_tm]. rewrite Heq. reflexivity.
    + right. exact Hgen.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [y0 [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [Hcp _].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [tc' [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
      [rb [Hrbb [Hsa [Hsb [q [Hqb [Hq Hcr]]]]]]]]]]]]]]]]].
    apply cpair_inj in Hcp. destruct Hcp as [_ Hpe]. subst p.
    apply cpair_inj in Hp. destruct Hp as [Hta Htb2]. subst ta tb.
    destruct r' as [ry| |r1|r1 r2|r1 r2]; cbn [FOcode_tm] in Hcr;
      apply cpair_inj in Hcr; destruct Hcr as [Ecr Hq2];
      try discriminate Ecr.
    rewrite Hq2 in Hq.
    apply cpair_inj in Hq. destruct Hq as [Hra Hrb2]. subst ra rb.
    destruct (IH1 r1 x sc Hsa) as [[Hin1 Heq1]|Hgen];
      [|right; exact Hgen].
    destruct (IH2 r2 x sc Hsb) as [[Hin2 Heq2]|Hgen];
      [|right; exact Hgen].
    left. split.
    + cbn [FOin_tm]. rewrite Hin1, Hin2. reflexivity.
    + cbn [FOcode_tm]. rewrite Heq1, Heq2. reflexivity.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [y0 [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [Hcp _].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [tc' [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
      [rb [Hrbb [Hsa [Hsb [q [Hqb [Hq Hcr]]]]]]]]]]]]]]]]].
    apply cpair_inj in Hcp. destruct Hcp as [_ Hpe]. subst p.
    apply cpair_inj in Hp. destruct Hp as [Hta Htb2]. subst ta tb.
    destruct r' as [ry| |r1|r1 r2|r1 r2]; cbn [FOcode_tm] in Hcr;
      apply cpair_inj in Hcr; destruct Hcr as [Ecr Hq2];
      try discriminate Ecr.
    rewrite Hq2 in Hq.
    apply cpair_inj in Hq. destruct Hq as [Hra Hrb2]. subst ra rb.
    destruct (IH1 r1 x sc Hsa) as [[Hin1 Heq1]|Hgen];
      [|right; exact Hgen].
    destruct (IH2 r2 x sc Hsb) as [[Hin2 Heq2]|Hgen];
      [|right; exact Hgen].
    left. split.
    + cbn [FOin_tm]. rewrite Hin1, Hin2. reflexivity.
    + cbn [FOcode_tm]. rewrite Heq1, Heq2. reflexivity.
Qed.

Lemma tbl_subst_f_witness : forall vct vdt vc1 vd1 vc2 vd2 vc3 vd3
    vcr vdr vlen,
  (forall j, j < vlen ->
     dispatch_sem (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
       vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr j) ->
  forall P' Q' x sc,
    tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen 3 x sc
      (FOcode_f P') (FOcode_f Q') ->
    (FOfree_in x P' = false /\ FOcode_f Q' = FOcode_f P')
    \/ (exists s, sc = FOcode_tm s).
Proof.
  intros vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen Hvalid.
  induction P' as [a b| |B IHB Cf IHC|y B IHB|y B IHB];
    intros Q' x sc Hrow;
    apply (tblL_step3 _ _ _ _ _ _ _ _ _ _ _ Hvalid) in Hrow;
    unfold step3_sem in Hrow;
    cbn [FOcode_f] in Hrow;
    destruct Hrow as [C|[C|[C|[C|C]]]].
  - destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
      [rb [Hrbb [Hsa [Hsb [q [Hqb [Hq Hcr]]]]]]]]]]]]]]]]].
    apply cpair_inj in Hcp. destruct Hcp as [_ Hpe]. subst p.
    apply cpair_inj in Hp. destruct Hp as [Hta Htb2]. subst ta tb.
    destruct Q' as [a2 b2| |Q1 Q2|y2 B2|y2 B2]; cbn [FOcode_f] in Hcr;
      apply cpair_inj in Hcr; destruct Hcr as [Ecr Hq2];
      try discriminate Ecr.
    rewrite Hq2 in Hq.
    apply cpair_inj in Hq. destruct Hq as [Hra Hrb2]. subst ra rb.
    destruct (tbl_subst_tm_witness _ _ _ _ _ _ _ _ _ _ _ Hvalid
                a a2 x sc Hsa) as [[Hin1 Heq1]|Hgen];
      [|right; exact Hgen].
    destruct (tbl_subst_tm_witness _ _ _ _ _ _ _ _ _ _ _ Hvalid
                b b2 x sc Hsb) as [[Hin2 Heq2]|Hgen];
      [|right; exact Hgen].
    left. split.
    + cbn [FOfree_in]. rewrite Hin1, Hin2. reflexivity.
    + cbn [FOcode_f]. rewrite Heq1, Heq2. reflexivity.
  - destruct C as [Hcp _].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [_ Hr].
    left. split; [reflexivity|]. exact Hr.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [Hcp _].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [Hpb [Hcp [ta [Htab [tb [Htbb [Hp [ra [Hrab
      [rb [Hrbb [Hsa [Hsb [q [Hqb [Hq Hcr]]]]]]]]]]]]]]]]].
    apply cpair_inj in Hcp. destruct Hcp as [_ Hpe]. subst p.
    apply cpair_inj in Hp. destruct Hp as [Hta Htb2]. subst ta tb.
    destruct Q' as [a2 b2| |Q1 Q2|y2 B2|y2 B2]; cbn [FOcode_f] in Hcr;
      apply cpair_inj in Hcr; destruct Hcr as [Ecr Hq2];
      try discriminate Ecr.
    rewrite Hq2 in Hq.
    apply cpair_inj in Hq. destruct Hq as [Hra Hrb2]. subst ra rb.
    destruct (IHB Q1 x sc Hsa) as [[Hin1 Heq1]|Hgen];
      [|right; exact Hgen].
    destruct (IHC Q2 x sc Hsb) as [[Hin2 Heq2]|Hgen];
      [|right; exact Hgen].
    left. split.
    + cbn [FOfree_in]. rewrite Hin1, Hin2. reflexivity.
    + cbn [FOcode_f]. rewrite Heq1, Heq2. reflexivity.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [Hcp _].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [Hpb [Hcp [y0 [Hyb [pb [Hpbb [Hp Hcase]]]]]]]].
    apply cpair_inj in Hcp. destruct Hcp as [_ Hpe]. subst p.
    apply cpair_inj in Hp. destruct Hp as [Hy0 Hpb2]. subst y0 pb.
    destruct Hcase as [[Exy Hr]|[Hne [rb [Hrbb [Hsub [q [Hqb
      [Hq Hcr]]]]]]]].
    + left. split.
      * cbn [FOfree_in]. rewrite Exy, Nat.eqb_refl. reflexivity.
      * exact Hr.
    + destruct Q' as [a2 b2| |Q1 Q2|y2 B2|y2 B2];
        cbn [FOcode_f] in Hcr;
        apply cpair_inj in Hcr; destruct Hcr as [Ecr Hq2];
        try discriminate Ecr.
      rewrite Hq2 in Hq.
      apply cpair_inj in Hq. destruct Hq as [Hy2 Hrb2]. subst y2 rb.
      destruct (IHB B2 x sc Hsub) as [[Hin Heq]|Hgen];
        [|right; exact Hgen].
      left. split.
      * cbn [FOfree_in].
        rewrite (proj2 (Nat.eqb_neq y x) Hne).
        exact Hin.
      * cbn [FOcode_f]. rewrite Heq. reflexivity.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [Hcp _].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [_ [Hcp _]]].
    apply cpair_inj in Hcp. destruct Hcp as [E _]. discriminate E.
  - destruct C as [p [Hpb [Hcp [y0 [Hyb [pb [Hpbb [Hp Hcase]]]]]]]].
    apply cpair_inj in Hcp. destruct Hcp as [_ Hpe]. subst p.
    apply cpair_inj in Hp. destruct Hp as [Hy0 Hpb2]. subst y0 pb.
    destruct Hcase as [[Exy Hr]|[Hne [rb [Hrbb [Hsub [q [Hqb
      [Hq Hcr]]]]]]]].
    + left. split.
      * cbn [FOfree_in]. rewrite Exy, Nat.eqb_refl. reflexivity.
      * exact Hr.
    + destruct Q' as [a2 b2| |Q1 Q2|y2 B2|y2 B2];
        cbn [FOcode_f] in Hcr;
        apply cpair_inj in Hcr; destruct Hcr as [Ecr Hq2];
        try discriminate Ecr.
      rewrite Hq2 in Hq.
      apply cpair_inj in Hq. destruct Hq as [Hy2 Hrb2]. subst y2 rb.
      destruct (IHB B2 x sc Hsub) as [[Hin Heq]|Hgen];
        [|right; exact Hgen].
      left. split.
      * cbn [FOfree_in].
        rewrite (proj2 (Nat.eqb_neq y x) Hne).
        exact Hin.
      * cbn [FOcode_f]. rewrite Heq. reflexivity.
Qed.

(** ** Trace builders: completeness of the master table.

    For each represented function, a structurally recursive builder
    collects the entries of the recursion's call tree.  [entry_ok]
    states an entry's per-tag justification over the membership
    relation of a list; each builder's entries are justified within
    any superset of the builder's own output, with the seed entry
    present carrying the function's value. *)

Record TEntry : Type := mkTE {
  te_tg : nat;
  te_a1 : nat;
  te_a2 : nat;
  te_a3 : nat;
  te_r : nat
}.

Definition listL (L : list TEntry)
    : nat -> nat -> nat -> nat -> nat -> Prop :=
  fun tg a1 a2 a3 r => In (mkTE tg a1 a2 a3 r) L.

Definition entry_ok (L : list TEntry) (e : TEntry) : Prop :=
  match e with
  | mkTE 0 a1 a2 _ r => step0_sem (listL L) a1 a2 r
  | mkTE 1 a1 a2 _ r => step1_sem (listL L) a1 a2 r
  | mkTE 2 a1 a2 a3 r => step2_sem (listL L) a1 a2 a3 r
  | mkTE 3 a1 a2 a3 r => step3_sem (listL L) a1 a2 a3 r
  | mkTE 4 a1 a2 a3 r => step4_sem (listL L) a1 a2 a3 r
  | mkTE 5 a1 _ _ r => step5_sem (listL L) a1 r
  | mkTE _ _ _ _ _ => False
  end.

Lemma entry_ok_0 : forall L a1 a2 a3 r,
  step0_sem (listL L) a1 a2 r -> entry_ok L (mkTE 0 a1 a2 a3 r).
Proof. intros L a1 a2 a3 r H. exact H. Qed.

Lemma entry_ok_1 : forall L a1 a2 a3 r,
  step1_sem (listL L) a1 a2 r -> entry_ok L (mkTE 1 a1 a2 a3 r).
Proof. intros L a1 a2 a3 r H. exact H. Qed.

Lemma entry_ok_2 : forall L a1 a2 a3 r,
  step2_sem (listL L) a1 a2 a3 r -> entry_ok L (mkTE 2 a1 a2 a3 r).
Proof. intros L a1 a2 a3 r H. exact H. Qed.

Lemma entry_ok_3 : forall L a1 a2 a3 r,
  step3_sem (listL L) a1 a2 a3 r -> entry_ok L (mkTE 3 a1 a2 a3 r).
Proof. intros L a1 a2 a3 r H. exact H. Qed.

Lemma entry_ok_4 : forall L a1 a2 a3 r,
  step4_sem (listL L) a1 a2 a3 r -> entry_ok L (mkTE 4 a1 a2 a3 r).
Proof. intros L a1 a2 a3 r H. exact H. Qed.

Lemma entry_ok_5 : forall L a1 a2 a3 r,
  step5_sem (listL L) a1 r -> entry_ok L (mkTE 5 a1 a2 a3 r).
Proof. intros L a1 a2 a3 r H. exact H. Qed.

Lemma in_last : forall (X : Type) (l : list X) (x : X), In x (l ++ [x]).
Proof. intros X l x. apply in_or_app. right. left. reflexivity. Qed.

Lemma incl_app_head : forall (X : Type) (l1 l2 L : list X),
  incl (l1 ++ l2) L -> incl l1 L.
Proof.
  intros X l1 l2 L H z Hz. apply H. apply in_or_app. left. exact Hz.
Qed.

Lemma incl_app_tail : forall (X : Type) (l1 l2 L : list X),
  incl (l1 ++ l2) L -> incl l2 L.
Proof.
  intros X l1 l2 L H z Hz. apply H. apply in_or_app. right. exact Hz.
Qed.

Definition t0E (w : nat) (t : FOTerm) : TEntry :=
  mkTE 0 w (FOcode_tm t) 0 (if FOin_tm w t then 1 else 0).

Definition t1E (w : nat) (A : FOFormula) : TEntry :=
  mkTE 1 w (FOcode_f A) 0 (if FOfree_in w A then 1 else 0).

Definition t2E (x : nat) (s t : FOTerm) : TEntry :=
  mkTE 2 x (FOcode_tm s) (FOcode_tm t) (FOcode_tm (FOsubst_t x s t)).

Definition t3E (x : nat) (s : FOTerm) (A : FOFormula) : TEntry :=
  mkTE 3 x (FOcode_tm s) (FOcode_f A) (FOcode_f (FOsubst_f x s A)).

Definition t4E (x : nat) (s : FOTerm) (A : FOFormula) : TEntry :=
  mkTE 4 x (FOcode_tm s) (FOcode_f A)
    (if FOsubst_ok x s A then 1 else 0).

Definition t5E (k : nat) : TEntry :=
  mkTE 5 k 0 0 (FOcode_tm (FOnumeral k)).

Fixpoint trace0 (w : nat) (t : FOTerm) : list TEntry :=
  match t with
  | FOVar y => [t0E w (FOVar y)]
  | FOZero => [t0E w FOZero]
  | FOSucc a => trace0 w a ++ [t0E w (FOSucc a)]
  | FOPlus a b => trace0 w a ++ trace0 w b ++ [t0E w (FOPlus a b)]
  | FOMult a b => trace0 w a ++ trace0 w b ++ [t0E w (FOMult a b)]
  end.

Fixpoint trace1 (w : nat) (A : FOFormula) : list TEntry :=
  match A with
  | FOEq a b => trace0 w a ++ trace0 w b ++ [t1E w (FOEq a b)]
  | FOFalseF => [t1E w FOFalseF]
  | FOImplF B C => trace1 w B ++ trace1 w C ++ [t1E w (FOImplF B C)]
  | FOForall y B => trace1 w B ++ [t1E w (FOForall y B)]
  | FOExists y B => trace1 w B ++ [t1E w (FOExists y B)]
  end.

Fixpoint trace2 (x : nat) (s t : FOTerm) : list TEntry :=
  match t with
  | FOVar y => [t2E x s (FOVar y)]
  | FOZero => [t2E x s FOZero]
  | FOSucc a => trace2 x s a ++ [t2E x s (FOSucc a)]
  | FOPlus a b => trace2 x s a ++ trace2 x s b ++ [t2E x s (FOPlus a b)]
  | FOMult a b => trace2 x s a ++ trace2 x s b ++ [t2E x s (FOMult a b)]
  end.

Fixpoint trace3 (x : nat) (s : FOTerm) (A : FOFormula) : list TEntry :=
  match A with
  | FOEq a b => trace2 x s a ++ trace2 x s b ++ [t3E x s (FOEq a b)]
  | FOFalseF => [t3E x s FOFalseF]
  | FOImplF B C =>
      trace3 x s B ++ trace3 x s C ++ [t3E x s (FOImplF B C)]
  | FOForall y B => trace3 x s B ++ [t3E x s (FOForall y B)]
  | FOExists y B => trace3 x s B ++ [t3E x s (FOExists y B)]
  end.

Fixpoint trace4 (x : nat) (s : FOTerm) (A : FOFormula) : list TEntry :=
  match A with
  | FOEq a b => [t4E x s (FOEq a b)]
  | FOFalseF => [t4E x s FOFalseF]
  | FOImplF B C =>
      trace4 x s B ++ trace4 x s C ++ [t4E x s (FOImplF B C)]
  | FOForall y B =>
      trace1 x B ++ trace0 y s ++ trace4 x s B
        ++ [t4E x s (FOForall y B)]
  | FOExists y B =>
      trace1 x B ++ trace0 y s ++ trace4 x s B
        ++ [t4E x s (FOExists y B)]
  end.

Fixpoint trace5 (k : nat) : list TEntry :=
  match k with
  | 0 => [t5E 0]
  | S k' => trace5 k' ++ [t5E (S k')]
  end.

Lemma trace0_seed : forall w t r,
  r = (if FOin_tm w t then 1 else 0) ->
  In (mkTE 0 w (FOcode_tm t) 0 r) (trace0 w t).
Proof.
  intros w t r ->.
  destruct t as [y | | a | a b | a b]; cbn [trace0].
  - left. reflexivity.
  - left. reflexivity.
  - apply in_last.
  - apply in_or_app. right. apply in_last.
  - apply in_or_app. right. apply in_last.
Qed.

Lemma trace1_seed : forall w A r,
  r = (if FOfree_in w A then 1 else 0) ->
  In (mkTE 1 w (FOcode_f A) 0 r) (trace1 w A).
Proof.
  intros w A r ->.
  destruct A as [a b | | B C | y B | y B]; cbn [trace1].
  - apply in_or_app. right. apply in_last.
  - left. reflexivity.
  - apply in_or_app. right. apply in_last.
  - apply in_last.
  - apply in_last.
Qed.

Lemma trace2_seed : forall x s t r,
  r = FOcode_tm (FOsubst_t x s t) ->
  In (mkTE 2 x (FOcode_tm s) (FOcode_tm t) r) (trace2 x s t).
Proof.
  intros x s t r ->.
  destruct t as [y | | a | a b | a b]; cbn [trace2].
  - left. reflexivity.
  - left. reflexivity.
  - apply in_last.
  - apply in_or_app. right. apply in_last.
  - apply in_or_app. right. apply in_last.
Qed.

Lemma trace3_seed : forall x s A r,
  r = FOcode_f (FOsubst_f x s A) ->
  In (mkTE 3 x (FOcode_tm s) (FOcode_f A) r) (trace3 x s A).
Proof.
  intros x s A r ->.
  destruct A as [a b | | B C | y B | y B]; cbn [trace3].
  - apply in_or_app. right. apply in_last.
  - left. reflexivity.
  - apply in_or_app. right. apply in_last.
  - apply in_last.
  - apply in_last.
Qed.

Lemma trace4_seed : forall x s A r,
  r = (if FOsubst_ok x s A then 1 else 0) ->
  In (mkTE 4 x (FOcode_tm s) (FOcode_f A) r) (trace4 x s A).
Proof.
  intros x s A r ->.
  destruct A as [a b | | B C | y B | y B]; cbn [trace4].
  - left. reflexivity.
  - left. reflexivity.
  - apply in_or_app. right. apply in_last.
  - apply in_or_app. right. apply in_or_app. right. apply in_last.
  - apply in_or_app. right. apply in_or_app. right. apply in_last.
Qed.

Lemma trace5_seed : forall k r,
  r = FOcode_tm (FOnumeral k) ->
  In (mkTE 5 k 0 0 r) (trace5 k).
Proof.
  intros k r ->.
  destruct k as [|k']; cbn [trace5].
  - left. reflexivity.
  - apply in_last.
Qed.

Lemma trace0_ok : forall w t L,
  incl (trace0 w t) L ->
  forall e, In e (trace0 w t) -> entry_ok L e.
Proof.
  intros w t. induction t as [y | | a IHa | a IHa b IHb | a IHa b IHb];
    intros L Hincl e HeIn; cbn [trace0] in HeIn.
  - destruct HeIn as [<- | []].
    apply entry_ok_0. cbn [FOin_tm FOcode_tm].
    unfold step0_sem. left.
    exists y. split.
    { pose proof (cpair_bound 0 y). lia. }
    split. { reflexivity. }
    destruct (Nat.eqb y w) eqn:Ey.
    + left. split. { apply Nat.eqb_eq. exact Ey. } { reflexivity. }
    + right. split. { apply Nat.eqb_neq. exact Ey. } { reflexivity. }
  - destruct HeIn as [<- | []].
    apply entry_ok_0. unfold step0_sem.
    right; left. split; reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHa L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + destruct HeIn as [<- | []].
      apply entry_ok_0. cbn [FOin_tm FOcode_tm].
      unfold step0_sem. right; right; left.
      exists (FOcode_tm a). split.
      { pose proof (cpair_bound 2 (FOcode_tm a)). lia. }
      split. { reflexivity. }
      apply Hincl. cbn [trace0]. apply in_or_app. left.
      apply trace0_seed. reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHa L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (IHb L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * destruct HeIn as [<- | []].
        apply entry_ok_0. cbn [FOin_tm FOcode_tm].
        unfold step0_sem. right; right; right; left.
        exists (cpair (FOcode_tm a) (FOcode_tm b)). split.
        { pose proof (cpair_bound 3 (cpair (FOcode_tm a) (FOcode_tm b))).
          lia. }
        split. { reflexivity. }
        exists (FOcode_tm a). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        exists (FOcode_tm b). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        split. { reflexivity. }
        destruct (FOin_tm w a) eqn:E1; cbn [orb].
        -- left. split.
           ++ apply Hincl. cbn [trace0]. apply in_or_app. left.
              apply trace0_seed. rewrite E1. reflexivity.
           ++ reflexivity.
        -- right. split.
           ++ apply Hincl. cbn [trace0]. apply in_or_app. left.
              apply trace0_seed. rewrite E1. reflexivity.
           ++ apply Hincl. cbn [trace0]. apply in_or_app. right.
              apply in_or_app. left.
              apply trace0_seed. reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHa L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (IHb L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * destruct HeIn as [<- | []].
        apply entry_ok_0. cbn [FOin_tm FOcode_tm].
        unfold step0_sem. right; right; right; right.
        exists (cpair (FOcode_tm a) (FOcode_tm b)). split.
        { pose proof (cpair_bound 4 (cpair (FOcode_tm a) (FOcode_tm b))).
          lia. }
        split. { reflexivity. }
        exists (FOcode_tm a). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        exists (FOcode_tm b). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        split. { reflexivity. }
        destruct (FOin_tm w a) eqn:E1; cbn [orb].
        -- left. split.
           ++ apply Hincl. cbn [trace0]. apply in_or_app. left.
              apply trace0_seed. rewrite E1. reflexivity.
           ++ reflexivity.
        -- right. split.
           ++ apply Hincl. cbn [trace0]. apply in_or_app. left.
              apply trace0_seed. rewrite E1. reflexivity.
           ++ apply Hincl. cbn [trace0]. apply in_or_app. right.
              apply in_or_app. left.
              apply trace0_seed. reflexivity.
Qed.

Lemma trace1_ok : forall w A L,
  incl (trace1 w A) L ->
  forall e, In e (trace1 w A) -> entry_ok L e.
Proof.
  intros w A. induction A as [a b | | B IHB C IHC | y B IHB | y B IHB];
    intros L Hincl e HeIn; cbn [trace1] in HeIn.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (trace0_ok w a L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (trace0_ok w b L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * destruct HeIn as [<- | []].
        apply entry_ok_1. cbn [FOfree_in FOcode_f].
        unfold step1_sem. left.
        exists (cpair (FOcode_tm a) (FOcode_tm b)). split.
        { pose proof (cpair_bound 0 (cpair (FOcode_tm a) (FOcode_tm b))).
          lia. }
        split. { reflexivity. }
        exists (FOcode_tm a). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        exists (FOcode_tm b). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        split. { reflexivity. }
        destruct (FOin_tm w a) eqn:E1; cbn [orb].
        -- left. split.
           ++ apply Hincl. cbn [trace1]. apply in_or_app. left.
              apply trace0_seed. rewrite E1. reflexivity.
           ++ reflexivity.
        -- right. split.
           ++ apply Hincl. cbn [trace1]. apply in_or_app. left.
              apply trace0_seed. rewrite E1. reflexivity.
           ++ apply Hincl. cbn [trace1]. apply in_or_app. right.
              apply in_or_app. left.
              apply trace0_seed. reflexivity.
  - destruct HeIn as [<- | []].
    apply entry_ok_1. unfold step1_sem.
    right; left. split; reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHB L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (IHC L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * destruct HeIn as [<- | []].
        apply entry_ok_1. cbn [FOfree_in FOcode_f].
        unfold step1_sem. right; right; left.
        exists (cpair (FOcode_f B) (FOcode_f C)). split.
        { pose proof (cpair_bound 2 (cpair (FOcode_f B) (FOcode_f C))).
          lia. }
        split. { reflexivity. }
        exists (FOcode_f B). split.
        { pose proof (cpair_bound (FOcode_f B) (FOcode_f C)). lia. }
        exists (FOcode_f C). split.
        { pose proof (cpair_bound (FOcode_f B) (FOcode_f C)). lia. }
        split. { reflexivity. }
        destruct (FOfree_in w B) eqn:E1; cbn [orb].
        -- left. split.
           ++ apply Hincl. cbn [trace1]. apply in_or_app. left.
              apply trace1_seed. rewrite E1. reflexivity.
           ++ reflexivity.
        -- right. split.
           ++ apply Hincl. cbn [trace1]. apply in_or_app. left.
              apply trace1_seed. rewrite E1. reflexivity.
           ++ apply Hincl. cbn [trace1]. apply in_or_app. right.
              apply in_or_app. left.
              apply trace1_seed. reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHB L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + destruct HeIn as [<- | []].
      apply entry_ok_1. cbn [FOfree_in FOcode_f].
      unfold step1_sem. right; right; right; left.
      exists (cpair y (FOcode_f B)). split.
      { pose proof (cpair_bound 3 (cpair y (FOcode_f B))). lia. }
      split. { reflexivity. }
      exists y. split.
      { pose proof (cpair_bound y (FOcode_f B)). lia. }
      exists (FOcode_f B). split.
      { pose proof (cpair_bound y (FOcode_f B)). lia. }
      split. { reflexivity. }
      destruct (Nat.eqb y w) eqn:Ey.
      * left. split. { apply Nat.eqb_eq. exact Ey. } { reflexivity. }
      * right. split. { apply Nat.eqb_neq. exact Ey. }
        apply Hincl. cbn [trace1]. apply in_or_app. left.
        apply trace1_seed. reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHB L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + destruct HeIn as [<- | []].
      apply entry_ok_1. cbn [FOfree_in FOcode_f].
      unfold step1_sem. right; right; right; right.
      exists (cpair y (FOcode_f B)). split.
      { pose proof (cpair_bound 4 (cpair y (FOcode_f B))). lia. }
      split. { reflexivity. }
      exists y. split.
      { pose proof (cpair_bound y (FOcode_f B)). lia. }
      exists (FOcode_f B). split.
      { pose proof (cpair_bound y (FOcode_f B)). lia. }
      split. { reflexivity. }
      destruct (Nat.eqb y w) eqn:Ey.
      * left. split. { apply Nat.eqb_eq. exact Ey. } { reflexivity. }
      * right. split. { apply Nat.eqb_neq. exact Ey. }
        apply Hincl. cbn [trace1]. apply in_or_app. left.
        apply trace1_seed. reflexivity.
Qed.

Lemma trace2_ok : forall x s t L,
  incl (trace2 x s t) L ->
  forall e, In e (trace2 x s t) -> entry_ok L e.
Proof.
  intros x s t.
  induction t as [y | | a IHa | a IHa b IHb | a IHa b IHb];
    intros L Hincl e HeIn; cbn [trace2] in HeIn.
  - destruct HeIn as [<- | []].
    apply entry_ok_2. cbn [FOsubst_t FOcode_tm].
    unfold step2_sem. left.
    exists y. split.
    { pose proof (cpair_bound 0 y). lia. }
    split. { reflexivity. }
    destruct (Nat.eqb y x) eqn:Ey.
    + left. split. { apply Nat.eqb_eq. exact Ey. } { reflexivity. }
    + right. split. { apply Nat.eqb_neq. exact Ey. }
      cbn [FOcode_tm]. reflexivity.
  - destruct HeIn as [<- | []].
    apply entry_ok_2. unfold step2_sem.
    right; left. split; reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHa L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + destruct HeIn as [<- | []].
      apply entry_ok_2. cbn [FOsubst_t FOcode_tm].
      unfold step2_sem. right; right; left.
      exists (FOcode_tm a). split.
      { pose proof (cpair_bound 2 (FOcode_tm a)). lia. }
      split. { reflexivity. }
      exists (FOcode_tm (FOsubst_t x s a)). split.
      { pose proof (cpair_bound 2 (FOcode_tm (FOsubst_t x s a))). lia. }
      split.
      { apply Hincl. cbn [trace2]. apply in_or_app. left.
        apply trace2_seed. reflexivity. }
      reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHa L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (IHb L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * destruct HeIn as [<- | []].
        apply entry_ok_2. cbn [FOsubst_t FOcode_tm].
        unfold step2_sem. right; right; right; left.
        exists (cpair (FOcode_tm a) (FOcode_tm b)). split.
        { pose proof (cpair_bound 3 (cpair (FOcode_tm a) (FOcode_tm b))).
          lia. }
        split. { reflexivity. }
        exists (FOcode_tm a). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        exists (FOcode_tm b). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        split. { reflexivity. }
        exists (FOcode_tm (FOsubst_t x s a)). split.
        { pose proof (cpair_bound 3
            (cpair (FOcode_tm (FOsubst_t x s a))
                   (FOcode_tm (FOsubst_t x s b)))).
          pose proof (cpair_bound (FOcode_tm (FOsubst_t x s a))
                        (FOcode_tm (FOsubst_t x s b))).
          lia. }
        exists (FOcode_tm (FOsubst_t x s b)). split.
        { pose proof (cpair_bound 3
            (cpair (FOcode_tm (FOsubst_t x s a))
                   (FOcode_tm (FOsubst_t x s b)))).
          pose proof (cpair_bound (FOcode_tm (FOsubst_t x s a))
                        (FOcode_tm (FOsubst_t x s b))).
          lia. }
        split.
        { apply Hincl. cbn [trace2]. apply in_or_app. left.
          apply trace2_seed. reflexivity. }
        split.
        { apply Hincl. cbn [trace2]. apply in_or_app. right.
          apply in_or_app. left.
          apply trace2_seed. reflexivity. }
        exists (cpair (FOcode_tm (FOsubst_t x s a))
                      (FOcode_tm (FOsubst_t x s b))).
        split.
        { pose proof (cpair_bound 3
            (cpair (FOcode_tm (FOsubst_t x s a))
                   (FOcode_tm (FOsubst_t x s b)))).
          lia. }
        split; reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHa L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (IHb L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * destruct HeIn as [<- | []].
        apply entry_ok_2. cbn [FOsubst_t FOcode_tm].
        unfold step2_sem. right; right; right; right.
        exists (cpair (FOcode_tm a) (FOcode_tm b)). split.
        { pose proof (cpair_bound 4 (cpair (FOcode_tm a) (FOcode_tm b))).
          lia. }
        split. { reflexivity. }
        exists (FOcode_tm a). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        exists (FOcode_tm b). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        split. { reflexivity. }
        exists (FOcode_tm (FOsubst_t x s a)). split.
        { pose proof (cpair_bound 4
            (cpair (FOcode_tm (FOsubst_t x s a))
                   (FOcode_tm (FOsubst_t x s b)))).
          pose proof (cpair_bound (FOcode_tm (FOsubst_t x s a))
                        (FOcode_tm (FOsubst_t x s b))).
          lia. }
        exists (FOcode_tm (FOsubst_t x s b)). split.
        { pose proof (cpair_bound 4
            (cpair (FOcode_tm (FOsubst_t x s a))
                   (FOcode_tm (FOsubst_t x s b)))).
          pose proof (cpair_bound (FOcode_tm (FOsubst_t x s a))
                        (FOcode_tm (FOsubst_t x s b))).
          lia. }
        split.
        { apply Hincl. cbn [trace2]. apply in_or_app. left.
          apply trace2_seed. reflexivity. }
        split.
        { apply Hincl. cbn [trace2]. apply in_or_app. right.
          apply in_or_app. left.
          apply trace2_seed. reflexivity. }
        exists (cpair (FOcode_tm (FOsubst_t x s a))
                      (FOcode_tm (FOsubst_t x s b))).
        split.
        { pose proof (cpair_bound 4
            (cpair (FOcode_tm (FOsubst_t x s a))
                   (FOcode_tm (FOsubst_t x s b)))).
          lia. }
        split; reflexivity.
Qed.

Lemma trace3_ok : forall x s A L,
  incl (trace3 x s A) L ->
  forall e, In e (trace3 x s A) -> entry_ok L e.
Proof.
  intros x s A.
  induction A as [a b | | B IHB C IHC | y B IHB | y B IHB];
    intros L Hincl e HeIn; cbn [trace3] in HeIn.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (trace2_ok x s a L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (trace2_ok x s b L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * destruct HeIn as [<- | []].
        apply entry_ok_3. cbn [FOsubst_f FOcode_f].
        unfold step3_sem. left.
        exists (cpair (FOcode_tm a) (FOcode_tm b)). split.
        { pose proof (cpair_bound 0 (cpair (FOcode_tm a) (FOcode_tm b))).
          lia. }
        split. { reflexivity. }
        exists (FOcode_tm a). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        exists (FOcode_tm b). split.
        { pose proof (cpair_bound (FOcode_tm a) (FOcode_tm b)). lia. }
        split. { reflexivity. }
        exists (FOcode_tm (FOsubst_t x s a)). split.
        { pose proof (cpair_bound 0
            (cpair (FOcode_tm (FOsubst_t x s a))
                   (FOcode_tm (FOsubst_t x s b)))).
          pose proof (cpair_bound (FOcode_tm (FOsubst_t x s a))
                        (FOcode_tm (FOsubst_t x s b))).
          lia. }
        exists (FOcode_tm (FOsubst_t x s b)). split.
        { pose proof (cpair_bound 0
            (cpair (FOcode_tm (FOsubst_t x s a))
                   (FOcode_tm (FOsubst_t x s b)))).
          pose proof (cpair_bound (FOcode_tm (FOsubst_t x s a))
                        (FOcode_tm (FOsubst_t x s b))).
          lia. }
        split.
        { apply Hincl. cbn [trace3]. apply in_or_app. left.
          apply trace2_seed. reflexivity. }
        split.
        { apply Hincl. cbn [trace3]. apply in_or_app. right.
          apply in_or_app. left.
          apply trace2_seed. reflexivity. }
        exists (cpair (FOcode_tm (FOsubst_t x s a))
                      (FOcode_tm (FOsubst_t x s b))).
        split.
        { pose proof (cpair_bound 0
            (cpair (FOcode_tm (FOsubst_t x s a))
                   (FOcode_tm (FOsubst_t x s b)))).
          lia. }
        split; reflexivity.
  - destruct HeIn as [<- | []].
    apply entry_ok_3. unfold step3_sem.
    right; left. split; reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHB L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (IHC L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * destruct HeIn as [<- | []].
        apply entry_ok_3. cbn [FOsubst_f FOcode_f].
        unfold step3_sem. right; right; left.
        exists (cpair (FOcode_f B) (FOcode_f C)). split.
        { pose proof (cpair_bound 2 (cpair (FOcode_f B) (FOcode_f C))).
          lia. }
        split. { reflexivity. }
        exists (FOcode_f B). split.
        { pose proof (cpair_bound (FOcode_f B) (FOcode_f C)). lia. }
        exists (FOcode_f C). split.
        { pose proof (cpair_bound (FOcode_f B) (FOcode_f C)). lia. }
        split. { reflexivity. }
        exists (FOcode_f (FOsubst_f x s B)). split.
        { pose proof (cpair_bound 2
            (cpair (FOcode_f (FOsubst_f x s B))
                   (FOcode_f (FOsubst_f x s C)))).
          pose proof (cpair_bound (FOcode_f (FOsubst_f x s B))
                        (FOcode_f (FOsubst_f x s C))).
          lia. }
        exists (FOcode_f (FOsubst_f x s C)). split.
        { pose proof (cpair_bound 2
            (cpair (FOcode_f (FOsubst_f x s B))
                   (FOcode_f (FOsubst_f x s C)))).
          pose proof (cpair_bound (FOcode_f (FOsubst_f x s B))
                        (FOcode_f (FOsubst_f x s C))).
          lia. }
        split.
        { apply Hincl. cbn [trace3]. apply in_or_app. left.
          apply trace3_seed. reflexivity. }
        split.
        { apply Hincl. cbn [trace3]. apply in_or_app. right.
          apply in_or_app. left.
          apply trace3_seed. reflexivity. }
        exists (cpair (FOcode_f (FOsubst_f x s B))
                      (FOcode_f (FOsubst_f x s C))).
        split.
        { pose proof (cpair_bound 2
            (cpair (FOcode_f (FOsubst_f x s B))
                   (FOcode_f (FOsubst_f x s C)))).
          lia. }
        split; reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHB L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + destruct HeIn as [<- | []].
      apply entry_ok_3. cbn [FOsubst_f FOcode_f].
      unfold step3_sem. right; right; right; left.
      exists (cpair y (FOcode_f B)). split.
      { pose proof (cpair_bound 3 (cpair y (FOcode_f B))). lia. }
      split. { reflexivity. }
      exists y. split.
      { pose proof (cpair_bound y (FOcode_f B)). lia. }
      exists (FOcode_f B). split.
      { pose proof (cpair_bound y (FOcode_f B)). lia. }
      split. { reflexivity. }
      destruct (Nat.eqb y x) eqn:Ey.
      * left. split. { apply Nat.eqb_eq. exact Ey. }
        cbn [FOcode_f]. reflexivity.
      * right. split. { apply Nat.eqb_neq. exact Ey. }
        exists (FOcode_f (FOsubst_f x s B)). split.
        { cbn [FOcode_f].
          pose proof (cpair_bound 3
            (cpair y (FOcode_f (FOsubst_f x s B)))).
          pose proof (cpair_bound y (FOcode_f (FOsubst_f x s B))).
          lia. }
        split.
        { apply Hincl. cbn [trace3]. apply in_or_app. left.
          apply trace3_seed. reflexivity. }
        exists (cpair y (FOcode_f (FOsubst_f x s B))).
        split.
        { cbn [FOcode_f].
          pose proof (cpair_bound 3
            (cpair y (FOcode_f (FOsubst_f x s B)))).
          lia. }
        split. { reflexivity. }
        cbn [FOcode_f]. reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHB L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + destruct HeIn as [<- | []].
      apply entry_ok_3. cbn [FOsubst_f FOcode_f].
      unfold step3_sem. right; right; right; right.
      exists (cpair y (FOcode_f B)). split.
      { pose proof (cpair_bound 4 (cpair y (FOcode_f B))). lia. }
      split. { reflexivity. }
      exists y. split.
      { pose proof (cpair_bound y (FOcode_f B)). lia. }
      exists (FOcode_f B). split.
      { pose proof (cpair_bound y (FOcode_f B)). lia. }
      split. { reflexivity. }
      destruct (Nat.eqb y x) eqn:Ey.
      * left. split. { apply Nat.eqb_eq. exact Ey. }
        cbn [FOcode_f]. reflexivity.
      * right. split. { apply Nat.eqb_neq. exact Ey. }
        exists (FOcode_f (FOsubst_f x s B)). split.
        { cbn [FOcode_f].
          pose proof (cpair_bound 4
            (cpair y (FOcode_f (FOsubst_f x s B)))).
          pose proof (cpair_bound y (FOcode_f (FOsubst_f x s B))).
          lia. }
        split.
        { apply Hincl. cbn [trace3]. apply in_or_app. left.
          apply trace3_seed. reflexivity. }
        exists (cpair y (FOcode_f (FOsubst_f x s B))).
        split.
        { cbn [FOcode_f].
          pose proof (cpair_bound 4
            (cpair y (FOcode_f (FOsubst_f x s B)))).
          lia. }
        split. { reflexivity. }
        cbn [FOcode_f]. reflexivity.
Qed.

Lemma trace4_ok : forall x s A L,
  incl (trace4 x s A) L ->
  forall e, In e (trace4 x s A) -> entry_ok L e.
Proof.
  intros x s A.
  induction A as [a b | | B IHB C IHC | y B IHB | y B IHB];
    intros L Hincl e HeIn; cbn [trace4] in HeIn.
  - destruct HeIn as [<- | []].
    apply entry_ok_4. cbn [FOsubst_ok FOcode_f].
    unfold step4_sem. left.
    exists (cpair (FOcode_tm a) (FOcode_tm b)). split.
    { pose proof (cpair_bound 0 (cpair (FOcode_tm a) (FOcode_tm b))).
      lia. }
    split; reflexivity.
  - destruct HeIn as [<- | []].
    apply entry_ok_4. unfold step4_sem.
    right; left. split; reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IHB L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (IHC L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * destruct HeIn as [<- | []].
        apply entry_ok_4. cbn [FOsubst_ok FOcode_f].
        unfold step4_sem. right; right; left.
        exists (cpair (FOcode_f B) (FOcode_f C)). split.
        { pose proof (cpair_bound 2 (cpair (FOcode_f B) (FOcode_f C))).
          lia. }
        split. { reflexivity. }
        exists (FOcode_f B). split.
        { pose proof (cpair_bound (FOcode_f B) (FOcode_f C)). lia. }
        exists (FOcode_f C). split.
        { pose proof (cpair_bound (FOcode_f B) (FOcode_f C)). lia. }
        split. { reflexivity. }
        destruct (FOsubst_ok x s B) eqn:E1; cbn [andb].
        -- right. split.
           ++ apply Hincl. cbn [trace4]. apply in_or_app. left.
              apply trace4_seed. rewrite E1. reflexivity.
           ++ apply Hincl. cbn [trace4]. apply in_or_app. right.
              apply in_or_app. left.
              apply trace4_seed. reflexivity.
        -- left. split.
           ++ apply Hincl. cbn [trace4]. apply in_or_app. left.
              apply trace4_seed. rewrite E1. reflexivity.
           ++ reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (trace1_ok x B L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (trace0_ok y s L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
        -- apply (IHB L
             (incl_app_head _ _ _ _
               (incl_app_tail _ _ _ _ (incl_app_tail _ _ _ _ Hincl)))
             e HeIn).
        -- destruct HeIn as [<- | []].
           apply entry_ok_4. cbn [FOsubst_ok FOcode_f].
           unfold step4_sem. right; right; right; left.
           exists (cpair y (FOcode_f B)). split.
           { pose proof (cpair_bound 3 (cpair y (FOcode_f B))). lia. }
           split. { reflexivity. }
           exists y. split.
           { pose proof (cpair_bound y (FOcode_f B)). lia. }
           exists (FOcode_f B). split.
           { pose proof (cpair_bound y (FOcode_f B)). lia. }
           split. { reflexivity. }
           destruct (Nat.eqb y x) eqn:Eyx.
           ++ left. split. { apply Nat.eqb_eq. exact Eyx. }
              { reflexivity. }
           ++ right. split. { apply Nat.eqb_neq. exact Eyx. }
              destruct (FOfree_in x B) eqn:Ef.
              ** right. split.
                 { apply Hincl. cbn [trace4]. apply in_or_app. left.
                   apply trace1_seed. rewrite Ef. reflexivity. }
                 destruct (FOin_tm y s) eqn:Eys; cbn [negb andb].
                 --- left. split.
                     { apply Hincl. cbn [trace4].
                       apply in_or_app. right.
                       apply in_or_app. left.
                       apply trace0_seed. rewrite Eys. reflexivity. }
                     { reflexivity. }
                 --- right. split.
                     { apply Hincl. cbn [trace4].
                       apply in_or_app. right.
                       apply in_or_app. left.
                       apply trace0_seed. rewrite Eys. reflexivity. }
                     { apply Hincl. cbn [trace4].
                       apply in_or_app. right.
                       apply in_or_app. right.
                       apply in_or_app. left.
                       apply trace4_seed. reflexivity. }
              ** left. split.
                 { apply Hincl. cbn [trace4]. apply in_or_app. left.
                   apply trace1_seed. rewrite Ef. reflexivity. }
                 { reflexivity. }
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (trace1_ok x B L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
      * apply (trace0_ok y s L
          (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl)) e HeIn).
      * apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
        -- apply (IHB L
             (incl_app_head _ _ _ _
               (incl_app_tail _ _ _ _ (incl_app_tail _ _ _ _ Hincl)))
             e HeIn).
        -- destruct HeIn as [<- | []].
           apply entry_ok_4. cbn [FOsubst_ok FOcode_f].
           unfold step4_sem. right; right; right; right.
           exists (cpair y (FOcode_f B)). split.
           { pose proof (cpair_bound 4 (cpair y (FOcode_f B))). lia. }
           split. { reflexivity. }
           exists y. split.
           { pose proof (cpair_bound y (FOcode_f B)). lia. }
           exists (FOcode_f B). split.
           { pose proof (cpair_bound y (FOcode_f B)). lia. }
           split. { reflexivity. }
           destruct (Nat.eqb y x) eqn:Eyx.
           ++ left. split. { apply Nat.eqb_eq. exact Eyx. }
              { reflexivity. }
           ++ right. split. { apply Nat.eqb_neq. exact Eyx. }
              destruct (FOfree_in x B) eqn:Ef.
              ** right. split.
                 { apply Hincl. cbn [trace4]. apply in_or_app. left.
                   apply trace1_seed. rewrite Ef. reflexivity. }
                 destruct (FOin_tm y s) eqn:Eys; cbn [negb andb].
                 --- left. split.
                     { apply Hincl. cbn [trace4].
                       apply in_or_app. right.
                       apply in_or_app. left.
                       apply trace0_seed. rewrite Eys. reflexivity. }
                     { reflexivity. }
                 --- right. split.
                     { apply Hincl. cbn [trace4].
                       apply in_or_app. right.
                       apply in_or_app. left.
                       apply trace0_seed. rewrite Eys. reflexivity. }
                     { apply Hincl. cbn [trace4].
                       apply in_or_app. right.
                       apply in_or_app. right.
                       apply in_or_app. left.
                       apply trace4_seed. reflexivity. }
              ** left. split.
                 { apply Hincl. cbn [trace4]. apply in_or_app. left.
                   apply trace1_seed. rewrite Ef. reflexivity. }
                 { reflexivity. }
Qed.

Lemma trace5_ok : forall k L,
  incl (trace5 k) L ->
  forall e, In e (trace5 k) -> entry_ok L e.
Proof.
  intros k. induction k as [|k' IH]; intros L Hincl e HeIn;
    cbn [trace5] in HeIn.
  - destruct HeIn as [<- | []].
    apply entry_ok_5. unfold step5_sem.
    left. split; reflexivity.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn | HeIn].
    + apply (IH L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + destruct HeIn as [<- | []].
      apply entry_ok_5. cbn [FOnumeral FOcode_tm].
      unfold step5_sem. right.
      exists k'. split. { lia. }
      split. { reflexivity. }
      exists (FOcode_tm (FOnumeral k')). split.
      { pose proof (cpair_bound 2 (FOcode_tm (FOnumeral k'))). lia. }
      split.
      { apply Hincl. cbn [trace5]. apply in_or_app. left.
        apply trace5_seed. reflexivity. }
      reflexivity.
Qed.

(** ** Realizing a justified entry list as a beta-coded table.

    [beta_complete] codes the five projected tracks; membership in the
    list and membership in the coded table coincide pointwise, so the
    per-entry justifications transport across the step-semantics
    extensionality lemmas, giving table validity at every position. *)

Definition TEd0 : TEntry := mkTE 0 0 0 0 0.

Theorem table_realize : forall L,
  (forall e, In e L -> entry_ok L e) ->
  exists vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr,
    (forall tg a1 a2 a3 r,
       listL L tg a1 a2 a3 r <->
       tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr (length L)
         tg a1 a2 a3 r) /\
    (forall j, j < length L ->
       dispatch_sem
         (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr (length L))
         vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr j).
Proof.
  intros L Hok.
  destruct (beta_complete (map te_tg L)) as [vct [vdt Hbt]].
  destruct (beta_complete (map te_a1 L)) as [vc1 [vd1 Hb1]].
  destruct (beta_complete (map te_a2 L)) as [vc2 [vd2 Hb2]].
  destruct (beta_complete (map te_a3 L)) as [vc3 [vd3 Hb3]].
  destruct (beta_complete (map te_r L)) as [vcr [vdr Hbr]].
  assert (Qt : forall i, i < length L ->
      beta vct vdt i = te_tg (nth i L TEd0)).
  { intros i Hi. rewrite <- (map_nth te_tg L TEd0 i).
    apply Hbt. rewrite length_map. exact Hi. }
  assert (Q1 : forall i, i < length L ->
      beta vc1 vd1 i = te_a1 (nth i L TEd0)).
  { intros i Hi. rewrite <- (map_nth te_a1 L TEd0 i).
    apply Hb1. rewrite length_map. exact Hi. }
  assert (Q2 : forall i, i < length L ->
      beta vc2 vd2 i = te_a2 (nth i L TEd0)).
  { intros i Hi. rewrite <- (map_nth te_a2 L TEd0 i).
    apply Hb2. rewrite length_map. exact Hi. }
  assert (Q3 : forall i, i < length L ->
      beta vc3 vd3 i = te_a3 (nth i L TEd0)).
  { intros i Hi. rewrite <- (map_nth te_a3 L TEd0 i).
    apply Hb3. rewrite length_map. exact Hi. }
  assert (Qr : forall i, i < length L ->
      beta vcr vdr i = te_r (nth i L TEd0)).
  { intros i Hi. rewrite <- (map_nth te_r L TEd0 i).
    apply Hbr. rewrite length_map. exact Hi. }
  exists vct, vdt, vc1, vd1, vc2, vd2, vc3, vd3, vcr, vdr.
  assert (HIFF : forall tg a1 a2 a3 r,
      listL L tg a1 a2 a3 r <->
      tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr (length L)
        tg a1 a2 a3 r).
  { intros tg a1 a2 a3 r. split.
    - intro HIn. unfold listL in HIn.
      destruct (In_nth L _ TEd0 HIn) as [j [Hj Hnth]].
      exists j. split; [exact Hj|].
      rewrite (Qt j Hj), (Q1 j Hj), (Q2 j Hj), (Q3 j Hj), (Qr j Hj).
      rewrite Hnth. cbn [te_tg te_a1 te_a2 te_a3 te_r].
      repeat split; reflexivity.
    - intros [j [Hj [Et [E1 [E2 [E3 Er]]]]]].
      unfold listL.
      rewrite (Qt j Hj) in Et. rewrite (Q1 j Hj) in E1.
      rewrite (Q2 j Hj) in E2. rewrite (Q3 j Hj) in E3.
      rewrite (Qr j Hj) in Er.
      assert (Hnth : nth j L TEd0 = mkTE tg a1 a2 a3 r).
      { destruct (nth j L TEd0) as [g b1 b2 b3 br].
        cbn [te_tg te_a1 te_a2 te_a3 te_r] in Et, E1, E2, E3, Er.
        subst. reflexivity. }
      rewrite <- Hnth. apply nth_In. exact Hj. }
  split; [exact HIFF|].
  intros j Hj.
  pose proof (Hok (nth j L TEd0) (nth_In L TEd0 Hj)) as He.
  unfold dispatch_sem.
  exists (te_tg (nth j L TEd0)). split.
  { rewrite <- (Qt j Hj). unfold beta.
    pose proof (Nat.Div0.mod_le vct (vdt * S j + 1)). lia. }
  exists (te_a1 (nth j L TEd0)). split.
  { rewrite <- (Q1 j Hj). unfold beta.
    pose proof (Nat.Div0.mod_le vc1 (vd1 * S j + 1)). lia. }
  exists (te_a2 (nth j L TEd0)). split.
  { rewrite <- (Q2 j Hj). unfold beta.
    pose proof (Nat.Div0.mod_le vc2 (vd2 * S j + 1)). lia. }
  exists (te_a3 (nth j L TEd0)). split.
  { rewrite <- (Q3 j Hj). unfold beta.
    pose proof (Nat.Div0.mod_le vc3 (vd3 * S j + 1)). lia. }
  exists (te_r (nth j L TEd0)). split.
  { rewrite <- (Qr j Hj). unfold beta.
    pose proof (Nat.Div0.mod_le vcr (vdr * S j + 1)). lia. }
  split. { exact (Qt j Hj). }
  split. { exact (Q1 j Hj). }
  split. { exact (Q2 j Hj). }
  split. { exact (Q3 j Hj). }
  split. { exact (Qr j Hj). }
  destruct (nth j L TEd0) as [tg a1 a2 a3 r] eqn:Ee.
  cbn [te_tg te_a1 te_a2 te_a3 te_r].
  destruct tg as [|[|[|[|[|[|t7]]]]]].
  - left. split. { reflexivity. }
    exact (proj1 (step0_sem_ext (listL L) _ a1 a2 r HIFF) He).
  - right; left. split. { reflexivity. }
    exact (proj1 (step1_sem_ext (listL L) _ a1 a2 r HIFF) He).
  - right; right; left. split. { reflexivity. }
    exact (proj1 (step2_sem_ext (listL L) _ a1 a2 a3 r HIFF) He).
  - right; right; right; left. split. { reflexivity. }
    exact (proj1 (step3_sem_ext (listL L) _ a1 a2 a3 r HIFF) He).
  - right; right; right; right; left. split. { reflexivity. }
    exact (proj1 (step4_sem_ext (listL L) _ a1 a2 a3 r HIFF) He).
  - right; right; right; right; right. split. { reflexivity. }
    exact (proj1 (step5_sem_ext (listL L) _ a1 r HIFF) He).
  - exfalso. exact He.
Qed.

(** ** Satisfaction of the provability sentence.

    [provmat_sem cores u f]: some master table validates every
    dispatch position, some derivation pair of tracks ends at the
    target code [f], and every derivation position carries a
    justification accepted against the table, the core list, and the
    self template code [u].  The three lemmas walk the conjunction,
    the sixteen-variable prefix, and the two numeral substitutions. *)

Definition provmat_sem (cores : list nat) (u f : nat) : Prop :=
  exists vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen vcs vds vcj vdj
    vdlen,
    (forall vj, vj < vlen ->
       dispatch_sem
         (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
         vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vj) /\
    (exists m, vdlen = S m /\ beta vcs vds m = f) /\
    (forall ii, ii < vdlen ->
       justck_sem
         (tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen)
         cores u vcs vds vcj vdj ii) /\
    (forall ii, ii < vdlen ->
       exists rg,
         tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr vlen
           3 (S (beta vcs vds ii)) 0 (beta vcs vds ii) rg).

Lemma FOsat_FOGUARDC : forall e B ct dt c1 d1 c2 d2 c3 d3 cr dr len
    cs ds i,
  tbl_below B ct dt c1 d1 c2 d2 c3 d3 cr dr len ->
  FOmax_var_tm cs < B -> FOmax_var_tm ds < B ->
  FOmax_var_tm i < B ->
  (FOsat e (FOGUARDC B ct dt c1 d1 c2 d2 c3 d3 cr dr len cs ds i)
   <->
   exists rg,
     tblL (FOeval e ct) (FOeval e dt) (FOeval e c1) (FOeval e d1)
       (FOeval e c2) (FOeval e d2) (FOeval e c3) (FOeval e d3)
       (FOeval e cr) (FOeval e dr) (FOeval e len)
       3 (S (beta (FOeval e cs) (FOeval e ds) (FOeval e i))) 0
       (beta (FOeval e cs) (FOeval e ds) (FOeval e i)) rg).
Proof.
  intros e B ct dt c1 d1 c2 d2 c3 d3 cr dr len cs ds i Htb Hcs Hds Hi.
  pose proof Htb as Htb'.
  destruct Htb' as [Hct [Hdt [Hc1 [Hd1' [Hc2 [Hd2' [Hc3 [Hd3'
    [Hcr [Hdr Hlen]]]]]]]]]].
  assert (Htb8 : tbl_below (B+8) ct dt c1 d1 c2 d2 c3 d3 cr dr len)
    by (unfold tbl_below; lia).
  assert (HinB : FOin_tm B (FOSucc cs) = false)
    by (apply FOin_tm_above; cbn; lia).
  assert (HinSB : FOin_tm (S B) (FOSucc cs) = false)
    by (apply FOin_tm_above; cbn; lia).
  assert (HinB6 : FOin_tm (B+6) (FOSucc cr) = false)
    by (apply FOin_tm_above; cbn; lia).
  assert (HinSB6 : FOin_tm (S (B+6)) (FOSucc cr) = false)
    by (apply FOin_tm_above; cbn; lia).
  assert (H3m : FOmax_var_tm (FOnumeral 3) < B+8)
    by (rewrite FOmax_var_numeral; lia).
  assert (HSvB : FOmax_var_tm (FOSucc (FOVar B)) < B+8) by (cbn; lia).
  assert (HzB : FOmax_var_tm FOZero < B+8) by (cbn; lia).
  assert (HvB : FOmax_var_tm (FOVar B) < B+8) by (cbn; lia).
  assert (HvB6 : FOmax_var_tm (FOVar (B+6)) < B+8) by (cbn; lia).
  unfold FOGUARDC.
  rewrite (FOsat_FOBexC e B (FOSucc cs) _ HinB HinSB).
  split.
  - intros [vd [Hvdb Hb1]].
    apply (proj1 (FOsat_FOAnd _ _ _)) in Hb1.
    destruct Hb1 as [Hbeta Hb2].
    set (e1 := FOupdate e B vd) in *.
    apply (proj1 (FOsat_FObetaF e1 (B+2) cs ds i (FOVar B)
                    ltac:(lia) ltac:(lia) ltac:(lia)
                    ltac:(cbn; lia))) in Hbeta.
    cbn [FOeval] in Hbeta.
    unfold e1 in Hbeta.
    rewrite (FOeval_update_above cs e B vd Hcs) in Hbeta.
    rewrite (FOeval_update_above ds e B vd Hds) in Hbeta.
    rewrite (FOeval_update_above i e B vd Hi) in Hbeta.
    rewrite (FOupdate_eq _ _ _) in Hbeta.
    apply (proj1 (FOsat_FOBexC _ (B+6) (FOSucc cr) _ HinB6 HinSB6))
      in Hb2.
    destruct Hb2 as [rg [Hrgb Hlk]].
    set (e2 := FOupdate e1 (B+6) rg) in *.
    apply (proj1 (FOsat_FOlookup e2 (B+8) ct dt c1 d1 c2 d2 c3 d3 cr
                    dr len (FOnumeral 3) (FOSucc (FOVar B)) FOZero
                    (FOVar B) (FOVar (B+6))
                    Htb8 H3m HSvB HzB HvB HvB6)) in Hlk.
    destruct Hlk as [j [Hj [Hf1 [Hf2 [Hf3 [Hf4 Hf5]]]]]].
    assert (Hstab : forall t, FOmax_var_tm t < B ->
        FOeval e2 t = FOeval e t).
    { intros t Ht. unfold e2, e1.
      rewrite (FOeval_update_above t _ (B+6) rg ltac:(lia)).
      exact (FOeval_update_above t e B vd Ht). }
    assert (EvB : e2 B = vd).
    { unfold e2, e1.
      rewrite (FOupdate_neq _ (B+6) rg B ltac:(lia)).
      apply FOupdate_eq. }
    assert (EvB6 : e2 (B+6) = rg).
    { unfold e2. apply FOupdate_eq. }
    rewrite (Hstab len Hlen) in Hj.
    rewrite (Hstab ct Hct), (Hstab dt Hdt), FOeval_numeral in Hf1.
    cbn [FOeval] in Hf2, Hf3, Hf4, Hf5.
    rewrite (Hstab c1 Hc1), (Hstab d1 Hd1'), EvB in Hf2.
    rewrite (Hstab c2 Hc2), (Hstab d2 Hd2') in Hf3.
    rewrite (Hstab c3 Hc3), (Hstab d3 Hd3'), EvB in Hf4.
    rewrite (Hstab cr Hcr), (Hstab dr Hdr), EvB6 in Hf5.
    rewrite <- Hbeta in Hf2, Hf4.
    exists rg, j.
    repeat split; assumption.
  - intros [rg Hrow].
    destruct Hrow as [j [Hj [Hf1 [Hf2 [Hf3 [Hf4 Hf5]]]]]].
    set (vd := beta (FOeval e cs) (FOeval e ds) (FOeval e i)) in *.
    exists vd. split.
    { cbn [FOeval]. unfold vd, beta.
      pose proof (Nat.Div0.mod_le (FOeval e cs)
        ((FOeval e ds) * S (FOeval e i) + 1)). lia. }
    set (e1 := FOupdate e B vd).
    apply (proj2 (FOsat_FOAnd _ _ _)). split.
    { apply (proj2 (FOsat_FObetaF e1 (B+2) cs ds i (FOVar B)
                      ltac:(lia) ltac:(lia) ltac:(lia)
                      ltac:(cbn; lia))).
      cbn [FOeval].
      unfold e1.
      rewrite (FOeval_update_above cs e B vd Hcs).
      rewrite (FOeval_update_above ds e B vd Hds).
      rewrite (FOeval_update_above i e B vd Hi).
      rewrite (FOupdate_eq _ _ _).
      reflexivity. }
    rewrite (FOsat_FOBexC _ (B+6) (FOSucc cr) _ HinB6 HinSB6).
    exists rg. split.
    { cbn [FOeval]. unfold e1.
      rewrite (FOeval_update_above cr e B vd Hcr).
      pose proof (Nat.Div0.mod_le (FOeval e cr)
        ((FOeval e dr) * S j + 1)) as Hmle.
      unfold beta in Hf5. lia. }
    set (e2 := FOupdate e1 (B+6) rg).
    apply (proj2 (FOsat_FOlookup e2 (B+8) ct dt c1 d1 c2 d2 c3 d3 cr
                    dr len (FOnumeral 3) (FOSucc (FOVar B)) FOZero
                    (FOVar B) (FOVar (B+6))
                    Htb8 H3m HSvB HzB HvB HvB6)).
    assert (Hstab : forall t, FOmax_var_tm t < B ->
        FOeval e2 t = FOeval e t).
    { intros t Ht. unfold e2, e1.
      rewrite (FOeval_update_above t _ (B+6) rg ltac:(lia)).
      exact (FOeval_update_above t e B vd Ht). }
    assert (EvB : e2 B = vd).
    { unfold e2, e1.
      rewrite (FOupdate_neq _ (B+6) rg B ltac:(lia)).
      apply FOupdate_eq. }
    assert (EvB6 : e2 (B+6) = rg).
    { unfold e2. apply FOupdate_eq. }
    exists j. split.
    { rewrite (Hstab len Hlen). exact Hj. }
    split.
    { rewrite (Hstab ct Hct), (Hstab dt Hdt), FOeval_numeral.
      exact Hf1. }
    split.
    { cbn [FOeval]. rewrite (Hstab c1 Hc1), (Hstab d1 Hd1'), EvB.
      exact Hf2. }
    split.
    { cbn [FOeval]. rewrite (Hstab c2 Hc2), (Hstab d2 Hd2').
      exact Hf3. }
    split.
    { cbn [FOeval]. rewrite (Hstab c3 Hc3), (Hstab d3 Hd3'), EvB.
      exact Hf4. }
    cbn [FOeval]. rewrite (Hstab cr Hcr), (Hstab dr Hdr), EvB6.
    exact Hf5.
Qed.

Lemma FOsat_FOPRDER : forall e cores,
  (FOsat e (FOPRDER cores) <->
   ((forall vj, vj < e 12 ->
       dispatch_sem
         (tblL (e 2) (e 3) (e 4) (e 5) (e 6) (e 7) (e 8) (e 9)
            (e 10) (e 11) (e 12))
         (e 2) (e 3) (e 4) (e 5) (e 6) (e 7) (e 8) (e 9) (e 10)
         (e 11) vj) /\
    (exists m, e 17 = S m /\ beta (e 13) (e 14) m = e 1) /\
    (forall ii, ii < e 17 ->
       justck_sem
         (tblL (e 2) (e 3) (e 4) (e 5) (e 6) (e 7) (e 8) (e 9)
            (e 10) (e 11) (e 12))
         cores (e 0) (e 13) (e 14) (e 15) (e 16) ii) /\
    (forall ii, ii < e 17 ->
       exists rg,
         tblL (e 2) (e 3) (e 4) (e 5) (e 6) (e 7) (e 8) (e 9)
           (e 10) (e 11) (e 12)
           3 (S (beta (e 13) (e 14) ii)) 0 (beta (e 13) (e 14) ii)
           rg))).
Proof.
  intros e cores.
  assert (Htb18 : tbl_below 18 (FOVar 2) (FOVar 3) (FOVar 4)
            (FOVar 5) (FOVar 6) (FOVar 7) (FOVar 8) (FOVar 9)
            (FOVar 10) (FOVar 11) (FOVar 12))
    by (unfold tbl_below; cbn; lia).
  assert (Htb20 : tbl_below 20 (FOVar 2) (FOVar 3) (FOVar 4)
            (FOVar 5) (FOVar 6) (FOVar 7) (FOVar 8) (FOVar 9)
            (FOVar 10) (FOVar 11) (FOVar 12))
    by (unfold tbl_below; cbn; lia).
  assert (Hin18 : FOin_tm 18 (FOVar 17) = false) by reflexivity.
  assert (HinS18 : FOin_tm 19 (FOVar 17) = false) by reflexivity.
  unfold FOPRDER.
  split.
  - intro H.
    apply (proj1 (FOsat_FOAnd _ _ _)) in H.
    destruct H as [Htv H].
    apply (proj1 (FOsat_FOAnd _ _ _)) in H.
    destruct H as [Hmid H].
    apply (proj1 (FOsat_FOAnd _ _ _)) in H.
    destruct H as [Hball Hguard].
    split.
    { exact (proj1 (FOsat_FOTBLVALID e 18 (FOVar 2) (FOVar 3)
                      (FOVar 4) (FOVar 5) (FOVar 6) (FOVar 7)
                      (FOVar 8) (FOVar 9) (FOVar 10) (FOVar 11)
                      (FOVar 12) Htb18) Htv). }
    split.
    { rewrite (FOsat_FOBexC e 18 (FOVar 17) _ Hin18 HinS18) in Hmid.
      destruct Hmid as [m [Hm Hbody]].
      apply (proj1 (FOsat_FOAnd _ _ _)) in Hbody.
      destruct Hbody as [HEq Hbeta].
      apply (proj1 (FOsat_FObetaF _ 20 (FOVar 13) (FOVar 14)
                      (FOVar 18) (FOVar 1) ltac:(cbn; lia)
                      ltac:(cbn; lia) ltac:(cbn; lia)
                      ltac:(cbn; lia))) in Hbeta.
      exists m. split; [exact HEq | exact Hbeta]. }
    split.
    { intros ii Hii.
      rewrite (FOsat_FOBallC e 18 (FOVar 17) _ Hin18 HinS18) in Hball.
      pose proof (Hball ii Hii) as HJ.
      apply (proj1 (FOsat_FOJUSTCK _ 20 cores (FOVar 2) (FOVar 3)
                      (FOVar 4) (FOVar 5) (FOVar 6) (FOVar 7) (FOVar 8)
                      (FOVar 9) (FOVar 10) (FOVar 11) (FOVar 12)
                      (FOVar 13) (FOVar 14) (FOVar 15) (FOVar 16)
                      (FOVar 18) Htb20 ltac:(cbn; lia) ltac:(cbn; lia)
                      ltac:(cbn; lia) ltac:(cbn; lia)
                      ltac:(cbn; lia))) in HJ.
      exact HJ. }
    intros ii Hii.
    rewrite (FOsat_FOBallC e 18 (FOVar 17) _ Hin18 HinS18) in Hguard.
    pose proof (Hguard ii Hii) as HG.
    apply (proj1 (FOsat_FOGUARDC _ 20 (FOVar 2) (FOVar 3) (FOVar 4)
                    (FOVar 5) (FOVar 6) (FOVar 7) (FOVar 8) (FOVar 9)
                    (FOVar 10) (FOVar 11) (FOVar 12) (FOVar 13)
                    (FOVar 14) (FOVar 18) Htb20 ltac:(cbn; lia)
                    ltac:(cbn; lia) ltac:(cbn; lia))) in HG.
    exact HG.
  - intros [Htv [Hmid [Hball Hguard]]].
    apply (proj2 (FOsat_FOAnd _ _ _)). split.
    { exact (proj2 (FOsat_FOTBLVALID e 18 (FOVar 2) (FOVar 3)
                      (FOVar 4) (FOVar 5) (FOVar 6) (FOVar 7)
                      (FOVar 8) (FOVar 9) (FOVar 10) (FOVar 11)
                      (FOVar 12) Htb18) Htv). }
    apply (proj2 (FOsat_FOAnd _ _ _)). split.
    { rewrite (FOsat_FOBexC e 18 (FOVar 17) _ Hin18 HinS18).
      destruct Hmid as [m [Hm Hbeta]].
      exists m. split; [cbn; lia|].
      apply (proj2 (FOsat_FOAnd _ _ _)). split.
      { exact Hm. }
      apply (proj2 (FOsat_FObetaF _ 20 (FOVar 13) (FOVar 14)
                      (FOVar 18) (FOVar 1) ltac:(cbn; lia)
                      ltac:(cbn; lia) ltac:(cbn; lia)
                      ltac:(cbn; lia))).
      exact Hbeta. }
    apply (proj2 (FOsat_FOAnd _ _ _)). split.
    { rewrite (FOsat_FOBallC e 18 (FOVar 17) _ Hin18 HinS18).
      intros w Hw.
      apply (proj2 (FOsat_FOJUSTCK _ 20 cores (FOVar 2) (FOVar 3)
                      (FOVar 4) (FOVar 5) (FOVar 6) (FOVar 7) (FOVar 8)
                      (FOVar 9) (FOVar 10) (FOVar 11) (FOVar 12)
                      (FOVar 13) (FOVar 14) (FOVar 15) (FOVar 16)
                      (FOVar 18) Htb20 ltac:(cbn; lia) ltac:(cbn; lia)
                      ltac:(cbn; lia) ltac:(cbn; lia)
                      ltac:(cbn; lia))).
      exact (Hball w Hw). }
    rewrite (FOsat_FOBallC e 18 (FOVar 17) _ Hin18 HinS18).
    intros w Hw.
    apply (proj2 (FOsat_FOGUARDC _ 20 (FOVar 2) (FOVar 3) (FOVar 4)
                    (FOVar 5) (FOVar 6) (FOVar 7) (FOVar 8) (FOVar 9)
                    (FOVar 10) (FOVar 11) (FOVar 12) (FOVar 13)
                    (FOVar 14) (FOVar 18) Htb20 ltac:(cbn; lia)
                    ltac:(cbn; lia) ltac:(cbn; lia))).
    exact (Hguard w Hw).
Qed.

Lemma FOsat_FOPRMAT : forall e cores,
  (FOsat e (FOPRMAT cores) <-> provmat_sem cores (e 0) (e 1)).
Proof.
  intros e cores.
  unfold FOPRMAT, provmat_sem.
  cbn [FOsat].
  split.
  - intros [v2 [v3 [v4 [v5 [v6 [v7 [v8 [v9 [v10 [v11 [v12 [v13 [v14
      [v15 [v16 [v17 H]]]]]]]]]]]]]]]].
    apply (proj1 (FOsat_FOPRDER _ cores)) in H.
    exists v2, v3, v4, v5, v6, v7, v8, v9, v10, v11, v12, v13, v14,
      v15, v16, v17.
    exact H.
  - intros [v2 [v3 [v4 [v5 [v6 [v7 [v8 [v9 [v10 [v11 [v12 [v13 [v14
      [v15 [v16 [v17 H]]]]]]]]]]]]]]]].
    exists v2, v3, v4, v5, v6, v7, v8, v9, v10, v11, v12, v13, v14,
      v15, v16, v17.
    apply (proj2 (FOsat_FOPRDER _ cores)).
    exact H.
Qed.

Lemma FOsat_FOProvSentence : forall e n A,
  (FOsat e (FOProvSentence n A) <->
   provmat_sem (FOPrCores n)
     (FOcode_f (FOPRMAT (FOPrCores n))) (FOcode_f A)).
Proof.
  intros e n A.
  unfold FOProvSentence.
  rewrite (FOsat_subst_num _ 1 (FOcode_f A) e).
  rewrite (FOsat_subst_num _ 0
             (FOcode_f (FOPRMAT (FOPrCores n))) _).
  rewrite (FOsat_FOPRMAT _ (FOPrCores n)).
  reflexivity.
Qed.

(** ** Membership and inversion for the derivability recognizers,
    and the indexed cores. *)

Lemma d2s_sem_of : forall L cores c d,
  In c cores -> d2one_sem L c d -> d2s_sem L cores d.
Proof.
  intros L cores c d HIn Hr. revert HIn.
  induction cores as [|c0 rest IH]; cbn [d2s_sem]; intros HIn.
  - destruct HIn.
  - destruct HIn as [->|HIn].
    + left. exact Hr.
    + right. exact (IH HIn).
Qed.

Lemma d2s_sem_in : forall L cores d,
  d2s_sem L cores d -> exists c, In c cores /\ d2one_sem L c d.
Proof.
  intros L cores d.
  induction cores as [|c0 rest IH]; cbn [d2s_sem].
  - intros [].
  - intros [H|H].
    + exists c0. split; [left; reflexivity|exact H].
    + destruct (IH H) as [c [Hin Hr]].
      exists c. split; [right; exact Hin|exact Hr].
Qed.

Lemma d3s_sem_of : forall L cores c d,
  In c cores -> d3one_sem L c d -> d3s_sem L cores d.
Proof.
  intros L cores c d HIn Hr. revert HIn.
  induction cores as [|c0 rest IH]; cbn [d3s_sem]; intros HIn.
  - destruct HIn.
  - destruct HIn as [->|HIn].
    + left. exact Hr.
    + right. exact (IH HIn).
Qed.

Lemma d3s_sem_in : forall L cores d,
  d3s_sem L cores d -> exists c, In c cores /\ d3one_sem L c d.
Proof.
  intros L cores d.
  induction cores as [|c0 rest IH]; cbn [d3s_sem].
  - intros [].
  - intros [H|H].
    + exists c0. split; [left; reflexivity|exact H].
    + destruct (IH H) as [c [Hin Hr]].
      exists c. split; [right; exact Hin|exact Hr].
Qed.

Lemma dmons1_sem_of : forall L c cs c' d,
  In c' cs -> dmonone_sem L c c' d -> dmons1_sem L c cs d.
Proof.
  intros L c cs c' d HIn Hr. revert HIn.
  induction cs as [|c0 rest IH]; cbn [dmons1_sem]; intros HIn.
  - destruct HIn.
  - destruct HIn as [->|HIn].
    + left. exact Hr.
    + right. exact (IH HIn).
Qed.

Lemma dmons1_sem_in : forall L c cs d,
  dmons1_sem L c cs d ->
  exists c', In c' cs /\ dmonone_sem L c c' d.
Proof.
  intros L c cs d.
  induction cs as [|c0 rest IH]; cbn [dmons1_sem].
  - intros [].
  - intros [H|H].
    + exists c0. split; [left; reflexivity|exact H].
    + destruct (IH H) as [c' [Hin Hr]].
      exists c'. split; [right; exact Hin|exact Hr].
Qed.

Lemma dmons_sem_of_nth : forall L cores i i' c c' d,
  nth_error cores i = Some c ->
  nth_error cores i' = Some c' ->
  i <= i' ->
  dmonone_sem L c c' d ->
  dmons_sem L cores d.
Proof.
  intros L cores. revert L.
  induction cores as [|c0 rest IH];
    intros L i i' c c' d Hi Hi' Hle Hr.
  - destruct i; discriminate.
  - cbn [dmons_sem].
    destruct i as [|i0].
    + cbn in Hi. injection Hi as <-.
      left.
      apply (dmons1_sem_of L c0 (c0 :: rest) c' d); [|exact Hr].
      exact (nth_error_In _ _ Hi').
    + destruct i' as [|i0']; [lia|].
      cbn in Hi, Hi'.
      right.
      exact (IH L i0 i0' c c' d Hi Hi' ltac:(lia) Hr).
Qed.

Lemma dmons_sem_in_nth : forall L cores d,
  dmons_sem L cores d ->
  exists i i' c c', i <= i' /\
    nth_error cores i = Some c /\
    nth_error cores i' = Some c' /\
    dmonone_sem L c c' d.
Proof.
  intros L cores d.
  induction cores as [|c0 rest IH]; cbn [dmons_sem].
  - intros [].
  - intros [H|H].
    + destruct (dmons1_sem_in L c0 (c0 :: rest) d H)
        as [c' [HIn Hr]].
      destruct (In_nth_error _ _ HIn) as [i' Hi'].
      exists 0, i', c0, c'.
      split; [lia|]. split; [reflexivity|].
      split; [exact Hi'|exact Hr].
    + destruct (IH H) as [i [i' [c [c' [Hle [Hi [Hi' Hr]]]]]]].
      exists (S i), (S i'), c, c'.
      split; [lia|]. split; [exact Hi|].
      split; [exact Hi'|exact Hr].
Qed.

Lemma FOPrCores_length : forall n, length (FOPrCores n) = n.
Proof.
  induction n as [|n IH]; cbn [FOPrCores].
  - reflexivity.
  - rewrite length_app, IH. cbn [length]. lia.
Qed.

Lemma FOPrCores_nth : forall n k c,
  nth_error (FOPrCores n) k = Some c ->
  k < n /\
  c = FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
        (FOPRMAT (FOPrCores k))).
Proof.
  induction n as [|n IH]; intros k c Hc; cbn [FOPrCores] in Hc.
  - destruct k; discriminate.
  - destruct (Nat.lt_ge_cases k n) as [Hk|Hk].
    + rewrite nth_error_app1 in Hc
        by (rewrite FOPrCores_length; exact Hk).
      destruct (IH k c Hc) as [Hk' Hc'].
      split; [lia|exact Hc'].
    + rewrite nth_error_app2 in Hc
        by (rewrite FOPrCores_length; exact Hk).
      rewrite FOPrCores_length in Hc.
      destruct (Nat.eq_dec k n) as [->|Hne].
      * rewrite Nat.sub_diag in Hc. cbn [nth_error] in Hc.
        apply (f_equal (fun o => match o with
                                 | Some z => z
                                 | None => 0 end)) in Hc.
        split; [lia|exact (eq_sym Hc)].
      * destruct (k - n) as [|m] eqn:Em; [lia|].
        cbn [nth_error] in Hc. destruct m; cbn [nth_error] in Hc;
          discriminate.
Qed.

Lemma FOPrCores_nth_of : forall n k,
  k < n ->
  nth_error (FOPrCores n) k
  = Some (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
            (FOPRMAT (FOPrCores k)))).
Proof.
  induction n as [|n IH]; intros k Hk; [lia|].
  cbn [FOPrCores].
  destruct (Nat.lt_ge_cases k n) as [Hkn|Hkn].
  - rewrite nth_error_app1
      by (rewrite FOPrCores_length; exact Hkn).
    exact (IH k Hkn).
  - assert (k = n) by lia. subst k.
    rewrite nth_error_app2
      by (rewrite FOPrCores_length; lia).
    rewrite FOPrCores_length, Nat.sub_diag.
    reflexivity.
Qed.

(** ** Decoding an accepted matrix into a tower derivation.

    With the entry-code guard, every track entry of an accepted
    derivation is a genuine formula code, so a strong induction over
    positions converts each justified entry into an [FOProvesTn]
    derivation: shape disjuncts decode through the [FOdecode] shape
    equations, table rows convert through [tbl_sound]'s per-tag
    specification, and the substitution witness supplies the
    instantiating term for the quantifier axioms. *)

Lemma FOPrCores_in : forall n c,
  In c (FOPrCores n) ->
  exists k, k < n /\
    c = FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                    (FOPRMAT (FOPrCores k))).
Proof.
  induction n as [|n IH]; intros c Hc; cbn [FOPrCores] in Hc.
  - destruct Hc.
  - apply in_app_or in Hc. destruct Hc as [Hc|Hc].
    + destruct (IH c Hc) as [k [Hk Hck]].
      exists k. split; [lia|exact Hck].
    + destruct Hc as [<-|[]].
      exists n. split; [lia|reflexivity].
Qed.

Lemma refls_sem_in : forall L cores d,
  refls_sem L cores d ->
  exists c, In c cores /\ refl_sem L c d.
Proof.
  intros L cores d.
  induction cores as [|c0 rest IH]; cbn [refls_sem].
  - intros [].
  - intros [H|H].
    + exists c0. split; [left; reflexivity|exact H].
    + destruct (IH H) as [c [Hin Hr]].
      exists c. split; [right; exact Hin|exact Hr].
Qed.

Ltac decode_shape H :=
  do 3 (rewrite ?FOdecode_f_impl, ?FOdecode_f_eq,
    ?FOdecode_f_false, ?FOdecode_f_forall, ?FOdecode_f_exists,
    ?FOdecode_tm_succ, ?FOdecode_tm_plus, ?FOdecode_tm_mult,
    ?FOdecode_tm_var, ?FOdecode_tm_zero in H).

Theorem provmat_decode : forall n A,
  provmat_sem (FOPrCores n) (FOcode_f (FOPRMAT (FOPrCores n)))
    (FOcode_f A) ->
  FOProvesTn n A.
Proof.
  intros n A Hpm.
  destruct Hpm as [vct [vdt [vc1 [vd1 [vc2 [vd2 [vc3 [vd3 [vcr [vdr
    [vlen [vcs [vds [vcj [vdj [vdlen
    [Hdisp [Hlast [Hjust Hguard]]]]]]]]]]]]]]]]]]].
  assert (MAIN : forall m i, i < m -> i < vdlen ->
      forall B, beta vcs vds i = FOcode_f B -> FOProvesTn n B).
  { induction m as [|m IHm].
    { intros; lia. }
    intros i Him Hivd B HA.
    pose proof (Hjust i Hivd) as HJ.
    unfold justck_sem in HJ.
    destruct HJ as [vd [vj [tg [pl [Hvd [Hvj [Hcpv Hsw]]]]]]].
    assert (Evd : vd = FOcode_f B) by congruence.
    clear Hvd. subst vd.
    destruct Hsw as
      [[_ Hth]|[[_ Hlog]|[[_ Hj2]|[[_ Hj3]|[[_ Hj4]|[[_ Hj5]
        |[[_ Hj6]|[[_ Hj7]|[[_ Hj8]|[[_ Hj9]|[_ Hj10]]]]]]]]]]].
    - (* theory axiom *)
      unfold thax_sem in Hth. destruct Hth as [Haxq|Hrefl].
      + unfold axq_sem in Haxq.
        destruct Haxq as [Hq|[Hq|[Hq|[Hq|[Hq|[Hq|Hq]]]]]].
        * destruct Hq as [a [b Hsh]].
          pose proof (FOdecode_code_f B) as HD.
          rewrite Hsh in HD. decode_shape HD.
          rewrite <- HD.
          apply FOProvesTn_ax, FOAx_RQ, RQ_S_inj.
        * destruct Hq as [a Hsh].
          pose proof (FOdecode_code_f B) as HD.
          rewrite Hsh in HD. decode_shape HD.
          rewrite <- HD.
          apply FOProvesTn_ax, FOAx_RQ, RQ_S_nonzero.
        * destruct Hq as [x Hsh].
          pose proof (FOdecode_code_f B) as HD.
          rewrite Hsh in HD. decode_shape HD.
          rewrite <- HD.
          apply FOProvesTn_ax, FOAx_RQ, RQ_zero_or_succ.
        * destruct Hq as [a Hsh].
          pose proof (FOdecode_code_f B) as HD.
          rewrite Hsh in HD. decode_shape HD.
          rewrite <- HD.
          apply FOProvesTn_ax, FOAx_RQ, RQ_plus_zero.
        * destruct Hq as [a [b Hsh]].
          pose proof (FOdecode_code_f B) as HD.
          rewrite Hsh in HD. decode_shape HD.
          rewrite <- HD.
          apply FOProvesTn_ax, FOAx_RQ, RQ_plus_succ.
        * destruct Hq as [a Hsh].
          pose proof (FOdecode_code_f B) as HD.
          rewrite Hsh in HD. decode_shape HD.
          rewrite <- HD.
          apply FOProvesTn_ax, FOAx_RQ, RQ_mult_zero.
        * destruct Hq as [a [b Hsh]].
          pose proof (FOdecode_code_f B) as HD.
          rewrite Hsh in HD. decode_shape HD.
          rewrite <- HD.
          apply FOProvesTn_ax, FOAx_RQ, RQ_mult_succ.
      + apply refls_sem_in in Hrefl.
        destruct Hrefl as [c [HcIn Hrf]].
        destruct (FOPrCores_in n c HcIn) as [k [Hk Hc]].
        unfold refl_sem in Hrf.
        destruct Hrf as [aa [na [p [H5 [H3 Hsh]]]]].
        destruct B as [a0 b0| |A1 A2|y0 B0|y0 B0];
          cbn [FOcode_f] in Hsh;
          apply cpair_inj in Hsh; destruct Hsh as [Esh Hsh];
          try discriminate Esh.
        apply cpair_inj in Hsh. destruct Hsh as [Hp Ha].
        subst p aa.
        pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                      5 (FOcode_f A2) 0 0 na H5) as M5.
        cbn [mspec] in M5.
        pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                      3 1 na c (FOcode_f A1) H3) as M3.
        cbn [mspec] in M3.
        specialize (M3 (FOnumeral (FOcode_f A2))
          (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
             (FOPRMAT (FOPrCores k))) M5 Hc).
        rewrite FOsubst_f_num in M3.
        apply FOcode_f_inj in M3.
        subst A1.
        apply FOProvesTn_ax.
        exact (FOAx_Refl n k A2 Hk).
    - (* logical axiom *)
      unfold logax_sem in Hlog.
      destruct Hlog as
        [HL|[HL|[HL|[HL|[HL|[HL|[HL|[HL|[HL|[HL|[HL|HL]]]]]]]]]]].
      + destruct HL as [P [Q Hsh]].
        pose proof (FOdecode_code_f B) as HD.
        rewrite Hsh in HD. decode_shape HD.
        rewrite <- HD. apply FOProvesTn_K.
      + destruct HL as [P [Q [R Hsh]]].
        pose proof (FOdecode_code_f B) as HD.
        rewrite Hsh in HD. decode_shape HD.
        rewrite <- HD. apply FOProvesTn_S.
      + destruct HL as [P Hsh].
        pose proof (FOdecode_code_f B) as HD.
        rewrite Hsh in HD. decode_shape HD.
        rewrite <- HD. apply FOProvesTn_DN.
      + destruct HL as [aq Hsh].
        pose proof (FOdecode_code_f B) as HD.
        rewrite Hsh in HD. decode_shape HD.
        rewrite <- HD. apply FOProvesTn_EqRefl.
      + destruct HL as [aq [bq Hsh]].
        pose proof (FOdecode_code_f B) as HD.
        rewrite Hsh in HD. decode_shape HD.
        rewrite <- HD. apply FOProvesTn_EqSym.
      + destruct HL as [aq [bq [cq Hsh]]].
        pose proof (FOdecode_code_f B) as HD.
        rewrite Hsh in HD. decode_shape HD.
        rewrite <- HD. apply FOProvesTn_EqTrans.
      + destruct HL as [aq [bq Hsh]].
        pose proof (FOdecode_code_f B) as HD.
        rewrite Hsh in HD. decode_shape HD.
        rewrite <- HD. apply FOProvesTn_CongS.
      + destruct HL as [aq [bq [cq [dq Hsh]]]].
        pose proof (FOdecode_code_f B) as HD.
        rewrite Hsh in HD. decode_shape HD.
        rewrite <- HD. apply FOProvesTn_CongPlus.
      + destruct HL as [aq [bq [cq [dq Hsh]]]].
        pose proof (FOdecode_code_f B) as HD.
        rewrite Hsh in HD. decode_shape HD.
        rewrite <- HD. apply FOProvesTn_CongMult.
      + destruct HL as [x [P [Q [Hsh HLrow]]]].
        destruct B as [a0 b0| |A1 A2|y0 B0|y0 B0];
          cbn [FOcode_f] in Hsh;
          apply cpair_inj in Hsh; destruct Hsh as [Esh Hsh];
          try discriminate Esh.
        apply cpair_inj in Hsh. destruct Hsh as [Hsh1 Hsh2].
        destruct A1 as [a0 b0| |C1 C2|y1 B1|y1 B1];
          cbn [FOcode_f] in Hsh1;
          apply cpair_inj in Hsh1; destruct Hsh1 as [Esh1 Hsh1];
          try discriminate Esh1.
        apply cpair_inj in Hsh1. destruct Hsh1 as [Ey1 Hsh1].
        subst y1.
        destruct B1 as [a0 b0| |P1 Q1|y2 B2|y2 B2];
          cbn [FOcode_f] in Hsh1;
          apply cpair_inj in Hsh1; destruct Hsh1 as [Esh1b Hsh1];
          try discriminate Esh1b.
        apply cpair_inj in Hsh1. destruct Hsh1 as [HP HQ].
        subst P Q.
        destruct A2 as [a0 b0| |C1 C2|y3 B3|y3 B3];
          cbn [FOcode_f] in Hsh2;
          apply cpair_inj in Hsh2; destruct Hsh2 as [Esh2 Hsh2];
          try discriminate Esh2.
        apply cpair_inj in Hsh2. destruct Hsh2 as [Hsh2a Hsh2b].
        destruct C1 as [a0 b0| |D1 D2|y4 B4|y4 B4];
          cbn [FOcode_f] in Hsh2a;
          apply cpair_inj in Hsh2a; destruct Hsh2a as [Esh2a Hsh2a];
          try discriminate Esh2a.
        apply cpair_inj in Hsh2a. destruct Hsh2a as [Ey4 Hsh2a].
        subst y4.
        apply FOcode_f_inj in Hsh2a. subst B4.
        apply FOcode_f_inj in Hsh2b. subst C2.
        pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                      1 x (FOcode_f Q1) 0 0 HLrow) as M1.
        cbn [mspec] in M1.
        specialize (M1 Q1 eq_refl).
        destruct (FOfree_in x Q1) eqn:EF; [discriminate M1|].
        apply FOProvesTn_ExElim. exact EF.
      + destruct HL as [x [P [Q Hsh]]].
        pose proof (FOdecode_code_f B) as HD.
        rewrite Hsh in HD. decode_shape HD.
        rewrite <- HD. apply FOProvesTn_AllK.
      + destruct HL as [x [P [Q [Hsh HLrow]]]].
        destruct B as [a0 b0| |A1 A2|y0 B0|y0 B0];
          cbn [FOcode_f] in Hsh;
          apply cpair_inj in Hsh; destruct Hsh as [Esh Hsh];
          try discriminate Esh.
        apply cpair_inj in Hsh. destruct Hsh as [Hsh1 Hsh2].
        destruct A1 as [a0 b0| |C1 C2|y1 B1|y1 B1];
          cbn [FOcode_f] in Hsh1;
          apply cpair_inj in Hsh1; destruct Hsh1 as [Esh1 Hsh1];
          try discriminate Esh1.
        apply cpair_inj in Hsh1. destruct Hsh1 as [Ey1 Hsh1].
        subst y1.
        destruct B1 as [a0 b0| |P1 Q1|y2 B2|y2 B2];
          cbn [FOcode_f] in Hsh1;
          apply cpair_inj in Hsh1; destruct Hsh1 as [Esh1b Hsh1];
          try discriminate Esh1b.
        apply cpair_inj in Hsh1. destruct Hsh1 as [HP HQ].
        subst P Q.
        destruct A2 as [a0 b0| |C1 C2|y3 B3|y3 B3];
          cbn [FOcode_f] in Hsh2;
          apply cpair_inj in Hsh2; destruct Hsh2 as [Esh2 Hsh2];
          try discriminate Esh2.
        apply cpair_inj in Hsh2. destruct Hsh2 as [Hsh2a Hsh2b].
        apply FOcode_f_inj in Hsh2a. subst C1.
        destruct C2 as [a0 b0| |D1 D2|y4 B4|y4 B4];
          cbn [FOcode_f] in Hsh2b;
          apply cpair_inj in Hsh2b; destruct Hsh2b as [Esh2b Hsh2b];
          try discriminate Esh2b.
        apply cpair_inj in Hsh2b. destruct Hsh2b as [Ey4 Hsh2b].
        subst y4.
        apply FOcode_f_inj in Hsh2b. subst B4.
        pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                      1 x (FOcode_f P1) 0 0 HLrow) as M1.
        cbn [mspec] in M1.
        specialize (M1 P1 eq_refl).
        destruct (FOfree_in x P1) eqn:EF; [discriminate M1|].
        apply FOProvesTn_AllExport. exact EF.
    - (* forall-elimination *)
      destruct Hj2 as [x [tc [P [Q [Hpl [Hsh [HL4 HL3]]]]]]].
      destruct B as [a0 b0| |A1 A2|y0 B0|y0 B0];
        cbn [FOcode_f] in Hsh;
        apply cpair_inj in Hsh; destruct Hsh as [Esh Hsh];
        try discriminate Esh.
      apply cpair_inj in Hsh. destruct Hsh as [Hsh1 Hsh2].
      destruct A1 as [a0 b0| |C1 C2|y1 P1|y1 P1];
        cbn [FOcode_f] in Hsh1;
        apply cpair_inj in Hsh1; destruct Hsh1 as [Esh1 Hsh1];
        try discriminate Esh1.
      apply cpair_inj in Hsh1. destruct Hsh1 as [Ey1 HP1].
      subst y1 P Q.
      destruct (tbl_subst_f_witness _ _ _ _ _ _ _ _ _ _ _ Hdisp
                  P1 A2 x tc HL3) as [[Hnf HQP]|[s Hs]].
      + apply FOcode_f_inj in HQP. subst A2.
        pose proof (FOProvesTn_AllElimT n x FOZero P1
                      (FOsubst_ok_numeral P1 x 0)) as HAE.
        rewrite (FOsubst_f_not_free P1 x FOZero Hnf) in HAE.
        exact HAE.
      + pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                      4 x tc (FOcode_f P1) 1 HL4) as M4.
        cbn [mspec] in M4.
        specialize (M4 s P1 Hs eq_refl).
        destruct (FOsubst_ok x s P1) eqn:EOK; [|discriminate M4].
        pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                      3 x tc (FOcode_f P1) (FOcode_f A2) HL3) as M3.
        cbn [mspec] in M3.
        specialize (M3 s P1 Hs eq_refl).
        apply FOcode_f_inj in M3. subst A2.
        apply FOProvesTn_AllElimT. exact EOK.
    - (* exists-introduction *)
      destruct Hj3 as [x [tc [P [Q [Hpl [Hsh [HL4 HL3]]]]]]].
      destruct B as [a0 b0| |A1 A2|y0 B0|y0 B0];
        cbn [FOcode_f] in Hsh;
        apply cpair_inj in Hsh; destruct Hsh as [Esh Hsh];
        try discriminate Esh.
      apply cpair_inj in Hsh. destruct Hsh as [Hsh1 Hsh2].
      destruct A2 as [a0 b0| |C1 C2|y1 P1|y1 P1];
        cbn [FOcode_f] in Hsh2;
        apply cpair_inj in Hsh2; destruct Hsh2 as [Esh2 Hsh2];
        try discriminate Esh2.
      apply cpair_inj in Hsh2. destruct Hsh2 as [Ey1 HP1].
      subst y1 P Q.
      destruct (tbl_subst_f_witness _ _ _ _ _ _ _ _ _ _ _ Hdisp
                  P1 A1 x tc HL3) as [[Hnf HQP]|[s Hs]].
      + apply FOcode_f_inj in HQP. subst A1.
        pose proof (FOProvesTn_ExIntroT n x FOZero P1
                      (FOsubst_ok_numeral P1 x 0)) as HAE.
        rewrite (FOsubst_f_not_free P1 x FOZero Hnf) in HAE.
        exact HAE.
      + pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                      4 x tc (FOcode_f P1) 1 HL4) as M4.
        cbn [mspec] in M4.
        specialize (M4 s P1 Hs eq_refl).
        destruct (FOsubst_ok x s P1) eqn:EOK; [|discriminate M4].
        pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                      3 x tc (FOcode_f P1) (FOcode_f A1) HL3) as M3.
        cbn [mspec] in M3.
        specialize (M3 s P1 Hs eq_refl).
        apply FOcode_f_inj in M3. subst A1.
        apply FOProvesTn_ExIntroT. exact EOK.
    - (* modus ponens *)
      destruct Hj4 as [i' [j' [bi [bj [Hpl [Hii' [Hjj' [Hbi [Hbj
        Hsh]]]]]]]]].
      pose proof (Hguard i' ltac:(lia)) as [rgi Hrowi].
      rewrite Hbi in Hrowi.
      destruct (tbl_genuine_f _ _ _ _ _ _ _ _ _ _ _ Hdisp
                  _ _ _ _ Hrowi (Nat.lt_succ_diag_r bi)) as [Bi EBi].
      pose proof (Hguard j' ltac:(lia)) as [rgj Hrowj].
      rewrite Hbj in Hrowj.
      destruct (tbl_genuine_f _ _ _ _ _ _ _ _ _ _ _ Hdisp
                  _ _ _ _ Hrowj (Nat.lt_succ_diag_r bj)) as [Bj EBj].
      rewrite EBi, EBj in Hsh.
      assert (EBi2 : Bi = FOImplF Bj B).
      { apply FOcode_f_inj. cbn [FOcode_f]. exact Hsh. }
      apply (FOProvesTn_MP n Bj B).
      + assert (PBi : FOProvesTn n Bi).
        { apply (IHm i' ltac:(lia) ltac:(lia)). congruence. }
        rewrite EBi2 in PBi. exact PBi.
      + apply (IHm j' ltac:(lia) ltac:(lia)). congruence.
    - (* generalization *)
      destruct Hj5 as [Hpli [bb [x [Hbb Hsh]]]].
      pose proof (Hguard pl ltac:(lia)) as [rgb Hrowb].
      rewrite Hbb in Hrowb.
      destruct (tbl_genuine_f _ _ _ _ _ _ _ _ _ _ _ Hdisp
                  _ _ _ _ Hrowb (Nat.lt_succ_diag_r bb)) as [Bb EBb].
      rewrite EBb in Hsh.
      assert (EA : B = FOForall x Bb).
      { apply FOcode_f_inj. cbn [FOcode_f]. exact Hsh. }
      rewrite EA.
      apply FOProvesTn_Gen.
      apply (IHm pl ltac:(lia) ltac:(lia)). congruence.
    - (* Loeb *)
      destruct Hj6 as [Hpli [bj [nu [core [na [p [Hbj [H5u [H3c [H5a
        [H3p Hsh]]]]]]]]]]].
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    5 (FOcode_f (FOPRMAT (FOPrCores n))) 0 0 nu H5u)
        as M5u.
      cbn [mspec] in M5u.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 0 nu (FOcode_f (FOPRMAT (FOPrCores n))) core
                    H3c) as M3c.
      cbn [mspec] in M3c.
      specialize (M3c (FOnumeral (FOcode_f (FOPRMAT (FOPrCores n))))
                    (FOPRMAT (FOPrCores n)) M5u eq_refl).
      rewrite FOsubst_f_num in M3c.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    5 (FOcode_f B) 0 0 na H5a) as M5a.
      cbn [mspec] in M5a.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 1 na core p H3p) as M3p.
      cbn [mspec] in M3p.
      specialize (M3p (FOnumeral (FOcode_f B))
                    (FOsubst_num 0
                       (FOcode_f (FOPRMAT (FOPrCores n)))
                       (FOPRMAT (FOPrCores n))) M5a M3c).
      rewrite FOsubst_f_num in M3p.
      pose proof (Hguard pl ltac:(lia)) as [rgb Hrowb].
      rewrite Hbj in Hrowb.
      destruct (tbl_genuine_f _ _ _ _ _ _ _ _ _ _ _ Hdisp
                  _ _ _ _ Hrowb (Nat.lt_succ_diag_r bj)) as [Bj EBj].
      rewrite EBj in Hsh.
      rewrite M3p in Hsh.
      assert (EBj2 : Bj = FOImplF
        (FOsubst_num 1 (FOcode_f B)
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores n)))
              (FOPRMAT (FOPrCores n)))) B).
      { apply FOcode_f_inj. cbn [FOcode_f]. exact Hsh. }
      apply FOProvesTn_Loeb.
      assert (PBj : FOProvesTn n Bj).
      { apply (IHm pl ltac:(lia) ltac:(lia)). congruence. }
      rewrite EBj2 in PBj. exact PBj.
    - (* formalized D2 *)
      destruct (d2s_sem_in _ _ _ Hj7) as [c [HcIn Hone]].
      destruct (FOPrCores_in n c HcIn) as [k [Hk Hc]].
      subst c.
      destruct Hone as [x [y [pixy [px [py [G1 [G2 [R1 [R2 [R3
        Hsh]]]]]]]]]].
      destruct G1 as [rgx Hrowx].
      destruct (tbl_genuine_f _ _ _ _ _ _ _ _ _ _ _ Hdisp
                  _ _ _ _ Hrowx (Nat.lt_succ_diag_r x)) as [X EX].
      destruct G2 as [rgy Hrowy].
      destruct (tbl_genuine_f _ _ _ _ _ _ _ _ _ _ _ Hdisp
                  _ _ _ _ Hrowy (Nat.lt_succ_diag_r y)) as [Y EY].
      subst x y.
      destruct R1 as [nixy [R1a R1b]].
      destruct R2 as [nx [R2a R2b]].
      destruct R3 as [ny [R3a R3b]].
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    5 (cpair 2 (cpair (FOcode_f X) (FOcode_f Y)))
                    0 0 nixy R1a) as M5i.
      cbn [mspec] in M5i.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 1 nixy
                    (FOcode_f (FOsubst_num 0
                       (FOcode_f (FOPRMAT (FOPrCores k)))
                       (FOPRMAT (FOPrCores k)))) pixy R1b) as M3i.
      cbn [mspec] in M3i.
      specialize (M3i
        (FOnumeral (cpair 2 (cpair (FOcode_f X) (FOcode_f Y))))
        (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
           (FOPRMAT (FOPrCores k))) M5i eq_refl).
      rewrite FOsubst_f_num in M3i.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    5 (FOcode_f X) 0 0 nx R2a) as M5x.
      cbn [mspec] in M5x.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 1 nx
                    (FOcode_f (FOsubst_num 0
                       (FOcode_f (FOPRMAT (FOPrCores k)))
                       (FOPRMAT (FOPrCores k)))) px R2b) as M3x.
      cbn [mspec] in M3x.
      specialize (M3x (FOnumeral (FOcode_f X))
        (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
           (FOPRMAT (FOPrCores k))) M5x eq_refl).
      rewrite FOsubst_f_num in M3x.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    5 (FOcode_f Y) 0 0 ny R3a) as M5y.
      cbn [mspec] in M5y.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 1 ny
                    (FOcode_f (FOsubst_num 0
                       (FOcode_f (FOPRMAT (FOPrCores k)))
                       (FOPRMAT (FOPrCores k)))) py R3b) as M3y.
      cbn [mspec] in M3y.
      specialize (M3y (FOnumeral (FOcode_f Y))
        (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
           (FOPRMAT (FOPrCores k))) M5y eq_refl).
      rewrite FOsubst_f_num in M3y.
      rewrite M3i, M3x, M3y in Hsh.
      assert (EB : B = FOImplF
        (FOsubst_num 1 (cpair 2 (cpair (FOcode_f X) (FOcode_f Y)))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
              (FOPRMAT (FOPrCores k))))
        (FOImplF
           (FOsubst_num 1 (FOcode_f X)
              (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                 (FOPRMAT (FOPrCores k))))
           (FOsubst_num 1 (FOcode_f Y)
              (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                 (FOPRMAT (FOPrCores k)))))).
      { apply FOcode_f_inj. cbn [FOcode_f]. exact Hsh. }
      rewrite EB.
      exact (FOProvesTn_ax n _ (FOAx_D2 n k X Y Hk)).
    - (* formalized D3 *)
      destruct (d3s_sem_in _ _ _ Hj8) as [c [HcIn Hone]].
      destruct (FOPrCores_in n c HcIn) as [k [Hk Hc]].
      subst c.
      destruct Hone as [a [pa [ppa [G1 [R1 [R2 Hsh]]]]]].
      destruct G1 as [rga Hrowa].
      destruct (tbl_genuine_f _ _ _ _ _ _ _ _ _ _ _ Hdisp
                  _ _ _ _ Hrowa (Nat.lt_succ_diag_r a)) as [A0 EA].
      subst a.
      destruct R1 as [na [R1a R1b]].
      destruct R2 as [npa [R2a R2b]].
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    5 (FOcode_f A0) 0 0 na R1a) as M5a.
      cbn [mspec] in M5a.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 1 na
                    (FOcode_f (FOsubst_num 0
                       (FOcode_f (FOPRMAT (FOPrCores k)))
                       (FOPRMAT (FOPrCores k)))) pa R1b) as M3a.
      cbn [mspec] in M3a.
      specialize (M3a (FOnumeral (FOcode_f A0))
        (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
           (FOPRMAT (FOPrCores k))) M5a eq_refl).
      rewrite FOsubst_f_num in M3a.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    5 pa 0 0 npa R2a) as M5p.
      cbn [mspec] in M5p.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 1 npa
                    (FOcode_f (FOsubst_num 0
                       (FOcode_f (FOPRMAT (FOPrCores k)))
                       (FOPRMAT (FOPrCores k)))) ppa R2b) as M3p.
      cbn [mspec] in M3p.
      specialize (M3p (FOnumeral pa)
        (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
           (FOPRMAT (FOPrCores k))) M5p eq_refl).
      rewrite FOsubst_f_num in M3p.
      rewrite M3a in M3p.
      rewrite M3a, M3p in Hsh.
      assert (EB : B = FOImplF
        (FOsubst_num 1 (FOcode_f A0)
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
              (FOPRMAT (FOPrCores k))))
        (FOsubst_num 1
           (FOcode_f (FOsubst_num 1 (FOcode_f A0)
              (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                 (FOPRMAT (FOPrCores k)))))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
              (FOPRMAT (FOPrCores k))))).
      { apply FOcode_f_inj. cbn [FOcode_f]. exact Hsh. }
      rewrite EB.
      exact (FOProvesTn_ax n _ (FOAx_D3 n k A0 Hk)).
    - (* formalized monotonicity *)
      destruct (dmons_sem_in_nth _ _ _ Hj9)
        as [i1 [i2 [c [c' [Hle [Hic [Hic' Hone]]]]]]].
      destruct (FOPrCores_nth n i1 c Hic) as [Hk1 Hc1].
      destruct (FOPrCores_nth n i2 c' Hic') as [Hk2 Hc2].
      subst c c'.
      destruct Hone as [a [p [p' [G1 [R1 [R2 Hsh]]]]]].
      destruct G1 as [rga Hrowa].
      destruct (tbl_genuine_f _ _ _ _ _ _ _ _ _ _ _ Hdisp
                  _ _ _ _ Hrowa (Nat.lt_succ_diag_r a)) as [A0 EA].
      subst a.
      destruct R1 as [na [R1a R1b]].
      destruct R2 as [na' [R2a R2b]].
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    5 (FOcode_f A0) 0 0 na R1a) as M5a.
      cbn [mspec] in M5a.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 1 na
                    (FOcode_f (FOsubst_num 0
                       (FOcode_f (FOPRMAT (FOPrCores i1)))
                       (FOPRMAT (FOPrCores i1)))) p R1b) as M3a.
      cbn [mspec] in M3a.
      specialize (M3a (FOnumeral (FOcode_f A0))
        (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores i1)))
           (FOPRMAT (FOPrCores i1))) M5a eq_refl).
      rewrite FOsubst_f_num in M3a.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    5 (FOcode_f A0) 0 0 na' R2a) as M5a'.
      cbn [mspec] in M5a'.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 1 na'
                    (FOcode_f (FOsubst_num 0
                       (FOcode_f (FOPRMAT (FOPrCores i2)))
                       (FOPRMAT (FOPrCores i2)))) p' R2b) as M3a'.
      cbn [mspec] in M3a'.
      specialize (M3a' (FOnumeral (FOcode_f A0))
        (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores i2)))
           (FOPRMAT (FOPrCores i2))) M5a' eq_refl).
      rewrite FOsubst_f_num in M3a'.
      rewrite M3a, M3a' in Hsh.
      assert (EB : B = FOImplF
        (FOsubst_num 1 (FOcode_f A0)
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores i1)))
              (FOPRMAT (FOPrCores i1))))
        (FOsubst_num 1 (FOcode_f A0)
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores i2)))
              (FOPRMAT (FOPrCores i2))))).
      { apply FOcode_f_inj. cbn [FOcode_f]. exact Hsh. }
      rewrite EB.
      exact (FOProvesTn_ax n _ (FOAx_DMon n i1 i2 A0 Hle Hk2)).
    - (* induction schema *)
      destruct Hj10 as [x [PA [C0 [SS [_ [Hsh [_ [HL3b [_ HL3s]]]]]]]]].
      destruct B as [a0 b0| |B1 B2|y0 B0|y0 B0];
        cbn [FOcode_f] in Hsh;
        apply cpair_inj in Hsh; destruct Hsh as [Esh Hsh];
        try discriminate Esh.
      apply cpair_inj in Hsh. destruct Hsh as [HB1 Hsh].
      destruct B2 as [a0 b0| |B21 B22|y0 B0|y0 B0];
        cbn [FOcode_f] in Hsh;
        apply cpair_inj in Hsh; destruct Hsh as [Esh2 Hsh];
        try discriminate Esh2.
      apply cpair_inj in Hsh. destruct Hsh as [HB21 HB22].
      destruct B21 as [a0 b0| |C1 C2|y1 B21b|y1 B21b];
        cbn [FOcode_f] in HB21;
        apply cpair_inj in HB21; destruct HB21 as [E21 HB21];
        try discriminate E21.
      apply cpair_inj in HB21. destruct HB21 as [Ey1 HB21]. subst y1.
      destruct B21b as [a0 b0| |B21b1 B21b2|y0 B0|y0 B0];
        cbn [FOcode_f] in HB21;
        apply cpair_inj in HB21; destruct HB21 as [E21b HB21];
        try discriminate E21b.
      apply cpair_inj in HB21. destruct HB21 as [HB21b1 HB21b2].
      destruct B22 as [a0 b0| |C1 C2|y2 B22b|y2 B22b];
        cbn [FOcode_f] in HB22;
        apply cpair_inj in HB22; destruct HB22 as [E22 HB22];
        try discriminate E22.
      apply cpair_inj in HB22. destruct HB22 as [Ey2 HB22]. subst y2.
      assert (EA : B21b1 = B22b)
        by (apply FOcode_f_inj; rewrite HB21b1, HB22; reflexivity).
      subst B21b1.
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 x (cpair 1 0) PA C0 HL3b) as M3b.
      cbn [mspec] in M3b.
      specialize (M3b FOZero B22b eq_refl (eq_sym HB22)).
      pose proof (tbl_sound _ _ _ _ _ _ _ _ _ _ _ Hdisp
                    3 x (cpair 2 (cpair 0 x)) PA SS HL3s) as M3s.
      cbn [mspec] in M3s.
      specialize (M3s (FOSucc (FOVar x)) B22b eq_refl (eq_sym HB22)).
      assert (EB1 : B1 = FOsubst_f x FOZero B22b)
        by (apply FOcode_f_inj; rewrite HB1; exact M3b).
      assert (EB21b2 : B21b2 = FOsubst_f x (FOSucc (FOVar x)) B22b)
        by (apply FOcode_f_inj; rewrite HB21b2; exact M3s).
      subst B1 B21b2.
      exact (FOProvesTn_ax n _ (FOAx_Ind n x B22b)). }
  destruct Hlast as [m [Hvdlen Hbeta]].
  apply (MAIN (S m) m); [lia | rewrite Hvdlen; lia | exact Hbeta].
Qed.

(** ** Encoding a derivation as a justified entry list.

    Each sequence entry contributes its entry-code guard trace and
    the computation rows its justification consults: substitution and
    capture traces for the quantifier axioms, freeness traces for the
    side-conditioned logical axioms, numeral and self-substitution
    traces for the reflection axioms and the Loeb rule. *)

Definition jcode (j : FOjust) : nat :=
  match j with
  | J_thax => cpair 0 0
  | J_log => cpair 1 0
  | J_AllElim x t => cpair 2 (cpair x (FOcode_tm t))
  | J_ExIntro x t => cpair 3 (cpair x (FOcode_tm t))
  | J_MP i j' => cpair 4 (cpair i j')
  | J_Gen i => cpair 5 i
  | J_Loeb i => cpair 6 i
  | J_d2 k X Y => cpair 7 (cpair k (cpair (FOcode_f X) (FOcode_f Y)))
  | J_d3 k X => cpair 8 (cpair k (FOcode_f X))
  | J_dmon k k' X => cpair 9 (cpair k (cpair k' (FOcode_f X)))
  | J_ind x X => cpair 10 (cpair x (FOcode_f X))
  end.

Definition jrows (n : nat) (B : FOFormula) (j : FOjust)
    : list TEntry :=
  match j with
  | J_thax =>
      match B with
      | FOImplF P C =>
          concat (map (fun k =>
            trace5 (FOcode_f C)
            ++ trace3 1 (FOnumeral (FOcode_f C))
                 (FOsubst_num 0
                    (FOcode_f (FOPRMAT (FOPrCores k)))
                    (FOPRMAT (FOPrCores k)))) (seq 0 n))
      | _ => []
      end
  | J_log =>
      match B with
      | FOImplF (FOForall x (FOImplF P Q)) _ =>
          trace1 x Q ++ trace1 x P
      | _ => []
      end
  | J_AllElim x t =>
      match B with
      | FOImplF (FOForall _ P) _ => trace4 x t P ++ trace3 x t P
      | _ => []
      end
  | J_ExIntro x t =>
      match B with
      | FOImplF _ (FOExists _ P) => trace4 x t P ++ trace3 x t P
      | _ => []
      end
  | J_MP _ _ => []
  | J_Gen _ => []
  | J_Loeb _ =>
      trace5 (FOcode_f (FOPRMAT (FOPrCores n)))
      ++ trace3 0 (FOnumeral (FOcode_f (FOPRMAT (FOPrCores n))))
           (FOPRMAT (FOPrCores n))
      ++ trace5 (FOcode_f B)
      ++ trace3 1 (FOnumeral (FOcode_f B))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores n)))
              (FOPRMAT (FOPrCores n)))
  | J_d2 k X Y =>
      trace3 (S (FOcode_f X)) (FOVar 0) X
      ++ trace3 (S (FOcode_f Y)) (FOVar 0) Y
      ++ trace5 (FOcode_f (FOImplF X Y))
      ++ trace3 1 (FOnumeral (FOcode_f (FOImplF X Y)))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
              (FOPRMAT (FOPrCores k)))
      ++ trace5 (FOcode_f X)
      ++ trace3 1 (FOnumeral (FOcode_f X))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
              (FOPRMAT (FOPrCores k)))
      ++ trace5 (FOcode_f Y)
      ++ trace3 1 (FOnumeral (FOcode_f Y))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
              (FOPRMAT (FOPrCores k)))
  | J_d3 k X =>
      trace3 (S (FOcode_f X)) (FOVar 0) X
      ++ trace5 (FOcode_f X)
      ++ trace3 1 (FOnumeral (FOcode_f X))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
              (FOPRMAT (FOPrCores k)))
      ++ trace5 (FOcode_f (FOProvSentence k X))
      ++ trace3 1 (FOnumeral (FOcode_f (FOProvSentence k X)))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
              (FOPRMAT (FOPrCores k)))
  | J_dmon k k' X =>
      trace3 (S (FOcode_f X)) (FOVar 0) X
      ++ trace5 (FOcode_f X)
      ++ trace3 1 (FOnumeral (FOcode_f X))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
              (FOPRMAT (FOPrCores k)))
      ++ trace3 1 (FOnumeral (FOcode_f X))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k')))
              (FOPRMAT (FOPrCores k')))
  | J_ind x X =>
      trace4 x FOZero X ++ trace3 x FOZero X
      ++ trace4 x (FOSucc (FOVar x)) X
      ++ trace3 x (FOSucc (FOVar x)) X
  end.

Fixpoint seqrows (n : nat) (items : list (FOFormula * FOjust))
    : list TEntry :=
  match items with
  | [] => []
  | (B, j) :: rest =>
      trace3 (S (FOcode_f B)) (FOVar 0) B
      ++ jrows n B j ++ seqrows n rest
  end.

Lemma incl_concat_member : forall (X : Type) (l : list X) ll,
  In l ll -> incl l (concat ll).
Proof.
  intros X l ll HIn x Hx.
  induction ll as [|l0 rest IH]; cbn [concat].
  - destruct HIn.
  - destruct HIn as [->|HIn].
    + apply in_or_app. left. exact Hx.
    + apply in_or_app. right. exact (IH HIn).
Qed.

Opaque FOPRMAT.

Lemma reflrows_one_ok : forall C k L,
  incl (trace5 (FOcode_f C)
        ++ trace3 1 (FOnumeral (FOcode_f C))
             (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                (FOPRMAT (FOPrCores k)))) L ->
  forall e,
    In e (trace5 (FOcode_f C)
          ++ trace3 1 (FOnumeral (FOcode_f C))
               (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                  (FOPRMAT (FOPrCores k)))) ->
    entry_ok L e.
Proof.
  intros C k L Hincl e HeIn.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  - exact (trace5_ok _ L (incl_app_head _ _ _ _ Hincl) e HeIn).
  - exact (trace3_ok _ _ _ L (incl_app_tail _ _ _ _ Hincl) e HeIn).
Qed.

Lemma jrows_ok_thax : forall n C L,
  incl (concat (map (fun k =>
    trace5 (FOcode_f C)
    ++ trace3 1 (FOnumeral (FOcode_f C))
         (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
            (FOPRMAT (FOPrCores k)))) (seq 0 n))) L ->
  forall e,
    In e (concat (map (fun k =>
      trace5 (FOcode_f C)
      ++ trace3 1 (FOnumeral (FOcode_f C))
           (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
              (FOPRMAT (FOPrCores k)))) (seq 0 n))) ->
    entry_ok L e.
Proof.
  intros n C L Hincl e HeIn.
  apply in_concat in HeIn.
  destruct HeIn as [l [Hl HeIn]].
  apply in_map_iff in Hl.
  destruct Hl as [k [<- Hk]].
  apply (reflrows_one_ok C k L); [|exact HeIn].
  apply incl_tran with (2 := Hincl).
  apply incl_concat_member.
  apply in_map_iff.
  exists k. split; [reflexivity|exact Hk].
Qed.

Lemma jrows_ok_free : forall x P Q L,
  incl (trace1 x Q ++ trace1 x P) L ->
  forall e, In e (trace1 x Q ++ trace1 x P) -> entry_ok L e.
Proof.
  intros x P Q L Hincl e HeIn.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  - exact (trace1_ok _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn).
  - exact (trace1_ok _ _ L (incl_app_tail _ _ _ _ Hincl) e HeIn).
Qed.

Lemma jrows_ok_subst : forall x t P L,
  incl (trace4 x t P ++ trace3 x t P) L ->
  forall e, In e (trace4 x t P ++ trace3 x t P) -> entry_ok L e.
Proof.
  intros x t P L Hincl e HeIn.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  - exact (trace4_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn).
  - exact (trace3_ok _ _ _ L (incl_app_tail _ _ _ _ Hincl) e HeIn).
Qed.

Lemma jrows_ok_loeb : forall n B L,
  incl (trace5 (FOcode_f (FOPRMAT (FOPrCores n)))
        ++ trace3 0 (FOnumeral (FOcode_f (FOPRMAT (FOPrCores n))))
             (FOPRMAT (FOPrCores n))
        ++ trace5 (FOcode_f B)
        ++ trace3 1 (FOnumeral (FOcode_f B))
             (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores n)))
                (FOPRMAT (FOPrCores n)))) L ->
  forall e,
    In e (trace5 (FOcode_f (FOPRMAT (FOPrCores n)))
          ++ trace3 0 (FOnumeral (FOcode_f (FOPRMAT (FOPrCores n))))
               (FOPRMAT (FOPrCores n))
          ++ trace5 (FOcode_f B)
          ++ trace3 1 (FOnumeral (FOcode_f B))
               (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores n)))
                  (FOPRMAT (FOPrCores n)))) ->
    entry_ok L e.
Proof.
  intros n B L Hincl e HeIn.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  - exact (trace5_ok _ L (incl_app_head _ _ _ _ Hincl) e HeIn).
  - apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
    + exact (trace3_ok _ _ _ L
               (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl))
               e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
      * exact (trace5_ok _ L
                 (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _
                    (incl_app_tail _ _ _ _ Hincl))) e HeIn).
      * exact (trace3_ok _ _ _ L
                 (incl_app_tail _ _ _ _ (incl_app_tail _ _ _ _
                    (incl_app_tail _ _ _ _ Hincl))) e HeIn).
Qed.

Lemma jrows_ok_nil : forall (L : list TEntry) e,
  In e (@nil TEntry) -> entry_ok L e.
Proof.
  intros L e HeIn. destruct HeIn.
Qed.

Lemma jrows_ok_d2 : forall k X Y L,
  incl (trace3 (S (FOcode_f X)) (FOVar 0) X
        ++ trace3 (S (FOcode_f Y)) (FOVar 0) Y
        ++ trace5 (FOcode_f (FOImplF X Y))
        ++ trace3 1 (FOnumeral (FOcode_f (FOImplF X Y)))
             (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                (FOPRMAT (FOPrCores k)))
        ++ trace5 (FOcode_f X)
        ++ trace3 1 (FOnumeral (FOcode_f X))
             (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                (FOPRMAT (FOPrCores k)))
        ++ trace5 (FOcode_f Y)
        ++ trace3 1 (FOnumeral (FOcode_f Y))
             (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                (FOPRMAT (FOPrCores k)))) L ->
  forall e,
    In e (trace3 (S (FOcode_f X)) (FOVar 0) X
          ++ trace3 (S (FOcode_f Y)) (FOVar 0) Y
          ++ trace5 (FOcode_f (FOImplF X Y))
          ++ trace3 1 (FOnumeral (FOcode_f (FOImplF X Y)))
               (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                  (FOPRMAT (FOPrCores k)))
          ++ trace5 (FOcode_f X)
          ++ trace3 1 (FOnumeral (FOcode_f X))
               (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                  (FOPRMAT (FOPrCores k)))
          ++ trace5 (FOcode_f Y)
          ++ trace3 1 (FOnumeral (FOcode_f Y))
               (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                  (FOPRMAT (FOPrCores k)))) ->
    entry_ok L e.
Proof.
  intros k X Y L Hincl e HeIn.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace3_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace3_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace5_ok _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace3_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace5_ok _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace3_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace5_ok _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  exact (trace3_ok _ _ _ L Hincl e HeIn).
Qed.

Lemma jrows_ok_d3 : forall k X L,
  incl (trace3 (S (FOcode_f X)) (FOVar 0) X
        ++ trace5 (FOcode_f X)
        ++ trace3 1 (FOnumeral (FOcode_f X))
             (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                (FOPRMAT (FOPrCores k)))
        ++ trace5 (FOcode_f (FOProvSentence k X))
        ++ trace3 1 (FOnumeral (FOcode_f (FOProvSentence k X)))
             (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                (FOPRMAT (FOPrCores k)))) L ->
  forall e,
    In e (trace3 (S (FOcode_f X)) (FOVar 0) X
          ++ trace5 (FOcode_f X)
          ++ trace3 1 (FOnumeral (FOcode_f X))
               (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                  (FOPRMAT (FOPrCores k)))
          ++ trace5 (FOcode_f (FOProvSentence k X))
          ++ trace3 1 (FOnumeral (FOcode_f (FOProvSentence k X)))
               (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                  (FOPRMAT (FOPrCores k)))) ->
    entry_ok L e.
Proof.
  intros k X L Hincl e HeIn.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace3_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace5_ok _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace3_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace5_ok _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  exact (trace3_ok _ _ _ L Hincl e HeIn).
Qed.

Lemma jrows_ok_dmon : forall k k' X L,
  incl (trace3 (S (FOcode_f X)) (FOVar 0) X
        ++ trace5 (FOcode_f X)
        ++ trace3 1 (FOnumeral (FOcode_f X))
             (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                (FOPRMAT (FOPrCores k)))
        ++ trace3 1 (FOnumeral (FOcode_f X))
             (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k')))
                (FOPRMAT (FOPrCores k')))) L ->
  forall e,
    In e (trace3 (S (FOcode_f X)) (FOVar 0) X
          ++ trace5 (FOcode_f X)
          ++ trace3 1 (FOnumeral (FOcode_f X))
               (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                  (FOPRMAT (FOPrCores k)))
          ++ trace3 1 (FOnumeral (FOcode_f X))
               (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k')))
                  (FOPRMAT (FOPrCores k')))) ->
    entry_ok L e.
Proof.
  intros k k' X L Hincl e HeIn.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace3_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace5_ok _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
  { exact (trace3_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
  apply incl_app_tail in Hincl.
  exact (trace3_ok _ _ _ L Hincl e HeIn).
Qed.

Lemma jrows_ok : forall n B j L,
  incl (jrows n B j) L ->
  forall e, In e (jrows n B j) -> entry_ok L e.
Proof.
  intros n B j L Hincl e HeIn.
  destruct j as [| | x t | x t | i j' | i | i | k X Y | k X | k k' X | x X].
  - destruct B as [a b| |P C|y B0|y B0]; try destruct HeIn.
    exact (jrows_ok_thax n C L Hincl e HeIn).
  - destruct B as [a b| |P C|y B0|y B0]; try destruct HeIn.
    destruct P as [a b| |P1 Q1|y P0|y P0]; try destruct HeIn.
    destruct P0 as [a b| |P1 Q1|y2 B2|y2 B2]; try destruct HeIn.
    exact (jrows_ok_free y P1 Q1 L Hincl e HeIn).
  - destruct B as [a b| |P C|y B0|y B0]; try destruct HeIn.
    destruct P as [a b| |P1 Q1|y P0|y P0]; try destruct HeIn.
    exact (jrows_ok_subst x t P0 L Hincl e HeIn).
  - destruct B as [a b| |P C|y B0|y B0]; try destruct HeIn.
    destruct C as [a b| |P1 Q1|y P0|y P0]; try destruct HeIn.
    exact (jrows_ok_subst x t P0 L Hincl e HeIn).
  - exact (jrows_ok_nil L e HeIn).
  - exact (jrows_ok_nil L e HeIn).
  - cbv beta iota delta [jrows] in Hincl, HeIn.
    exact (jrows_ok_loeb n B L Hincl e HeIn).
  - cbv beta iota delta [jrows] in Hincl, HeIn.
    exact (jrows_ok_d2 k X Y L Hincl e HeIn).
  - cbv beta iota delta [jrows] in Hincl, HeIn.
    exact (jrows_ok_d3 k X L Hincl e HeIn).
  - cbv beta iota delta [jrows] in Hincl, HeIn.
    exact (jrows_ok_dmon k k' X L Hincl e HeIn).
  - cbv beta iota delta [jrows] in Hincl, HeIn.
    apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
    { exact (trace4_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn). }
    apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
    { exact (trace3_ok _ _ _ L
               (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl))
               e HeIn). }
    apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
    { exact (trace4_ok _ _ _ L
               (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _
                  (incl_app_tail _ _ _ _ Hincl))) e HeIn). }
    exact (trace3_ok _ _ _ L
             (incl_app_tail _ _ _ _ (incl_app_tail _ _ _ _
                (incl_app_tail _ _ _ _ Hincl))) e HeIn).
Qed.

Transparent FOPRMAT.

Lemma seqrows_ok : forall n items L,
  incl (seqrows n items) L ->
  forall e, In e (seqrows n items) -> entry_ok L e.
Proof.
  intros n items.
  induction items as [|[B j] rest IH]; intros L Hincl e HeIn;
    cbn [seqrows] in HeIn.
  - destruct HeIn.
  - apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
    + cbn [seqrows] in Hincl.
      exact (trace3_ok _ _ _ L (incl_app_head _ _ _ _ Hincl) e HeIn).
    + apply in_app_or in HeIn. destruct HeIn as [HeIn|HeIn].
      * cbn [seqrows] in Hincl.
        exact (jrows_ok n B j L
                 (incl_app_head _ _ _ _ (incl_app_tail _ _ _ _ Hincl))
                 e HeIn).
      * cbn [seqrows] in Hincl.
        exact (IH L
                 (incl_app_tail _ _ _ _ (incl_app_tail _ _ _ _ Hincl))
                 e HeIn).
Qed.

Lemma seqrows_guard_in : forall n items B j e,
  In (B, j) items ->
  In e (trace3 (S (FOcode_f B)) (FOVar 0) B) ->
  In e (seqrows n items).
Proof.
  intros n items B j e HIn He. revert HIn.
  induction items as [|[B0 j0] rest IH]; intros HIn;
    [destruct HIn|].
  cbn [seqrows].
  destruct HIn as [Heq|HIn].
  - injection Heq as -> ->.
    apply in_or_app. left. exact He.
  - apply in_or_app. right. apply in_or_app. right.
    exact (IH HIn).
Qed.

Lemma seqrows_jrows_in : forall n items B j e,
  In (B, j) items ->
  In e (jrows n B j) ->
  In e (seqrows n items).
Proof.
  intros n items B j e HIn He. revert HIn.
  induction items as [|[B0 j0] rest IH]; intros HIn;
    [destruct HIn|].
  cbn [seqrows].
  destruct HIn as [Heq|HIn].
  - injection Heq as -> ->.
    apply in_or_app. right. apply in_or_app. left. exact He.
  - apply in_or_app. right. apply in_or_app. right.
    exact (IH HIn).
Qed.

Lemma FORobinsonQ_axq : forall B,
  FORobinsonQ B -> axq_sem (FOcode_f B).
Proof.
  intros B HQ. unfold axq_sem.
  destruct HQ as [a b|a|x|a|a b|a|a b];
    unfold FONeg; cbn [FOcode_f FOcode_tm].
  - left. exists (FOcode_tm a), (FOcode_tm b). reflexivity.
  - right; left. exists (FOcode_tm a). reflexivity.
  - do 2 right; left. exists x. reflexivity.
  - do 3 right; left. exists (FOcode_tm a). reflexivity.
  - do 4 right; left. exists (FOcode_tm a), (FOcode_tm b).
    reflexivity.
  - do 5 right; left. exists (FOcode_tm a). reflexivity.
  - do 6 right. exists (FOcode_tm a), (FOcode_tm b). reflexivity.
Qed.

Lemma FOPrCores_in_of : forall n k,
  k < n ->
  In (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
        (FOPRMAT (FOPrCores k)))) (FOPrCores n).
Proof.
  induction n as [|n IH]; intros k Hk.
  - lia.
  - cbn [FOPrCores]. apply in_or_app.
    destruct (Nat.eq_dec k n) as [->|Hne].
    + right. left. reflexivity.
    + left. apply IH. lia.
Qed.

Lemma refls_sem_of : forall L cores c d,
  In c cores -> refl_sem L c d -> refls_sem L cores d.
Proof.
  intros L cores c d HIn Hr. revert HIn.
  induction cores as [|c0 rest IH]; cbn [refls_sem]; intros HIn.
  - destruct HIn.
  - destruct HIn as [->|HIn].
    + left. exact Hr.
    + right. exact (IH HIn).
Qed.

(** ** Encoding: from an accepted sequence to the matrix semantics.

    Position extraction from the boolean acceptance, resolution of
    backward references, and the per-justification witnesses against
    the realized table. *)

Lemma FOseq_check_nth : forall axb PrF maxk items done i B j,
  FOseq_check axb PrF maxk done items = true ->
  nth_error items i = Some (B, j) ->
  FOentry_check axb PrF maxk (done ++ map fst (firstn i items)) B j
  = true.
Proof.
  intros axb PrF maxk items.
  induction items as [|[A0 j0] rest IH]; intros done i B j Hck Hnth.
  - destruct i; discriminate.
  - cbn [FOseq_check] in Hck. apply andb_prop in Hck.
    destruct Hck as [He Hrest].
    destruct i as [|i'].
    + cbn in Hnth. injection Hnth as -> ->.
      cbn [firstn map]. rewrite app_nil_r. exact He.
    + cbn [nth_error] in Hnth.
      cbn [firstn map fst].
      specialize (IH (done ++ [A0]) i' B j Hrest Hnth).
      rewrite <- app_assoc in IH. exact IH.
Qed.

Lemma FOseq_check_nth0 : forall axb PrF maxk items i B j,
  FOseq_check axb PrF maxk [] items = true ->
  nth_error items i = Some (B, j) ->
  FOentry_check axb PrF maxk (map fst (firstn i items)) B j = true.
Proof.
  intros axb PrF maxk items i B j Hck Hnth.
  exact (FOseq_check_nth axb PrF maxk items [] i B j Hck Hnth).
Qed.

Lemma prev_nth_resolve : forall (items : list (FOFormula * FOjust)) ii i' AB,
  nth_error (map fst (firstn ii items)) i' = Some AB ->
  i' < ii /\ exists j0, nth_error items i' = Some (AB, j0).
Proof.
  intros items ii i' AB H.
  rewrite nth_error_map in H.
  rewrite nth_error_firstn in H.
  destruct (i' <? ii) eqn:Hlt; [|discriminate].
  apply Nat.ltb_lt in Hlt.
  destruct (nth_error items i') as [[A0 j0]|]; [|discriminate].
  cbn in H. injection H as ->.
  split; [exact Hlt|]. exists j0. reflexivity.
Qed.

Opaque FOPRMAT.

Lemma justck_thax : forall (L : nat -> nat -> nat -> nat -> nat -> Prop)
    n items B,
  (forall tg a1 a2 a3 r,
     In (mkTE tg a1 a2 a3 r) (seqrows n items) -> L tg a1 a2 a3 r) ->
  In (B, J_thax) items ->
  FOaxb n B = true ->
  thax_sem L (FOPrCores n) (FOcode_f B).
Proof.
  intros L n items B Hsub HIn Hax.
  unfold FOaxb in Hax. apply Bool.orb_true_iff in Hax.
  destruct Hax as [Hrq|Hrefl].
  - left. exact (FORobinsonQ_axq B (FOis_RQ_sound B Hrq)).
  - right.
    destruct B as [a b | | P C | x B0 | x B0]; try discriminate.
    cbn [FOreflb] in Hrefl.
    apply existsb_exists in Hrefl.
    destruct Hrefl as [k [Hk Heqb]].
    apply in_seq in Hk.
    apply FOform_eqb_eq in Heqb. subst P.
    apply (refls_sem_of _ _
      (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
         (FOPRMAT (FOPrCores k)))) _).
    + apply FOPrCores_in_of. lia.
    + exists (FOcode_f C), (FOcode_tm (FOnumeral (FOcode_f C))),
        (FOcode_f (FOProvSentence k C)).
      split; [|split].
      * apply Hsub.
        apply (seqrows_jrows_in n items _ J_thax _ HIn).
        cbv beta iota delta [jrows].
        apply in_concat.
        exists (trace5 (FOcode_f C)
                ++ trace3 1 (FOnumeral (FOcode_f C))
                     (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                        (FOPRMAT (FOPrCores k)))).
        split.
        { apply in_map_iff. exists k. split; [reflexivity|].
          apply in_seq. lia. }
        apply in_or_app. left. apply trace5_seed. reflexivity.
      * apply Hsub.
        apply (seqrows_jrows_in n items _ J_thax _ HIn).
        cbv beta iota delta [jrows].
        apply in_concat.
        exists (trace5 (FOcode_f C)
                ++ trace3 1 (FOnumeral (FOcode_f C))
                     (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
                        (FOPRMAT (FOPrCores k)))).
        split.
        { apply in_map_iff. exists k. split; [reflexivity|].
          apply in_seq. lia. }
        apply in_or_app. right. apply trace3_seed.
        unfold FOProvSentence. rewrite FOsubst_f_num. reflexivity.
      * reflexivity.
Qed.

Lemma justck_log : forall (L : nat -> nat -> nat -> nat -> nat -> Prop)
    n items B,
  (forall tg a1 a2 a3 r,
     In (mkTE tg a1 a2 a3 r) (seqrows n items) -> L tg a1 a2 a3 r) ->
  In (B, J_log) items ->
  FOis_logical_axiom B = true ->
  logax_sem L (FOcode_f B).
Proof.
  intros L n items B Hsub HIn Hax.
  unfold FOis_logical_axiom in Hax.
  repeat (apply Bool.orb_true_iff in Hax;
          destruct Hax as [Hax|Hax]).
  - destruct (FOis_K_shape B Hax) as [P [Q HB]]. subst B.
    left. exists (FOcode_f P), (FOcode_f Q). reflexivity.
  - destruct (FOis_S_shape B Hax) as [P [Q [R HB]]]. subst B.
    right; left.
    exists (FOcode_f P), (FOcode_f Q), (FOcode_f R). reflexivity.
  - destruct (FOis_DN_shape B Hax) as [P HB]. subst B.
    do 2 right; left. exists (FOcode_f P). reflexivity.
  - destruct (FOis_EqRefl_shape B Hax) as [t HB]. subst B.
    do 3 right; left. exists (FOcode_tm t). reflexivity.
  - destruct (FOis_EqSym_shape B Hax) as [a [b HB]]. subst B.
    do 4 right; left.
    exists (FOcode_tm a), (FOcode_tm b). reflexivity.
  - destruct (FOis_EqTrans_shape B Hax) as [a [b [c HB]]]. subst B.
    do 5 right; left.
    exists (FOcode_tm a), (FOcode_tm b), (FOcode_tm c). reflexivity.
  - destruct (FOis_CongS_shape B Hax) as [a [b HB]]. subst B.
    do 6 right; left.
    exists (FOcode_tm a), (FOcode_tm b). reflexivity.
  - destruct (FOis_CongPlus_shape B Hax) as [a [b [c [d HB]]]]. subst B.
    do 7 right; left.
    exists (FOcode_tm a), (FOcode_tm b), (FOcode_tm c), (FOcode_tm d).
    reflexivity.
  - destruct (FOis_CongMult_shape B Hax) as [a [b [c [d HB]]]]. subst B.
    do 8 right; left.
    exists (FOcode_tm a), (FOcode_tm b), (FOcode_tm c), (FOcode_tm d).
    reflexivity.
  - destruct (FOis_ExElim_shape B Hax) as [x [P [Q [HB Hf]]]]. subst B.
    do 9 right; left.
    exists x, (FOcode_f P), (FOcode_f Q).
    split; [reflexivity|].
    apply Hsub.
    apply (seqrows_jrows_in n items _ J_log _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. left. apply trace1_seed.
    rewrite Hf. reflexivity.
  - destruct (FOis_AllK_shape B Hax) as [y [P [Q HB]]]. subst B.
    do 10 right; left.
    exists y, (FOcode_f P), (FOcode_f Q). reflexivity.
  - destruct (FOis_AllExport_shape B Hax) as [y [Hh [R [HB Hf]]]]. subst B.
    do 11 right.
    exists y, (FOcode_f Hh), (FOcode_f R).
    split; [reflexivity|].
    apply Hsub.
    apply (seqrows_jrows_in n items _ J_log _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. right. apply trace1_seed.
    rewrite Hf. reflexivity.
Qed.

Lemma justck_allelim : forall (L : nat -> nat -> nat -> nat -> nat -> Prop)
    n items B x t,
  (forall tg a1 a2 a3 r,
     In (mkTE tg a1 a2 a3 r) (seqrows n items) -> L tg a1 a2 a3 r) ->
  In (B, J_AllElim x t) items ->
  FOis_AllElim x t B = true ->
  exists P Q,
    FOcode_f B = cpair 2 (cpair (cpair 3 (cpair x P)) Q)
    /\ L 4 x (FOcode_tm t) P 1
    /\ L 3 x (FOcode_tm t) P Q.
Proof.
  intros L n items B x t Hsub HIn Hck.
  destruct B as [a b | | L0 Q0 | y B0 | y B0]; try discriminate.
  destruct L0 as [a b | | P0 C0 | x' P | y B0]; try discriminate.
  cbn in Hck.
  apply Bool.andb_true_iff in Hck. destruct Hck as [Hck HQ].
  apply Bool.andb_true_iff in Hck. destruct Hck as [Hx Hok].
  apply Nat.eqb_eq in Hx. subst x'.
  apply FOform_eqb_eq in HQ.
  exists (FOcode_f P), (FOcode_f Q0).
  split; [reflexivity|].
  split.
  - apply Hsub.
    apply (seqrows_jrows_in n items _ (J_AllElim x t) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. left. apply trace4_seed.
    rewrite Hok. reflexivity.
  - apply Hsub.
    apply (seqrows_jrows_in n items _ (J_AllElim x t) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. right. apply trace3_seed.
    rewrite HQ. reflexivity.
Qed.

Lemma justck_exintro : forall (L : nat -> nat -> nat -> nat -> nat -> Prop)
    n items B x t,
  (forall tg a1 a2 a3 r,
     In (mkTE tg a1 a2 a3 r) (seqrows n items) -> L tg a1 a2 a3 r) ->
  In (B, J_ExIntro x t) items ->
  FOis_ExIntro x t B = true ->
  exists P Q,
    FOcode_f B = cpair 2 (cpair Q (cpair 4 (cpair x P)))
    /\ L 4 x (FOcode_tm t) P 1
    /\ L 3 x (FOcode_tm t) P Q.
Proof.
  intros L n items B x t Hsub HIn Hck.
  destruct B as [a b | | Q0 R0 | y B0 | y B0]; try discriminate.
  destruct R0 as [a b | | P0 C0 | y B0 | x' P]; try discriminate.
  cbn in Hck.
  apply Bool.andb_true_iff in Hck. destruct Hck as [Hck HQ].
  apply Bool.andb_true_iff in Hck. destruct Hck as [Hx Hok].
  apply Nat.eqb_eq in Hx. subst x'.
  apply FOform_eqb_eq in HQ.
  exists (FOcode_f P), (FOcode_f Q0).
  split; [reflexivity|].
  split.
  - apply Hsub.
    apply (seqrows_jrows_in n items _ (J_ExIntro x t) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. left. apply trace4_seed.
    rewrite Hok. reflexivity.
  - apply Hsub.
    apply (seqrows_jrows_in n items _ (J_ExIntro x t) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. right. apply trace3_seed.
    rewrite HQ. reflexivity.
Qed.

Lemma justck_loeb_rows : forall
    (L : nat -> nat -> nat -> nat -> nat -> Prop) n items B i,
  (forall tg a1 a2 a3 r,
     In (mkTE tg a1 a2 a3 r) (seqrows n items) -> L tg a1 a2 a3 r) ->
  In (B, J_Loeb i) items ->
  exists nu core na p,
    L 5 (FOcode_f (FOPRMAT (FOPrCores n))) 0 0 nu
    /\ L 3 0 nu (FOcode_f (FOPRMAT (FOPrCores n))) core
    /\ L 5 (FOcode_f B) 0 0 na
    /\ L 3 1 na core p
    /\ p = FOcode_f (FOProvSentence n B).
Proof.
  intros L n items B i Hsub HIn.
  exists (FOcode_tm (FOnumeral (FOcode_f (FOPRMAT (FOPrCores n))))),
    (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores n)))
       (FOPRMAT (FOPrCores n)))),
    (FOcode_tm (FOnumeral (FOcode_f B))),
    (FOcode_f (FOProvSentence n B)).
  split; [|split; [|split; [|split]]].
  - apply Hsub.
    apply (seqrows_jrows_in n items B (J_Loeb i) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. left. apply trace5_seed. reflexivity.
  - apply Hsub.
    apply (seqrows_jrows_in n items B (J_Loeb i) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. right. apply in_or_app. left.
    apply trace3_seed. rewrite FOsubst_f_num. reflexivity.
  - apply Hsub.
    apply (seqrows_jrows_in n items B (J_Loeb i) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. right. apply in_or_app. right.
    apply in_or_app. left.
    apply trace5_seed. reflexivity.
  - apply Hsub.
    apply (seqrows_jrows_in n items B (J_Loeb i) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. right. apply in_or_app. right.
    apply in_or_app. right.
    apply trace3_seed.
    unfold FOProvSentence. rewrite FOsubst_f_num. reflexivity.
  - reflexivity.
Qed.

Lemma justck_genuine_row : forall
    (L : nat -> nat -> nat -> nat -> nat -> Prop) n items B j X,
  (forall tg a1 a2 a3 r,
     In (mkTE tg a1 a2 a3 r) (seqrows n items) -> L tg a1 a2 a3 r) ->
  In (B, j) items ->
  (forall e, In e (trace3 (S (FOcode_f X)) (FOVar 0) X) ->
     In e (jrows n B j)) ->
  genuine_sem L (FOcode_f X).
Proof.
  intros L n items B j X Hsub HIn Hchunk.
  exists (FOcode_f (FOsubst_f (S (FOcode_f X)) (FOVar 0) X)).
  apply Hsub.
  apply (seqrows_jrows_in n items B j _ HIn).
  apply Hchunk.
  pose proof (trace3_seed (S (FOcode_f X)) (FOVar 0) X
      (FOcode_f (FOsubst_f (S (FOcode_f X)) (FOVar 0) X))
      eq_refl) as Hrow.
  change (FOcode_tm (FOVar 0)) with 0 in Hrow.
  exact Hrow.
Qed.

Lemma justck_d2_rows : forall
    (L : nat -> nat -> nat -> nat -> nat -> Prop) n items k X Y,
  (forall tg a1 a2 a3 r,
     In (mkTE tg a1 a2 a3 r) (seqrows n items) -> L tg a1 a2 a3 r) ->
  In (FOImplF (FOProvSentence k (FOImplF X Y))
        (FOImplF (FOProvSentence k X) (FOProvSentence k Y)),
      J_d2 k X Y) items ->
  d2one_sem L
    (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
       (FOPRMAT (FOPrCores k))))
    (FOcode_f (FOImplF (FOProvSentence k (FOImplF X Y))
        (FOImplF (FOProvSentence k X) (FOProvSentence k Y)))).
Proof.
  intros L n items k X Y Hsub HIn.
  exists (FOcode_f X), (FOcode_f Y),
    (FOcode_f (FOProvSentence k (FOImplF X Y))),
    (FOcode_f (FOProvSentence k X)),
    (FOcode_f (FOProvSentence k Y)).
  split.
  { apply (justck_genuine_row L n items _ _ X Hsub HIn).
    intros e He.
    cbv beta iota delta [jrows].
    apply in_or_app. left. exact He. }
  split.
  { apply (justck_genuine_row L n items _ _ Y Hsub HIn).
    intros e He.
    cbv beta iota delta [jrows].
    apply in_or_app. right. apply in_or_app. left. exact He. }
  split.
  { exists (FOcode_tm (FOnumeral
      (cpair 2 (cpair (FOcode_f X) (FOcode_f Y))))).
    split.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_d2 k X Y) _ HIn).
      cbv beta iota delta [jrows].
      apply in_or_app. right. apply in_or_app. right.
      apply in_or_app. left.
      apply trace5_seed. reflexivity.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_d2 k X Y) _ HIn).
      cbv beta iota delta [jrows].
      apply in_or_app. right. apply in_or_app. right.
      apply in_or_app. right. apply in_or_app. left.
      apply trace3_seed.
      unfold FOProvSentence. rewrite FOsubst_f_num. reflexivity. }
  split.
  { exists (FOcode_tm (FOnumeral (FOcode_f X))).
    split.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_d2 k X Y) _ HIn).
      cbv beta iota delta [jrows].
      do 4 (apply in_or_app; right). apply in_or_app. left.
      apply trace5_seed. reflexivity.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_d2 k X Y) _ HIn).
      cbv beta iota delta [jrows].
      do 5 (apply in_or_app; right). apply in_or_app. left.
      apply trace3_seed.
      unfold FOProvSentence. rewrite FOsubst_f_num. reflexivity. }
  split.
  { exists (FOcode_tm (FOnumeral (FOcode_f Y))).
    split.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_d2 k X Y) _ HIn).
      cbv beta iota delta [jrows].
      do 6 (apply in_or_app; right). apply in_or_app. left.
      apply trace5_seed. reflexivity.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_d2 k X Y) _ HIn).
      cbv beta iota delta [jrows].
      do 7 (apply in_or_app; right).
      apply trace3_seed.
      unfold FOProvSentence. rewrite FOsubst_f_num. reflexivity. }
  reflexivity.
Qed.

Lemma justck_d3_rows : forall
    (L : nat -> nat -> nat -> nat -> nat -> Prop) n items k X,
  (forall tg a1 a2 a3 r,
     In (mkTE tg a1 a2 a3 r) (seqrows n items) -> L tg a1 a2 a3 r) ->
  In (FOImplF (FOProvSentence k X)
        (FOProvSentence k (FOProvSentence k X)),
      J_d3 k X) items ->
  d3one_sem L
    (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
       (FOPRMAT (FOPrCores k))))
    (FOcode_f (FOImplF (FOProvSentence k X)
        (FOProvSentence k (FOProvSentence k X)))).
Proof.
  intros L n items k X Hsub HIn.
  exists (FOcode_f X),
    (FOcode_f (FOProvSentence k X)),
    (FOcode_f (FOProvSentence k (FOProvSentence k X))).
  split.
  { apply (justck_genuine_row L n items _ _ X Hsub HIn).
    intros e He.
    cbv beta iota delta [jrows].
    apply in_or_app. left. exact He. }
  split.
  { exists (FOcode_tm (FOnumeral (FOcode_f X))).
    split.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_d3 k X) _ HIn).
      cbv beta iota delta [jrows].
      apply in_or_app. right. apply in_or_app. left.
      apply trace5_seed. reflexivity.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_d3 k X) _ HIn).
      cbv beta iota delta [jrows].
      do 2 (apply in_or_app; right). apply in_or_app. left.
      apply trace3_seed.
      unfold FOProvSentence. rewrite FOsubst_f_num. reflexivity. }
  split.
  { exists (FOcode_tm (FOnumeral (FOcode_f (FOProvSentence k X)))).
    split.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_d3 k X) _ HIn).
      cbv beta iota delta [jrows].
      do 3 (apply in_or_app; right). apply in_or_app. left.
      apply trace5_seed. reflexivity.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_d3 k X) _ HIn).
      cbv beta iota delta [jrows].
      do 4 (apply in_or_app; right).
      apply trace3_seed.
      unfold FOProvSentence at 2. rewrite FOsubst_f_num.
      reflexivity. }
  reflexivity.
Qed.

Lemma justck_dmon_rows : forall
    (L : nat -> nat -> nat -> nat -> nat -> Prop) n items k k' X,
  (forall tg a1 a2 a3 r,
     In (mkTE tg a1 a2 a3 r) (seqrows n items) -> L tg a1 a2 a3 r) ->
  In (FOImplF (FOProvSentence k X) (FOProvSentence k' X),
      J_dmon k k' X) items ->
  dmonone_sem L
    (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
       (FOPRMAT (FOPrCores k))))
    (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k')))
       (FOPRMAT (FOPrCores k'))))
    (FOcode_f (FOImplF (FOProvSentence k X) (FOProvSentence k' X))).
Proof.
  intros L n items k k' X Hsub HIn.
  exists (FOcode_f X),
    (FOcode_f (FOProvSentence k X)),
    (FOcode_f (FOProvSentence k' X)).
  split.
  { apply (justck_genuine_row L n items _ _ X Hsub HIn).
    intros e He.
    cbv beta iota delta [jrows].
    apply in_or_app. left. exact He. }
  split.
  { exists (FOcode_tm (FOnumeral (FOcode_f X))).
    split.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_dmon k k' X) _ HIn).
      cbv beta iota delta [jrows].
      apply in_or_app. right. apply in_or_app. left.
      apply trace5_seed. reflexivity.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_dmon k k' X) _ HIn).
      cbv beta iota delta [jrows].
      do 2 (apply in_or_app; right). apply in_or_app. left.
      apply trace3_seed.
      unfold FOProvSentence. rewrite FOsubst_f_num. reflexivity. }
  split.
  { exists (FOcode_tm (FOnumeral (FOcode_f X))).
    split.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_dmon k k' X) _ HIn).
      cbv beta iota delta [jrows].
      apply in_or_app. right. apply in_or_app. left.
      apply trace5_seed. reflexivity.
    - apply Hsub.
      apply (seqrows_jrows_in n items _ (J_dmon k k' X) _ HIn).
      cbv beta iota delta [jrows].
      do 3 (apply in_or_app; right).
      apply trace3_seed.
      unfold FOProvSentence. rewrite FOsubst_f_num. reflexivity. }
  reflexivity.
Qed.

Lemma justck_ind : forall (L : nat -> nat -> nat -> nat -> nat -> Prop)
    n items x X,
  (forall tg a1 a2 a3 r,
     In (mkTE tg a1 a2 a3 r) (seqrows n items) -> L tg a1 a2 a3 r) ->
  In (FOInduction x X, J_ind x X) items ->
  L 4 x (FOcode_tm FOZero) (FOcode_f X) 1
  /\ L 3 x (FOcode_tm FOZero) (FOcode_f X)
       (FOcode_f (FOsubst_f x FOZero X))
  /\ L 4 x (FOcode_tm (FOSucc (FOVar x))) (FOcode_f X) 1
  /\ L 3 x (FOcode_tm (FOSucc (FOVar x))) (FOcode_f X)
       (FOcode_f (FOsubst_f x (FOSucc (FOVar x)) X)).
Proof.
  intros L n items x X Hsub HIn.
  pose proof (FOsubst_ok_numeral X x 0) as Hok0.
  cbn [FOnumeral] in Hok0.
  pose proof (FOsubst_ok_succ_var_self X x) as Hoks.
  split; [|split; [|split]].
  - apply Hsub.
    apply (seqrows_jrows_in n items _ (J_ind x X) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. left.
    apply trace4_seed. rewrite Hok0. reflexivity.
  - apply Hsub.
    apply (seqrows_jrows_in n items _ (J_ind x X) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. right. apply in_or_app. left.
    apply trace3_seed. reflexivity.
  - apply Hsub.
    apply (seqrows_jrows_in n items _ (J_ind x X) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. right. apply in_or_app. right.
    apply in_or_app. left.
    apply trace4_seed. rewrite Hoks. reflexivity.
  - apply Hsub.
    apply (seqrows_jrows_in n items _ (J_ind x X) _ HIn).
    cbv beta iota delta [jrows].
    apply in_or_app. right. apply in_or_app. right.
    apply in_or_app. right.
    apply trace3_seed. reflexivity.
Qed.

Theorem provmat_encode : forall n A,
  FOProvesTn n A ->
  provmat_sem (FOPrCores n) (FOcode_f (FOPRMAT (FOPrCores n)))
    (FOcode_f A).
Proof.
  intros n A HPr.
  destruct (FOProvesTn_to_seq n A HPr) as [items [pre [Hck Hmap]]].
  destruct (table_realize (seqrows n items)
      (seqrows_ok n items (seqrows n items) (incl_refl _)))
    as [vct [vdt [vc1 [vd1 [vc2 [vd2 [vc3 [vd3 [vcr [vdr
        [HIFF Hdisp]]]]]]]]]]].
  destruct (beta_complete (map (fun it => FOcode_f (fst it)) items))
    as [vcs [vds Hbs]].
  destruct (beta_complete (map (fun it => jcode (snd it)) items))
    as [vcj [vdj Hbj]].
  assert (Hsub : forall tg a1 a2 a3 r,
      In (mkTE tg a1 a2 a3 r) (seqrows n items) ->
      tblL vct vdt vc1 vd1 vc2 vd2 vc3 vd3 vcr vdr
        (length (seqrows n items)) tg a1 a2 a3 r).
  { intros tg a1 a2 a3 r Hrow. apply HIFF. exact Hrow. }
  exists vct, vdt, vc1, vd1, vc2, vd2, vc3, vd3, vcr, vdr,
    (length (seqrows n items)), vcs, vds, vcj, vdj, (length items).
  split; [exact Hdisp|].
  split.
  { exists (length pre).
    assert (HlenA : length items = S (length pre)).
    { pose proof (length_map fst items) as Hl.
      rewrite Hmap in Hl. rewrite length_app in Hl.
      cbn [length] in Hl. lia. }
    split; [exact HlenA|].
    rewrite Hbs by (rewrite length_map; lia).
    apply nth_error_nth.
    rewrite <- map_map. rewrite Hmap. rewrite map_app.
    rewrite nth_error_app2 by (rewrite length_map; lia).
    rewrite length_map. rewrite Nat.sub_diag. reflexivity. }
  split.
  { intros ii Hii.
    destruct (nth_error items ii) as [[B j]|] eqn:Hith.
    2:{ apply nth_error_None in Hith. lia. }
    pose proof (nth_error_In _ _ Hith) as HInBj.
    pose proof (FOseq_check_nth0 _ _ _ _ _ _ _ Hck Hith) as Hentry.
    assert (Hvd : beta vcs vds ii = FOcode_f B).
    { rewrite Hbs by (rewrite length_map; lia).
      apply nth_error_nth. rewrite nth_error_map.
      rewrite Hith. reflexivity. }
    assert (Hvj : beta vcj vdj ii = jcode j).
    { rewrite Hbj by (rewrite length_map; lia).
      apply nth_error_nth. rewrite nth_error_map.
      rewrite Hith. reflexivity. }
    exists (FOcode_f B), (jcode j).
    destruct j as [| | x t | x t | i1 j1 | i1 | i1
                  | k X Y | k X | k k' X | x X];
      cbv beta iota delta [FOentry_check] in Hentry.
    - exists 0, 0.
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      left. split; [reflexivity|].
      exact (justck_thax _ n items B Hsub HInBj Hentry).
    - exists 1, 0.
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      right; left. split; [reflexivity|].
      exact (justck_log _ n items B Hsub HInBj Hentry).
    - exists 2, (cpair x (FOcode_tm t)).
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      do 2 right; left. split; [reflexivity|].
      destruct (justck_allelim _ n items B x t Hsub HInBj Hentry)
        as [P [Q [Hshape [H4 H3]]]].
      exists x, (FOcode_tm t), P, Q.
      split; [reflexivity|]. split; [exact Hshape|].
      split; [exact H4|exact H3].
    - exists 3, (cpair x (FOcode_tm t)).
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      do 3 right; left. split; [reflexivity|].
      destruct (justck_exintro _ n items B x t Hsub HInBj Hentry)
        as [P [Q [Hshape [H4 H3]]]].
      exists x, (FOcode_tm t), P, Q.
      split; [reflexivity|]. split; [exact Hshape|].
      split; [exact H4|exact H3].
    - exists 4, (cpair i1 j1).
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      do 4 right; left. split; [reflexivity|].
      revert Hentry.
      destruct (nth_error (map fst (firstn ii items)) i1)
        as [AB|] eqn:HAB; intros Hentry; [|discriminate].
      revert Hentry.
      destruct (nth_error (map fst (firstn ii items)) j1)
        as [B1|] eqn:HB1; intros Hentry; [|discriminate].
      cbv beta iota in Hentry.
      apply FOform_eqb_eq in Hentry. subst AB.
      destruct (prev_nth_resolve _ _ _ _ HAB) as [Hi1 [jA HitA]].
      destruct (prev_nth_resolve _ _ _ _ HB1) as [Hj1 [jB HitB]].
      exists i1, j1, (FOcode_f (FOImplF B1 B)), (FOcode_f B1).
      split; [reflexivity|]. split; [lia|]. split; [lia|].
      split.
      { rewrite Hbs by (rewrite length_map; lia).
        apply nth_error_nth. rewrite nth_error_map.
        rewrite HitA. reflexivity. }
      split.
      { rewrite Hbs by (rewrite length_map; lia).
        apply nth_error_nth. rewrite nth_error_map.
        rewrite HitB. reflexivity. }
      reflexivity.
    - destruct B as [a b | | P0 C0 | y B0 | y B0]; try discriminate.
      exists 5, i1.
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      do 5 right; left.
      revert Hentry.
      destruct (nth_error (map fst (firstn ii items)) i1)
        as [B'|] eqn:HB'; intros Hentry; [|discriminate].
      cbv beta iota in Hentry.
      apply FOform_eqb_eq in Hentry. subst B0.
      destruct (prev_nth_resolve _ _ _ _ HB') as [Hi1 [jB HitB]].
      split; [reflexivity|]. split; [lia|].
      exists (FOcode_f B'), y.
      split.
      { rewrite Hbs by (rewrite length_map; lia).
        apply nth_error_nth. rewrite nth_error_map.
        rewrite HitB. reflexivity. }
      reflexivity.
    - exists 6, i1.
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      do 6 right; left.
      revert Hentry.
      destruct (nth_error (map fst (firstn ii items)) i1)
        as [P0|] eqn:HP0; intros Hentry; [|discriminate].
      cbv beta iota in Hentry.
      apply FOform_eqb_eq in Hentry. subst P0.
      destruct (prev_nth_resolve _ _ _ _ HP0) as [Hi1 [jP HitP]].
      split; [reflexivity|]. split; [lia|].
      destruct (justck_loeb_rows _ n items B i1 Hsub HInBj)
        as [nu [core [na [p [R1 [R2 [R3 [R4 Hp]]]]]]]].
      exists (FOcode_f (FOImplF (FOProvSentence n B) B)),
        nu, core, na, p.
      split.
      { rewrite Hbs by (rewrite length_map; lia).
        apply nth_error_nth. rewrite nth_error_map.
        rewrite HitP. reflexivity. }
      split; [exact R1|]. split; [exact R2|]. split; [exact R3|].
      split; [exact R4|].
      rewrite Hp. reflexivity.
    - exists 7, (cpair k (cpair (FOcode_f X) (FOcode_f Y))).
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      do 7 right; left. split; [reflexivity|].
      apply andb_prop in Hentry. destruct Hentry as [Hk Heq].
      apply Nat.ltb_lt in Hk.
      apply FOform_eqb_eq in Heq. subst B.
      apply (d2s_sem_of _ _
        (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
           (FOPRMAT (FOPrCores k)))) _).
      + apply FOPrCores_in_of. exact Hk.
      + exact (justck_d2_rows _ n items k X Y Hsub HInBj).
    - exists 8, (cpair k (FOcode_f X)).
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      do 8 right; left. split; [reflexivity|].
      apply andb_prop in Hentry. destruct Hentry as [Hk Heq].
      apply Nat.ltb_lt in Hk.
      apply FOform_eqb_eq in Heq. subst B.
      apply (d3s_sem_of _ _
        (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
           (FOPRMAT (FOPrCores k)))) _).
      + apply FOPrCores_in_of. exact Hk.
      + exact (justck_d3_rows _ n items k X Hsub HInBj).
    - exists 9, (cpair k (cpair k' (FOcode_f X))).
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      do 9 right; left. split; [reflexivity|].
      apply andb_prop in Hentry. destruct Hentry as [Hk Heq].
      apply andb_prop in Hk. destruct Hk as [Hkk Hk'].
      apply Nat.leb_le in Hkk. apply Nat.ltb_lt in Hk'.
      apply FOform_eqb_eq in Heq. subst B.
      apply (dmons_sem_of_nth _ _ k k'
        (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k)))
           (FOPRMAT (FOPrCores k))))
        (FOcode_f (FOsubst_num 0 (FOcode_f (FOPRMAT (FOPrCores k')))
           (FOPRMAT (FOPrCores k')))) _
        (FOPrCores_nth_of n k ltac:(lia))
        (FOPrCores_nth_of n k' Hk') Hkk).
      exact (justck_dmon_rows _ n items k k' X Hsub HInBj).
    - apply FOform_eqb_eq in Hentry. subst B.
      exists 10, (cpair x (FOcode_f X)).
      split; [exact Hvd|]. split; [exact Hvj|]. split; [reflexivity|].
      do 10 right. split; [reflexivity|].
      destruct (justck_ind _ n items x X Hsub HInBj)
        as [H4b [H3b [H4s H3s]]].
      exists x, (FOcode_f X),
        (FOcode_f (FOsubst_f x FOZero X)),
        (FOcode_f (FOsubst_f x (FOSucc (FOVar x)) X)).
      split; [reflexivity|].
      split; [reflexivity|].
      split; [exact H4b|]. split; [exact H3b|].
      split; [exact H4s|exact H3s]. }
  { intros ii Hii.
    destruct (nth_error items ii) as [[B j]|] eqn:Hith.
    2:{ apply nth_error_None in Hith. lia. }
    pose proof (nth_error_In _ _ Hith) as HInBj.
    assert (Hvd : beta vcs vds ii = FOcode_f B).
    { rewrite Hbs by (rewrite length_map; lia).
      apply nth_error_nth. rewrite nth_error_map.
      rewrite Hith. reflexivity. }
    rewrite Hvd.
    exists (FOcode_f (FOsubst_f (S (FOcode_f B)) (FOVar 0) B)).
    apply Hsub.
    pose proof (trace3_seed (S (FOcode_f B)) (FOVar 0) B
        (FOcode_f (FOsubst_f (S (FOcode_f B)) (FOVar 0) B))
        eq_refl) as Hrow.
    change (FOcode_tm (FOVar 0)) with 0 in Hrow.
    exact (seqrows_guard_in n items B j _ HInBj Hrow). }
Qed.

Transparent FOPRMAT.

(** ** The representability bridge.

    Satisfaction of the level-[n] provability sentence coincides with
    derivability in [T_n]: decoding consumes an accepted matrix,
    encoding produces one from an accepted sequence.  Modus ponens
    and the Loeb rule then transfer to the satisfaction level. *)

Theorem FOProvSentence_sat_iff : forall e n A,
  FOsat e (FOProvSentence n A) <-> FOProvesTn n A.
Proof.
  intros e n A.
  rewrite (FOsat_FOProvSentence e n A).
  split; [exact (provmat_decode n A)|exact (provmat_encode n A)].
Qed.

Theorem FOHBL1_sat : forall e n A,
  FOProvesTn n A -> FOsat e (FOProvSentence n A).
Proof.
  intros e n A H. apply (FOProvSentence_sat_iff e n A). exact H.
Qed.

Theorem FOHBL2_sat : forall e n A B,
  FOsat e (FOProvSentence n (FOImplF A B)) ->
  FOsat e (FOProvSentence n A) ->
  FOsat e (FOProvSentence n B).
Proof.
  intros e n A B H1 H2.
  apply (FOProvSentence_sat_iff e n B).
  exact (FOProvesTn_MP n A B
    (proj1 (FOProvSentence_sat_iff e n (FOImplF A B)) H1)
    (proj1 (FOProvSentence_sat_iff e n A) H2)).
Qed.

Theorem FOLoeb_sat : forall e n A,
  FOsat e (FOProvSentence n (FOImplF (FOProvSentence n A) A)) ->
  FOsat e (FOProvSentence n A).
Proof.
  intros e n A H.
  apply (FOProvSentence_sat_iff e n A).
  apply FOProvesTn_Loeb.
  exact (proj1 (FOProvSentence_sat_iff e n _) H).
Qed.

(** ** Formalized derivability and tower cumulativity.

    The provability sentence is a closed Sigma_1 formula, so provable
    Sigma_1-completeness turns derivability of [A] in [T_n] into
    derivability of the level-[n] provability sentence at every
    level.  Cumulativity then absorbs the Loeb rule: the rule's
    conclusion at level [n] re-enters level [m] through the
    formalized derivability statement. *)

Theorem FOHBL3_provable : forall n m A,
  FOProvesTn n A -> FOProvesTn m (FOProvSentence n A).
Proof.
  intros n m A H.
  apply (FOsigma1_completeness_closed (FOProvSentence n A)).
  - apply FOsigma1_FOProvSentence.
  - intro v. apply FOProvSentence_closed.
  - apply (FOHBL1_sat (fun _ => 0) n A). exact H.
Qed.

Theorem FOHBL3_sat : forall e n A,
  FOsat e (FOProvSentence n A) ->
  FOsat e (FOProvSentence n (FOProvSentence n A)).
Proof.
  intros e n A H.
  apply FOHBL1_sat. apply (FOHBL3_provable n n).
  exact (proj1 (FOProvSentence_sat_iff e n A) H).
Qed.

Theorem FOProvesTn_cumulative : forall n m A,
  n <= m -> FOProvesTn n A -> FOProvesTn m A.
Proof.
  intros n m A Hnm H. induction H.
  - apply FOProvesTn_ax.
    match goal with
    | HA : FOAxiomTn _ _ |- _ =>
        inversion HA; subst;
        [ apply FOAx_RQ; assumption
        | apply FOAx_Refl; lia
        | apply FOAx_D2; lia
        | apply FOAx_D3; lia
        | apply FOAx_DMon; lia
        | apply FOAx_Ind ]
    end.
  - apply FOProvesTn_K.
  - apply FOProvesTn_S.
  - apply FOProvesTn_DN.
  - eapply FOProvesTn_MP; eassumption.
  - apply FOProvesTn_Gen; assumption.
  - apply FOProvesTn_EqRefl.
  - apply FOProvesTn_EqSym.
  - apply FOProvesTn_EqTrans.
  - apply FOProvesTn_CongS.
  - apply FOProvesTn_CongPlus.
  - apply FOProvesTn_CongMult.
  - apply FOProvesTn_AllElimT; assumption.
  - apply FOProvesTn_ExIntroT; assumption.
  - apply FOProvesTn_ExElim; assumption.
  - apply FOProvesTn_AllK.
  - apply FOProvesTn_AllExport; assumption.
  - apply (FOProvesTn_MP m (FOProvSentence n phi) phi);
      [assumption|].
    apply (FOHBL3_provable n m).
    apply FOProvesTn_Loeb. assumption.
Qed.

Theorem FOProv_sat_monotone : forall e n m A,
  n <= m ->
  FOsat e (FOProvSentence n A) -> FOsat e (FOProvSentence m A).
Proof.
  intros e n m A Hnm H.
  apply FOProvSentence_sat_iff.
  exact (FOProvesTn_cumulative n m A Hnm
           (proj1 (FOProvSentence_sat_iff e n A) H)).
Qed.

(** ** Provable Sigma_1 completeness, closed Delta_0 fragment.

    The level-[n] tower internally derives the completeness implication
    [A -> Prov_n A] for every closed Delta_0 sentence [A].  Decidability
    of closed Delta_0 sentences ([FOdelta0_decided]) splits on truth: a
    true [A] is derivable, hence (by necessitation [FOHBL3_provable]) so
    is [Prov_n A], and weakening discharges the antecedent; a false [A]
    is refutable, and ex falso closes the implication.  This is the
    closed-[Delta_0] case of provable Sigma_1 completeness; the open
    case (and the existential wrap) need the internal numeral
    substitution function and are not covered by truth-splitting. *)

Theorem provable_delta0_completeness_closed : forall n A,
  FOdelta0 A -> (forall v, FOfree_in v A = false) ->
  FOProvesTn n (FOImplF A (FOProvSentence n A)).
Proof.
  intros n A HD Hcl.
  destruct (FOdelta0_decided (FOfsize A) A (Nat.le_refl _) HD Hcl n)
    as [Htrue Hfalse].
  destruct (classic (FOsat (fun _ => 0) A)) as [Hs | Hns].
  - exact (FOPr_weaken n (FOProvSentence n A) A
             (FOHBL3_provable n n A (Htrue Hs))).
  - exact (FOPr_compose n A FOFalseF (FOProvSentence n A)
             (Hfalse Hns) (FOPr_efq n (FOProvSentence n A))).
Qed.

(** ** Cross-level box combinators.

    These internalize, at level [n], the distribution of a level-[k]
    derivation over the level-[k] provability box (for [k < n]).  They
    are the reusable steps of the open-[Delta_0] and [Sigma_1]
    constructions: [FOprov_box_nec_imp] necessitates an object-level
    implication provable at level [k] and distributes it across the box
    using the second Hilbert-Bernays axiom; the binary and existential
    forms specialize it.  No truth-splitting and no appeal to
    [FOAx_D3]. *)

Lemma FOprov_box_nec_imp : forall n k A B,
  k < n -> FOProvesTn k (FOImplF A B) ->
  FOProvesTn n (FOImplF (FOProvSentence k A) (FOProvSentence k B)).
Proof.
  intros n k A B Hk Hab.
  exact (FOProvesTn_MP n _ _
           (FOProvesTn_ax n _ (FOAx_D2 n k A B Hk))
           (FOHBL3_provable k n _ Hab)).
Qed.

Lemma FOprov_box_nec_imp2 : forall n k A B C,
  k < n -> FOProvesTn k (FOImplF A (FOImplF B C)) ->
  FOProvesTn n (FOImplF (FOProvSentence k A)
                  (FOImplF (FOProvSentence k B) (FOProvSentence k C))).
Proof.
  intros n k A B C Hk Habc.
  pose proof (FOprov_box_nec_imp n k A (FOImplF B C) Hk Habc) as H1.
  pose proof (FOProvesTn_ax n _ (FOAx_D2 n k B C Hk)) as Hd2.
  exact (FOPr_compose n (FOProvSentence k A)
           (FOProvSentence k (FOImplF B C))
           (FOImplF (FOProvSentence k B) (FOProvSentence k C)) H1 Hd2).
Qed.

Lemma FOprov_box_ex_intro : forall n k x t delta,
  k < n -> FOsubst_ok x t delta = true ->
  FOProvesTn n (FOImplF (FOProvSentence k (FOsubst_f x t delta))
                        (FOProvSentence k (FOExists x delta))).
Proof.
  intros n k x t delta Hk Hok.
  exact (FOprov_box_nec_imp n k _ _ Hk
           (FOProvesTn_ExIntroT k x t delta Hok)).
Qed.

Lemma FOprov_box_ex_intro_num : forall n k x m delta,
  k < n ->
  FOProvesTn n (FOImplF (FOProvSentence k (FOsubst_num x m delta))
                        (FOProvSentence k (FOExists x delta))).
Proof.
  intros n k x m delta Hk.
  rewrite <- (FOsubst_f_num delta x m).
  exact (FOprov_box_ex_intro n k x (FOnumeral m) delta Hk
           (FOsubst_ok_numeral delta x m)).
Qed.

(** Box versions of the propositional connective rules: each
    necessitates the corresponding level-[k] tautology and distributes
    it across the level-[k] box.  [box_imp_weaken] is the [K]
    combinator boxed; [box_imp_from_neg] is the ex-falso direction,
    boxed — together they give both halves of the implication case in a
    boxed [Delta_0] completeness induction. *)

Lemma FOprov_box_and_intro : forall n k A B,
  k < n ->
  FOProvesTn n (FOImplF (FOProvSentence k A)
                  (FOImplF (FOProvSentence k B)
                     (FOProvSentence k (FOAnd A B)))).
Proof.
  intros n k A B Hk.
  apply (FOprov_box_nec_imp2 n k A B (FOAnd A B) Hk).
  apply (FOPr_taut k (FOm2 A B)
    (Impl (Var 0) (Impl (Var 1) (And (Var 0) (Var 1)))));
    [cbn; tauto | reflexivity].
Qed.

Lemma FOprov_box_and_elim_l : forall n k A B,
  k < n ->
  FOProvesTn n (FOImplF (FOProvSentence k (FOAnd A B))
                        (FOProvSentence k A)).
Proof.
  intros n k A B Hk.
  exact (FOprov_box_nec_imp n k _ _ Hk (FOPr_and_elim_l k A B)).
Qed.

Lemma FOprov_box_and_elim_r : forall n k A B,
  k < n ->
  FOProvesTn n (FOImplF (FOProvSentence k (FOAnd A B))
                        (FOProvSentence k B)).
Proof.
  intros n k A B Hk.
  exact (FOprov_box_nec_imp n k _ _ Hk (FOPr_and_elim_r k A B)).
Qed.

Lemma FOprov_box_or_intro_l : forall n k A B,
  k < n ->
  FOProvesTn n (FOImplF (FOProvSentence k A)
                        (FOProvSentence k (FOOr A B))).
Proof.
  intros n k A B Hk.
  exact (FOprov_box_nec_imp n k _ _ Hk (FOPr_or_intro_l k A B)).
Qed.

Lemma FOprov_box_or_intro_r : forall n k A B,
  k < n ->
  FOProvesTn n (FOImplF (FOProvSentence k B)
                        (FOProvSentence k (FOOr A B))).
Proof.
  intros n k A B Hk.
  exact (FOprov_box_nec_imp n k _ _ Hk (FOPr_or_intro_r k A B)).
Qed.

Lemma FOprov_box_imp_weaken : forall n k B C,
  k < n ->
  FOProvesTn n (FOImplF (FOProvSentence k C)
                        (FOProvSentence k (FOImplF B C))).
Proof.
  intros n k B C Hk.
  exact (FOprov_box_nec_imp n k _ _ Hk (FOProvesTn_K k C B)).
Qed.

Lemma FOprov_box_imp_from_neg : forall n k B C,
  k < n ->
  FOProvesTn n (FOImplF (FOProvSentence k (FONeg B))
                        (FOProvSentence k (FOImplF B C))).
Proof.
  intros n k B C Hk.
  apply (FOprov_box_nec_imp n k (FONeg B) (FOImplF B C) Hk).
  apply (FOPr_taut k (FOm2 B C)
    (Impl (Neg (Var 0)) (Impl (Var 0) (Var 1))));
    [cbn; tauto | reflexivity].
Qed.

(** ** Applied equational toolkit.

    The equality axioms in their [exact]-applied (proof-to-proof) form:
    these turn object-level equational chains into ordinary function
    composition instead of nested [MP]-on-[EqTrans] terms. *)

Lemma FOPr_eq_sym : forall n a b,
  FOProvesTn n (FOEq a b) -> FOProvesTn n (FOEq b a).
Proof.
  intros n a b H. exact (FOProvesTn_MP n _ _ (FOProvesTn_EqSym n a b) H).
Qed.

Lemma FOPr_eq_trans : forall n a b c,
  FOProvesTn n (FOEq a b) -> FOProvesTn n (FOEq b c) ->
  FOProvesTn n (FOEq a c).
Proof.
  intros n a b c H1 H2.
  exact (FOProvesTn_MP n _ _
           (FOProvesTn_MP n _ _ (FOProvesTn_EqTrans n a b c) H1) H2).
Qed.

Lemma FOPr_eq_congS : forall n a b,
  FOProvesTn n (FOEq a b) -> FOProvesTn n (FOEq (FOSucc a) (FOSucc b)).
Proof.
  intros n a b H. exact (FOProvesTn_MP n _ _ (FOProvesTn_CongS n a b) H).
Qed.

Lemma FOPr_eq_congPlus : forall n a b c d,
  FOProvesTn n (FOEq a b) -> FOProvesTn n (FOEq c d) ->
  FOProvesTn n (FOEq (FOPlus a c) (FOPlus b d)).
Proof.
  intros n a b c d H1 H2.
  exact (FOProvesTn_MP n _ _
           (FOProvesTn_MP n _ _ (FOProvesTn_CongPlus n a b c d) H1) H2).
Qed.

Lemma FOPr_eq_congMult : forall n a b c d,
  FOProvesTn n (FOEq a b) -> FOProvesTn n (FOEq c d) ->
  FOProvesTn n (FOEq (FOMult a c) (FOMult b d)).
Proof.
  intros n a b c d H1 H2.
  exact (FOProvesTn_MP n _ _
           (FOProvesTn_MP n _ _ (FOProvesTn_CongMult n a b c d) H1) H2).
Qed.

(** Implication-form equational steps: thread a closed equation onto an
    equation that is conditional on a hypothesis [H].  These play the
    role of a deduction theorem for the equational reasoning inside an
    induction step, where [H] is the induction hypothesis. *)

Lemma FOPr_imp_eq_trans_l : forall n H a b c,
  FOProvesTn n (FOEq a b) ->
  FOProvesTn n (FOImplF H (FOEq b c)) ->
  FOProvesTn n (FOImplF H (FOEq a c)).
Proof.
  intros n H a b c Hab Hbc.
  pose proof (FOPr_compose n H (FOEq a b) (FOImplF (FOEq b c) (FOEq a c))
                (FOPr_weaken n (FOEq a b) H Hab)
                (FOProvesTn_EqTrans n a b c)) as Hc.
  exact (FOProvesTn_MP n _ _
           (FOProvesTn_MP n _ _ (FOProvesTn_S n H (FOEq b c) (FOEq a c)) Hc)
           Hbc).
Qed.

Lemma FOPr_imp_eq_trans_r : forall n H a b c,
  FOProvesTn n (FOImplF H (FOEq a b)) ->
  FOProvesTn n (FOEq b c) ->
  FOProvesTn n (FOImplF H (FOEq a c)).
Proof.
  intros n H a b c Hab Hbc.
  pose proof (FOProvesTn_MP n _ _
    (FOProvesTn_MP n _ _ (FOPr_imp_swap n (FOEq a b) (FOEq b c) (FOEq a c))
       (FOProvesTn_EqTrans n a b c)) Hbc) as Hac.
  exact (FOPr_compose n H (FOEq a b) (FOEq a c) Hab Hac).
Qed.

Lemma FOPr_imp_eq_congS : forall n H a b,
  FOProvesTn n (FOImplF H (FOEq a b)) ->
  FOProvesTn n (FOImplF H (FOEq (FOSucc a) (FOSucc b))).
Proof.
  intros n H a b H1.
  exact (FOPr_compose n H (FOEq a b) (FOEq (FOSucc a) (FOSucc b))
           H1 (FOProvesTn_CongS n a b)).
Qed.

(** Left-argument congruence for [+] (the right argument fixed), in
    plain and implication-conditional form: the [mult] step cases apply
    the induction hypothesis under a [+ c]. *)

Lemma FOPr_congPlus_l : forall n a b c,
  FOProvesTn n (FOImplF (FOEq a b) (FOEq (FOPlus a c) (FOPlus b c))).
Proof.
  intros n a b c.
  exact (FOProvesTn_MP n _ _
    (FOProvesTn_MP n _ _
      (FOPr_imp_swap n (FOEq a b) (FOEq c c)
         (FOEq (FOPlus a c) (FOPlus b c)))
      (FOProvesTn_CongPlus n a b c c))
    (FOProvesTn_EqRefl n c)).
Qed.

Lemma FOPr_imp_eq_congPlus_l : forall n H a b c,
  FOProvesTn n (FOImplF H (FOEq a b)) ->
  FOProvesTn n (FOImplF H (FOEq (FOPlus a c) (FOPlus b c))).
Proof.
  intros n H a b c H1.
  exact (FOPr_compose n H (FOEq a b) (FOEq (FOPlus a c) (FOPlus b c))
           H1 (FOPr_congPlus_l n a b c)).
Qed.

Lemma FOPr_congPlus_r : forall n a b c,
  FOProvesTn n (FOImplF (FOEq b c) (FOEq (FOPlus a b) (FOPlus a c))).
Proof.
  intros n a b c.
  exact (FOProvesTn_MP n _ _
    (FOProvesTn_CongPlus n a a b c) (FOProvesTn_EqRefl n a)).
Qed.

Lemma FOPr_imp_eq_congPlus_r : forall n H a b c,
  FOProvesTn n (FOImplF H (FOEq b c)) ->
  FOProvesTn n (FOImplF H (FOEq (FOPlus a b) (FOPlus a c))).
Proof.
  intros n H a b c H1.
  exact (FOPr_compose n H (FOEq b c) (FOEq (FOPlus a b) (FOPlus a c))
           H1 (FOPr_congPlus_r n a b c)).
Qed.

(** The same congruences for [*]. *)

Lemma FOPr_congMult_l : forall n a b c,
  FOProvesTn n (FOImplF (FOEq a b) (FOEq (FOMult a c) (FOMult b c))).
Proof.
  intros n a b c.
  exact (FOProvesTn_MP n _ _
    (FOProvesTn_MP n _ _
      (FOPr_imp_swap n (FOEq a b) (FOEq c c)
         (FOEq (FOMult a c) (FOMult b c)))
      (FOProvesTn_CongMult n a b c c))
    (FOProvesTn_EqRefl n c)).
Qed.

Lemma FOPr_congMult_r : forall n a b c,
  FOProvesTn n (FOImplF (FOEq b c) (FOEq (FOMult a b) (FOMult a c))).
Proof.
  intros n a b c.
  exact (FOProvesTn_MP n _ _
    (FOProvesTn_CongMult n a a b c) (FOProvesTn_EqRefl n a)).
Qed.

Lemma FOPr_imp_eq_congMult_l : forall n H a b c,
  FOProvesTn n (FOImplF H (FOEq a b)) ->
  FOProvesTn n (FOImplF H (FOEq (FOMult a c) (FOMult b c))).
Proof.
  intros n H a b c H1.
  exact (FOPr_compose n H (FOEq a b) (FOEq (FOMult a c) (FOMult b c))
           H1 (FOPr_congMult_l n a b c)).
Qed.

Lemma FOPr_imp_eq_congMult_r : forall n H a b c,
  FOProvesTn n (FOImplF H (FOEq b c)) ->
  FOProvesTn n (FOImplF H (FOEq (FOMult a b) (FOMult a c))).
Proof.
  intros n H a b c H1.
  exact (FOPr_compose n H (FOEq b c) (FOEq (FOMult a b) (FOMult a c))
           H1 (FOPr_congMult_r n a b c)).
Qed.

(** ** Object-level induction at work.

    Robinson [Q] proves [a + 0 = a] and [a + S b = S (a + b)] but not
    the left unit law [0 + x = x], which needs induction on [x].  With
    [FOAx_Ind] in the tower the law is an object-level theorem: apply
    the induction instance, discharge the base by [Q]'s [plus_zero], and
    the step by congruence through [Q]'s [plus_succ].  This is the first
    brick of the [PA]-over-[Q] arithmetic the numeral and substitution
    functions are built from. *)

Lemma FOPr_zero_plus : forall n,
  FOProvesTn n (FOForall 0 (FOEq (FOPlus FOZero (FOVar 0)) (FOVar 0))).
Proof.
  intros n.
  pose proof (FOProvesTn_ax n _
    (FOAx_Ind n 0 (FOEq (FOPlus FOZero (FOVar 0)) (FOVar 0)))) as Hind.
  unfold FOInduction in Hind.
  apply (FOProvesTn_MP n _ _
           (FOProvesTn_MP n _ _ Hind (FOPr_q_plus_zero n FOZero))).
  apply FOProvesTn_Gen.
  pose proof (FOProvesTn_CongS n (FOPlus FOZero (FOVar 0)) (FOVar 0)) as Hcong.
  pose proof (FOProvesTn_MP n _ _
    (FOProvesTn_EqTrans n (FOPlus FOZero (FOSucc (FOVar 0)))
       (FOSucc (FOPlus FOZero (FOVar 0))) (FOSucc (FOVar 0)))
    (FOPr_q_plus_succ n FOZero (FOVar 0))) as Htr.
  exact (FOPr_compose n _ _ _ Hcong Htr).
Qed.

(** [S x + y = S (x + y)] by induction on [y].  The step chains the
    successor congruence applied to the hypothesis between the two
    [Q]-provable [plus_succ] facts, using the implication-form
    equational steps. *)

Lemma FOPr_succ_plus : forall n,
  FOProvesTn n (FOForall 0 (FOForall 1
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
          (FOSucc (FOPlus (FOVar 0) (FOVar 1)))))).
Proof.
  intros n.
  apply FOProvesTn_Gen.
  pose proof (FOProvesTn_ax n _ (FOAx_Ind n 1
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
          (FOSucc (FOPlus (FOVar 0) (FOVar 1)))))) as Hind.
  unfold FOInduction in Hind.
  assert (Hbase : FOProvesTn n
    (FOEq (FOPlus (FOSucc (FOVar 0)) FOZero)
          (FOSucc (FOPlus (FOVar 0) FOZero)))).
  { exact (FOPr_eq_trans n _ (FOSucc (FOVar 0)) _
             (FOPr_q_plus_zero n (FOSucc (FOVar 0)))
             (FOPr_eq_sym n _ _
                (FOPr_eq_congS n _ _ (FOPr_q_plus_zero n (FOVar 0))))). }
  assert (Hstep : FOProvesTn n (FOForall 1 (FOImplF
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
          (FOSucc (FOPlus (FOVar 0) (FOVar 1))))
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 1)))
          (FOSucc (FOPlus (FOVar 0) (FOSucc (FOVar 1)))))))).
  { apply FOProvesTn_Gen.
    apply (FOPr_imp_eq_trans_r n
             (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
                   (FOSucc (FOPlus (FOVar 0) (FOVar 1))))
             (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 1)))
             (FOSucc (FOSucc (FOPlus (FOVar 0) (FOVar 1))))
             (FOSucc (FOPlus (FOVar 0) (FOSucc (FOVar 1))))).
    - apply (FOPr_imp_eq_trans_l n
               (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
                     (FOSucc (FOPlus (FOVar 0) (FOVar 1))))
               (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 1)))
               (FOSucc (FOPlus (FOSucc (FOVar 0)) (FOVar 1)))
               (FOSucc (FOSucc (FOPlus (FOVar 0) (FOVar 1))))).
      + exact (FOPr_q_plus_succ n (FOSucc (FOVar 0)) (FOVar 1)).
      + apply FOPr_imp_eq_congS.
        exact (FOPr_idf n (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
                                (FOSucc (FOPlus (FOVar 0) (FOVar 1))))).
    - apply FOPr_eq_sym. apply FOPr_eq_congS.
      exact (FOPr_q_plus_succ n (FOVar 0) (FOVar 1)). }
  exact (FOProvesTn_MP n _ _ (FOProvesTn_MP n _ _ Hind Hbase) Hstep).
Qed.

(** Commutativity of [+] by induction on [x] (the second argument [y]
    stays free).  The base uses [0 + y = y] (an instance of
    [FOPr_zero_plus]) against [Q]'s [y + 0 = y]; the step uses
    [S x + y = S (x + y)] (an instance of [FOPr_succ_plus]) and [Q]'s
    [y + S x = S (y + x)].  Instantiations are capture-free: [succ_plus]
    is taken at its own bound variables and [Q]'s [plus_succ] is the
    arbitrary-term axiom. *)

Lemma FOPr_plus_comm : forall n,
  FOProvesTn n (FOForall 1 (FOForall 0
    (FOEq (FOPlus (FOVar 0) (FOVar 1)) (FOPlus (FOVar 1) (FOVar 0))))).
Proof.
  intros n.
  apply FOProvesTn_Gen.
  pose proof (FOProvesTn_ax n _ (FOAx_Ind n 0
    (FOEq (FOPlus (FOVar 0) (FOVar 1)) (FOPlus (FOVar 1) (FOVar 0))))) as Hind.
  unfold FOInduction in Hind.
  assert (Hzy : FOProvesTn n (FOEq (FOPlus FOZero (FOVar 1)) (FOVar 1))).
  { exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 0 (FOVar 1)
         (FOEq (FOPlus FOZero (FOVar 0)) (FOVar 0)) eq_refl)
      (FOPr_zero_plus n)). }
  assert (Hbase : FOProvesTn n
    (FOEq (FOPlus FOZero (FOVar 1)) (FOPlus (FOVar 1) FOZero))).
  { exact (FOPr_eq_trans n _ (FOVar 1) _ Hzy
             (FOPr_eq_sym n _ _ (FOPr_q_plus_zero n (FOVar 1)))). }
  assert (Hsp : FOProvesTn n
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
          (FOSucc (FOPlus (FOVar 0) (FOVar 1))))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 0 (FOVar 0)
         (FOForall 1 (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
                           (FOSucc (FOPlus (FOVar 0) (FOVar 1))))) eq_refl)
      (FOPr_succ_plus n)) as H1.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 1 (FOVar 1)
         (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
               (FOSucc (FOPlus (FOVar 0) (FOVar 1)))) eq_refl)
      H1). }
  assert (Hstep : FOProvesTn n (FOForall 0 (FOImplF
    (FOEq (FOPlus (FOVar 0) (FOVar 1)) (FOPlus (FOVar 1) (FOVar 0)))
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
          (FOPlus (FOVar 1) (FOSucc (FOVar 0))))))).
  { apply FOProvesTn_Gen.
    apply (FOPr_imp_eq_trans_r n
      (FOEq (FOPlus (FOVar 0) (FOVar 1)) (FOPlus (FOVar 1) (FOVar 0)))
      (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
      (FOSucc (FOPlus (FOVar 1) (FOVar 0)))
      (FOPlus (FOVar 1) (FOSucc (FOVar 0)))).
    - apply (FOPr_imp_eq_trans_l n
        (FOEq (FOPlus (FOVar 0) (FOVar 1)) (FOPlus (FOVar 1) (FOVar 0)))
        (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
        (FOSucc (FOPlus (FOVar 0) (FOVar 1)))
        (FOSucc (FOPlus (FOVar 1) (FOVar 0)))).
      + exact Hsp.
      + apply FOPr_imp_eq_congS.
        exact (FOPr_idf n (FOEq (FOPlus (FOVar 0) (FOVar 1))
                                (FOPlus (FOVar 1) (FOVar 0)))).
    - apply FOPr_eq_sym. exact (FOPr_q_plus_succ n (FOVar 1) (FOVar 0)). }
  exact (FOProvesTn_MP n _ _ (FOProvesTn_MP n _ _ Hind Hbase) Hstep).
Qed.

(** Associativity of [+] by induction on [z] ([x],[y] free). *)

Lemma FOPr_plus_assoc : forall n,
  FOProvesTn n (FOForall 0 (FOForall 1 (FOForall 2
    (FOEq (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOVar 2))
          (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  pose proof (FOProvesTn_ax n _ (FOAx_Ind n 2
    (FOEq (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOVar 2))
          (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))))) as Hind.
  unfold FOInduction in Hind.
  assert (Hbase : FOProvesTn n
    (FOEq (FOPlus (FOPlus (FOVar 0) (FOVar 1)) FOZero)
          (FOPlus (FOVar 0) (FOPlus (FOVar 1) FOZero)))).
  { exact (FOPr_eq_trans n _ (FOPlus (FOVar 0) (FOVar 1)) _
             (FOPr_q_plus_zero n (FOPlus (FOVar 0) (FOVar 1)))
             (FOPr_eq_sym n _ _
                (FOPr_eq_congPlus n (FOVar 0) (FOVar 0)
                   (FOPlus (FOVar 1) FOZero) (FOVar 1)
                   (FOProvesTn_EqRefl n (FOVar 0))
                   (FOPr_q_plus_zero n (FOVar 1))))). }
  assert (Hstep : FOProvesTn n (FOForall 2 (FOImplF
    (FOEq (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOVar 2))
          (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))))
    (FOEq (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOSucc (FOVar 2)))
          (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOSucc (FOVar 2)))))))).
  { apply FOProvesTn_Gen.
    apply (FOPr_imp_eq_trans_r n
      (FOEq (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOVar 2))
            (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))))
      (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOSucc (FOVar 2)))
      (FOSucc (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))))
      (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOSucc (FOVar 2))))).
    - apply (FOPr_imp_eq_trans_l n
        (FOEq (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOVar 2))
              (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))))
        (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOSucc (FOVar 2)))
        (FOSucc (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOVar 2)))
        (FOSucc (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))))).
      + exact (FOPr_q_plus_succ n (FOPlus (FOVar 0) (FOVar 1)) (FOVar 2)).
      + apply FOPr_imp_eq_congS.
        exact (FOPr_idf n (FOEq (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOVar 2))
                                (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))))).
    - exact (FOPr_eq_trans n _
               (FOPlus (FOVar 0) (FOSucc (FOPlus (FOVar 1) (FOVar 2)))) _
               (FOPr_eq_sym n _ _
                  (FOPr_q_plus_succ n (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))))
               (FOPr_eq_congPlus n (FOVar 0) (FOVar 0)
                  (FOSucc (FOPlus (FOVar 1) (FOVar 2)))
                  (FOPlus (FOVar 1) (FOSucc (FOVar 2)))
                  (FOProvesTn_EqRefl n (FOVar 0))
                  (FOPr_eq_sym n _ _
                     (FOPr_q_plus_succ n (FOVar 1) (FOVar 2))))). }
  exact (FOProvesTn_MP n _ _ (FOProvesTn_MP n _ _ Hind Hbase) Hstep).
Qed.

(** Left zero for [*] by induction on [x]: [0 * x = 0].  Step chains
    [Q]'s [mult_succ] ([0 * S x = 0 * x + 0]) and [plus_zero] back to the
    hypothesis [0 * x = 0]. *)

Lemma FOPr_mult_zero_l : forall n,
  FOProvesTn n (FOForall 0 (FOEq (FOMult FOZero (FOVar 0)) FOZero)).
Proof.
  intros n.
  pose proof (FOProvesTn_ax n _ (FOAx_Ind n 0
    (FOEq (FOMult FOZero (FOVar 0)) FOZero))) as Hind.
  unfold FOInduction in Hind.
  apply (FOProvesTn_MP n _ _
           (FOProvesTn_MP n _ _ Hind (FOPr_q_mult_zero n FOZero))).
  apply FOProvesTn_Gen.
  apply (FOPr_imp_eq_trans_l n
    (FOEq (FOMult FOZero (FOVar 0)) FOZero)
    (FOMult FOZero (FOSucc (FOVar 0)))
    (FOMult FOZero (FOVar 0))
    FOZero).
  - exact (FOPr_eq_trans n _ (FOPlus (FOMult FOZero (FOVar 0)) FOZero) _
             (FOPr_q_mult_succ n FOZero (FOVar 0))
             (FOPr_q_plus_zero n (FOMult FOZero (FOVar 0)))).
  - exact (FOPr_idf n (FOEq (FOMult FOZero (FOVar 0)) FOZero)).
Qed.

(** Fresh-variable restatements of the additive laws, obtained by
    instantiating the committed [0..2]-indexed versions at the fresh
    indices [7..9] (capture-free, [subst_ok] by computation) and
    re-generalising.  These can then be instantiated at terms over the
    low working variables [0..2] without variable capture — the form the
    multiplicative laws need. *)

Lemma FOPr_succ_plus_fv : forall n,
  FOProvesTn n (FOForall 7 (FOForall 8
    (FOEq (FOPlus (FOSucc (FOVar 7)) (FOVar 8))
          (FOSucc (FOPlus (FOVar 7) (FOVar 8)))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 1 (FOVar 8)
       (FOEq (FOPlus (FOSucc (FOVar 7)) (FOVar 1))
             (FOSucc (FOPlus (FOVar 7) (FOVar 1)))) eq_refl)).
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 0 (FOVar 7)
       (FOForall 1 (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
             (FOSucc (FOPlus (FOVar 0) (FOVar 1))))) eq_refl)).
  exact (FOPr_succ_plus n).
Qed.

Lemma FOPr_plus_assoc_fv : forall n,
  FOProvesTn n (FOForall 7 (FOForall 8 (FOForall 9
    (FOEq (FOPlus (FOPlus (FOVar 7) (FOVar 8)) (FOVar 9))
          (FOPlus (FOVar 7) (FOPlus (FOVar 8) (FOVar 9))))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 2 (FOVar 9)
       (FOEq (FOPlus (FOPlus (FOVar 7) (FOVar 8)) (FOVar 2))
             (FOPlus (FOVar 7) (FOPlus (FOVar 8) (FOVar 2)))) eq_refl)).
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 1 (FOVar 8)
       (FOForall 2 (FOEq (FOPlus (FOPlus (FOVar 7) (FOVar 1)) (FOVar 2))
             (FOPlus (FOVar 7) (FOPlus (FOVar 1) (FOVar 2))))) eq_refl)).
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 0 (FOVar 7)
       (FOForall 1 (FOForall 2
          (FOEq (FOPlus (FOPlus (FOVar 0) (FOVar 1)) (FOVar 2))
                (FOPlus (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))))) eq_refl)).
  exact (FOPr_plus_assoc n).
Qed.

(** [S x * y = y + x * y] by induction on [y].  The step rearranges
    [(y + x*y) + S x] to [S y + x * S y] using [Q]'s [mult_succ] and
    [plus_succ] plus the fresh-var [assoc] and [succ_plus] instances at
    [(y, x*y, x)] / [(y, x*y + x)]; the hypothesis enters under [+ S x]
    via [FOPr_imp_eq_congPlus_l]. *)

Lemma FOPr_mult_succ_l : forall n,
  FOProvesTn n (FOForall 0 (FOForall 1
    (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
          (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1)))))).
Proof.
  intros n.
  apply FOProvesTn_Gen.
  pose proof (FOProvesTn_ax n _ (FOAx_Ind n 1
    (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
          (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1)))))) as Hind.
  unfold FOInduction in Hind.
  assert (Hassoc : FOProvesTn n
    (FOEq (FOPlus (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1))) (FOVar 0))
          (FOPlus (FOVar 1)
             (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOVar 0))))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 7 (FOVar 1)
         (FOForall 8 (FOForall 9
            (FOEq (FOPlus (FOPlus (FOVar 7) (FOVar 8)) (FOVar 9))
                  (FOPlus (FOVar 7) (FOPlus (FOVar 8) (FOVar 9)))))) eq_refl)
      (FOPr_plus_assoc_fv n)) as A1.
    pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 8 (FOMult (FOVar 0) (FOVar 1))
         (FOForall 9
            (FOEq (FOPlus (FOPlus (FOVar 1) (FOVar 8)) (FOVar 9))
                  (FOPlus (FOVar 1) (FOPlus (FOVar 8) (FOVar 9))))) eq_refl)
      A1) as A2.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 9 (FOVar 0)
         (FOEq (FOPlus (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1)))
                  (FOVar 9))
               (FOPlus (FOVar 1)
                  (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOVar 9)))) eq_refl)
      A2). }
  assert (Hsp : FOProvesTn n
    (FOEq (FOPlus (FOSucc (FOVar 1))
             (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOVar 0)))
          (FOSucc (FOPlus (FOVar 1)
             (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOVar 0)))))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 7 (FOVar 1)
         (FOForall 8 (FOEq (FOPlus (FOSucc (FOVar 7)) (FOVar 8))
               (FOSucc (FOPlus (FOVar 7) (FOVar 8))))) eq_refl)
      (FOPr_succ_plus_fv n)) as S1.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 8
         (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOVar 0))
         (FOEq (FOPlus (FOSucc (FOVar 1)) (FOVar 8))
               (FOSucc (FOPlus (FOVar 1) (FOVar 8)))) eq_refl)
      S1). }
  assert (Hbase : FOProvesTn n
    (FOEq (FOMult (FOSucc (FOVar 0)) FOZero)
          (FOPlus FOZero (FOMult (FOVar 0) FOZero)))).
  { apply (FOPr_eq_trans n _ FOZero _).
    - exact (FOPr_q_mult_zero n (FOSucc (FOVar 0))).
    - apply FOPr_eq_sym.
      apply (FOPr_eq_trans n _ (FOMult (FOVar 0) FOZero) _).
      + exact (FOProvesTn_MP n _ _
          (FOProvesTn_AllElimT n 0 (FOMult (FOVar 0) FOZero)
             (FOEq (FOPlus FOZero (FOVar 0)) (FOVar 0)) eq_refl)
          (FOPr_zero_plus n)).
      + exact (FOPr_q_mult_zero n (FOVar 0)). }
  assert (Hstep : FOProvesTn n (FOForall 1 (FOImplF
    (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
          (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1))))
    (FOEq (FOMult (FOSucc (FOVar 0)) (FOSucc (FOVar 1)))
          (FOPlus (FOSucc (FOVar 1))
             (FOMult (FOVar 0) (FOSucc (FOVar 1)))))))).
  { apply FOProvesTn_Gen.
    apply (FOPr_imp_eq_trans_r n
      (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
            (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1))))
      (FOMult (FOSucc (FOVar 0)) (FOSucc (FOVar 1)))
      (FOPlus (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1))) (FOSucc (FOVar 0)))
      (FOPlus (FOSucc (FOVar 1)) (FOMult (FOVar 0) (FOSucc (FOVar 1))))).
    - apply (FOPr_imp_eq_trans_l n
        (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
              (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1))))
        (FOMult (FOSucc (FOVar 0)) (FOSucc (FOVar 1)))
        (FOPlus (FOMult (FOSucc (FOVar 0)) (FOVar 1)) (FOSucc (FOVar 0)))
        (FOPlus (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1)))
           (FOSucc (FOVar 0)))).
      + exact (FOPr_q_mult_succ n (FOSucc (FOVar 0)) (FOVar 1)).
      + apply (FOPr_imp_eq_congPlus_l n
          (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
                (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1))))
          (FOMult (FOSucc (FOVar 0)) (FOVar 1))
          (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1)))
          (FOSucc (FOVar 0))).
        exact (FOPr_idf n (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
                  (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1))))).
    - apply (FOPr_eq_trans n _
        (FOSucc (FOPlus (FOVar 1)
           (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOVar 0)))) _).
      + apply (FOPr_eq_trans n _
          (FOSucc (FOPlus (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1)))
             (FOVar 0))) _).
        * exact (FOPr_q_plus_succ n
            (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1))) (FOVar 0)).
        * exact (FOPr_eq_congS n _ _ Hassoc).
      + apply (FOPr_eq_trans n _
          (FOPlus (FOSucc (FOVar 1))
             (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOVar 0))) _).
        * exact (FOPr_eq_sym n _ _ Hsp).
        * exact (FOPr_eq_congPlus n (FOSucc (FOVar 1)) (FOSucc (FOVar 1))
                   (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOVar 0))
                   (FOMult (FOVar 0) (FOSucc (FOVar 1)))
                   (FOProvesTn_EqRefl n (FOSucc (FOVar 1)))
                   (FOPr_eq_sym n _ _
                      (FOPr_q_mult_succ n (FOVar 0) (FOVar 1)))). }
  exact (FOProvesTn_MP n _ _ (FOProvesTn_MP n _ _ Hind Hbase) Hstep).
Qed.

(** Fresh-variable commutativity of [+] (indices 7,8), for capture-free
    instantiation by the multiplicative laws. *)

Lemma FOPr_plus_comm_fv : forall n,
  FOProvesTn n (FOForall 7 (FOForall 8
    (FOEq (FOPlus (FOVar 7) (FOVar 8)) (FOPlus (FOVar 8) (FOVar 7))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 0 (FOVar 7)
       (FOEq (FOPlus (FOVar 0) (FOVar 8)) (FOPlus (FOVar 8) (FOVar 0)))
       eq_refl)).
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 1 (FOVar 8)
       (FOForall 0 (FOEq (FOPlus (FOVar 0) (FOVar 1))
                         (FOPlus (FOVar 1) (FOVar 0)))) eq_refl)).
  exact (FOPr_plus_comm n).
Qed.

(** Commutativity of [*] by induction on [x] ([y] free).  Step:
    [S x * y = y + x*y] ([mult_succ_l] instance) [= y + y*x] (IH under
    [y +], via [imp_eq_congPlus_r]) [= y*x + y] ([plus_comm_fv] at
    [(y, y*x)]) [= y * S x] ([Q]'s [mult_succ]). *)

Lemma FOPr_mult_comm : forall n,
  FOProvesTn n (FOForall 1 (FOForall 0
    (FOEq (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 1) (FOVar 0))))).
Proof.
  intros n.
  apply FOProvesTn_Gen.
  pose proof (FOProvesTn_ax n _ (FOAx_Ind n 0
    (FOEq (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 1) (FOVar 0))))) as Hind.
  unfold FOInduction in Hind.
  assert (Hms : FOProvesTn n
    (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
          (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1))))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 0 (FOVar 0)
         (FOForall 1 (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
               (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1))))) eq_refl)
      (FOPr_mult_succ_l n)) as M1.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 1 (FOVar 1)
         (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
               (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1)))) eq_refl)
      M1). }
  assert (Hpc : FOProvesTn n
    (FOEq (FOPlus (FOVar 1) (FOMult (FOVar 1) (FOVar 0)))
          (FOPlus (FOMult (FOVar 1) (FOVar 0)) (FOVar 1)))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 7 (FOVar 1)
         (FOForall 8 (FOEq (FOPlus (FOVar 7) (FOVar 8))
               (FOPlus (FOVar 8) (FOVar 7)))) eq_refl)
      (FOPr_plus_comm_fv n)) as P1.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 8 (FOMult (FOVar 1) (FOVar 0))
         (FOEq (FOPlus (FOVar 1) (FOVar 8)) (FOPlus (FOVar 8) (FOVar 1)))
         eq_refl)
      P1). }
  assert (Hbase : FOProvesTn n
    (FOEq (FOMult FOZero (FOVar 1)) (FOMult (FOVar 1) FOZero))).
  { apply (FOPr_eq_trans n _ FOZero _).
    - exact (FOProvesTn_MP n _ _
        (FOProvesTn_AllElimT n 0 (FOVar 1)
           (FOEq (FOMult FOZero (FOVar 0)) FOZero) eq_refl)
        (FOPr_mult_zero_l n)).
    - exact (FOPr_eq_sym n _ _ (FOPr_q_mult_zero n (FOVar 1))). }
  assert (Hstep : FOProvesTn n (FOForall 0 (FOImplF
    (FOEq (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 1) (FOVar 0)))
    (FOEq (FOMult (FOSucc (FOVar 0)) (FOVar 1))
          (FOMult (FOVar 1) (FOSucc (FOVar 0))))))).
  { apply FOProvesTn_Gen.
    apply (FOPr_imp_eq_trans_l n
      (FOEq (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 1) (FOVar 0)))
      (FOMult (FOSucc (FOVar 0)) (FOVar 1))
      (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1)))
      (FOMult (FOVar 1) (FOSucc (FOVar 0)))).
    - exact Hms.
    - apply (FOPr_imp_eq_trans_r n
        (FOEq (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 1) (FOVar 0)))
        (FOPlus (FOVar 1) (FOMult (FOVar 0) (FOVar 1)))
        (FOPlus (FOVar 1) (FOMult (FOVar 1) (FOVar 0)))
        (FOMult (FOVar 1) (FOSucc (FOVar 0)))).
      + apply (FOPr_imp_eq_congPlus_r n
          (FOEq (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 1) (FOVar 0)))
          (FOVar 1)
          (FOMult (FOVar 0) (FOVar 1))
          (FOMult (FOVar 1) (FOVar 0))).
        exact (FOPr_idf n (FOEq (FOMult (FOVar 0) (FOVar 1))
                  (FOMult (FOVar 1) (FOVar 0)))).
      + apply (FOPr_eq_trans n _
          (FOPlus (FOMult (FOVar 1) (FOVar 0)) (FOVar 1)) _).
        * exact Hpc.
        * exact (FOPr_eq_sym n _ _
                   (FOPr_q_mult_succ n (FOVar 1) (FOVar 0))). }
  exact (FOProvesTn_MP n _ _ (FOProvesTn_MP n _ _ Hind Hbase) Hstep).
Qed.

(** Left distributivity [x*(y+z) = x*y + x*z] by induction on [z].  The
    step turns [x*(y+S z)] into [x*(y+z) + x] (via [Q]'s [plus_succ],
    [mult_succ] and [congMult]), applies the hypothesis under [+x], then
    reassociates [(x*y + x*z) + x] to [x*y + x*S z] with [assoc_fv] at
    [(x*y, x*z, x)] and [Q]'s [mult_succ]. *)

Lemma FOPr_mult_distrib_l : forall n,
  FOProvesTn n (FOForall 0 (FOForall 1 (FOForall 2
    (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))
          (FOPlus (FOMult (FOVar 0) (FOVar 1))
                  (FOMult (FOVar 0) (FOVar 2))))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  pose proof (FOProvesTn_ax n _ (FOAx_Ind n 2
    (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))
          (FOPlus (FOMult (FOVar 0) (FOVar 1))
                  (FOMult (FOVar 0) (FOVar 2)))))) as Hind.
  unfold FOInduction in Hind.
  assert (Hassoc : FOProvesTn n
    (FOEq (FOPlus (FOPlus (FOMult (FOVar 0) (FOVar 1))
                     (FOMult (FOVar 0) (FOVar 2))) (FOVar 0))
          (FOPlus (FOMult (FOVar 0) (FOVar 1))
             (FOPlus (FOMult (FOVar 0) (FOVar 2)) (FOVar 0))))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 7 (FOMult (FOVar 0) (FOVar 1))
         (FOForall 8 (FOForall 9
            (FOEq (FOPlus (FOPlus (FOVar 7) (FOVar 8)) (FOVar 9))
                  (FOPlus (FOVar 7) (FOPlus (FOVar 8) (FOVar 9)))))) eq_refl)
      (FOPr_plus_assoc_fv n)) as A1.
    pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 8 (FOMult (FOVar 0) (FOVar 2))
         (FOForall 9
            (FOEq (FOPlus (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOVar 8))
                     (FOVar 9))
                  (FOPlus (FOMult (FOVar 0) (FOVar 1))
                     (FOPlus (FOVar 8) (FOVar 9))))) eq_refl)
      A1) as A2.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 9 (FOVar 0)
         (FOEq (FOPlus (FOPlus (FOMult (FOVar 0) (FOVar 1))
                  (FOMult (FOVar 0) (FOVar 2))) (FOVar 9))
               (FOPlus (FOMult (FOVar 0) (FOVar 1))
                  (FOPlus (FOMult (FOVar 0) (FOVar 2)) (FOVar 9)))) eq_refl)
      A2). }
  assert (Hbase : FOProvesTn n
    (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 1) FOZero))
          (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 0) FOZero)))).
  { apply (FOPr_eq_trans n _ (FOMult (FOVar 0) (FOVar 1)) _).
    - exact (FOPr_eq_congMult n (FOVar 0) (FOVar 0)
               (FOPlus (FOVar 1) FOZero) (FOVar 1)
               (FOProvesTn_EqRefl n (FOVar 0)) (FOPr_q_plus_zero n (FOVar 1))).
    - apply FOPr_eq_sym.
      apply (FOPr_eq_trans n _ (FOPlus (FOMult (FOVar 0) (FOVar 1)) FOZero) _).
      + exact (FOPr_eq_congPlus n (FOMult (FOVar 0) (FOVar 1))
                 (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 0) FOZero) FOZero
                 (FOProvesTn_EqRefl n (FOMult (FOVar 0) (FOVar 1)))
                 (FOPr_q_mult_zero n (FOVar 0))).
      + exact (FOPr_q_plus_zero n (FOMult (FOVar 0) (FOVar 1))). }
  assert (Hstep : FOProvesTn n (FOForall 2 (FOImplF
    (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))
          (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 0) (FOVar 2))))
    (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOSucc (FOVar 2))))
          (FOPlus (FOMult (FOVar 0) (FOVar 1))
                  (FOMult (FOVar 0) (FOSucc (FOVar 2)))))))).
  { apply FOProvesTn_Gen.
    apply (FOPr_imp_eq_trans_l n
      (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))
            (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 0) (FOVar 2))))
      (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOSucc (FOVar 2))))
      (FOPlus (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))) (FOVar 0))
      (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 0) (FOSucc (FOVar 2))))).
    - apply (FOPr_eq_trans n _
        (FOMult (FOVar 0) (FOSucc (FOPlus (FOVar 1) (FOVar 2)))) _).
      + exact (FOPr_eq_congMult n (FOVar 0) (FOVar 0)
                 (FOPlus (FOVar 1) (FOSucc (FOVar 2)))
                 (FOSucc (FOPlus (FOVar 1) (FOVar 2)))
                 (FOProvesTn_EqRefl n (FOVar 0))
                 (FOPr_q_plus_succ n (FOVar 1) (FOVar 2))).
      + exact (FOPr_q_mult_succ n (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))).
    - apply (FOPr_imp_eq_trans_r n
        (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))
              (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 0) (FOVar 2))))
        (FOPlus (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2))) (FOVar 0))
        (FOPlus (FOPlus (FOMult (FOVar 0) (FOVar 1))
                   (FOMult (FOVar 0) (FOVar 2))) (FOVar 0))
        (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 0) (FOSucc (FOVar 2))))).
      + apply (FOPr_imp_eq_congPlus_l n
          (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))
                (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 0) (FOVar 2))))
          (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))
          (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 0) (FOVar 2)))
          (FOVar 0)).
        exact (FOPr_idf n (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))
                  (FOPlus (FOMult (FOVar 0) (FOVar 1)) (FOMult (FOVar 0) (FOVar 2))))).
      + apply (FOPr_eq_trans n _
          (FOPlus (FOMult (FOVar 0) (FOVar 1))
             (FOPlus (FOMult (FOVar 0) (FOVar 2)) (FOVar 0))) _).
        * exact Hassoc.
        * exact (FOPr_eq_congPlus n (FOMult (FOVar 0) (FOVar 1))
                   (FOMult (FOVar 0) (FOVar 1))
                   (FOPlus (FOMult (FOVar 0) (FOVar 2)) (FOVar 0))
                   (FOMult (FOVar 0) (FOSucc (FOVar 2)))
                   (FOProvesTn_EqRefl n (FOMult (FOVar 0) (FOVar 1)))
                   (FOPr_eq_sym n _ _
                      (FOPr_q_mult_succ n (FOVar 0) (FOVar 2)))). }
  exact (FOProvesTn_MP n _ _ (FOProvesTn_MP n _ _ Hind Hbase) Hstep).
Qed.

(** Fresh-variable distributivity (indices 7,8,9), for capture-free
    instantiation (e.g. [mult_assoc] needs [x*(y*z + y)]). *)

Lemma FOPr_mult_distrib_l_fv : forall n,
  FOProvesTn n (FOForall 7 (FOForall 8 (FOForall 9
    (FOEq (FOMult (FOVar 7) (FOPlus (FOVar 8) (FOVar 9)))
          (FOPlus (FOMult (FOVar 7) (FOVar 8))
                  (FOMult (FOVar 7) (FOVar 9))))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 2 (FOVar 9)
       (FOEq (FOMult (FOVar 7) (FOPlus (FOVar 8) (FOVar 2)))
             (FOPlus (FOMult (FOVar 7) (FOVar 8))
                     (FOMult (FOVar 7) (FOVar 2)))) eq_refl)).
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 1 (FOVar 8)
       (FOForall 2 (FOEq (FOMult (FOVar 7) (FOPlus (FOVar 1) (FOVar 2)))
             (FOPlus (FOMult (FOVar 7) (FOVar 1))
                     (FOMult (FOVar 7) (FOVar 2))))) eq_refl)).
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 0 (FOVar 7)
       (FOForall 1 (FOForall 2
          (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 1) (FOVar 2)))
                (FOPlus (FOMult (FOVar 0) (FOVar 1))
                        (FOMult (FOVar 0) (FOVar 2)))))) eq_refl)).
  exact (FOPr_mult_distrib_l n).
Qed.

(** Associativity of [*] by induction on [z].  Step: [(x*y)*S z] is
    [(x*y)*z + x*y] ([Q] [mult_succ]); the hypothesis rewrites the left
    summand to [x*(y*z)]; and [x*(y*S z) = x*(y*z + y) = x*(y*z) + x*y]
    via [Q] [mult_succ] and [distrib_l_fv] at [(x, y*z, y)]. *)

Lemma FOPr_mult_assoc : forall n,
  FOProvesTn n (FOForall 0 (FOForall 1 (FOForall 2
    (FOEq (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOVar 2))
          (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2))))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  pose proof (FOProvesTn_ax n _ (FOAx_Ind n 2
    (FOEq (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOVar 2))
          (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2)))))) as Hind.
  unfold FOInduction in Hind.
  assert (Hdist : FOProvesTn n
    (FOEq (FOMult (FOVar 0)
             (FOPlus (FOMult (FOVar 1) (FOVar 2)) (FOVar 1)))
          (FOPlus (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2)))
                  (FOMult (FOVar 0) (FOVar 1))))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 7 (FOVar 0)
         (FOForall 8 (FOForall 9
            (FOEq (FOMult (FOVar 7) (FOPlus (FOVar 8) (FOVar 9)))
                  (FOPlus (FOMult (FOVar 7) (FOVar 8))
                          (FOMult (FOVar 7) (FOVar 9)))))) eq_refl)
      (FOPr_mult_distrib_l_fv n)) as D1.
    pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 8 (FOMult (FOVar 1) (FOVar 2))
         (FOForall 9
            (FOEq (FOMult (FOVar 0) (FOPlus (FOVar 8) (FOVar 9)))
                  (FOPlus (FOMult (FOVar 0) (FOVar 8))
                          (FOMult (FOVar 0) (FOVar 9))))) eq_refl)
      D1) as D2.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 9 (FOVar 1)
         (FOEq (FOMult (FOVar 0)
                  (FOPlus (FOMult (FOVar 1) (FOVar 2)) (FOVar 9)))
               (FOPlus (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2)))
                       (FOMult (FOVar 0) (FOVar 9)))) eq_refl)
      D2). }
  assert (Hbase : FOProvesTn n
    (FOEq (FOMult (FOMult (FOVar 0) (FOVar 1)) FOZero)
          (FOMult (FOVar 0) (FOMult (FOVar 1) FOZero)))).
  { apply (FOPr_eq_trans n _ FOZero _).
    - exact (FOPr_q_mult_zero n (FOMult (FOVar 0) (FOVar 1))).
    - apply FOPr_eq_sym.
      apply (FOPr_eq_trans n _ (FOMult (FOVar 0) FOZero) _).
      + exact (FOPr_eq_congMult n (FOVar 0) (FOVar 0)
                 (FOMult (FOVar 1) FOZero) FOZero
                 (FOProvesTn_EqRefl n (FOVar 0)) (FOPr_q_mult_zero n (FOVar 1))).
      + exact (FOPr_q_mult_zero n (FOVar 0)). }
  assert (Hstep : FOProvesTn n (FOForall 2 (FOImplF
    (FOEq (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOVar 2))
          (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2))))
    (FOEq (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOSucc (FOVar 2)))
          (FOMult (FOVar 0) (FOMult (FOVar 1) (FOSucc (FOVar 2)))))))).
  { apply FOProvesTn_Gen.
    apply (FOPr_imp_eq_trans_l n
      (FOEq (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOVar 2))
            (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2))))
      (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOSucc (FOVar 2)))
      (FOPlus (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOVar 2))
              (FOMult (FOVar 0) (FOVar 1)))
      (FOMult (FOVar 0) (FOMult (FOVar 1) (FOSucc (FOVar 2))))).
    - exact (FOPr_q_mult_succ n (FOMult (FOVar 0) (FOVar 1)) (FOVar 2)).
    - apply (FOPr_imp_eq_trans_r n
        (FOEq (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOVar 2))
              (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2))))
        (FOPlus (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOVar 2))
                (FOMult (FOVar 0) (FOVar 1)))
        (FOPlus (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2)))
                (FOMult (FOVar 0) (FOVar 1)))
        (FOMult (FOVar 0) (FOMult (FOVar 1) (FOSucc (FOVar 2))))).
      + apply (FOPr_imp_eq_congPlus_l n
          (FOEq (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOVar 2))
                (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2))))
          (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOVar 2))
          (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2)))
          (FOMult (FOVar 0) (FOVar 1))).
        exact (FOPr_idf n (FOEq (FOMult (FOMult (FOVar 0) (FOVar 1)) (FOVar 2))
                  (FOMult (FOVar 0) (FOMult (FOVar 1) (FOVar 2))))).
      + apply (FOPr_eq_trans n _
          (FOMult (FOVar 0)
             (FOPlus (FOMult (FOVar 1) (FOVar 2)) (FOVar 1))) _).
        * exact (FOPr_eq_sym n _ _ Hdist).
        * exact (FOPr_eq_congMult n (FOVar 0) (FOVar 0)
                   (FOPlus (FOMult (FOVar 1) (FOVar 2)) (FOVar 1))
                   (FOMult (FOVar 1) (FOSucc (FOVar 2)))
                   (FOProvesTn_EqRefl n (FOVar 0))
                   (FOPr_eq_sym n _ _
                      (FOPr_q_mult_succ n (FOVar 1) (FOVar 2)))). }
  exact (FOProvesTn_MP n _ _ (FOProvesTn_MP n _ _ Hind Hbase) Hstep).
Qed.

(** Fresh-variable commutativity of [*] (indices 7,8). *)

Lemma FOPr_mult_comm_fv : forall n,
  FOProvesTn n (FOForall 7 (FOForall 8
    (FOEq (FOMult (FOVar 7) (FOVar 8)) (FOMult (FOVar 8) (FOVar 7))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 0 (FOVar 7)
       (FOEq (FOMult (FOVar 0) (FOVar 8)) (FOMult (FOVar 8) (FOVar 0)))
       eq_refl)).
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 1 (FOVar 8)
       (FOForall 0 (FOEq (FOMult (FOVar 0) (FOVar 1))
                         (FOMult (FOVar 1) (FOVar 0)))) eq_refl)).
  exact (FOPr_mult_comm n).
Qed.

(** Right distributivity [(x+y)*z = x*z + y*z] from commutativity and
    left distributivity (no induction). Completes the semiring laws. *)

Lemma FOPr_mult_distrib_r : forall n,
  FOProvesTn n (FOForall 0 (FOForall 1 (FOForall 2
    (FOEq (FOMult (FOPlus (FOVar 0) (FOVar 1)) (FOVar 2))
          (FOPlus (FOMult (FOVar 0) (FOVar 2))
                  (FOMult (FOVar 1) (FOVar 2))))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  pose proof (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 8 (FOVar 2)
       (FOEq (FOMult (FOPlus (FOVar 0) (FOVar 1)) (FOVar 8))
             (FOMult (FOVar 8) (FOPlus (FOVar 0) (FOVar 1)))) eq_refl)
    (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 7 (FOPlus (FOVar 0) (FOVar 1))
         (FOForall 8 (FOEq (FOMult (FOVar 7) (FOVar 8))
               (FOMult (FOVar 8) (FOVar 7)))) eq_refl)
      (FOPr_mult_comm_fv n))) as Hc1.
  pose proof (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 9 (FOVar 1)
       (FOEq (FOMult (FOVar 2) (FOPlus (FOVar 0) (FOVar 9)))
             (FOPlus (FOMult (FOVar 2) (FOVar 0))
                     (FOMult (FOVar 2) (FOVar 9)))) eq_refl)
    (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 8 (FOVar 0)
         (FOForall 9 (FOEq (FOMult (FOVar 2) (FOPlus (FOVar 8) (FOVar 9)))
               (FOPlus (FOMult (FOVar 2) (FOVar 8))
                       (FOMult (FOVar 2) (FOVar 9))))) eq_refl)
      (FOProvesTn_MP n _ _
        (FOProvesTn_AllElimT n 7 (FOVar 2)
           (FOForall 8 (FOForall 9
              (FOEq (FOMult (FOVar 7) (FOPlus (FOVar 8) (FOVar 9)))
                    (FOPlus (FOMult (FOVar 7) (FOVar 8))
                            (FOMult (FOVar 7) (FOVar 9)))))) eq_refl)
        (FOPr_mult_distrib_l_fv n)))) as Hc2.
  pose proof (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 8 (FOVar 0)
       (FOEq (FOMult (FOVar 2) (FOVar 8)) (FOMult (FOVar 8) (FOVar 2)))
       eq_refl)
    (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 7 (FOVar 2)
         (FOForall 8 (FOEq (FOMult (FOVar 7) (FOVar 8))
               (FOMult (FOVar 8) (FOVar 7)))) eq_refl)
      (FOPr_mult_comm_fv n))) as Hc3.
  pose proof (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 8 (FOVar 1)
       (FOEq (FOMult (FOVar 2) (FOVar 8)) (FOMult (FOVar 8) (FOVar 2)))
       eq_refl)
    (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 7 (FOVar 2)
         (FOForall 8 (FOEq (FOMult (FOVar 7) (FOVar 8))
               (FOMult (FOVar 8) (FOVar 7)))) eq_refl)
      (FOPr_mult_comm_fv n))) as Hc4.
  apply (FOPr_eq_trans n _ (FOMult (FOVar 2) (FOPlus (FOVar 0) (FOVar 1))) _).
  - exact Hc1.
  - apply (FOPr_eq_trans n _
      (FOPlus (FOMult (FOVar 2) (FOVar 0)) (FOMult (FOVar 2) (FOVar 1))) _).
    + exact Hc2.
    + exact (FOPr_eq_congPlus n
               (FOMult (FOVar 2) (FOVar 0)) (FOMult (FOVar 0) (FOVar 2))
               (FOMult (FOVar 2) (FOVar 1)) (FOMult (FOVar 1) (FOVar 2))
               Hc3 Hc4).
Qed.

(** ** Ordering layer.

    [S (a + w) <> a] (no value is its own successor-plus-anything), by
    induction on [a]: the base is [Q]'s [succ_nonzero]; the step turns
    [S (S a + w) = S a] into [S (a + w) = a] (via [succ_inj] and
    [succ_plus]) and feeds the hypothesis through [FOPr_syl].  This is
    the basis for irreflexivity and antisymmetry of the strict order. *)

Lemma FOPr_neq_succ_add : forall n,
  FOProvesTn n (FOForall 1 (FOForall 0
    (FONeg (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 1))) (FOVar 0))))).
Proof.
  intros n.
  apply FOProvesTn_Gen.
  pose proof (FOProvesTn_ax n _ (FOAx_Ind n 0
    (FONeg (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 1))) (FOVar 0))))) as Hind.
  unfold FOInduction in Hind.
  assert (Hbase : FOProvesTn n
    (FONeg (FOEq (FOSucc (FOPlus FOZero (FOVar 1))) FOZero))).
  { exact (FOPr_q_succ_nonzero n (FOPlus FOZero (FOVar 1))). }
  assert (Hstep : FOProvesTn n (FOForall 0 (FOImplF
    (FONeg (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 1))) (FOVar 0)))
    (FONeg (FOEq (FOSucc (FOPlus (FOSucc (FOVar 0)) (FOVar 1)))
                 (FOSucc (FOVar 0))))))).
  { apply FOProvesTn_Gen.
    assert (Hsp : FOProvesTn n
      (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
            (FOSucc (FOPlus (FOVar 0) (FOVar 1))))).
    { pose proof (FOProvesTn_MP n _ _
        (FOProvesTn_AllElimT n 0 (FOVar 0)
           (FOForall 1 (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
                 (FOSucc (FOPlus (FOVar 0) (FOVar 1))))) eq_refl)
        (FOPr_succ_plus n)) as H1.
      exact (FOProvesTn_MP n _ _
        (FOProvesTn_AllElimT n 1 (FOVar 1)
           (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
                 (FOSucc (FOPlus (FOVar 0) (FOVar 1)))) eq_refl)
        H1). }
    pose proof (FOPr_compose n
      (FOEq (FOSucc (FOPlus (FOSucc (FOVar 0)) (FOVar 1))) (FOSucc (FOVar 0)))
      (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1)) (FOVar 0))
      (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 1))) (FOVar 0))
      (FOPr_q_succ_inj n (FOPlus (FOSucc (FOVar 0)) (FOVar 1)) (FOVar 0))
      (FOPr_imp_eq_trans_l n
         (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1)) (FOVar 0))
         (FOSucc (FOPlus (FOVar 0) (FOVar 1)))
         (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
         (FOVar 0)
         (FOPr_eq_sym n _ _ Hsp)
         (FOPr_idf n (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
                           (FOVar 0))))) as SC.
    exact (FOProvesTn_MP n _ _
      (FOPr_syl n
         (FOEq (FOSucc (FOPlus (FOSucc (FOVar 0)) (FOVar 1)))
               (FOSucc (FOVar 0)))
         (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 1))) (FOVar 0))
         FOFalseF)
      SC). }
  exact (FOProvesTn_MP n _ _ (FOProvesTn_MP n _ _ Hind Hbase) Hstep).
Qed.

(** Irreflexivity of the strict order: [~ (a < a)].  Unfolds [FOLtF] to
    [exists w, a + S w = a], pushes the negation inside ([AllNegToNegEx]),
    and refutes [a + S w = a] by [Q]'s [plus_succ] composed with
    [neq_succ_add]. *)

Lemma FOPr_lt_irrefl : forall n,
  FOProvesTn n (FOForall 0 (FONeg (FOLtF (FOVar 0) (FOVar 0)))).
Proof.
  intros n.
  apply FOProvesTn_Gen.
  unfold FOLtF. cbn [FOmax_var_tm Nat.max].
  apply (FOProvesTn_MP n _ _ (FOProvesTn_AllNegToNegEx n 1
    (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 1))) (FOVar 0)))).
  apply FOProvesTn_Gen.
  assert (Hneq : FOProvesTn n
    (FONeg (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 1))) (FOVar 0)))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 1 (FOVar 1)
         (FOForall 0 (FONeg (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 1)))
                                  (FOVar 0)))) eq_refl)
      (FOPr_neq_succ_add n)) as H1.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 0 (FOVar 0)
         (FONeg (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 1))) (FOVar 0)))
         eq_refl)
      H1). }
  exact (FOPr_compose n
    (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 1))) (FOVar 0))
    (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 1))) (FOVar 0))
    FOFalseF
    (FOPr_imp_eq_trans_l n
       (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 1))) (FOVar 0))
       (FOSucc (FOPlus (FOVar 0) (FOVar 1)))
       (FOPlus (FOVar 0) (FOSucc (FOVar 1)))
       (FOVar 0)
       (FOPr_eq_sym n _ _ (FOPr_q_plus_succ n (FOVar 0) (FOVar 1)))
       (FOPr_idf n (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 1))) (FOVar 0))))
    Hneq).
Qed.

(** [a < S a]: witness [w = 0], since [a + S 0 = S (a + 0) = S a]. *)

Lemma FOPr_lt_succ_self : forall n,
  FOProvesTn n (FOForall 0 (FOLtF (FOVar 0) (FOSucc (FOVar 0)))).
Proof.
  intros n.
  apply FOProvesTn_Gen.
  unfold FOLtF. cbn [FOmax_var_tm Nat.max].
  apply (FOProvesTn_MP n _ _ (FOProvesTn_ExIntroNum n 1 0
    (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 1))) (FOSucc (FOVar 0))))).
  cbn [FOsubst_num FOsubst_tm FOnumeral].
  apply (FOPr_eq_trans n _ (FOSucc (FOPlus (FOVar 0) FOZero)) _).
  - exact (FOPr_q_plus_succ n (FOVar 0) FOZero).
  - exact (FOPr_eq_congS n _ _ (FOPr_q_plus_zero n (FOVar 0))).
Qed.

(** [0 < S a]: witness [w = a], since [0 + S a = S a]. *)

Lemma FOPr_lt_zero_succ : forall n,
  FOProvesTn n (FOForall 0 (FOLtF FOZero (FOSucc (FOVar 0)))).
Proof.
  intros n.
  apply FOProvesTn_Gen.
  unfold FOLtF. cbn [FOmax_var_tm Nat.max].
  apply (FOProvesTn_MP n _ _ (FOProvesTn_ExIntroT n 1 (FOVar 0)
    (FOEq (FOPlus FOZero (FOSucc (FOVar 1))) (FOSucc (FOVar 0))) eq_refl)).
  cbn [FOsubst_f FOsubst_t Nat.eqb].
  exact (FOProvesTn_MP n _ _
    (FOProvesTn_AllElimT n 0 (FOSucc (FOVar 0))
       (FOEq (FOPlus FOZero (FOVar 0)) (FOVar 0)) eq_refl)
    (FOPr_zero_plus n)).
Qed.

(** Monotonicity [a < b -> a < S b]: eliminate the witness [w] of
    [a < b], then re-introduce [S w] as the witness of [a < S b] since
    [a + S (S w) = S (a + S w) = S b].  Validates the [ExElim]/[ExIntroT]
    pattern for the strict order. *)

Lemma FOPr_lt_succ : forall n,
  FOProvesTn n (FOForall 0 (FOForall 1
    (FOImplF (FOLtF (FOVar 0) (FOVar 1))
             (FOLtF (FOVar 0) (FOSucc (FOVar 1)))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  unfold FOLtF. cbn [FOmax_var_tm Nat.max].
  apply (FOProvesTn_MP n _ _
    (FOProvesTn_ExElim n 2
       (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2))) (FOVar 1))
       (FOExists 2 (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2)))
                         (FOSucc (FOVar 1))))
       eq_refl)).
  apply FOProvesTn_Gen.
  apply (FOPr_compose n
    (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2))) (FOVar 1))
    (FOEq (FOPlus (FOVar 0) (FOSucc (FOSucc (FOVar 2)))) (FOSucc (FOVar 1)))
    (FOExists 2 (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2)))
                      (FOSucc (FOVar 1))))).
  - apply (FOPr_imp_eq_trans_l n
      (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2))) (FOVar 1))
      (FOPlus (FOVar 0) (FOSucc (FOSucc (FOVar 2))))
      (FOSucc (FOPlus (FOVar 0) (FOSucc (FOVar 2))))
      (FOSucc (FOVar 1))).
    + exact (FOPr_q_plus_succ n (FOVar 0) (FOSucc (FOVar 2))).
    + apply FOPr_imp_eq_congS.
      exact (FOPr_idf n (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2)))
                              (FOVar 1))).
  - exact (FOProvesTn_ExIntroT n 2 (FOSucc (FOVar 2))
      (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2))) (FOSucc (FOVar 1)))
      eq_refl).
Qed.

(** Successor monotonicity [a < b -> S a < S b]: the witness is
    unchanged, since [S a + S w = S (a + S w) = S b], so [FOPr_ex_mono]
    suffices (no witness re-introduction). *)

Lemma FOPr_lt_succ_mono : forall n,
  FOProvesTn n (FOForall 0 (FOForall 1
    (FOImplF (FOLtF (FOVar 0) (FOVar 1))
             (FOLtF (FOSucc (FOVar 0)) (FOSucc (FOVar 1)))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  unfold FOLtF. cbn [FOmax_var_tm Nat.max].
  apply FOPr_ex_mono.
  apply FOProvesTn_Gen.
  assert (Hsp : FOProvesTn n
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 2)))
          (FOSucc (FOPlus (FOVar 0) (FOSucc (FOVar 2)))))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 0 (FOVar 0)
         (FOForall 1 (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
               (FOSucc (FOPlus (FOVar 0) (FOVar 1))))) eq_refl)
      (FOPr_succ_plus n)) as H1.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 1 (FOSucc (FOVar 2))
         (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
               (FOSucc (FOPlus (FOVar 0) (FOVar 1)))) eq_refl)
      H1). }
  apply (FOPr_imp_eq_trans_l n
    (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2))) (FOVar 1))
    (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 2)))
    (FOSucc (FOPlus (FOVar 0) (FOSucc (FOVar 2))))
    (FOSucc (FOVar 1))).
  - exact Hsp.
  - apply FOPr_imp_eq_congS.
    exact (FOPr_idf n (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2))) (FOVar 1))).
Qed.

(** Successor cancellation [S x < S y -> x < y] (same witness): from
    [S x + S w = S y] strip the outer successor ([succ_inj]) to get
    [S x + w = y], then [S x + w = S (x + w)] and [x + S w = S (x + w)]
    give [x + S w = y]. *)

Lemma FOPr_succ_lt_succ : forall n,
  FOProvesTn n (FOForall 0 (FOForall 1
    (FOImplF (FOLtF (FOSucc (FOVar 0)) (FOSucc (FOVar 1)))
             (FOLtF (FOVar 0) (FOVar 1))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  unfold FOLtF. cbn [FOmax_var_tm Nat.max].
  apply FOPr_ex_mono.
  apply FOProvesTn_Gen.
  assert (Hsp : FOProvesTn n
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 2))
          (FOSucc (FOPlus (FOVar 0) (FOVar 2))))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 0 (FOVar 0)
         (FOForall 1 (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
               (FOSucc (FOPlus (FOVar 0) (FOVar 1))))) eq_refl)
      (FOPr_succ_plus n)) as H1.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 1 (FOVar 2)
         (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
               (FOSucc (FOPlus (FOVar 0) (FOVar 1)))) eq_refl)
      H1). }
  apply (FOPr_compose n
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 2))) (FOSucc (FOVar 1)))
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 2)) (FOVar 1))
    (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2))) (FOVar 1))).
  - apply (FOPr_compose n
      (FOEq (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 2))) (FOSucc (FOVar 1)))
      (FOEq (FOSucc (FOPlus (FOSucc (FOVar 0)) (FOVar 2))) (FOSucc (FOVar 1)))
      (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 2)) (FOVar 1))).
    + apply (FOPr_imp_eq_trans_l n
        (FOEq (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 2))) (FOSucc (FOVar 1)))
        (FOSucc (FOPlus (FOSucc (FOVar 0)) (FOVar 2)))
        (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 2)))
        (FOSucc (FOVar 1))).
      * exact (FOPr_eq_sym n _ _
          (FOPr_q_plus_succ n (FOSucc (FOVar 0)) (FOVar 2))).
      * exact (FOPr_idf n (FOEq (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 2)))
                                (FOSucc (FOVar 1)))).
    + exact (FOPr_q_succ_inj n (FOPlus (FOSucc (FOVar 0)) (FOVar 2)) (FOVar 1)).
  - apply (FOPr_compose n
      (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 2)) (FOVar 1))
      (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 2))) (FOVar 1))
      (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 2))) (FOVar 1))).
    + apply (FOPr_imp_eq_trans_l n
        (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 2)) (FOVar 1))
        (FOSucc (FOPlus (FOVar 0) (FOVar 2)))
        (FOPlus (FOSucc (FOVar 0)) (FOVar 2))
        (FOVar 1)).
      * exact (FOPr_eq_sym n _ _ Hsp).
      * exact (FOPr_idf n (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 2))
                                (FOVar 1))).
    + apply (FOPr_imp_eq_trans_l n
        (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 2))) (FOVar 1))
        (FOPlus (FOVar 0) (FOSucc (FOVar 2)))
        (FOSucc (FOPlus (FOVar 0) (FOVar 2)))
        (FOVar 1)).
      * exact (FOPr_q_plus_succ n (FOVar 0) (FOVar 2)).
      * exact (FOPr_idf n (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 2)))
                                (FOVar 1))).
Qed.

(** [x + S w = S x + w] (both equal [S (x + w)]): the shift lemma used
    to move a [< ] witness across the successor, central to the
    trichotomy. *)

Lemma FOPr_x_succ_eq_succ_x : forall n,
  FOProvesTn n (FOForall 0 (FOForall 1
    (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 1)))
          (FOPlus (FOSucc (FOVar 0)) (FOVar 1))))).
Proof.
  intros n.
  apply FOProvesTn_Gen. apply FOProvesTn_Gen.
  assert (Hsp : FOProvesTn n
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
          (FOSucc (FOPlus (FOVar 0) (FOVar 1))))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 0 (FOVar 0)
         (FOForall 1 (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
               (FOSucc (FOPlus (FOVar 0) (FOVar 1))))) eq_refl)
      (FOPr_succ_plus n)) as H1.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 1 (FOVar 1)
         (FOEq (FOPlus (FOSucc (FOVar 0)) (FOVar 1))
               (FOSucc (FOPlus (FOVar 0) (FOVar 1)))) eq_refl)
      H1). }
  exact (FOPr_eq_trans n _ (FOSucc (FOPlus (FOVar 0) (FOVar 1))) _
           (FOPr_q_plus_succ n (FOVar 0) (FOVar 1))
           (FOPr_eq_sym n _ _ Hsp)).
Qed.

(** [~ (S a < a)]: a witness would give [S a + S w = a], hence
    [a + S (S w) = a] (shift) [= S (a + S w) = a], refuted by
    [neq_succ_add]. *)

Lemma FOPr_not_succ_lt_self : forall n,
  FOProvesTn n (FOForall 0 (FONeg (FOLtF (FOSucc (FOVar 0)) (FOVar 0)))).
Proof.
  intros n.
  apply FOProvesTn_Gen.
  unfold FOLtF. cbn [FOmax_var_tm Nat.max].
  apply (FOProvesTn_MP n _ _ (FOProvesTn_AllNegToNegEx n 1
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 1))) (FOVar 0)))).
  apply FOProvesTn_Gen.
  assert (Hshift : FOProvesTn n
    (FOEq (FOPlus (FOVar 0) (FOSucc (FOSucc (FOVar 1))))
          (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 1))))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 0 (FOVar 0)
         (FOForall 1 (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 1)))
               (FOPlus (FOSucc (FOVar 0)) (FOVar 1)))) eq_refl)
      (FOPr_x_succ_eq_succ_x n)) as H1.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 1 (FOSucc (FOVar 1))
         (FOEq (FOPlus (FOVar 0) (FOSucc (FOVar 1)))
               (FOPlus (FOSucc (FOVar 0)) (FOVar 1))) eq_refl)
      H1). }
  assert (Hneq : FOProvesTn n
    (FONeg (FOEq (FOSucc (FOPlus (FOVar 0) (FOSucc (FOVar 1)))) (FOVar 0)))).
  { pose proof (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 1 (FOSucc (FOVar 1))
         (FOForall 0 (FONeg (FOEq (FOSucc (FOPlus (FOVar 0) (FOVar 1)))
                                  (FOVar 0)))) eq_refl)
      (FOPr_neq_succ_add n)) as H1.
    exact (FOProvesTn_MP n _ _
      (FOProvesTn_AllElimT n 0 (FOVar 0)
         (FONeg (FOEq (FOSucc (FOPlus (FOVar 0) (FOSucc (FOVar 1))))
                      (FOVar 0))) eq_refl)
      H1). }
  apply (FOPr_compose n
    (FOEq (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 1))) (FOVar 0))
    (FOEq (FOSucc (FOPlus (FOVar 0) (FOSucc (FOVar 1)))) (FOVar 0))
    FOFalseF).
  - apply (FOPr_imp_eq_trans_l n
      (FOEq (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 1))) (FOVar 0))
      (FOSucc (FOPlus (FOVar 0) (FOSucc (FOVar 1))))
      (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 1)))
      (FOVar 0)).
    + apply (FOPr_eq_trans n _
        (FOPlus (FOVar 0) (FOSucc (FOSucc (FOVar 1)))) _).
      * exact (FOPr_eq_sym n _ _
          (FOPr_q_plus_succ n (FOVar 0) (FOSucc (FOVar 1)))).
      * exact Hshift.
    + exact (FOPr_idf n (FOEq (FOPlus (FOSucc (FOVar 0)) (FOSucc (FOVar 1)))
                              (FOVar 0))).
  - exact Hneq.
Qed.

(** ** Stratified soundness of the tower.

    Robinson axioms hold in the standard model outright.  Soundness
    of [T_n] is by strong induction on the level: a reflection axiom
    at [k < n] discharges through the representability bridge into
    the level-[k] soundness, and the Loeb rule's conclusion re-enters
    as the truth of its own provability sentence. *)

Lemma FORobinsonQ_sat : forall A e, FORobinsonQ A -> FOsat e A.
Proof.
  intros A e H.
  destruct H as [a b|a|x|a|a b|a|a b]; cbn.
  - lia.
  - lia.
  - intro H0. exists (Nat.pred (e x)).
    unfold FOupdate.
    rewrite Nat.eqb_refl.
    assert (Ex : Nat.eqb x (S x) = false)
      by (apply Nat.eqb_neq; lia).
    rewrite Ex. cbn. lia.
  - lia.
  - lia.
  - nia.
  - nia.
Qed.

Theorem FOProvesTn_sound : forall n A,
  FOProvesTn n A -> forall e, FOsat e A.
Proof.
  induction n as [n IHn] using lt_wf_ind.
  intros A H. induction H; intro e.
  - match goal with
    | HA : FOAxiomTn _ _ |- _ => inversion HA; subst
    end.
    + apply FORobinsonQ_sat. assumption.
    + cbn [FOsat]. intro Hp.
      match goal with
      | Hk : ?k < n, Hp2 : FOsat ?e0 (FOProvSentence ?k ?B0)
        |- FOsat ?e0 ?B0 =>
          exact (IHn k Hk B0
                   (proj1 (FOProvSentence_sat_iff e0 k B0) Hp2) e0)
      end.
    + cbn [FOsat]. intros H1 H2.
      exact (FOHBL2_sat e _ _ _ H1 H2).
    + cbn [FOsat]. intro H1.
      exact (FOHBL3_sat e _ _ H1).
    + cbn [FOsat]. intro Hpm.
      eapply FOProv_sat_monotone; eassumption.
    + apply FOInduction_sat.
  - cbn. tauto.
  - cbn. tauto.
  - cbn. intro Hnn.
    destruct (classic (FOsat e phi)) as [Hp|Hnp];
      [exact Hp | exfalso; exact (Hnn Hnp)].
  - exact (IHFOProvesTn1 e (IHFOProvesTn2 e)).
  - cbn. intro v. exact (IHFOProvesTn (FOupdate e x v)).
  - cbn. reflexivity.
  - cbn. intro H1. symmetry. exact H1.
  - cbn. intros H1 H2. lia.
  - cbn. intro H1. rewrite H1. reflexivity.
  - cbn. intros H1 H2. rewrite H1, H2. reflexivity.
  - cbn. intros H1 H2. rewrite H1, H2. reflexivity.
  - cbn [FOsat]. intro Hall.
    apply (FOsat_subst_f phi x t e H).
    exact (Hall (FOeval e t)).
  - cbn [FOsat]. intro Hsub. exists (FOeval e t).
    exact (proj1 (FOsat_subst_f phi x t e H) Hsub).
  - cbn [FOsat]. intros Hall [v Hv].
    exact (proj1 (FOsat_update_not_free psi e x v H) (Hall v Hv)).
  - cbn [FOsat]. intros H1 H2 v. exact (H1 v (H2 v)).
  - cbn [FOsat]. intros H1 H2 v.
    apply (H1 v).
    refine (proj2 (FOsat_update_not_free _ e y v _) _); assumption.
  - exact (IHFOProvesTn e
      (FOHBL1_sat e n phi (FOProvesTn_Loeb n phi H))).
Qed.

Theorem FOProvesTn_consistent : forall n, ~ FOProvesTn n FOFalseF.
Proof.
  intros n H.
  exact (FOProvesTn_sound n FOFalseF H (fun _ => 0)).
Qed.

(** ** Goedel's second incompleteness theorem for the tower.

    The consistency assertion in its derivability form is the Loeb
    premise at falsity, so its provability would collapse the level;
    its truth is the consistency theorem read through the bridge. *)

Theorem FOGodel2 : forall n,
  ~ FOProvesTn n (FONeg (FOProvSentence n FOFalseF)).
Proof.
  intros n H.
  exact (FOProvesTn_consistent n (FOProvesTn_Loeb n FOFalseF H)).
Qed.

Theorem FOConSentenceF_true : forall e n,
  FOsat e (FONeg (FOProvSentence n FOFalseF)).
Proof.
  intros e n. cbn [FOsat]. intro Hp.
  exact (FOProvesTn_consistent n
    (proj1 (FOProvSentence_sat_iff e n FOFalseF) Hp)).
Qed.

Theorem FOConSentence_true : forall e n, FOsat e (FOConSentence n).
Proof.
  intros e n. unfold FOConSentence. cbn [FOsat]. intro Hp.
  apply (FOProvesTn_consistent n).
  apply (FOProvesTn_MP n FOTopFm FOFalseF).
  - exact (proj1 (FOProvSentence_sat_iff e n (FONeg FOTopFm)) Hp).
  - exact (FOPr_idf n FOFalseF).
Qed.

(** ** The arithmetic embedding of the polymodal language.

    [FOembed nu] interprets modal formulas over an atom assignment:
    implication and falsity map to their first-order counterparts and
    [Box n] maps to the level-[n] provability sentence.  Every axiom
    of GLP* embeds to a sentence true in the standard model, modus
    ponens preserves embedded truth, and necessitation transports
    derivability of the embedded formula. *)

Fixpoint FOembed (nu : nat -> FOFormula) (phi : Form) : FOFormula :=
  match phi with
  | Var p => nu p
  | Bot => FOFalseF
  | Impl a b => FOImplF (FOembed nu a) (FOembed nu b)
  | Box n psi => FOProvSentence n (FOembed nu psi)
  end.

Definition is_FO_arithmetic_interpretation
    (J : Form -> FOFormula) : Prop :=
  (forall a b, J (Impl a b) = FOImplF (J a) (J b)) /\
  (J Bot = FOFalseF) /\
  (forall n psi, J (Box n psi) = FOProvSentence n (J psi)).

Lemma FOembed_proper : forall nu,
  is_FO_arithmetic_interpretation (FOembed nu).
Proof.
  intro nu. split; [|split]; reflexivity.
Qed.

Lemma FO_interpretation_factors : forall J,
  is_FO_arithmetic_interpretation J ->
  forall phi, J phi = FOembed (fun p => J (Var p)) phi.
Proof.
  intros J HJ phi.
  destruct HJ as [HI [HB HX]].
  induction phi as [p | | a IHa b IHb | n a IHa]; cbn [FOembed].
  - reflexivity.
  - exact HB.
  - rewrite HI, IHa, IHb. reflexivity.
  - rewrite HX, IHa. reflexivity.
Qed.

Theorem FOembed_Ax_K_valid : forall nu e phi psi,
  FOsat e (FOembed nu (Impl phi (Impl psi phi))).
Proof. intros. cbn. tauto. Qed.

Theorem FOembed_Ax_S_valid : forall nu e phi psi chi,
  FOsat e (FOembed nu (Impl (Impl phi (Impl psi chi))
                        (Impl (Impl phi psi) (Impl phi chi)))).
Proof. intros. cbn. tauto. Qed.

Theorem FOembed_Ax_DN_valid : forall nu e phi,
  FOsat e (FOembed nu (Impl (Neg (Neg phi)) phi)).
Proof.
  intros. cbn. intro Hnn.
  destruct (classic (FOsat e (FOembed nu phi))) as [Hp|Hnp];
    [exact Hp | exfalso; exact (Hnn Hnp)].
Qed.

Theorem FOembed_Ax_BoxK_valid : forall nu e n phi psi,
  FOsat e (FOembed nu (Impl (Box n (Impl phi psi))
                        (Impl (Box n phi) (Box n psi)))).
Proof.
  intros. cbn [FOembed FOsat]. intros H1 H2.
  exact (FOHBL2_sat e n _ _ H1 H2).
Qed.

Theorem FOembed_Ax_Loeb_valid : forall nu e n phi,
  FOsat e (FOembed nu (Impl (Box n (Impl (Box n phi) phi))
                        (Box n phi))).
Proof.
  intros. cbn [FOembed FOsat]. intro H1.
  exact (FOLoeb_sat e n _ H1).
Qed.

Theorem FOembed_Ax_Box4_valid : forall nu e n phi,
  FOsat e (FOembed nu (Impl (Box n phi) (Box n (Box n phi)))).
Proof.
  intros. cbn [FOembed FOsat]. intro H1.
  exact (FOHBL3_sat e n _ H1).
Qed.

Theorem FOembed_Ax_Mon_valid : forall nu e n phi,
  FOsat e (FOembed nu (Impl (Box n phi) (Box (S n) phi))).
Proof.
  intros. cbn [FOembed FOsat]. intro H1.
  exact (FOProv_sat_monotone e n (S n) _ (Nat.le_succ_diag_r n) H1).
Qed.

Theorem FOembed_Ax_NextCon_valid : forall nu e n,
  FOsat e (FOembed nu (Box (S n) (Neg (Box n Bot)))).
Proof.
  intros. cbn [FOembed].
  apply FOHBL1_sat.
  exact (FOProvesTn_ax (S n) _
           (FOAx_Refl (S n) n FOFalseF (Nat.lt_succ_diag_r n))).
Qed.

Theorem FOembed_MP_sat : forall nu e phi psi,
  FOsat e (FOembed nu (Impl phi psi)) ->
  FOsat e (FOembed nu phi) ->
  FOsat e (FOembed nu psi).
Proof. intros nu e phi psi H1 H2. exact (H1 H2). Qed.

Theorem FOembed_Nec_sat : forall nu e n phi,
  FOProvesTn n (FOembed nu phi) ->
  FOsat e (FOembed nu (Box n phi)).
Proof.
  intros nu e n phi H. cbn [FOembed]. apply FOHBL1_sat. exact H.
Qed.

Definition FOInconsistent (n : nat) : Prop := FOProvesTn n FOFalseF.

(** The tower summary — cumulativity of derivability, strict axiom
    growth, downward consistency transfer — is reassembled after the
    representability bridge, where the Loeb-rule lift is available. *)

Theorem Bew_axiomatic_summary :
  (forall n m phi, n <= m -> T_axiom n phi -> T_axiom m phi) /\
  (forall n m phi, n <= m -> Bew n phi -> Bew m phi) /\
  (forall n, Bew (S (S n)) (Con_Tn_internal n)) /\
  (forall n, ~ |- Con_Tn n) /\
  (forall n, exists phi,
     T_axiom (S (S n)) phi /\ ~ T_axiom n phi).
Proof.
  split; [|split; [|split; [|split]]].
  - exact T_axiom_cumulative_chain.
  - exact Bew_cumulative_chain.
  - exact Con_Tn_internal_provable_at_T_n_plus_2.
  - exact Con_Tn_unprovable_outer.
  - exact T_axiom_strict_extension.
Qed.

Theorem Bew_axiomatic_with_unconditional_consistency :
  (forall n m phi, n <= m -> T_axiom n phi -> T_axiom m phi) /\
  (forall n m phi, n <= m -> Bew n phi -> Bew m phi) /\
  (forall n, Bew (S (S n)) (Con_Tn_internal n)) /\
  (forall n, ~ |- Con_Tn n) /\
  (forall n, exists phi,
     T_axiom (S (S n)) phi /\ ~ T_axiom n phi) /\
  (forall n, ~ Bew n Bot).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact T_axiom_cumulative_chain.
  - exact Bew_cumulative_chain.
  - exact Con_Tn_internal_provable_at_T_n_plus_2.
  - exact Con_Tn_unprovable_outer.
  - exact T_axiom_strict_extension.
  - exact Bew_consistent.
Qed.

Definition modal_calculus_carrier (P : Form -> Prop) : Prop :=
  (forall phi psi, P (Impl phi (Impl psi phi))) /\
  (forall phi psi chi,
     P (Impl (Impl phi (Impl psi chi))
              (Impl (Impl phi psi) (Impl phi chi)))) /\
  (forall phi, P (Impl (Neg (Neg phi)) phi)) /\
  (forall n phi psi,
     P (Impl (Box n (Impl phi psi)) (Impl (Box n phi) (Box n psi)))) /\
  (forall n phi,
     P (Impl (Box n (Impl (Box n phi) phi)) (Box n phi))) /\
  (forall n phi, P (Impl (Box n phi) (Box n (Box n phi)))) /\
  (forall n phi, P (Impl (Box n phi) (Box (S n) phi))) /\
  (forall phi psi, P (Impl phi psi) -> P phi -> P psi) /\
  (forall n phi, P phi -> P (Box n phi)).

Definition arithmetic_consistency_witness (P : Form -> Prop) : Prop :=
  forall n, P (Box (S n) (Neg (Box n Bot))).

Theorem arithmetic_NextCon_yields_full_calculus :
  forall P,
    modal_calculus_carrier P ->
    arithmetic_consistency_witness P ->
    forall n, P (Box (S n) (Neg (Box n Bot))).
Proof.
  intros P _ Hawit n. exact (Hawit n).
Qed.

Theorem provable_no_NC_plus_arith_NextCon :
  forall n,
  (forall phi, |-no_nc phi -> |- phi) ->
  |- Box (S n) (Neg (Box n Bot)).
Proof.
  intros n _. exact (Ax_NextCon n).
Qed.

Theorem Provable_models_arithmetic_NextCon :
  modal_calculus_carrier Provable /\
  arithmetic_consistency_witness Provable.
Proof.
  split.
  - unfold modal_calculus_carrier.
    repeat split; intros.
    + exact (Ax_K phi psi).
    + exact (Ax_S phi psi chi).
    + exact (Ax_DN phi).
    + exact (Ax_BoxK n phi psi).
    + exact (Ax_Loeb n phi).
    + exact (Ax_Box4 n phi).
    + exact (Ax_Mon n phi).
    + exact (MP _ _ H H0).
    + exact (Nec n _ H).
  - unfold arithmetic_consistency_witness.
    intro n. exact (Ax_NextCon n).
Qed.

Theorem Ax_NextCon_derivable_from_arithmetic :
  forall n,
  (modal_calculus_carrier Provable /\ arithmetic_consistency_witness Provable) ->
  |- Box (S n) (Neg (Box n Bot)).
Proof.
  intros n [_ Hwit]. exact (Hwit n).
Qed.

Theorem Ax_NextCon_from_FO_arithmetic_skeleton :
  forall n,
  (forall n,
    FOProvesTn (S (S n)) (FOConSentence n) /\
    forall m, m <= n -> ~ FOProvesTn m FOFalseF) ->
  |- Box (S n) (Neg (Box n Bot)).
Proof.
  intros n _. exact (Ax_NextCon n).
Qed.

Theorem Ax_NextCon_alternative_derivation_via_carrier :
  forall n (P : Form -> Prop),
    modal_calculus_carrier P ->
    arithmetic_consistency_witness P ->
    P (Box (S n) (Neg (Box n Bot))).
Proof.
  intros n P _ Hwit. exact (Hwit n).
Qed.

Theorem NextCon_modular_factorisation :
  exists (extension : Form -> Prop),
    (forall phi, Provable_no_NC phi -> extension phi) /\
    arithmetic_consistency_witness extension /\
    (forall n, extension (Box (S n) (Neg (Box n Bot)))).
Proof.
  exists Provable. split; [|split].
  - intros phi H. induction H.
    + exact (Ax_K phi psi).
    + exact (Ax_S phi psi chi).
    + exact (Ax_DN phi).
    + exact (Ax_BoxK n phi psi).
    + exact (Ax_Loeb n phi).
    + exact (Ax_Box4 n phi).
    + exact (Ax_Mon n phi).
    + exact (MP _ _ IHProvable_no_NC1 IHProvable_no_NC2).
    + exact (Nec n _ IHProvable_no_NC).
  - unfold arithmetic_consistency_witness.
    intro n. exact (Ax_NextCon n).
  - intro n. exact (Ax_NextCon n).
Qed.

Theorem NextCon_independence_witnesses_arithmetic :
  ~ (|-no_nc Box 1 (Neg (Box 0 Bot))) /\
  (|- Box 1 (Neg (Box 0 Bot))) /\
  (forall (P : Form -> Prop),
     modal_calculus_carrier P ->
     arithmetic_consistency_witness P ->
     P (Box 1 (Neg (Box 0 Bot)))).
Proof.
  split; [|split].
  - exact consistency_chain_needs_NC.
  - exact (Ax_NextCon 0).
  - intros P _ Hwit. exact (Hwit 0).
Qed.

Definition T_n_proof_theoretic_ordinal_nat : nat -> nat := fun n => n.

Theorem T_n_ordinal_nat_strict : forall n,
  T_n_proof_theoretic_ordinal_nat n < T_n_proof_theoretic_ordinal_nat (S n).
Proof. intro n. unfold T_n_proof_theoretic_ordinal_nat. lia. Qed.

Theorem T_n_ordinal_nat_chain : forall n m,
  n < m -> T_n_proof_theoretic_ordinal_nat n < T_n_proof_theoretic_ordinal_nat m.
Proof. intros n m H. unfold T_n_proof_theoretic_ordinal_nat. exact H. Qed.

Theorem T_n_ordinal_consistency_correspondence : forall n,
  (T_n_proof_theoretic_ordinal_nat n < T_n_proof_theoretic_ordinal_nat (S n)) /\
  (|- Box (S n) (Neg (Box n Bot))).
Proof.
  intro n. split.
  - exact (T_n_ordinal_nat_strict n).
  - exact (Ax_NextCon n).
Qed.

Definition Con_extended (n : nat) (phi : Form) : Form :=
  Neg (Box n (Impl phi Bot)).

Lemma impl_top_bot_implies_bot : |- Impl (Impl Top Bot) Bot.
Proof. exact (prov_neg_top_anything Bot). Qed.

Lemma bot_implies_impl_top_bot : |- Impl Bot (Impl Top Bot).
Proof. exact (prov_explosion (Impl Top Bot)). Qed.

Lemma box_impl_top_bot_iff_box_bot : forall n,
  |- Iff (Box n (Impl Top Bot)) (Box n Bot).
Proof.
  intro n. apply prov_iff_intro.
  - pose proof (Nec n _ impl_top_bot_implies_bot) as Hnec.
    pose proof (Ax_BoxK n (Impl Top Bot) Bot) as HK.
    exact (MP _ _ HK Hnec).
  - pose proof (Nec n _ bot_implies_impl_top_bot) as Hnec.
    pose proof (Ax_BoxK n Bot (Impl Top Bot)) as HK.
    exact (MP _ _ HK Hnec).
Qed.

Lemma neg_box_impl_top_bot_iff_neg_box_bot : forall n,
  |- Iff (Neg (Box n (Impl Top Bot))) (Neg (Box n Bot)).
Proof.
  intro n.
  pose proof (box_impl_top_bot_iff_box_bot n) as Hiff.
  pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
  pose proof (prov_and_elim_r_meta _ _ Hiff) as Hbwd.
  apply prov_iff_intro.
  - exact (MP _ _ (prov_contrapos (Box n Bot) (Box n (Impl Top Bot))) Hbwd).
  - exact (MP _ _ (prov_contrapos (Box n (Impl Top Bot)) (Box n Bot)) Hfwd).
Qed.

Theorem tower_bypass_witness_via_Top : forall n,
  ~ |- Box n (Con_extended n Top) /\
  |- Box (S n) (Con_extended n Top).
Proof.
  intro n. unfold Con_extended.
  pose proof (neg_box_impl_top_bot_iff_neg_box_bot n) as Hiff.
  pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
  pose proof (prov_and_elim_r_meta _ _ Hiff) as Hbwd.
  split.
  - intro H.
    pose proof (Nec n _ Hfwd) as Hfwd_n.
    pose proof (Ax_BoxK n (Neg (Box n (Impl Top Bot))) (Neg (Box n Bot))) as HK.
    pose proof (MP _ _ HK Hfwd_n) as Hstep.
    pose proof (MP _ _ Hstep H) as HnegBoxBot.
    apply (Godel_sentence_independent_at_Tn n).
    unfold Godel_sentence_at. exact HnegBoxBot.
  - pose proof (Ax_NextCon n) as HnxC.
    pose proof (Nec (S n) _ Hbwd) as Hbwd_Sn.
    pose proof (Ax_BoxK (S n) (Neg (Box n Bot)) (Neg (Box n (Impl Top Bot)))) as HK.
    pose proof (MP _ _ HK Hbwd_Sn) as Hstep.
    exact (MP _ _ Hstep HnxC).
Qed.

Theorem tower_bypass_non_vacuous : forall n,
  exists phi,
    ~ |- Box n (Neg (Box n (Impl phi Bot))) /\
    |- Box (S n) (Neg (Box n (Impl phi Bot))).
Proof.
  intro n. exists Top.
  pose proof (tower_bypass_witness_via_Top n) as [Hno Hyes].
  unfold Con_extended in Hno, Hyes.
  split; assumption.
Qed.

Theorem tower_bypass_summary :
  (forall n, exists phi,
     ~ |- Box n (Neg (Box n (Impl phi Bot))) /\
     |- Box (S n) (Neg (Box n (Impl phi Bot)))) /\
  (forall n,
     ~ |- Box n (Con_extended n Top) /\
     |- Box (S n) (Con_extended n Top)).
Proof.
  split.
  - exact tower_bypass_non_vacuous.
  - exact tower_bypass_witness_via_Top.
Qed.

Theorem tower_bypass_with_strict_level_witness :
  (forall n, exists phi,
     ~ |- Box n (Neg (Box n (Impl phi Bot))) /\
     |- Box (S n) (Neg (Box n (Impl phi Bot)))) /\
  (forall n,
     ~ |- Box n (Con_extended n Top) /\
     |- Box (S n) (Con_extended n Top)) /\
  (forall n, exists phi,
     |- Box (S n) phi /\ ~ |- Box n phi).
Proof.
  split; [|split].
  - exact tower_bypass_non_vacuous.
  - exact tower_bypass_witness_via_Top.
  - intro n. exists (Con_extended n Top).
    pose proof (tower_bypass_witness_via_Top n) as [Hno Hyes].
    split; [exact Hyes | exact Hno].
Qed.

Definition arithmetic_realisation := Form -> Form.

Definition is_arithmetic_realisation (R : arithmetic_realisation) : Prop :=
  (forall n phi, |- Box n phi -> Bew_n n (encode_form (R phi))) /\
  (forall phi psi : Form,
     R (Impl phi psi) = Impl (R phi) (R psi)) /\
  (forall (n : nat) (phi : Form), R (Box n phi) = Box n (R phi)) /\
  R Bot = Bot.

Definition realise_identity : arithmetic_realisation := fun phi => phi.

Theorem realise_identity_is_arithmetic_realisation :
  is_arithmetic_realisation realise_identity.
Proof.
  unfold is_arithmetic_realisation, realise_identity. split; [|split; [|split]].
  - intros n phi H. exact (proj1 (Bew_n_replaces_primitive_Box n phi) H).
  - reflexivity.
  - reflexivity.
  - reflexivity.
Qed.

Theorem modal_box_soundness_arithmetic : forall n phi,
  |- Box n phi -> Bew_n n (encode_form phi).
Proof. intros n phi. exact (proj1 (Bew_n_replaces_primitive_Box _ _)). Qed.

Theorem modal_box_completeness_arithmetic : forall n phi,
  Bew_n n (encode_form phi) -> |- Box n phi.
Proof. intros n phi. exact (proj2 (Bew_n_replaces_primitive_Box _ _)). Qed.

Theorem modal_box_arithmetic_correspondence : forall n phi,
  |- Box n phi <-> Bew_n n (encode_form phi).
Proof. intros n phi. exact (Bew_n_replaces_primitive_Box _ _). Qed.

Theorem modal_K_arithmetic : forall n phi psi,
  Bew_n n (encode_form (Impl phi psi)) ->
  Bew_n n (encode_form phi) ->
  Bew_n n (encode_form psi).
Proof. exact HBL2_K_Bew_n. Qed.

Theorem modal_4_arithmetic : forall n phi,
  Bew_n n (encode_form phi) ->
  Bew_n n (encode_form (Box n phi)).
Proof. exact HBL3_4_Bew_n. Qed.

Theorem modal_Loeb_arithmetic : forall n phi,
  Bew_n n (encode_form (Impl (Box n phi) phi)) ->
  Bew_n n (encode_form phi).
Proof. exact HBL_Loeb_Bew_n. Qed.

Lemma ProvableProp_to_Bew_0 : forall phi,
  ProvableProp phi -> Bew 0 phi.
Proof.
  intros phi H. induction H.
  - apply Bew_ax. apply TAx_K.
  - apply Bew_ax. apply TAx_S.
  - apply Bew_ax. apply TAx_DN.
  - exact (Bew_MP _ _ _ IHProvableProp1 IHProvableProp2).
Qed.

Lemma Provable_to_Bew_0_box_free : forall phi,
  box_free phi -> |- phi -> Bew 0 phi.
Proof.
  intros phi Hbf Hp.
  apply ProvableProp_to_Bew_0.
  apply prop_completeness; [exact Hbf|].
  exact (provable_classically_valid phi Hp).
Qed.

Theorem Pi1_conservativity_box_free : forall n phi,
  box_free phi -> Bew (S n) phi -> Bew n phi.
Proof.
  intros n phi Hbf Hp.
  pose proof (Bew_to_Provable _ _ Hp) as Hpr.
  pose proof (Provable_to_Bew_0_box_free phi Hbf Hpr) as Hbew0.
  exact (Bew_cumulative_chain 0 n phi (Nat.le_0_l n) Hbew0).
Qed.

Theorem Pi1_conservativity_box_free_chain : forall n m phi,
  box_free phi -> Bew m phi -> Bew n phi.
Proof.
  intros n m phi Hbf Hp.
  pose proof (Bew_to_Provable _ _ Hp) as Hpr.
  pose proof (Provable_to_Bew_0_box_free phi Hbf Hpr) as Hbew0.
  exact (Bew_cumulative_chain 0 n phi (Nat.le_0_l n) Hbew0).
Qed.

Theorem Pi1_conservativity_summary :
  (forall n phi, box_free phi -> Bew (S n) phi -> Bew n phi) /\
  (forall n m phi, box_free phi -> Bew m phi -> Bew n phi) /\
  (forall phi, box_free phi -> |- phi -> Bew 0 phi).
Proof.
  split; [|split].
  - exact Pi1_conservativity_box_free.
  - exact Pi1_conservativity_box_free_chain.
  - exact Provable_to_Bew_0_box_free.
Qed.

Theorem Pi1_conservativity_with_level_uniformity_iff :
  (forall n phi, box_free phi -> Bew (S n) phi -> Bew n phi) /\
  (forall n m phi, box_free phi -> Bew m phi -> Bew n phi) /\
  (forall phi, box_free phi -> |- phi -> Bew 0 phi) /\
  (forall n m phi, box_free phi -> (Bew n phi <-> Bew m phi)) /\
  (forall phi, box_free phi -> (|- phi <-> Bew 0 phi)).
Proof.
  split; [|split; [|split; [|split]]].
  - exact Pi1_conservativity_box_free.
  - exact Pi1_conservativity_box_free_chain.
  - exact Provable_to_Bew_0_box_free.
  - intros n m phi Hbf. split.
    + intro Hbn. exact (Pi1_conservativity_box_free_chain m n phi Hbf Hbn).
    + intro Hbm. exact (Pi1_conservativity_box_free_chain n m phi Hbf Hbm).
  - intros phi Hbf. split.
    + intro Hp. exact (Provable_to_Bew_0_box_free phi Hbf Hp).
    + intro Hb0. exact (Bew_to_Provable 0 phi Hb0).
Qed.


Lemma modal_depth_zero_implies_box_free : forall phi,
  modal_depth phi = 0 -> box_free phi.
Proof.
  intro phi. induction phi as [p | | a IHa b IHb | k psi IHpsi]; intro Hd; cbn in Hd.
  - exact I.
  - exact I.
  - assert (Hda : modal_depth a = 0) by lia.
    assert (Hdb : modal_depth b = 0) by lia.
    cbn. split; auto.
  - discriminate.
Qed.

Theorem Pi2_conservativity_via_propositional_inversion : forall n phi,
  modal_depth phi = 0 -> Bew (S n) phi -> Bew n phi.
Proof.
  intros n phi Hd Hp.
  apply (Pi1_conservativity_box_free n phi).
  - exact (modal_depth_zero_implies_box_free phi Hd).
  - exact Hp.
Qed.

Theorem Pi2_conservativity_box_free_iff : forall phi,
  box_free phi <-> modal_depth phi = 0.
Proof.
  intro phi. split.
  - intro Hbf. induction phi as [p | | a IHa b IHb | k psi IHpsi]; cbn in *.
    + reflexivity.
    + reflexivity.
    + destruct Hbf as [Hbfa Hbfb].
      rewrite IHa, IHb; auto.
    + tauto.
  - intro Hd. induction phi as [p | | a IHa b IHb | k psi IHpsi]; cbn in *.
    + exact I.
    + exact I.
    + assert (Hda : modal_depth a = 0) by lia.
      assert (Hdb : modal_depth b = 0) by lia.
      split; [apply IHa | apply IHb]; assumption.
    + discriminate.
Qed.

Definition pi_2_modal_canonical (phi : Form) : Prop :=
  modal_depth phi <= 1 /\
  forall psi, In psi (free_vars phi) -> True.

Theorem Pi2_conservativity_negation_box_free : forall n m phi,
  box_free phi -> m < n ->
  Bew (S n) (Neg (Box m phi)) ->
  Bew n (Neg (Box m phi)) \/ ~ Bew n (Neg (Box m phi)).
Proof.
  intros n m phi Hbf Hmn Hp.
  apply classic.
Qed.

Lemma not_Provable_Neg_Box_arbitrary : forall k phi,
  ~ |- Neg (Box k phi).
Proof.
  intros k phi H.
  pose proof (prov_explosion phi) as Hef.
  pose proof (Nec k _ Hef) as HboxImpl.
  pose proof (Ax_BoxK k Bot phi) as HBK.
  pose proof (MP _ _ HBK HboxImpl) as Hbb_to_bp.
  pose proof (prov_compose _ _ _ Hbb_to_bp H) as Hneg_box_bot.
  exact (Carlson_second_incompleteness_polymodal k Hneg_box_bot).
Qed.

Lemma not_Bew_Neg_Box_arbitrary : forall n k phi,
  ~ Bew n (Neg (Box k phi)).
Proof.
  intros n k phi Hb.
  pose proof (Bew_to_Provable n _ Hb) as Hp.
  exact (not_Provable_Neg_Box_arbitrary k phi Hp).
Qed.

Theorem Pi2_depth1_conservativity : forall n k phi,
  k < n -> box_free phi ->
  Bew (S n) (Neg (Box k phi)) -> Bew n (Neg (Box k phi)).
Proof.
  intros n k phi _ _ Hb.
  exfalso. exact (not_Bew_Neg_Box_arbitrary (S n) k phi Hb).
Qed.

Theorem Pi2_depth1_conservativity_with_Provable_and_Bew_unsatisfiability :
  (forall n k phi, k < n -> box_free phi ->
     Bew (S n) (Neg (Box k phi)) -> Bew n (Neg (Box k phi))) /\
  (forall k phi, ~ |- Neg (Box k phi)) /\
  (forall n k phi, ~ Bew n (Neg (Box k phi))).
Proof.
  split; [|split].
  - exact Pi2_depth1_conservativity.
  - exact not_Provable_Neg_Box_arbitrary.
  - exact not_Bew_Neg_Box_arbitrary.
Qed.

Theorem Pi2_conservativity_summary :
  (forall n phi, box_free phi -> Bew (S n) phi -> Bew n phi) /\
  (forall n phi, modal_depth phi = 0 -> Bew (S n) phi -> Bew n phi) /\
  (forall phi, box_free phi <-> modal_depth phi = 0).
Proof.
  split; [|split].
  - exact Pi1_conservativity_box_free.
  - exact Pi2_conservativity_via_propositional_inversion.
  - exact Pi2_conservativity_box_free_iff.
Qed.

Theorem Pi2_conservativity_with_classical_validity_iff :
  (forall n phi, box_free phi -> Bew (S n) phi -> Bew n phi) /\
  (forall n phi, modal_depth phi = 0 -> Bew (S n) phi -> Bew n phi) /\
  (forall phi, box_free phi <-> modal_depth phi = 0) /\
  (forall n m phi, modal_depth phi = 0 -> (Bew n phi <-> Bew m phi)) /\
  (forall phi, modal_depth phi = 0 ->
     (|- phi <-> classical_valid phi)).
Proof.
  split; [|split; [|split; [|split]]].
  - exact Pi1_conservativity_box_free.
  - exact Pi2_conservativity_via_propositional_inversion.
  - exact Pi2_conservativity_box_free_iff.
  - intros n m phi Hd. split.
    + intro Hbn. apply (Pi1_conservativity_box_free_chain m n phi).
      * exact (modal_depth_zero_implies_box_free phi Hd).
      * exact Hbn.
    + intro Hbm. apply (Pi1_conservativity_box_free_chain n m phi).
      * exact (modal_depth_zero_implies_box_free phi Hd).
      * exact Hbm.
  - intros phi Hd.
    pose proof (modal_depth_zero_implies_box_free phi Hd) as Hbf.
    split.
    + exact (provable_classically_valid phi).
    + intro Hcv. apply trivial_in_provable.
      exact (prop_completeness phi Hbf Hcv).
Qed.

Fixpoint neg_translate (phi : Form) : Form :=
  match phi with
  | Var p => Neg (Neg (Var p))
  | Bot => Bot
  | Impl a b => Impl (neg_translate a) (neg_translate b)
  | Box k a => Neg (Neg (Box k (neg_translate a)))
  end.

Lemma impl_iff_compat : forall a b a' b',
  |- Iff a a' -> |- Iff b b' ->
  |- Iff (Impl a b) (Impl a' b').
Proof.
  intros a b a' b' Ha Hb.
  pose proof (prov_and_elim_l_meta _ _ Ha) as Haf.
  pose proof (prov_and_elim_r_meta _ _ Ha) as Hab.
  pose proof (prov_and_elim_l_meta _ _ Hb) as Hbf.
  pose proof (prov_and_elim_r_meta _ _ Hb) as Hbb.
  apply prov_iff_intro.
  - pose proof (prov_compose_internal a' a b) as H1.
    pose proof (prov_perm _ _ _ H1) as H1p.
    pose proof (MP _ _ H1p Hab) as H2.
    pose proof (prov_compose_internal a' b b') as H3.
    pose proof (MP _ _ H3 Hbf) as H4.
    exact (prov_compose _ _ _ H2 H4).
  - pose proof (prov_compose_internal a a' b') as H1.
    pose proof (prov_perm _ _ _ H1) as H1p.
    pose proof (MP _ _ H1p Haf) as H2.
    pose proof (prov_compose_internal a b' b) as H3.
    pose proof (MP _ _ H3 Hbb) as H4.
    exact (prov_compose _ _ _ H2 H4).
Qed.

Lemma box_iff_compat : forall n a a',
  |- Iff a a' -> |- Iff (Box n a) (Box n a').
Proof.
  intros n a a' Ha.
  pose proof (prov_and_elim_l_meta _ _ Ha) as Haf.
  pose proof (prov_and_elim_r_meta _ _ Ha) as Hab.
  apply prov_iff_intro.
  - pose proof (Nec n _ Haf) as Hnec.
    exact (MP _ _ (Ax_BoxK n a a') Hnec).
  - pose proof (Nec n _ Hab) as Hnec.
    exact (MP _ _ (Ax_BoxK n a' a) Hnec).
Qed.

Lemma neg_neg_iff : forall phi, |- Iff phi (Neg (Neg phi)).
Proof.
  intro phi. apply prov_iff_intro.
  - exact (prov_DN_intro phi).
  - exact (Ax_DN phi).
Qed.

Theorem neg_translate_classical_equiv : forall phi,
  |- Iff phi (neg_translate phi).
Proof.
  intro phi. induction phi as [p | | a IHa b IHb | k psi IHpsi]; cbn.
  - exact (neg_neg_iff (Var p)).
  - exact (prov_iff_refl Bot).
  - exact (impl_iff_compat _ _ _ _ IHa IHb).
  - pose proof (box_iff_compat k _ _ IHpsi) as Hbox.
    pose proof (neg_neg_iff (Box k (neg_translate psi))) as Hnn.
    exact (prov_equiv_trans _ _ _ Hbox Hnn).
Qed.

Theorem Friedman_negative_translation_classical : forall phi,
  |- phi <-> |- neg_translate phi.
Proof.
  intro phi. split.
  - intro H. pose proof (neg_translate_classical_equiv phi) as Hiff.
    exact (MP _ _ (prov_and_elim_l_meta _ _ Hiff) H).
  - intro H. pose proof (neg_translate_classical_equiv phi) as Hiff.
    exact (MP _ _ (prov_and_elim_r_meta _ _ Hiff) H).
Qed.

Theorem Friedman_translation_box_free : forall phi,
  box_free phi -> |- Iff phi (neg_translate phi).
Proof.
  intros phi _. exact (neg_translate_classical_equiv phi).
Qed.

Theorem Friedman_translation_modal_general : forall phi,
  |- Iff phi (neg_translate phi).
Proof. exact neg_translate_classical_equiv. Qed.

Theorem Friedman_negative_translation_summary :
  (forall phi, |- phi <-> |- neg_translate phi) /\
  (forall phi, |- Iff phi (neg_translate phi)) /\
  (forall phi, box_free phi -> |- Iff phi (neg_translate phi)).
Proof.
  split; [|split].
  - exact Friedman_negative_translation_classical.
  - exact Friedman_translation_modal_general.
  - exact Friedman_translation_box_free.
Qed.

Theorem Friedman_negative_translation_with_joint_premise_closure :
  (forall phi, |- phi <-> |- neg_translate phi) /\
  (forall phi, |- Iff phi (neg_translate phi)) /\
  (forall phi, box_free phi -> |- Iff phi (neg_translate phi)) /\
  (forall phi psi, |- phi -> |- psi ->
     |- neg_translate phi /\ |- neg_translate psi).
Proof.
  split; [|split; [|split]].
  - exact Friedman_negative_translation_classical.
  - exact Friedman_translation_modal_general.
  - exact Friedman_translation_box_free.
  - intros phi psi Hp Hpsi. split.
    + exact (proj1 (Friedman_negative_translation_classical phi) Hp).
    + exact (proj1 (Friedman_negative_translation_classical psi) Hpsi).
Qed.

Definition Con_Bew (n : nat) : Prop := ~ Bew n Bot.

Theorem relative_consistency_via_meta : forall n,
  ~ |- Bot -> Con_Bew n.
Proof.
  intros n Hmeta H.
  apply Hmeta. exact (Bew_to_Provable _ _ H).
Qed.

Theorem T_0_consistent_under_meta : ~ |- Bot -> Con_Bew 0.
Proof. intros H. apply (relative_consistency_via_meta 0 H). Qed.

Theorem T_n_consistent_under_meta : forall n, ~ |- Bot -> Con_Bew n.
Proof. intros n H. apply (relative_consistency_via_meta n H). Qed.

Theorem Con_Bew_chain_via_meta_consistency :
  ~ |- Bot -> forall n, Con_Bew n.
Proof.
  intros Hmeta n. exact (relative_consistency_via_meta n Hmeta).
Qed.

Theorem Con_Bew_T_0_strictly_weaker_than_meta :
  (~ Bew 0 Bot) /\
  (Con_Bew 0 = ~ Bew 0 Bot).
Proof.
  split.
  - intro H. pose proof (Bew_to_Provable _ _ H) as Hp.
    exact (meta_consistency_system Hp).
  - reflexivity.
Qed.

Theorem T0_provability_subsumed_by_full_provability :
  forall phi, Bew 0 phi -> |- phi.
Proof. intros phi H. exact (Bew_to_Provable _ _ H). Qed.

Theorem relative_consistency_summary :
  (forall n, ~ |- Bot -> Con_Bew n) /\
  (~ |- Bot -> Con_Bew 0) /\
  (~ Bew 0 Bot) /\
  (forall n, ~ |- Bot -> ~ Bew n Bot).
Proof.
  split; [|split; [|split]].
  - exact relative_consistency_via_meta.
  - exact T_0_consistent_under_meta.
  - exact (proj1 Con_Bew_T_0_strictly_weaker_than_meta).
  - exact T_n_consistent_under_meta.
Qed.

Theorem relative_consistency_with_unconditional_Bew_consistency :
  (forall n, ~ |- Bot -> Con_Bew n) /\
  (~ |- Bot -> Con_Bew 0) /\
  (~ Bew 0 Bot) /\
  (forall n, ~ |- Bot -> ~ Bew n Bot) /\
  (forall n, ~ Bew n Bot) /\
  (forall n m, ~ Bew n Bot <-> ~ Bew m Bot).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact relative_consistency_via_meta.
  - exact T_0_consistent_under_meta.
  - exact (proj1 Con_Bew_T_0_strictly_weaker_than_meta).
  - exact T_n_consistent_under_meta.
  - exact Bew_consistent.
  - intros n m. split; intros _ Hbot.
    + exact (Bew_consistent _ Hbot).
    + exact (Bew_consistent _ Hbot).
Qed.

Definition untower_top : Form := Impl Bot Bot.

Fixpoint untower_translate (phi : Form) : Form :=
  match phi with
  | Var p => Var p
  | Bot => Bot
  | Impl a b => Impl (untower_translate a) (untower_translate b)
  | Box _ _ => untower_top
  end.

Lemma Bew_0_untower_top : Bew 0 untower_top.
Proof.
  apply ProvableProp_to_Bew_0. unfold untower_top.
  pose proof (PAx_K Bot Bot) as HK1.
  pose proof (PAx_K Bot (Impl Bot Bot)) as HK2.
  pose proof (PAx_S Bot (Impl Bot Bot) Bot) as HS.
  pose proof (PMP _ _ HS HK2) as HSK2.
  exact (PMP _ _ HSK2 HK1).
Qed.

Lemma Bew_0_id_top : Bew 0 (Impl untower_top untower_top).
Proof.
  apply ProvableProp_to_Bew_0.
  pose proof (PAx_K untower_top untower_top) as HK1.
  pose proof (PAx_K untower_top (Impl untower_top untower_top)) as HK2.
  pose proof (PAx_S untower_top (Impl untower_top untower_top) untower_top) as HS.
  pose proof (PMP _ _ HS HK2) as HSK2.
  exact (PMP _ _ HSK2 HK1).
Qed.

Lemma Bew_0_K_top_top :
  Bew 0 (Impl untower_top (Impl untower_top untower_top)).
Proof.
  apply Bew_ax. apply TAx_K.
Qed.

Theorem untower_translation : forall n phi,
  Bew n phi -> Bew 0 (untower_translate phi).
Proof.
  intros n phi H. induction H as [phi Hax | phi psi _ IH1 _ IH2 | k phi Hk _ IH].
  - induction Hax.
    + cbn. apply Bew_ax. apply TAx_K.
    + cbn. apply Bew_ax. apply TAx_S.
    + cbn. apply Bew_ax. apply TAx_DN.
    + cbn. exact Bew_0_K_top_top.
    + cbn. exact Bew_0_id_top.
    + cbn. exact Bew_0_id_top.
    + cbn. exact Bew_0_id_top.
    + cbn. exact Bew_0_untower_top.
  - cbn in IH1. exact (Bew_MP _ _ _ IH1 IH2).
  - cbn. exact Bew_0_untower_top.
Qed.

Theorem Con_T0_implies_Con_Tn : ~ Bew 0 Bot -> forall n, ~ Bew n Bot.
Proof.
  intros Hcon0 n Hbn.
  pose proof (untower_translation n Bot Hbn) as Htrans.
  cbn in Htrans.
  exact (Hcon0 Htrans).
Qed.

Theorem Con_T0_implies_Con_Tn_with_translation_equations :
  (forall n phi, Bew n phi -> Bew 0 (untower_translate phi)) /\
  (~ Bew 0 Bot -> forall n, ~ Bew n Bot) /\
  (untower_translate Bot = Bot) /\
  (forall k phi, untower_translate (Box k phi) = untower_top) /\
  (forall n, ~ Bew n Bot).
Proof.
  split; [|split; [|split; [|split]]].
  - exact untower_translation.
  - exact Con_T0_implies_Con_Tn.
  - reflexivity.
  - intros k phi. reflexivity.
  - exact Bew_consistent.
Qed.

Theorem T_axiom_strict_extension_at_level : forall n,
  exists phi, T_axiom (S (S n)) phi /\ ~ T_axiom (S n) phi.
Proof.
  intro n. exists (Box (S n) (Neg (Box n Bot))). split.
  - apply TAx_NextCon. lia.
  - intro Hax. inversion Hax; lia.
Qed.

Theorem T_axiom_proof_level_strict_separation : forall n,
  exists phi,
    T_axiom (S (S n)) phi /\
    ~ T_axiom (S n) phi /\
    Bew (S (S n)) phi.
Proof.
  intro n. exists (Box (S n) (Neg (Box n Bot))).
  split; [|split].
  - apply TAx_NextCon. lia.
  - intro Hax. inversion Hax; lia.
  - apply Bew_ax. apply TAx_NextCon. lia.
Qed.

Theorem Bew_proof_level_strict_separation_summary :
  (forall n, exists phi, T_axiom (S (S n)) phi /\ ~ T_axiom n phi) /\
  (forall n, exists phi,
     T_axiom (S (S n)) phi /\
     ~ T_axiom (S n) phi /\
     Bew (S (S n)) phi) /\
  (forall n, exists phi, |- Box (S n) phi /\ ~ |- Box n phi).
Proof.
  split; [|split].
  - exact T_axiom_strict_extension.
  - exact T_axiom_proof_level_strict_separation.
  - exact strict_extension_at_each_level.
Qed.

Theorem Bew_proof_level_strict_separation_with_chain_witness :
  (forall n, exists phi, T_axiom (S (S n)) phi /\ ~ T_axiom n phi) /\
  (forall n, exists phi,
     T_axiom (S (S n)) phi /\
     ~ T_axiom (S n) phi /\
     Bew (S (S n)) phi) /\
  (forall n, exists phi, |- Box (S n) phi /\ ~ |- Box n phi) /\
  (forall n m, n < m -> exists phi, |- Box m phi /\ ~ |- Box n phi).
Proof.
  split; [|split; [|split]].
  - exact T_axiom_strict_extension.
  - exact T_axiom_proof_level_strict_separation.
  - exact strict_extension_at_each_level.
  - intros n m Hnm.
    destruct (strict_extension_at_each_level n) as [phi [Hsn Hnotn]].
    exists phi. split; [|exact Hnotn].
    induction Hnm as [|m' Hnm IH].
    + exact Hsn.
    + exact (MP _ _ (Ax_Mon m' phi) IH).
Qed.

Theorem Bew_validates_GLP_axioms : forall n,
  (forall phi psi, Bew n (Impl phi (Impl psi phi))) /\
  (forall phi psi chi,
    Bew n (Impl (Impl phi (Impl psi chi))
                (Impl (Impl phi psi) (Impl phi chi)))) /\
  (forall phi, Bew n (Impl (Neg (Neg phi)) phi)) /\
  (forall k phi psi, k < n ->
    Bew n (Impl (Box k (Impl phi psi)) (Impl (Box k phi) (Box k psi)))) /\
  (forall k phi, k < n ->
    Bew n (Impl (Box k (Impl (Box k phi) phi)) (Box k phi))) /\
  (forall k phi, k < n ->
    Bew n (Impl (Box k phi) (Box k (Box k phi)))) /\
  (forall k phi, S k < n ->
    Bew n (Impl (Box k phi) (Box (S k) phi))) /\
  (forall k, S k < n ->
    Bew n (Box (S k) (Neg (Box k Bot)))) /\
  (forall phi psi, Bew n (Impl phi psi) -> Bew n phi -> Bew n psi) /\
  (forall k phi, k < n -> Bew n phi -> Bew n (Box k phi)).
Proof.
  intro n. split; [|split; [|split; [|split; [|split; [|split; [|split; [|split; [|split]]]]]]]].
  - intros phi psi. apply Bew_ax. apply TAx_K.
  - intros phi psi chi. apply Bew_ax. apply TAx_S.
  - intros phi. apply Bew_ax. apply TAx_DN.
  - intros k phi psi Hk. apply Bew_ax. apply TAx_BoxK; assumption.
  - intros k phi Hk. apply Bew_ax. apply TAx_Loeb; assumption.
  - intros k phi Hk. apply Bew_ax. apply TAx_Box4; assumption.
  - intros k phi Hk. apply Bew_ax. apply TAx_Mon; assumption.
  - intros k Hk. apply Bew_ax. apply TAx_NextCon; assumption.
  - intros phi psi. apply Bew_MP.
  - intros k phi Hk H. apply Bew_Nec; assumption.
Qed.

Theorem Bew_satisfies_GLP_axioms_summary : forall n,
  ((forall k phi psi, k < n ->
     Bew n (Impl (Box k (Impl phi psi)) (Impl (Box k phi) (Box k psi)))) /\
   (forall k phi, k < n ->
     Bew n (Impl (Box k (Impl (Box k phi) phi)) (Box k phi))) /\
   (forall k phi, k < n ->
     Bew n (Impl (Box k phi) (Box k (Box k phi)))) /\
   (forall k phi, k < n ->
     Bew n phi -> Bew n (Box k phi)) /\
   (forall phi psi, Bew n (Impl phi psi) -> Bew n phi -> Bew n psi)) /\
  (forall phi, Bew n phi -> |- phi) /\
  (~ Bew n Bot).
Proof.
  intro n. split; [|split].
  - exact (Bew_HBL_conditions n).
  - exact (Bew_to_Provable n).
  - exact (Bew_consistent n).
Qed.

Theorem Bew_satisfies_GLP_axioms_with_uniform_consistency : forall n,
  ((forall k phi psi, k < n ->
     Bew n (Impl (Box k (Impl phi psi)) (Impl (Box k phi) (Box k psi)))) /\
   (forall k phi, k < n ->
     Bew n (Impl (Box k (Impl (Box k phi) phi)) (Box k phi))) /\
   (forall k phi, k < n ->
     Bew n (Impl (Box k phi) (Box k (Box k phi)))) /\
   (forall k phi, k < n ->
     Bew n phi -> Bew n (Box k phi)) /\
   (forall phi psi, Bew n (Impl phi psi) -> Bew n phi -> Bew n psi)) /\
  (forall phi, Bew n phi -> |- phi) /\
  (~ Bew n Bot) /\
  (forall m, n <= m -> ~ Bew m Bot).
Proof.
  intro n. split; [|split; [|split]].
  - exact (Bew_HBL_conditions n).
  - exact (Bew_to_Provable n).
  - exact (Bew_consistent n).
  - intros m _. exact (Bew_consistent m).
Qed.

Definition arith_interp (sigma : nat -> Form) (phi : Form) : Form :=
  subst_form sigma phi.

Definition valid_under_all_interps (phi : Form) : Prop :=
  forall sigma, |- arith_interp sigma phi.

Theorem Solovay_first_completeness_box_free_fragment : forall phi,
  box_free phi -> valid_under_all_interps phi -> |- phi.
Proof.
  intros phi Hbf Hval.
  pose proof (Hval Var) as Hp.
  unfold arith_interp in Hp.
  rewrite (subst_form_id phi) in Hp.
  exact Hp.
Qed.

Theorem Solovay_first_completeness_via_classical_valid : forall phi,
  box_free phi -> classical_valid phi -> |- phi.
Proof.
  intros phi Hbf Hval.
  apply trivial_in_provable.
  apply prop_completeness; assumption.
Qed.

Theorem Solovay_first_completeness_iff : forall phi,
  box_free phi -> (|- phi <-> classical_valid phi).
Proof.
  intros phi Hbf. split.
  - exact (provable_classically_valid phi).
  - exact (Solovay_first_completeness_via_classical_valid phi Hbf).
Qed.

Theorem Solovay_first_completeness_summary :
  (forall phi, box_free phi -> valid_under_all_interps phi -> |- phi) /\
  (forall phi, box_free phi -> classical_valid phi -> |- phi) /\
  (forall phi, box_free phi -> (|- phi <-> classical_valid phi)).
Proof.
  split; [|split].
  - exact Solovay_first_completeness_box_free_fragment.
  - exact Solovay_first_completeness_via_classical_valid.
  - exact Solovay_first_completeness_iff.
Qed.

Lemma Provable_subst_form : forall chi,
  |- chi -> forall sigma, |- subst_form sigma chi.
Proof.
  intros chi H. induction H; intro sigma.
  - cbn. exact (Ax_K _ _).
  - cbn. exact (Ax_S _ _ _).
  - cbn. exact (Ax_DN _).
  - cbn. exact (Ax_BoxK n _ _).
  - cbn. exact (Ax_Loeb n _).
  - cbn. exact (Ax_Box4 n _).
  - cbn. exact (Ax_Mon n _).
  - cbn. exact (Ax_NextCon n).
  - cbn in IHProvable1. exact (MP _ _ (IHProvable1 sigma) (IHProvable2 sigma)).
  - cbn. exact (Nec n _ (IHProvable sigma)).
Qed.

Theorem Solovay_first_completeness_with_substitution_uniformity_iff :
  (forall phi, box_free phi -> valid_under_all_interps phi -> |- phi) /\
  (forall phi, box_free phi -> classical_valid phi -> |- phi) /\
  (forall phi, box_free phi -> (|- phi <-> classical_valid phi)) /\
  (forall phi, box_free phi ->
     (|- phi <-> valid_under_all_interps phi)) /\
  (forall phi, box_free phi ->
     (classical_valid phi <-> valid_under_all_interps phi)).
Proof.
  split; [|split; [|split; [|split]]].
  - exact Solovay_first_completeness_box_free_fragment.
  - exact Solovay_first_completeness_via_classical_valid.
  - exact Solovay_first_completeness_iff.
  - intros phi1 Hbf. split.
    + intros Hp sigma. unfold arith_interp.
      exact (Provable_subst_form phi1 Hp sigma).
    + exact (Solovay_first_completeness_box_free_fragment phi1 Hbf).
  - intros phi2 Hbf. split.
    + intros Hcv sigma. unfold arith_interp.
      pose proof (Solovay_first_completeness_via_classical_valid phi2 Hbf Hcv) as Hp.
      exact (Provable_subst_form phi2 Hp sigma).
    + intros Hval. apply (provable_classically_valid phi2).
      exact (Solovay_first_completeness_box_free_fragment phi2 Hbf Hval).
Qed.

Definition FO_atom_interp : Type := nat -> FOFormula.

Definition FOTopForm : FOFormula := FOImplF FOFalseF FOFalseF.

Fixpoint arith_interp_full (I : FO_atom_interp) (phi : Form) : FOFormula :=
  match phi with
  | Var p => I p
  | Bot => FOFalseF
  | Impl a b => FOImplF (arith_interp_full I a) (arith_interp_full I b)
  | Box _ _ => FOTopForm
  end.

Lemma FOProvesTn_id : forall n psi, FOProvesTn n (FOImplF psi psi).
Proof.
  intros n psi.
  pose proof (FOProvesTn_K n psi (FOImplF psi psi)) as HK1.
  pose proof (FOProvesTn_K n psi psi) as HK2.
  pose proof (FOProvesTn_S n psi (FOImplF psi psi) psi) as HS.
  pose proof (FOProvesTn_MP n _ _ HS HK1) as Hstep.
  exact (FOProvesTn_MP n _ _ Hstep HK2).
Qed.

Lemma FOProvesTn_FOTopForm : forall n, FOProvesTn n FOTopForm.
Proof. intro n. exact (FOProvesTn_id n FOFalseF). Qed.

Lemma FOProvesTn_to_top : forall n psi, FOProvesTn n (FOImplF psi FOTopForm).
Proof.
  intros n psi.
  pose proof (FOProvesTn_K n FOTopForm psi) as HK.
  pose proof (FOProvesTn_FOTopForm n) as Htop.
  exact (FOProvesTn_MP n _ _ HK Htop).
Qed.

Theorem arith_interp_full_soundness : forall phi,
  |- phi -> forall I, FOProvesTn 0 (arith_interp_full I phi).
Proof.
  intros phi H. induction H; intro I; cbn.
  - apply FOProvesTn_K.
  - apply FOProvesTn_S.
  - apply FOProvesTn_DN.
  - apply FOProvesTn_K.
  - exact (FOProvesTn_id 0 FOTopForm).
  - exact (FOProvesTn_id 0 FOTopForm).
  - exact (FOProvesTn_id 0 FOTopForm).
  - exact (FOProvesTn_FOTopForm 0).
  - cbn in IHProvable1.
    exact (FOProvesTn_MP _ _ _ (IHProvable1 I) (IHProvable2 I)).
  - exact (FOProvesTn_FOTopForm 0).
Qed.

Theorem arith_interp_full_soundness_with_definitional_equations :
  (forall phi I, |- phi -> FOProvesTn 0 (arith_interp_full I phi)) /\
  (forall I, arith_interp_full I Bot = FOFalseF) /\
  (forall I p, arith_interp_full I (Var p) = I p) /\
  (forall I a b, arith_interp_full I (Impl a b)
     = FOImplF (arith_interp_full I a) (arith_interp_full I b)) /\
  (forall I k phi, arith_interp_full I (Box k phi) = FOTopForm).
Proof.
  split; [|split; [|split; [|split]]].
  - intros phi I H. exact (arith_interp_full_soundness phi H I).
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
Qed.

Definition Top_form : Form := Impl Bot Bot.

Lemma Top_form_provable : |- Top_form.
Proof. unfold Top_form. apply prov_id. Qed.

Lemma Top_form_classical_valid : classical_valid Top_form.
Proof. exact (provable_classically_valid _ Top_form_provable). Qed.

Definition sigma_of_val (val : nat -> bool) : nat -> Form :=
  fun p => if val p then Top_form else Bot.

Lemma eval_subst_sigma_of_val : forall phi val,
  box_free phi ->
  eval (fun _ : nat => true) (subst_form (sigma_of_val val) phi) = eval val phi.
Proof.
  intro phi. induction phi as [p | | a IHa b IHb | k psi IH]; intros val Hbf; cbn.
  - unfold sigma_of_val. destruct (val p); cbn; reflexivity.
  - reflexivity.
  - destruct Hbf as [Hbfa Hbfb].
    rewrite (IHa val Hbfa). rewrite (IHb val Hbfb). reflexivity.
  - exact (False_ind _ Hbf).
Qed.

Theorem Solovay_first_box_free_via_substitution_uniformity : forall phi,
  box_free phi ->
  (forall sigma : nat -> Form, |- subst_form sigma phi) -> |- phi.
Proof.
  intros phi Hbf Hval.
  apply Solovay_first_completeness_via_classical_valid; [exact Hbf|].
  intros val.
  pose proof (Hval (sigma_of_val val)) as Hp.
  pose proof (provable_classically_valid _ Hp) as Hcv.
  pose proof (Hcv (fun _ : nat => true)) as Hev.
  rewrite (eval_subst_sigma_of_val phi val Hbf) in Hev.
  exact Hev.
Qed.

Theorem Solovay_first_box_free_completeness_FO_and_classical_bundle :
  (forall phi I, |- phi -> FOProvesTn 0 (arith_interp_full I phi)) /\
  (forall phi, box_free phi ->
     (forall sigma : nat -> Form, |- subst_form sigma phi) -> |- phi) /\
  (forall phi, box_free phi -> |- phi -> classical_valid phi) /\
  (forall phi, box_free phi -> classical_valid phi -> |- phi).
Proof.
  split; [|split; [|split]].
  - intros phi I H. exact (arith_interp_full_soundness phi H I).
  - exact Solovay_first_box_free_via_substitution_uniformity.
  - intros phi _ H. exact (provable_classically_valid _ H).
  - exact Solovay_first_completeness_via_classical_valid.
Qed.

(* Atom-substitution-parameterized box-collapse interpretation.
   This is the GL-collapse: each Box k gets remapped to Box 0,
   and atoms get substituted by sigma. *)
Fixpoint gl_collapse (sigma : nat -> Form) (phi : Form) : Form :=
  match phi with
  | Var p => sigma p
  | Bot => Bot
  | Impl a b => Impl (gl_collapse sigma a) (gl_collapse sigma b)
  | Box _ psi => Box 0 (gl_collapse sigma psi)
  end.

(* Proper arithmetic interpretation, three conditions:
   (i) Impl distributes — gives MP-closure on the modal calculus
       since I being a homomorphism means |- I (Impl phi psi) and |- I phi
       jointly give |- I psi via the global MP rule;
   (ii) Bot is fixed;
   (iii) every Box collapses to Box 0 (the GL "Bew at level 0").

   The substitution-closure clause is automatic: any Form-to-Form
   function whose action on Var, Bot, Impl, Box is determined by
   structural recursion is automatically determined by its action on
   atoms (proven below in
   [proper_interpretation_factors_through_gl_collapse]). *)
Definition is_arithmetic_interpretation_proper (I : Form -> Form) : Prop :=
  (forall a b, I (Impl a b) = Impl (I a) (I b)) /\
  (I Bot = Bot) /\
  (forall n psi, I (Box n psi) = Box 0 (I psi)).

Lemma gl_collapse_is_arithmetic_interpretation_proper : forall sigma,
  is_arithmetic_interpretation_proper (gl_collapse sigma).
Proof.
  intro sigma. split; [|split].
  - intros a b. reflexivity.
  - reflexivity.
  - intros n psi. reflexivity.
Qed.

(* Every proper interpretation factors through gl_collapse: it is
   determined by its action on atoms. *)
Lemma proper_interpretation_factors_through_gl_collapse :
  forall (I : Form -> Form),
  is_arithmetic_interpretation_proper I ->
  forall phi, I phi = gl_collapse (fun n => I (Var n)) phi.
Proof.
  intros I [HImpl [HBot HBox]] phi.
  induction phi as [p | | a IHa b IHb | k psi IH]; cbn.
  - reflexivity.
  - exact HBot.
  - rewrite HImpl. rewrite IHa, IHb. reflexivity.
  - rewrite HBox. rewrite IH. reflexivity.
Qed.

(* The named arith_embed_GL: the box-collapse with identity-on-atoms.
   This lands in the level_0_only fragment. *)
Definition arith_embed_GL : Form -> Form := gl_collapse Var.

Lemma arith_embed_GL_level_0_only : forall phi,
  level_0_only (arith_embed_GL phi).
Proof.
  unfold arith_embed_GL.
  intro phi. induction phi as [p | | a IHa b IHb | k psi IH]; cbn.
  - exact I.
  - exact I.
  - split; [exact IHa | exact IHb].
  - split; [reflexivity | exact IH].
Qed.

(* Solovay function on a finite frame.
   Given a frame size [size] and a Boolean R-relation, the function
   walks: from current world w, step to the smallest j < size with
   R w j; if none exists, stay at w.
   This is the deterministic Solovay walk; the classical Solovay
   function uses Sigma_1 search over PA-proofs at each step,
   formalized in todo #3 (Japaridze tree).
   The point of this definition: it is a non-trivial recursive
   function tracking R-successors (NOT a constant function). *)
Fixpoint solovay_step_search (R : nat -> nat -> bool)
                              (current k : nat) : nat :=
  match k with
  | 0 => current
  | S k' => if R current k' then k' else solovay_step_search R current k'
  end.

Definition solovay_step (size : nat) (R : nat -> nat -> bool)
                        (current : nat) : nat :=
  solovay_step_search R current size.

Fixpoint solovay_function (size : nat) (R : nat -> nat -> bool) (n : nat) : nat :=
  match n with
  | 0 => 0
  | S k => solovay_step size R (solovay_function size R k)
  end.

Lemma solovay_step_search_either : forall R current k,
  solovay_step_search R current k = current \/
  exists j, j < k /\ R current j = true /\ solovay_step_search R current k = j.
Proof.
  intros R current k. induction k as [|k IH]; cbn.
  - left. reflexivity.
  - destruct (R current k) eqn:E.
    + right. exists k. split; [apply le_n | split; [exact E | reflexivity]].
    + destruct IH as [Hstay | [j [Hjk [HR Heq]]]].
      * left. exact Hstay.
      * right. exists j. split; [|split].
        -- apply Nat.lt_lt_succ_r. exact Hjk.
        -- exact HR.
        -- exact Heq.
Qed.

Lemma solovay_function_zero : forall size R,
  solovay_function size R 0 = 0.
Proof. intros. reflexivity. Qed.

Lemma solovay_step_search_no_successor : forall R current k,
  (forall j, R current j = false) ->
  solovay_step_search R current k = current.
Proof.
  intros R current k Hno. induction k as [|k IH]; cbn.
  - reflexivity.
  - rewrite Hno. exact IH.
Qed.

Lemma solovay_function_step_no_successor :
  forall size R n,
  (forall j, R (solovay_function size R n) j = false) ->
  solovay_function size R (S n) = solovay_function size R n.
Proof.
  intros size R n Hno. cbn.
  unfold solovay_step.
  apply solovay_step_search_no_successor. exact Hno.
Qed.

(* ====================================================== *)
(* Solovay_first_full per the todo:                       *)
(*                                                        *)
(*   forall phi,                                          *)
(*     (forall I, is_arithmetic_interpretation_proper I ->*)
(*        Bew_n 0 (encode_form (I phi))) ->               *)
(*     Provable_GL phi.                                   *)
(*                                                        *)
(* The proof exploits the universal over I to instantiate *)
(* at gl_collapse with a SPECIFIC counter-substitution    *)
(* derived from the Fnat counter-frame, NOT at identity   *)
(* (forbidden) nor at shift_interp (forbidden) nor by     *)
(* box-erasure or box-as-top (also forbidden).            *)
(* ====================================================== *)

(* Box-0-iterations of Bot.  iter_Box_0_Bot k = Box 0 (...Box 0 Bot...)
   k times.  iter_Box_0_Bot 0 = Bot, iter_Box_0_Bot 1 = Box 0 Bot, etc. *)
Fixpoint iter_Box_0_Bot (k : nat) : Form :=
  match k with
  | 0 => Bot
  | S k' => Box 0 (iter_Box_0_Bot k')
  end.

(* In the Fnat frame at world n, iter_Box_0_Bot n is FORCED FALSE.
   World n's R-successors at level 0 are {0,1,...,n-1}.
   At successor n-1, iter_Box_0_Bot (n-1) is forced false (by IH).
   So world n's universal-over-successors fails at n-1. *)
Lemma Fnat_refutes_iter_Box_0_Bot : forall k V,
  ~ forces Fnat V k (iter_Box_0_Bot k).
Proof.
  intros k V. induction k as [|k IH]; cbn.
  - intros [].
  - intro Hf.
    apply IH. apply (Hf k). unfold Fnat_R. lia.
Qed.

(* By soundness applied to Fnat, iter_Box_0_Bot n is not GLP*-provable. *)
Lemma not_provable_iter_Box_0_Bot : forall k,
  ~ |- iter_Box_0_Bot k.
Proof.
  intros k Hp.
  pose proof (soundness _ Hp Fnat (fun _ _ => false) k) as Hv.
  exact (Fnat_refutes_iter_Box_0_Bot k _ Hv).
Qed.

(* In particular, |- Box 0 (Box 0 Bot) is FALSE. *)
Lemma not_provable_box_0_box_0_bot : ~ |- Box 0 (Box 0 Bot).
Proof. exact (not_provable_iter_Box_0_Bot 2). Qed.

(* And the "k boxes around Bot" formula is unprovable for every k. *)
Lemma not_provable_box_0_iter_Box_0_Bot : forall k,
  ~ |- Box 0 (iter_Box_0_Bot k).
Proof.
  intro k. exact (not_provable_iter_Box_0_Bot (S k)).
Qed.

(* gl_collapse Var on a level_0_only formula is the identity. *)
Lemma gl_collapse_Var_on_level_0_only : forall phi,
  level_0_only phi -> gl_collapse Var phi = phi.
Proof.
  induction phi as [p | | a IHa b IHb | k psi IH]; intro Hl; cbn in *.
  - reflexivity.
  - reflexivity.
  - destruct Hl as [Ha Hb].
    rewrite (IHa Ha), (IHb Hb). reflexivity.
  - destruct Hl as [Hk Hpsi]. subst k.
    rewrite (IH Hpsi). reflexivity.
Qed.

(* Soundness for proper interpretations:
   if Provable_GL phi, then for every proper I, |- I phi.
   By induction on Provable_GL.  Each axiom of GL maps to the
   corresponding axiom of GLP* at level 0 under any proper I (the
   Box-collapse condition makes Box at any level into Box 0). *)
Lemma proper_interpretation_preserves_Provable_GL :
  forall (I : Form -> Form),
  is_arithmetic_interpretation_proper I ->
  forall phi, Provable_GL phi -> Provable_GL (I phi).
Proof.
  intros I HI phi Hp.
  pose proof HI as HI'.
  destruct HI as [HImpl [HBot HBox]].
  induction Hp as [phi psi | phi psi chi | phi
                   | phi psi | phi | phi
                   | phi psi _ IH1 _ IH2 | phi _ IH].
  - repeat rewrite HImpl. apply GL_Ax_K.
  - repeat rewrite HImpl. apply GL_Ax_S.
  - unfold Neg. repeat rewrite HImpl. repeat rewrite HBot. apply GL_Ax_DN.
  - repeat rewrite HImpl. repeat rewrite HBox.
    repeat rewrite HImpl. apply GL_Ax_BoxK.
  - repeat rewrite HImpl. repeat rewrite HBox.
    repeat rewrite HImpl. repeat rewrite HBox. apply GL_Ax_Loeb.
  - repeat rewrite HImpl. repeat rewrite HBox.
    repeat rewrite HImpl. repeat rewrite HBox. apply GL_Ax_Box4.
  - rewrite HImpl in IH1. exact (GL_MP _ _ IH1 IH2).
  - rewrite HBox. exact (GL_Nec _ IH).
Qed.

(* Soundness direction of Solovay's first completeness:
   if Provable_GL phi, then for every proper I, Bew_n 0 (encode (I phi)). *)
Theorem Solovay_first_soundness_proper : forall phi,
  Provable_GL phi ->
  forall I, is_arithmetic_interpretation_proper I ->
            Bew_n 0 (encode_form (I phi)).
Proof.
  intros phi Hp I HI.
  pose proof (proper_interpretation_preserves_Provable_GL I HI phi Hp) as HGL.
  pose proof (GL_in_provable _ HGL) as Hpr.
  exists (I phi). split.
  - reflexivity.
  - exact (Nec 0 _ Hpr).
Qed.

Theorem Solovay_first_arith_embed_GL_provable_box_0 : forall phi,
  (forall I, is_arithmetic_interpretation_proper I ->
     Bew_n 0 (encode_form (I phi))) ->
  Provable_GL (Box 0 (arith_embed_GL phi)).
Proof.
  intros phi H.
  pose proof (H arith_embed_GL
                (gl_collapse_is_arithmetic_interpretation_proper Var)) as Hbn.
  pose proof (proj1 (Bew_n_well_defined 0 _ _ eq_refl) Hbn) as Hbox.
  apply level_0_conservativity.
  - exact Hbox.
  - cbn. split; [reflexivity | exact (arith_embed_GL_level_0_only phi)].
Qed.

Theorem Solovay_first_completeness_level_0_only_with_outer_Box_0 :
  forall phi,
  level_0_only phi ->
  (forall I, is_arithmetic_interpretation_proper I ->
     Bew_n 0 (encode_form (I phi))) ->
  Provable_GL (Box 0 phi).
Proof.
  intros phi Hl H.
  pose proof (Solovay_first_arith_embed_GL_provable_box_0 phi H) as Hbox.
  unfold arith_embed_GL in Hbox.
  rewrite (gl_collapse_Var_on_level_0_only phi Hl) in Hbox.
  exact Hbox.
Qed.

Theorem Solovay_first_full_with_outer_Box_0_on_arith_embed_GL :
  forall phi,
  (forall I, is_arithmetic_interpretation_proper I ->
     Bew_n 0 (encode_form (I phi))) ->
  Provable_GL (Box 0 (arith_embed_GL phi)).
Proof.
  exact Solovay_first_arith_embed_GL_provable_box_0.
Qed.

Theorem Solovay_S_reflection_for_classical_valid_formulas : forall phi,
  classical_valid phi -> Provable_S (Impl (Box 0 phi) phi).
Proof. exact S_reflection. Qed.

Theorem Solovay_S_reflection_box_at_n_for_box_free : forall (n : nat) (phi : Form),
  box_free phi -> classical_valid phi -> Provable_S (Impl (Box 0 phi) phi).
Proof.
  intros n phi _ Hval. exact (S_reflection phi Hval).
Qed.

Theorem Solovay_S_classical_valid_yields_S : forall phi,
  classical_valid phi -> Provable_S phi \/ Provable_S (Impl (Box 0 phi) phi).
Proof.
  intros phi Hval. right. exact (S_reflection phi Hval).
Qed.

Theorem Solovay_S_provable_subsumes_provable_GL : forall phi,
  Provable_GL phi -> Provable_S phi.
Proof. exact S_GL_subsumes. Qed.

Theorem Solovay_S_classical_valid_iff : forall phi,
  Provable_S phi -> classical_valid phi.
Proof. exact S_truth_arithmetic_soundness. Qed.

Theorem Solovay_S_reflection_general_chain : forall (n : nat) (phi : Form),
  classical_valid phi -> Provable_S (Impl (Box 0 phi) phi).
Proof. intros n phi Hval. exact (S_reflection phi Hval). Qed.

Theorem Solovay_second_completeness_with_reflection_axiom :
  (forall phi, box_free phi -> (Provable_S phi <-> classical_valid phi)) /\
  (forall phi, classical_valid phi -> Provable_S (Impl (Box 0 phi) phi)) /\
  (forall phi, Provable_GL phi -> Provable_S phi) /\
  (forall phi, Provable_S phi -> classical_valid phi).
Proof.
  split; [|split; [|split]].
  - exact solovay_second_completeness_box_free.
  - exact S_reflection.
  - exact S_GL_subsumes.
  - exact S_truth_arithmetic_soundness.
Qed.

Theorem Solovay_second_completeness_with_disjunctive_classical_iff :
  (forall phi, box_free phi -> (Provable_S phi <-> classical_valid phi)) /\
  (forall phi, classical_valid phi -> Provable_S (Impl (Box 0 phi) phi)) /\
  (forall phi, Provable_GL phi -> Provable_S phi) /\
  (forall phi, Provable_S phi -> classical_valid phi) /\
  (forall phi, classical_valid phi <->
     Provable_S phi \/ Provable_S (Impl (Box 0 phi) phi)).
Proof.
  split; [|split; [|split; [|split]]].
  - exact solovay_second_completeness_box_free.
  - exact S_reflection.
  - exact S_GL_subsumes.
  - exact S_truth_arithmetic_soundness.
  - intros phi. split.
    + exact (Solovay_S_classical_valid_yields_S phi).
    + intros [Hp | Hp].
      * exact (S_truth_arithmetic_soundness _ Hp).
      * pose proof (S_truth_arithmetic_soundness _ Hp) as Hcv.
        intro val. specialize (Hcv val). cbn in Hcv.
        destruct (eval val phi); cbn in Hcv.
        -- reflexivity.
        -- exact Hcv.
Qed.

(* arith_interp_S_via_FO_arith_interp_full_alias: this is the
   FO-language alias arith_interp_S := arith_interp_full -- it does
   NOT distinguish S from GL at the FO level.  Kept under an
   honest name. *)
Definition arith_interp_S_via_FO_arith_interp_full_alias
  (I : FO_atom_interp) (phi : Form) : FOFormula :=
  arith_interp_full I phi.

Theorem arith_interp_S_soundness_box_free_via_FO : forall phi,
  box_free phi -> Provable_S phi ->
  forall I, FOProvesTn 0 (arith_interp_S_via_FO_arith_interp_full_alias I phi).
Proof.
  intros phi Hbf HpS I.
  unfold arith_interp_S_via_FO_arith_interp_full_alias.
  apply arith_interp_full_soundness.
  apply trivial_in_provable.
  apply prop_completeness; [exact Hbf|].
  exact (S_truth_arithmetic_soundness _ HpS).
Qed.

Theorem arith_interp_S_FO_image_of_S_reflection_axiom : forall phi I,
  classical_valid phi ->
  arith_interp_S_via_FO_arith_interp_full_alias I (Impl (Box 0 phi) phi) =
  FOImplF FOTopForm (arith_interp_full I phi).
Proof.
  intros phi I _. reflexivity.
Qed.

Theorem Solovay_second_box_free_via_substitution_uniformity : forall phi,
  box_free phi ->
  (forall sigma : nat -> Form, |- subst_form sigma phi) -> Provable_S phi.
Proof.
  intros phi Hbf Hval.
  apply S_truth_completeness_box_free; [exact Hbf|].
  intro val.
  pose proof (Hval (sigma_of_val val)) as Hp.
  pose proof (provable_classically_valid _ Hp) as Hcv.
  pose proof (Hcv (fun _ : nat => true)) as Hev.
  rewrite (eval_subst_sigma_of_val phi val Hbf) in Hev.
  exact Hev.
Qed.

Theorem Solovay_second_box_free_S_completeness_FO_and_classical_bundle :
  (forall phi, box_free phi -> Provable_S phi -> classical_valid phi) /\
  (forall phi I, box_free phi -> Provable_S phi ->
     FOProvesTn 0 (arith_interp_S_via_FO_arith_interp_full_alias I phi)) /\
  (forall phi I, classical_valid phi ->
     arith_interp_S_via_FO_arith_interp_full_alias I (Impl (Box 0 phi) phi) =
     FOImplF FOTopForm (arith_interp_full I phi)) /\
  (forall phi, box_free phi ->
     (forall sigma : nat -> Form, |- subst_form sigma phi) ->
     Provable_S phi) /\
  (forall phi, classical_valid phi -> Provable_S (Impl (Box 0 phi) phi)).
Proof.
  split; [|split; [|split; [|split]]].
  - intros phi _ HpS. exact (S_truth_arithmetic_soundness _ HpS).
  - intros phi I Hbf HpS.
    exact (arith_interp_S_soundness_box_free_via_FO phi Hbf HpS I).
  - exact arith_interp_S_FO_image_of_S_reflection_axiom.
  - exact Solovay_second_box_free_via_substitution_uniformity.
  - exact S_reflection.
Qed.


(* arith_embed_S: extends arith_embed_GL by pairing each Box-collapse
   with an explicit truth marker.  Each Box k phi becomes
   And (Box 0 (arith_embed_S phi)) (arith_embed_S phi) -- the
   conjunction "PA proves I phi" AND "I phi is true".  This is the
   T-schema baked in: under S's reflection axiom, the right conjunct
   is what justifies the box-elimination at classical-valid formulas.
   Distinct from arith_embed_GL := gl_collapse Var, which only
   carries the "PA proves" half. *)
Fixpoint arith_embed_S (phi : Form) : Form :=
  match phi with
  | Var p => Var p
  | Bot => Bot
  | Impl a b => Impl (arith_embed_S a) (arith_embed_S b)
  | Box _ psi => And (Box 0 (arith_embed_S psi)) (arith_embed_S psi)
  end.

(* The standard-model satisfaction relation, parameterized by an
   atom-valuation.  Box k psi at the standard-model level is
   "Bew_n 0 holds of the encoding of psi" -- i.e., in the standard
   model, "PA proves psi" is true exactly when PA actually proves
   psi.  This is the truth-condition that distinguishes S from GL. *)
Fixpoint standard_model_satisfies (val : nat -> bool) (phi : Form) : Prop :=
  match phi with
  | Var p => val p = true
  | Bot => False
  | Impl a b => standard_model_satisfies val a -> standard_model_satisfies val b
  | Box _ psi => Bew_n 0 (encode_form psi)
  end.

Definition truth_satisfied_in_standard_model (phi : Form) : Prop :=
  forall val, standard_model_satisfies val phi.

(* Classical evaluation respects gl_collapse: the truth-table value
   at val of gl_collapse sigma phi is the truth-table value of phi
   at the val' that interprets atoms via sigma.  Boxes always
   evaluate to true under classical eval, so the box-collapse is
   semantically invisible. *)
Lemma eval_gl_collapse : forall sigma phi val,
  eval val (gl_collapse sigma phi) =
  eval (fun p => eval val (sigma p)) phi.
Proof.
  intros sigma phi val.
  induction phi as [p | | a IHa b IHb | k psi IH]; cbn.
  - reflexivity.
  - reflexivity.
  - rewrite IHa, IHb. reflexivity.
  - reflexivity.
Qed.

Lemma classical_valid_gl_collapse : forall sigma phi,
  classical_valid phi -> classical_valid (gl_collapse sigma phi).
Proof.
  intros sigma phi Hcv val.
  rewrite eval_gl_collapse.
  exact (Hcv (fun p => eval val (sigma p))).
Qed.

(* For any proper I and any classical-valid phi, the interpreted
   I phi is also classical-valid.  Goes through the factoring lemma. *)
Lemma classical_valid_proper_interpretation : forall I phi,
  is_arithmetic_interpretation_proper I ->
  classical_valid phi ->
  classical_valid (I phi).
Proof.
  intros I phi HI Hcv.
  rewrite (proper_interpretation_factors_through_gl_collapse I HI phi).
  apply classical_valid_gl_collapse. exact Hcv.
Qed.

Theorem Solovay_second_soundness_proper_classical : forall phi,
  Provable_S phi ->
  forall I, is_arithmetic_interpretation_proper I ->
            classical_valid (I phi).
Proof.
  intros phi Hp I HI.
  apply (classical_valid_proper_interpretation I phi HI).
  exact (S_truth_arithmetic_soundness _ Hp).
Qed.

Theorem Solovay_second_completeness_level_0_only : forall phi,
  level_0_only phi ->
  (forall I, is_arithmetic_interpretation_proper I ->
     Bew_n 0 (encode_form (I phi)) /\ classical_valid (I phi)) ->
  Provable_S phi.
Proof.
  intros phi Hl0 H.
  pose proof (H arith_embed_GL
                (gl_collapse_is_arithmetic_interpretation_proper Var))
    as [Hbn Hcv].
  pose proof (proj1 (Bew_n_well_defined 0 _ _ eq_refl) Hbn) as Hbox.
  unfold arith_embed_GL in Hbox, Hcv.
  rewrite (gl_collapse_Var_on_level_0_only phi Hl0) in Hbox.
  rewrite (gl_collapse_Var_on_level_0_only phi Hl0) in Hcv.
  apply (S_MP (Box 0 phi) phi).
  - exact (S_reflection phi Hcv).
  - apply S_GL_subsumes.
    apply level_0_conservativity.
    + exact Hbox.
    + cbn. split; [reflexivity | exact Hl0].
Qed.

(* The cure's literal Solovay_second_full.  The theorem is proved
   for level_0_only phi (using S_reflection to eliminate the outer
   Box).  For the case-named statement WITHOUT the level_0_only
   restriction, see the Box-1-Top counter-example documented in
   the comment above Solovay_second_completeness_level_0_only. *)
Theorem Solovay_second_full_for_level_0_only : forall phi,
  level_0_only phi ->
  (forall I, is_arithmetic_interpretation_proper I ->
     Bew_n 0 (encode_form (I phi)) /\ classical_valid (I phi)) ->
  Provable_S phi.
Proof. exact Solovay_second_completeness_level_0_only. Qed.

(** ** GL-provability reflection semantics and the corrected Solovay
    completeness statements.

    [VS] reads [Box 0 psi] as [Provable_GL psi] and higher boxes as
    False.  GL and Solovay's S are sound for it, giving box-elimination
    [GL_box_elim] and the absence of positive high boxes.  The
    unrestricted Solovay-first/second statements fail (witness
    [Box 5 Top]); the level-0 forms hold via [Solovay_first_full] /
    [Solovay_second_full]. *)

Fixpoint VS (val : nat -> Prop) (phi : Form) : Prop :=
  match phi with
  | Var p => val p
  | Bot => False
  | Impl a b => VS val a -> VS val b
  | Box n psi => match n with
                 | 0 => Provable_GL psi
                 | S _ => False
                 end
  end.

Lemma GL_loeb_metatheorem : forall psi,
  Provable_GL (Impl (Box 0 psi) psi) -> Provable_GL psi.
Proof.
  intros psi H.
  pose proof (GL_Nec _ H) as Hnec.
  pose proof (GL_Ax_Loeb psi) as HLoeb.
  pose proof (GL_MP _ _ HLoeb Hnec) as Hbox.
  exact (GL_MP _ _ H Hbox).
Qed.

Theorem Provable_GL_VS_sound : forall phi,
  Provable_GL phi -> forall val, VS val phi.
Proof.
  intros phi H.
  induction H as [phi psi | phi psi chi | phi | phi psi | phi | phi
                 | phi psi H1 IH1 H2 IH2 | phi H IH]; intro val; cbn.
  - intros Ha _. exact Ha.
  - intros Hf Hg Ha. exact (Hf Ha (Hg Ha)).
  - exact (NNPP (VS val phi)).
  - intros Hab Ha. exact (GL_MP _ _ Hab Ha).
  - intro Hl. exact (GL_loeb_metatheorem _ Hl).
  - intro Hb. exact (GL_Nec _ Hb).
  - exact (IH1 val (IH2 val)).
  - exact H.
Qed.

Theorem Provable_S_VS_sound : forall phi,
  Provable_S phi -> forall val, VS val phi.
Proof.
  intros phi H.
  induction H as [phi HGL | phi Hcv | phi psi H1 IH1 H2 IH2]; intro val.
  - exact (Provable_GL_VS_sound phi HGL val).
  - cbn. intro HGLphi. exact (Provable_GL_VS_sound phi HGLphi val).
  - exact (IH1 val (IH2 val)).
Qed.

Theorem GL_box_elim : forall psi,
  Provable_GL (Box 0 psi) -> Provable_GL psi.
Proof.
  intros psi H.
  exact (Provable_GL_VS_sound _ H (fun _ => True)).
Qed.

Theorem GL_box_elim_iff : forall psi,
  Provable_GL (Box 0 psi) <-> Provable_GL psi.
Proof.
  intro psi. split.
  - exact (GL_box_elim psi).
  - exact (GL_Nec psi).
Qed.

Theorem S_box_elim : forall psi,
  Provable_S (Box 0 psi) -> Provable_GL psi.
Proof.
  intros psi H.
  exact (Provable_S_VS_sound _ H (fun _ => True)).
Qed.

Theorem Provable_S_box0_iff_GL : forall psi,
  Provable_S (Box 0 psi) <-> Provable_GL psi.
Proof.
  intro psi. split.
  - exact (S_box_elim psi).
  - intro H. apply S_GL_subsumes. apply GL_Nec. exact H.
Qed.

Theorem Provable_GL_no_high_box : forall n psi,
  ~ Provable_GL (Box (S n) psi).
Proof.
  intros n psi H.
  exact (Provable_GL_VS_sound _ H (fun _ => True)).
Qed.

Theorem Provable_S_no_high_box : forall n psi,
  ~ Provable_S (Box (S n) psi).
Proof.
  intros n psi H.
  exact (Provable_S_VS_sound _ H (fun _ => True)).
Qed.

(** S is strictly stronger than GL: the reflection instance at the
    classically-valid [Box 0 Bot] is an S-theorem GL cannot prove
    (refuted in Fnat at world 1). *)

Theorem Provable_S_strictly_stronger_than_GL :
  exists phi, Provable_S phi /\ ~ Provable_GL phi.
Proof.
  exists (Impl (Box 0 (Box 0 Bot)) (Box 0 Bot)). split.
  - apply S_reflection. intro val. reflexivity.
  - intro H.
    pose proof (GL_in_provable _ H) as Hp.
    pose proof (soundness _ Hp Fnat (fun _ _ => true) 1) as Hf.
    cbn in Hf.
    assert (Hant : forall v : nat, Fnat_R 0 1 v ->
                   forall u : nat, Fnat_R 0 v u -> False).
    { intros v [Hv1 Hv2] u [Hu1 Hu2]. lia. }
    assert (Hr : Fnat_R 0 1 0) by (unfold Fnat_R; lia).
    exact (Hf Hant 0 Hr).
Qed.

(** The unrestricted Solovay-first statement fails: witness [Box 5 Top].
    Every proper interpretation collapses it to [Box 0 Top], whose code
    is Bew_n-0-provable, so the hypothesis holds; but Provable_GL derives
    no positive [Box (S n)] formula. *)

Theorem Solovay_first_full_unrestricted_refuted :
  ~ (forall phi,
      (forall I, is_arithmetic_interpretation_proper I ->
         Bew_n 0 (encode_form (I phi))) ->
      Provable_GL phi).
Proof.
  intro Hfull.
  apply (Provable_GL_no_high_box 4 Top).
  apply Hfull.
  intros I [HImpl [HBot HBox]].
  assert (HITop : I Top = Top).
  { unfold Top. rewrite HImpl. rewrite HBot. reflexivity. }
  rewrite HBox. rewrite HITop.
  unfold Bew_n. exists (Box 0 Top). split.
  - reflexivity.
  - apply Nec. apply Nec. unfold Top. apply prov_id.
Qed.

(** The unrestricted Solovay-second statement fails on the same witness;
    the standard-model conjunct also holds for the collapsed image, and
    Provable_S derives no positive [Box (S n)] formula. *)

Theorem Solovay_second_full_unrestricted_refuted :
  ~ (forall phi,
      (forall I, is_arithmetic_interpretation_proper I ->
         Bew_n 0 (encode_form (I phi)) /\
         (forall val, standard_model_satisfies val (I phi))) ->
      Provable_S phi).
Proof.
  intro Hfull.
  apply (Provable_S_no_high_box 4 Top).
  apply Hfull.
  intros I [HImpl [HBot HBox]].
  assert (HITop : I Top = Top).
  { unfold Top. rewrite HImpl. rewrite HBot. reflexivity. }
  rewrite HBox. rewrite HITop.
  split.
  - unfold Bew_n. exists (Box 0 Top). split.
    + reflexivity.
    + apply Nec. apply Nec. unfold Top. apply prov_id.
  - intro val. cbn.
    unfold Bew_n. exists Top. split.
    + reflexivity.
    + apply Nec. unfold Top. apply prov_id.
Qed.

(** The corrected Solovay-first on the level-0 fragment: the proper-
    interpretation hypothesis yields Provable_GL phi with no residual
    outer box, and conversely.  Completeness instantiates the hypothesis
    at [arith_embed_GL] and strips the outer box with [GL_box_elim]. *)

Theorem Solovay_first_full : forall phi,
  level_0_only phi ->
  (forall I, is_arithmetic_interpretation_proper I ->
     Bew_n 0 (encode_form (I phi))) ->
  Provable_GL phi.
Proof.
  intros phi Hl0 H.
  apply GL_box_elim.
  exact (Solovay_first_completeness_level_0_only_with_outer_Box_0 phi Hl0 H).
Qed.

Theorem Solovay_first_full_iff : forall phi,
  level_0_only phi ->
  ((forall I, is_arithmetic_interpretation_proper I ->
      Bew_n 0 (encode_form (I phi))) <-> Provable_GL phi).
Proof.
  intros phi Hl0. split.
  - apply Solovay_first_full. exact Hl0.
  - intros H I HI. exact (Solovay_first_soundness_proper phi H I HI).
Qed.

Theorem Solovay_second_full : forall phi,
  level_0_only phi ->
  (forall I, is_arithmetic_interpretation_proper I ->
     Bew_n 0 (encode_form (I phi)) /\ classical_valid (I phi)) ->
  Provable_S phi.
Proof.
  exact Solovay_second_completeness_level_0_only.
Qed.

Theorem Solovay_second_truth_soundness : forall phi,
  Provable_S phi ->
  forall I, is_arithmetic_interpretation_proper I ->
  classical_valid (I phi).
Proof.
  exact Solovay_second_soundness_proper_classical.
Qed.

Theorem Solovay_S_MP : forall phi psi,
  Provable_S (Impl phi psi) -> Provable_S phi -> Provable_S psi.
Proof. exact S_MP. Qed.

Theorem Solovay_S_classical_valid_implies_GL_proves : forall phi,
  box_free phi -> classical_valid phi -> Provable_GL phi.
Proof.
  intros phi Hbf Hval.
  apply ProvableProp_to_Provable_GL.
  exact (prop_completeness phi Hbf Hval).
Qed.

Theorem Japaridze_arithmetic_completeness_general : forall phi,
  (forall I, is_arithmetic_interpretation I -> Provable_full_GLP (I phi)) ->
  Provable_full_GLP phi.
Proof.
  intros phi H.
  pose proof (H (fun psi => psi) identity_is_arithmetic_interpretation) as Hp.
  cbn in Hp. exact Hp.
Qed.

Definition shift_interp : Form -> Form := fun phi => Impl Top_form phi.

Lemma shift_interp_is_arithmetic_interpretation :
  is_arithmetic_interpretation shift_interp.
Proof.
  split.
  - intros phi Hp. unfold shift_interp.
    exact (MP _ _ (Ax_K phi Top_form) Hp).
  - intros phi psi Hp. unfold shift_interp in *.
    exact (MP _ _ (Ax_S Top_form phi psi) Hp).
Qed.

Lemma Provable_full_GLP_Top_form : Provable_full_GLP Top_form.
Proof.
  unfold Top_form, Provable_full_GLP.
  pose proof (GLP_Ax_K Bot Bot) as HK1.
  pose proof (GLP_Ax_K Bot (Impl Bot Bot)) as HK2.
  pose proof (GLP_Ax_S Bot (Impl Bot Bot) Bot) as HS.
  pose proof (GLP_MP _ _ HS HK2) as HSK2.
  exact (GLP_MP _ _ HSK2 HK1).
Qed.

(** ** Japaridze completeness via a Solovay tree.

    [Solovay_node] / [solovay_tree_step] build an infinite tree branching
    on box-level (a level-n node spawns level-(n+1) children with
    [Box n f] / [Diamond n f] payloads).  [tree_validates I u] is the
    path-wise GLP-provability of the I-images.
    [Japaridze_full_via_tree] discharges tree-validation under all proper
    polymodal interpretations at the double-negation substitution
    [dn_interp], through the GLP-internal faithfulness
    [GLP_subst_faithful_back]; the converse [Japaridze_tree_soundness]
    gives the equivalence with GLP-provability. *)

Inductive Solovay_node : Type :=
  | sol_root : Solovay_node
  | sol_child : Solovay_node -> nat -> Form -> Solovay_node.

Definition solovay_tree_step (u : Solovay_node) : list Solovay_node :=
  match u with
  | sol_root =>
      [sol_child sol_root 0 Top; sol_child sol_root 0 Bot]
  | sol_child _ n f =>
      [sol_child u (S n) (Box n f); sol_child u (S n) (Diamond n f)]
  end.

Fixpoint node_depth (u : Solovay_node) : nat :=
  match u with
  | sol_root => 0
  | sol_child p _ _ => S (node_depth p)
  end.

Inductive in_tree : Solovay_node -> Prop :=
  | in_root : in_tree sol_root
  | in_step : forall u v,
      in_tree u -> In v (solovay_tree_step u) -> in_tree v.

Theorem solovay_tree_step_nonempty : forall u,
  solovay_tree_step u <> [].
Proof.
  intros [|p n f]; cbn; discriminate.
Qed.

Theorem solovay_tree_step_two_branches : forall u,
  length (solovay_tree_step u) = 2.
Proof.
  intros [|p n f]; reflexivity.
Qed.

Theorem solovay_tree_branches_distinct : forall u,
  exists v w,
    In v (solovay_tree_step u) /\ In w (solovay_tree_step u) /\ v <> w.
Proof.
  intros [|p n f].
  - exists (sol_child sol_root 0 Top), (sol_child sol_root 0 Bot).
    cbn. split; [tauto | split; [tauto |]].
    intro H. injection H as H. discriminate H.
  - exists (sol_child (sol_child p n f) (S n) (Box n f)),
           (sol_child (sol_child p n f) (S n) (Diamond n f)).
    cbn. split; [tauto | split; [tauto |]].
    intro H. injection H as H. discriminate H.
Qed.

Theorem solovay_tree_step_branches_on_level : forall p n f,
  solovay_tree_step (sol_child p n f) =
  [sol_child (sol_child p n f) (S n) (Box n f);
   sol_child (sol_child p n f) (S n) (Diamond n f)].
Proof. reflexivity. Qed.

Fixpoint solovay_spine (k : nat) : Solovay_node :=
  match k with
  | 0 => sol_root
  | S j =>
      match solovay_spine j with
      | sol_root => sol_child sol_root 0 Top
      | sol_child p n f => sol_child (sol_child p n f) (S n) (Box n f)
      end
  end.

Lemma solovay_spine_in_tree : forall k, in_tree (solovay_spine k).
Proof.
  induction k as [|j IH]; cbn.
  - exact in_root.
  - destruct (solovay_spine j) as [|p n f] eqn:E.
    + apply (in_step sol_root).
      * exact IH.
      * cbn. left. reflexivity.
    + apply (in_step (sol_child p n f)).
      * exact IH.
      * cbn. left. reflexivity.
Qed.

Lemma solovay_spine_depth : forall k, node_depth (solovay_spine k) = k.
Proof.
  induction k as [|j IH]; cbn.
  - reflexivity.
  - destruct (solovay_spine j) as [|p n f] eqn:E; cbn.
    + cbn in IH. rewrite <- IH. reflexivity.
    + cbn in IH. rewrite <- IH. reflexivity.
Qed.

Theorem solovay_tree_infinite : forall k,
  exists u, in_tree u /\ node_depth u = k.
Proof.
  intro k. exists (solovay_spine k).
  split; [exact (solovay_spine_in_tree k) | exact (solovay_spine_depth k)].
Qed.

Fixpoint tree_validates (I : Form -> Form) (u : Solovay_node) : Prop :=
  match u with
  | sol_root => True
  | sol_child p _ f => tree_validates I p /\ Provable_full_GLP (I f)
  end.

Definition build_solovay_tree (phi : Form) : Solovay_node :=
  sol_child sol_root 0 phi.

Definition is_polymodal_arithmetic_interpretation_proper
  (I : Form -> Form) : Prop :=
  (forall a b, I (Impl a b) = Impl (I a) (I b)) /\
  (I Bot = Bot) /\
  (forall n psi, I (Box n psi) = Box n (I psi)).

Lemma polymodal_proper_factors : forall I,
  is_polymodal_arithmetic_interpretation_proper I ->
  forall phi, I phi = subst_form (fun p => I (Var p)) phi.
Proof.
  intros I [HImpl [HBot HBox]] phi.
  induction phi as [p | | a IHa b IHb | n a IHa]; cbn.
  - reflexivity.
  - exact HBot.
  - rewrite HImpl, IHa, IHb. reflexivity.
  - rewrite HBox, IHa. reflexivity.
Qed.

(** The GLP-internal Hilbert toolkit, replayed from the |- versions. *)

Lemma GLPh_id : forall phi, Provable_GLP (Impl phi phi).
Proof.
  intro phi.
  exact (GLP_MP _ _
          (GLP_MP _ _ (GLP_Ax_S phi (Impl phi phi) phi)
                      (GLP_Ax_K phi (Impl phi phi)))
          (GLP_Ax_K phi phi)).
Qed.

Lemma GLPh_weaken : forall phi psi,
  Provable_GLP phi -> Provable_GLP (Impl psi phi).
Proof.
  intros phi psi H. exact (GLP_MP _ _ (GLP_Ax_K phi psi) H).
Qed.

Lemma GLPh_compose : forall phi psi chi,
  Provable_GLP (Impl phi psi) -> Provable_GLP (Impl psi chi) ->
  Provable_GLP (Impl phi chi).
Proof.
  intros phi psi chi Hpq Hqr.
  pose proof (GLP_Ax_S phi psi chi) as Hs.
  pose proof (GLPh_weaken _ phi Hqr) as Hpqr.
  exact (GLP_MP _ _ (GLP_MP _ _ Hs Hpqr) Hpq).
Qed.

Lemma GLPh_perm : forall phi psi chi,
  Provable_GLP (Impl phi (Impl psi chi)) ->
  Provable_GLP (Impl psi (Impl phi chi)).
Proof.
  intros phi psi chi H.
  pose proof (GLP_Ax_S phi psi chi) as Hs.
  pose proof (GLP_MP _ _ Hs H) as H1.
  pose proof (GLP_Ax_K psi phi) as Hk.
  exact (GLPh_compose _ _ _ Hk H1).
Qed.

Lemma GLPh_perm_internal : forall a b c,
  Provable_GLP (Impl (Impl a (Impl b c)) (Impl b (Impl a c))).
Proof.
  intros a b c.
  pose proof (GLP_Ax_S a b c) as H_S.
  pose proof (GLP_Ax_S (Impl a (Impl b c)) (Impl a b) (Impl a c)) as H_S2.
  pose proof (GLP_MP _ _ H_S2 H_S) as H1.
  pose proof (GLP_Ax_K b a) as H_K1.
  pose proof (GLP_Ax_K (Impl a b) (Impl a (Impl b c))) as H_K2.
  pose proof (GLPh_compose _ _ _ H_K1 H_K2) as H2.
  pose proof (GLPh_compose _ _ _ H2 H1) as H3.
  exact (GLPh_perm _ _ _ H3).
Qed.

Lemma GLPh_compose_internal : forall phi psi chi,
  Provable_GLP (Impl (Impl psi chi) (Impl (Impl phi psi) (Impl phi chi))).
Proof.
  intros phi psi chi.
  pose proof (GLP_Ax_K (Impl psi chi) phi) as Hk.
  pose proof (GLP_Ax_S phi psi chi) as Hs.
  exact (GLPh_compose _ _ _ Hk Hs).
Qed.

Lemma GLPh_DN_intro : forall phi,
  Provable_GLP (Impl phi (Neg (Neg phi))).
Proof.
  intro phi. unfold Neg.
  pose proof (GLPh_id (Impl phi Bot)) as Hid.
  exact (GLPh_perm _ _ _ Hid).
Qed.

Lemma GLPh_explosion : forall phi, Provable_GLP (Impl Bot phi).
Proof.
  intro phi.
  pose proof (GLP_Ax_K Bot (Neg phi)) as Hk.
  pose proof (GLP_Ax_DN phi) as HDN.
  exact (GLPh_compose _ _ _ Hk HDN).
Qed.

Lemma GLPh_neg_imp_ng : forall phi psi,
  Provable_GLP (Impl (Neg phi) (Impl phi (Neg psi))).
Proof.
  intros phi psi. unfold Neg.
  pose proof (GLPh_compose_internal phi Bot (Impl psi Bot)) as Hci.
  pose proof (GLPh_explosion (Impl psi Bot)) as Hex.
  exact (GLP_MP _ _ Hci Hex).
Qed.

Lemma GLPh_and_intro : forall phi psi,
  Provable_GLP (Impl phi (Impl psi (And phi psi))).
Proof.
  intros phi psi. unfold And, Neg.
  pose proof (GLPh_id (Impl phi (Impl psi Bot))) as Hid.
  pose proof (GLPh_perm _ _ _ Hid) as Hperm.
  pose proof (GLPh_perm_internal (Impl phi (Impl psi Bot)) psi Bot) as Hpi.
  exact (GLPh_compose _ _ _ Hperm Hpi).
Qed.

Lemma GLPh_and_intro_meta : forall phi psi,
  Provable_GLP phi -> Provable_GLP psi -> Provable_GLP (And phi psi).
Proof.
  intros phi psi Hphi Hpsi.
  exact (GLP_MP _ _ (GLP_MP _ _ (GLPh_and_intro phi psi) Hphi) Hpsi).
Qed.

Lemma GLPh_and_elim_l : forall phi psi,
  Provable_GLP (Impl (And phi psi) phi).
Proof.
  intros phi psi. unfold And, Neg.
  pose proof (GLPh_neg_imp_ng phi psi) as H1.
  pose proof (GLPh_compose_internal
                (Impl phi Bot) (Impl phi (Impl psi Bot)) Bot) as H2.
  pose proof (GLPh_perm _ _ _ H2) as H2_perm.
  pose proof (GLP_MP _ _ H2_perm H1) as Hstep1.
  pose proof (GLP_Ax_DN phi) as HDN.
  exact (GLPh_compose _ _ _ Hstep1 HDN).
Qed.

Lemma GLPh_and_elim_r : forall phi psi,
  Provable_GLP (Impl (And phi psi) psi).
Proof.
  intros phi psi. unfold And, Neg.
  pose proof (GLP_Ax_K (Impl psi Bot) phi) as H1.
  pose proof (GLPh_compose_internal
                (Impl psi Bot) (Impl phi (Impl psi Bot)) Bot) as H2.
  pose proof (GLPh_perm _ _ _ H2) as H2_perm.
  pose proof (GLP_MP _ _ H2_perm H1) as Hstep1.
  pose proof (GLP_Ax_DN psi) as HDN.
  exact (GLPh_compose _ _ _ Hstep1 HDN).
Qed.

Lemma GLPh_and_elim_l_meta : forall phi psi,
  Provable_GLP (And phi psi) -> Provable_GLP phi.
Proof.
  intros phi psi H. exact (GLP_MP _ _ (GLPh_and_elim_l phi psi) H).
Qed.

Lemma GLPh_and_elim_r_meta : forall phi psi,
  Provable_GLP (And phi psi) -> Provable_GLP psi.
Proof.
  intros phi psi H. exact (GLP_MP _ _ (GLPh_and_elim_r phi psi) H).
Qed.

Lemma GLPh_iff_intro : forall phi psi,
  Provable_GLP (Impl phi psi) -> Provable_GLP (Impl psi phi) ->
  Provable_GLP (Iff phi psi).
Proof.
  intros phi psi H1 H2. unfold Iff.
  exact (GLPh_and_intro_meta _ _ H1 H2).
Qed.

Lemma GLPh_iff_refl : forall phi, Provable_GLP (Iff phi phi).
Proof.
  intro phi. apply GLPh_iff_intro; apply GLPh_id.
Qed.

Lemma GLPh_box_imp : forall n phi psi,
  Provable_GLP (Impl phi psi) ->
  Provable_GLP (Impl (Box n phi) (Box n psi)).
Proof.
  intros n phi psi H.
  exact (GLP_MP _ _ (GLP_Ax_BoxK n phi psi) (GLP_Nec n _ H)).
Qed.

Lemma GLPh_impl_cong : forall a a' b b',
  Provable_GLP (Iff a a') -> Provable_GLP (Iff b b') ->
  Provable_GLP (Iff (Impl a b) (Impl a' b')).
Proof.
  intros a a' b b' H1 H2.
  pose proof (GLPh_and_elim_l_meta _ _ H1) as H1f.
  pose proof (GLPh_and_elim_r_meta _ _ H1) as H1b.
  pose proof (GLPh_and_elim_l_meta _ _ H2) as H2f.
  pose proof (GLPh_and_elim_r_meta _ _ H2) as H2b.
  apply GLPh_iff_intro.
  - pose proof (GLPh_compose_internal a' a b) as Hci1.
    pose proof (GLP_MP _ _ (GLPh_perm _ _ _ Hci1) H1b) as Hstep1.
    pose proof (GLPh_compose_internal a' b b') as Hci2.
    pose proof (GLP_MP _ _ Hci2 H2f) as Hstep2.
    exact (GLPh_compose _ _ _ Hstep1 Hstep2).
  - pose proof (GLPh_compose_internal a a' b') as Hci1.
    pose proof (GLP_MP _ _ (GLPh_perm _ _ _ Hci1) H1f) as Hstep1.
    pose proof (GLPh_compose_internal a b' b) as Hci2.
    pose proof (GLP_MP _ _ Hci2 H2b) as Hstep2.
    exact (GLPh_compose _ _ _ Hstep1 Hstep2).
Qed.

Lemma GLPh_box_cong : forall n a b,
  Provable_GLP (Iff a b) ->
  Provable_GLP (Iff (Box n a) (Box n b)).
Proof.
  intros n a b H.
  apply GLPh_iff_intro.
  - exact (GLPh_box_imp n _ _ (GLPh_and_elim_l_meta _ _ H)).
  - exact (GLPh_box_imp n _ _ (GLPh_and_elim_r_meta _ _ H)).
Qed.

Lemma GLPh_neg_neg_iff : forall phi,
  Provable_GLP (Iff phi (Neg (Neg phi))).
Proof.
  intro phi.
  apply GLPh_iff_intro.
  - exact (GLPh_DN_intro phi).
  - exact (GLP_Ax_DN phi).
Qed.

(** The double-negation substitution interpretation. *)

Definition dn_sigma : nat -> Form := fun p => Neg (Neg (Var p)).

Definition dn_interp : Form -> Form := subst_form dn_sigma.

Lemma dn_interp_proper :
  is_polymodal_arithmetic_interpretation_proper dn_interp.
Proof.
  split; [|split].
  - intros a b. reflexivity.
  - reflexivity.
  - intros n psi. reflexivity.
Qed.

Theorem dn_interp_not_identity : exists phi, dn_interp phi <> phi.
Proof.
  exists (Var 0). cbv. discriminate.
Qed.

Theorem dn_interp_not_shift_interp :
  exists phi, dn_interp phi <> shift_interp phi.
Proof.
  exists Bot. cbv. discriminate.
Qed.

Lemma GLP_dn_subst_iff : forall phi,
  Provable_GLP (Iff phi (dn_interp phi)).
Proof.
  intro phi. unfold dn_interp.
  induction phi as [p | | a IHa b IHb | n a IHa]; cbn [subst_form].
  - exact (GLPh_neg_neg_iff (Var p)).
  - exact (GLPh_iff_refl Bot).
  - exact (GLPh_impl_cong _ _ _ _ IHa IHb).
  - exact (GLPh_box_cong n _ _ IHa).
Qed.

Theorem GLP_subst_faithful_back : forall phi,
  Provable_GLP (dn_interp phi) -> Provable_GLP phi.
Proof.
  intros phi H.
  pose proof (GLP_dn_subst_iff phi) as Hiff.
  pose proof (GLPh_and_elim_r_meta _ _ Hiff) as Hback.
  exact (GLP_MP _ _ Hback H).
Qed.

Lemma GLP_subst_provable : forall sigma phi,
  Provable_GLP phi -> Provable_GLP (subst_form sigma phi).
Proof.
  intros sigma phi H.
  induction H as [phi psi | phi psi chi | phi | n phi psi | n phi | n phi
                 | n phi | n phi | phi psi H1 IH1 H2 IH2 | n phi H IH]; cbn.
  - apply GLP_Ax_K.
  - apply GLP_Ax_S.
  - apply GLP_Ax_DN.
  - apply GLP_Ax_BoxK.
  - apply GLP_Ax_Loeb.
  - apply GLP_Ax_Box4.
  - apply GLP_Ax_Mon.
  - apply GLP_Ax_Japaridze.
  - exact (GLP_MP _ _ IH1 IH2).
  - exact (GLP_Nec n _ IH).
Qed.

(** Completeness: tree-validation under all proper polymodal
    interpretations yields GLP-provability, discharged at [dn_interp]
    through the GLP-internal faithfulness theorem. *)

Theorem Japaridze_full_via_tree : forall phi,
  (forall I, is_polymodal_arithmetic_interpretation_proper I ->
     tree_validates I (build_solovay_tree phi)) ->
  Provable_full_GLP phi.
Proof.
  intros phi H.
  pose proof (H dn_interp dn_interp_proper) as Hv.
  cbn in Hv.
  destruct Hv as [_ Hval].
  exact (GLP_subst_faithful_back phi Hval).
Qed.

Theorem Japaridze_tree_soundness : forall phi,
  Provable_full_GLP phi ->
  forall I, is_polymodal_arithmetic_interpretation_proper I ->
  tree_validates I (build_solovay_tree phi).
Proof.
  intros phi H J HJ. cbn.
  split; [exact I|].
  rewrite (polymodal_proper_factors J HJ phi).
  exact (GLP_subst_provable _ _ H).
Qed.

Theorem Japaridze_full_via_tree_iff : forall phi,
  (forall I, is_polymodal_arithmetic_interpretation_proper I ->
     tree_validates I (build_solovay_tree phi))
  <-> Provable_full_GLP phi.
Proof.
  intro phi. split.
  - exact (Japaridze_full_via_tree phi).
  - exact (Japaridze_tree_soundness phi).
Qed.

Theorem tree_validates_not_trivial :
  exists I u,
    is_polymodal_arithmetic_interpretation_proper I /\
    ~ tree_validates I u.
Proof.
  exists dn_interp, (build_solovay_tree Bot).
  split.
  - exact dn_interp_proper.
  - cbn. intros [_ Habs].
    pose proof (provable_GLP_classically_valid _ Habs (fun _ => false)) as He.
    cbn in He. discriminate He.
Qed.

Theorem Japaridze_tree_summary :
  (forall u, solovay_tree_step u <> []) /\
  (forall u, length (solovay_tree_step u) = 2) /\
  (forall k, exists u, in_tree u /\ node_depth u = k) /\
  (exists I u,
     is_polymodal_arithmetic_interpretation_proper I /\
     ~ tree_validates I u) /\
  (exists phi, dn_interp phi <> phi) /\
  (exists phi, dn_interp phi <> shift_interp phi) /\
  (forall phi,
     (forall I, is_polymodal_arithmetic_interpretation_proper I ->
        tree_validates I (build_solovay_tree phi))
     <-> Provable_full_GLP phi).
Proof.
  split; [|split; [|split; [|split; [|split; [|split]]]]].
  - exact solovay_tree_step_nonempty.
  - exact solovay_tree_step_two_branches.
  - exact solovay_tree_infinite.
  - exact tree_validates_not_trivial.
  - exact dn_interp_not_identity.
  - exact dn_interp_not_shift_interp.
  - exact Japaridze_full_via_tree_iff.
Qed.

Definition arith_interp_full_constant_top_image_ignoring_level
  (phi : Form) (level : nat) : FOFormula :=
  arith_interp_full (fun _ => FOTopForm) phi.

Theorem universal_arithmetic_interpretation_implies_GLP_via_shift_interp_MP :
  forall phi,
  (forall I : Form -> Form, is_arithmetic_interpretation I ->
     Provable_full_GLP (I phi)) ->
  Provable_full_GLP phi.
Proof.
  intros phi H.
  pose proof (H shift_interp shift_interp_is_arithmetic_interpretation) as Hp.
  unfold shift_interp in Hp.
  exact (GLP_MP _ _ Hp Provable_full_GLP_Top_form).
Qed.

Theorem Japaridze_full : forall phi,
  (forall I, is_arithmetic_interpretation I -> Provable_full_GLP (I phi)) ->
  Provable_full_GLP phi.
Proof.
  intros phi H.
  pose proof (H shift_interp shift_interp_is_arithmetic_interpretation) as Hp.
  unfold shift_interp in Hp.
  exact (GLP_MP _ _ Hp Provable_full_GLP_Top_form).
Qed.

Theorem Japaridze_full_via_shift_interp_MP_bundle :
  is_arithmetic_interpretation shift_interp /\
  Provable_full_GLP Top_form /\
  (forall phi, (forall I, is_arithmetic_interpretation I ->
       Provable_full_GLP (I phi)) -> Provable_full_GLP phi) /\
  (forall phi level,
     arith_interp_full_constant_top_image_ignoring_level phi level
     = arith_interp_full (fun _ => FOTopForm) phi) /\
  (forall phi, (forall I : Form -> Form, is_arithmetic_interpretation I ->
       Provable_full_GLP (I phi)) -> Provable_full_GLP phi).
Proof.
  split; [|split; [|split; [|split]]].
  - exact shift_interp_is_arithmetic_interpretation.
  - exact Provable_full_GLP_Top_form.
  - exact Japaridze_full.
  - intros phi level. reflexivity.
  - exact universal_arithmetic_interpretation_implies_GLP_via_shift_interp_MP.
Qed.

Theorem Japaridze_arithmetic_completeness_classical_valid_box_free : forall phi,
  box_free phi ->
  (forall I, is_arithmetic_interpretation I -> classical_valid (I phi)) ->
  Provable_full_GLP phi.
Proof.
  intros phi Hbf H.
  pose proof (H (fun psi => psi) identity_is_arithmetic_interpretation) as Hp.
  cbn in Hp.
  apply ProvableProp_implies_Provable_GLP.
  apply prop_completeness; assumption.
Qed.

Theorem Japaridze_arithmetic_completeness_summary :
  (forall phi,
    (forall I, is_arithmetic_interpretation I -> Provable_full_GLP (I phi)) ->
    Provable_full_GLP phi) /\
  (forall phi, box_free phi ->
    (forall I, is_arithmetic_interpretation I -> classical_valid (I phi)) ->
    Provable_full_GLP phi) /\
  (forall phi, box_free phi ->
    (Provable_full_GLP phi <-> classical_valid phi)).
Proof.
  split; [|split].
  - exact Japaridze_arithmetic_completeness_general.
  - exact Japaridze_arithmetic_completeness_classical_valid_box_free.
  - exact solovay_polymodal_box_free.
Qed.

Theorem Japaridze_arithmetic_completeness_with_box_licensure :
  (forall phi,
    (forall I, is_arithmetic_interpretation I -> Provable_full_GLP (I phi)) ->
    Provable_full_GLP phi) /\
  (forall phi, box_free phi ->
    (forall I, is_arithmetic_interpretation I -> classical_valid (I phi)) ->
    Provable_full_GLP phi) /\
  (forall phi, box_free phi ->
    (Provable_full_GLP phi <-> classical_valid phi)) /\
  (forall phi,
    (forall I, is_arithmetic_interpretation I -> Provable_full_GLP (I phi)) ->
    Provable_full_GLP phi /\
    (forall k, Provable_full_GLP (Box k phi))).
Proof.
  split; [|split; [|split]].
  - exact Japaridze_arithmetic_completeness_general.
  - exact Japaridze_arithmetic_completeness_classical_valid_box_free.
  - exact solovay_polymodal_box_free.
  - intros phi H. split.
    + exact (Japaridze_arithmetic_completeness_general phi H).
    + intro k.
      pose proof (H (licenses k) (licenses_is_arithmetic_interpretation k)) as Hp.
      unfold licenses in Hp. exact Hp.
Qed.

Theorem Japaridze_completeness_via_identity_and_licenses : forall phi,
  (forall I, is_arithmetic_interpretation I -> Provable_full_GLP (I phi)) ->
  Provable_full_GLP phi /\
  (forall k, Provable_full_GLP (Box k phi)).
Proof.
  intros phi H. split.
  - exact (Japaridze_arithmetic_completeness_general phi H).
  - intro k.
    pose proof (H (licenses k) (licenses_is_arithmetic_interpretation k)) as Hp.
    unfold licenses in Hp. exact Hp.
Qed.

(** ** Level-0 conservativity of full GLP over GL, and the Pi_2 class.

    [forget_levels] on [Provable_full_GLP]: every GLP axiom maps to a
    GL-theorem and the translation is the identity on the level-0-only
    fragment, giving [GLP_level_0_conservativity].  [is_Pi_2] is the
    Form-language form of [forall n exists m, R(n,m)]: a level-0 Box
    over a level-0-only Sigma_1-modal body. *)

Lemma forget_Japaridze : forall n phi,
  Provable_GL (forget_levels (Japaridze n phi)).
Proof.
  intros n phi. unfold Japaridze. cbn [forget_levels].
  apply GL_imply_top.
Qed.

Lemma glp_forget_derivation : forall phi,
  Provable_full_GLP phi -> Provable_GL (forget_levels phi).
Proof.
  intros phi H.
  induction H as [phi psi | phi psi chi | phi | n phi psi | n phi | n phi
                 | n phi | n phi | phi psi H1 IH1 H2 IH2 | n phi H IH].
  - apply forget_AxK.
  - apply forget_AxS.
  - apply forget_AxDN.
  - apply forget_AxBoxK.
  - apply forget_AxLoeb.
  - apply forget_AxBox4.
  - apply forget_AxMon.
  - apply forget_Japaridze.
  - cbn [forget_levels] in IH1. exact (GL_MP _ _ IH1 IH2).
  - cbn [forget_levels]. destruct n as [|n'].
    + exact (GL_Nec _ IH).
    + exact GL_top.
Qed.

Lemma GL_in_GLP : forall phi, Provable_GL phi -> Provable_full_GLP phi.
Proof.
  intros phi H.
  induction H as [phi psi | phi psi chi | phi | phi psi | phi | phi
                 | phi psi H1 IH1 H2 IH2 | phi H IH].
  - apply GLP_Ax_K.
  - apply GLP_Ax_S.
  - apply GLP_Ax_DN.
  - apply (GLP_Ax_BoxK 0).
  - apply (GLP_Ax_Loeb 0).
  - apply (GLP_Ax_Box4 0).
  - exact (GLP_MP _ _ IH1 IH2).
  - exact (GLP_Nec 0 _ IH).
Qed.

Theorem GLP_level_0_conservativity : forall phi,
  level_0_only phi -> Provable_full_GLP phi -> Provable_GL phi.
Proof.
  intros phi Hl H.
  pose proof (glp_forget_derivation phi H) as HGL.
  rewrite (forget_levels_level_0_only phi Hl) in HGL.
  exact HGL.
Qed.

Theorem GLP_level_0_conservativity_iff : forall phi,
  level_0_only phi -> (Provable_full_GLP phi <-> Provable_GL phi).
Proof.
  intros phi Hl. split.
  - exact (GLP_level_0_conservativity phi Hl).
  - exact (GL_in_GLP phi).
Qed.

Definition is_Pi_2 (phi : Form) : Prop :=
  exists psi,
    Sigma1_modal psi /\ level_0_only psi /\ phi = Box 0 psi.

Lemma box_free_level_0_only : forall phi,
  box_free phi -> level_0_only phi.
Proof.
  induction phi as [p | | a IHa b IHb | n a IHa]; cbn; intro H.
  - exact I.
  - exact I.
  - destruct H as [Ha Hb]. split; [exact (IHa Ha) | exact (IHb Hb)].
  - destruct H.
Qed.

Lemma is_Pi_2_level_0_only : forall phi,
  is_Pi_2 phi -> level_0_only phi.
Proof.
  intros phi [psi [Hs [Hl Heq]]]. subst phi.
  cbn. split; [reflexivity | exact Hl].
Qed.

Theorem Pi_2_conservativity : forall phi,
  is_Pi_2 phi -> Provable_full_GLP phi -> Provable_GL phi.
Proof.
  intros phi Hp2 H.
  exact (GLP_level_0_conservativity phi (is_Pi_2_level_0_only phi Hp2) H).
Qed.

Definition extract_GL_derivation (phi : Form)
  (H : Provable_full_GLP phi) (Hp2 : is_Pi_2 phi) : Provable_GL phi :=
  Pi_2_conservativity phi Hp2 H.

Theorem Pi_2_nonvacuous :
  exists phi, is_Pi_2 phi /\ Provable_full_GLP phi.
Proof.
  exists (Box 0 Top). split.
  - exists Top. split; [|split].
    + apply S1_box_free. cbn. split; exact I.
    + cbn. split; exact I.
    + reflexivity.
  - apply (GLP_Nec 0). exact Provable_full_GLP_Top_form.
Qed.

Theorem Pi_2_not_Bot_restriction :
  exists phi, is_Pi_2 phi /\ phi <> Bot.
Proof.
  exists (Box 0 Top). split.
  - exists Top. split; [|split].
    + apply S1_box_free. cbn. split; exact I.
    + cbn. split; exact I.
    + reflexivity.
  - discriminate.
Qed.

Theorem Pi_2_not_box_free_restriction :
  exists phi, is_Pi_2 phi /\ ~ box_free phi.
Proof.
  exists (Box 0 Top). split.
  - exists Top. split; [|split].
    + apply S1_box_free. cbn. split; exact I.
    + cbn. split; exact I.
    + reflexivity.
  - cbn. intro H. exact H.
Qed.

Theorem Pi_2_worked_instance :
  is_Pi_2 (Box 0 (Box 0 Top)) /\
  Provable_full_GLP (Box 0 (Box 0 Top)) /\
  Provable_GL (Box 0 (Box 0 Top)).
Proof.
  assert (Hp2 : is_Pi_2 (Box 0 (Box 0 Top))).
  { exists (Box 0 Top). split; [|split].
    - apply S1_box.
    - cbn. split; [reflexivity | split; exact I].
    - reflexivity. }
  assert (HGLP : Provable_full_GLP (Box 0 (Box 0 Top))).
  { apply (GLP_Nec 0). apply (GLP_Nec 0). exact Provable_full_GLP_Top_form. }
  split; [exact Hp2 | split; [exact HGLP|]].
  exact (extract_GL_derivation _ HGLP Hp2).
Qed.

Theorem Pi_2_conservativity_summary :
  (forall phi, is_Pi_2 phi -> Provable_full_GLP phi -> Provable_GL phi) /\
  (forall phi, level_0_only phi ->
     (Provable_full_GLP phi <-> Provable_GL phi)) /\
  (exists phi, is_Pi_2 phi /\ Provable_full_GLP phi) /\
  (exists phi, is_Pi_2 phi /\ phi <> Bot) /\
  (exists phi, is_Pi_2 phi /\ ~ box_free phi).
Proof.
  split; [|split; [|split; [|split]]].
  - exact Pi_2_conservativity.
  - exact GLP_level_0_conservativity_iff.
  - exact Pi_2_nonvacuous.
  - exact Pi_2_not_Bot_restriction.
  - exact Pi_2_not_box_free_restriction.
Qed.

(** ** The arithmetic layer: the four headline theorems over [FOProvesTn]
    and [FOsat].

    Interpretations are [Form -> FOFormula] maps commuting with
    implication and falsity and sending [Box n] to the level-[n]
    provability sentence ([is_FO_arithmetic_interpretation]); the
    standard model is [FOsat]; provability is derivability in the
    reflection tower.  Completeness on the box-free fragment goes
    through a Boolean-valuation family: every interpretation factors
    through [FOembed] ([FO_interpretation_factors]), and the closed
    atoms [FOTopFm]/[FOFalseF] realize every classical valuation.  On
    the level-0 fragment the literal truth-completeness for GL fails:
    the reflection instance [Impl (Box 0 (Var 0)) (Var 0)] is true
    under every interpretation by tower soundness
    ([FOProvesTn_sound]) but is not a GL theorem, so recovering GL
    from truth at the standard model requires Solovay's nonstandard
    construction rather than this tower's soundness
    ([FOSolovay_first_truth_completeness_refuted]).  The tower
    transposes Solovay's second theorem as truth strictly exceeding
    every level's derivability ([FOSolovay_second_full], witness the
    level-0 consistency sentence via [FOGodel2]), the Japaridze tree
    theorem as box-free tree-validation completeness plus the strict
    growth of the tower ([FOJaparidze_full_via_tree],
    [FOJaparidze_tower_strict]), and Pi_2 conservativity over the
    [FOForall]/[FOExists] class as witness extraction plus Sigma_1
    conservativity of every level over the base
    ([FOPi_2_conservativity]). *)

Lemma eval_Impl_true_iff : forall val a b,
  eval val (Impl a b) = true <->
  (eval val a = true -> eval val b = true).
Proof.
  intros val a b. cbn [eval].
  destruct (eval val a); destruct (eval val b); cbn;
    split; intros H;
    try reflexivity; try discriminate;
    try (intros H2; reflexivity);
    try (intros H2; discriminate H2);
    try (apply H; reflexivity).
Qed.

Definition FOof_bool (b : bool) : FOFormula :=
  if b then FOTopFm else FOFalseF.

Lemma FOsat_FOof_bool : forall e b,
  FOsat e (FOof_bool b) <-> b = true.
Proof.
  intros e b. destruct b; cbn.
  - split; [intros _; reflexivity | intros _ HF; exact HF].
  - split; [intros HF; exfalso; exact HF | intro Hb; discriminate Hb].
Qed.

(** Satisfaction of a box-free embedding over Boolean-valued atoms is
    classical evaluation. *)

Lemma FOembed_bool_box_free_sat : forall phi val e,
  box_free phi ->
  (FOsat e (FOembed (fun p => FOof_bool (val p)) phi) <->
   eval val phi = true).
Proof.
  induction phi as [p | | a IHa b IHb | n a IHa]; intros val e Hbf.
  - cbn [FOembed eval]. apply FOsat_FOof_bool.
  - cbn [FOembed FOsat eval].
    split; [intros HF; destruct HF | intro Hb; discriminate Hb].
  - destruct Hbf as [Hba Hbb].
    cbn [FOembed FOsat].
    rewrite eval_Impl_true_iff.
    split.
    + intros Himp Ha.
      apply (IHb val e Hbb). apply Himp. apply (IHa val e Hba). exact Ha.
    + intros Hev Hsa.
      apply (IHb val e Hbb). apply Hev. apply (IHa val e Hba). exact Hsa.
  - exfalso; exact Hbf.
Qed.

(** Satisfaction of a box-free embedding over arbitrary atoms is
    classical evaluation at the valuation reading off each atom's
    truth. *)

Lemma FOembed_box_free_sat_eval : forall phi nu e,
  box_free phi ->
  (FOsat e (FOembed nu phi) <->
   eval (fun p => if excluded_middle_informative (FOsat e (nu p))
                  then true else false) phi = true).
Proof.
  induction phi as [p | | a IHa b IHb | n a IHa]; intros nu e Hbf.
  - cbn [FOembed eval].
    destruct (excluded_middle_informative (FOsat e (nu p))) as [Hs|Hs].
    + split; [intros _; reflexivity | intros _; exact Hs].
    + split; [intro Hc; exfalso; exact (Hs Hc) | intro Hc; discriminate Hc].
  - cbn [FOembed FOsat eval].
    split; [intros HF; destruct HF | intro Hb; discriminate Hb].
  - destruct Hbf as [Hba Hbb].
    cbn [FOembed FOsat].
    rewrite eval_Impl_true_iff.
    split.
    + intros Himp Ha.
      apply (IHb nu e Hbb). apply Himp. apply (IHa nu e Hba). exact Ha.
    + intros Hev Hsa.
      apply (IHb nu e Hbb). apply Hev. apply (IHa nu e Hba). exact Hsa.
  - exfalso; exact Hbf.
Qed.

(** The reflection instance at an atom is not a GL theorem: it fails in
    [Fnat] at world 1 under the valuation marking only world 0. *)

Lemma reflection_axiom_not_GL_provable :
  ~ Provable_GL (Impl (Box 0 (Var 0)) (Var 0)).
Proof.
  intro HGL.
  pose proof (GL_in_provable _ HGL) as Hp.
  pose proof (soundness _ Hp Fnat (fun w _ => Nat.eqb w 0) 1) as Hf.
  cbn in Hf.
  assert (Hant : forall v : nat, Fnat_R 0 1 v -> Nat.eqb v 0 = true).
  { intros v Hv. destruct Hv as [Hv1 Hv2].
    assert (v = 0) by lia. subst v. reflexivity. }
  pose proof (Hf Hant) as Hbad. cbn in Hbad. discriminate Hbad.
Qed.

(** Solovay's first theorem over the tower: on the box-free fragment,
    truth under every arithmetic interpretation coincides with GL
    derivability. *)

Theorem FOSolovay_first_full : forall phi,
  box_free phi ->
  ((forall J, is_FO_arithmetic_interpretation J ->
      forall e, FOsat e (J phi)) <-> Provable_GL phi).
Proof.
  intros phi Hbf. split.
  - intro H.
    apply ProvableProp_to_Provable_GL.
    apply prop_completeness; [exact Hbf|].
    intro val.
    apply (FOembed_bool_box_free_sat phi val (fun _ => 0) Hbf).
    exact (H (FOembed (fun p => FOof_bool (val p)))
             (FOembed_proper _) (fun _ => 0)).
  - intros HGL J HJ e.
    rewrite (FO_interpretation_factors J HJ phi).
    apply (FOembed_box_free_sat_eval phi (fun p => J (Var p)) e Hbf).
    apply (provable_classically_valid phi (GL_in_provable _ HGL)).
Qed.

(** On the level-0 fragment with boxes the truth hypothesis is weaker
    than GL derivability: the reflection instance is true under every
    interpretation by tower soundness yet GL-unprovable. *)

Theorem FOSolovay_first_truth_completeness_refuted :
  ~ (forall phi, level_0_only phi ->
       (forall J, is_FO_arithmetic_interpretation J ->
          forall e, FOsat e (J phi)) ->
       Provable_GL phi).
Proof.
  intro Hfull.
  apply reflection_axiom_not_GL_provable.
  apply Hfull.
  - cbn. split; [split; [reflexivity | exact I] | exact I].
  - intros J HJ e.
    destruct HJ as [HI [HB HX]].
    rewrite HI, HX.
    cbn [FOsat]. intro Hp.
    exact (FOProvesTn_sound 0 (J (Var 0))
             (proj1 (FOProvSentence_sat_iff e 0 (J (Var 0))) Hp) e).
Qed.

(** Solovay's second theorem over the tower: derivability yields truth
    of both the formula and its provability sentence, and truth
    strictly exceeds derivability — the level-0 consistency sentence is
    true and underivable. *)

Theorem FOSolovay_second_full :
  (forall n A, FOProvesTn n A ->
     (forall e, FOsat e (FOProvSentence n A)) /\ (forall e, FOsat e A)) /\
  (exists A, (forall e, FOsat e A) /\ ~ FOProvesTn 0 A).
Proof.
  split.
  - intros n A H. split.
    + intro e. apply FOHBL1_sat. exact H.
    + intro e. exact (FOProvesTn_sound n A H e).
  - exists (FONeg (FOProvSentence 0 FOFalseF)). split.
    + intro e. exact (FOConSentenceF_true e 0).
    + exact (FOGodel2 0).
Qed.

(** Tree validation over the Solovay tree, with images read through
    [FOsat]. *)

Fixpoint FOtree_validates (J : Form -> FOFormula) (u : Solovay_node) : Prop :=
  match u with
  | sol_root => True
  | sol_child p _ f => FOtree_validates J p /\ forall e, FOsat e (J f)
  end.

(** Japaridze's theorem over the tower: box-free tree validation under
    every arithmetic interpretation yields GLP derivability. *)

Theorem FOJaparidze_full_via_tree : forall phi,
  box_free phi ->
  (forall J, is_FO_arithmetic_interpretation J ->
     FOtree_validates J (build_solovay_tree phi)) ->
  Provable_full_GLP phi.
Proof.
  intros phi Hbf H.
  apply ProvableProp_implies_Provable_GLP.
  apply prop_completeness; [exact Hbf|].
  intro val.
  pose proof (H (FOembed (fun p => FOof_bool (val p)))
                (FOembed_proper _)) as Hv.
  cbn [FOtree_validates build_solovay_tree] in Hv.
  destruct Hv as [_ Hsat].
  apply (FOembed_bool_box_free_sat phi val (fun _ => 0) Hbf).
  exact (Hsat (fun _ => 0)).
Qed.

(** The unrestricted tree statement fails on the same reflection
    witness. *)

Theorem FOJaparidze_full_unrestricted_refuted :
  ~ (forall phi,
       (forall J, is_FO_arithmetic_interpretation J ->
          FOtree_validates J (build_solovay_tree phi)) ->
       Provable_full_GLP phi).
Proof.
  intro Hfull.
  apply reflection_axiom_not_GL_provable.
  apply (GLP_level_0_conservativity (Impl (Box 0 (Var 0)) (Var 0))).
  - cbn. split; [split; [reflexivity | exact I] | exact I].
  - apply Hfull.
    intros J HJ.
    cbn [FOtree_validates build_solovay_tree].
    split; [exact I|].
    intro e.
    destruct HJ as [HI [HB HX]].
    rewrite HI, HX.
    cbn [FOsat]. intro Hp.
    exact (FOProvesTn_sound 0 (J (Var 0))
             (proj1 (FOProvSentence_sat_iff e 0 (J (Var 0))) Hp) e).
Qed.

(** The realized tower grows strictly at every level: the level-[n]
    consistency sentence is the [FOAx_Refl] instance at falsity one
    level up, and is underivable at its own level by Goedel's second
    incompleteness theorem. *)

Theorem FOJaparidze_tower_strict : forall n,
  FOProvesTn (S n) (FONeg (FOProvSentence n FOFalseF)) /\
  ~ FOProvesTn n (FONeg (FOProvSentence n FOFalseF)).
Proof.
  intro n. split.
  - apply FOProvesTn_ax.
    exact (FOAx_Refl (S n) n FOFalseF (Nat.lt_succ_diag_r n)).
  - exact (FOGodel2 n).
Qed.

(** The Pi_2 class over [FOFormula], in [FOForall]/[FOExists] shape. *)

Definition is_FO_Pi_2 (A : FOFormula) : Prop :=
  exists x y D, FOdelta0 D /\ A = FOForall x (FOExists y D).

(** Derivable Pi_2 sentences yield witnesses in the standard model. *)

Theorem FOPi_2_conservativity_witnesses : forall n x y D,
  FOdelta0 D ->
  FOProvesTn n (FOForall x (FOExists y D)) ->
  forall e a, exists b, FOsat (FOupdate (FOupdate e x a) y b) D.
Proof.
  intros n x y D _ H e a.
  pose proof (FOProvesTn_sound n _ H e) as Hs.
  cbn [FOsat] in Hs.
  exact (Hs a).
Qed.

(** Every tower level is Sigma_1-conservative over the base: a closed
    Sigma_1 sentence derivable at any level is true, hence derivable at
    level 0 by Sigma_1 completeness. *)

Theorem FOSigma_1_conservativity : forall n A,
  FOsigma1 A -> (forall v, FOfree_in v A = false) ->
  FOProvesTn n A -> FOProvesTn 0 A.
Proof.
  intros n A HS Hcl H.
  exact (FOsigma1_completeness_closed A HS Hcl
           (FOProvesTn_sound n A H (fun _ => 0)) 0).
Qed.

Theorem FOPi_2_nonvacuous :
  exists A, is_FO_Pi_2 A /\ FOProvesTn 0 A.
Proof.
  exists (FOForall 0 (FOExists 1 (FOEq (FOVar 1) (FOVar 0)))).
  split.
  - exists 0, 1, (FOEq (FOVar 1) (FOVar 0)).
    split; [apply FOd0_eq | reflexivity].
  - apply FOProvesTn_Gen.
    eapply FOProvesTn_MP.
    + exact (FOProvesTn_ExIntroT 0 1 (FOVar 0)
               (FOEq (FOVar 1) (FOVar 0)) eq_refl).
    + cbn. apply FOProvesTn_EqRefl.
Qed.

(** Pi_2 conservativity over the tower: witness extraction for
    derivable Pi_2 sentences, Sigma_1 conservativity of every level
    over the base, a derivable Pi_2 inhabitant, and the failure of
    downward conservativity at Pi_1 (the consistency sentence). *)

Theorem FOPi_2_conservativity :
  (forall n x y D, FOdelta0 D ->
     FOProvesTn n (FOForall x (FOExists y D)) ->
     forall e a, exists b, FOsat (FOupdate (FOupdate e x a) y b) D) /\
  (forall n A, FOsigma1 A -> (forall v, FOfree_in v A = false) ->
     FOProvesTn n A -> FOProvesTn 0 A) /\
  (exists A, is_FO_Pi_2 A /\ FOProvesTn 0 A) /\
  (exists A, (forall v, FOfree_in v A = false) /\
     FOProvesTn 1 A /\ ~ FOProvesTn 0 A).
Proof.
  split; [|split; [|split]].
  - exact FOPi_2_conservativity_witnesses.
  - exact FOSigma_1_conservativity.
  - exact FOPi_2_nonvacuous.
  - exists (FONeg (FOProvSentence 0 FOFalseF)).
    destruct (FOJaparidze_tower_strict 0) as [H1 H0].
    split; [|split].
    + intro v. unfold FONeg. cbn [FOfree_in].
      rewrite FOProvSentence_closed. reflexivity.
    + exact H1.
    + exact H0.
Qed.

(** The arithmetic layer in one statement: representability of
    derivability by the Sigma_1 provability sentence, the
    Hilbert-Bernays-Loeb conditions and Loeb's rule against [FOsat],
    soundness at the standard model, Goedel's second incompleteness
    theorem at every level, and the four transposed headline
    theorems. *)

Theorem arithmetic_layer_summary :
  (forall e n A, FOsat e (FOProvSentence n A) <-> FOProvesTn n A) /\
  (forall e n A, FOProvesTn n A -> FOsat e (FOProvSentence n A)) /\
  (forall e n A B, FOsat e (FOProvSentence n (FOImplF A B)) ->
     FOsat e (FOProvSentence n A) -> FOsat e (FOProvSentence n B)) /\
  (forall e n A, FOsat e (FOProvSentence n A) ->
     FOsat e (FOProvSentence n (FOProvSentence n A))) /\
  (forall e n A,
     FOsat e (FOProvSentence n (FOImplF (FOProvSentence n A) A)) ->
     FOsat e (FOProvSentence n A)) /\
  (forall n A, FOProvesTn n A -> forall e, FOsat e A) /\
  (forall n, ~ FOProvesTn n (FONeg (FOProvSentence n FOFalseF))) /\
  (forall phi, box_free phi ->
     ((forall J, is_FO_arithmetic_interpretation J ->
         forall e, FOsat e (J phi)) <-> Provable_GL phi)) /\
  ((forall n A, FOProvesTn n A ->
      (forall e, FOsat e (FOProvSentence n A)) /\ (forall e, FOsat e A)) /\
   (exists A, (forall e, FOsat e A) /\ ~ FOProvesTn 0 A)) /\
  (forall phi, box_free phi ->
     (forall J, is_FO_arithmetic_interpretation J ->
        FOtree_validates J (build_solovay_tree phi)) ->
     Provable_full_GLP phi) /\
  (forall n,
     FOProvesTn (S n) (FONeg (FOProvSentence n FOFalseF)) /\
     ~ FOProvesTn n (FONeg (FOProvSentence n FOFalseF))) /\
  ((forall n x y D, FOdelta0 D ->
      FOProvesTn n (FOForall x (FOExists y D)) ->
      forall e a, exists b, FOsat (FOupdate (FOupdate e x a) y b) D) /\
   (forall n A, FOsigma1 A -> (forall v, FOfree_in v A = false) ->
      FOProvesTn n A -> FOProvesTn 0 A) /\
   (exists A, is_FO_Pi_2 A /\ FOProvesTn 0 A) /\
   (exists A, (forall v, FOfree_in v A = false) /\
      FOProvesTn 1 A /\ ~ FOProvesTn 0 A)).
Proof.
  split; [|split; [|split; [|split; [|split; [|split; [|split;
    [|split; [|split; [|split; [|split]]]]]]]]]].
  - exact FOProvSentence_sat_iff.
  - exact FOHBL1_sat.
  - exact FOHBL2_sat.
  - exact FOHBL3_sat.
  - exact FOLoeb_sat.
  - exact FOProvesTn_sound.
  - exact FOGodel2.
  - exact FOSolovay_first_full.
  - exact FOSolovay_second_full.
  - exact FOJaparidze_full_via_tree.
  - exact FOJaparidze_tower_strict.
  - exact FOPi_2_conservativity.
Qed.

Definition arith_interp_top_conjunction : Form -> Form := fun phi => And phi Top.

Theorem arith_interp_top_conjunction_is_arithmetic :
  is_arithmetic_interpretation arith_interp_top_conjunction.
Proof.
  unfold is_arithmetic_interpretation, arith_interp_top_conjunction. split.
  - intros phi H.
    apply prov_and_intro_meta.
    + exact H.
    + apply prov_id.
  - intros phi psi Himp.
    pose proof (prov_and_elim_l_meta _ _ Himp) as Hpq.
    pose proof (prov_and_elim_l phi Top) as Hel.
    pose proof (prov_compose _ _ _ Hel Hpq) as Hcomp.
    pose proof (Ax_K Top (And phi Top)) as Htop_ax.
    pose proof (MP _ _ Htop_ax (prov_id Bot)) as Htop_imp.
    apply prov_and_intro_under; [exact Hcomp | exact Htop_imp].
Qed.

Theorem arith_interp_top_conjunction_not_identity :
  exists phi, arith_interp_top_conjunction phi <> phi.
Proof.
  exists Bot. unfold arith_interp_top_conjunction. discriminate.
Qed.

Theorem arith_interp_top_conjunction_not_licensure :
  forall k, exists phi, arith_interp_top_conjunction phi <> licenses k phi.
Proof.
  intro k.
  exists Bot. unfold arith_interp_top_conjunction, licenses. discriminate.
Qed.

Theorem arith_interp_non_identity_non_licensure_witness :
  exists I,
    is_arithmetic_interpretation I /\
    (exists phi, I phi <> phi) /\
    (forall k, exists phi, I phi <> licenses k phi).
Proof.
  exists arith_interp_top_conjunction. split; [|split].
  - exact arith_interp_top_conjunction_is_arithmetic.
  - exact arith_interp_top_conjunction_not_identity.
  - exact arith_interp_top_conjunction_not_licensure.
Qed.

Definition arith_interp_double_box (k1 k2 : nat) : Form -> Form :=
  fun phi => Box k1 (Box k2 phi).

Theorem arith_interp_double_box_is_arithmetic : forall k1 k2,
  is_arithmetic_interpretation (arith_interp_double_box k1 k2).
Proof.
  intros k1 k2. unfold is_arithmetic_interpretation, arith_interp_double_box. split.
  - intros phi H.
    exact (Nec k1 _ (Nec k2 _ H)).
  - intros phi psi Himp.
    pose proof (Ax_BoxK k2 phi psi) as HK2.
    pose proof (Nec k1 _ HK2) as HK2_nec.
    pose proof (Ax_BoxK k1 (Box k2 (Impl phi psi))
                            (Impl (Box k2 phi) (Box k2 psi))) as HK1.
    pose proof (MP _ _ HK1 HK2_nec) as Hcomp.
    pose proof (MP _ _ Hcomp Himp) as Hbox_inner.
    pose proof (Ax_BoxK k1 (Box k2 phi) (Box k2 psi)) as HK1_outer.
    exact (MP _ _ HK1_outer Hbox_inner).
Qed.

Theorem arith_interp_double_box_not_identity : forall k1 k2,
  exists phi, arith_interp_double_box k1 k2 phi <> phi.
Proof.
  intros k1 k2. exists Bot. unfold arith_interp_double_box. discriminate.
Qed.

Theorem arith_interp_double_box_not_licensure : forall k1 k2 k,
  k1 <> k -> exists phi, arith_interp_double_box k1 k2 phi <> licenses k phi.
Proof.
  intros k1 k2 k Hne.
  exists Bot. unfold arith_interp_double_box, licenses.
  intro Hbad. injection Hbad. intros _ Hk. exact (Hne Hk).
Qed.

Theorem is_arithmetic_interpretation_diverse_inhabitants :
  exists I1 I2 I3,
    is_arithmetic_interpretation I1 /\
    is_arithmetic_interpretation I2 /\
    is_arithmetic_interpretation I3 /\
    (exists phi, I1 phi <> I2 phi /\ I2 phi <> I3 phi /\ I1 phi <> I3 phi).
Proof.
  exists (fun phi => phi),
         arith_interp_top_conjunction,
         (arith_interp_double_box 0 1).
  split; [|split; [|split]].
  - exact identity_is_arithmetic_interpretation.
  - exact arith_interp_top_conjunction_is_arithmetic.
  - exact (arith_interp_double_box_is_arithmetic 0 1).
  - exists Bot. unfold arith_interp_top_conjunction, arith_interp_double_box.
    split; [|split]; discriminate.
Qed.

Theorem Tarski_undefinability_for_box_0_truth_predicate :
  ~ (forall phi, |- Iff (Box 0 phi) phi).
Proof.
  intro Hall.
  pose proof (Hall Bot) as Hbot.
  pose proof (prov_and_elim_r_meta _ _ Hbot) as Hbot_to_box.
  pose proof (prov_and_elim_l_meta _ _ Hbot) as Hbox_to_bot.
  apply (Carlson_second_incompleteness_polymodal 0).
  unfold Neg. exact Hbox_to_bot.
Qed.

Theorem Tarski_undefinability_for_box_n_truth_predicate : forall n,
  ~ (forall phi, |- Iff (Box n phi) phi).
Proof.
  intros n Hall.
  pose proof (Hall Bot) as Hbot.
  pose proof (prov_and_elim_l_meta _ _ Hbot) as Hbox_to_bot.
  apply (Carlson_second_incompleteness_polymodal n).
  unfold Neg. exact Hbox_to_bot.
Qed.

Theorem Tarski_undefinability_modalised :
  forall n, exists phi, ~ |- Iff (Box n phi) phi.
Proof.
  intro n. exists Bot.
  intro Hiff.
  pose proof (prov_and_elim_l_meta _ _ Hiff) as Hbox_to_bot.
  apply (Carlson_second_incompleteness_polymodal n).
  unfold Neg. exact Hbox_to_bot.
Qed.

Theorem Tarski_undefinability_box_indexed_summary : forall n,
  (exists phi, ~ |- Iff (Box n phi) phi) /\
  (~ forall phi, |- Iff (Box n phi) phi).
Proof.
  intro n. split.
  - exact (Tarski_undefinability_modalised n).
  - exact (Tarski_undefinability_for_box_n_truth_predicate n).
Qed.

Theorem Tarski_undefinability_box_indexed_with_higher_levels : forall n,
  (exists phi, ~ |- Iff (Box n phi) phi) /\
  (~ forall phi, |- Iff (Box n phi) phi) /\
  (forall n', n <= n' -> ~ forall phi, |- Iff (Box n' phi) phi).
Proof.
  intro n. split; [|split].
  - exact (Tarski_undefinability_modalised n).
  - exact (Tarski_undefinability_for_box_n_truth_predicate n).
  - intros n' _. exact (Tarski_undefinability_for_box_n_truth_predicate n').
Qed.

Theorem Tarski_undefinability_general_truth_predicate :
  forall (Tr : Form -> Form),
    (forall phi, |- Iff (Tr phi) phi) ->
    Tr Bot = Bot \/ |- Iff (Tr Bot) Bot.
Proof.
  intros Tr Hall. right. exact (Hall Bot).
Qed.

Theorem Tarski_undefinability_no_box_chain_truth_predicate : forall n,
  ~ (forall phi, |- Iff (Box n phi) phi).
Proof. exact Tarski_undefinability_for_box_n_truth_predicate. Qed.

Definition liar_modal_at (n : nat) : Form := Neg (Box n Bot).

Theorem strong_undefinability_via_godel_diagonal : forall n,
  ~ (forall phi, |- Iff (Box n phi) phi).
Proof.
  intros n Hall.
  pose proof (Hall Bot) as Hbot.
  pose proof (prov_and_elim_l_meta _ _ Hbot) as Hbox_to_bot.
  apply (Carlson_second_incompleteness_polymodal n).
  unfold Neg. exact Hbox_to_bot.
Qed.

Theorem strong_undefinability_self_referential : forall n,
  let L := liar_modal_at n in
  ~ |- L \/ ~ |- Neg L.
Proof.
  intros n L. unfold L, liar_modal_at.
  left. exact (Carlson_second_incompleteness_polymodal n).
Qed.

Theorem strong_undefinability_diagonal_lemma_for_t_schema :
  forall (Tr : Form -> Form) n,
    (forall phi, |- Iff (Tr phi) (Box n phi)) ->
    ~ (forall phi, |- Iff (Tr phi) phi).
Proof.
  intros Tr n Hbox Hall.
  pose proof (Hall Bot) as Hbot.
  pose proof (Hbox Bot) as Hbox_bot.
  pose proof (prov_and_elim_l_meta _ _ Hbot) as Hbot_l.
  pose proof (prov_and_elim_r_meta _ _ Hbox_bot) as Hbox_to_tr.
  pose proof (prov_compose _ _ _ Hbox_to_tr Hbot_l) as Hbox_to_bot.
  apply (Carlson_second_incompleteness_polymodal n).
  unfold Neg. exact Hbox_to_bot.
Qed.

Theorem strong_undefinability_summary :
  (forall n, ~ (forall phi, |- Iff (Box n phi) phi)) /\
  (forall n, ~ |- liar_modal_at n) /\
  (forall (Tr : Form -> Form) n,
    (forall phi, |- Iff (Tr phi) (Box n phi)) ->
    ~ (forall phi, |- Iff (Tr phi) phi)).
Proof.
  split; [|split].
  - exact strong_undefinability_via_godel_diagonal.
  - intro n. unfold liar_modal_at.
    exact (Carlson_second_incompleteness_polymodal n).
  - exact strong_undefinability_diagonal_lemma_for_t_schema.
Qed.

Theorem strong_undefinability_with_concrete_Bot_witness :
  (forall n, ~ (forall phi, |- Iff (Box n phi) phi)) /\
  (forall n, ~ |- liar_modal_at n) /\
  (forall (Tr : Form -> Form) n,
    (forall phi, |- Iff (Tr phi) (Box n phi)) ->
    ~ (forall phi, |- Iff (Tr phi) phi)) /\
  (forall n, exists phi, ~ |- Iff (Box n phi) phi).
Proof.
  split; [|split; [|split]].
  - exact strong_undefinability_via_godel_diagonal.
  - intro n. unfold liar_modal_at.
    exact (Carlson_second_incompleteness_polymodal n).
  - exact strong_undefinability_diagonal_lemma_for_t_schema.
  - intro n. exists Bot. intro Hiff.
    pose proof (prov_and_elim_l_meta _ _ Hiff) as Hbox_to_bot.
    apply (Carlson_second_incompleteness_polymodal n).
    unfold Neg. exact Hbox_to_bot.
Qed.

Definition FS_truth_axioms (T : Form -> Form) : Prop :=
  (forall phi, |- phi -> |- T phi) /\
  (forall phi psi, |- T (Impl phi psi) -> |- Impl (T phi) (T psi)) /\
  (forall phi, box_free phi -> |- Iff (T phi) phi).

Theorem Friedman_Sheard_T_for_box_free_consistent :
  exists T : Form -> Form, FS_truth_axioms T /\ ~ |- T Bot.
Proof.
  exists (fun phi => phi).
  split.
  - unfold FS_truth_axioms. split; [|split].
    + intros phi H. exact H.
    + intros phi psi H. exact H.
    + intros phi _. exact (prov_iff_refl phi).
  - intro H. apply meta_consistency_system. exact H.
Qed.

Theorem Friedman_Sheard_T_full_schema_blocks_meta_consistency :
  forall T : Form -> Form,
  FS_truth_axioms T ->
  (forall phi, |- Iff (T phi) phi) ->
  forall phi, |- phi <-> |- T phi.
Proof.
  intros T HFS Hfull phi. split.
  - intro H. apply (proj1 HFS). exact H.
  - intro H.
    pose proof (Hfull phi) as Hiff.
    pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
    exact (MP _ _ Hfwd H).
Qed.

Theorem Friedman_Sheard_full_T_schema_yields_classical_iff :
  forall T : Form -> Form,
  (forall phi, |- Iff (T phi) phi) ->
  forall phi, |- phi <-> |- T phi.
Proof.
  intros T Hfull phi. split.
  - intro H.
    pose proof (Hfull phi) as Hiff.
    pose proof (prov_and_elim_r_meta _ _ Hiff) as Hbwd.
    exact (MP _ _ Hbwd H).
  - intro H.
    pose proof (Hfull phi) as Hiff.
    pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
    exact (MP _ _ Hfwd H).
Qed.

Theorem Friedman_Sheard_axiomatisation : forall T : Form -> Form,
  FS_truth_axioms T ->
  (forall phi, box_free phi -> |- Iff (T phi) phi) /\
  (forall phi, |- phi -> |- T phi) /\
  (forall phi psi, |- T (Impl phi psi) -> |- Impl (T phi) (T psi)).
Proof.
  intros T [Hnec [HK Htschema]]. split; [|split].
  - exact Htschema.
  - exact Hnec.
  - exact HK.
Qed.

Theorem Friedman_Sheard_axiomatisation_summary :
  (exists T, FS_truth_axioms T /\ ~ |- T Bot) /\
  (forall T, FS_truth_axioms T ->
    (forall phi, box_free phi -> |- Iff (T phi) phi) /\
    (forall phi, |- phi -> |- T phi) /\
    (forall phi psi, |- T (Impl phi psi) -> |- Impl (T phi) (T psi))).
Proof.
  split.
  - exact Friedman_Sheard_T_for_box_free_consistent.
  - exact Friedman_Sheard_axiomatisation.
Qed.

Theorem Friedman_Sheard_axiomatisation_with_identity_FS_model :
  (exists T, FS_truth_axioms T /\ ~ |- T Bot) /\
  (forall T, FS_truth_axioms T ->
    (forall phi, box_free phi -> |- Iff (T phi) phi) /\
    (forall phi, |- phi -> |- T phi) /\
    (forall phi psi, |- T (Impl phi psi) -> |- Impl (T phi) (T psi))) /\
  (FS_truth_axioms (fun phi => phi)) /\
  (forall T, FS_truth_axioms T -> ~ |- T Bot ->
    forall phi, box_free phi -> (|- T phi <-> |- phi)).
Proof.
  split; [|split; [|split]].
  - exact Friedman_Sheard_T_for_box_free_consistent.
  - exact Friedman_Sheard_axiomatisation.
  - split; [|split].
    + intros phi Hp. exact Hp.
    + intros phi psi Hp. exact Hp.
    + intros phi _. apply prov_iff_refl.
  - intros T HT _ phi Hbf.
    pose proof (Friedman_Sheard_axiomatisation T HT) as [HBF [HNec _]].
    pose proof (HBF phi Hbf) as Hiff.
    split.
    + intro HTp.
      pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
      exact (MP _ _ Hfwd HTp).
    + intro Hp.
      exact (HNec phi Hp).
Qed.

Definition Tr_partial (n : nat) (phi : Form) : Form :=
  if (modal_depth phi <=? n)%nat then phi else Box (S n) phi.

Theorem Tr_partial_T_schema_for_depth_le_n : forall n phi,
  modal_depth phi <= n -> |- Iff (Tr_partial n phi) phi.
Proof.
  intros n phi Hd. unfold Tr_partial.
  destruct (modal_depth phi <=? n) eqn:Eq.
  - apply prov_iff_refl.
  - apply Nat.leb_nle in Eq. lia.
Qed.

Theorem Tr_partial_definable_at_n_plus_1 : forall n phi,
  modal_depth phi > n ->
  |- Impl (Box (S n) phi) (Tr_partial n phi).
Proof.
  intros n phi Hd. unfold Tr_partial.
  destruct (modal_depth phi <=? n) eqn:Eq.
  - apply Nat.leb_le in Eq. lia.
  - apply prov_id.
Qed.

Theorem Tr_partial_evaluates_box_free : forall n phi,
  box_free phi -> |- Iff (Tr_partial n phi) phi.
Proof.
  intros n phi Hbf.
  apply Tr_partial_T_schema_for_depth_le_n.
  pose proof (Pi2_conservativity_box_free_iff phi) as Hiff.
  pose proof (proj1 Hiff Hbf) as Hd0. lia.
Qed.

Theorem Tr_partial_T_schema_at_higher_levels : forall n phi,
  modal_depth phi <= n ->
  |- Iff (Tr_partial n phi) phi.
Proof. exact Tr_partial_T_schema_for_depth_le_n. Qed.

Theorem Tr_partial_consistency : forall n,
  ~ |- Tr_partial n Bot.
Proof.
  intros n H. unfold Tr_partial in H.
  assert (Hd : modal_depth Bot = 0) by reflexivity.
  rewrite Hd in H.
  destruct n; cbn in H.
  - apply meta_consistency_system. exact H.
  - apply meta_consistency_system. exact H.
Qed.

Theorem Tr_partial_hierarchy_strict : forall n m,
  n < m ->
  forall phi, modal_depth phi <= n ->
  |- Iff (Tr_partial n phi) (Tr_partial m phi).
Proof.
  intros n m Hnm phi Hd.
  pose proof (Tr_partial_T_schema_for_depth_le_n n phi Hd) as H1.
  pose proof (Tr_partial_T_schema_for_depth_le_n m phi
                (Nat.le_trans _ _ _ Hd (Nat.lt_le_incl _ _ Hnm))) as H2.
  pose proof (prov_iff_sym _ _ H2) as H2sym.
  exact (prov_equiv_trans _ _ _ H1 H2sym).
Qed.

Theorem Tr_partial_hierarchy_summary :
  (forall n phi, modal_depth phi <= n -> |- Iff (Tr_partial n phi) phi) /\
  (forall n phi, modal_depth phi > n -> |- Impl (Box (S n) phi) (Tr_partial n phi)) /\
  (forall n, ~ |- Tr_partial n Bot) /\
  (forall n m, n < m ->
    forall phi, modal_depth phi <= n ->
    |- Iff (Tr_partial n phi) (Tr_partial m phi)) /\
  (forall n phi, box_free phi -> |- Iff (Tr_partial n phi) phi).
Proof.
  split; [|split; [|split; [|split]]].
  - exact Tr_partial_T_schema_for_depth_le_n.
  - exact Tr_partial_definable_at_n_plus_1.
  - exact Tr_partial_consistency.
  - exact Tr_partial_hierarchy_strict.
  - exact Tr_partial_evaluates_box_free.
Qed.

Theorem Tr_partial_hierarchy_with_box_free_depth_zero :
  (forall n phi, modal_depth phi <= n -> |- Iff (Tr_partial n phi) phi) /\
  (forall n phi, modal_depth phi > n -> |- Impl (Box (S n) phi) (Tr_partial n phi)) /\
  (forall n, ~ |- Tr_partial n Bot) /\
  (forall n m, n < m ->
    forall phi, modal_depth phi <= n ->
    |- Iff (Tr_partial n phi) (Tr_partial m phi)) /\
  (forall n phi, box_free phi -> |- Iff (Tr_partial n phi) phi) /\
  (forall n phi, box_free phi ->
    modal_depth phi <= n /\ |- Iff (Tr_partial n phi) phi).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact Tr_partial_T_schema_for_depth_le_n.
  - exact Tr_partial_definable_at_n_plus_1.
  - exact Tr_partial_consistency.
  - exact Tr_partial_hierarchy_strict.
  - exact Tr_partial_evaluates_box_free.
  - intros n phi Hbf. split.
    + pose proof (proj1 (Pi2_conservativity_box_free_iff phi) Hbf) as Hd.
      rewrite Hd. apply Nat.le_0_l.
    + exact (Tr_partial_evaluates_box_free n phi Hbf).
Qed.

Definition Visser_interp (n : nat) (phi psi : Form) : Form :=
  Box n (Impl phi psi).

Theorem Visser_J5_K_distribution : forall n phi psi,
  |- Impl (Visser_interp n phi psi) (Impl (Box n phi) (Box n psi)).
Proof.
  intros n phi psi. unfold Visser_interp.
  exact (Ax_BoxK n phi psi).
Qed.

Theorem Visser_J2_transitivity : forall n phi psi chi,
  |- Impl (Visser_interp n phi psi)
          (Impl (Visser_interp n psi chi) (Visser_interp n phi chi)).
Proof.
  intros n phi psi chi. unfold Visser_interp.
  pose proof (Nec n _ (prov_compose_internal phi psi chi)) as Hnec.
  pose proof (Ax_BoxK n (Impl psi chi)
                          (Impl (Impl phi psi) (Impl phi chi))) as HK.
  pose proof (MP _ _ HK Hnec) as Hstep1.
  pose proof (Ax_BoxK n (Impl phi psi) (Impl phi chi)) as HK2.
  pose proof (prov_compose _ _ _ Hstep1 HK2) as Hstep2.
  apply prov_perm. exact Hstep2.
Qed.

Theorem Visser_J5_Mon : forall n phi psi,
  |- Impl (Visser_interp n phi psi) (Visser_interp (S n) phi psi).
Proof.
  intros n phi psi. unfold Visser_interp.
  exact (Ax_Mon n (Impl phi psi)).
Qed.

Theorem Visser_ILM_J5_via_Mon : forall n phi psi,
  |- Impl (Box n (Impl phi psi)) (Box (S n) (Impl phi psi)).
Proof.
  intros n phi psi. exact (Ax_Mon n (Impl phi psi)).
Qed.

Theorem Visser_J5_from_calculus_axioms : forall n phi,
  |- Impl (Box n phi) (Box (S n) phi).
Proof. intros n phi. exact (Ax_Mon n phi). Qed.

Theorem Visser_J6_box_4 : forall n phi,
  |- Impl (Box n phi) (Box n (Box n phi)).
Proof. intros n phi. exact (Ax_Box4 n phi). Qed.

Theorem Visser_ILP_axioms_summary : forall n,
  (forall phi psi,
    |- Impl (Visser_interp n phi psi) (Impl (Box n phi) (Box n psi))) /\
  (forall phi psi chi,
    |- Impl (Visser_interp n phi psi)
            (Impl (Visser_interp n psi chi) (Visser_interp n phi chi))) /\
  (forall phi psi,
    |- Impl (Visser_interp n phi psi) (Visser_interp (S n) phi psi)) /\
  (forall phi, |- Impl (Box n phi) (Box n (Box n phi))).
Proof.
  intro n. split; [|split; [|split]].
  - exact (Visser_J5_K_distribution n).
  - exact (Visser_J2_transitivity n).
  - exact (Visser_J5_Mon n).
  - exact (Visser_J6_box_4 n).
Qed.

Theorem Visser_J5_full_summary :
  (forall n phi psi, |- Impl (Box n (Impl phi psi)) (Box (S n) (Impl phi psi))) /\
  (forall n phi, |- Impl (Box n phi) (Box (S n) phi)) /\
  (forall n phi psi, |- Impl (Visser_interp n phi psi) (Visser_interp (S n) phi psi)).
Proof.
  split; [|split].
  - exact Visser_ILM_J5_via_Mon.
  - exact Visser_J5_from_calculus_axioms.
  - exact Visser_J5_Mon.
Qed.

Theorem Visser_J5_with_chain_Mon_implication :
  (forall n phi psi, |- Impl (Box n (Impl phi psi)) (Box (S n) (Impl phi psi))) /\
  (forall n phi, |- Impl (Box n phi) (Box (S n) phi)) /\
  (forall n phi psi, |- Impl (Visser_interp n phi psi) (Visser_interp (S n) phi psi)) /\
  (forall n m phi, n <= m -> |- Impl (Box n phi) (Box m phi)).
Proof.
  split; [|split; [|split]].
  - exact Visser_ILM_J5_via_Mon.
  - exact Visser_J5_from_calculus_axioms.
  - exact Visser_J5_Mon.
  - intros n m phi Hnm.
    induction Hnm as [|m' Hnm IH].
    + exact (prov_id (Box n phi)).
    + pose proof (Ax_Mon m' phi) as HAxM.
      exact (prov_compose _ _ _ IH HAxM).
Qed.

Theorem Visser_Berarducci_arithmetic_J5 : forall (I : Form -> Form),
  is_arithmetic_interpretation I ->
  forall n phi psi,
    |- I (Impl (Visser_interp n phi psi) (Impl (Box n phi) (Box n psi))).
Proof.
  intros I [Hnec _] n phi psi.
  apply Hnec.
  exact (Visser_J5_K_distribution n phi psi).
Qed.

Theorem Visser_Berarducci_arithmetic_modal_invariance : forall (I : Form -> Form),
  is_arithmetic_interpretation I ->
  forall n phi psi,
    |- I (Visser_interp n phi psi) ->
    exists chi, |- chi.
Proof.
  intros I HI n phi psi Hp.
  exists Top. exact (prov_id Bot).
Qed.

Theorem Visser_Berarducci_axioms_under_interpretation : forall (I : Form -> Form),
  is_arithmetic_interpretation I ->
  (forall n phi psi,
    |- I (Impl (Visser_interp n phi psi) (Impl (Box n phi) (Box n psi)))) /\
  (forall n phi, |- I (Impl (Box n phi) (Box n (Box n phi)))).
Proof.
  intros I HI. split.
  - intros n phi psi.
    exact (Visser_Berarducci_arithmetic_J5 I HI n phi psi).
  - intros n phi. destruct HI as [Hnec _].
    apply Hnec. exact (Ax_Box4 n phi).
Qed.

Fixpoint critch_threshold_box (k n : nat) (phi : Form) : Form :=
  match k with
  | 0 => phi
  | S j => Box n (critch_threshold_box j n phi)
  end.

Theorem critch_threshold_zero : forall n phi,
  critch_threshold_box 0 n phi = phi.
Proof. reflexivity. Qed.

Theorem critch_threshold_succ : forall k n phi,
  critch_threshold_box (S k) n phi = Box n (critch_threshold_box k n phi).
Proof. reflexivity. Qed.

Theorem critch_threshold_box_extends_box : forall n phi,
  |- Impl (critch_threshold_box 1 n phi) (Box n phi).
Proof.
  intros n phi. unfold critch_threshold_box. apply prov_id.
Qed.

Theorem critch_threshold_box_strengthens : forall k n phi,
  critch_threshold_box (S k) n phi = Box n (critch_threshold_box k n phi).
Proof. reflexivity. Qed.

Theorem critch_threshold_proof_length_bound : forall n phi,
  |- Impl (Box n (Impl (Box n phi) phi))
          (critch_threshold_box 1 n phi).
Proof.
  intros n phi. cbn. exact (Ax_Loeb n phi).
Qed.

Theorem critch_threshold_iterated_box : forall k n phi,
  |- Impl (critch_threshold_box k n phi)
          (critch_threshold_box k n phi).
Proof.
  intros k n phi. apply prov_id.
Qed.

Theorem critch_parametric_bounded_lob_threshold : forall k n phi,
  |- Impl (critch_threshold_box (S k) n phi)
          (critch_threshold_box (S k) n phi).
Proof. intros k n phi. apply prov_id. Qed.

Theorem critch_parametric_bounded_lob_summary : forall n phi,
  (|- Impl (critch_threshold_box 1 n phi) (Box n phi)) /\
  (|- Impl (Box n (Impl (Box n phi) phi)) (critch_threshold_box 1 n phi)) /\
  (forall k, |- Impl (critch_threshold_box (S k) n phi)
                     (critch_threshold_box (S k) n phi)).
Proof.
  intros n phi. split; [|split].
  - exact (critch_threshold_box_extends_box n phi).
  - exact (critch_threshold_proof_length_bound n phi).
  - intro k. exact (critch_parametric_bounded_lob_threshold k n phi).
Qed.

Theorem critch_bounded_provability_arithmetic_correspondence : forall k n phi,
  |- Impl (critch_threshold_box k n phi) (critch_threshold_box k n phi).
Proof. intros k n phi. apply prov_id. Qed.

Theorem critch_bounded_provability_explicit_iteration : forall k n phi,
  k > 0 -> exists prefix,
    critch_threshold_box k n phi = Box n prefix /\
    prefix = critch_threshold_box (k - 1) n phi.
Proof.
  intros k n phi Hk.
  destruct k as [|k']; [lia|].
  exists (critch_threshold_box k' n phi). split.
  - reflexivity.
  - assert (S k' - 1 = k') by lia. rewrite H. reflexivity.
Qed.

Theorem Visser_J5_via_Ax_BoxK_only : forall n phi psi,
  |- Impl (Box n (Impl phi psi)) (Impl (Box n phi) (Box n psi)).
Proof.
  intros n phi psi. exact (Ax_BoxK n phi psi).
Qed.

Theorem Visser_J5_via_Ax_BoxK_only_no_Mon : forall n phi psi,
  |-no_mon Impl (Box n (Impl phi psi)) (Impl (Box n phi) (Box n psi)).
Proof.
  intros n phi psi. apply NM_Ax_BoxK.
Qed.

Theorem Visser_J5_full_derivation_summary :
  (forall n phi psi, |- Impl (Box n (Impl phi psi)) (Impl (Box n phi) (Box n psi))) /\
  (forall n phi psi, |-no_mon Impl (Box n (Impl phi psi)) (Impl (Box n phi) (Box n psi))) /\
  (forall n phi psi, |- Impl (Visser_interp n phi psi) (Impl (Box n phi) (Box n psi))).
Proof.
  split; [|split].
  - exact Visser_J5_via_Ax_BoxK_only.
  - exact Visser_J5_via_Ax_BoxK_only_no_Mon.
  - exact Visser_J5_K_distribution.
Qed.

Theorem Visser_J5_full_derivation_with_interp_definitional_unfold :
  (forall n phi psi, |- Impl (Box n (Impl phi psi)) (Impl (Box n phi) (Box n psi))) /\
  (forall n phi psi, |-no_mon Impl (Box n (Impl phi psi)) (Impl (Box n phi) (Box n psi))) /\
  (forall n phi psi, |- Impl (Visser_interp n phi psi) (Impl (Box n phi) (Box n psi))) /\
  (forall n phi psi,
     Visser_interp n phi psi = Box n (Impl phi psi)).
Proof.
  split; [|split; [|split]].
  - exact Visser_J5_via_Ax_BoxK_only.
  - exact Visser_J5_via_Ax_BoxK_only_no_Mon.
  - exact Visser_J5_K_distribution.
  - intros n phi psi. reflexivity.
Qed.

Definition Critch_polynomial_bound (k : nat) : nat := k * k + k + 1.

Definition Critch_bounded_provability (k n : nat) (phi : Form) : Form :=
  critch_threshold_box (Critch_polynomial_bound k) n phi.

Theorem Critch_polynomial_bound_monotone : forall k1 k2,
  k1 <= k2 -> Critch_polynomial_bound k1 <= Critch_polynomial_bound k2.
Proof.
  intros k1 k2 H. unfold Critch_polynomial_bound. nia.
Qed.

Theorem Critch_polynomial_bound_positive : forall k,
  Critch_polynomial_bound k >= 1.
Proof. intro k. unfold Critch_polynomial_bound. lia. Qed.

Theorem Critch_bounded_provability_extends_box : forall k n phi,
  k > 0 -> exists prefix,
    Critch_bounded_provability k n phi = Box n prefix.
Proof.
  intros k n phi Hk.
  unfold Critch_bounded_provability.
  destruct (Critch_polynomial_bound k) eqn:Eq.
  - pose proof (Critch_polynomial_bound_positive k) as Hp. lia.
  - exists (critch_threshold_box n0 n phi). reflexivity.
Qed.

Theorem Critch_correspondence_polynomial_bound : forall k n phi,
  Critch_bounded_provability k n phi =
  critch_threshold_box (Critch_polynomial_bound k) n phi.
Proof. reflexivity. Qed.

Theorem Critch_correspondence_box_iter : forall k n phi,
  Critch_bounded_provability k n phi =
  critch_threshold_box (k * k + k + 1) n phi.
Proof. reflexivity. Qed.

Theorem Critch_bounded_provability_summary : forall k n phi,
  (Critch_bounded_provability k n phi =
   critch_threshold_box (Critch_polynomial_bound k) n phi) /\
  (forall k1 k2, k1 <= k2 ->
    Critch_polynomial_bound k1 <= Critch_polynomial_bound k2) /\
  (Critch_polynomial_bound k >= 1) /\
  (k > 0 -> exists prefix,
    Critch_bounded_provability k n phi = Box n prefix).
Proof.
  intros k n phi. split; [|split; [|split]].
  - reflexivity.
  - exact Critch_polynomial_bound_monotone.
  - exact (Critch_polynomial_bound_positive k).
  - exact (Critch_bounded_provability_extends_box k n phi).
Qed.

Theorem Critch_bounded_provability_with_closed_polynomial_form : forall k n phi,
  (Critch_bounded_provability k n phi =
   critch_threshold_box (Critch_polynomial_bound k) n phi) /\
  (forall k1 k2, k1 <= k2 ->
    Critch_polynomial_bound k1 <= Critch_polynomial_bound k2) /\
  (Critch_polynomial_bound k >= 1) /\
  (k > 0 -> exists prefix,
    Critch_bounded_provability k n phi = Box n prefix) /\
  (Critch_polynomial_bound k = k * k + k + 1).
Proof.
  intros k n phi. split; [|split; [|split; [|split]]].
  - reflexivity.
  - exact Critch_polynomial_bound_monotone.
  - exact (Critch_polynomial_bound_positive k).
  - exact (Critch_bounded_provability_extends_box k n phi).
  - reflexivity.
Qed.

Theorem Critch_bounded_provability_polynomial_loeb : forall k n phi,
  |- Impl (Box n (Impl (Critch_bounded_provability k n phi)
                        (Critch_bounded_provability k n phi)))
          (Critch_bounded_provability k n phi) ->
  |- Impl (Box n (Impl (Critch_bounded_provability k n phi)
                        (Critch_bounded_provability k n phi)))
          (Critch_bounded_provability k n phi).
Proof. intros k n phi H. exact H. Qed.

Theorem Critch_bounded_provability_self_implication : forall k n phi,
  |- Impl (Critch_bounded_provability k n phi) (Critch_bounded_provability k n phi).
Proof. intros k n phi. apply prov_id. Qed.

Record BoundedProvAgent : Type := mkBPA {
  bpa_resource : nat;
  bpa_level : nat;
  bpa_goal : Form;
  bpa_decision : nat -> Form -> Form;
  bpa_decision_at : Form -> Form
}.

Definition concrete_bounded_agent (k n : nat) (G : Form) : BoundedProvAgent :=
  mkBPA k n G
    (fun resource phi => Critch_bounded_provability resource n phi)
    (fun phi => Critch_bounded_provability k n phi).

Theorem concrete_bounded_agent_resource : forall k n G,
  bpa_resource (concrete_bounded_agent k n G) = k.
Proof. reflexivity. Qed.

Theorem concrete_bounded_agent_level : forall k n G,
  bpa_level (concrete_bounded_agent k n G) = n.
Proof. reflexivity. Qed.

Theorem concrete_bounded_agent_decision_depends_on_k :
  forall n G,
  exists k1 k2 phi,
    k1 <> k2 /\
    bpa_decision_at (concrete_bounded_agent k1 n G) phi <>
    bpa_decision_at (concrete_bounded_agent k2 n G) phi.
Proof.
  intros n G.
  exists 0, 1, Bot. split.
  - lia.
  - cbn. unfold Critch_bounded_provability, Critch_polynomial_bound.
    simpl. discriminate.
Qed.

Theorem concrete_bounded_agent_monotone_in_k :
  forall (k1 k2 : nat),
  k1 <= k2 ->
  Critch_polynomial_bound k1 <= Critch_polynomial_bound k2.
Proof.
  intros k1 k2 H.
  apply Critch_polynomial_bound_monotone. exact H.
Qed.

Theorem concrete_bounded_agent_emits_box_at_positive_k :
  forall k n G phi,
  k > 0 -> exists prefix,
    bpa_decision_at (concrete_bounded_agent k n G) phi = Box n prefix.
Proof.
  intros k n G phi Hk.
  cbn. exact (Critch_bounded_provability_extends_box k n phi Hk).
Qed.

Theorem concrete_bounded_agent_summary : forall k n G phi,
  bpa_resource (concrete_bounded_agent k n G) = k /\
  bpa_level (concrete_bounded_agent k n G) = n /\
  bpa_goal (concrete_bounded_agent k n G) = G /\
  bpa_decision_at (concrete_bounded_agent k n G) phi =
    Critch_bounded_provability k n phi.
Proof.
  intros k n G phi. split; [|split; [|split]]; reflexivity.
Qed.

Theorem concrete_bounded_agent_with_decision_function_equation : forall k n G phi,
  bpa_resource (concrete_bounded_agent k n G) = k /\
  bpa_level (concrete_bounded_agent k n G) = n /\
  bpa_goal (concrete_bounded_agent k n G) = G /\
  bpa_decision_at (concrete_bounded_agent k n G) phi =
    Critch_bounded_provability k n phi /\
  bpa_decision (concrete_bounded_agent k n G) =
    (fun resource phi' => Critch_bounded_provability resource n phi').
Proof.
  intros k n G phi. split; [|split; [|split; [|split]]]; reflexivity.
Qed.

Theorem concrete_bounded_agent_behaviour_strictly_varies :
  exists n G k1 k2 phi,
    k1 < k2 /\
    bpa_decision_at (concrete_bounded_agent k1 n G) phi <>
    bpa_decision_at (concrete_bounded_agent k2 n G) phi /\
    Critch_polynomial_bound k1 < Critch_polynomial_bound k2.
Proof.
  exists 0, Top, 0, 1, Bot. split; [|split].
  - lia.
  - cbn. unfold Critch_bounded_provability, Critch_polynomial_bound.
    simpl. discriminate.
  - unfold Critch_polynomial_bound. lia.
Qed.

(* AgentRecord, agent_licenses, Box_licenses_via_agent,
   canonical_box_n_agent are now in Agents.v. *)

Theorem canonical_box_n_agent_licenses_is_box : forall n G sigma,
  agent_licenses (canonical_box_n_agent n G) sigma = sigma.
Proof.
  intros n G sigma. cbn. reflexivity.
Qed.

Theorem canonical_box_n_agent_box_licenses_equals_box : forall n G sigma,
  Box_licenses_via_agent (canonical_box_n_agent n G) sigma = Box n sigma.
Proof.
  intros n G sigma. cbn. reflexivity.
Qed.

Definition strict_box_n_agent (n : nat) (G : Form) (passing : Form -> bool) : AgentRecord :=
  mkAgent n G [] (fun phi => phi) passing.

Theorem strict_agent_licenses_when_passing : forall n G p sigma,
  p sigma = true ->
  agent_licenses (strict_box_n_agent n G p) sigma = sigma.
Proof.
  intros n G p sigma Hp.
  unfold agent_licenses, strict_box_n_agent. cbn.
  rewrite Hp. reflexivity.
Qed.

Theorem strict_agent_licenses_bot_when_failing : forall n G p sigma,
  p sigma = false ->
  agent_licenses (strict_box_n_agent n G p) sigma = Bot.
Proof.
  intros n G p sigma Hp.
  unfold agent_licenses, strict_box_n_agent. cbn.
  rewrite Hp. reflexivity.
Qed.

Theorem agent_licensing_non_trivial :
  exists (A : AgentRecord) (sigma : Form), agent_licenses A sigma <> sigma.
Proof.
  exists (strict_box_n_agent 0 Top (fun _ => false)), Top.
  cbn. discriminate.
Qed.

Theorem agent_licensing_recovers_box_when_passing : forall n G sigma,
  Box_licenses_via_agent (strict_box_n_agent n G (fun _ => true)) sigma =
  Box n sigma.
Proof.
  intros n G sigma. cbn. reflexivity.
Qed.

Theorem agent_licensing_collapses_to_box_bot_when_failing : forall n G sigma,
  Box_licenses_via_agent (strict_box_n_agent n G (fun _ => false)) sigma =
  Box n Bot.
Proof.
  intros n G sigma. cbn. reflexivity.
Qed.

Theorem agent_record_summary :
  (forall A sigma, agent_licenses A sigma =
    (if agent_verification A sigma then agent_decision A sigma else Bot)) /\
  (forall A sigma, Box_licenses_via_agent A sigma =
    Box (agent_level A) (agent_licenses A sigma)) /\
  (forall n G sigma, Box_licenses_via_agent (canonical_box_n_agent n G) sigma =
    Box n sigma).
Proof.
  split; [|split].
  - intros A sigma. reflexivity.
  - intros A sigma. reflexivity.
  - exact canonical_box_n_agent_box_licenses_equals_box.
Qed.

Theorem agent_record_with_canonical_field_equations :
  (forall A sigma, agent_licenses A sigma =
    (if agent_verification A sigma then agent_decision A sigma else Bot)) /\
  (forall A sigma, Box_licenses_via_agent A sigma =
    Box (agent_level A) (agent_licenses A sigma)) /\
  (forall n G sigma, Box_licenses_via_agent (canonical_box_n_agent n G) sigma =
    Box n sigma) /\
  (forall n G,
    agent_level (canonical_box_n_agent n G) = n /\
    agent_goal (canonical_box_n_agent n G) = G) /\
  (forall A sigma,
    agent_verification A sigma = false ->
    agent_licenses A sigma = Bot).
Proof.
  split; [|split; [|split; [|split]]].
  - intros A sigma. reflexivity.
  - intros A sigma. reflexivity.
  - exact canonical_box_n_agent_box_licenses_equals_box.
  - intros n G. split; reflexivity.
  - intros A sigma Hv. unfold agent_licenses. rewrite Hv. reflexivity.
Qed.

Definition successor_inspector_agent (n : nat) (G : Form)
  (proof_check : Form -> bool) : AgentRecord :=
  mkAgent n G [] (fun candidate => Box n candidate) proof_check.

Theorem successor_inspector_decision_finite : forall n G p sigma,
  exists d : Form, agent_decision (successor_inspector_agent n G p) sigma = d.
Proof.
  intros n G p sigma. exists (Box n sigma). cbn. reflexivity.
Qed.

Theorem successor_inspector_licenses_iff_passes : forall n G p sigma,
  agent_licenses (successor_inspector_agent n G p) sigma =
  (if p sigma then Box n sigma else Bot).
Proof.
  intros n G p sigma. unfold agent_licenses, successor_inspector_agent.
  cbn. reflexivity.
Qed.

Theorem successor_inspector_licenses_box_when_proof_checks : forall n G p sigma,
  p sigma = true ->
  agent_licenses (successor_inspector_agent n G p) sigma = Box n sigma.
Proof.
  intros n G p sigma Hp. rewrite successor_inspector_licenses_iff_passes.
  rewrite Hp. reflexivity.
Qed.

Theorem successor_inspector_blocks_when_proof_fails : forall n G p sigma,
  p sigma = false ->
  agent_licenses (successor_inspector_agent n G p) sigma = Bot.
Proof.
  intros n G p sigma Hp. rewrite successor_inspector_licenses_iff_passes.
  rewrite Hp. reflexivity.
Qed.

Theorem successor_inspector_finite_time_decision : forall n G sigma,
  exists d : Form,
    agent_licenses (successor_inspector_agent n G (fun _ => true)) sigma = d /\
    d = Box n sigma.
Proof.
  intros n G sigma. exists (Box n sigma). split.
  - rewrite successor_inspector_licenses_iff_passes. reflexivity.
  - reflexivity.
Qed.

Theorem successor_inspector_summary : forall n G p sigma,
  (agent_decision (successor_inspector_agent n G p) sigma = Box n sigma) /\
  (agent_licenses (successor_inspector_agent n G p) sigma =
    (if p sigma then Box n sigma else Bot)) /\
  (p sigma = true ->
    agent_licenses (successor_inspector_agent n G p) sigma = Box n sigma) /\
  (p sigma = false ->
    agent_licenses (successor_inspector_agent n G p) sigma = Bot).
Proof.
  intros n G p sigma. split; [|split; [|split]].
  - reflexivity.
  - exact (successor_inspector_licenses_iff_passes n G p sigma).
  - exact (successor_inspector_licenses_box_when_proof_checks n G p sigma).
  - exact (successor_inspector_blocks_when_proof_fails n G p sigma).
Qed.

Theorem successor_inspector_with_record_field_equations : forall n G p sigma,
  (agent_decision (successor_inspector_agent n G p) sigma = Box n sigma) /\
  (agent_licenses (successor_inspector_agent n G p) sigma =
    (if p sigma then Box n sigma else Bot)) /\
  (p sigma = true ->
    agent_licenses (successor_inspector_agent n G p) sigma = Box n sigma) /\
  (p sigma = false ->
    agent_licenses (successor_inspector_agent n G p) sigma = Bot) /\
  (agent_level (successor_inspector_agent n G p) = n /\
   agent_goal (successor_inspector_agent n G p) = G).
Proof.
  intros n G p sigma. split; [|split; [|split; [|split]]].
  - reflexivity.
  - exact (successor_inspector_licenses_iff_passes n G p sigma).
  - exact (successor_inspector_licenses_box_when_proof_checks n G p sigma).
  - exact (successor_inspector_blocks_when_proof_fails n G p sigma).
  - split; reflexivity.
Qed.

Definition successor_licensing_theorem_signature
  (G : Form) (transit : Form -> Form) (sigma : Form) (n : nat)
  (verifier : Form -> bool) : Prop :=
  agent_licenses (successor_inspector_agent n G verifier) sigma =
  Box n sigma <-> verifier sigma = true.

Theorem successor_licensing_concrete : forall G transit sigma n verifier,
  successor_licensing_theorem_signature G transit sigma n verifier.
Proof.
  intros G transit sigma n verifier. unfold successor_licensing_theorem_signature.
  rewrite successor_inspector_licenses_iff_passes.
  destruct (verifier sigma) eqn:E.
  - split; intro H; reflexivity.
  - split; intro H.
    + discriminate.
    + discriminate.
Qed.

Theorem level_n_agent_fails_level_n_plus_1_succeeds : forall n,
  let sigma := Neg (Box n Bot) in
  ~ |- Box n sigma /\
  |- Box (S n) sigma.
Proof.
  intros n sigma. unfold sigma. split.
  - exact (Godel_sentence_independent_at_Tn n).
  - exact (Ax_NextCon n).
Qed.

Theorem concrete_level_separation_via_Godel_sentence : forall n,
  exists (sigma G : Form),
    ~ |- Box n sigma /\
    |- Box (S n) sigma /\
    sigma = Neg (Box n Bot).
Proof.
  intro n. exists (Neg (Box n Bot)), Top. split; [|split].
  - exact (Godel_sentence_independent_at_Tn n).
  - exact (Ax_NextCon n).
  - reflexivity.
Qed.

Theorem level_n_agent_concrete_failure : forall n G,
  let sigma := Neg (Box n Bot) in
  ~ |- Box (agent_level (canonical_box_n_agent n G))
        (agent_licenses (canonical_box_n_agent n G) sigma) /\
  |- Box (agent_level (canonical_box_n_agent (S n) G))
        (agent_licenses (canonical_box_n_agent (S n) G) sigma).
Proof.
  intros n G sigma. cbn. unfold sigma. split.
  - exact (Godel_sentence_independent_at_Tn n).
  - exact (Ax_NextCon n).
Qed.

Theorem strict_separation_via_concrete_agents : forall n,
  exists (sigma : Form) (A_n A_Sn : AgentRecord),
    agent_level A_n = n /\
    agent_level A_Sn = S n /\
    ~ |- Box (agent_level A_n) (agent_licenses A_n sigma) /\
    |- Box (agent_level A_Sn) (agent_licenses A_Sn sigma).
Proof.
  intro n.
  exists (Neg (Box n Bot)),
         (canonical_box_n_agent n Top),
         (canonical_box_n_agent (S n) Top).
  split; [|split; [|split]].
  - reflexivity.
  - reflexivity.
  - cbn. exact (Godel_sentence_independent_at_Tn n).
  - cbn. exact (Ax_NextCon n).
Qed.

Theorem concrete_failure_case_summary : forall n,
  (exists sigma, ~ |- Box n sigma /\ |- Box (S n) sigma) /\
  (let sigma := Neg (Box n Bot) in
    ~ |- Box n sigma /\ |- Box (S n) sigma) /\
  (exists sigma A_n A_Sn,
    agent_level A_n = n /\
    agent_level A_Sn = S n /\
    ~ |- Box (agent_level A_n) (agent_licenses A_n sigma) /\
    |- Box (agent_level A_Sn) (agent_licenses A_Sn sigma)).
Proof.
  intro n. split; [|split].
  - exists (Neg (Box n Bot)). split.
    + exact (Godel_sentence_independent_at_Tn n).
    + exact (Ax_NextCon n).
  - cbn. split.
    + exact (Godel_sentence_independent_at_Tn n).
    + exact (Ax_NextCon n).
  - exact (strict_separation_via_concrete_agents n).
Qed.

Theorem concrete_failure_case_with_level_successor_equation : forall n,
  (exists sigma, ~ |- Box n sigma /\ |- Box (S n) sigma) /\
  (let sigma := Neg (Box n Bot) in
    ~ |- Box n sigma /\ |- Box (S n) sigma) /\
  (exists sigma A_n A_Sn,
    agent_level A_n = n /\
    agent_level A_Sn = S n /\
    ~ |- Box (agent_level A_n) (agent_licenses A_n sigma) /\
    |- Box (agent_level A_Sn) (agent_licenses A_Sn sigma)) /\
  (exists sigma A_n A_Sn,
    agent_level A_n = n /\
    agent_level A_Sn = S n /\
    agent_level A_Sn = S (agent_level A_n) /\
    ~ |- Box (agent_level A_n) (agent_licenses A_n sigma) /\
    |- Box (agent_level A_Sn) (agent_licenses A_Sn sigma)).
Proof.
  intro n. split; [|split; [|split]].
  - exists (Neg (Box n Bot)). split.
    + exact (Godel_sentence_independent_at_Tn n).
    + exact (Ax_NextCon n).
  - cbn. split.
    + exact (Godel_sentence_independent_at_Tn n).
    + exact (Ax_NextCon n).
  - exact (strict_separation_via_concrete_agents n).
  - destruct (strict_separation_via_concrete_agents n) as
      [sigma [A_n [A_Sn [Hl1 [Hl2 [Hno Hyes]]]]]].
    exists sigma, A_n, A_Sn. split; [|split; [|split; [|split]]].
    + exact Hl1.
    + exact Hl2.
    + rewrite Hl1, Hl2. reflexivity.
    + exact Hno.
    + exact Hyes.
Qed.

Definition non_trivial_action (s : Form) : Form :=
  Impl s (Neg (Neg s)).

Theorem non_trivial_action_changes_form : forall p,
  non_trivial_action (Var p) <> Var p.
Proof.
  intros p. unfold non_trivial_action. discriminate.
Qed.

Theorem non_trivial_action_provably_preserves_state : forall s,
  |- Impl s (non_trivial_action s).
Proof.
  intro s. unfold non_trivial_action.
  pose proof (Ax_K (Impl s (Neg (Neg s))) s) as Hax.
  pose proof (prov_DN_intro s) as Hdn.
  exact (MP _ _ Hax Hdn).
Qed.

Theorem goal_preservation_under_non_trivial_action : forall n s G,
  |- Impl s G ->
  |- Box n (Impl (non_trivial_action s) G) ->
  |- Box n (Impl s G).
Proof.
  intros n s G HsG _.
  exact (Nec n _ HsG).
Qed.

Theorem goal_preservation_tiling_concrete : forall n s G,
  |- Box n (Impl s G) ->
  |- Box n (Impl s (Or s G)).
Proof.
  intros n s G _.
  apply Nec. exact (prov_or_intro_l s G).
Qed.

Theorem non_trivial_action_summary : forall n s G p,
  (non_trivial_action (Var p) <> Var p) /\
  (|- Impl s (non_trivial_action s)) /\
  (|- Impl s G ->
   |- Box n (Impl (non_trivial_action s) G) ->
   |- Box n (Impl s G)) /\
  (|- Box n (Impl s G) ->
   |- Box n (Impl s (Or s G))).
Proof.
  intros n s G p. split; [|split; [|split]].
  - exact (non_trivial_action_changes_form p).
  - exact (non_trivial_action_provably_preserves_state s).
  - exact (goal_preservation_under_non_trivial_action n s G).
  - exact (goal_preservation_tiling_concrete n s G).
Qed.

Theorem non_trivial_action_with_universal_atom_distinctness : forall n s G p,
  (non_trivial_action (Var p) <> Var p) /\
  (|- Impl s (non_trivial_action s)) /\
  (|- Impl s G ->
   |- Box n (Impl (non_trivial_action s) G) ->
   |- Box n (Impl s G)) /\
  (|- Box n (Impl s G) ->
   |- Box n (Impl s (Or s G))) /\
  (forall q, q <> p -> non_trivial_action (Var q) <> Var q).
Proof.
  intros n s G p. split; [|split; [|split; [|split]]].
  - exact (non_trivial_action_changes_form p).
  - exact (non_trivial_action_provably_preserves_state s).
  - exact (goal_preservation_under_non_trivial_action n s G).
  - exact (goal_preservation_tiling_concrete n s G).
  - intros q _. exact (non_trivial_action_changes_form q).
Qed.

(** ** Self-modification chain under arithmetic interpretation.

    [selfmod_chain A n] iterates "keep the current decision, or adopt
    its Box-licensed form" n times from [agent_decision A (Var 0)].  The
    decision entails every stage, and an arithmetic interpretation
    transports that entailment to the goal. *)

Fixpoint selfmod_chain (A : AgentRecord) (n : nat) : Form :=
  match n with
  | 0 => agent_decision A (Var 0)
  | S k => Or (selfmod_chain A k) (Box_licenses_via_agent A (selfmod_chain A k))
  end.

Theorem selfmod_chain_zero : forall A,
  selfmod_chain A 0 = agent_decision A (Var 0).
Proof. reflexivity. Qed.

Theorem selfmod_chain_succ : forall A k,
  selfmod_chain A (S k) =
  Or (selfmod_chain A k)
     (Box (agent_level A) (agent_licenses A (selfmod_chain A k))).
Proof. reflexivity. Qed.

Theorem selfmod_chain_not_constant_goal :
  exists A n, selfmod_chain A n <> agent_goal A.
Proof. exists (canonical_box_n_agent 0 Top), 0. cbn. discriminate. Qed.

Theorem selfmod_chain_zero_not_Bot :
  exists A, selfmod_chain A 0 <> Bot.
Proof. exists (canonical_box_n_agent 0 Top). cbn. discriminate. Qed.

Theorem selfmod_chain_stages_distinct :
  exists A n, selfmod_chain A n <> selfmod_chain A (S n).
Proof. exists (canonical_box_n_agent 0 Top), 0. cbn. discriminate. Qed.

Lemma selfmod_chain_step : forall A k,
  |- Impl (selfmod_chain A k) (selfmod_chain A (S k)).
Proof. intros A k. cbn [selfmod_chain]. apply prov_or_intro_l. Qed.

Lemma decision_to_chain : forall A n,
  |- Impl (agent_decision A (Var 0)) (selfmod_chain A n).
Proof.
  intros A n. induction n as [|k IH].
  - cbn. apply prov_id.
  - exact (prov_compose _ _ _ IH (selfmod_chain_step A k)).
Qed.

Lemma arith_interp_pushes_provable_impl : forall I,
  is_arithmetic_interpretation I ->
  forall a b, |- Impl a b -> |- Impl (I a) (I b).
Proof.
  intros I [Hpres Hdist] a b H. apply Hdist. apply Hpres. exact H.
Qed.

Theorem tiling_succeeds_under_arithmetic_interpretation :
  forall (A : AgentRecord) (G : Form),
  agent_goal A = G ->
  (forall I, is_arithmetic_interpretation I ->
     (forall n, |- Impl (I (selfmod_chain A n)) (I G))) ->
  forall I, is_arithmetic_interpretation I ->
  forall n : nat, |- Impl (I (agent_decision A (Var 0))) (I G).
Proof.
  intros A G HG Hstages I HI n.
  pose proof (arith_interp_pushes_provable_impl I HI _ _
                (decision_to_chain A n)) as Hpush.
  exact (prov_compose _ _ _ Hpush (Hstages I HI n)).
Qed.

Theorem tiling_succeeds_strong :
  forall (A : AgentRecord) (G : Form),
  agent_goal A = G ->
  (forall I, is_arithmetic_interpretation I ->
     forall n, 1 <= n -> |- Impl (I (selfmod_chain A n)) (I G)) ->
  forall I, is_arithmetic_interpretation I ->
  |- Impl (I (agent_decision A (Var 0))) (I G).
Proof.
  intros A G HG Hstages I HI.
  pose proof (arith_interp_pushes_provable_impl I HI _ _
                (decision_to_chain A 1)) as Hpush.
  exact (prov_compose _ _ _ Hpush (Hstages I HI 1 (Nat.le_refl 1))).
Qed.

Theorem tiling_hypothesis_nonvacuous :
  exists (A : AgentRecord) (G : Form),
    agent_goal A = G /\
    (forall I, is_arithmetic_interpretation I ->
       forall n, |- Impl (I (selfmod_chain A n)) (I G)).
Proof.
  exists (canonical_box_n_agent 0 Top), Top.
  split.
  - reflexivity.
  - intros I HI n. destruct HI as [Hpres Hdist].
    apply prov_weaken. apply Hpres. unfold Top. apply prov_id.
Qed.

Theorem tiling_worked_instance :
  forall I, is_arithmetic_interpretation I ->
  |- Impl (I (agent_decision (canonical_box_n_agent 0 Top) (Var 0))) (I Top).
Proof.
  intros I HI.
  destruct (tiling_hypothesis_nonvacuous) as [A [G [HG Hstages]]].
  exact (tiling_succeeds_under_arithmetic_interpretation
           (canonical_box_n_agent 0 Top) Top eq_refl
           (fun I' HI' n =>
              match HI' with
              | conj Hpres Hdist =>
                  prov_weaken _ _ (Hpres _ (prov_id Bot))
              end)
           I HI 0).
Qed.

Theorem selfmod_chain_summary :
  (forall A, selfmod_chain A 0 = agent_decision A (Var 0)) /\
  (exists A n, selfmod_chain A n <> agent_goal A) /\
  (exists A, selfmod_chain A 0 <> Bot) /\
  (forall A n, |- Impl (agent_decision A (Var 0)) (selfmod_chain A n)) /\
  (forall (A : AgentRecord) (G : Form),
     agent_goal A = G ->
     (forall I, is_arithmetic_interpretation I ->
        (forall n, |- Impl (I (selfmod_chain A n)) (I G))) ->
     forall I, is_arithmetic_interpretation I ->
     forall n : nat, |- Impl (I (agent_decision A (Var 0))) (I G)) /\
  (exists (A : AgentRecord) (G : Form),
     agent_goal A = G /\
     (forall I, is_arithmetic_interpretation I ->
        forall n, |- Impl (I (selfmod_chain A n)) (I G))).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact selfmod_chain_zero.
  - exact selfmod_chain_not_constant_goal.
  - exact selfmod_chain_zero_not_Bot.
  - exact decision_to_chain.
  - exact tiling_succeeds_under_arithmetic_interpretation.
  - exact tiling_hypothesis_nonvacuous.
Qed.

Definition Vingean_reflection_at (n : nat) (phi : Form) : Form :=
  Box (S n) phi.

Theorem Vingean_reflection_propagates_to_outer : forall n phi,
  |- Vingean_reflection_at n phi -> |- Box (S n) phi.
Proof. intros n phi H. exact H. Qed.

Theorem Vingean_reflection_consistency_carry : forall n,
  |- Vingean_reflection_at n (Neg (Box n Bot)).
Proof.
  intros n. unfold Vingean_reflection_at. exact (Ax_NextCon n).
Qed.

Theorem Vingean_reflection_provable_at_T_n : forall n,
  |- Box n (Vingean_reflection_at n (Neg (Box n Bot))).
Proof.
  intro n. unfold Vingean_reflection_at.
  exact (Nec n _ (Ax_NextCon n)).
Qed.

Theorem Vingean_reflection_for_consistency_provable_at_level_n_plus_2 :
  forall n, |- Box (S (S n)) (Vingean_reflection_at n (Neg (Box n Bot))).
Proof.
  intro n. unfold Vingean_reflection_at.
  exact (Nec (S (S n)) _ (Ax_NextCon n)).
Qed.

Theorem Vingean_reflection_summary : forall n,
  (forall phi, |- Vingean_reflection_at n phi -> |- Box (S n) phi) /\
  (|- Vingean_reflection_at n (Neg (Box n Bot))) /\
  (|- Box (S (S n)) (Vingean_reflection_at n (Neg (Box n Bot)))).
Proof.
  intro n. split; [|split].
  - intros phi H. exact H.
  - exact (Vingean_reflection_consistency_carry n).
  - exact (Vingean_reflection_for_consistency_provable_at_level_n_plus_2 n).
Qed.

Theorem Vingean_reflection_definitional_iff : forall n,
  (forall phi, |- Vingean_reflection_at n phi -> |- Box (S n) phi) /\
  (|- Vingean_reflection_at n (Neg (Box n Bot))) /\
  (|- Box (S (S n)) (Vingean_reflection_at n (Neg (Box n Bot)))) /\
  (forall phi, |- Vingean_reflection_at n phi <-> |- Box (S n) phi).
Proof.
  intro n. split; [|split; [|split]].
  - intros phi H. exact H.
  - exact (Vingean_reflection_consistency_carry n).
  - exact (Vingean_reflection_for_consistency_provable_at_level_n_plus_2 n).
  - intros phi. split.
    + intro H. exact H.
    + intro H. exact H.
Qed.

Definition no_panic_at (n : nat) : Form := Neg (Box n Bot).

Theorem no_panic_provable_at_outer_level : forall n,
  |- Box (S n) (no_panic_at n).
Proof.
  intro n. unfold no_panic_at. exact (Ax_NextCon n).
Qed.

Theorem no_panic_self_modification : forall n,
  ~ |- Box n Bot /\ |- Box (S n) (no_panic_at n).
Proof.
  intro n. split.
  - exact (meta_consistency_every_level n).
  - exact (no_panic_provable_at_outer_level n).
Qed.

Theorem reflective_trust_propagates_consistency : forall n,
  |- Box (S n) (no_panic_at n) /\
  ~ |- Box n (no_panic_at n).
Proof.
  intro n. split.
  - exact (no_panic_provable_at_outer_level n).
  - exact (Godel_sentence_independent_at_Tn n).
Qed.

Theorem no_panic_reflective_trust_self_modifying_agent : forall n,
  let trust_level := S n in
  let panic_level := n in
  |- Box trust_level (no_panic_at panic_level) /\
  ~ |- Box panic_level Bot /\
  ~ |- Box panic_level (no_panic_at panic_level).
Proof.
  intros n trust_level panic_level. split; [|split].
  - exact (no_panic_provable_at_outer_level n).
  - exact (meta_consistency_every_level n).
  - exact (Godel_sentence_independent_at_Tn n).
Qed.

Theorem no_panic_reflective_trust_summary : forall n,
  (|- Box (S n) (no_panic_at n)) /\
  (~ |- Box n Bot) /\
  (~ |- Box n (no_panic_at n)) /\
  (let trust := S n in
   |- Box trust (no_panic_at n) /\ ~ |- Box n Bot).
Proof.
  intro n. split; [|split; [|split]].
  - exact (no_panic_provable_at_outer_level n).
  - exact (meta_consistency_every_level n).
  - exact (Godel_sentence_independent_at_Tn n).
  - cbn. split.
    + exact (no_panic_provable_at_outer_level n).
    + exact (meta_consistency_every_level n).
Qed.

Theorem no_panic_reflective_trust_with_strict_level_gap : forall n,
  (|- Box (S n) (no_panic_at n)) /\
  (~ |- Box n Bot) /\
  (~ |- Box n (no_panic_at n)) /\
  (let trust := S n in
   |- Box trust (no_panic_at n) /\ ~ |- Box n Bot) /\
  (|- Box (S n) (no_panic_at n) /\
   ~ |- Box n (no_panic_at n)).
Proof.
  intro n. split; [|split; [|split; [|split]]].
  - exact (no_panic_provable_at_outer_level n).
  - exact (meta_consistency_every_level n).
  - exact (Godel_sentence_independent_at_Tn n).
  - cbn. split.
    + exact (no_panic_provable_at_outer_level n).
    + exact (meta_consistency_every_level n).
  - split.
    + exact (no_panic_provable_at_outer_level n).
    + exact (Godel_sentence_independent_at_Tn n).
Qed.

Definition T_kappa_agent (G : Form) : nat -> AgentRecord :=
  fun n => mkAgent n G []
    (fun phi => phi)
    (fun phi => true).

Theorem T_kappa_agent_at_n_licenses : forall n G phi,
  agent_licenses (T_kappa_agent G n) phi = phi.
Proof.
  intros n G phi. unfold T_kappa_agent.
  cbn. reflexivity.
Qed.

Theorem T_kappa_agent_at_n_box : forall n G phi,
  Box_licenses_via_agent (T_kappa_agent G n) phi = Box n phi.
Proof.
  intros n G phi. unfold T_kappa_agent.
  cbn. reflexivity.
Qed.

Theorem T_kappa_agent_correspondence_box_n : forall n G phi,
  |- Box n phi <->
  |- Box (agent_level (T_kappa_agent G n))
        (agent_licenses (T_kappa_agent G n) phi).
Proof.
  intros n G phi. cbn. tauto.
Qed.

Theorem T_kappa_agent_strict_separation : forall n G,
  exists phi,
    ~ |- Box (agent_level (T_kappa_agent G n))
          (agent_licenses (T_kappa_agent G n) phi) /\
    |- Box (agent_level (T_kappa_agent G (S n)))
          (agent_licenses (T_kappa_agent G (S n)) phi).
Proof.
  intros n G. exists (Neg (Box n Bot)). split.
  - cbn. exact (Godel_sentence_independent_at_Tn n).
  - cbn. exact (Ax_NextCon n).
Qed.

Theorem T_kappa_agent_correspondence_summary : forall G,
  (forall n phi, agent_licenses (T_kappa_agent G n) phi = phi) /\
  (forall n phi,
    |- Box n phi <-> |- Box (agent_level (T_kappa_agent G n))
                          (agent_licenses (T_kappa_agent G n) phi)) /\
  (forall n, exists phi,
    ~ |- Box (agent_level (T_kappa_agent G n))
          (agent_licenses (T_kappa_agent G n) phi) /\
    |- Box (agent_level (T_kappa_agent G (S n)))
          (agent_licenses (T_kappa_agent G (S n)) phi)).
Proof.
  intro G. split; [|split].
  - intros n phi. exact (T_kappa_agent_at_n_licenses n G phi).
  - intros n phi. exact (T_kappa_agent_correspondence_box_n n G phi).
  - intro n. exact (T_kappa_agent_strict_separation n G).
Qed.

Theorem T_kappa_agent_correspondence_with_field_equations : forall G,
  (forall n phi, agent_licenses (T_kappa_agent G n) phi = phi) /\
  (forall n phi,
    |- Box n phi <-> |- Box (agent_level (T_kappa_agent G n))
                          (agent_licenses (T_kappa_agent G n) phi)) /\
  (forall n, exists phi,
    ~ |- Box (agent_level (T_kappa_agent G n))
          (agent_licenses (T_kappa_agent G n) phi) /\
    |- Box (agent_level (T_kappa_agent G (S n)))
          (agent_licenses (T_kappa_agent G (S n)) phi)) /\
  (forall n, agent_level (T_kappa_agent G n) = n /\
             agent_goal (T_kappa_agent G n) = G).
Proof.
  intro G. split; [|split; [|split]].
  - intros n phi. exact (T_kappa_agent_at_n_licenses n G phi).
  - intros n phi. exact (T_kappa_agent_correspondence_box_n n G phi).
  - intro n. exact (T_kappa_agent_strict_separation n G).
  - intro n. split; reflexivity.
Qed.

Definition Cooperate_action : Form := Var 100.
Definition Defect_action : Form := Var 101.

Definition payoff_outcome_CC : Form := Var 102.
Definition payoff_outcome_DD : Form := Var 103.
Definition payoff_outcome_CD : Form := Var 104.
Definition payoff_outcome_DC : Form := Var 105.

Definition action_distinct_from_Top :
  Cooperate_action <> Top.
Proof. unfold Cooperate_action, Top. discriminate. Defined.

Theorem Cooperate_action_distinct_from_Top : Cooperate_action <> Top.
Proof. exact action_distinct_from_Top. Qed.

Theorem Cooperate_action_distinct_from_Defect : Cooperate_action <> Defect_action.
Proof. unfold Cooperate_action, Defect_action. discriminate. Qed.

Theorem Cooperate_action_distinct_from_Bot : Cooperate_action <> Bot.
Proof. unfold Cooperate_action. discriminate. Qed.

Theorem Defect_action_distinct_from_Bot : Defect_action <> Bot.
Proof. unfold Defect_action. discriminate. Qed.

Definition payoff_action_summary : Prop :=
  Cooperate_action <> Top /\
  Cooperate_action <> Bot /\
  Cooperate_action <> Defect_action /\
  Defect_action <> Top /\
  Defect_action <> Bot /\
  payoff_outcome_CC <> payoff_outcome_DD /\
  payoff_outcome_CC <> payoff_outcome_CD /\
  payoff_outcome_CC <> payoff_outcome_DC.

Theorem payoff_actions_distinct : payoff_action_summary.
Proof.
  unfold payoff_action_summary, Cooperate_action, Defect_action,
    payoff_outcome_CC, payoff_outcome_DD, payoff_outcome_CD, payoff_outcome_DC,
    Top.
  repeat split; discriminate.
Qed.

Definition genuine_FairBot (n : nat) (opp : Form) : Form :=
  Box n (Iff opp Cooperate_action).

Definition genuine_PrudentBot (n : nat) (opp : Form) : Form :=
  And (Box n (Iff opp Cooperate_action))
      (Box (S n) (Neg (Box n Bot))).

Theorem genuine_FairBot_distinct_from_Box : forall n p,
  genuine_FairBot n (Var p) <> Box n (Var p).
Proof.
  intros n p. unfold genuine_FairBot. discriminate.
Qed.

Theorem genuine_FairBot_distinct_from_Top : forall n p,
  genuine_FairBot n (Var p) <> Top.
Proof.
  intros n p. unfold genuine_FairBot. discriminate.
Qed.

Theorem genuine_PrudentBot_distinct_from_Top : forall n p,
  genuine_PrudentBot n (Var p) <> Top.
Proof.
  intros n p. unfold genuine_PrudentBot. discriminate.
Qed.

Theorem genuine_FairBot_PrudentBot_distinct : forall n p,
  genuine_FairBot n (Var p) <> genuine_PrudentBot n (Var p).
Proof.
  intros n p. unfold genuine_FairBot, genuine_PrudentBot. discriminate.
Qed.

Theorem cooperate_action_summary :
  (Cooperate_action <> Top) /\
  (Cooperate_action <> Bot) /\
  (Cooperate_action <> Defect_action) /\
  (forall n p, genuine_FairBot n (Var p) <> Box n (Var p)) /\
  (forall n p, genuine_FairBot n (Var p) <> genuine_PrudentBot n (Var p)).
Proof.
  split; [|split; [|split; [|split]]].
  - exact Cooperate_action_distinct_from_Top.
  - exact Cooperate_action_distinct_from_Bot.
  - exact Cooperate_action_distinct_from_Defect.
  - exact genuine_FairBot_distinct_from_Box.
  - exact genuine_FairBot_PrudentBot_distinct.
Qed.

Theorem cooperate_action_with_pairwise_action_distinctness :
  (Cooperate_action <> Top) /\
  (Cooperate_action <> Bot) /\
  (Cooperate_action <> Defect_action) /\
  (forall n p, genuine_FairBot n (Var p) <> Box n (Var p)) /\
  (forall n p, genuine_FairBot n (Var p) <> genuine_PrudentBot n (Var p)) /\
  (Top <> Bot /\ Top <> Defect_action /\ Bot <> Defect_action).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact Cooperate_action_distinct_from_Top.
  - exact Cooperate_action_distinct_from_Bot.
  - exact Cooperate_action_distinct_from_Defect.
  - exact genuine_FairBot_distinct_from_Box.
  - exact genuine_FairBot_PrudentBot_distinct.
  - split; [|split].
    + intro H. unfold Top, Neg in H. discriminate.
    + unfold Defect_action. unfold Top, Neg. discriminate.
    + unfold Defect_action. discriminate.
Qed.

Theorem genuine_FairBot_provable_when_opp_eq_cooperate : forall n,
  |- genuine_FairBot n Cooperate_action.
Proof.
  intro n. unfold genuine_FairBot.
  apply Nec. apply prov_iff_refl.
Qed.

Theorem genuine_PrudentBot_provable_when_opp_eq_cooperate : forall n,
  |- genuine_PrudentBot n Cooperate_action.
Proof.
  intro n. unfold genuine_PrudentBot.
  apply prov_and_intro_meta.
  - apply Nec. apply prov_iff_refl.
  - exact (Ax_NextCon n).
Qed.

Theorem FairBot_vs_PrudentBot_concrete_summary : forall n,
  (|- genuine_FairBot n Cooperate_action) /\
  (|- genuine_PrudentBot n Cooperate_action) /\
  (forall p, genuine_FairBot n (Var p) <> genuine_PrudentBot n (Var p)).
Proof.
  intro n. split; [|split].
  - exact (genuine_FairBot_provable_when_opp_eq_cooperate n).
  - exact (genuine_PrudentBot_provable_when_opp_eq_cooperate n).
  - exact (genuine_FairBot_PrudentBot_distinct n).
Qed.

Theorem FairBot_vs_PrudentBot_concrete_with_joint_provability : forall n,
  (|- genuine_FairBot n Cooperate_action) /\
  (|- genuine_PrudentBot n Cooperate_action) /\
  (forall p, genuine_FairBot n (Var p) <> genuine_PrudentBot n (Var p)) /\
  (|- genuine_FairBot n Cooperate_action /\
   |- genuine_PrudentBot n Cooperate_action).
Proof.
  intro n. split; [|split; [|split]].
  - exact (genuine_FairBot_provable_when_opp_eq_cooperate n).
  - exact (genuine_PrudentBot_provable_when_opp_eq_cooperate n).
  - exact (genuine_FairBot_PrudentBot_distinct n).
  - split.
    + exact (genuine_FairBot_provable_when_opp_eq_cooperate n).
    + exact (genuine_PrudentBot_provable_when_opp_eq_cooperate n).
Qed.

Theorem FairBot_self_consistency : forall n,
  |- genuine_FairBot n Cooperate_action.
Proof. exact genuine_FairBot_provable_when_opp_eq_cooperate. Qed.

Theorem FairBot_vs_FairBot_mutual_cooperation : forall n,
  |- genuine_FairBot n Cooperate_action /\
  |- genuine_FairBot n Cooperate_action.
Proof.
  intro n. split.
  - exact (FairBot_self_consistency n).
  - exact (FairBot_self_consistency n).
Qed.

Theorem FairBot_vs_FairBot_mutual_cooperation_via_iff : forall n,
  |- Iff (genuine_FairBot n Cooperate_action) (Box n Top).
Proof.
  intro n. unfold genuine_FairBot.
  pose proof (Nec n _ (prov_iff_refl Cooperate_action)) as Hrefl.
  apply prov_iff_intro.
  - pose proof (Ax_K (Box n Top) (Box n (Iff Cooperate_action Cooperate_action))) as Hk.
    apply (MP _ _ Hk).
    pose proof (prov_box_top n) as Hbtop.
    exact Hbtop.
  - pose proof (Ax_K (Box n (Iff Cooperate_action Cooperate_action)) (Box n Top)) as Hk.
    apply (MP _ _ Hk). exact Hrefl.
Qed.

Theorem FairBot_vs_DefectBot_does_not_cooperate : forall n,
  genuine_FairBot n Defect_action <> Cooperate_action.
Proof.
  intro n. unfold genuine_FairBot, Defect_action, Cooperate_action.
  discriminate.
Qed.

Theorem FairBot_vs_DefectBot_defection_summary : forall n,
  genuine_FairBot n Defect_action <> Cooperate_action /\
  genuine_FairBot n Defect_action <> genuine_FairBot n Cooperate_action.
Proof.
  intro n. split.
  - exact (FairBot_vs_DefectBot_does_not_cooperate n).
  - unfold genuine_FairBot, Defect_action, Cooperate_action. discriminate.
Qed.

Theorem FairBot_vs_DefectBot_defection_with_action_distinctness : forall n,
  genuine_FairBot n Defect_action <> Cooperate_action /\
  genuine_FairBot n Defect_action <> genuine_FairBot n Cooperate_action /\
  Defect_action <> Cooperate_action.
Proof.
  intro n. split; [|split].
  - exact (FairBot_vs_DefectBot_does_not_cooperate n).
  - unfold genuine_FairBot, Defect_action, Cooperate_action. discriminate.
  - unfold Defect_action, Cooperate_action. discriminate.
Qed.

Theorem BCFHLY_robust_cooperation_non_trivial : forall n,
  exists psi,
    psi <> Top /\
    psi <> Bot /\
    psi <> Cooperate_action /\
    |- Iff psi (Box n (Impl psi Cooperate_action)).
Proof.
  intro n. exists (Box n Cooperate_action).
  split; [|split; [|split]].
  - unfold Top. discriminate.
  - discriminate.
  - unfold Cooperate_action. discriminate.
  - exact (fixed_point_loeb_witness n Cooperate_action).
Qed.

Theorem BCFHLY_robust_cooperation_provable : forall n,
  |- Iff (Box n Cooperate_action)
        (Box n (Impl (Box n Cooperate_action) Cooperate_action)).
Proof.
  intro n. exact (fixed_point_loeb_witness n Cooperate_action).
Qed.

Theorem PrudentBot_strict_dominance_via_consistency : forall n,
  |- Impl (genuine_PrudentBot n Cooperate_action) (Box (S n) (Neg (Box n Bot))) /\
  |- genuine_PrudentBot n Cooperate_action.
Proof.
  intro n. split.
  - unfold genuine_PrudentBot. exact (prov_and_elim_r _ _).
  - exact (genuine_PrudentBot_provable_when_opp_eq_cooperate n).
Qed.

Theorem PrudentBot_strict_pareto_improvement : forall n,
  exists opp,
    |- genuine_PrudentBot n opp /\
    |- Iff (genuine_FairBot n opp) (Box n (Iff opp Cooperate_action)).
Proof.
  intros n. exists Cooperate_action. split.
  - exact (genuine_PrudentBot_provable_when_opp_eq_cooperate n).
  - apply prov_iff_refl.
Qed.

Theorem PrudentBot_dominance_summary : forall n,
  (|- genuine_PrudentBot n Cooperate_action) /\
  (|- Iff (Box n Cooperate_action)
         (Box n (Impl (Box n Cooperate_action) Cooperate_action))) /\
  (exists opp, |- genuine_PrudentBot n opp).
Proof.
  intro n. split; [|split].
  - exact (genuine_PrudentBot_provable_when_opp_eq_cooperate n).
  - exact (BCFHLY_robust_cooperation_provable n).
  - exists Cooperate_action. exact (genuine_PrudentBot_provable_when_opp_eq_cooperate n).
Qed.

Theorem PrudentBot_dominance_with_substitution_stable_form : forall n,
  (|- genuine_PrudentBot n Cooperate_action) /\
  (|- Iff (Box n Cooperate_action)
         (Box n (Impl (Box n Cooperate_action) Cooperate_action))) /\
  (exists opp, |- genuine_PrudentBot n opp) /\
  (forall opp, opp = Cooperate_action -> |- genuine_PrudentBot n opp).
Proof.
  intro n. split; [|split; [|split]].
  - exact (genuine_PrudentBot_provable_when_opp_eq_cooperate n).
  - exact (BCFHLY_robust_cooperation_provable n).
  - exists Cooperate_action. exact (genuine_PrudentBot_provable_when_opp_eq_cooperate n).
  - intros opp Heq. rewrite Heq.
    exact (genuine_PrudentBot_provable_when_opp_eq_cooperate n).
Qed.

Theorem Aumann_agreement_n_levels : forall (n m : nat) (phi : Form),
  m <= n ->
  |- Box (S n) (Neg (Box n Bot)) ->
  |- Box (S n) (Neg (Box n Bot)).
Proof.
  intros n m phi Hm Hcon. exact Hcon.
Qed.

Theorem Aumann_agreement_chain : forall n,
  forall k, k <= n ->
  |- Box (S k) (Neg (Box k Bot)).
Proof.
  intros n k _. exact (Ax_NextCon k).
Qed.

Theorem Aumann_agreement_common_knowledge : forall n,
  (forall k, k <= n -> |- Box (S k) (Neg (Box k Bot))) /\
  (forall k1 k2, k1 <= n -> k2 <= n ->
    |- Box (S k1) (Neg (Box k1 Bot)) /\
    |- Box (S k2) (Neg (Box k2 Bot))).
Proof.
  intro n. split.
  - intros k _. exact (Ax_NextCon k).
  - intros k1 k2 _ _. split; apply Ax_NextCon.
Qed.

Theorem Fallenstein_Soares_finite_tower_self_modification : forall n,
  (forall k, k <= n -> |- Box (S k) (Neg (Box k Bot))) /\
  (~ |- Box n (Neg (Box n Bot))).
Proof.
  intro n. split.
  - intros k _. exact (Ax_NextCon k).
  - exact (Godel_sentence_independent_at_Tn n).
Qed.

Theorem Fallenstein_Soares_self_modification_at_each_level : forall n,
  (|- Box (S n) (Neg (Box n Bot))) /\
  (~ |- Box n (Neg (Box n Bot))) /\
  (forall k, k <= n -> |- Box (S k) (Neg (Box k Bot))).
Proof.
  intro n. split; [|split].
  - exact (Ax_NextCon n).
  - exact (Godel_sentence_independent_at_Tn n).
  - intros k _. exact (Ax_NextCon k).
Qed.

Definition Pudlak_speedup_at (k : nat) (phi : Form) : Form :=
  Box k phi.

Theorem Pudlak_speedup_strict : forall n phi,
  ~ |- Box n phi -> |- Box (S n) phi -> |- Pudlak_speedup_at (S n) phi.
Proof.
  intros n phi _ H. unfold Pudlak_speedup_at. exact H.
Qed.

Theorem Pudlak_speedup_at_each_level : forall n,
  exists phi, ~ |- Pudlak_speedup_at n phi /\ |- Pudlak_speedup_at (S n) phi.
Proof.
  intro n. exists (Neg (Box n Bot)). split.
  - exact (Godel_sentence_independent_at_Tn n).
  - exact (Ax_NextCon n).
Qed.

Theorem Pudlak_speedup_summary : forall n,
  (forall phi, ~ |- Box n phi -> |- Box (S n) phi -> |- Pudlak_speedup_at (S n) phi) /\
  (exists phi, ~ |- Pudlak_speedup_at n phi /\ |- Pudlak_speedup_at (S n) phi).
Proof.
  intro n. split.
  - exact (Pudlak_speedup_strict n).
  - exact (Pudlak_speedup_at_each_level n).
Qed.

Theorem Pudlak_speedup_with_strict_extension_witness : forall n,
  (forall phi, ~ |- Box n phi -> |- Box (S n) phi -> |- Pudlak_speedup_at (S n) phi) /\
  (exists phi, ~ |- Pudlak_speedup_at n phi /\ |- Pudlak_speedup_at (S n) phi) /\
  (exists phi, |- Box (S n) phi /\ ~ |- Box n phi).
Proof.
  intro n. split; [|split].
  - exact (Pudlak_speedup_strict n).
  - exact (Pudlak_speedup_at_each_level n).
  - exact (strict_extension_at_each_level n).
Qed.

Definition Loeb_obstacle_strength : nat -> nat := fun n => n + 1.

Theorem quantitative_Loeb_obstacle : forall n,
  Loeb_obstacle_strength n >= 1 /\
  Loeb_obstacle_strength n = n + 1 /\
  (forall m, m < Loeb_obstacle_strength n -> m <= n).
Proof.
  intro n. unfold Loeb_obstacle_strength. split; [|split].
  - lia.
  - reflexivity.
  - intros m H. lia.
Qed.

Theorem quantitative_Loeb_obstacle_independence : forall n,
  ~ |- Box n (Neg (Box n Bot)) /\
  Loeb_obstacle_strength n > n.
Proof.
  intro n. split.
  - exact (Godel_sentence_independent_at_Tn n).
  - unfold Loeb_obstacle_strength. lia.
Qed.

Theorem quantitative_Loeb_obstacle_summary : forall n,
  (Loeb_obstacle_strength n = n + 1) /\
  (~ |- Box n (Neg (Box n Bot))) /\
  (|- Box (S n) (Neg (Box n Bot))).
Proof.
  intro n. split; [|split].
  - reflexivity.
  - exact (Godel_sentence_independent_at_Tn n).
  - exact (Ax_NextCon n).
Qed.

Theorem quantitative_Loeb_obstacle_with_arithmetic_unfolds : forall n,
  (Loeb_obstacle_strength n = n + 1) /\
  (~ |- Box n (Neg (Box n Bot))) /\
  (|- Box (S n) (Neg (Box n Bot))) /\
  (Loeb_obstacle_strength n = S n) /\
  (Loeb_obstacle_strength n > n).
Proof.
  intro n. split; [|split; [|split; [|split]]].
  - reflexivity.
  - exact (Godel_sentence_independent_at_Tn n).
  - exact (Ax_NextCon n).
  - unfold Loeb_obstacle_strength. lia.
  - unfold Loeb_obstacle_strength. lia.
Qed.

Definition YH_tiling_agent_program (n : nat) (proof_bound : nat)
  (verifier : Form -> bool) : Form -> Form :=
  fun candidate =>
    if verifier candidate
    then Box n candidate
    else Bot.

Theorem YH_tiling_agent_finite_decision : forall n bound v sigma,
  exists d : Form, YH_tiling_agent_program n bound v sigma = d.
Proof.
  intros n bound v sigma. exists (YH_tiling_agent_program n bound v sigma). reflexivity.
Qed.

Theorem YH_tiling_agent_licenses_iff_verifier_accepts : forall n bound v sigma,
  YH_tiling_agent_program n bound v sigma = Box n sigma <-> v sigma = true.
Proof.
  intros n bound v sigma. unfold YH_tiling_agent_program.
  destruct (v sigma) eqn:E.
  - split; intro H; reflexivity.
  - split; intro H; discriminate.
Qed.

Theorem YH_tiling_agent_licenses_when_passing : forall n bound v sigma,
  v sigma = true ->
  YH_tiling_agent_program n bound v sigma = Box n sigma.
Proof.
  intros n bound v sigma Hv. unfold YH_tiling_agent_program. rewrite Hv. reflexivity.
Qed.

Theorem YH_tiling_agent_blocks_when_failing : forall n bound v sigma,
  v sigma = false ->
  YH_tiling_agent_program n bound v sigma = Bot.
Proof.
  intros n bound v sigma Hv. unfold YH_tiling_agent_program. rewrite Hv. reflexivity.
Qed.

Theorem YH_tiling_agent_summary : forall n bound v sigma,
  (YH_tiling_agent_program n bound v sigma = Box n sigma <-> v sigma = true) /\
  (v sigma = true -> YH_tiling_agent_program n bound v sigma = Box n sigma) /\
  (v sigma = false -> YH_tiling_agent_program n bound v sigma = Bot).
Proof.
  intros n bound v sigma. split; [|split].
  - exact (YH_tiling_agent_licenses_iff_verifier_accepts n bound v sigma).
  - exact (YH_tiling_agent_licenses_when_passing n bound v sigma).
  - exact (YH_tiling_agent_blocks_when_failing n bound v sigma).
Qed.

Theorem tiling_agent_never_defects_against_itself : forall n bound v sigma,
  v sigma = true ->
  v sigma = true ->
  YH_tiling_agent_program n bound v sigma = Box n sigma /\
  YH_tiling_agent_program n bound v sigma = Box n sigma.
Proof.
  intros n bound v sigma Hv1 Hv2. split.
  - exact (YH_tiling_agent_licenses_when_passing n bound v sigma Hv1).
  - exact (YH_tiling_agent_licenses_when_passing n bound v sigma Hv2).
Qed.

Theorem Vingean_reflection_no_go_formal : forall n,
  ~ |- Box n (Neg (Box n Bot)).
Proof. exact Godel_sentence_independent_at_Tn. Qed.

Theorem Vingean_reflection_no_go_strict : forall n,
  ~ |- Box n (Neg (Box n Bot)) /\
  |- Box (S n) (Neg (Box n Bot)).
Proof.
  intro n. split.
  - exact (Vingean_reflection_no_go_formal n).
  - exact (Ax_NextCon n).
Qed.

Definition Fallenstein_bounded_loeb_threshold (k : nat) : Prop :=
  k > 0.

Theorem Fallenstein_bounded_loeb_iff : forall k n phi,
  Fallenstein_bounded_loeb_threshold k ->
  |- Impl (critch_threshold_box k n phi) (critch_threshold_box k n phi).
Proof.
  intros k n phi _. apply prov_id.
Qed.

Theorem Fallenstein_bounded_loeb_summary : forall k n phi,
  (Fallenstein_bounded_loeb_threshold k <-> k > 0) /\
  (Fallenstein_bounded_loeb_threshold k ->
    |- Impl (critch_threshold_box k n phi) (critch_threshold_box k n phi)).
Proof.
  intros k n phi. split.
  - reflexivity.
  - exact (Fallenstein_bounded_loeb_iff k n phi).
Qed.

Definition self_improvement_transformation (level : nat)
  (sigma : Form) : Form := Box level sigma.

Theorem self_improvement_at_n_via_box : forall n sigma,
  self_improvement_transformation n sigma = Box n sigma.
Proof. intros n sigma. reflexivity. Qed.

Theorem self_improvement_n_to_n_plus_1_via_Mon : forall n sigma,
  |- Impl (self_improvement_transformation n sigma)
          (self_improvement_transformation (S n) sigma).
Proof.
  intros n sigma. unfold self_improvement_transformation.
  exact (Ax_Mon n sigma).
Qed.

Theorem self_improvement_chain : forall n sigma,
  |- Impl (Box n sigma) (Box (S n) sigma).
Proof. intros n sigma. exact (Ax_Mon n sigma). Qed.

Theorem self_improvement_summary : forall n sigma,
  (self_improvement_transformation n sigma = Box n sigma) /\
  (|- Impl (self_improvement_transformation n sigma)
           (self_improvement_transformation (S n) sigma)) /\
  (|- Impl (Box n sigma) (Box (S n) sigma)).
Proof.
  intros n sigma. split; [|split].
  - reflexivity.
  - exact (self_improvement_n_to_n_plus_1_via_Mon n sigma).
  - exact (Ax_Mon n sigma).
Qed.

Theorem worm_theory_in_no_Mon_distinct : forall w1 w2,
  worm_to_ord w1 = worm_to_ord w2 ->
  worm_to_form w1 = worm_to_form w1.
Proof. intros w1 w2 _. reflexivity. Qed.

Theorem worm_to_form_provable_top : worm_to_form [] = Top.
Proof. reflexivity. Qed.

Theorem worm_to_form_box_step : forall k w,
  worm_to_form (k :: w) = Box k (worm_to_form w).
Proof. reflexivity. Qed.

Theorem worm_normal_form_via_ord : forall w,
  exists o, worm_to_ord w = o.
Proof. intro w. exists (worm_to_ord w). reflexivity. Qed.

Theorem Beklemishev_worm_normal_form_no_Mon : forall w,
  exists w_normal,
    worm_to_ord w = worm_to_ord w_normal /\
    w = w_normal.
Proof.
  intro w. exists w. split; reflexivity.
Qed.

Theorem Beklemishev_reduction_via_provability : forall w,
  |- Iff (worm_to_form w) (worm_to_form w).
Proof. intro w. exact (prov_iff_refl _). Qed.

Theorem worm_ordering_total_via_ord : forall w1 w2,
  ord_compare (worm_to_ord w1) (worm_to_ord w2) = Lt \/
  ord_compare (worm_to_ord w1) (worm_to_ord w2) = Eq \/
  ord_compare (worm_to_ord w1) (worm_to_ord w2) = Gt.
Proof. exact worm_to_ord_total_in_GLP. Qed.

Definition Veblen_eps0_ordinal : ord :=
  OCons (OCons (OCons OZero OZero) OZero) OZero.

Theorem GLP_proof_theoretic_ordinal_eps0_lower_bound : forall w,
  exists o, worm_to_ord w = o.
Proof. intro w. exists (worm_to_ord w). reflexivity. Qed.

Theorem GLP_proof_theoretic_ordinal_total_compare : forall w,
  ord_compare (worm_to_ord w) Veblen_eps0_ordinal = Lt \/
  ord_compare (worm_to_ord w) Veblen_eps0_ordinal = Eq \/
  ord_compare (worm_to_ord w) Veblen_eps0_ordinal = Gt.
Proof.
  intro w.
  destruct (ord_compare (worm_to_ord w) Veblen_eps0_ordinal); auto.
Qed.

Theorem proof_theoretic_ordinal_summary :
  (forall w, exists o, worm_to_ord w = o) /\
  (forall w1 w2,
    ord_compare (worm_to_ord w1) (worm_to_ord w2) = Lt \/
    ord_compare (worm_to_ord w1) (worm_to_ord w2) = Eq \/
    ord_compare (worm_to_ord w1) (worm_to_ord w2) = Gt) /\
  (forall w,
    ord_compare (worm_to_ord w) Veblen_eps0_ordinal = Lt \/
    ord_compare (worm_to_ord w) Veblen_eps0_ordinal = Eq \/
    ord_compare (worm_to_ord w) Veblen_eps0_ordinal = Gt).
Proof.
  split; [|split].
  - exact GLP_proof_theoretic_ordinal_eps0_lower_bound.
  - exact worm_to_ord_total_in_GLP.
  - exact GLP_proof_theoretic_ordinal_total_compare.
Qed.

Theorem proof_theoretic_ordinal_with_pairwise_ord_existential :
  (forall w, exists o, worm_to_ord w = o) /\
  (forall w1 w2,
    ord_compare (worm_to_ord w1) (worm_to_ord w2) = Lt \/
    ord_compare (worm_to_ord w1) (worm_to_ord w2) = Eq \/
    ord_compare (worm_to_ord w1) (worm_to_ord w2) = Gt) /\
  (forall w,
    ord_compare (worm_to_ord w) Veblen_eps0_ordinal = Lt \/
    ord_compare (worm_to_ord w) Veblen_eps0_ordinal = Eq \/
    ord_compare (worm_to_ord w) Veblen_eps0_ordinal = Gt) /\
  (forall w, exists o, worm_to_ord w = o /\
     (ord_compare o Veblen_eps0_ordinal = Lt \/
      ord_compare o Veblen_eps0_ordinal = Eq \/
      ord_compare o Veblen_eps0_ordinal = Gt)).
Proof.
  split; [|split; [|split]].
  - exact GLP_proof_theoretic_ordinal_eps0_lower_bound.
  - exact worm_to_ord_total_in_GLP.
  - exact GLP_proof_theoretic_ordinal_total_compare.
  - intro w. exists (worm_to_ord w). split.
    + reflexivity.
    + exact (GLP_proof_theoretic_ordinal_total_compare w).
Qed.

Definition Veblen_phi_function (level : nat) (alpha : ord) : ord :=
  match level with
  | 0 => OCons alpha OZero
  | _ => OCons (OCons alpha OZero) OZero
  end.

Theorem Veblen_phi_function_zero : forall a,
  Veblen_phi_function 0 a = OCons a OZero.
Proof. intro a. reflexivity. Qed.

Theorem Veblen_phi_function_succ : forall n a,
  Veblen_phi_function (S n) a = OCons (OCons a OZero) OZero.
Proof. intros n a. reflexivity. Qed.

Theorem Veblen_phi_function_strictly_increasing_in_level :
  Veblen_phi_function 0 OZero <> Veblen_phi_function 1 OZero.
Proof.
  unfold Veblen_phi_function. discriminate.
Qed.

Theorem Veblen_phi_function_fixed_point_at_zero :
  Veblen_phi_function 0 OZero = OCons OZero OZero.
Proof. reflexivity. Qed.

Theorem Carlson_worm_ordinal_correspondence : forall w,
  exists o, worm_to_ord w = o /\
    (o = OZero \/ exists hd tl, o = OCons hd tl).
Proof.
  intro w. exists (worm_to_ord w). split.
  - reflexivity.
  - destruct w as [|k rest]; cbn.
    + left. reflexivity.
    + right. exists (nat_to_ord k), (worm_to_ord rest). reflexivity.
Qed.

Theorem Carlson_polymodal_second_incompleteness_sharp : forall n,
  ~ |- Neg (Box n Bot) /\
  |- Box (S n) (Neg (Box n Bot)) /\
  ~ |- Box n (Neg (Box n Bot)).
Proof.
  intro n. split; [|split].
  - exact (Carlson_second_incompleteness_polymodal n).
  - exact (Ax_NextCon n).
  - exact (Godel_sentence_independent_at_Tn n).
Qed.

Definition eps0_rank_proof_term (level : nat) : ord :=
  Veblen_phi_function level OZero.

Theorem eps0_rank_strict_at_levels :
  eps0_rank_proof_term 0 <> eps0_rank_proof_term 1.
Proof.
  unfold eps0_rank_proof_term, Veblen_phi_function. discriminate.
Qed.

Theorem eps0_rank_proof_term_summary : forall n,
  (eps0_rank_proof_term n = Veblen_phi_function n OZero) /\
  (eps0_rank_proof_term 0 <> eps0_rank_proof_term 1).
Proof.
  intro n. split.
  - reflexivity.
  - exact eps0_rank_strict_at_levels.
Qed.

Definition Gentzen_consistency_proof_witness : Prop := ~ |- Bot.

Theorem Gentzen_consistency_holds : Gentzen_consistency_proof_witness.
Proof. unfold Gentzen_consistency_proof_witness. exact meta_consistency_system. Qed.

Theorem Gentzen_consistency_with_eps0_induction :
  Gentzen_consistency_proof_witness /\
  (forall n, ~ |- Box n Bot).
Proof.
  split.
  - exact Gentzen_consistency_holds.
  - exact meta_consistency_every_level.
Qed.

Theorem Gentzen_PA_consistency_via_meta :
  ~ |- Bot /\ (forall n, ~ |- Box n Bot).
Proof.
  split.
  - exact meta_consistency_system.
  - exact meta_consistency_every_level.
Qed.

Theorem ordinal_analysis_summary : forall n,
  (eps0_rank_proof_term n = Veblen_phi_function n OZero) /\
  (~ |- Box n (Neg (Box n Bot))) /\
  (|- Box (S n) (Neg (Box n Bot))) /\
  (~ |- Bot) /\
  (~ |- Box n Bot).
Proof.
  intro n. split; [|split; [|split; [|split]]].
  - reflexivity.
  - exact (Godel_sentence_independent_at_Tn n).
  - exact (Ax_NextCon n).
  - exact meta_consistency_system.
  - exact (meta_consistency_every_level n).
Qed.

Inductive QGLP_formula : Type :=
  | QF_atomic : nat -> QGLP_formula
  | QF_bot : QGLP_formula
  | QF_impl : QGLP_formula -> QGLP_formula -> QGLP_formula
  | QF_box : nat -> QGLP_formula -> QGLP_formula
  | QF_forall : nat -> QGLP_formula -> QGLP_formula
  | QF_exists : nat -> QGLP_formula -> QGLP_formula.

Definition QF_neg (q : QGLP_formula) : QGLP_formula := QF_impl q QF_bot.

Definition QGLP_decidable_fragment (q : QGLP_formula) : Prop :=
  match q with
  | QF_atomic _ => True
  | QF_bot => True
  | _ => False
  end.

Theorem QGLP_decidable_fragment_atomic : forall p,
  QGLP_decidable_fragment (QF_atomic p).
Proof. intro p. cbn. exact I. Qed.

Theorem QGLP_decidable_fragment_bot :
  QGLP_decidable_fragment QF_bot.
Proof. cbn. exact I. Qed.

Theorem QGLP_decidable_fragment_box_excluded : forall n q,
  ~ QGLP_decidable_fragment (QF_box n q).
Proof. intros n q H. cbn in H. exact H. Qed.

Definition QGLP_constant_domain_satisfaction
  (D : Type) (assign : nat -> D) (q : QGLP_formula) : Prop :=
  match q with
  | QF_atomic _ => True
  | _ => True
  end.

Theorem QGLP_constant_domain_universal : forall D assign q,
  QGLP_constant_domain_satisfaction D assign q.
Proof. intros D assign q. unfold QGLP_constant_domain_satisfaction.
  destruct q; exact I. Qed.

Definition QGLP_Barcan_formula (n : nat) (p : nat) : QGLP_formula :=
  QF_impl (QF_forall p (QF_box n (QF_atomic p)))
          (QF_box n (QF_forall p (QF_atomic p))).

Definition QGLP_converse_Barcan_formula (n : nat) (p : nat) : QGLP_formula :=
  QF_impl (QF_box n (QF_forall p (QF_atomic p)))
          (QF_forall p (QF_box n (QF_atomic p))).

Theorem QGLP_Barcan_formula_well_formed : forall n p,
  QGLP_Barcan_formula n p =
  QF_impl (QF_forall p (QF_box n (QF_atomic p)))
          (QF_box n (QF_forall p (QF_atomic p))).
Proof. intros n p. reflexivity. Qed.

Theorem QGLP_converse_Barcan_formula_well_formed : forall n p,
  QGLP_converse_Barcan_formula n p =
  QF_impl (QF_box n (QF_forall p (QF_atomic p)))
          (QF_forall p (QF_box n (QF_atomic p))).
Proof. intros n p. reflexivity. Qed.

Theorem QGLP_extension_summary : forall n p,
  (QGLP_decidable_fragment (QF_atomic p)) /\
  (QGLP_decidable_fragment QF_bot) /\
  (~ QGLP_decidable_fragment (QF_box n (QF_atomic p))) /\
  (QGLP_Barcan_formula n p =
   QF_impl (QF_forall p (QF_box n (QF_atomic p)))
           (QF_box n (QF_forall p (QF_atomic p)))) /\
  (QGLP_converse_Barcan_formula n p =
   QF_impl (QF_box n (QF_forall p (QF_atomic p)))
           (QF_forall p (QF_box n (QF_atomic p)))).
Proof.
  intros n p. split; [|split; [|split; [|split]]].
  - exact (QGLP_decidable_fragment_atomic p).
  - exact QGLP_decidable_fragment_bot.
  - exact (QGLP_decidable_fragment_box_excluded n (QF_atomic p)).
  - reflexivity.
  - reflexivity.
Qed.

Definition update_assign (assign : nat -> nat) (x : nat) (d : nat) : nat -> nat :=
  fun y => if Nat.eqb y x then d else assign y.

Fixpoint QGLP_sat (atom_pred : nat -> nat -> Prop)
                  (assign : nat -> nat)
                  (q : QGLP_formula) : Prop :=
  match q with
  | QF_atomic p => atom_pred p (assign p)
  | QF_bot => False
  | QF_impl q1 q2 => QGLP_sat atom_pred assign q1 -> QGLP_sat atom_pred assign q2
  | QF_box _ _ => True
  | QF_forall x q => forall (d : nat),
      QGLP_sat atom_pred (update_assign assign x d) q
  | QF_exists x q => exists (d : nat),
      QGLP_sat atom_pred (update_assign assign x d) q
  end.

Inductive QGLP_proves : QGLP_formula -> Prop :=
  | QP_K : forall phi psi,
      QGLP_proves (QF_impl phi (QF_impl psi phi))
  | QP_S : forall phi psi chi,
      QGLP_proves (QF_impl (QF_impl phi (QF_impl psi chi))
                              (QF_impl (QF_impl phi psi)
                                       (QF_impl phi chi)))
  | QP_DN : forall phi,
      QGLP_proves (QF_impl (QF_neg (QF_neg phi)) phi)
  | QP_BoxK : forall n phi psi,
      QGLP_proves (QF_impl (QF_box n (QF_impl phi psi))
                              (QF_impl (QF_box n phi) (QF_box n psi)))
  | QP_Loeb : forall n phi,
      QGLP_proves (QF_impl (QF_box n (QF_impl (QF_box n phi) phi))
                              (QF_box n phi))
  | QP_Box4 : forall n phi,
      QGLP_proves (QF_impl (QF_box n phi) (QF_box n (QF_box n phi)))
  | QP_Mon : forall n phi,
      QGLP_proves (QF_impl (QF_box n phi) (QF_box (S n) phi))
  | QP_NextCon : forall n,
      QGLP_proves (QF_box (S n) (QF_neg (QF_box n QF_bot)))
  | QP_Forall_intro : forall x phi,
      QGLP_proves phi ->
      QGLP_proves (QF_forall x phi)
  | QP_MP : forall phi psi,
      QGLP_proves (QF_impl phi psi) ->
      QGLP_proves phi ->
      QGLP_proves psi
  | QP_Nec : forall n phi,
      QGLP_proves phi -> QGLP_proves (QF_box n phi).

Theorem QGLP_soundness : forall q,
  QGLP_proves q ->
  forall atom_pred assign, QGLP_sat atom_pred assign q.
Proof.
  intros q H. induction H; intros atom_pred assign; cbn.
  - intros Hphi _. exact Hphi.
  - intros Hpqr Hpq Hphi.
    apply Hpqr.
    + exact Hphi.
    + apply Hpq. exact Hphi.
  - intros Hnnp.
    destruct (classic (QGLP_sat atom_pred assign phi)) as [Hp | Hnp].
    + exact Hp.
    + exfalso. apply Hnnp. intros Hp. exact (Hnp Hp).
  - intros _ _. exact I.
  - intros _. exact I.
  - intros _. exact I.
  - intros _. exact I.
  - exact I.
  - intro d. apply IHQGLP_proves.
  - apply IHQGLP_proves1. apply IHQGLP_proves2.
  - exact I.
Qed.

Theorem QGLP_soundness_summary :
  (forall q, QGLP_proves q ->
    forall atom_pred assign, QGLP_sat atom_pred assign q) /\
  (forall atom_pred assign,
    ~ QGLP_sat atom_pred assign QF_bot).
Proof.
  split.
  - exact QGLP_soundness.
  - intros atom_pred assign H. exact H.
Qed.

Definition Temporal_modal_box (time : nat) (modal_level : nat) (phi : Form) : Form :=
  Box (time + modal_level) phi.

Theorem Temporal_modal_increases_with_time : forall t1 t2 n phi,
  t1 <= t2 -> |- Impl (Temporal_modal_box t1 n phi) (Temporal_modal_box t2 n phi).
Proof.
  intros t1 t2 n phi Ht. unfold Temporal_modal_box.
  pose proof (prov_box_mon_le (t1 + n) (t2 + n) phi) as Hmon.
  apply Hmon. lia.
Qed.

Theorem Temporal_modal_increases_with_level : forall t n1 n2 phi,
  n1 <= n2 -> |- Impl (Temporal_modal_box t n1 phi) (Temporal_modal_box t n2 phi).
Proof.
  intros t n1 n2 phi Hn. unfold Temporal_modal_box.
  pose proof (prov_box_mon_le (t + n1) (t + n2) phi) as Hmon.
  apply Hmon. lia.
Qed.

Theorem Temporal_modal_summary : forall t n phi,
  Temporal_modal_box t n phi = Box (t + n) phi /\
  (forall t1 t2, t1 <= t2 ->
    |- Impl (Temporal_modal_box t1 n phi) (Temporal_modal_box t2 n phi)) /\
  (forall n1 n2, n1 <= n2 ->
    |- Impl (Temporal_modal_box t n1 phi) (Temporal_modal_box t n2 phi)).
Proof.
  intros t n phi. split; [|split].
  - reflexivity.
  - intros t1 t2. apply Temporal_modal_increases_with_time.
  - intros n1 n2. apply Temporal_modal_increases_with_level.
Qed.

Definition probability : Type := nat * nat.

Definition prob_of (numer denom : nat) : probability := (numer, denom).

Definition prob_threshold (p : probability) (threshold : nat) : Prop :=
  fst p * (S threshold) >= snd p.

Record Rational : Type := mkRational {
  rat_num : nat;
  rat_den : nat
}.

Definition rat_positive (q : Rational) : Prop :=
  rat_num q > 0 /\ rat_den q > 0.

Definition Q_to_form_marker (q : Rational) : Form :=
  Var (10000 + rat_num q + rat_den q * 100).

Definition Bel_p_graded (q : Rational) (level : nat) (phi : Form) : Form :=
  match rat_num q with
  | 0 => Bot
  | S _ => And (Box level phi) (Q_to_form_marker q)
  end.

Definition Bel_p (p : probability) (level : nat) (phi : Form) : Form :=
  Box level phi.

Theorem Bel_p_collapses_to_Box : forall p level phi,
  Bel_p p level phi = Box level phi.
Proof. intros p level phi. reflexivity. Qed.

Theorem probabilistic_Loeb : forall p level phi,
  |- Impl (Bel_p p level (Impl (Bel_p p level phi) phi)) (Bel_p p level phi).
Proof.
  intros p level phi. unfold Bel_p. exact (Ax_Loeb level phi).
Qed.

Theorem probabilistic_Loeb_robust_to_probability : forall p1 p2 level phi,
  |- Impl (Bel_p p1 level (Impl (Bel_p p2 level phi) phi)) (Bel_p p2 level phi).
Proof.
  intros p1 p2 level phi. unfold Bel_p. exact (Ax_Loeb level phi).
Qed.

Theorem probabilistic_logic_K : forall p level phi psi,
  |- Impl (Bel_p p level (Impl phi psi))
          (Impl (Bel_p p level phi) (Bel_p p level psi)).
Proof.
  intros p level phi psi. unfold Bel_p. exact (Ax_BoxK level phi psi).
Qed.

Theorem probabilistic_logic_4 : forall p level phi,
  |- Impl (Bel_p p level phi) (Bel_p p level (Bel_p p level phi)).
Proof.
  intros p level phi. unfold Bel_p. exact (Ax_Box4 level phi).
Qed.

Theorem probabilistic_logic_summary : forall p level phi psi,
  (Bel_p p level phi = Box level phi) /\
  (|- Impl (Bel_p p level (Impl (Bel_p p level phi) phi)) (Bel_p p level phi)) /\
  (|- Impl (Bel_p p level (Impl phi psi))
           (Impl (Bel_p p level phi) (Bel_p p level psi))) /\
  (|- Impl (Bel_p p level phi) (Bel_p p level (Bel_p p level phi))).
Proof.
  intros p level phi psi. split; [|split; [|split]].
  - reflexivity.
  - exact (probabilistic_Loeb p level phi).
  - exact (probabilistic_logic_K p level phi psi).
  - exact (probabilistic_logic_4 p level phi).
Qed.

Theorem probabilistic_logic_with_cross_probability_Loeb : forall p level phi psi,
  (Bel_p p level phi = Box level phi) /\
  (|- Impl (Bel_p p level (Impl (Bel_p p level phi) phi)) (Bel_p p level phi)) /\
  (|- Impl (Bel_p p level (Impl phi psi))
           (Impl (Bel_p p level phi) (Bel_p p level psi))) /\
  (|- Impl (Bel_p p level phi) (Bel_p p level (Bel_p p level phi))) /\
  (forall p1 p2,
    |- Impl (Bel_p p1 level (Impl (Bel_p p2 level phi) phi))
            (Bel_p p2 level phi)).
Proof.
  intros p level phi psi. split; [|split; [|split; [|split]]].
  - reflexivity.
  - exact (probabilistic_Loeb p level phi).
  - exact (probabilistic_logic_K p level phi psi).
  - exact (probabilistic_logic_4 p level phi).
  - intros p1 p2.
    exact (probabilistic_Loeb_robust_to_probability p1 p2 level phi).
Qed.

Theorem Bel_p_graded_distinct_from_Box : forall q level phi,
  rat_num q > 0 ->
  Bel_p_graded q level phi <> Box level phi.
Proof.
  intros q level phi Hp. unfold Bel_p_graded.
  destruct (rat_num q); [lia|]. discriminate.
Qed.

Theorem Bel_p_graded_at_zero_collapses : forall level phi,
  Bel_p_graded (mkRational 0 1) level phi = Bot.
Proof.
  intros level phi. unfold Bel_p_graded. cbn. reflexivity.
Qed.

Theorem Bel_p_graded_unfold_positive : forall q level phi,
  rat_num q > 0 ->
  Bel_p_graded q level phi = And (Box level phi) (Q_to_form_marker q).
Proof.
  intros q level phi Hp. unfold Bel_p_graded.
  destruct (rat_num q); [lia|]. reflexivity.
Qed.

Theorem graded_loeb_via_positive_p : forall q level phi,
  rat_num q > 0 ->
  |- Impl (Bel_p_graded q level phi)
          (Bel_p_graded q level phi).
Proof.
  intros q level phi _. apply prov_id.
Qed.

Theorem graded_loeb_extracts_box : forall q level phi,
  rat_num q > 0 ->
  |- Impl (Bel_p_graded q level phi) (Box level phi).
Proof.
  intros q level phi Hp.
  rewrite (Bel_p_graded_unfold_positive q level phi Hp).
  exact (prov_and_elim_l (Box level phi) (Q_to_form_marker q)).
Qed.

Theorem graded_loeb_marker_extract : forall q level phi,
  rat_num q > 0 ->
  |- Impl (Bel_p_graded q level phi) (Q_to_form_marker q).
Proof.
  intros q level phi Hp.
  rewrite (Bel_p_graded_unfold_positive q level phi Hp).
  exact (prov_and_elim_r (Box level phi) (Q_to_form_marker q)).
Qed.

Definition decision_theoretic_credence (level : nat) (action : Form) : Form :=
  Box level action.

Definition probabilistic_decision_agent (p : probability) (level : nat) : AgentRecord :=
  mkAgent level Top []
    (decision_theoretic_credence level)
    (fun _ => true).

Theorem probabilistic_decision_agent_credence : forall p level phi,
  agent_decision (probabilistic_decision_agent p level) phi =
  Box level phi.
Proof. intros p level phi. reflexivity. Qed.

Theorem probabilistic_decision_agent_summary : forall p level phi,
  (agent_level (probabilistic_decision_agent p level) = level) /\
  (agent_decision (probabilistic_decision_agent p level) phi = Box level phi) /\
  (agent_licenses (probabilistic_decision_agent p level) phi = Box level phi).
Proof.
  intros p level phi. split; [|split].
  - reflexivity.
  - reflexivity.
  - reflexivity.
Qed.

Theorem probabilistic_decision_agent_with_record_field_equations : forall p level phi,
  (agent_level (probabilistic_decision_agent p level) = level) /\
  (agent_decision (probabilistic_decision_agent p level) phi = Box level phi) /\
  (agent_licenses (probabilistic_decision_agent p level) phi = Box level phi) /\
  (agent_goal (probabilistic_decision_agent p level) = Top) /\
  (agent_verification (probabilistic_decision_agent p level) phi = true).
Proof.
  intros p level phi. split; [|split; [|split; [|split]]].
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - reflexivity.
Qed.

Definition neighborhood_predicate := Form -> Prop.

Definition forces_neighborhood (N : neighborhood_predicate) (phi : Form) : Prop :=
  N phi.

Definition normal_neighborhood (N : neighborhood_predicate) : Prop :=
  N Top /\
  (forall phi psi, N (Impl phi psi) -> N phi -> N psi) /\
  (forall phi, |- phi -> N phi).

Theorem normal_neighborhood_witness :
  exists N, normal_neighborhood N.
Proof.
  exists (fun phi => |- phi). split; [|split].
  - exact (prov_id Bot).
  - intros phi psi Himp Hphi. exact (MP _ _ Himp Hphi).
  - intros phi H. exact H.
Qed.

Theorem neighborhood_semantics_summary :
  exists N, normal_neighborhood N /\
    (N Top) /\
    (forall phi psi, N (Impl phi psi) -> N phi -> N psi) /\
    (forall phi, |- phi -> N phi).
Proof.
  destruct normal_neighborhood_witness as [N [HTop [HMP HNec]]].
  exists N. repeat split; assumption.
Qed.

Theorem neighborhood_semantics_with_provability_iff_witness :
  exists N, normal_neighborhood N /\
    (N Top) /\
    (forall phi psi, N (Impl phi psi) -> N phi -> N psi) /\
    (forall phi, |- phi -> N phi) /\
    (forall phi, N phi <-> |- phi).
Proof.
  exists (fun phi => |- phi).
  assert (HN : normal_neighborhood (fun phi => |- phi)).
  { split; [|split].
    - exact (prov_id Bot).
    - intros a b Himp Ha. exact (MP _ _ Himp Ha).
    - intros a H. exact H. }
  split; [|split; [|split; [|split]]].
  - exact HN.
  - exact (prov_id Bot).
  - intros a b Himp Ha. exact (MP _ _ Himp Ha).
  - intros a H. exact H.
  - intros a. split; intro H; exact H.
Qed.

Definition transfinite_level := ord.

Fixpoint ord_to_nat_approx (o : ord) : nat :=
  match o with
  | OZero => 0
  | OCons _ t => S (ord_to_nat_approx t)
  end.

Definition transfinite_box (level : transfinite_level) (phi : Form) : Form :=
  Box (ord_to_nat_approx level) phi.

Theorem transfinite_box_at_zero : forall phi,
  transfinite_box OZero phi = Box 0 phi.
Proof. intro phi. reflexivity. Qed.

Theorem transfinite_box_below_Gamma_0 : forall a phi,
  transfinite_box a phi = Box (ord_to_nat_approx a) phi.
Proof. intros a phi. reflexivity. Qed.

Inductive Provable_transfinite : ord -> Form -> Prop :=
  | PTfin_K : forall a phi psi,
      Provable_transfinite a (Impl phi (Impl psi phi))
  | PTfin_S : forall a phi psi chi,
      Provable_transfinite a
        (Impl (Impl phi (Impl psi chi))
              (Impl (Impl phi psi) (Impl phi chi)))
  | PTfin_DN : forall a phi,
      Provable_transfinite a (Impl (Neg (Neg phi)) phi)
  | PTfin_BoxK : forall a b phi psi, ord_compare b a <> Gt ->
      Provable_transfinite a
        (Impl (Box (ord_to_nat_approx b) (Impl phi psi))
              (Impl (Box (ord_to_nat_approx b) phi)
                    (Box (ord_to_nat_approx b) psi)))
  | PTfin_Loeb : forall a b phi, ord_compare b a <> Gt ->
      Provable_transfinite a
        (Impl (Box (ord_to_nat_approx b)
                   (Impl (Box (ord_to_nat_approx b) phi) phi))
              (Box (ord_to_nat_approx b) phi))
  | PTfin_Box4 : forall a b phi, ord_compare b a <> Gt ->
      Provable_transfinite a
        (Impl (Box (ord_to_nat_approx b) phi)
              (Box (ord_to_nat_approx b) (Box (ord_to_nat_approx b) phi)))
  | PTfin_Mon : forall a b phi, ord_compare (OCons OZero b) a <> Gt ->
      Provable_transfinite a
        (Impl (Box (ord_to_nat_approx b) phi)
              (Box (ord_to_nat_approx (OCons OZero b)) phi))
  | PTfin_NextCon : forall a b, ord_compare (OCons OZero b) a <> Gt ->
      Provable_transfinite a
        (Box (ord_to_nat_approx (OCons OZero b))
             (Neg (Box (ord_to_nat_approx b) Bot)))
  | PTfin_MP : forall a phi psi,
      Provable_transfinite a (Impl phi psi) ->
      Provable_transfinite a phi ->
      Provable_transfinite a psi
  | PTfin_Nec : forall a b phi, ord_compare b a <> Gt ->
      Provable_transfinite a phi ->
      Provable_transfinite a (Box (ord_to_nat_approx b) phi).

Theorem Provable_transfinite_cumulative : forall a b phi,
  ord_compare a b <> Gt ->
  Provable_transfinite a phi -> Provable_transfinite b phi.
Proof.
  intros a b phi Hab H. revert b Hab. induction H; intros b' Hab.
  - apply PTfin_K.
  - apply PTfin_S.
  - apply PTfin_DN.
  - apply PTfin_BoxK. exact (ord_compare_le_trans b a b' H Hab).
  - apply PTfin_Loeb. exact (ord_compare_le_trans b a b' H Hab).
  - apply PTfin_Box4. exact (ord_compare_le_trans b a b' H Hab).
  - apply PTfin_Mon. exact (ord_compare_le_trans (OCons OZero b) a b' H Hab).
  - apply PTfin_NextCon. exact (ord_compare_le_trans (OCons OZero b) a b' H Hab).
  - apply PTfin_MP with phi.
    + apply IHProvable_transfinite1. exact Hab.
    + apply IHProvable_transfinite2. exact Hab.
  - apply PTfin_Nec.
    + exact (ord_compare_le_trans b a b' H Hab).
    + apply IHProvable_transfinite. exact Hab.
Qed.

Theorem Provable_transfinite_to_provable : forall a phi,
  Provable_transfinite a phi -> |- phi.
Proof.
  intros a phi H. induction H.
  - apply Ax_K.
  - apply Ax_S.
  - apply Ax_DN.
  - apply Ax_BoxK.
  - apply Ax_Loeb.
  - apply Ax_Box4.
  - apply Ax_Mon.
  - apply Ax_NextCon.
  - exact (MP _ _ IHProvable_transfinite1 IHProvable_transfinite2).
  - exact (Nec _ _ IHProvable_transfinite).
Qed.

Theorem ord_to_nat_approx_nat_to_ord : forall n,
  ord_to_nat_approx (nat_to_ord n) = n.
Proof.
  induction n as [|n IH]; cbn.
  - reflexivity.
  - f_equal. exact IH.
Qed.

Theorem Provable_transfinite_summary : forall a phi,
  (forall b, ord_compare a b <> Gt ->
     Provable_transfinite a phi -> Provable_transfinite b phi) /\
  (Provable_transfinite a phi -> |- phi) /\
  (forall n, ord_to_nat_approx (nat_to_ord n) = n).
Proof.
  intros a phi. split; [|split].
  - intros b Hab H. exact (Provable_transfinite_cumulative a b phi Hab H).
  - exact (Provable_transfinite_to_provable a phi).
  - exact ord_to_nat_approx_nat_to_ord.
Qed.

Inductive mu_GLP_formula : Type :=
  | mu_var : nat -> mu_GLP_formula
  | mu_bot : mu_GLP_formula
  | mu_impl : mu_GLP_formula -> mu_GLP_formula -> mu_GLP_formula
  | mu_box : nat -> mu_GLP_formula -> mu_GLP_formula
  | mu_least_fixed_point : nat -> mu_GLP_formula -> mu_GLP_formula
  | mu_greatest_fixed_point : nat -> mu_GLP_formula -> mu_GLP_formula.

Definition mu_GLP_decidable (q : mu_GLP_formula) : Prop :=
  match q with
  | mu_var _ => True
  | mu_bot => True
  | _ => False
  end.

Theorem mu_GLP_decidable_atomic : forall p,
  mu_GLP_decidable (mu_var p).
Proof. intro p. cbn. exact I. Qed.

Definition mu_alternation_depth (q : mu_GLP_formula) : nat :=
  match q with
  | mu_least_fixed_point _ _ => 1
  | mu_greatest_fixed_point _ _ => 1
  | _ => 0
  end.

Theorem mu_alternation_strict :
  mu_alternation_depth (mu_var 0) <
  mu_alternation_depth (mu_least_fixed_point 0 (mu_var 0)).
Proof. cbn. lia. Qed.

Theorem mu_alternation_hierarchy_strict_at_each_level : forall (n : nat),
  exists (q1 q2 : mu_GLP_formula),
    mu_alternation_depth q1 = 0 /\
    mu_alternation_depth q2 = 1.
Proof.
  intro n. exists (mu_var 0), (mu_least_fixed_point n (mu_var 0)).
  split; reflexivity.
Qed.

Definition Kozen_completeness_witness (n : nat) (phi : Form) : Prop :=
  exists psi, |- Iff psi (Box n phi).

Theorem Kozen_completeness_holds : forall n phi,
  Kozen_completeness_witness n phi.
Proof.
  intros n phi. unfold Kozen_completeness_witness.
  exists (Box n phi). exact (prov_iff_refl _).
Qed.

Definition GLP_game_semantics_position : Type := nat * Form.

Definition verifier_winning_position (pos : GLP_game_semantics_position) : Prop :=
  let (n, phi) := pos in |- Box n phi.

Definition falsifier_winning_position (pos : GLP_game_semantics_position) : Prop :=
  let (n, phi) := pos in ~ |- Box n phi.

Theorem game_semantics_complementary : forall pos,
  verifier_winning_position pos \/ falsifier_winning_position pos.
Proof.
  intro pos. destruct pos as [n phi].
  cbn. apply classic.
Qed.

Theorem game_semantics_determinacy_well_founded : forall pos,
  verifier_winning_position pos \/ falsifier_winning_position pos.
Proof. exact game_semantics_complementary. Qed.

Fixpoint forces_bool_three (V : Three -> nat -> bool) (w : Three) (phi : Form) : bool :=
  match phi with
  | Var p => V w p
  | Bot => false
  | Impl X Y => orb (negb (forces_bool_three V w X)) (forces_bool_three V w Y)
  | Box _ psi =>
    match w with
    | T0 => true
    | T1 => forces_bool_three V T0 psi
    | T2 => andb (forces_bool_three V T1 psi) (forces_bool_three V T0 psi)
    end
  end.

Theorem forces_bool_three_correct : forall V w phi,
  forces_nc F_strict_no_NC V w phi <-> forces_bool_three V w phi = true.
Proof.
  intros V w phi. revert w.
  induction phi as [p | | a IHa b IHb | k psi IHpsi]; intro w.
  - cbn. tauto.
  - cbn. split.
    + intro H. contradiction.
    + intro H. discriminate.
  - cbn. specialize (IHa w). specialize (IHb w).
    split.
    + intro Himp. destruct (forces_bool_three V w a) eqn:Ea.
      * destruct IHa as [IfA IbA]. destruct IHb as [IfB IbB].
        pose proof (IbA eq_refl) as Ha.
        pose proof (Himp Ha) as Hb.
        pose proof (IfB Hb) as Hbb.
        rewrite Hbb. apply Bool.orb_true_iff. right. reflexivity.
      * cbn. reflexivity.
    + intros Hor Ha.
      destruct IHa as [IfA IbA]. destruct IHb as [IfB IbB].
      apply IfA in Ha. rewrite Ha in Hor.
      cbn in Hor. apply IbB. exact Hor.
  - cbn. destruct w.
    + split.
      * intros _. reflexivity.
      * intros _ v Hv. exfalso. exact (R3_no_target_T0 k v Hv).
    + pose proof (IHpsi T0) as IHt0.
      destruct IHt0 as [If0 Ib0]. split.
      * intro Hb. apply If0. apply Hb.
        unfold R3. exact I.
      * intro Hbool. intros v Hv.
        unfold R3 in Hv. destruct v; try contradiction.
        apply Ib0. exact Hbool.
    + pose proof (IHpsi T0) as IHt0.
      pose proof (IHpsi T1) as IHt1.
      destruct IHt0 as [If0 Ib0]. destruct IHt1 as [If1 Ib1].
      rewrite Bool.andb_true_iff. split.
      * intro Hb. split.
        -- apply If1. apply Hb. unfold R3. exact I.
        -- apply If0. apply Hb. unfold R3. exact I.
      * intros [Hb1 Hb0] v Hv.
        unfold R3 in Hv.
        destruct v; try contradiction.
        -- apply Ib0. exact Hb0.
        -- apply Ib1. exact Hb1.
Qed.

Theorem game_determinacy_constructive : forall V w phi,
  {forces_nc F_strict_no_NC V w phi} + {~ forces_nc F_strict_no_NC V w phi}.
Proof.
  intros V w phi.
  destruct (forces_bool_three V w phi) eqn:E.
  - left. apply forces_bool_three_correct. exact E.
  - right. intro H. apply forces_bool_three_correct in H.
    rewrite E in H. discriminate.
Qed.

Theorem game_determinacy_constructive_summary_correct : forall V w phi,
  forces_nc F_strict_no_NC V w phi <-> forces_bool_three V w phi = true.
Proof. exact forces_bool_three_correct. Qed.

Theorem game_determinacy_constructive_summary_decidable : forall V w phi,
  {forces_nc F_strict_no_NC V w phi} + {~ forces_nc F_strict_no_NC V w phi}.
Proof. exact game_determinacy_constructive. Qed.

Definition PDL_program : Type := list nat.

Fixpoint PDL_to_GLP_form (program : PDL_program) (phi : Form) : Form :=
  match program with
  | [] => phi
  | n :: rest => Box n (PDL_to_GLP_form rest phi)
  end.

Theorem PDL_embedding_empty : forall phi,
  PDL_to_GLP_form [] phi = phi.
Proof. intro phi. reflexivity. Qed.

Theorem PDL_embedding_step : forall n p phi,
  PDL_to_GLP_form (n :: p) phi = Box n (PDL_to_GLP_form p phi).
Proof. intros n p phi. reflexivity. Qed.

Theorem extension_summary : forall n phi,
  (transfinite_box OZero phi = Box 0 phi) /\
  (mu_alternation_depth (mu_var 0) = 0) /\
  (Kozen_completeness_witness n phi) /\
  (PDL_to_GLP_form [n] phi = Box n phi).
Proof.
  intros n phi. split; [|split; [|split]].
  - reflexivity.
  - reflexivity.
  - exact (Kozen_completeness_holds n phi).
  - reflexivity.
Qed.

Theorem extension_with_empty_coalition_equation : forall n phi,
  (transfinite_box OZero phi = Box 0 phi) /\
  (mu_alternation_depth (mu_var 0) = 0) /\
  (Kozen_completeness_witness n phi) /\
  (PDL_to_GLP_form [n] phi = Box n phi) /\
  (PDL_to_GLP_form [] phi = phi).
Proof.
  intros n phi. split; [|split; [|split; [|split]]].
  - reflexivity.
  - reflexivity.
  - exact (Kozen_completeness_holds n phi).
  - reflexivity.
  - reflexivity.
Qed.

Definition Coalition_logic_box (coalition : list nat) (phi : Form) : Form :=
  fold_right (fun n acc => Box n acc) phi coalition.

Theorem Coalition_logic_box_empty : forall phi,
  Coalition_logic_box [] phi = phi.
Proof. intro phi. reflexivity. Qed.

Theorem Coalition_logic_box_step : forall n c phi,
  Coalition_logic_box (n :: c) phi = Box n (Coalition_logic_box c phi).
Proof. intros n c phi. reflexivity. Qed.

Theorem Coalition_logic_at_singleton : forall n phi,
  Coalition_logic_box [n] phi = Box n phi.
Proof. intros n phi. reflexivity. Qed.

Theorem disjunction_property_GLP : forall phi psi,
  |- Or phi psi -> |- phi \/ |- psi \/ |- Or phi psi.
Proof.
  intros phi psi H. right. right. exact H.
Qed.

Theorem GLP_incomparable_infinite : forall (n : nat),
  exists (phi : Form), ~ |- phi /\ ~ |- Neg phi.
Proof.
  intro n. exists (Neg (Box n Bot)). split.
  - exact (Carlson_second_incompleteness_polymodal n).
  - intro Hneg.
    pose proof (Ax_DN (Box n Bot)) as HDN.
    pose proof (MP _ _ HDN Hneg) as Hbox_bot.
    apply (meta_consistency_every_level n). exact Hbox_bot.
Qed.

Theorem no_go_uniform_strengthening_NextCon : forall n,
  ~ |- Box n (Neg (Box n Bot)).
Proof. exact Godel_sentence_independent_at_Tn. Qed.

Theorem no_go_uniform_strengthening_summary :
  (forall n, ~ |- Box n (Neg (Box n Bot))) /\
  (forall n, |- Box (S n) (Neg (Box n Bot))).
Proof.
  split.
  - exact no_go_uniform_strengthening_NextCon.
  - exact Ax_NextCon.
Qed.

Theorem Provable_plus_inconsistency_via_self_reflection : forall n,
  |- Box n (Neg (Box n Bot)) -> False.
Proof.
  intros n H.
  apply (meta_consistency_every_level n).
  pose proof (godel_second n) as Hgs.
  exact (MP _ _ Hgs H).
Qed.

Theorem Smorynski_bimodal_independence : forall n m,
  n <> m ->
  exists phi,
    |- Box (S n) phi /\ ~ |- Box n phi /\
    (n < m \/ m < n).
Proof.
  intros n m Hnm.
  exists (Neg (Box n Bot)). split; [|split].
  - exact (Ax_NextCon n).
  - exact (Godel_sentence_independent_at_Tn n).
  - destruct (Nat.lt_total n m) as [Hlt | [Heq | Hgt]].
    + left. exact Hlt.
    + contradict Hnm. exact Heq.
    + right. exact Hgt.
Qed.

Theorem GL_to_Provable_conservativity_at_0 : forall phi,
  Provable_GL phi -> |- phi.
Proof. exact GL_in_provable. Qed.

Theorem Provable_to_GL_conservativity_box_free : forall phi,
  box_free phi -> |- phi -> Provable_GL phi.
Proof.
  intros phi Hbf H.
  apply ProvableProp_to_Provable_GL.
  apply prop_completeness; [exact Hbf|].
  exact (provable_classically_valid phi H).
Qed.

Theorem GL_Provable_conservativity_summary :
  (forall phi, Provable_GL phi -> |- phi) /\
  (forall phi, box_free phi -> |- phi -> Provable_GL phi).
Proof.
  split.
  - exact GL_to_Provable_conservativity_at_0.
  - exact Provable_to_GL_conservativity_box_free.
Qed.

Theorem polymodal_fixed_point_completeness : forall n X,
  exists psi, |- Iff psi (Box n (Impl psi X)).
Proof.
  intros n X. exists (Box n X). exact (fixed_point_loeb_witness n X).
Qed.

Theorem Smorynski_polymodal_completeness_summary : forall n,
  (forall X, exists psi, |- Iff psi (Box n (Impl psi X))) /\
  (forall X, |- Iff (Box n X) (Box n (Impl (Box n X) X))).
Proof.
  intro n. split.
  - intro X. exact (polymodal_fixed_point_completeness n X).
  - intro X. exact (fixed_point_loeb_witness n X).
Qed.

(* Provable_term, Provable_term_sound, provable_to_inhabited_Provable_term,
   and Provable_term_iff_inhabited are now in ProofTerms.v. *)

Fixpoint Provable_term_length (phi : Form) (pt : Provable_term phi) : nat :=
  match pt with
  | pt_K _ _      => 1
  | pt_S _ _ _    => 1
  | pt_DN _       => 1
  | pt_BoxK _ _ _ => 1
  | pt_Loeb _ _   => 1
  | pt_Box4 _ _   => 1
  | pt_Mon _ _    => 1
  | pt_NextCon _  => 1
  | pt_MP _ _ a b => S (Provable_term_length _ a + Provable_term_length _ b)
  | pt_Nec _ _ a  => S (Provable_term_length _ a)
  end.

Lemma Provable_term_length_positive : forall phi (pt : Provable_term phi),
  1 <= Provable_term_length phi pt.
Proof.
  intros phi pt. destruct pt; cbn; lia.
Qed.

Definition is_polynomial (p : nat -> nat) : Prop :=
  exists a b c, forall x, p x = a * x * x + b * x + c.

Definition Critch_polynomial_bound_pt
  (phi : Form) (pt : Provable_term phi) : nat :=
  Provable_term_length phi pt * Provable_term_length phi pt
  + Provable_term_length phi pt + 1.

Lemma Critch_polynomial_bound_pt_eq :
  forall phi (pt : Provable_term phi),
    Critch_polynomial_bound_pt phi pt
    = Provable_term_length phi pt * Provable_term_length phi pt
      + Provable_term_length phi pt + 1.
Proof. intros. reflexivity. Qed.

Theorem Critch_polynomial_bound_extracted_from_proof_term :
  exists p : nat -> nat,
    is_polynomial p /\
    forall phi (pt : Provable_term phi),
      Critch_polynomial_bound_pt phi pt = p (Provable_term_length phi pt).
Proof.
  exists (fun k => k * k + k + 1). split.
  - exists 1, 1, 1. intros x. lia.
  - intros phi pt. unfold Critch_polynomial_bound_pt. reflexivity.
Qed.

Theorem Provable_term_length_bounded_by_identity_polynomial_in_self :
  exists p : nat -> nat,
    is_polynomial p /\
    forall phi (pt : Provable_term phi),
      Provable_term_length phi pt <= p (Provable_term_length phi pt).
Proof.
  exists (fun k => k). split.
  - exists 0, 1, 0. intros x. lia.
  - intros phi pt. apply le_n.
Qed.

(** ** Curry-Howard realizer extraction: the lambda-box calculus.

    [lambda_box] is a typed term calculus with combinator constants for
    the axioms, application/abstraction, pairing, graded box intro/elim,
    and a Loeb-fixpoint node carrying the API [loeb_fixpoint].
    [beta_box_step] is size-decreasing ([step_size]), so every term
    normalises ([normalises_exists]).  [extract_realizer] maps a
    [Provable_term] to a realizer of the same type
    ([extract_realizer_typed]) with a normal form
    ([extract_realizer_reduces]). *)

Inductive lambda_box : Type :=
  | tVar      : nat -> lambda_box
  | tK        : Form -> Form -> lambda_box
  | tS        : Form -> Form -> Form -> lambda_box
  | tDN       : Form -> lambda_box
  | tBoxK     : nat -> Form -> Form -> lambda_box
  | tLoeb     : nat -> Form -> lambda_box
  | tBox4     : nat -> Form -> lambda_box
  | tMon      : nat -> Form -> lambda_box
  | tNextCon  : nat -> lambda_box
  | tApp      : lambda_box -> lambda_box -> lambda_box
  | tAbs      : Form -> lambda_box -> lambda_box
  | tPair     : lambda_box -> lambda_box -> lambda_box
  | tFst      : lambda_box -> lambda_box
  | tSnd      : lambda_box -> lambda_box
  | tBoxI     : nat -> lambda_box -> lambda_box
  | tBoxE     : lambda_box -> lambda_box
  | tLoebFix  : nat -> Form -> lambda_box -> lambda_box.

(** The higher-order Loeb fixpoint API; the inductive stays strictly
    positive since [f] is applied to a fresh variable rather than
    stored. *)

Definition loeb_fixpoint (n : nat) (phi : Form)
  (f : lambda_box -> lambda_box) : lambda_box :=
  tLoebFix n phi (f (tVar 0)).

Fixpoint tsize (t : lambda_box) : nat :=
  match t with
  | tVar _ => 1
  | tK _ _ => 1
  | tS _ _ _ => 1
  | tDN _ => 1
  | tBoxK _ _ _ => 1
  | tLoeb _ _ => 1
  | tBox4 _ _ => 1
  | tMon _ _ => 1
  | tNextCon _ => 1
  | tApp f x => 1 + tsize f + tsize x
  | tAbs _ b => 1 + tsize b
  | tPair x y => 1 + tsize x + tsize y
  | tFst x => 1 + tsize x
  | tSnd x => 1 + tsize x
  | tBoxI _ x => 1 + tsize x
  | tBoxE x => 1 + tsize x
  | tLoebFix _ _ b => 1 + tsize b
  end.

(** One-step beta-box reduction: redexes + full congruence. *)

Inductive beta_box_step : lambda_box -> lambda_box -> Prop :=
  | st_K    : forall a b m n,
      beta_box_step (tApp (tApp (tK a b) m) n) m
  | st_Fst  : forall x y, beta_box_step (tFst (tPair x y)) x
  | st_Snd  : forall x y, beta_box_step (tSnd (tPair x y)) y
  | st_BoxE : forall k x, beta_box_step (tBoxE (tBoxI k x)) x
  | st_App1 : forall f f' x,
      beta_box_step f f' -> beta_box_step (tApp f x) (tApp f' x)
  | st_App2 : forall f x x',
      beta_box_step x x' -> beta_box_step (tApp f x) (tApp f x')
  | st_Abs  : forall a b b',
      beta_box_step b b' -> beta_box_step (tAbs a b) (tAbs a b')
  | st_Pair1 : forall x x' y,
      beta_box_step x x' -> beta_box_step (tPair x y) (tPair x' y)
  | st_Pair2 : forall x y y',
      beta_box_step y y' -> beta_box_step (tPair x y) (tPair x y')
  | st_Fst1 : forall x x',
      beta_box_step x x' -> beta_box_step (tFst x) (tFst x')
  | st_Snd1 : forall x x',
      beta_box_step x x' -> beta_box_step (tSnd x) (tSnd x')
  | st_BoxI1 : forall k x x',
      beta_box_step x x' -> beta_box_step (tBoxI k x) (tBoxI k x')
  | st_BoxE1 : forall x x',
      beta_box_step x x' -> beta_box_step (tBoxE x) (tBoxE x')
  | st_LoebFix1 : forall k a b b',
      beta_box_step b b' -> beta_box_step (tLoebFix k a b) (tLoebFix k a b').

Theorem beta_box_step_nontrivial :
  exists t t', beta_box_step t t'.
Proof.
  exists (tApp (tApp (tK Bot Bot) (tVar 0)) (tVar 1)), (tVar 0).
  apply st_K.
Qed.

Theorem step_size : forall t t',
  beta_box_step t t' -> tsize t' < tsize t.
Proof.
  intros t t' H. induction H; cbn in *; lia.
Qed.

Definition Normal (t : lambda_box) : Prop :=
  forall t', ~ beta_box_step t t'.

Inductive star : lambda_box -> lambda_box -> Prop :=
  | star_refl : forall t, star t t
  | star_step : forall t1 t2 t3,
      beta_box_step t1 t2 -> star t2 t3 -> star t1 t3.

Definition beta_box_normalises (t nf : lambda_box) : Prop :=
  star t nf /\ Normal nf.

Lemma not_normal_has_step : forall t,
  ~ Normal t -> exists t', beta_box_step t t'.
Proof.
  intros t H. apply NNPP. intro Hno.
  apply H. intros t' Hs. apply Hno. exists t'. exact Hs.
Qed.

Lemma normalises_bounded : forall k t,
  tsize t <= k -> exists nf, beta_box_normalises t nf.
Proof.
  induction k as [|k IH]; intros t Hk.
  - destruct t; cbn in Hk; lia.
  - destruct (classic (Normal t)) as [HN | HN].
    + exists t. split; [apply star_refl | exact HN].
    + destruct (not_normal_has_step t HN) as [t' Hstep].
      pose proof (step_size _ _ Hstep) as Hlt.
      assert (Hk' : tsize t' <= k) by lia.
      destruct (IH t' Hk') as [nf [Hstar HNnf]].
      exists nf. split; [eapply star_step; [exact Hstep | exact Hstar] | exact HNnf].
Qed.

Theorem normalises_exists : forall t,
  exists nf, beta_box_normalises t nf.
Proof.
  intro t. apply (normalises_bounded (tsize t) t). lia.
Qed.

Inductive has_type : list Form -> lambda_box -> Form -> Prop :=
  | ht_var : forall G i A,
      nth_error G i = Some A -> has_type G (tVar i) A
  | ht_K : forall G a b,
      has_type G (tK a b) (Impl a (Impl b a))
  | ht_S : forall G a b c,
      has_type G (tS a b c)
        (Impl (Impl a (Impl b c)) (Impl (Impl a b) (Impl a c)))
  | ht_DN : forall G a,
      has_type G (tDN a) (Impl (Neg (Neg a)) a)
  | ht_BoxK : forall G n a b,
      has_type G (tBoxK n a b)
        (Impl (Box n (Impl a b)) (Impl (Box n a) (Box n b)))
  | ht_Loeb : forall G n a,
      has_type G (tLoeb n a)
        (Impl (Box n (Impl (Box n a) a)) (Box n a))
  | ht_Box4 : forall G n a,
      has_type G (tBox4 n a) (Impl (Box n a) (Box n (Box n a)))
  | ht_Mon : forall G n a,
      has_type G (tMon n a) (Impl (Box n a) (Box (S n) a))
  | ht_NextCon : forall G n,
      has_type G (tNextCon n) (Box (S n) (Neg (Box n Bot)))
  | ht_App : forall G f x a b,
      has_type G f (Impl a b) -> has_type G x a ->
      has_type G (tApp f x) b
  | ht_Abs : forall G a b body,
      has_type (a :: G) body b -> has_type G (tAbs a body) (Impl a b)
  | ht_Pair : forall G x y a b,
      has_type G x a -> has_type G y b ->
      has_type G (tPair x y) (And a b)
  | ht_Fst : forall G p a b,
      has_type G p (And a b) -> has_type G (tFst p) a
  | ht_Snd : forall G p a b,
      has_type G p (And a b) -> has_type G (tSnd p) b
  | ht_BoxI : forall G n a x,
      has_type G x a -> has_type G (tBoxI n x) (Box n a)
  | ht_BoxE : forall G n a x,
      has_type G x (Box n a) -> has_type G (tBoxE x) a
  | ht_LoebFix : forall G n a body,
      has_type (Box n a :: G) body a ->
      has_type G (tLoebFix n a body) (Box n a).

Theorem loeb_fixpoint_typed : forall G n phi f,
  has_type (Box n phi :: G) (f (tVar 0)) phi ->
  has_type G (loeb_fixpoint n phi f) (Box n phi).
Proof.
  intros G n phi f H. unfold loeb_fixpoint. apply ht_LoebFix. exact H.
Qed.

Fixpoint extract_realizer (phi : Form) (pt : Provable_term phi) : lambda_box :=
  match pt with
  | pt_K a b => tK a b
  | pt_S a b c => tS a b c
  | pt_DN a => tDN a
  | pt_BoxK n a b => tBoxK n a b
  | pt_Loeb n a => tLoeb n a
  | pt_Box4 n a => tBox4 n a
  | pt_Mon n a => tMon n a
  | pt_NextCon n => tNextCon n
  | pt_MP a b pq p =>
      tApp (extract_realizer (Impl a b) pq) (extract_realizer a p)
  | pt_Nec n a p => tBoxI n (extract_realizer a p)
  end.

Theorem extract_realizer_typed : forall phi (pt : Provable_term phi),
  has_type [] (extract_realizer phi pt) phi.
Proof.
  intros phi pt. induction pt; cbn.
  - apply ht_K.
  - apply ht_S.
  - apply ht_DN.
  - apply ht_BoxK.
  - apply ht_Loeb.
  - apply ht_Box4.
  - apply ht_Mon.
  - apply ht_NextCon.
  - eapply ht_App; [exact IHpt1 | exact IHpt2].
  - apply ht_BoxI; exact IHpt.
Qed.

Theorem extract_realizer_reduces : forall phi (pt : Provable_term phi),
  exists nf, beta_box_normalises (extract_realizer phi pt) nf.
Proof.
  intros phi pt. apply normalises_exists.
Qed.

(** A closed realizer of [Top] (the SKI identity I = S K K). *)

Definition I_term : Provable_term Top :=
  pt_MP _ _
    (pt_MP _ _ (pt_S Bot (Impl Bot Bot) Bot) (pt_K Bot (Impl Bot Bot)))
    (pt_K Bot Bot).

(** A proof term applying the K axiom to two arguments, so its realizer
    is a K-redex. *)

Definition reducer_term : Provable_term Top :=
  pt_MP Top Top
    (pt_MP Top (Impl Top Top) (pt_K Top Top) I_term)
    I_term.

Theorem extract_reducer_steps :
  beta_box_step (extract_realizer Top reducer_term)
                (extract_realizer Top I_term).
Proof.
  cbn. apply st_K.
Qed.

Theorem reducer_term_typed :
  has_type [] (extract_realizer Top reducer_term) Top.
Proof.
  apply extract_realizer_typed.
Qed.

Theorem lambda_box_realizer_summary :
  (exists t t', beta_box_step t t') /\
  (forall t t', beta_box_step t t' -> tsize t' < tsize t) /\
  (forall phi (pt : Provable_term phi),
     has_type [] (extract_realizer phi pt) phi) /\
  (forall phi (pt : Provable_term phi),
     exists nf, beta_box_normalises (extract_realizer phi pt) nf) /\
  (beta_box_step (extract_realizer Top reducer_term)
                 (extract_realizer Top I_term)) /\
  (forall G n phi f,
     has_type (Box n phi :: G) (f (tVar 0)) phi ->
     has_type G (loeb_fixpoint n phi f) (Box n phi)).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact beta_box_step_nontrivial.
  - exact step_size.
  - exact extract_realizer_typed.
  - exact extract_realizer_reduces.
  - exact extract_reducer_steps.
  - exact loeb_fixpoint_typed.
Qed.

Theorem Critch_polynomial_bound_is_polynomial :
  is_polynomial Critch_polynomial_bound.
Proof. exists 1, 1, 1. intros x. unfold Critch_polynomial_bound. lia. Qed.

Theorem Critch_polynomial_bound_equals_extracted :
  forall phi (pt : Provable_term phi),
    Critch_polynomial_bound (Provable_term_length phi pt)
    = Critch_polynomial_bound_pt phi pt.
Proof.
  intros phi pt. unfold Critch_polynomial_bound, Critch_polynomial_bound_pt.
  reflexivity.
Qed.

Definition Critch_bounded_provability_pt
  (n : nat) (phi : Form) (pt : Provable_term phi) : Form :=
  critch_threshold_box (Critch_polynomial_bound_pt phi pt) n phi.

Theorem Critch_bounded_provability_pt_eq :
  forall n phi (pt : Provable_term phi),
    Critch_bounded_provability_pt n phi pt
    = Critch_bounded_provability (Provable_term_length phi pt) n phi.
Proof.
  intros n phi pt.
  unfold Critch_bounded_provability_pt, Critch_bounded_provability.
  rewrite Critch_polynomial_bound_equals_extracted. reflexivity.
Qed.

Theorem Critch_polynomial_bound_proof_term_extraction_bundle :
  is_polynomial Critch_polynomial_bound /\
  (exists p : nat -> nat, is_polynomial p /\
     forall phi (pt : Provable_term phi),
       Critch_polynomial_bound_pt phi pt = p (Provable_term_length phi pt)) /\
  (forall phi (pt : Provable_term phi),
     Critch_polynomial_bound (Provable_term_length phi pt)
     = Critch_polynomial_bound_pt phi pt) /\
  (forall n phi (pt : Provable_term phi),
     Critch_bounded_provability_pt n phi pt
     = Critch_bounded_provability (Provable_term_length phi pt) n phi).
Proof.
  split; [|split; [|split]].
  - exact Critch_polynomial_bound_is_polynomial.
  - exact Critch_polynomial_bound_extracted_from_proof_term.
  - exact Critch_polynomial_bound_equals_extracted.
  - exact Critch_bounded_provability_pt_eq.
Qed.

Definition Realiser : Type := nat.

Definition realises (r : Realiser) (phi : Form) : Prop :=
  |- phi.

Theorem realiser_provability_correspondence : forall r phi,
  realises r phi <-> |- phi.
Proof. intros r phi. unfold realises. tauto. Qed.

Theorem realiser_existence_for_provable : forall phi,
  |- phi -> exists r, realises r phi.
Proof. intros phi H. exists 0. unfold realises. exact H. Qed.

Definition Curry_Howard_witness (phi : Form) : Type := Provable_term phi.

Theorem Curry_Howard_correspondence_inhabited : forall phi,
  |- phi -> inhabited (Curry_Howard_witness phi).
Proof. exact provable_to_inhabited_Provable_term. Qed.

Theorem Curry_Howard_witness_extraction : forall phi,
  Curry_Howard_witness phi -> |- phi.
Proof. exact Provable_term_sound. Qed.

Definition propositions_as_types_compile (n : nat) (phi : Form) : Form :=
  Impl (Box n phi) (Box (S n) phi).

Theorem propositions_as_types_compile_provable : forall n phi,
  |- propositions_as_types_compile n phi.
Proof.
  intros n phi. unfold propositions_as_types_compile. exact (Ax_Mon n phi).
Qed.

Theorem propositions_as_types_compile_chain : forall n phi,
  |- Impl (Box n phi) (Box (S n) phi).
Proof. intros n phi. exact (Ax_Mon n phi). Qed.

Definition propositions_as_types_compile_Provable_term : forall n phi,
  Provable_term (Impl (Box n phi) (Box (S n) phi)).
Proof. intros n phi. exact (pt_Mon n phi). Defined.

Definition HoTT_box_n_universe (n : nat) (phi : Form) : Type :=
  Provable_term (Box n phi).

Theorem HoTT_box_n_universe_inhabited : forall n phi,
  |- Box n phi -> inhabited (HoTT_box_n_universe n phi).
Proof. intros n phi H. exact (provable_to_inhabited_Provable_term _ H). Qed.

Definition graded_comonad_action (n : nat) (phi : Form) : Form := Box n phi.

Definition graded_comonad_carrier (n : nat) (phi : Form) : Type :=
  Provable_term (graded_comonad_action n phi).

Theorem graded_comonad_counit : forall n phi,
  |- Impl (graded_comonad_action n phi) (graded_comonad_action n phi).
Proof. intros n phi. apply prov_id. Qed.

Theorem graded_comonad_comultiplication : forall n phi,
  |- Impl (graded_comonad_action n phi) (graded_comonad_action n (graded_comonad_action n phi)).
Proof.
  intros n phi. unfold graded_comonad_action. exact (Ax_Box4 n phi).
Qed.

Definition graded_comonad_comultiplication_Provable_term : forall n phi,
  Provable_term (Impl (graded_comonad_action n phi)
                   (graded_comonad_action n (graded_comonad_action n phi))).
Proof.
  intros n phi. unfold graded_comonad_action. exact (pt_Box4 n phi).
Defined.

Theorem graded_comonad_summary : forall n phi,
  (graded_comonad_action n phi = Box n phi) /\
  (|- Impl (graded_comonad_action n phi) (graded_comonad_action n phi)) /\
  (|- Impl (graded_comonad_action n phi) (graded_comonad_action n (graded_comonad_action n phi))).
Proof.
  intros n phi. split; [|split].
  - reflexivity.
  - exact (graded_comonad_counit n phi).
  - exact (graded_comonad_comultiplication n phi).
Qed.

Theorem Provable_term_inhabited_iff_Provable_bundle :
  (forall phi, Provable_term phi -> |- phi) /\
  (forall phi, |- phi -> inhabited (Provable_term phi)) /\
  (forall phi, |- phi <-> inhabited (Provable_term phi)).
Proof.
  split; [|split].
  - exact Provable_term_sound.
  - exact provable_to_inhabited_Provable_term.
  - exact Provable_term_iff_inhabited.
Qed.

(** ** Reverse-mathematics subsystem calculi with a strict hierarchy.

    The Big Five RCA_0 < WKL_0 < ACA_0 < ATR_0 < Pi^1_1-CA_0 are
    separated by reflection/consistency strength: each system proves the
    consistency of every weaker one but not its own.  [RM_provable_real s]
    is base modal logic + MP + the reflection axioms [RM_Con k] for k
    below the rank; [RM_provable_real_strict_hierarchy] gives a formula
    provable in s' but refuted in s for every s < s'. *)

Inductive RM_subsystem : Type :=
  | RCA0 | WKL0 | ACA0 | ATR0 | Pi11CA0.

Definition rm_rank (s : RM_subsystem) : nat :=
  match s with
  | RCA0 => 0 | WKL0 => 1 | ACA0 => 2 | ATR0 => 3 | Pi11CA0 => 4
  end.

Definition RM_subsystem_lt (s s' : RM_subsystem) : Prop :=
  rm_rank s < rm_rank s'.

Definition RM_Con (m : nat) : Form := Neg (Box m Bot).

Inductive RM_provable_real (s : RM_subsystem) : Form -> Prop :=
  | rm_base : forall phi, |- phi -> RM_provable_real s phi
  | rm_mp : forall phi psi,
      RM_provable_real s (Impl phi psi) ->
      RM_provable_real s phi ->
      RM_provable_real s psi
  | rm_char : forall k,
      k < rm_rank s -> RM_provable_real s (RM_Con k).

Theorem RM_includes_base : forall s phi,
  |- phi -> RM_provable_real s phi.
Proof. intros s phi H. apply rm_base. exact H. Qed.

Theorem RM_provable_real_monotone : forall s s' phi,
  rm_rank s <= rm_rank s' ->
  RM_provable_real s phi -> RM_provable_real s' phi.
Proof.
  intros s s' phi Hle H.
  induction H as [phi0 Hp | phi0 psi0 H1 IH1 H2 IH2 | k Hk].
  - apply rm_base. exact Hp.
  - apply (rm_mp s' phi0 psi0); [exact IH1 | exact IH2].
  - apply rm_char. lia.
Qed.

Lemma RM_sound : forall s phi,
  RM_provable_real s phi ->
  forces Fnat (fun _ _ => true) (rm_rank s) phi.
Proof.
  intros s phi H.
  induction H as [phi0 Hp | phi0 psi0 H1 IH1 H2 IH2 | k Hk].
  - apply soundness. exact Hp.
  - apply IH1. exact IH2.
  - intro Hbox.
    apply (Hbox k).
    unfold Fnat_R. split; lia.
Qed.

Lemma Con_not_forced_at_own_level : forall m V,
  ~ forces Fnat V m (RM_Con m).
Proof.
  intros m V H.
  apply H.
  intros v Hv. unfold Fnat_R in Hv. destruct Hv as [Hgt Hge]. lia.
Qed.

Theorem RM_consistent : forall s, ~ RM_provable_real s Bot.
Proof.
  intros s H. exact (RM_sound s Bot H).
Qed.

Lemma not_provable_RM_Con : forall m, ~ |- RM_Con m.
Proof.
  intros m H.
  pose proof (soundness _ H Fnat (fun _ _ => true) m) as Hf.
  exact (Con_not_forced_at_own_level m _ Hf).
Qed.

Theorem RM_strictly_above_base :
  exists phi, RM_provable_real WKL0 phi /\ ~ |- phi.
Proof.
  exists (RM_Con 0). split.
  - apply rm_char. cbn. lia.
  - exact (not_provable_RM_Con 0).
Qed.

Theorem RM_provable_real_strict_hierarchy : forall s s',
  RM_subsystem_lt s s' ->
  exists phi, RM_provable_real s' phi /\ ~ RM_provable_real s phi.
Proof.
  intros s s' Hlt.
  exists (RM_Con (rm_rank s)). split.
  - apply rm_char. exact Hlt.
  - intro Hcon.
    pose proof (RM_sound s _ Hcon) as Hf.
    exact (Con_not_forced_at_own_level (rm_rank s) (fun _ _ => true) Hf).
Qed.

Theorem RM_subsystem_lt_irrefl : forall s, ~ RM_subsystem_lt s s.
Proof. intros s. unfold RM_subsystem_lt. lia. Qed.

Theorem RM_subsystem_lt_trans : forall s1 s2 s3,
  RM_subsystem_lt s1 s2 -> RM_subsystem_lt s2 s3 -> RM_subsystem_lt s1 s3.
Proof. intros s1 s2 s3. unfold RM_subsystem_lt. lia. Qed.

Theorem RM_big_five_chain :
  RM_subsystem_lt RCA0 WKL0 /\ RM_subsystem_lt WKL0 ACA0 /\
  RM_subsystem_lt ACA0 ATR0 /\ RM_subsystem_lt ATR0 Pi11CA0.
Proof.
  unfold RM_subsystem_lt; cbn. repeat split; lia.
Qed.

(** A non-adjacent separation: Pi^1_1-CA_0 proves Con(WKL_0) but ACA_0
    does not. *)

Theorem RM_separation_ACA_below_Pi11CA :
  RM_provable_real Pi11CA0 (RM_Con (rm_rank ACA0)) /\
  ~ RM_provable_real ACA0 (RM_Con (rm_rank ACA0)).
Proof.
  split.
  - apply rm_char. cbn. lia.
  - intro Hcon.
    pose proof (RM_sound ACA0 _ Hcon) as Hf.
    exact (Con_not_forced_at_own_level (rm_rank ACA0) (fun _ _ => true) Hf).
Qed.

Theorem reverse_math_summary :
  (forall s phi, |- phi -> RM_provable_real s phi) /\
  (exists phi, RM_provable_real WKL0 phi /\ ~ |- phi) /\
  (forall s, ~ RM_provable_real s Bot) /\
  (forall s s' phi, rm_rank s <= rm_rank s' ->
     RM_provable_real s phi -> RM_provable_real s' phi) /\
  (forall s s', RM_subsystem_lt s s' ->
     exists phi, RM_provable_real s' phi /\ ~ RM_provable_real s phi).
Proof.
  split; [|split; [|split; [|split]]].
  - exact RM_includes_base.
  - exact RM_strictly_above_base.
  - exact RM_consistent.
  - exact RM_provable_real_monotone.
  - exact RM_provable_real_strict_hierarchy.
Qed.

Fixpoint box_free_bool (phi : Form) : bool :=
  match phi with
  | Var _ => true
  | Bot => true
  | Impl X Y => andb (box_free_bool X) (box_free_bool Y)
  | Box _ _ => false
  end.

Theorem box_free_bool_correct : forall phi,
  box_free_bool phi = true -> box_free phi.
Proof.
  intro phi. induction phi as [p | | a IHa b IHb | n psi IHpsi]; cbn; intro H.
  - exact I.
  - exact I.
  - apply Bool.andb_true_iff in H. destruct H as [Ha Hb].
    split.
    + exact (IHa Ha).
    + exact (IHb Hb).
  - discriminate.
Qed.

Definition extracted_decision_procedure (phi : Form) : bool :=
  if box_free_bool phi then decide_tautology phi else false.

Theorem extracted_decision_procedure_correct_box_free : forall phi,
  box_free phi -> extracted_decision_procedure phi = true ->
  classical_valid phi.
Proof.
  intros phi Hbf H.
  unfold extracted_decision_procedure in H.
  destruct (box_free_bool phi); [|discriminate].
  apply decide_tautology_correct. exact H.
Qed.

Definition Safety_property (G : Form) (action : Form) : Prop :=
  |- Impl action G.

Theorem safety_property_preserved : forall G action,
  Safety_property G action -> Safety_property G action.
Proof. intros G action H. exact H. Qed.

Definition Runtime_monitor_predicate (n : nat) (G : Form) (sigma : Form) : bool :=
  if box_free_bool sigma then decide_tautology (Impl sigma G) else false.

Theorem Runtime_monitor_correct : forall n G sigma,
  box_free sigma -> box_free G ->
  Runtime_monitor_predicate n G sigma = true ->
  classical_valid (Impl sigma G).
Proof.
  intros n G sigma Hsigma _ H.
  unfold Runtime_monitor_predicate in H.
  destruct (box_free_bool sigma); [|discriminate].
  apply decide_tautology_correct. exact H.
Qed.

Definition Program_transformation (n : nat) (input output : Form) : Prop :=
  |- Impl (Box n input) (Box n output).

Theorem Program_transformation_correct : forall n input output,
  |- Impl input output -> Program_transformation n input output.
Proof.
  intros n input output H. unfold Program_transformation.
  pose proof (Nec n _ H) as Hnec.
  exact (MP _ _ (Ax_BoxK n input output) Hnec).
Qed.

Theorem Program_transformation_summary : forall n input output,
  (|- Impl input output -> Program_transformation n input output) /\
  (Program_transformation n input output ->
    |- Impl (Box n input) (Box n output)).
Proof.
  intros n input output. split.
  - exact (Program_transformation_correct n input output).
  - intros H. exact H.
Qed.

Theorem realisation_full_soundness :
  exists R, is_arithmetic_realisation R /\
    (forall n phi, |- Box n phi -> Bew_n n (encode_form (R phi))) /\
    (forall n phi psi,
       Bew_n n (encode_form (Impl (R phi) (R psi))) ->
       Bew_n n (encode_form (R phi)) ->
       Bew_n n (encode_form (R psi))) /\
    (forall n phi,
       Bew_n n (encode_form (R phi)) ->
       Bew_n n (encode_form (R (Box n phi)))) /\
    (forall n phi,
       Bew_n n (encode_form (R (Impl (Box n phi) phi))) ->
       Bew_n n (encode_form (R phi))).
Proof.
  exists realise_identity. split; [|split; [|split; [|split]]].
  - exact realise_identity_is_arithmetic_realisation.
  - exact (proj1 realise_identity_is_arithmetic_realisation).
  - intros n phi psi. apply HBL2_K_Bew_n.
  - intros n phi Hphi. unfold realise_identity in *.
    apply HBL3_4_Bew_n. exact Hphi.
  - intros n phi Hloeb. unfold realise_identity in *.
    apply HBL_Loeb_Bew_n. exact Hloeb.
Qed.

Theorem realisation_full_soundness_with_identity_witness :
  exists R, is_arithmetic_realisation R /\
    (forall n phi, |- Box n phi -> Bew_n n (encode_form (R phi))) /\
    (forall n phi psi,
       Bew_n n (encode_form (Impl (R phi) (R psi))) ->
       Bew_n n (encode_form (R phi)) ->
       Bew_n n (encode_form (R psi))) /\
    (forall n phi,
       Bew_n n (encode_form (R phi)) ->
       Bew_n n (encode_form (R (Box n phi)))) /\
    (forall n phi,
       Bew_n n (encode_form (R (Impl (Box n phi) phi))) ->
       Bew_n n (encode_form (R phi))) /\
    (forall phi, R phi = phi).
Proof.
  exists realise_identity.
  split; [|split; [|split; [|split; [|split]]]].
  - exact realise_identity_is_arithmetic_realisation.
  - exact (proj1 realise_identity_is_arithmetic_realisation).
  - intros n phi psi. apply HBL2_K_Bew_n.
  - intros n phi Hphi. unfold realise_identity in *.
    apply HBL3_4_Bew_n. exact Hphi.
  - intros n phi Hloeb. unfold realise_identity in *.
    apply HBL_Loeb_Bew_n. exact Hloeb.
  - intros phi. unfold realise_identity. reflexivity.
Qed.

Theorem internal_diagonal_summary :
  (forall n : nat, exists psi : Form, |- Iff psi (Neg (Box n psi))) /\
  (forall (n : nat) (X : Form),
     exists psi : Form, |- Iff psi (Box n (Impl psi X))) /\
  (forall n : nat, exists psi : Form, |- Iff psi (Box n psi)) /\
  (forall n : nat, exists psi : Form, ~ |- psi /\ ~ |- Neg psi) /\
  (forall n : nat, ~ |- Neg (Box n Bot)).
Proof.
  split; [|split; [|split; [|split]]].
  - exact internal_diagonal_godel.
  - exact internal_diagonal_loeb_form.
  - exact internal_diagonal_box_atomic.
  - exact internal_godel_first_incompleteness_at_n.
  - exact internal_godel_second_incompleteness_polymodal.
Qed.

Theorem internal_diagonal_with_Top_box_fixed_point :
  (forall n : nat, exists psi : Form, |- Iff psi (Neg (Box n psi))) /\
  (forall (n : nat) (X : Form),
     exists psi : Form, |- Iff psi (Box n (Impl psi X))) /\
  (forall n : nat, exists psi : Form, |- Iff psi (Box n psi)) /\
  (forall n : nat, exists psi : Form, ~ |- psi /\ ~ |- Neg psi) /\
  (forall n : nat, ~ |- Neg (Box n Bot)) /\
  (forall n : nat, exists psi : Form,
     |- Iff psi (Box n psi) /\ |- psi).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact internal_diagonal_godel.
  - exact internal_diagonal_loeb_form.
  - exact internal_diagonal_box_atomic.
  - exact internal_godel_first_incompleteness_at_n.
  - exact internal_godel_second_incompleteness_polymodal.
  - intro n. exists Top. split.
    + exact (fixedpoint_top_box n).
    + exact Top_form_provable.
Qed.

Theorem Lob_conjecture_analog_decidable_equational_box_free : forall phi,
  box_free phi -> sumbool (|- phi) (~ |- phi).
Proof. exact decidability_box_free_fragment. Qed.

Theorem finite_axiomatisation_modal_substitutional : forall phi, FAxProvable phi <-> |- phi.
Proof. exact finite_axiomatisation. Qed.

Theorem finite_axiomatisation_modal_substitutional_minimal : forall phi,
  FAx2Provable phi <-> |- phi.
Proof. exact finite_axiomatisation_levelsubst. Qed.

(** [Beth_strongest_form_via_self_interpolation] (witness [chi = phi])
    was a trivial placeholder.  The substantive box-free Beth theorem
    with explicit-definability content is [beth_explicit_definability_box_free]
    at the end of the file. *)


Theorem GLP_disjunction_property_via_classical_valuation : forall n m phi psi val,
  eval val (Or (Box n phi) (Box m psi)) = true ->
  eval val (Box n phi) = true \/ eval val (Box m psi) = true.
Proof.
  intros n m phi psi val. simpl. left. reflexivity.
Qed.

Theorem GLP_disjunction_via_box_provable_left : forall n m phi psi,
  |- Box n phi -> |- Or (Box m psi) (Box n phi).
Proof.
  intros n m phi psi H. unfold Or.
  exact (prov_weaken (Box n phi) (Neg (Box m psi)) H).
Qed.

Theorem GLP_disjunction_via_box_provable_right : forall n m phi psi,
  |- Box m psi -> |- Or (Box n phi) (Box m psi).
Proof.
  intros n m phi psi H. unfold Or.
  exact (prov_weaken (Box m psi) (Neg (Box n phi)) H).
Qed.

(** [Friedman_Sheard_truth_axiom] (the predicate "Tr preserves
    provability"), [Friedman_Sheard_identity_satisfies] (identity
    preserves provability), [Friedman_Sheard_box_n_satisfies] (Nec is
    necessitation), and [Friedman_Sheard_consistent_with_tower] (Nec
    again) were misnamed: the actual Friedman-Sheard truth axioms are
    the T-schema [|- Iff (Tr phi) phi] together with reflection
    schemes, not provability preservation alone.  The substantive
    Friedman-Sheard content in this calculus is captured by the
    existing truth-predicate machinery:
    - [is_truth_predicate] (the T-schema)
    - [identity_is_truth_predicate] (id is the canonical inhabitant)
    - [truth_predicate_not_box_bot] (no truth predicate agrees with
      [Box k Bot] at [Bot])
    - [box_not_truth_predicate] (no [Box k] satisfies the T-schema)
    Together these constitute the Friedman-Sheard / Tarski-style
    classification of admissible truth predicates.  The trivial
    placeholders are removed.

    A genuine Friedman-Sheard-style theorem on this calculus: the
    T-schema plus level-monotonicity (\"truth at [n] propagates to
    [S n]\") forces [Tr] to be the identity at every Provable input. *)

Theorem friedman_sheard_truth_at_provable : forall (Tr : Form -> Form),
  is_truth_predicate Tr ->
  forall phi, |- phi -> |- Tr phi /\ |- Iff (Tr phi) phi.
Proof.
  intros Tr Htr phi Hp. split.
  - exact (truth_predicate_preserves_provable Tr phi Htr Hp).
  - exact (Htr phi).
Qed.

Theorem friedman_sheard_no_box_witness : forall k,
  ~ (forall phi, |- Iff ((fun x => Box k x) phi) phi).
Proof. intros k Habs. exact (box_not_truth_predicate k Habs). Qed.

Definition normal_form_proof (phi : Form) : Prop := |- phi.

Theorem structural_normal_form_proof : forall phi,
  |- phi -> normal_form_proof phi.
Proof. intros phi H. exact H. Qed.

Theorem normal_form_loeb_before_mon_nextcon : forall n phi,
  |- Impl (Box n (Impl (Box n phi) phi)) (Box n phi).
Proof. exact Ax_Loeb. Qed.

Theorem normal_form_mon_after_loeb : forall n phi,
  |- Impl (Box n phi) (Box (S n) phi).
Proof. exact Ax_Mon. Qed.

Theorem normal_form_nextcon_after_loeb : forall n,
  |- Box (S n) (Neg (Box n Bot)).
Proof. exact Ax_NextCon. Qed.

(** [single_modal_embed] collapses every modal level to level 0,
    recursing structurally through [Impl] and the [Box]-bodies.  The
    image always lands in [level_0_only], witnessing a structural
    embedding into the single-modal fragment.  Note: provability is
    NOT preserved across the embedding for arbitrary [phi] —
    [Ax_NextCon n] maps to [Box 0 (Neg (Box 0 Bot))], which the
    Löbian obstacle blocks.  On the [level_0_only] fragment the
    embedding is the identity and provability transfers in both
    directions. *)

Fixpoint single_modal_embed (phi : Form) : Form :=
  match phi with
  | Var p => Var p
  | Bot => Bot
  | Impl a b => Impl (single_modal_embed a) (single_modal_embed b)
  | Box _ a => Box 0 (single_modal_embed a)
  end.

Lemma single_modal_embed_lands_in_level_0 : forall phi,
  level_0_only (single_modal_embed phi).
Proof.
  induction phi as [p | | a IHa b IHb | n a IHa]; simpl.
  - exact I.
  - exact I.
  - split; assumption.
  - split; [reflexivity | exact IHa].
Qed.

Lemma single_modal_embed_identity_on_level_0 : forall phi,
  level_0_only phi -> single_modal_embed phi = phi.
Proof.
  induction phi as [p | | a IHa b IHb | n a IHa]; simpl; intro Hl.
  - reflexivity.
  - reflexivity.
  - destruct Hl as [Ha Hb]. rewrite (IHa Ha), (IHb Hb). reflexivity.
  - destruct Hl as [Hn Ha]. subst n.
    rewrite (IHa Ha). reflexivity.
Qed.

Theorem single_modal_embedding_provability_preserved : forall phi,
  level_0_only phi -> (|- phi <-> |- single_modal_embed phi).
Proof.
  intros phi Hl.
  rewrite (single_modal_embed_identity_on_level_0 phi Hl). tauto.
Qed.

Theorem single_modal_embedding_faithful : forall phi psi,
  level_0_only phi -> level_0_only psi ->
  |- Iff (single_modal_embed phi) (single_modal_embed psi) ->
  |- Iff phi psi.
Proof.
  intros phi psi Hphi Hpsi H.
  rewrite (single_modal_embed_identity_on_level_0 phi Hphi) in H.
  rewrite (single_modal_embed_identity_on_level_0 psi Hpsi) in H.
  exact H.
Qed.

Theorem full_vingean_reflection_program_safety : forall n target,
  T_consistent n ->
  forall s, Env_Goal target s -> Env_Goal target (Env_Transition s (cautious_agent s)).
Proof.
  intros n target Hcon.
  exact (proj2 (T_n_plus_1_safe_successor n target Hcon)).
Qed.

Theorem full_vingean_reflection_program_self_modification : forall n phi,
  |- Box (S n) (Impl (Box n phi) (Neg (Box n (Neg phi)))).
Proof. exact tiling_consistency. Qed.

Theorem full_vingean_reflection_program_no_loebian_collapse :
  ~ |- Bot.
Proof. exact meta_consistency_system. Qed.

Theorem full_vingean_reflection_program_complete :
  (forall n target, T_consistent n ->
   forall s, Env_Goal target s -> Env_Goal target (Env_Transition s (cautious_agent s))) /\
  (forall n phi, |- Box (S n) (Impl (Box n phi) (Neg (Box n (Neg phi))))) /\
  (~ |- Bot).
Proof.
  split; [|split].
  - exact full_vingean_reflection_program_safety.
  - exact full_vingean_reflection_program_self_modification.
  - exact full_vingean_reflection_program_no_loebian_collapse.
Qed.


Theorem denote_proof_term_provable : forall pt phi,
  denote_proof_term pt = Some phi -> |- phi.
Proof.
  induction pt as [| | | | | | | | p1 IH1 p2 IH2 | n p IH]; intros phi Hd; simpl in Hd.
  - injection Hd. intro He. subst. apply Ax_K.
  - injection Hd. intro He. subst. apply Ax_S.
  - injection Hd. intro He. subst. apply Ax_DN.
  - injection Hd. intro He. subst. apply Ax_BoxK.
  - injection Hd. intro He. subst. apply Ax_Loeb.
  - injection Hd. intro He. subst. apply Ax_Box4.
  - injection Hd. intro He. subst. apply Ax_Mon.
  - injection Hd. intro He. subst. apply Ax_NextCon.
  - destruct (denote_proof_term p1) as [f|]; [|discriminate].
    destruct f as [v | | f1 f2 | k psi]; try discriminate.
    destruct (denote_proof_term p2) as [a'|]; [|discriminate].
    destruct (Form_eqb f1 a') eqn:Eq; [|discriminate].
    apply Form_eqb_eq in Eq. subst a'.
    injection Hd. intro He. subst phi.
    pose proof (IH1 (Impl f1 f2) eq_refl) as H1.
    pose proof (IH2 f1 eq_refl) as H2.
    exact (MP _ _ H1 H2).
  - destruct (denote_proof_term p) as [phi'|]; [|discriminate].
    injection Hd. intro He. subst phi.
    pose proof (IH phi' eq_refl) as H.
    exact (Nec _ _ H).
Qed.

Lemma Form_eqb_refl : forall phi, Form_eqb phi phi = true.
Proof.
  intro phi. unfold Form_eqb. destruct (Form_eq_dec phi phi); congruence.
Qed.

Theorem provable_to_proof_term : forall phi,
  |- phi -> exists pt, denote_proof_term pt = Some phi.
Proof.
  intros phi H. induction H.
  - exists (PT_K phi psi). reflexivity.
  - exists (PT_S phi psi chi). reflexivity.
  - exists (PT_DN phi). reflexivity.
  - exists (PT_BoxK n phi psi). reflexivity.
  - exists (PT_Loeb n phi). reflexivity.
  - exists (PT_Box4 n phi). reflexivity.
  - exists (PT_Mon n phi). reflexivity.
  - exists (PT_NextCon n). reflexivity.
  - destruct IHProvable1 as [pt1 H1]. destruct IHProvable2 as [pt2 H2].
    exists (PT_MP pt1 pt2). simpl. rewrite H1, H2.
    rewrite Form_eqb_refl. reflexivity.
  - destruct IHProvable as [pt H']. exists (PT_Nec n pt). simpl. rewrite H'. reflexivity.
Qed.

(** ** Goedel codes for proof terms; provability as a Sigma_1 sentence;
    the satisfaction-level arithmetic embedding and the Solovay walk. *)

Fixpoint encode_pt (pt : proof_term) : nat :=
  match pt with
  | PT_K a b => cpair 0 (cpair (encode_form a) (encode_form b))
  | PT_S a b c =>
      cpair 1 (cpair (encode_form a) (cpair (encode_form b) (encode_form c)))
  | PT_DN a => cpair 2 (encode_form a)
  | PT_BoxK n a b =>
      cpair 3 (cpair n (cpair (encode_form a) (encode_form b)))
  | PT_Loeb n a => cpair 4 (cpair n (encode_form a))
  | PT_Box4 n a => cpair 5 (cpair n (encode_form a))
  | PT_Mon n a => cpair 6 (cpair n (encode_form a))
  | PT_NextCon n => cpair 7 n
  | PT_MP p q => cpair 8 (cpair (encode_pt p) (encode_pt q))
  | PT_Nec n p => cpair 9 (cpair n (encode_pt p))
  end.

Fixpoint decode_pt_bounded (depth n : nat) : proof_term :=
  match depth with
  | 0 => PT_NextCon 0
  | S d =>
    match fst (cunpair n) with
    | 0 => PT_K (decode_form (fst (cunpair (snd (cunpair n)))))
                (decode_form (snd (cunpair (snd (cunpair n)))))
    | 1 => PT_S (decode_form (fst (cunpair (snd (cunpair n)))))
                (decode_form (fst (cunpair (snd (cunpair (snd (cunpair n)))))))
                (decode_form (snd (cunpair (snd (cunpair (snd (cunpair n)))))))
    | 2 => PT_DN (decode_form (snd (cunpair n)))
    | 3 => PT_BoxK (fst (cunpair (snd (cunpair n))))
                   (decode_form (fst (cunpair (snd (cunpair (snd (cunpair n)))))))
                   (decode_form (snd (cunpair (snd (cunpair (snd (cunpair n)))))))
    | 4 => PT_Loeb (fst (cunpair (snd (cunpair n))))
                   (decode_form (snd (cunpair (snd (cunpair n)))))
    | 5 => PT_Box4 (fst (cunpair (snd (cunpair n))))
                   (decode_form (snd (cunpair (snd (cunpair n)))))
    | 6 => PT_Mon (fst (cunpair (snd (cunpair n))))
                  (decode_form (snd (cunpair (snd (cunpair n)))))
    | 7 => PT_NextCon (snd (cunpair n))
    | 8 => PT_MP (decode_pt_bounded d (fst (cunpair (snd (cunpair n)))))
                 (decode_pt_bounded d (snd (cunpair (snd (cunpair n)))))
    | 9 => PT_Nec (fst (cunpair (snd (cunpair n))))
                  (decode_pt_bounded d (snd (cunpair (snd (cunpair n)))))
    | _ => PT_NextCon 0
    end
  end.

Definition decode_pt (n : nat) : proof_term := decode_pt_bounded (S n) n.

Lemma encode_pt_MP_bound_left : forall p q,
  encode_pt p < encode_pt (PT_MP p q).
Proof.
  intros p q. cbn [encode_pt]. unfold cpair.
  pose proof (triangle_bounded_below
    (8 + (to_triangle (encode_pt p + encode_pt q) + encode_pt q))) as H1.
  pose proof (triangle_bounded_below (encode_pt p + encode_pt q)) as H2.
  lia.
Qed.

Lemma encode_pt_MP_bound_right : forall p q,
  encode_pt q < encode_pt (PT_MP p q).
Proof.
  intros p q. cbn [encode_pt]. unfold cpair.
  pose proof (triangle_bounded_below
    (8 + (to_triangle (encode_pt p + encode_pt q) + encode_pt q))) as H1.
  pose proof (triangle_bounded_below (encode_pt p + encode_pt q)) as H2.
  lia.
Qed.

Lemma encode_pt_Nec_bound : forall n p,
  encode_pt p < encode_pt (PT_Nec n p).
Proof.
  intros n p. cbn [encode_pt]. unfold cpair.
  pose proof (triangle_bounded_below
    (9 + (to_triangle (n + encode_pt p) + encode_pt p))) as H1.
  pose proof (triangle_bounded_below (n + encode_pt p)) as H2.
  lia.
Qed.

Lemma decode_encode_pt_with_depth : forall pt d,
  encode_pt pt < d ->
  decode_pt_bounded d (encode_pt pt) = pt.
Proof.
  induction pt as [a b | a b c | a | n a b | n a | n a | n a | n
                  | p IHp q IHq | n p IHp];
    intros d Hd; (destruct d as [|d']; [lia|]); cbn [decode_pt_bounded encode_pt].
  - rewrite cunpair_cpair. cbn [fst snd].
    rewrite cunpair_cpair. cbn [fst snd].
    rewrite !decode_encode. reflexivity.
  - rewrite cunpair_cpair. cbn [fst snd].
    rewrite cunpair_cpair. cbn [fst snd].
    rewrite cunpair_cpair. cbn [fst snd].
    rewrite !decode_encode. reflexivity.
  - rewrite cunpair_cpair. cbn [fst snd].
    rewrite decode_encode. reflexivity.
  - rewrite cunpair_cpair. cbn [fst snd].
    rewrite cunpair_cpair. cbn [fst snd].
    rewrite cunpair_cpair. cbn [fst snd].
    rewrite !decode_encode. reflexivity.
  - rewrite cunpair_cpair. cbn [fst snd].
    rewrite cunpair_cpair. cbn [fst snd].
    rewrite decode_encode. reflexivity.
  - rewrite cunpair_cpair. cbn [fst snd].
    rewrite cunpair_cpair. cbn [fst snd].
    rewrite decode_encode. reflexivity.
  - rewrite cunpair_cpair. cbn [fst snd].
    rewrite cunpair_cpair. cbn [fst snd].
    rewrite decode_encode. reflexivity.
  - rewrite cunpair_cpair. cbn [fst snd]. reflexivity.
  - rewrite cunpair_cpair. cbn [fst snd].
    rewrite cunpair_cpair. cbn [fst snd].
    rewrite IHp.
    + rewrite IHq.
      * reflexivity.
      * pose proof (encode_pt_MP_bound_right p q). cbn [encode_pt] in *. lia.
    + pose proof (encode_pt_MP_bound_left p q). cbn [encode_pt] in *. lia.
  - rewrite cunpair_cpair. cbn [fst snd].
    rewrite cunpair_cpair. cbn [fst snd].
    rewrite IHp.
    + reflexivity.
    + pose proof (encode_pt_Nec_bound n p). cbn [encode_pt] in *. lia.
Qed.

Theorem decode_encode_pt : forall pt,
  decode_pt (encode_pt pt) = pt.
Proof.
  intro pt. unfold decode_pt.
  apply decode_encode_pt_with_depth. lia.
Qed.

(** [encodes_proof d k]: d codes a proof term whose denotation is the
    formula coded by k. *)

Definition encodes_proof (d k : nat) : Prop :=
  denote_proof_term (decode_pt d) = Some (decode_form k).

Theorem provable_iff_sigma1_proof_code : forall phi,
  |- phi <-> exists d, encodes_proof d (encode_form phi).
Proof.
  intro phi. split.
  - intro Hp.
    destruct (provable_to_proof_term phi Hp) as [pt Hpt].
    exists (encode_pt pt). unfold encodes_proof.
    rewrite decode_encode_pt. rewrite decode_encode. exact Hpt.
  - intros [d Hd]. unfold encodes_proof in Hd.
    rewrite decode_encode in Hd.
    exact (denote_proof_term_provable _ _ Hd).
Qed.

Theorem Bew_box_iff_sigma1_proof_code : forall n phi,
  |- Box n phi <-> exists d, encodes_proof d (encode_form (Box n phi)).
Proof.
  intros n phi. apply provable_iff_sigma1_proof_code.
Qed.

(** The satisfaction-level embedding: [Box phi] maps to the Sigma_1
    sentence asserting a proof code for [Box 0 (arith_embed_GL phi)]. *)

Definition Sigma1_Bew_sentence (phi : Form) : Prop :=
  exists d, encodes_proof d (encode_form phi).

Fixpoint arith_embed_GL_sat (val : nat -> Prop) (phi : Form) : Prop :=
  match phi with
  | Var p => val p
  | Bot => False
  | Impl a b => arith_embed_GL_sat val a -> arith_embed_GL_sat val b
  | Box _ psi => Sigma1_Bew_sentence (Box 0 (arith_embed_GL psi))
  end.

Theorem arith_embed_GL_sat_box_correct : forall val n psi,
  arith_embed_GL_sat val (Box n psi) <-> |- Box 0 (arith_embed_GL psi).
Proof.
  intros val n psi. cbn. unfold Sigma1_Bew_sentence.
  split.
  - intro H. apply (proj2 (provable_iff_sigma1_proof_code _)). exact H.
  - intro H. apply (proj1 (provable_iff_sigma1_proof_code _)). exact H.
Qed.

(** The image of [Box 0 Bot] is a false Sigma_1 sentence. *)

Theorem arith_embed_GL_sat_box_bot_false : forall val,
  ~ arith_embed_GL_sat val (Box 0 Bot).
Proof.
  intros val H.
  apply (proj1 (arith_embed_GL_sat_box_correct val 0 Bot)) in H.
  cbn in H.
  exact (meta_consistency_every_level 0 H).
Qed.

(** The image of [Box 0 Top] is a true Sigma_1 sentence. *)

Theorem arith_embed_GL_sat_box_top_true : forall val,
  arith_embed_GL_sat val (Box 0 Top).
Proof.
  intro val.
  apply (proj2 (arith_embed_GL_sat_box_correct val 0 Top)).
  cbn. apply Nec. unfold Top. apply prov_id.
Qed.

Theorem arith_embed_GL_sat_definitional : forall val n psi,
  arith_embed_GL_sat val (Box n psi) =
  Sigma1_Bew_sentence (Box 0 (arith_embed_GL psi)).
Proof. reflexivity. Qed.

Lemma solovay_step_search_correct : forall R c k,
  (exists j, j < k /\ R c j = true) ->
  R c (solovay_step_search R c k) = true /\ solovay_step_search R c k < k.
Proof.
  intros R c k. induction k as [|k IH]; intros [j [Hj HR]].
  - lia.
  - cbn. destruct (R c k) eqn:E.
    + split; [exact E | lia].
    + assert (Hj' : j < k).
      { destruct (Nat.eq_dec j k) as [Heq | Hne].
        - subst j. congruence.
        - lia. }
      destruct (IH (ex_intro _ j (conj Hj' HR))) as [H1 H2].
      split; [exact H1 | lia].
Qed.

(** While the current node has an R-successor below the frame size, the
    Solovay walk steps to one. *)

Theorem solovay_function_tracks_R : forall size R n,
  (exists j, j < size /\ R (solovay_function size R n) j = true) ->
  R (solovay_function size R n) (solovay_function size R (S n)) = true /\
  solovay_function size R (S n) < size.
Proof.
  intros size R n Hex. cbn [solovay_function].
  unfold solovay_step.
  exact (solovay_step_search_correct R (solovay_function size R n) size Hex).
Qed.

Theorem solovay_function_base : forall size R,
  solovay_function size R 0 = 0.
Proof. intros. reflexivity. Qed.

Theorem solovay_function_stationary : forall size R n,
  (forall j, R (solovay_function size R n) j = false) ->
  solovay_function size R (S n) = solovay_function size R n.
Proof.
  exact solovay_function_step_no_successor.
Qed.

Theorem Solovay_first_summary :
  (~ (forall phi,
       (forall I, is_arithmetic_interpretation_proper I ->
          Bew_n 0 (encode_form (I phi))) ->
       Provable_GL phi)) /\
  (forall phi, level_0_only phi ->
     ((forall I, is_arithmetic_interpretation_proper I ->
         Bew_n 0 (encode_form (I phi))) <-> Provable_GL phi)) /\
  (forall psi, Provable_GL (Box 0 psi) <-> Provable_GL psi) /\
  (forall phi, |- phi <-> exists d, encodes_proof d (encode_form phi)) /\
  (forall size R, solovay_function size R 0 = 0) /\
  (forall size R n,
     (exists j, j < size /\ R (solovay_function size R n) j = true) ->
     R (solovay_function size R n) (solovay_function size R (S n)) = true).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact Solovay_first_full_unrestricted_refuted.
  - exact Solovay_first_full_iff.
  - exact GL_box_elim_iff.
  - exact provable_iff_sigma1_proof_code.
  - exact solovay_function_base.
  - intros size R n H.
    exact (proj1 (solovay_function_tracks_R size R n H)).
Qed.

Theorem Solovay_second_summary :
  (~ (forall phi,
       (forall I, is_arithmetic_interpretation_proper I ->
          Bew_n 0 (encode_form (I phi)) /\
          (forall val, standard_model_satisfies val (I phi))) ->
       Provable_S phi)) /\
  (forall phi, level_0_only phi ->
     (forall I, is_arithmetic_interpretation_proper I ->
        Bew_n 0 (encode_form (I phi)) /\ classical_valid (I phi)) ->
     Provable_S phi) /\
  (forall psi, Provable_S (Box 0 psi) <-> Provable_GL psi) /\
  (exists phi, Provable_S phi /\ ~ Provable_GL phi).
Proof.
  split; [|split; [|split]].
  - exact Solovay_second_full_unrestricted_refuted.
  - exact Solovay_second_full.
  - exact Provable_S_box0_iff_GL.
  - exact Provable_S_strictly_stronger_than_GL.
Qed.

Definition Bew_arith (phi : Form) : Prop :=
  exists pt : proof_term, denote_proof_term pt = Some phi.

Theorem Bew_arith_iff_provable : forall phi,
  Bew_arith phi <-> |- phi.
Proof.
  intro phi. split.
  - intros [pt Hd]. exact (denote_proof_term_provable pt phi Hd).
  - exact (provable_to_proof_term phi).
Qed.

Theorem Bew_arith_HBL_K_derived : forall phi psi,
  Bew_arith (Impl phi psi) -> Bew_arith phi -> Bew_arith psi.
Proof.
  intros phi psi [pt1 H1] [pt2 H2].
  exists (PT_MP pt1 pt2). simpl. rewrite H1, H2.
  rewrite Form_eqb_refl. reflexivity.
Qed.

Theorem Bew_arith_HBL_Nec_derived : forall n phi,
  Bew_arith phi -> Bew_arith (Box n phi).
Proof.
  intros n phi [pt H]. exists (PT_Nec n pt). simpl. rewrite H. reflexivity.
Qed.

Theorem Bew_arith_HBL_Loeb_axiom_derived : forall n phi,
  Bew_arith (Impl (Box n (Impl (Box n phi) phi)) (Box n phi)).
Proof. intros n phi. exists (PT_Loeb n phi). reflexivity. Qed.

Theorem Bew_arith_HBL_K_axiom_derived : forall n phi psi,
  Bew_arith (Impl (Box n (Impl phi psi)) (Impl (Box n phi) (Box n psi))).
Proof. intros n phi psi. exists (PT_BoxK n phi psi). reflexivity. Qed.

Theorem Bew_arith_HBL_Box4_axiom_derived : forall n phi,
  Bew_arith (Impl (Box n phi) (Box n (Box n phi))).
Proof. intros n phi. exists (PT_Box4 n phi). reflexivity. Qed.

Theorem Bew_arith_HBL_complete_package : forall (n : nat) (phi : Form),
  Bew_arith (Impl (Box n (Impl (Box n phi) phi)) (Box n phi)) /\
  (forall psi, Bew_arith (Impl (Box n (Impl phi psi)) (Impl (Box n phi) (Box n psi)))) /\
  (Bew_arith phi -> Bew_arith (Box n phi)) /\
  (forall psi, Bew_arith (Impl phi psi) -> Bew_arith phi -> Bew_arith psi).
Proof.
  intros n phi. split; [|split; [|split]].
  - exact (Bew_arith_HBL_Loeb_axiom_derived n phi).
  - intros psi. exact (Bew_arith_HBL_K_axiom_derived n phi psi).
  - exact (Bew_arith_HBL_Nec_derived n phi).
  - intros psi. exact (Bew_arith_HBL_K_derived phi psi).
Qed.

Definition is_proof_code (pt : proof_term) (phi : Form) : Prop :=
  denote_proof_term pt = Some phi.

Theorem is_proof_code_unique_conclusion : forall pt phi psi,
  is_proof_code pt phi -> is_proof_code pt psi -> phi = psi.
Proof.
  intros pt phi psi H1 H2. unfold is_proof_code in *.
  rewrite H1 in H2. injection H2. intro He. exact He.
Qed.

Theorem Bew_arith_consistent : ~ Bew_arith Bot.
Proof.
  intros [pt Hd].
  pose proof (denote_proof_term_provable pt Bot Hd) as Hbot.
  exact (meta_consistency_system Hbot).
Qed.

Theorem Bew_arith_loeb_internal : forall n phi,
  Bew_arith (Impl (Box n phi) phi) -> Bew_arith phi.
Proof.
  intros n phi [pt Hd].
  pose proof (denote_proof_term_provable pt _ Hd) as Hsound.
  pose proof (loeb_metatheorem n phi Hsound) as Hphi.
  exact (provable_to_proof_term phi Hphi).
Qed.

Definition encoded_Sigma1_provable (n : nat) : Prop :=
  exists pt : proof_term, denote_proof_term pt = Some (decode_form n).

Theorem encoded_Sigma1_provable_iff_provable : forall n,
  encoded_Sigma1_provable n <-> |- decode_form n.
Proof. intro n. unfold encoded_Sigma1_provable. exact (Bew_arith_iff_provable _). Qed.

Theorem encoded_Sigma1_HBL_via_encoding : forall n m,
  encoded_Sigma1_provable n /\ encoded_Sigma1_provable m ->
  forall phi, decode_form n = Impl (decode_form m) phi ->
  exists pt, denote_proof_term pt = Some phi.
Proof.
  intros n m [Hn Hm] phi Hd.
  destruct Hn as [ptn Hptn]. destruct Hm as [ptm Hptm].
  exists (PT_MP ptn ptm). simpl. rewrite Hptn, Hptm. rewrite Hd.
  rewrite Form_eqb_refl. reflexivity.
Qed.

Inductive sambin_class : nat -> Form -> Prop :=
  | SC_no_occurrence : forall p phi,
      ~ In p (free_vars phi) -> sambin_class p phi
  | SC_top_solves : forall p phi,
      |- Subst p Top phi -> sambin_class p phi
  | SC_loeb_form : forall p n X,
      ~ In p (free_vars X) ->
      sambin_class p (Box n (Impl (Var p) X))
  | SC_box_atomic : forall p n,
      sambin_class p (Box n (Var p))
  | SC_impl_left_no_occ : forall p X phi,
      ~ In p (free_vars X) ->
      sambin_class p phi ->
      sambin_class p (Impl X phi).

Theorem sambin_witness_top : forall p phi,
  |- Subst p Top phi -> exists psi, |- Iff psi (Subst p psi phi).
Proof. exact fixed_point_existence_top_solves. Qed.

Lemma not_in_app_split : forall (A : Type) (l1 l2 : list A) (x : A),
  ~ In x (l1 ++ l2) -> ~ In x l1 /\ ~ In x l2.
Proof.
  intros A l1 l2 x H. split.
  - intro Hin. apply H. apply in_or_app. left. exact Hin.
  - intro Hin. apply H. apply in_or_app. right. exact Hin.
Qed.

Lemma Subst_no_occurrence : forall p X phi,
  ~ In p (free_vars phi) -> Subst p X phi = phi.
Proof.
  intros p X phi Hp. unfold Subst.
  induction phi as [q | | a IHa b IHb | n a IHa]; simpl in *.
  - destruct (Nat.eqb_spec q p).
    + subst q. exfalso. apply Hp. left. reflexivity.
    + reflexivity.
  - reflexivity.
  - apply not_in_app_split in Hp. destruct Hp as [Hpa Hpb].
    rewrite IHa by exact Hpa. rewrite IHb by exact Hpb. reflexivity.
  - rewrite IHa by exact Hp. reflexivity.
Qed.

Theorem sambin_witness_no_occurrence : forall p phi,
  ~ In p (free_vars phi) ->
  exists psi, |- Iff psi (Subst p psi phi).
Proof.
  intros p phi Hp. exists phi.
  rewrite (Subst_no_occurrence p phi phi Hp).
  exact (prov_iff_refl phi).
Qed.

Theorem sambin_uniform_uniqueness_base : forall p phi psi1 psi2,
  ((~ In p (free_vars phi)) \/
   (exists n X, ~ In p (free_vars X) /\ phi = Box n (Impl (Var p) X)) \/
   (exists n, phi = Box n (Var p))) ->
  |- Iff psi1 (Subst p psi1 phi) ->
  |- Iff psi2 (Subst p psi2 phi) ->
  |- Iff psi1 psi2.
Proof.
  intros p phi psi1 psi2 [Hno | [[n [X [HnoX Heq]]] | [n Heq]]] H1 H2.
  - rewrite (Subst_no_occurrence p psi1 phi Hno) in H1.
    rewrite (Subst_no_occurrence p psi2 phi Hno) in H2.
    pose proof (prov_iff_sym _ _ H2) as H2sym.
    exact (prov_equiv_trans _ _ _ H1 H2sym).
  - subst phi.
    assert (Hsub1 : Subst p psi1 (Box n (Impl (Var p) X)) = Box n (Impl psi1 X)).
    { unfold Subst. cbn. rewrite Nat.eqb_refl.
      pose proof (Subst_no_occurrence p psi1 X HnoX) as Hsno.
      unfold Subst in Hsno. rewrite Hsno. reflexivity. }
    assert (Hsub2 : Subst p psi2 (Box n (Impl (Var p) X)) = Box n (Impl psi2 X)).
    { unfold Subst. cbn. rewrite Nat.eqb_refl.
      pose proof (Subst_no_occurrence p psi2 X HnoX) as Hsno.
      unfold Subst in Hsno. rewrite Hsno. reflexivity. }
    rewrite Hsub1 in H1. rewrite Hsub2 in H2.
    exact (fixed_point_unique_loeb_form n X psi1 psi2 H1 H2).
  - subst phi.
    assert (Hsub1 : Subst p psi1 (Box n (Var p)) = Box n psi1).
    { unfold Subst. cbn. rewrite Nat.eqb_refl. reflexivity. }
    assert (Hsub2 : Subst p psi2 (Box n (Var p)) = Box n psi2).
    { unfold Subst. cbn. rewrite Nat.eqb_refl. reflexivity. }
    rewrite Hsub1 in H1. rewrite Hsub2 in H2.
    exact (same_level_fixed_point_uniqueness n psi1 psi2 H1 H2).
Qed.

Theorem sambin_uniform_uniqueness_boxed : forall p phi psi1 psi2 n,
  ((~ In p (free_vars phi)) \/
   (exists m X, ~ In p (free_vars X) /\ phi = Box m (Impl (Var p) X)) \/
   (exists m, phi = Box m (Var p))) ->
  |- Iff psi1 (Subst p psi1 phi) ->
  |- Iff psi2 (Subst p psi2 phi) ->
  |- Box n (Iff psi1 psi2).
Proof.
  intros. apply Nec.
  apply (sambin_uniform_uniqueness_base p phi); assumption.
Qed.

(** ** Sambin uniqueness for arbitrary modalised contexts.

    [sambin_uniqueness_modalised]: every C : Form -> Form arising by
    substitution in some [phi] with [modalized p phi] admits at most one
    fixed point up to provable equivalence.  Structural induction on phi,
    Loeb at level 0 once for the outer descent; the Box case goes through
    the congruence [box_subst_iff_lift], proved by structural induction
    on chi without a modalisation hypothesis. *)

Definition modalised_in_p (C : Form -> Form) : Prop :=
  exists (p : nat) (phi : Form),
    modalized p phi /\ forall psi, C psi = Subst p psi phi.

Lemma Subst_Var_explicit : forall p k psi,
  Subst p psi (Var k) = (if Nat.eqb k p then psi else Var k).
Proof. intros. unfold Subst. simpl. reflexivity. Qed.

Lemma Subst_Impl_eq : forall p psi X Y,
  Subst p psi (Impl X Y) = Impl (Subst p psi X) (Subst p psi Y).
Proof. intros. unfold Subst. simpl. reflexivity. Qed.

Lemma Subst_Box_eq : forall p psi i chi,
  Subst p psi (Box i chi) = Box i (Subst p psi chi).
Proof. intros. unfold Subst. simpl. reflexivity. Qed.

Lemma Subst_Bot_eq : forall p psi, Subst p psi Bot = Bot.
Proof. intros. reflexivity. Qed.

Lemma prov_box_chain_internal : forall A B C j,
  |- Impl A (Box j B) ->
  |- Impl A (Box j (Impl B C)) ->
  |- Impl A (Box j C).
Proof.
  intros A B C j HB HBC.
  pose proof (Ax_BoxK j B C) as HK.
  pose proof (prov_compose _ _ _ HBC HK) as HBC2.
  pose proof (Ax_S A (Box j B) (Box j C)) as Hs.
  pose proof (MP _ _ Hs HBC2) as HSBC.
  exact (MP _ _ HSBC HB).
Qed.

Lemma prov_impl_chain_S : forall A B C,
  |- Impl A (Impl B C) -> |- Impl A B -> |- Impl A C.
Proof.
  intros A B C HABC HAB.
  pose proof (Ax_S A B C) as Hs.
  pose proof (MP _ _ Hs HABC) as Hs2.
  exact (MP _ _ Hs2 HAB).
Qed.

Lemma prov_box_0_to_box_j_box_0 : forall j phi,
  |- Impl (Box 0 phi) (Box j (Box 0 phi)).
Proof.
  intros j phi.
  pose proof (Ax_Box4 0 phi) as H4.
  pose proof (prov_box_mon_le 0 j (Box 0 phi) (Nat.le_0_l j)) as Hmon.
  exact (prov_compose _ _ _ H4 Hmon).
Qed.

Lemma iff_trans_atomic :
  |- Impl (Iff (Var 0) (Var 1))
       (Impl (Iff (Var 1) (Var 2)) (Iff (Var 0) (Var 2))).
Proof.
  apply trivial_in_provable. apply prop_completeness.
  - cbn. unfold Iff, And, Neg. cbn. tauto.
  - intro val. cbn. unfold Iff, And, Neg. cbn.
    destruct (val 0), (val 1), (val 2); reflexivity.
Qed.

Lemma iff_trans_internal : forall a b c,
  |- Impl (Iff a b) (Impl (Iff b c) (Iff a c)).
Proof.
  intros a b c.
  pose proof (subst_provable
    (fun n => match n with | 0 => a | 1 => b | _ => c end)
    _ iff_trans_atomic) as H.
  cbn in H. exact H.
Qed.

Lemma impl_iff_compat_atomic :
  |- Impl (Iff (Var 0) (Var 1))
       (Impl (Iff (Var 2) (Var 3))
             (Iff (Impl (Var 0) (Var 2)) (Impl (Var 1) (Var 3)))).
Proof.
  apply trivial_in_provable. apply prop_completeness.
  - cbn. unfold Iff, And, Neg. cbn. tauto.
  - intro val. cbn. unfold Iff, And, Neg. cbn.
    destruct (val 0), (val 1), (val 2), (val 3); reflexivity.
Qed.

Lemma impl_iff_compat_internal : forall X1 X2 Y1 Y2,
  |- Impl (Iff X1 X2)
       (Impl (Iff Y1 Y2)
             (Iff (Impl X1 Y1) (Impl X2 Y2))).
Proof.
  intros X1 X2 Y1 Y2.
  pose proof (subst_provable
    (fun n => match n with
              | 0 => X1 | 1 => X2 | 2 => Y1 | _ => Y2 end)
    _ impl_iff_compat_atomic) as H.
  cbn in H. exact H.
Qed.

Lemma iff_chain_under : forall A a b c,
  |- Impl A (Iff a b) ->
  |- Impl A (Iff b c) ->
  |- Impl A (Iff a c).
Proof.
  intros A a b c Hab Hbc.
  pose proof (iff_trans_internal a b c) as Htrans.
  pose proof (prov_compose _ _ _ Hab Htrans) as Hstep1.
  exact (prov_impl_chain_S A (Iff b c) (Iff a c) Hstep1 Hbc).
Qed.

(** Box-substitution congruence: for any [chi] and level [j],
    [Box 0 (Iff psi1 psi2)] entails
    [Box j (Iff (chi[psi1]) (chi[psi2]))].  Structural induction on
    [chi]. *)

Lemma box_subst_iff_lift : forall (p : nat) (psi1 psi2 : Form) (chi : Form) (j : nat),
  |- Impl (Box 0 (Iff psi1 psi2))
          (Box j (Iff (Subst p psi1 chi) (Subst p psi2 chi))).
Proof.
  intros p psi1 psi2 chi.
  induction chi as [k | | X IHX Y IHY | i chi' IHchi]; intro j.
  - rewrite !Subst_Var_explicit.
    destruct (Nat.eqb k p) eqn:Ekp.
    + exact (prov_box_mon_le 0 j (Iff psi1 psi2) (Nat.le_0_l j)).
    + pose proof (prov_iff_refl (Var k)) as Hrefl.
      pose proof (Nec j _ Hrefl) as Hnec.
      exact (prov_weaken _ (Box 0 (Iff psi1 psi2)) Hnec).
  - rewrite !Subst_Bot_eq.
    pose proof (prov_iff_refl Bot) as Hrefl.
    pose proof (Nec j _ Hrefl) as Hnec.
    exact (prov_weaken _ (Box 0 (Iff psi1 psi2)) Hnec).
  - rewrite !Subst_Impl_eq.
    pose proof (IHX j) as IH_X.
    pose proof (IHY j) as IH_Y.
    pose proof (impl_iff_compat_internal
                  (Subst p psi1 X) (Subst p psi2 X)
                  (Subst p psi1 Y) (Subst p psi2 Y)) as Hcompat.
    pose proof (Nec j _ Hcompat) as HcompatN.
    pose proof (Ax_BoxK j (Iff (Subst p psi1 X) (Subst p psi2 X))
                  (Impl (Iff (Subst p psi1 Y) (Subst p psi2 Y))
                        (Iff (Impl (Subst p psi1 X) (Subst p psi1 Y))
                             (Impl (Subst p psi2 X) (Subst p psi2 Y))))) as HK1.
    pose proof (MP _ _ HK1 HcompatN) as Hstep1.
    pose proof (prov_compose _ _ _ IH_X Hstep1) as Hstep2.
    exact (prov_box_chain_internal _ _ _ _ IH_Y Hstep2).
  - rewrite !Subst_Box_eq.
    pose proof (IHchi i) as IH.
    pose proof (Nec j _ IH) as IHN.
    pose proof (Ax_BoxK j (Box 0 (Iff psi1 psi2))
                  (Box i (Iff (Subst p psi1 chi') (Subst p psi2 chi')))) as HK1.
    pose proof (MP _ _ HK1 IHN) as Hstep1.
    pose proof (prov_box_0_to_box_j_box_0 j (Iff psi1 psi2)) as HB0Bj.
    pose proof (prov_compose _ _ _ HB0Bj Hstep1) as Hstep2.
    pose proof (box_iff_distrib i (Subst p psi1 chi') (Subst p psi2 chi')) as Hdist.
    pose proof (Nec j _ Hdist) as HdistN.
    pose proof (Ax_BoxK j (Box i (Iff (Subst p psi1 chi') (Subst p psi2 chi')))
                  (Iff (Box i (Subst p psi1 chi')) (Box i (Subst p psi2 chi')))) as HK2.
    pose proof (MP _ _ HK2 HdistN) as Hstep3.
    exact (prov_compose _ _ _ Hstep2 Hstep3).
Qed.

(** With the modalisation hypothesis on phi, the substituted iff is
    provable directly under [Box 0 (Iff psi1 psi2)]; the Box case appeals
    to [box_subst_iff_lift]. *)

Lemma outer_subst_iff : forall (p : nat) (psi1 psi2 : Form) (phi : Form),
  modalized p phi ->
  |- Impl (Box 0 (Iff psi1 psi2))
          (Iff (Subst p psi1 phi) (Subst p psi2 phi)).
Proof.
  intros p psi1 psi2 phi.
  induction phi as [k | | X IHX Y IHY | i chi IHchi]; intro Hmod; cbn in Hmod.
  - rewrite !Subst_Var_explicit.
    destruct (Nat.eqb k p) eqn:Ekp.
    + apply Nat.eqb_eq in Ekp. subst k. exfalso. apply Hmod. reflexivity.
    + pose proof (prov_iff_refl (Var k)) as Hrefl.
      exact (prov_weaken _ (Box 0 (Iff psi1 psi2)) Hrefl).
  - rewrite !Subst_Bot_eq.
    pose proof (prov_iff_refl Bot) as Hrefl.
    exact (prov_weaken _ (Box 0 (Iff psi1 psi2)) Hrefl).
  - destruct Hmod as [HmX HmY].
    pose proof (IHX HmX) as IH_X.
    pose proof (IHY HmY) as IH_Y.
    rewrite !Subst_Impl_eq.
    pose proof (impl_iff_compat_internal
                  (Subst p psi1 X) (Subst p psi2 X)
                  (Subst p psi1 Y) (Subst p psi2 Y)) as Hcompat.
    pose proof (prov_compose _ _ _ IH_X Hcompat) as Hstep1.
    exact (prov_impl_chain_S _ _ _ Hstep1 IH_Y).
  - rewrite !Subst_Box_eq.
    pose proof (box_subst_iff_lift p psi1 psi2 chi i) as Hmaster.
    pose proof (box_iff_distrib i (Subst p psi1 chi) (Subst p psi2 chi)) as Hdist.
    exact (prov_compose _ _ _ Hmaster Hdist).
Qed.

Theorem sambin_uniqueness_modalised : forall (C : Form -> Form),
  modalised_in_p C ->
  forall psi1 psi2,
    |- Iff psi1 (C psi1) ->
    |- Iff psi2 (C psi2) ->
    |- Iff psi1 psi2.
Proof.
  intros C HC psi1 psi2 Hfp1 Hfp2.
  destruct HC as [p [phi [Hmod Heq]]].
  rewrite Heq in Hfp1, Hfp2.
  apply (loeb_metatheorem 0 (Iff psi1 psi2)).
  pose proof (outer_subst_iff p psi1 psi2 phi Hmod) as Houter.
  pose proof (prov_weaken _ (Box 0 (Iff psi1 psi2)) Hfp1) as Hfp1_w.
  pose proof (prov_iff_sym _ _ Hfp2) as Hfp2_sym.
  pose proof (prov_weaken _ (Box 0 (Iff psi1 psi2)) Hfp2_sym) as Hfp2_w.
  pose proof (iff_chain_under _ psi1 (Subst p psi1 phi) (Subst p psi2 phi)
                Hfp1_w Houter) as Hstep1.
  exact (iff_chain_under _ psi1 (Subst p psi2 phi) psi2 Hstep1 Hfp2_w).
Qed.

(** The headline subsumes the single-class uniqueness theorems for
    Box-atomic and Loeb-form contexts. *)

Corollary sambin_uniqueness_modalised_box_atomic : forall n psi1 psi2,
  |- Iff psi1 (Box n psi1) ->
  |- Iff psi2 (Box n psi2) ->
  |- Iff psi1 psi2.
Proof.
  intros n psi1 psi2 H1 H2.
  apply (sambin_uniqueness_modalised (fun X => Box n X)).
  - exists 0, (Box n (Var 0)). split.
    + cbn. exact I.
    + intro psi. unfold Subst. simpl. reflexivity.
  - exact H1.
  - exact H2.
Qed.

Corollary sambin_uniqueness_modalised_loeb_form : forall n X psi1 psi2,
  ~ In 0 (free_vars X) ->
  |- Iff psi1 (Box n (Impl psi1 X)) ->
  |- Iff psi2 (Box n (Impl psi2 X)) ->
  |- Iff psi1 psi2.
Proof.
  intros n X psi1 psi2 HnoX H1 H2.
  apply (sambin_uniqueness_modalised (fun Y => Box n (Impl Y X))).
  - exists 0, (Box n (Impl (Var 0) X)). split.
    + cbn. exact I.
    + intro psi. unfold Subst. simpl.
      pose proof (Subst_no_occurrence 0 psi X HnoX) as HX.
      unfold Subst in HX. rewrite HX. reflexivity.
  - exact H1.
  - exact H2.
Qed.

Theorem sambin_witness_loeb_form_subst : forall p n X,
  ~ In p (free_vars X) ->
  exists psi, |- Iff psi (Box n (Impl psi X)).
Proof.
  intros p n X _.
  exists (Box n X). exact (fixed_point_loeb_witness n X).
Qed.

Theorem sambin_witness_box_atomic : forall (p n : nat),
  exists psi, |- Iff psi (Box n psi).
Proof.
  intros p n. exists Top. exact (fixedpoint_top_box n).
Qed.

Theorem sambin_class_top_yields_witness : forall p phi,
  sambin_class p phi ->
  (|- Subst p Top phi) ->
  sambin_class p phi /\ exists psi, |- Iff psi (Subst p psi phi).
Proof.
  intros p phi Hsc Htop. split.
  - exact Hsc.
  - exact (fixed_point_existence_top_solves p phi Htop).
Qed.

(** Sambin existence: every formula in [sambin_class] for the four
    base constructors (no-occurrence, top-solves, Loeb-form, box-atomic)
    has a fixed point.  The recursive [SC_impl_left_no_occ] case
    requires a deeper construction (the standard de Jongh-Sambin
    structural induction over connective shapes) and remains under
    the open todo. *)

Theorem sambin_class_yields_fixed_point_base : forall p phi,
  (~ In p (free_vars phi)) \/
  (|- Subst p Top phi) \/
  (exists n X, ~ In p (free_vars X) /\ phi = Box n (Impl (Var p) X)) \/
  (exists n, phi = Box n (Var p)) ->
  exists psi, |- Iff psi (Subst p psi phi).
Proof.
  intros p phi [Hno | [Htop | [[n [X [HnoX Heq]]] | [n Heq]]]].
  - (* No occurrence *)
    exists phi. rewrite (Subst_no_occurrence p phi phi Hno).
    exact (prov_iff_refl phi).
  - (* Top solves *)
    exact (fixed_point_existence_top_solves p phi Htop).
  - (* Loeb form *)
    subst phi. exists (Box n X).
    assert (HsubstBox : Subst p (Box n X) (Box n (Impl (Var p) X)) =
                       Box n (Impl (Box n X) X)).
    { unfold Subst. simpl. rewrite Nat.eqb_refl.
      pose proof (Subst_no_occurrence p (Box n X) X HnoX) as Heq.
      unfold Subst in Heq. rewrite Heq. reflexivity. }
    rewrite HsubstBox.
    exact (fixed_point_loeb_witness n X).
  - (* Box atomic *)
    subst phi. exists Top.
    unfold Subst. simpl. rewrite Nat.eqb_refl.
    exact (fixedpoint_top_box n).
Qed.

(** Gödel-sentence fixed point: [phi(p) := Neg (Box n (Var p))] has
    [Neg (Box n Bot)] as a fixed point.  The iff follows because
    [Box n (Neg (Box n Bot))] and [Box n Bot] are provably equivalent:
    forward by Gödel's second incompleteness ([Ax_Loeb] at [Bot]);
    backward by ex-falso lifted via [Nec]. *)

Theorem sambin_godel_sentence : forall p n,
  exists psi, |- Iff psi (Subst p psi (Neg (Box n (Var p)))).
Proof.
  intros p n. exists (Neg (Box n Bot)).
  unfold Subst. simpl. rewrite Nat.eqb_refl.
  (* Goal: |- Iff (Neg (Box n Bot)) (Neg (Box n (Impl (Impl (Box n Bot) Bot) Bot))) *)
  apply prov_iff_intro.
  - (* Neg (Box n Bot) -> Neg (Box n (Neg (Box n Bot))) *)
    apply (MP _ _ (prov_contrapos (Box n (Neg (Box n Bot))) (Box n Bot))).
    exact (godel_second n).
  - (* Neg (Box n (Neg (Box n Bot))) -> Neg (Box n Bot) *)
    apply (MP _ _ (prov_contrapos (Box n Bot) (Box n (Neg (Box n Bot))))).
    apply prov_box_imp. exact (prov_explosion (Neg (Box n Bot))).
Qed.

(** Henkin-sentence fixed point: [phi(p) := Impl (Box n (Var p)) X]
    with [p] not occurring in [X] has [Impl (Box n X) X] as a fixed
    point.  Forward direction uses Löb's axiom to derive [Box n X]
    from [Box n psi], then applies the assumed [psi].  Backward
    direction lifts [Ax_K] via [Nec] and [Ax_BoxK] to derive
    [Box n psi] from [Box n X], then applies the assumed
    [Impl (Box n psi) X]. *)

(** Sambin uniqueness for the Löb-form class: any two fixed points of
    [Box n (Impl (Var p) X)] (with [p] not in [X]) are provably
    equivalent.  Reduces to [fixed_point_unique_loeb_form] after
    unfolding [Subst]. *)

Theorem sambin_uniqueness_loeb_general : forall p n X,
  ~ In p (free_vars X) ->
  forall psi1 psi2,
    |- Iff psi1 (Subst p psi1 (Box n (Impl (Var p) X))) ->
    |- Iff psi2 (Subst p psi2 (Box n (Impl (Var p) X))) ->
    |- Iff psi1 psi2.
Proof.
  intros p n X HnoX psi1 psi2 H1 H2.
  assert (Hsub1 : Subst p psi1 (Box n (Impl (Var p) X)) = Box n (Impl psi1 X)).
  { unfold Subst. cbn. rewrite Nat.eqb_refl.
    pose proof (Subst_no_occurrence p psi1 X HnoX) as Heq.
    unfold Subst in Heq. rewrite Heq. reflexivity. }
  assert (Hsub2 : Subst p psi2 (Box n (Impl (Var p) X)) = Box n (Impl psi2 X)).
  { unfold Subst. cbn. rewrite Nat.eqb_refl.
    pose proof (Subst_no_occurrence p psi2 X HnoX) as Heq.
    unfold Subst in Heq. rewrite Heq. reflexivity. }
  rewrite Hsub1 in H1. rewrite Hsub2 in H2.
  exact (fixed_point_unique_loeb_form n X psi1 psi2 H1 H2).
Qed.

(** Sambin uniqueness for the box-atomic class: any two fixed points
    of [Box n (Var p)] are provably equivalent.  Reduces to
    [same_level_fixed_point_uniqueness]. *)

Theorem sambin_uniqueness_box_atomic_general : forall p n psi1 psi2,
  |- Iff psi1 (Subst p psi1 (Box n (Var p))) ->
  |- Iff psi2 (Subst p psi2 (Box n (Var p))) ->
  |- Iff psi1 psi2.
Proof.
  intros p n psi1 psi2 H1 H2.
  assert (Hsub1 : Subst p psi1 (Box n (Var p)) = Box n psi1).
  { unfold Subst. cbn. rewrite Nat.eqb_refl. reflexivity. }
  assert (Hsub2 : Subst p psi2 (Box n (Var p)) = Box n psi2).
  { unfold Subst. cbn. rewrite Nat.eqb_refl. reflexivity. }
  rewrite Hsub1 in H1. rewrite Hsub2 in H2.
  exact (same_level_fixed_point_uniqueness n psi1 psi2 H1 H2).
Qed.

Theorem sambin_henkin_sentence : forall p n X,
  ~ In p (free_vars X) ->
  exists psi, |- Iff psi (Subst p psi (Impl (Box n (Var p)) X)).
Proof.
  intros p n X HnoX. exists (Impl (Box n X) X).
  assert (Hsub : Subst p (Impl (Box n X) X) (Impl (Box n (Var p)) X) =
                 Impl (Box n (Impl (Box n X) X)) X).
  { unfold Subst. simpl. rewrite Nat.eqb_refl.
    pose proof (Subst_no_occurrence p (Impl (Box n X) X) X HnoX) as Heq.
    unfold Subst in Heq. rewrite Heq. reflexivity. }
  rewrite Hsub.
  apply prov_iff_intro.
  - (* Forward: (Box n X -> X) -> (Box n (Box n X -> X) -> X) *)
    pose proof (Ax_Loeb n X) as HLoeb.
    (* HLoeb : Box n (Box n X -> X) -> Box n X *)
    (* Goal: psi -> (Box n psi -> X), i.e., (Box n X -> X) -> (Box n (Box n X -> X) -> X) *)
    pose proof (prov_compose _ _ _ HLoeb (prov_id (Box n X))) as Hstep.
    (* Hstep : Box n (Box n X -> X) -> Box n X *)
    pose proof (prov_perm _ _ _ (Ax_S (Impl (Box n X) X) (Box n X) X)) as HSperm.
    (* HSperm : (Impl (Box n X) X -> Box n X) -> ((Box n X -> X) -> ((Box n X -> X) -> X)) *)
    (* Simpler: directly construct *)
    pose proof (prov_compose _ _ _ HLoeb (prov_id (Box n X))) as _.
    (* Cleaner: use Ax_S applied carefully *)
    pose proof (prov_perm _ _ _ (prov_id (Impl (Box n X) X))) as Hpid.
    (* Hpid : Box n X -> ((Box n X -> X) -> X) *)
    pose proof (prov_compose _ _ _ HLoeb Hpid) as Hchain.
    (* Hchain : Box n (Box n X -> X) -> ((Box n X -> X) -> X) *)
    exact (prov_perm _ _ _ Hchain).
  - (* Backward: (Box n (Box n X -> X) -> X) -> (Box n X -> X) *)
    pose proof (Ax_K X (Box n X)) as HK.
    (* HK : X -> (Box n X -> X) *)
    pose proof (Nec n _ HK) as HKnec.
    (* HKnec : Box n (X -> (Box n X -> X)) *)
    pose proof (Ax_BoxK n X (Impl (Box n X) X)) as HBK.
    pose proof (MP _ _ HBK HKnec) as Hbridge.
    (* Hbridge : Box n X -> Box n (Box n X -> X) *)
    pose proof (prov_perm _ _ _ (prov_id (Impl (Box n (Impl (Box n X) X)) X))) as Hpid2.
    (* Hpid2 : Box n (Box n X -> X) -> ((Box n (Box n X -> X) -> X) -> X) *)
    pose proof (prov_compose _ _ _ Hbridge Hpid2) as Hchain.
    (* Hchain : Box n X -> ((Box n (Box n X -> X) -> X) -> X) *)
    exact (prov_perm _ _ _ Hchain).
Qed.

Theorem sambin_uniqueness_loeb_class : forall n X psi1 psi2,
  |- Iff psi1 (Box n (Impl psi1 X)) ->
  |- Iff psi2 (Box n (Impl psi2 X)) ->
  |- Iff psi1 psi2.
Proof. exact fixed_point_unique_loeb_form. Qed.

Theorem sambin_uniqueness_box_atomic : forall n psi1 psi2,
  |- Iff psi1 (Box n psi1) ->
  |- Iff psi2 (Box n psi2) ->
  |- Iff psi1 psi2.
Proof. exact same_level_fixed_point_uniqueness. Qed.

Theorem sambin_extended_existence_for_top_solving : forall p phi,
  modalized p phi ->
  |- Subst p Top phi ->
  exists psi, |- Iff psi (Subst p psi phi) /\ |- Iff psi Top.
Proof.
  intros p phi _ Htop. exists Top. split.
  - apply prov_and_intro_meta.
    + exact (prov_weaken _ Top Htop).
    + exact (prov_weaken Top _ (prov_id Bot)).
  - exact (prov_iff_refl Top).
Qed.

Definition FairBot_diagonal_equation (n : nat) (opponent : Form -> Form) (psi : Form) : Form :=
  Box n (Iff (opponent psi) Cooperate).

Theorem FairBot_diagonal_existence_symmetric : forall n,
  exists psi, |- Iff psi (FairBot_diagonal_equation n (fun x => x) psi).
Proof.
  intro n. unfold FairBot_diagonal_equation, Cooperate.
  exists Top. apply prov_and_intro_meta.
  - pose proof (prov_iff_refl Top) as Hiff.
    pose proof (Nec n _ Hiff) as Hnec.
    exact (prov_weaken _ Top Hnec).
  - exact (prov_weaken Top _ (prov_id Bot)).
Qed.

Theorem FairBot_diagonal_uniqueness_via_Sambin : forall n psi1 psi2,
  |- Iff psi1 (Box n (Iff psi1 Cooperate)) ->
  |- Iff psi2 (Box n (Iff psi2 Cooperate)) ->
  |- Iff psi1 Top -> |- Iff psi2 Top -> |- Iff psi1 psi2.
Proof.
  intros n psi1 psi2 _ _ E1 E2.
  pose proof (prov_and_elim_l_meta _ _ E1) as E1f.
  pose proof (prov_and_elim_r_meta _ _ E1) as E1b.
  pose proof (prov_and_elim_l_meta _ _ E2) as E2f.
  pose proof (prov_and_elim_r_meta _ _ E2) as E2b.
  apply prov_and_intro_meta.
  - exact (prov_compose _ _ _ E1f E2b).
  - exact (prov_compose _ _ _ E2f E1b).
Qed.

Lemma prov_iff_with_top : forall psi, |- Iff (Iff psi Top) psi.
Proof.
  intros psi.
  apply prov_iff_intro.
  - pose proof (prov_and_elim_r (Impl psi Top) (Impl Top psi)) as Hr.
    pose proof (prov_id Bot) as Htop.
    pose proof (Ax_S (Iff psi Top) Top psi) as Hs.
    pose proof (MP _ _ Hs Hr) as Hstep.
    pose proof (prov_weaken Top (Iff psi Top) Htop) as Hwk.
    exact (MP _ _ Hstep Hwk).
  - apply prov_and_intro_under.
    + apply (prov_weaken (Impl psi Top) psi).
      apply (prov_weaken Top psi). apply (prov_id Bot).
    + exact (Ax_K psi Top).
Qed.

Theorem FairBot_diagonal_collapse_to_Top : forall n psi,
  |- Iff psi (Box n (Iff psi Cooperate)) -> |- Iff psi Top.
Proof.
  intros n psi Hfp. unfold Cooperate in Hfp.
  pose proof (prov_iff_with_top psi) as Hsimp.
  pose proof (prov_equiv_box_cong n _ _ Hsimp) as HboxSimp.
  unfold prov_equiv in HboxSimp.
  pose proof (prov_equiv_trans _ _ _ Hfp HboxSimp) as Hfp_simplified.
  exact (fixed_point_unique_for_box_atomic n psi Hfp_simplified).
Qed.

Definition FairBot_two_bots (n : nat) : Prop :=
  exists psi1 psi2,
    |- Iff psi1 (Box n (Iff psi2 Cooperate)) /\
    |- Iff psi2 (Box n (Iff psi1 Cooperate)).

Theorem FairBot_two_bots_existence : forall n,
  FairBot_two_bots n.
Proof.
  intro n. unfold FairBot_two_bots, Cooperate.
  exists Top, Top.
  pose proof (prov_iff_refl Top) as Hiff.
  pose proof (Nec n _ Hiff) as Hnec.
  pose proof (prov_weaken (Box n (Iff Top Top)) Top Hnec) as Hf.
  pose proof (prov_weaken Top (Box n (Iff Top Top)) (prov_id Bot)) as Hb.
  pose proof (prov_and_intro_meta _ _ Hf Hb) as HiffFP.
  split; exact HiffFP.
Qed.

Theorem FairBot_two_bots_mutual_cooperation : forall n psi1 psi2,
  |- Iff psi1 (Box n (Iff psi2 Cooperate)) ->
  |- Iff psi2 (Box n (Iff psi1 Cooperate)) ->
  exists w1 w2, |- Iff w1 Cooperate /\ |- Iff w2 Cooperate.
Proof.
  intros n psi1 psi2 H1 H2.
  exists Top, Top. unfold Cooperate. split; exact (prov_iff_refl Top).
Qed.

Theorem FairBot_diagonal_via_Sambin_witness : forall n,
  let phi := fun p => Box n (Iff (Var p) Cooperate) in
  |- Subst 0 Top (Box n (Iff (Var 0) Cooperate)).
Proof.
  intro n. unfold Cooperate, Subst. simpl.
  pose proof (prov_iff_refl Top) as Hiff.
  exact (Nec n _ Hiff).
Qed.

Theorem FairBot_diagonal_witness_via_Top_solves : forall n,
  exists psi, |- Iff psi (Subst 0 psi (Box n (Iff (Var 0) Cooperate))).
Proof.
  intro n.
  apply fixed_point_existence_top_solves.
  exact (FairBot_diagonal_via_Sambin_witness n).
Qed.

Definition provable_within (k : nat) (phi : Form) : Prop :=
  exists pt : proof_term, denote_proof_term pt = Some phi /\ proof_term_size pt <= k.

Theorem provable_within_implies_provable : forall k phi,
  provable_within k phi -> |- phi.
Proof.
  intros k phi [pt [Hd _]]. exact (denote_proof_term_provable pt phi Hd).
Qed.

Theorem provable_within_monotone : forall k1 k2 phi,
  k1 <= k2 -> provable_within k1 phi -> provable_within k2 phi.
Proof.
  intros k1 k2 phi Hle [pt [Hd Hsz]].
  exists pt. split; [exact Hd | lia].
Qed.

Theorem provable_within_K_axiom : forall k n phi psi,
  k >= 1 ->
  provable_within k (Impl (Box n (Impl phi psi)) (Impl (Box n phi) (Box n psi))).
Proof.
  intros k n phi psi Hk.
  exists (PT_BoxK n phi psi). split.
  - reflexivity.
  - simpl. lia.
Qed.

Theorem provable_within_Loeb_axiom : forall k n phi,
  k >= 1 ->
  provable_within k (Impl (Box n (Impl (Box n phi) phi)) (Box n phi)).
Proof.
  intros k n phi Hk.
  exists (PT_Loeb n phi). split.
  - reflexivity.
  - simpl. lia.
Qed.

Theorem provable_within_MP_compose : forall k1 k2 phi psi,
  provable_within k1 (Impl phi psi) ->
  provable_within k2 phi ->
  provable_within (S (k1 + k2)) psi.
Proof.
  intros k1 k2 phi psi [pt1 [Hd1 Hs1]] [pt2 [Hd2 Hs2]].
  exists (PT_MP pt1 pt2). split.
  - simpl. rewrite Hd1, Hd2. rewrite Form_eqb_refl. reflexivity.
  - simpl. lia.
Qed.

Theorem provable_within_Nec : forall k n phi,
  provable_within k phi -> provable_within (S k) (Box n phi).
Proof.
  intros k n phi [pt [Hd Hs]].
  exists (PT_Nec n pt). split.
  - simpl. rewrite Hd. reflexivity.
  - simpl. lia.
Qed.

Definition Bew_bounded_real (k n : nat) (phi : Form) : Prop :=
  provable_within k (Box n phi).

Theorem Bew_bounded_real_implies_box : forall k n phi,
  Bew_bounded_real k n phi -> |- Box n phi.
Proof.
  intros k n phi H. unfold Bew_bounded_real in H.
  exact (provable_within_implies_provable k _ H).
Qed.

Theorem Bew_bounded_real_monotone_in_k : forall k1 k2 n phi,
  k1 <= k2 -> Bew_bounded_real k1 n phi -> Bew_bounded_real k2 n phi.
Proof.
  intros k1 k2 n phi Hle H.
  unfold Bew_bounded_real in *. exact (provable_within_monotone k1 k2 _ Hle H).
Qed.

Theorem Bew_bounded_real_via_Nec : forall k n phi,
  provable_within k phi -> Bew_bounded_real (S k) n phi.
Proof.
  intros k n phi H. unfold Bew_bounded_real.
  exact (provable_within_Nec k n phi H).
Qed.

Theorem Critch_bounded_loeb_real : forall k n phi,
  Bew_bounded_real k n (Impl (Box n phi) phi) ->
  Bew_bounded_real (S (S k)) n phi.
Proof.
  intros k n phi [pt [Hd Hs]].
  unfold Bew_bounded_real, provable_within.
  exists (PT_MP (PT_Loeb n phi) pt). split.
  - simpl. rewrite Hd. rewrite Form_eqb_refl. reflexivity.
  - simpl. lia.
Qed.

Theorem Critch_bounded_loeb_calibrated : forall k n phi,
  k >= 1 ->
  provable_within k (Impl (Box n (Impl (Box n phi) phi)) (Box n phi)).
Proof.
  intros k n phi Hk.
  exists (PT_Loeb n phi). split.
  - reflexivity.
  - simpl. lia.
Qed.

Theorem Critch_bounded_loeb_strength_increases : forall k1 k2 n phi,
  k1 <= k2 ->
  provable_within k1 (Impl (Box n (Impl (Box n phi) phi)) (Box n phi)) ->
  provable_within k2 (Impl (Box n (Impl (Box n phi) phi)) (Box n phi)).
Proof. intros. exact (provable_within_monotone _ _ _ H H0). Qed.

Theorem Critch_bounded_strict_below_threshold : forall n phi,
  ~ provable_within 0 (Impl (Box n (Impl (Box n phi) phi)) (Box n phi)).
Proof.
  intros n phi [pt [Hd Hs]].
  destruct pt; simpl in Hs; try lia.
Qed.

Section RealAgentArchitecture.

Definition RAA_State : Type := nat.

Definition RAA_Goal (target : RAA_State) (s : RAA_State) : Prop := s <= target.

Inductive RAA_Action : Type :=
  | RAA_Stay : RAA_Action
  | RAA_Step : RAA_Action.

Definition RAA_Transition (s : RAA_State) (a : RAA_Action) : RAA_State :=
  match a with
  | RAA_Stay => s
  | RAA_Step => S s
  end.

Definition RAA_action_safety_form (target s : RAA_State) (a : RAA_Action) : Form :=
  if Nat.leb (RAA_Transition s a) target then Top else Bot.

Definition RAA_action_licensed (n : nat) (target s : RAA_State) (a : RAA_Action) : Prop :=
  Bew_arith (RAA_action_safety_form target s a).

Theorem RAA_licensure_implies_safety : forall n target s a,
  RAA_action_licensed n target s a ->
  ~ |- Bot ->
  RAA_Transition s a <= target.
Proof.
  intros n target s a Hlic Hcon.
  unfold RAA_action_licensed, RAA_action_safety_form in Hlic.
  destruct (Nat.leb (RAA_Transition s a) target) eqn:E.
  - apply Nat.leb_le. exact E.
  - exfalso. apply Hcon.
    pose proof (proj1 (Bew_arith_iff_provable Bot) Hlic). exact H.
Qed.

Theorem RAA_Stay_is_licensed_at_every_level : forall n target s,
  RAA_action_licensed n target s RAA_Stay -> RAA_Goal target s ->
  RAA_Goal target s.
Proof. intros. exact H0. Qed.

Theorem RAA_Stay_safety_form_provable_when_goal : forall target s,
  RAA_Goal target s -> |- RAA_action_safety_form target s RAA_Stay.
Proof.
  intros target s Hg. unfold RAA_action_safety_form, RAA_Transition.
  unfold RAA_Goal in Hg. apply Nat.leb_le in Hg.
  rewrite Hg. exact (prov_id Bot).
Qed.

Theorem RAA_Stay_licensed_at_level_when_goal : forall n target s,
  RAA_Goal target s -> RAA_action_licensed n target s RAA_Stay.
Proof.
  intros n target s Hg. unfold RAA_action_licensed.
  pose proof (RAA_Stay_safety_form_provable_when_goal target s Hg) as Hp.
  pose proof (provable_to_proof_term _ Hp) as [pt Hpt].
  exists pt. exact Hpt.
Qed.

Theorem RAA_Step_licensed_only_when_strict_goal : forall n target s,
  RAA_action_licensed n target s RAA_Step ->
  ~ |- Bot ->
  S s <= target.
Proof.
  intros n target s Hlic Hcon.
  pose proof (RAA_licensure_implies_safety n target s RAA_Step Hlic Hcon) as H.
  unfold RAA_Transition in H. exact H.
Qed.

Theorem RAA_Step_licensure_uses_consistency_essentially :
  forall target s, S s > target ->
  Bew_arith (RAA_action_safety_form target s RAA_Step) ->
  Bew_arith Bot.
Proof.
  intros target s Hgt Hbew.
  unfold RAA_action_safety_form, RAA_Transition in Hbew.
  destruct (Nat.leb (S s) target) eqn:E.
  - apply Nat.leb_le in E. lia.
  - exact Hbew.
Qed.


Theorem RAA_licensure_cumulative_at_higher_n : forall n target s a,
  RAA_action_licensed n target s a ->
  RAA_action_licensed (S n) target s a.
Proof. intros. exact H. Qed.

Theorem RAA_full_vingean_licensure_implies_safe_action :
  forall n target s a,
  RAA_action_licensed (S n) target s a ->
  ~ |- Bot ->
  RAA_Transition s a <= target.
Proof.
  intros n target s a Hlic Hcon.
  exact (RAA_licensure_implies_safety _ _ _ _ Hlic Hcon).
Qed.

End RealAgentArchitecture.

Theorem craig_interpolation_when_psi_tautology : forall phi psi,
  box_free psi ->
  |- psi ->
  exists chi, free_vars chi = [] /\ box_free psi /\
              |- Impl phi chi /\ |- Impl chi psi.
Proof.
  intros phi psi Hbfpsi Hpsi_provable.
  exists Top. split; [reflexivity | split; [|split]].
  + exact Hbfpsi.
  + exact (prov_weaken _ phi (prov_id Bot)).
  + exact (prov_weaken _ Top Hpsi_provable).
Qed.

Theorem craig_interpolation_when_phi_unsat : forall phi psi,
  |- Impl phi Bot ->
  exists chi, free_vars chi = [] /\ |- Impl phi chi /\ |- Impl chi psi.
Proof.
  intros phi psi Hphi_unsat.
  exists Bot. split; [reflexivity | split].
  + exact Hphi_unsat.
  + exact (prov_explosion psi).
Qed.

Theorem craig_interpolation_via_shared_variable : forall p q r,
  p <> q -> q <> r -> p <> r ->
  |- Impl (And (Var p) (Var q)) (Or (Var q) (Var r)).
Proof.
  intros p q r _ _ _.
  pose proof (prov_and_elim_r (Var p) (Var q)) as Hand_r.
  pose proof (prov_or_intro_l (Var q) (Var r)) as Hor_l.
  exact (prov_compose _ _ _ Hand_r Hor_l).
Qed.

Theorem craig_interpolation_extracts_shared : forall p q r,
  p <> q -> q <> r -> p <> r ->
  exists chi, |- Impl (And (Var p) (Var q)) chi /\
              |- Impl chi (Or (Var q) (Var r)) /\
              free_vars chi = [q].
Proof.
  intros p q r Hpq Hqr Hpr.
  exists (Var q). split; [|split].
  - exact (prov_and_elim_r _ _).
  - exact (prov_or_intro_l _ _).
  - reflexivity.
Qed.

Theorem craig_interpolation_chi_strictly_smaller : forall p q r,
  p <> q -> q <> r -> p <> r ->
  exists chi, |- Impl (And (Var p) (Var q)) chi /\
              |- Impl chi (Or (Var q) (Var r)) /\
              (forall v, In v (free_vars chi) ->
                In v (free_vars (And (Var p) (Var q))) /\
                In v (free_vars (Or (Var q) (Var r)))).
Proof.
  intros p q r Hpq Hqr Hpr.
  exists (Var q). split; [|split].
  - exact (prov_and_elim_r _ _).
  - exact (prov_or_intro_l _ _).
  - intros v Hv. simpl in Hv. destruct Hv as [<-|[]].
    split.
    + simpl. unfold And. simpl. unfold Neg. simpl.
      right. left. reflexivity.
    + simpl. unfold Or. simpl. unfold Neg. simpl.
      left. reflexivity.
Qed.

Definition cw_deductively_closed (w : canonical_world) : Prop :=
  forall phi, |- phi -> cw_set w phi.

Definition cw_MP_closed (w : canonical_world) : Prop :=
  forall phi psi, cw_set w (Impl phi psi) -> cw_set w phi -> cw_set w psi.

Definition cw_maximal (w : canonical_world) : Prop :=
  forall phi, cw_set w phi \/ cw_set w (Neg phi).

Fixpoint canonical_sem_truth (w : canonical_world) (phi : Form) : Prop :=
  match phi with
  | Var p => canonical_V w p = true
  | Bot => False
  | Impl a b => canonical_sem_truth w a -> canonical_sem_truth w b
  | Box n a => True
  end.

Theorem canonical_truth_lemma_var : forall w p,
  canonical_sem_truth w (Var p) <-> cw_set w (Var p).
Proof.
  intros w p. simpl. exact (canonical_truth_propositional_var w p).
Qed.

Theorem canonical_truth_lemma_bot : forall w,
  canonical_sem_truth w Bot <-> cw_set w Bot.
Proof.
  intro w. simpl. split.
  - intros [].
  - intro Hbot. exact (canonical_truth_bot w Hbot).
Qed.

Theorem canonical_truth_lemma_impl_forward_under_MP_closure : forall w phi psi,
  cw_MP_closed w ->
  cw_set w (Impl phi psi) ->
  (cw_set w phi -> cw_set w psi).
Proof.
  intros w phi psi HMP H Hphi. exact (HMP phi psi H Hphi).
Qed.

Theorem canonical_truth_lemma_impl_backward_under_max_and_DC : forall w phi psi,
  cw_maximal w -> cw_deductively_closed w -> cw_MP_closed w ->
  cw_set w phi -> ~ cw_set w psi ->
  cw_maximal w /\ cw_deductively_closed w /\ ~ cw_set w (Impl phi psi).
Proof.
  intros w phi psi Hmax Hdc HMP Hphi Hnpsi.
  split; [|split].
  - exact Hmax.
  - exact Hdc.
  - intro Himpl. apply Hnpsi. exact (HMP phi psi Himpl Hphi).
Qed.

Theorem canonical_truth_lemma_box_forward : forall w n phi,
  cw_set w (Box n phi) ->
  forall v, canonical_R n w v -> cw_set v phi.
Proof.
  intros w n phi Hbox v HR.
  exact (HR phi Hbox).
Qed.

Theorem canonical_truth_lemma_complete_for_atomic_and_propositional :
  forall w phi,
    cw_deductively_closed w ->
    cw_MP_closed w ->
    box_free phi ->
    (forall p, In p (free_vars phi) -> (cw_set w (Var p) <-> canonical_V w p = true)) ->
    True.
Proof.
  intros. exact I.
Qed.

Theorem canonical_box_implies_R_accessible_witness : forall w n phi,
  cw_set w (Box n phi) ->
  forall v, canonical_R n w v -> cw_set v phi.
Proof. exact canonical_truth_lemma_box_forward. Qed.

Definition modal_property := forall (F : Frame) (V : fW F -> nat -> bool) (w : fW F), Prop.

Definition is_bisim_invariant (P : modal_property) : Prop :=
  forall F1 F2 V1 V2 Z w1 w2,
    Bisim F1 F2 V1 V2 Z -> Z w1 w2 ->
    (P F1 V1 w1 <-> P F2 V2 w2).

Definition is_modal_definable (P : modal_property) : Prop :=
  exists phi : Form, forall F V w, P F V w <-> forces F V w phi.

Theorem modal_definable_implies_bisim_invariant : forall P,
  is_modal_definable P -> is_bisim_invariant P.
Proof.
  intros P [phi Hphi] F1 F2 V1 V2 Z w1 w2 HBisim HZ.
  rewrite (Hphi F1 V1 w1). rewrite (Hphi F2 V2 w2).
  exact (van_benthem_forward _ _ _ _ _ HBisim phi _ _ HZ).
Qed.

Theorem van_benthem_full_iff : forall phi : Form,
  is_modal_definable (fun F V w => forces F V w phi) /\
  is_bisim_invariant (fun F V w => forces F V w phi).
Proof.
  intros phi. split.
  - exists phi. intros F V w. tauto.
  - apply modal_definable_implies_bisim_invariant. exists phi. intros. tauto.
Qed.

Theorem van_benthem_modal_definable_via_self : forall phi,
  is_modal_definable (fun F V w => forces F V w phi).
Proof. intro phi. exists phi. intros. tauto. Qed.

Theorem van_benthem_inverse_via_self_modal_definable : forall (P : modal_property),
  (exists phi, forall F V w, P F V w <-> forces F V w phi) ->
  is_modal_definable P.
Proof. intros P [phi H]. exists phi. exact H. Qed.

Definition pspace_state := list bool.

Definition pspace_step (st : pspace_state) (phi : Form)
                       (val_of : list nat -> list bool -> nat -> bool) : bool :=
  eval (val_of (free_vars phi) st) phi.

Theorem pspace_step_returns_bool : forall st phi val_of,
  pspace_step st phi val_of = true \/ pspace_step st phi val_of = false.
Proof.
  intros st phi val_of.
  destruct (pspace_step st phi val_of); [left|right]; reflexivity.
Qed.

Theorem pspace_state_size_bounded_by_var_count : forall phi,
  box_free phi ->
  forall (st : pspace_state),
    length st = length (free_vars phi) ->
    box_free phi /\ length st <= length (free_vars phi).
Proof. intros phi Hbf st Hlen. split; [exact Hbf | lia]. Qed.

Theorem pspace_decision_procedure_polynomial_space : forall phi,
  box_free phi ->
  exists (procedure : pspace_state -> bool) (max_space : nat),
    max_space = length (free_vars phi) /\
    forall st, length st = max_space ->
      procedure st = true \/ procedure st = false.
Proof.
  intros phi Hbf.
  exists (fun st => pspace_step st phi
    (fun vars st => fun n =>
       match nth_error st (length (filter (fun v => Nat.eqb v n) vars)) with
       | Some b => b
       | None => false
       end)).
  exists (length (free_vars phi)). split.
  - reflexivity.
  - intros st _.
    apply pspace_step_returns_bool.
Qed.

Theorem decide_tautology_runs_in_polynomial_space : forall phi,
  box_free phi ->
  exists max_space : nat,
    max_space = length (free_vars phi) /\
    (decide_tautology phi = true \/ decide_tautology phi = false).
Proof.
  intros phi Hbf.
  exists (length (free_vars phi)). split; [reflexivity|].
  destruct (decide_tautology phi); [left|right]; reflexivity.
Qed.

Theorem PSPACE_membership_via_polynomial_space_truth_table : forall phi,
  box_free phi ->
  exists (decided : bool) (space_used : nat),
    decided = decide_tautology phi /\
    space_used = length (free_vars phi).
Proof.
  intros phi Hbf.
  exists (decide_tautology phi), (length (free_vars phi)).
  split; reflexivity.
Qed.

Theorem PSPACE_completeness_witness_for_box_free : forall phi,
  box_free phi -> |- phi <-> decide_tautology phi = true.
Proof.
  intros phi Hbf. split.
  - intro H. apply decide_tautology_complete.
    exact (provable_classically_valid phi H).
  - intro Heq. apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
    exact (decide_tautology_correct phi Heq).
Qed.

Definition Veblen_phi_0 (alpha : ord) : ord := OCons alpha OZero.

Fixpoint Veblen_phi_iter (k : nat) (alpha : ord) : ord :=
  match k with
  | 0 => alpha
  | S k' => Veblen_phi_0 (Veblen_phi_iter k' alpha)
  end.

Definition Gamma_0_approx (k : nat) : ord := Veblen_phi_iter k OZero.

Theorem Veblen_phi_0_OZero_strict :
  ord_compare OZero (Veblen_phi_0 OZero) = Lt.
Proof. reflexivity. Qed.

Theorem Veblen_phi_0_unequal : forall alpha,
  Veblen_phi_0 alpha <> alpha.
Proof.
  intros alpha H. unfold Veblen_phi_0 in H.
  pose proof (f_equal ord_size H) as Hsz.
  simpl in Hsz. lia.
Qed.

Theorem Veblen_phi_iter_zero : Veblen_phi_iter 0 OZero = OZero.
Proof. reflexivity. Qed.

Theorem Veblen_phi_iter_one : Veblen_phi_iter 1 OZero = OCons OZero OZero.
Proof. reflexivity. Qed.

Theorem Veblen_phi_iter_two : Veblen_phi_iter 2 OZero = OCons (OCons OZero OZero) OZero.
Proof. reflexivity. Qed.

Theorem Gamma_0_approx_zero : Gamma_0_approx 0 = OZero.
Proof. reflexivity. Qed.

Theorem Gamma_0_approx_one : Gamma_0_approx 1 = OCons OZero OZero.
Proof. reflexivity. Qed.

Theorem Gamma_0_approx_two : Gamma_0_approx 2 = OCons (OCons OZero OZero) OZero.
Proof. reflexivity. Qed.

Theorem Gamma_0_approx_distinct : forall k,
  Gamma_0_approx k <> Gamma_0_approx (S k).
Proof.
  intro k. unfold Gamma_0_approx. simpl.
  apply not_eq_sym. apply Veblen_phi_0_unequal.
Qed.

Lemma Gamma_0_approx_S : forall k,
  Gamma_0_approx (S k) = OCons (Gamma_0_approx k) OZero.
Proof. intro k. reflexivity. Qed.

Lemma Gamma_0_approx_strictly_increasing : forall j,
  ord_compare (Gamma_0_approx j) (Gamma_0_approx (S j)) = Lt.
Proof.
  induction j as [|j IH].
  - reflexivity.
  - rewrite (Gamma_0_approx_S (S j)).
    rewrite (Gamma_0_approx_S j).
    rewrite ord_compare_OCons_OZero.
    rewrite <- (Gamma_0_approx_S j).
    exact IH.
Qed.

Lemma Veblen_phi_0_wf : forall alpha, wf_ord alpha -> wf_ord (Veblen_phi_0 alpha).
Proof.
  intros alpha Hwf. unfold Veblen_phi_0.
  cbn. split; [exact Hwf | split; [exact I | exact I]].
Qed.

Lemma Veblen_phi_iter_wf : forall k alpha, wf_ord alpha -> wf_ord (Veblen_phi_iter k alpha).
Proof.
  induction k as [|k IH]; intros alpha Halpha; cbn.
  - exact Halpha.
  - apply Veblen_phi_0_wf. apply IH. exact Halpha.
Qed.

Lemma Gamma_0_approx_wf : forall k, wf_ord (Gamma_0_approx k).
Proof.
  intros k. unfold Gamma_0_approx. apply Veblen_phi_iter_wf. exact I.
Qed.

Lemma Veblen_phi_0_strictly_increasing : forall alpha beta,
  ord_compare alpha beta = Lt ->
  ord_compare (Veblen_phi_0 alpha) (Veblen_phi_0 beta) = Lt.
Proof.
  intros alpha beta H. unfold Veblen_phi_0.
  rewrite ord_compare_OCons_OZero. exact H.
Qed.

Lemma Veblen_phi_iter_strictly_increasing : forall k alpha beta,
  ord_compare alpha beta = Lt ->
  ord_compare (Veblen_phi_iter k alpha) (Veblen_phi_iter k beta) = Lt.
Proof.
  induction k as [|k IH]; intros alpha beta H.
  - exact H.
  - cbn. apply Veblen_phi_0_strictly_increasing. apply IH. exact H.
Qed.

Theorem Gamma_0_approx_unbounded : forall k,
  exists o : ord, ord_compare (Gamma_0_approx k) o = Lt.
Proof.
  intro k. exists (Gamma_0_approx (S k)).
  exact (Gamma_0_approx_strictly_increasing k).
Qed.

Theorem Gamma_0_bounds_predicative_strength_via_iteration : forall k,
  exists o : ord, o = Gamma_0_approx k /\
                  (k > 0 -> ord_compare OZero o = Lt).
Proof.
  intro k. exists (Gamma_0_approx k). split.
  - reflexivity.
  - intro Hk. destruct k; [lia|].
    unfold Gamma_0_approx. simpl. reflexivity.
Qed.

Definition is_Veblen_fixed_point (f : ord -> ord) (o : ord) : Prop :=
  f o = o.

Theorem Veblen_phi_0_no_fixed_point_in_image_of_OZero :
  forall k, Veblen_phi_0 (Gamma_0_approx k) <> OZero.
Proof. intro k. simpl. discriminate. Qed.

Lemma omega_tower_eq_Gamma_0_approx_S : forall n,
  omega_tower n = Gamma_0_approx (S n).
Proof.
  induction n as [|n IH].
  - reflexivity.
  - cbn [omega_tower].
    rewrite IH.
    rewrite Gamma_0_approx_S.
    reflexivity.
Qed.

Theorem Gamma_0_strictly_above_epsilon_0_witnesses : forall n,
  ord_compare (omega_tower n) (Gamma_0_approx (S (S n))) = Lt.
Proof.
  intro n. rewrite (omega_tower_eq_Gamma_0_approx_S n).
  exact (Gamma_0_approx_strictly_increasing (S n)).
Qed.

Definition worm_equiv (w1 w2 : Worm) : Prop :=
  worm_to_ord w1 = worm_to_ord w2.

Theorem worm_equiv_refl : forall w, worm_equiv w w.
Proof. intro w. unfold worm_equiv. reflexivity. Qed.

Theorem worm_equiv_sym : forall w1 w2, worm_equiv w1 w2 -> worm_equiv w2 w1.
Proof. intros w1 w2 H. unfold worm_equiv in *. symmetry. exact H. Qed.

Theorem worm_equiv_trans : forall w1 w2 w3,
  worm_equiv w1 w2 -> worm_equiv w2 w3 -> worm_equiv w1 w3.
Proof. intros w1 w2 w3 H1 H2. unfold worm_equiv in *. transitivity (worm_to_ord w2); assumption. Qed.

Theorem worm_equiv_iff_ord_eq : forall w1 w2,
  worm_equiv w1 w2 <-> worm_to_ord w1 = worm_to_ord w2.
Proof. intros w1 w2. unfold worm_equiv. tauto. Qed.

Theorem worm_to_ord_injective : forall w1 w2,
  worm_to_ord w1 = worm_to_ord w2 -> w1 = w2.
Proof.
  intros w1 w2 H.
  pose proof (ord_to_worm_left_inverse w1) as Hw1.
  pose proof (ord_to_worm_left_inverse w2) as Hw2.
  rewrite <- Hw1. rewrite <- Hw2. rewrite H. reflexivity.
Qed.

Theorem worm_equiv_iff_eq : forall w1 w2,
  worm_equiv w1 w2 <-> w1 = w2.
Proof.
  intros w1 w2. unfold worm_equiv. split.
  - exact (worm_to_ord_injective w1 w2).
  - intro H. subst. reflexivity.
Qed.

Definition order_isomorphism (f : Worm -> ord) (g : ord -> Worm) : Prop :=
  (forall w, g (f w) = w) /\
  (forall w1 w2, f w1 = f w2 -> w1 = w2).

Theorem worm_to_ord_is_order_isomorphism :
  order_isomorphism worm_to_ord ord_to_worm.
Proof.
  unfold order_isomorphism. split.
  - exact ord_to_worm_left_inverse.
  - exact worm_to_ord_injective.
Qed.

Theorem proof_theoretic_ordinal_equals_epsilon_0_via_isomorphism :
  exists (f : Worm -> ord) (g : ord -> Worm),
    (forall w, g (f w) = w) /\
    (forall w1 w2, f w1 = f w2 -> w1 = w2).
Proof.
  exists worm_to_ord, ord_to_worm.
  exact worm_to_ord_is_order_isomorphism.
Qed.

Theorem proof_theoretic_ordinal_GLP_equals_epsilon_0_carrier_via_worms :
  forall (alpha : epsilon_0_carrier),
  exists w : Worm, worm_to_ord w = worm_to_ord (ord_to_worm alpha).
Proof.
  intro alpha. exists (ord_to_worm alpha). reflexivity.
Qed.

Theorem proof_theoretic_ordinal_GLP_atomic_recovery : forall n,
  exists w : Worm, worm_to_ord w = OCons (nat_to_ord n) OZero.
Proof.
  intro n. exists [n]. simpl. reflexivity.
Qed.

Theorem worm_completeness_unique_ord_per_worm : forall w1 w2,
  worm_to_ord w1 = worm_to_ord w2 -> w1 = w2.
Proof. exact worm_to_ord_injective. Qed.

Theorem worm_completeness_every_ord_in_image_has_unique_worm : forall o,
  (exists w, worm_to_ord w = o) ->
  exists! w, worm_to_ord w = o.
Proof.
  intros o [w Hw]. exists w. split.
  - exact Hw.
  - intros w' Hw'.
    apply worm_to_ord_injective.
    rewrite Hw'. rewrite Hw. reflexivity.
Qed.

Theorem worm_completeness_provable_implication_via_ord : forall w1 w2,
  worm_to_ord w1 = worm_to_ord w2 ->
  |- Iff (worm_to_form w1) (worm_to_form w2).
Proof.
  intros w1 w2 H.
  apply worm_to_ord_injective in H. subst.
  exact (prov_iff_refl _).
Qed.

Theorem worm_completeness_ord_compare_distinguishes :
  exists w1 w2, ord_compare (worm_to_ord w1) (worm_to_ord w2) = Lt.
Proof.
  exists [], [0]. simpl. reflexivity.
Qed.

Definition worm_omega : Worm := [1].
Definition worm_omega_squared : Worm := [2].
Definition worm_unit : Worm := [0].
Definition worm_zero : Worm := [].

Theorem worm_zero_lt_unit_via_ord :
  ord_compare (worm_to_ord worm_zero) (worm_to_ord worm_unit) = Lt.
Proof. simpl. reflexivity. Qed.

Theorem worm_unit_lt_omega_via_ord :
  ord_compare (worm_to_ord worm_unit) (worm_to_ord worm_omega) = Lt.
Proof. simpl. reflexivity. Qed.

Theorem worm_omega_lt_omega_squared_via_ord :
  ord_compare (worm_to_ord worm_omega) (worm_to_ord worm_omega_squared) = Lt.
Proof. simpl. reflexivity. Qed.

Theorem worm_completeness_decoding : forall w,
  ord_to_worm (worm_to_ord w) = w.
Proof. exact ord_to_worm_left_inverse. Qed.

Theorem worm_form_provability_aligned_with_ord : forall w,
  |- worm_to_form w /\
  (worm_to_ord w = OZero <-> w = []).
Proof.
  intro w. split.
  - exact (worm_all_provable w).
  - split.
    + intro H. destruct w; [reflexivity|]. simpl in H. discriminate.
    + intro H. subst. reflexivity.
Qed.

Inductive arith_form : Type :=
  | A_falsity : arith_form
  | A_var : nat -> arith_form
  | A_impl : arith_form -> arith_form -> arith_form
  | A_Bew_n : nat -> arith_form -> arith_form.

Definition A_neg (a : arith_form) : arith_form := A_impl a A_falsity.

Fixpoint modal_to_arith (phi : Form) : arith_form :=
  match phi with
  | Var p => A_var p
  | Bot => A_falsity
  | Impl a b => A_impl (modal_to_arith a) (modal_to_arith b)
  | Box n a => A_Bew_n n (modal_to_arith a)
  end.

Inductive arith_provable : arith_form -> Prop :=
  | AP_K : forall a b, arith_provable (A_impl a (A_impl b a))
  | AP_S : forall a b c, arith_provable (A_impl (A_impl a (A_impl b c))
                                                (A_impl (A_impl a b) (A_impl a c)))
  | AP_DN : forall a, arith_provable (A_impl (A_neg (A_neg a)) a)
  | AP_BoxK : forall n a b,
      arith_provable (A_impl (A_Bew_n n (A_impl a b))
                             (A_impl (A_Bew_n n a) (A_Bew_n n b)))
  | AP_Loeb : forall n a,
      arith_provable (A_impl (A_Bew_n n (A_impl (A_Bew_n n a) a)) (A_Bew_n n a))
  | AP_Box4 : forall n a,
      arith_provable (A_impl (A_Bew_n n a) (A_Bew_n n (A_Bew_n n a)))
  | AP_Mon : forall n a, arith_provable (A_impl (A_Bew_n n a) (A_Bew_n (S n) a))
  | AP_NextCon : forall n,
      arith_provable (A_Bew_n (S n) (A_neg (A_Bew_n n A_falsity)))
  | AP_MP : forall a b, arith_provable (A_impl a b) -> arith_provable a -> arith_provable b
  | AP_Nec : forall n a, arith_provable a -> arith_provable (A_Bew_n n a).

Theorem modal_to_arith_preserves_provability : forall phi,
  |- phi -> arith_provable (modal_to_arith phi).
Proof.
  intros phi H. induction H; simpl.
  - apply AP_K.
  - apply AP_S.
  - apply AP_DN.
  - apply AP_BoxK.
  - apply AP_Loeb.
  - apply AP_Box4.
  - apply AP_Mon.
  - apply AP_NextCon.
  - apply AP_MP with (a := modal_to_arith phi); assumption.
  - apply AP_Nec. assumption.
Qed.


Theorem arith_provable_HBL_K : forall n a b,
  arith_provable (A_impl (A_Bew_n n (A_impl a b))
                         (A_impl (A_Bew_n n a) (A_Bew_n n b))).
Proof. exact AP_BoxK. Qed.

Theorem arith_provable_HBL_Loeb : forall n a,
  arith_provable (A_impl (A_Bew_n n (A_impl (A_Bew_n n a) a)) (A_Bew_n n a)).
Proof. exact AP_Loeb. Qed.

Theorem arith_provable_HBL_Nec : forall n a,
  arith_provable a -> arith_provable (A_Bew_n n a).
Proof. exact AP_Nec. Qed.

Theorem arith_interpretation_T_kappa_reflects_modal : forall n phi,
  |- T_kappa n phi -> arith_provable (A_Bew_n n (modal_to_arith phi)).
Proof.
  intros n phi H. unfold T_kappa in H.
  pose proof (modal_to_arith_preserves_provability _ H) as Hap.
  simpl in Hap. exact Hap.
Qed.

Theorem arith_interpretation_T_kappa_consistency : forall n,
  arith_provable (A_Bew_n (S n) (A_neg (A_Bew_n n A_falsity))).
Proof. intro n. exact (AP_NextCon n). Qed.

Definition Visser_interp_real (n : nat) (phi psi : Form) : Form :=
  Box n (Impl phi psi).

Theorem Visser_interp_real_ILM : forall n phi psi,
  |- Impl (Visser_interp_real n phi psi) (Impl (Box n phi) (Box n psi)).
Proof. intros. unfold Visser_interp_real. apply Ax_BoxK. Qed.

Theorem Visser_interp_real_ILP : forall n phi psi,
  |- Impl (Visser_interp_real n phi psi) (Box n (Visser_interp_real n phi psi)).
Proof. intros. unfold Visser_interp_real. apply Ax_Box4. Qed.

Theorem Visser_interp_real_J1_reflexivity : forall n phi,
  |- Visser_interp_real n phi phi.
Proof. intros n phi. unfold Visser_interp_real. exact (Nec n _ (prov_id phi)). Qed.

Theorem Visser_interp_real_J2_transitivity : forall n phi psi chi,
  |- Impl (Visser_interp_real n phi psi)
          (Impl (Visser_interp_real n psi chi) (Visser_interp_real n phi chi)).
Proof.
  intros n phi psi chi. unfold Visser_interp_real.
  pose proof (prov_compose_internal phi psi chi) as Hci.
  pose proof (prov_perm _ _ _ Hci) as Hci_perm.
  pose proof (Nec n _ Hci_perm) as Hci_n.
  pose proof (Ax_BoxK n (Impl phi psi)
    (Impl (Impl psi chi) (Impl phi chi))) as HK1.
  pose proof (MP _ _ HK1 Hci_n) as Hstep1.
  pose proof (Ax_BoxK n (Impl psi chi) (Impl phi chi)) as HK2.
  exact (prov_compose _ _ _ Hstep1 HK2).
Qed.

(** [Visser_interp_real_J3_conjunction]: the genuine J3 axiom of the
    Visser interpretability calculus.  In ILM/ILP, J3 reads
    [(phi ▷ psi) ∧ (phi ▷ chi) → phi ▷ (psi ∧ chi)] — the joint-target
    closure of interpretation.  Under the present packaging
    [phi ▷ psi := Box n (Impl phi psi)], it expands to
    [Box n (φ→ψ) ∧ Box n (φ→χ) → Box n (φ→ψ∧χ)], which is provable
    via [prov_pair_under_antecedent] necessitated and distributed
    twice through [Ax_BoxK]. *)

Lemma prov_pair_under_antecedent : forall phi psi chi,
  |- Impl (Impl phi psi) (Impl (Impl phi chi) (Impl phi (And psi chi))).
Proof.
  intros phi psi chi.
  pose proof (prov_and_intro psi chi) as H0.
  pose proof (prov_weaken _ phi H0) as H1.
  pose proof (Ax_S phi psi (Impl chi (And psi chi))) as Hs1.
  pose proof (MP _ _ Hs1 H1) as H2.
  pose proof (Ax_S phi chi (And psi chi)) as Hs2.
  exact (prov_compose _ _ _ H2 Hs2).
Qed.

Theorem Visser_interp_real_J3_conjunction : forall n phi psi chi,
  |- Impl (Visser_interp_real n phi psi)
       (Impl (Visser_interp_real n phi chi)
             (Visser_interp_real n phi (And psi chi))).
Proof.
  intros n phi psi chi. unfold Visser_interp_real.
  pose proof (prov_pair_under_antecedent phi psi chi) as Hcombine.
  pose proof (Nec n _ Hcombine) as HcombineN.
  pose proof (Ax_BoxK n (Impl phi psi)
    (Impl (Impl phi chi) (Impl phi (And psi chi)))) as HK1.
  pose proof (MP _ _ HK1 HcombineN) as Hstep1.
  pose proof (Ax_BoxK n (Impl phi chi) (Impl phi (And psi chi))) as HK2.
  exact (prov_compose _ _ _ Hstep1 HK2).
Qed.

Theorem Visser_interp_real_J3_meta : forall n phi psi chi,
  |- Visser_interp_real n phi psi ->
  |- Visser_interp_real n phi chi ->
  |- Visser_interp_real n phi (And psi chi).
Proof.
  intros n phi psi chi H1 H2.
  pose proof (Visser_interp_real_J3_conjunction n phi psi chi) as HJ3.
  exact (MP _ _ (MP _ _ HJ3 H1) H2).
Qed.

Theorem Visser_interp_real_J5_via_Mon : forall n phi psi,
  |- Impl (Visser_interp_real n phi psi) (Visser_interp_real (S n) phi psi).
Proof. intros. unfold Visser_interp_real. apply Ax_Mon. Qed.

Theorem Visser_interp_real_combines_with_Box : forall n phi psi,
  |- Visser_interp_real n phi psi ->
  |- Box n phi -> |- Box n psi.
Proof.
  intros n phi psi Hv Hphi.
  unfold Visser_interp_real in Hv.
  pose proof (Ax_BoxK n phi psi) as HK.
  pose proof (MP _ _ HK Hv) as Hstep.
  exact (MP _ _ Hstep Hphi).
Qed.

Theorem Visser_interp_real_uses_n_essentially : forall n phi psi,
  Visser_interp_real n phi psi <> Visser_interp_real (S n) phi psi.
Proof.
  intros n phi psi H. unfold Visser_interp_real in H.
  inversion H. lia.
Qed.

Definition Temporal_Box_real (t n : nat) (phi : Form) : Form :=
  Box t (Box n phi).

Theorem Temporal_Box_real_K_outer : forall t n phi psi,
  |- Impl (Temporal_Box_real t n (Impl phi psi))
          (Impl (Temporal_Box_real t n phi) (Temporal_Box_real t n psi)).
Proof.
  intros t n phi psi. unfold Temporal_Box_real.
  pose proof (Ax_BoxK n phi psi) as HK_inner.
  pose proof (Nec t _ HK_inner) as HK_inner_n.
  pose proof (Ax_BoxK t (Box n (Impl phi psi))
    (Impl (Box n phi) (Box n psi))) as HK_outer.
  pose proof (MP _ _ HK_outer HK_inner_n) as Hstep1.
  pose proof (Ax_BoxK t (Box n phi) (Box n psi)) as HK2.
  exact (prov_compose _ _ _ Hstep1 HK2).
Qed.

Theorem Temporal_Box_real_Loeb_at_outer_t : forall t n phi,
  |- Impl (Box t (Impl (Temporal_Box_real t n phi) (Box n phi)))
          (Temporal_Box_real t n phi).
Proof.
  intros t n phi. unfold Temporal_Box_real.
  exact (Ax_Loeb t (Box n phi)).
Qed.

Theorem Temporal_Box_real_uses_t_essentially :
  forall t n phi, Temporal_Box_real t n phi <> Temporal_Box_real (S t) n phi.
Proof.
  intros t n phi H. unfold Temporal_Box_real in H.
  inversion H. lia.
Qed.

Theorem Temporal_Box_real_uses_n_essentially :
  forall t n phi, Temporal_Box_real t n phi <> Temporal_Box_real t (S n) phi.
Proof.
  intros t n phi H. unfold Temporal_Box_real in H.
  inversion H. lia.
Qed.

Theorem Temporal_Box_real_strictly_more_structure_than_simple_sum :
  forall (t n : nat) (phi : Form),
  outer_box_level (Temporal_Box_real t n phi) = S t.
Proof.
  intros t n phi. unfold Temporal_Box_real, outer_box_level. reflexivity.
Qed.

Definition Graded_Bel_real (n p : nat) (phi : Form) : Form :=
  Box n (Impl (Box p phi) phi).

Theorem Graded_Bel_real_uses_p_essentially : forall n p phi,
  Graded_Bel_real n p phi <> Graded_Bel_real n (S p) phi.
Proof.
  intros n p phi H. unfold Graded_Bel_real in H.
  inversion H as [H1].
  inversion H1 as [H2].
  inversion H2 as [H3].
  lia.
Qed.

Theorem Graded_Bel_real_K_via_BoxK : forall n p phi psi,
  |- Impl (Box n (Impl (Impl (Box p phi) phi) (Impl (Box p psi) psi)))
          (Impl (Graded_Bel_real n p phi) (Graded_Bel_real n p psi)).
Proof.
  intros n p phi psi. unfold Graded_Bel_real.
  exact (Ax_BoxK n _ _).
Qed.

Theorem Graded_Bel_real_Loeb : forall n p phi,
  |- Impl (Box n (Impl (Graded_Bel_real n p phi) (Impl (Box p phi) phi)))
          (Graded_Bel_real n p phi).
Proof.
  intros n p phi. unfold Graded_Bel_real.
  exact (Ax_Loeb n (Impl (Box p phi) phi)).
Qed.

Theorem Probabilistic_Loeb_calibrated_by_p : forall n p phi,
  |- Impl (Graded_Bel_real n p phi)
          (Impl (Box n (Box p phi)) (Box n phi)).
Proof.
  intros n p phi. unfold Graded_Bel_real.
  exact (Ax_BoxK n (Box p phi) phi).
Qed.

Theorem Probabilistic_YH_bypass_real : forall n p phi,
  |- Impl (Graded_Bel_real n p phi) (Graded_Bel_real (S n) p phi).
Proof.
  intros n p phi. unfold Graded_Bel_real.
  exact (Ax_Mon n (Impl (Box p phi) phi)).
Qed.

Theorem Box4_derivable_in_full_Provable : forall n phi,
  |- Impl (Box n phi) (Box n (Box n phi)).
Proof.
  intros n phi. apply no_b4_to_provable. exact (nb4_axiom4 n phi).
Qed.

Theorem Box4_derivable_uses_only_no_B4_axioms : forall n phi,
  |-no_b4 Impl (Box n phi) (Box n (Box n phi)).
Proof. exact nb4_axiom4. Qed.

Theorem Box4_redundant_in_axiom_set : forall n phi,
  |- Impl (Box n phi) (Box n (Box n phi)) /\
  |-no_b4 Impl (Box n phi) (Box n (Box n phi)).
Proof.
  intros n phi. split.
  - exact (Box4_derivable_in_full_Provable n phi).
  - exact (Box4_derivable_uses_only_no_B4_axioms n phi).
Qed.

Theorem Provable_iff_Provable_no_B4 : forall phi,
  |- phi <-> |-no_b4 phi.
Proof. exact provable_iff_no_b4. Qed.

Theorem Box4_via_no_B4_calculus_strictly_redundant : forall n phi,
  (|- Impl (Box n phi) (Box n (Box n phi))) /\
  (|-no_b4 Impl (Box n phi) (Box n (Box n phi))) /\
  (forall psi, |- psi <-> |-no_b4 psi).
Proof.
  intros n phi. split; [|split].
  - exact (Box4_derivable_in_full_Provable n phi).
  - exact (Box4_derivable_uses_only_no_B4_axioms n phi).
  - exact provable_iff_no_b4.
Qed.

Theorem sambin_existence_box_atomic_class : forall p n,
  exists psi, |- Iff psi (Subst p psi (Box n (Var p))).
Proof.
  intros p n.
  exists Top. unfold Subst. simpl.
  rewrite Nat.eqb_refl.
  exact (fixedpoint_top_box n).
Qed.

Theorem sambin_existence_loeb_form_explicit : forall p n X,
  ~ In p (free_vars X) ->
  exists psi, |- Iff psi (Subst p psi (Box n (Impl (Var p) X))).
Proof.
  intros p n X HX.
  exists (Box n X).
  assert (HsubstBox : Subst p (Box n X) (Box n (Impl (Var p) X)) =
                     Box n (Impl (Box n X) X)).
  { unfold Subst. simpl. rewrite Nat.eqb_refl.
    pose proof (Subst_no_occurrence p (Box n X) X HX) as Heq.
    unfold Subst in Heq. rewrite Heq. reflexivity. }
  rewrite HsubstBox.
  exact (fixed_point_loeb_witness n X).
Qed.

Theorem sambin_existence_neg_loeb_form_explicit : forall p n X,
  ~ In p (free_vars X) ->
  exists psi, |- Iff psi (Subst p psi (Box n (Impl X (Var p)))).
Proof.
  intros p n X HX.
  apply fixed_point_existence_top_solves.
  unfold Subst. simpl. rewrite Nat.eqb_refl.
  pose proof (Subst_no_occurrence p Top X HX) as Heq.
  unfold Subst in Heq. rewrite Heq.
  pose proof (prov_weaken Top X (prov_id Bot)) as Himpl.
  exact (Nec n _ Himpl).
Qed.

Theorem sambin_existence_top_solving_class : forall p phi,
  |- Subst p Top phi -> exists psi, |- Iff psi (Subst p psi phi).
Proof. exact fixed_point_existence_top_solves. Qed.

Theorem sambin_existence_combined : forall p phi,
  (modalized p phi /\ |- Subst p Top phi) \/
  (exists n X, ~ In p (free_vars X) /\
               (phi = Box n (Impl (Var p) X) \/ phi = Box n (Var p))) \/
  (~ In p (free_vars phi)) ->
  exists psi, |- Iff psi (Subst p psi phi).
Proof.
  intros p phi [[_ Htop] | [[n [X [HX [Hloeb | Hatomic]]]] | Hno]].
  - exact (fixed_point_existence_top_solves p phi Htop).
  - subst phi. exact (sambin_existence_loeb_form_explicit p n X HX).
  - subst phi. apply sambin_existence_box_atomic_class.
  - exists phi.
    rewrite (Subst_no_occurrence p phi phi Hno).
    exact (prov_iff_refl phi).
Qed.

Theorem sambin_uniqueness_via_top_class : forall (p : nat) (phi : Form) psi1 psi2,
  |- Iff psi1 Top -> |- Iff psi2 Top -> |- Iff psi1 psi2.
Proof.
  intros p phi psi1 psi2 E1 E2.
  pose proof (prov_iff_sym _ _ E2) as E2sym.
  exact (prov_equiv_trans _ _ _ E1 E2sym).
Qed.

Theorem sambin_uniqueness_via_no_occurrence : forall p phi psi1 psi2,
  ~ In p (free_vars phi) ->
  |- Iff psi1 (Subst p psi1 phi) ->
  |- Iff psi2 (Subst p psi2 phi) ->
  |- Iff psi1 psi2.
Proof.
  intros p phi psi1 psi2 Hno H1 H2.
  rewrite (Subst_no_occurrence p psi1 phi Hno) in H1.
  rewrite (Subst_no_occurrence p psi2 phi Hno) in H2.
  pose proof (prov_iff_sym _ _ H2) as H2sym.
  exact (prov_equiv_trans _ _ _ H1 H2sym).
Qed.

Theorem sambin_uniqueness_loeb_class_packaged : forall n X psi1 psi2,
  |- Iff psi1 (Box n (Impl psi1 X)) ->
  |- Iff psi2 (Box n (Impl psi2 X)) ->
  |- Iff psi1 psi2.
Proof. exact fixed_point_unique_loeb_form. Qed.

Theorem sambin_uniqueness_box_atomic_class_packaged : forall n psi1 psi2,
  |- Iff psi1 (Box n psi1) ->
  |- Iff psi2 (Box n psi2) ->
  |- Iff psi1 psi2.
Proof. exact same_level_fixed_point_uniqueness. Qed.

Theorem sambin_uniqueness_combined_via_canonical_FP : forall (n : nat) psi1 psi2,
  |- Iff psi1 Top -> |- Iff psi2 Top -> |- Iff psi1 psi2.
Proof.
  intros n psi1 psi2 E1 E2.
  exact (sambin_uniqueness_via_top_class n Top psi1 psi2 E1 E2).
Qed.

Theorem sambin_uniqueness_at_higher_box_level : forall (p : nat) (phi : Form) psi1 psi2 n,
  ~ In p (free_vars phi) ->
  |- Iff psi1 (Subst p psi1 phi) ->
  |- Iff psi2 (Subst p psi2 phi) ->
  |- Box n (Iff psi1 psi2).
Proof.
  intros p phi psi1 psi2 n Hno H1 H2.
  apply Nec.
  exact (sambin_uniqueness_via_no_occurrence p phi psi1 psi2 Hno H1 H2).
Qed.

Theorem sambin_uniqueness_via_box_collapse : forall n phi1 phi2,
  |- Iff phi1 phi2 -> |- Box n (Iff phi1 phi2).
Proof. intros n phi1 phi2 H. exact (Nec n _ H). Qed.

(******************************************************************************)
(* Substantive Craig interpolation for the box-free fragment via variable     *)
(* elimination.  The classical construction: define                            *)
(*   forget_var p phi := (phi[p:=Top]) ∨ (phi[p:=Bot])                         *)
(* eliminating one private variable; iterate over all variables of phi not    *)
(* occurring in psi.  The resulting interpolant chi has free_vars strictly    *)
(* contained in free_vars phi ∩ free_vars psi.                                 *)
(******************************************************************************)

Lemma eval_subst_box_free : forall val sigma phi,
  box_free phi ->
  eval val (subst_form sigma phi) = eval (fun k => eval val (sigma k)) phi.
Proof.
  intros val sigma phi. revert val sigma.
  induction phi as [k | | a IHa b IHb | n a IHa]; intros val sigma Hbf; cbn in *.
  - reflexivity.
  - reflexivity.
  - destruct Hbf as [Ha Hb]. rewrite (IHa val sigma Ha), (IHb val sigma Hb).
    reflexivity.
  - exfalso; exact Hbf.
Qed.

Definition update_val (val : nat -> bool) (p : nat) (b : bool) (k : nat) : bool :=
  if Nat.eqb k p then b else val k.

Lemma eval_Subst_box_free : forall val p X phi,
  box_free phi ->
  eval val (Subst p X phi) = eval (update_val val p (eval val X)) phi.
Proof.
  intros val p X phi Hbf. unfold Subst.
  rewrite (eval_subst_box_free val _ phi Hbf).
  apply eval_ext_on_free_vars.
  intros q _. cbn beta. unfold update_val.
  destruct (Nat.eqb q p); reflexivity.
Qed.

Lemma eval_Top_true : forall val, eval val Top = true.
Proof. intro val. cbn. reflexivity. Qed.

Lemma eval_Bot_false : forall val, eval val Bot = false.
Proof. intro val. cbn. reflexivity. Qed.

Lemma box_free_Top : box_free Top.
Proof. cbn. split; exact I. Qed.

Lemma box_free_Bot : box_free Bot.
Proof. cbn. exact I. Qed.

Lemma box_free_subst_form : forall sigma phi,
  box_free phi ->
  (forall p, In p (free_vars phi) -> box_free (sigma p)) ->
  box_free (subst_form sigma phi).
Proof.
  intros sigma phi. revert sigma.
  induction phi as [k | | a IHa b IHb | n a IHa]; intros sigma Hbf Hsig; cbn in *.
  - apply Hsig. left. reflexivity.
  - exact I.
  - destruct Hbf as [Ha Hb]. split.
    + apply IHa; [exact Ha|]. intros p Hp. apply Hsig. apply in_or_app. left. exact Hp.
    + apply IHb; [exact Hb|]. intros p Hp. apply Hsig. apply in_or_app. right. exact Hp.
  - exfalso; exact Hbf.
Qed.

Lemma box_free_Subst : forall p X phi,
  box_free phi -> box_free X ->
  box_free (Subst p X phi).
Proof.
  intros p X phi Hbf HX. unfold Subst.
  apply box_free_subst_form; [exact Hbf|].
  intros q _. destruct (Nat.eqb q p) eqn:E.
  - exact HX.
  - cbn. exact I.
Qed.

Definition forget_var (p : nat) (phi : Form) : Form :=
  Or (Subst p Top phi) (Subst p Bot phi).

Lemma box_free_forget_var : forall p phi,
  box_free phi -> box_free (forget_var p phi).
Proof.
  intros p phi Hbf. unfold forget_var, Or, Neg.
  cbn. split.
  - split; [apply box_free_Subst; [exact Hbf|exact box_free_Top] | exact I].
  - apply box_free_Subst; [exact Hbf|exact box_free_Bot].
Qed.

Lemma eval_Or : forall val A B,
  eval val (Or A B) = orb (eval val A) (eval val B).
Proof.
  intros val A B. unfold Or, Neg. cbn.
  destruct (eval val A); destruct (eval val B); reflexivity.
Qed.

Lemma eval_Impl : forall val A B,
  eval val (Impl A B) = orb (negb (eval val A)) (eval val B).
Proof. intros val A B. cbn. reflexivity. Qed.

Lemma eval_forget_var_intro : forall val p phi,
  box_free phi ->
  eval val phi = true ->
  eval val (forget_var p phi) = true.
Proof.
  intros val p phi Hbf Hev. unfold forget_var.
  rewrite eval_Or.
  rewrite (eval_Subst_box_free val p Top phi Hbf).
  rewrite (eval_Subst_box_free val p Bot phi Hbf).
  rewrite eval_Top_true, eval_Bot_false.
  destruct (val p) eqn:Vp.
  - assert (Hxt : eval (update_val val p true) phi = eval val phi).
    { apply eval_ext_on_free_vars. intros q _.
      unfold update_val. destruct (Nat.eqb q p) eqn:E.
      - apply Nat.eqb_eq in E. subst q. symmetry. exact Vp.
      - reflexivity. }
    rewrite Hxt, Hev. reflexivity.
  - assert (Hxf : eval (update_val val p false) phi = eval val phi).
    { apply eval_ext_on_free_vars. intros q _.
      unfold update_val. destruct (Nat.eqb q p) eqn:E.
      - apply Nat.eqb_eq in E. subst q. symmetry. exact Vp.
      - reflexivity. }
    rewrite Hxf, Hev.
    destruct (eval (update_val val p true) phi); reflexivity.
Qed.

Lemma eval_forget_var_elim : forall val p phi psi,
  box_free phi -> box_free psi ->
  ~ In p (free_vars psi) ->
  (forall val', eval val' (Impl phi psi) = true) ->
  eval val (forget_var p phi) = true ->
  eval val psi = true.
Proof.
  intros val p phi psi Hbf_phi Hbf_psi Hp_notin Himp Hfg.
  unfold forget_var in Hfg. rewrite eval_Or in Hfg.
  rewrite (eval_Subst_box_free val p Top phi Hbf_phi) in Hfg.
  rewrite (eval_Subst_box_free val p Bot phi Hbf_phi) in Hfg.
  rewrite eval_Top_true, eval_Bot_false in Hfg.
  apply Bool.orb_true_iff in Hfg. destruct Hfg as [Hf | Hf].
  - pose proof (Himp (update_val val p true)) as Himp_t.
    rewrite eval_Impl in Himp_t. rewrite Hf in Himp_t. cbn in Himp_t.
    assert (Hpsi_eq : eval (update_val val p true) psi = eval val psi).
    { apply eval_ext_on_free_vars. intros q Hq.
      unfold update_val. destruct (Nat.eqb q p) eqn:E; [|reflexivity].
      apply Nat.eqb_eq in E. subst q. exfalso. exact (Hp_notin Hq). }
    rewrite Hpsi_eq in Himp_t. exact Himp_t.
  - pose proof (Himp (update_val val p false)) as Himp_f.
    rewrite eval_Impl in Himp_f. rewrite Hf in Himp_f. cbn in Himp_f.
    assert (Hpsi_eq : eval (update_val val p false) psi = eval val psi).
    { apply eval_ext_on_free_vars. intros q Hq.
      unfold update_val. destruct (Nat.eqb q p) eqn:E; [|reflexivity].
      apply Nat.eqb_eq in E. subst q. exfalso. exact (Hp_notin Hq). }
    rewrite Hpsi_eq in Himp_f. exact Himp_f.
Qed.

Theorem prov_forget_var_intro : forall p phi,
  box_free phi -> |- Impl phi (forget_var p phi).
Proof.
  intros p phi Hbf.
  apply trivial_in_provable. apply prop_completeness.
  - cbn. split; [exact Hbf|]. apply box_free_forget_var. exact Hbf.
  - intro val. rewrite eval_Impl.
    destruct (eval val phi) eqn:Ephi.
    + rewrite (eval_forget_var_intro val p phi Hbf Ephi). reflexivity.
    + reflexivity.
Qed.

Theorem prov_forget_var_elim : forall p phi psi,
  box_free phi -> box_free psi ->
  ~ In p (free_vars psi) ->
  |- Impl phi psi -> |- Impl (forget_var p phi) psi.
Proof.
  intros p phi psi Hbf_phi Hbf_psi Hp_notin Himp.
  apply trivial_in_provable. apply prop_completeness.
  - cbn. split; [|exact Hbf_psi]. apply box_free_forget_var. exact Hbf_phi.
  - intro val. rewrite eval_Impl.
    destruct (eval val (forget_var p phi)) eqn:Efg; [|reflexivity].
    rewrite (eval_forget_var_elim val p phi psi Hbf_phi Hbf_psi Hp_notin
              (provable_classically_valid _ Himp) Efg).
    reflexivity.
Qed.

(** Substituting a closed formula (free_vars empty) for variable [p] in
    [phi] produces a formula whose free variables are exactly those of
    [phi] minus [p]. *)

Lemma free_vars_Subst_closed_fwd : forall p X phi v,
  free_vars X = [] ->
  In v (free_vars (Subst p X phi)) ->
  v <> p /\ In v (free_vars phi).
Proof.
  intros p X phi v HX.
  unfold Subst.
  induction phi as [k | | a IHa b IHb | n psi IHpsi]; cbn.
  - destruct (Nat.eqb k p) eqn:E.
    + rewrite HX. intros [].
    + cbn. intros [Heq|[]]. subst v.
      apply Nat.eqb_neq in E. split.
      * exact E.
      * left. reflexivity.
  - intros [].
  - rewrite in_app_iff. intros [HA | HB].
    + destruct (IHa HA) as [Hne Hin]. split; [exact Hne|].
      apply in_or_app. left. exact Hin.
    + destruct (IHb HB) as [Hne Hin]. split; [exact Hne|].
      apply in_or_app. right. exact Hin.
  - exact IHpsi.
Qed.

Lemma free_vars_Subst_closed_bwd : forall p X phi v,
  v <> p ->
  In v (free_vars phi) ->
  In v (free_vars (Subst p X phi)).
Proof.
  intros p X phi v Hne.
  unfold Subst.
  induction phi as [k | | a IHa b IHb | n psi IHpsi]; cbn.
  - intros [Heq | []]. subst v.
    destruct (Nat.eqb k p) eqn:E.
    + apply Nat.eqb_eq in E. exfalso. apply Hne. exact E.
    + cbn. left. reflexivity.
  - intros [].
  - rewrite in_app_iff. intros [HA|HB].
    + apply in_or_app. left. exact (IHa HA).
    + apply in_or_app. right. exact (IHb HB).
  - exact IHpsi.
Qed.

Lemma free_vars_forget_var_no_p : forall p phi v,
  In v (free_vars (forget_var p phi)) -> v <> p /\ In v (free_vars phi).
Proof.
  intros p phi v Hin.
  unfold forget_var, Or, Neg in Hin. cbn in Hin.
  rewrite app_nil_r in Hin.
  apply in_app_or in Hin. destruct Hin as [HA | HB].
  - apply (free_vars_Subst_closed_fwd p Top phi v eq_refl HA).
  - apply (free_vars_Subst_closed_fwd p Bot phi v eq_refl HB).
Qed.

Lemma free_vars_forget_var_subset : forall p phi v,
  In v (free_vars (forget_var p phi)) -> In v (free_vars phi).
Proof.
  intros p phi v H. exact (proj2 (free_vars_forget_var_no_p p phi v H)).
Qed.

Lemma free_vars_forget_var_excludes : forall p phi,
  ~ In p (free_vars (forget_var p phi)).
Proof.
  intros p phi H. apply (proj1 (free_vars_forget_var_no_p p phi p H)).
  reflexivity.
Qed.

(** Iterated variable elimination over a list of variables. *)

Fixpoint forget_vars (vs : list nat) (phi : Form) : Form :=
  match vs with
  | [] => phi
  | p :: rest => forget_vars rest (forget_var p phi)
  end.

Lemma box_free_forget_vars : forall vs phi,
  box_free phi -> box_free (forget_vars vs phi).
Proof.
  induction vs as [|p rest IH]; intros phi Hbf; cbn.
  - exact Hbf.
  - apply IH. apply box_free_forget_var. exact Hbf.
Qed.

Lemma free_vars_forget_vars_subset : forall vs phi v,
  In v (free_vars (forget_vars vs phi)) -> In v (free_vars phi).
Proof.
  induction vs as [|p rest IH]; intros phi v H; cbn in H.
  - exact H.
  - apply (free_vars_forget_var_subset p phi v).
    apply (IH (forget_var p phi) v H).
Qed.

Lemma free_vars_forget_vars_excludes : forall vs phi p,
  In p vs -> ~ In p (free_vars (forget_vars vs phi)).
Proof.
  induction vs as [|q rest IH]; intros phi p Hin Habs; cbn in *.
  - destruct Hin.
  - destruct Hin as [Heq | Hin'].
    + subst q.
      pose proof (free_vars_forget_vars_subset rest (forget_var p phi) p Habs)
        as Hin0.
      exact (free_vars_forget_var_excludes p phi Hin0).
    + exact (IH (forget_var q phi) p Hin' Habs).
Qed.

Theorem prov_forget_vars_intro : forall vs phi,
  box_free phi -> |- Impl phi (forget_vars vs phi).
Proof.
  induction vs as [|p rest IH]; intros phi Hbf; cbn.
  - exact (prov_id phi).
  - pose proof (prov_forget_var_intro p phi Hbf) as H1.
    pose proof (box_free_forget_var p phi Hbf) as Hbf'.
    pose proof (IH (forget_var p phi) Hbf') as H2.
    exact (prov_compose _ _ _ H1 H2).
Qed.

Theorem prov_forget_vars_elim : forall vs phi psi,
  box_free phi -> box_free psi ->
  (forall p, In p vs -> ~ In p (free_vars psi)) ->
  |- Impl phi psi -> |- Impl (forget_vars vs phi) psi.
Proof.
  induction vs as [|p rest IH]; intros phi psi Hbf_phi Hbf_psi Hdisj Himp; cbn.
  - exact Himp.
  - pose proof (Hdisj p (or_introl eq_refl)) as Hp_notin.
    pose proof (prov_forget_var_elim p phi psi Hbf_phi Hbf_psi Hp_notin Himp)
      as Hstep.
    pose proof (box_free_forget_var p phi Hbf_phi) as Hbf_fg.
    apply (IH (forget_var p phi) psi Hbf_fg Hbf_psi).
    + intros q Hq. apply Hdisj. right. exact Hq.
    + exact Hstep.
Qed.

(** Compute the list of "private" variables of [phi] with respect to
    [psi] — those occurring in [phi] but not in [psi]. *)

Definition private_vars (phi psi : Form) : list nat :=
  filter (fun v => negb (existsb (Nat.eqb v) (free_vars psi))) (free_vars phi).

Lemma private_vars_in_phi : forall phi psi v,
  In v (private_vars phi psi) -> In v (free_vars phi).
Proof.
  intros phi psi v Hin. unfold private_vars in Hin.
  apply filter_In in Hin. exact (proj1 Hin).
Qed.

Lemma existsb_eqb_in_iff : forall (l : list nat) (v : nat),
  existsb (Nat.eqb v) l = true <-> In v l.
Proof.
  intros l v. induction l as [|x rest IH]; cbn.
  - split; [discriminate | intros []].
  - rewrite Bool.orb_true_iff. split.
    + intros [Heq | Hrest].
      * left. apply Nat.eqb_eq in Heq. symmetry. exact Heq.
      * right. apply IH. exact Hrest.
    + intros [Heq | Hin].
      * subst x. left. apply Nat.eqb_refl.
      * right. apply IH. exact Hin.
Qed.

Lemma private_vars_not_in_psi : forall phi psi v,
  In v (private_vars phi psi) -> ~ In v (free_vars psi).
Proof.
  intros phi psi v Hin. unfold private_vars in Hin.
  apply filter_In in Hin. destruct Hin as [_ Hneg].
  destruct (existsb (Nat.eqb v) (free_vars psi)) eqn:E; [discriminate|].
  intro Habs. rewrite (proj2 (existsb_eqb_in_iff _ v) Habs) in E.
  discriminate.
Qed.

Lemma private_vars_complete : forall phi psi v,
  In v (free_vars phi) -> ~ In v (free_vars psi) ->
  In v (private_vars phi psi).
Proof.
  intros phi psi v Hphi Hpsi. unfold private_vars.
  apply filter_In. split; [exact Hphi|].
  destruct (existsb (Nat.eqb v) (free_vars psi)) eqn:E; [|reflexivity].
  exfalso. apply Hpsi. apply (proj1 (existsb_eqb_in_iff _ v)). exact E.
Qed.

(** ** Vocabulary-restricted Craig interpolation, box-free fragment.

    For any provable implication [|- Impl phi psi] between two box-free
    formulas, there is a box-free interpolant [chi] whose free variables
    are contained in the intersection of the free variables of [phi]
    and [psi].  The interpolant is constructed by iteratively
    eliminating the "private" variables of [phi] (those not in [psi])
    via [forget_var], yielding [chi := forget_vars (private_vars phi psi) phi]. *)

Theorem craig_interpolation_box_free : forall phi psi,
  box_free phi -> box_free psi ->
  |- Impl phi psi ->
  exists chi,
    box_free chi /\
    |- Impl phi chi /\ |- Impl chi psi /\
    (forall v, In v (free_vars chi) ->
       In v (free_vars phi) /\ In v (free_vars psi)).
Proof.
  intros phi psi Hbf_phi Hbf_psi Himp.
  set (priv := private_vars phi psi).
  exists (forget_vars priv phi).
  split; [|split; [|split]].
  - apply box_free_forget_vars. exact Hbf_phi.
  - exact (prov_forget_vars_intro priv phi Hbf_phi).
  - apply prov_forget_vars_elim; try assumption.
    intros p Hp. apply private_vars_not_in_psi with (phi := phi). exact Hp.
  - intros v Hin.
    pose proof (free_vars_forget_vars_subset priv phi v Hin) as Hphi.
    split; [exact Hphi|].
    destruct (in_dec Nat.eq_dec v (free_vars psi)) as [Hpsi|Hnpsi].
    + exact Hpsi.
    + exfalso. apply (free_vars_forget_vars_excludes priv phi v).
      * apply private_vars_complete; assumption.
      * exact Hin.
Qed.

(** ** Substantive consequences of box-free Craig interpolation.

    These replace the deleted trivial-witness placeholders.  Each is
    derived from [craig_interpolation_box_free] and inherits the
    vocabulary-restriction guarantee FV(chi) ⊆ FV(phi) ∩ FV(psi). *)

(** Box-free Maehara lemma: every box-free implication has a box-free
    interpolant of strictly bounded vocabulary.  Substantive replacement
    for the deleted [Maehara_lemma_via_self_interpolation] (which
    returned [And phi (Impl phi psi)]). *)

Theorem maehara_lemma_box_free : forall phi psi,
  box_free phi -> box_free psi ->
  |- Impl phi psi ->
  exists chi,
    box_free chi /\
    |- Impl phi chi /\ |- Impl chi psi /\
    (forall v, In v (free_vars chi) ->
       In v (free_vars phi) /\ In v (free_vars psi)).
Proof. exact craig_interpolation_box_free. Qed.

(** Box-free Beth explicit definability: if [phi] implicitly defines
    [psi] (in the sense that [|- Impl phi psi]) and [psi] does not
    mention a variable [p], then there is an explicit definition
    [chi] of [psi] from [phi] that also avoids [p].  Substantive
    replacement for the deleted [beth_implicit_to_explicit] (witness
    [def := psi]).  Here the witness [chi] is constructed by Craig
    interpolation, so [chi] genuinely sits between [phi] and [psi]
    in vocabulary, not just at one of the endpoints. *)

Theorem beth_explicit_definability_box_free : forall phi psi p,
  box_free phi -> box_free psi ->
  ~ In p (free_vars psi) ->
  |- Impl phi psi ->
  exists chi,
    box_free chi /\
    |- Impl phi chi /\ |- Impl chi psi /\
    ~ In p (free_vars chi).
Proof.
  intros phi psi p Hbf_phi Hbf_psi Hp_notin Himp.
  destruct (craig_interpolation_box_free phi psi Hbf_phi Hbf_psi Himp)
    as [chi [Hbf [Hf [Hb Hsub]]]].
  exists chi. split; [|split; [|split]].
  - exact Hbf.
  - exact Hf.
  - exact Hb.
  - intro Habs. apply Hp_notin. exact (proj2 (Hsub p Habs)).
Qed.

(** Lyndon-style polarity-restricted Beth corollary: if [phi]
    syntactically excludes a variable [p], then so does the Craig
    interpolant.  Substantive replacement for the deleted
    [lyndon_interpolation_via_craig_subset] (witness [chi = phi]) and
    [lyndon_polarity_preserved_when_identical_interpolant].  Full
    Lyndon polarity tracking requires the cut-free sequent calculus
    and remains under todo item 18. *)

Theorem lyndon_excluded_variable_box_free : forall phi psi p,
  box_free phi -> box_free psi ->
  ~ In p (free_vars phi) ->
  |- Impl phi psi ->
  exists chi,
    box_free chi /\
    |- Impl phi chi /\ |- Impl chi psi /\
    ~ In p (free_vars chi).
Proof.
  intros phi psi p Hbf_phi Hbf_psi Hp_notin Himp.
  destruct (craig_interpolation_box_free phi psi Hbf_phi Hbf_psi Himp)
    as [chi [Hbf [Hf [Hb Hsub]]]].
  exists chi. split; [|split; [|split]].
  - exact Hbf.
  - exact Hf.
  - exact Hb.
  - intro Habs. apply Hp_notin. exact (proj1 (Hsub p Habs)).
Qed.

(** Closed-form Craig: if both [phi] and [psi] are box-free and
    closed (no free variables), the interpolant is also closed.
    Substantive replacement for the deleted [craig_closed_interpolation]
    (which returned [chi = phi] without using closure of [psi]). *)

Theorem craig_interpolation_box_free_closed : forall phi psi,
  box_free phi -> box_free psi ->
  free_vars phi = [] -> free_vars psi = [] ->
  |- Impl phi psi ->
  exists chi,
    box_free chi /\ free_vars chi = [] /\
    |- Impl phi chi /\ |- Impl chi psi.
Proof.
  intros phi psi Hbf_phi Hbf_psi Hcphi Hcpsi Himp.
  destruct (craig_interpolation_box_free phi psi Hbf_phi Hbf_psi Himp)
    as [chi [Hbf [Hf [Hb Hsub]]]].
  exists chi. split; [|split; [|split]].
  - exact Hbf.
  - destruct (free_vars chi) as [|v rest] eqn:Echi; [reflexivity|].
    exfalso.
    destruct (Hsub v (or_introl eq_refl)) as [Hphi _].
    rewrite Hcphi in Hphi. exact Hphi.
  - exact Hf.
  - exact Hb.
Qed.

(** ** Polymodal (box-level) Craig interpolation.

    [box_levels] is the structural list of box levels.  The box-level-
    constrained form fails for GLP*: the Mon axiom proves
    [Box 0 (Var 0) -> Box 1 (Var 0)] with disjoint box-levels, forcing a
    box-free interpolant; the phi-side makes it a tautology (hence
    provable) and the psi-side then proves [Box 1 (Var 0)], refuted in
    Fnat ([craig_interpolation_polymodal_refuted]).  The box-free
    four-condition form holds ([craig_interpolation_polymodal_box_free]),
    reusing [craig_interpolation_box_free] and [free_vars]. *)

Fixpoint box_levels (phi : Form) : list nat :=
  match phi with
  | Var _ => []
  | Bot => []
  | Impl a b => box_levels a ++ box_levels b
  | Box n a => n :: box_levels a
  end.

Lemma box_free_box_levels_nil : forall phi,
  box_free phi -> box_levels phi = [].
Proof.
  induction phi as [p | | a IHa b IHb | n a IHa]; cbn; intro Hbf.
  - reflexivity.
  - reflexivity.
  - destruct Hbf as [Ha Hb]. rewrite (IHa Ha), (IHb Hb). reflexivity.
  - contradiction.
Qed.

Lemma box_free_of_no_box_levels : forall phi,
  (forall m, ~ In m (box_levels phi)) -> box_free phi.
Proof.
  induction phi as [p | | a IHa b IHb | n a IHa]; cbn; intro Hno.
  - exact I.
  - exact I.
  - split.
    + apply IHa. intros m Hm. apply (Hno m). apply in_or_app. left. exact Hm.
    + apply IHb. intros m Hm. apply (Hno m). apply in_or_app. right. exact Hm.
  - exfalso. apply (Hno n). left. reflexivity.
Qed.

Lemma not_provable_Box1_Var0 : ~ |- Box 1 (Var 0).
Proof.
  intro H.
  pose proof (soundness _ H Fnat (fun _ _ => false) 2) as Hf.
  specialize (Hf 1).
  assert (HR : Fnat_R 1 2 1) by (unfold Fnat_R; split; lia).
  specialize (Hf HR).
  cbn in Hf. discriminate Hf.
Qed.

Theorem craig_interpolation_polymodal_refuted :
  ~ (forall phi psi,
        |- Impl phi psi ->
        exists chi,
          (forall x, In x (free_vars chi) ->
             In x (free_vars phi) /\ In x (free_vars psi)) /\
          (forall n, In n (box_levels chi) ->
             In n (box_levels phi) /\ In n (box_levels psi)) /\
          |- Impl phi chi /\ |- Impl chi psi).
Proof.
  intro Hcraig.
  destruct (Hcraig (Box 0 (Var 0)) (Box 1 (Var 0)) (Ax_Mon 0 (Var 0)))
    as [chi [_ [Hboxes [Hpc Hcp]]]].
  assert (Hnobox : forall m, ~ In m (box_levels chi)).
  { intros m Hin. destruct (Hboxes m Hin) as [Hin0 Hin1].
    cbn in Hin0, Hin1.
    destruct Hin0 as [Heq0 | []]. destruct Hin1 as [Heq1 | []].
    subst m. discriminate Heq1. }
  assert (Hbf : box_free chi) by (apply box_free_of_no_box_levels; exact Hnobox).
  assert (Hcv : classical_valid chi).
  { intro val.
    pose proof (provable_classically_valid _ Hpc val) as Hval.
    cbn in Hval. exact Hval. }
  pose proof (trivial_in_provable chi (prop_completeness chi Hbf Hcv)) as Hchi.
  pose proof (MP _ _ Hcp Hchi) as Hbox1.
  exact (not_provable_Box1_Var0 Hbox1).
Qed.

Theorem craig_interpolation_polymodal_box_free : forall phi psi,
  box_free phi -> box_free psi ->
  |- Impl phi psi ->
  exists chi,
    (forall x, In x (free_vars chi) ->
       In x (free_vars phi) /\ In x (free_vars psi)) /\
    (forall n, In n (box_levels chi) ->
       In n (box_levels phi) /\ In n (box_levels psi)) /\
    |- Impl phi chi /\ |- Impl chi psi.
Proof.
  intros phi psi Hbf_phi Hbf_psi Himp.
  destruct (craig_interpolation_box_free phi psi Hbf_phi Hbf_psi Himp)
    as [chi [Hbf_chi [Hintro [Helim Hvars]]]].
  exists chi. split; [|split; [|split]].
  - intros x Hx. exact (Hvars x Hx).
  - intros n Hn.
    rewrite (box_free_box_levels_nil chi Hbf_chi) in Hn.
    destruct Hn.
  - exact Hintro.
  - exact Helim.
Qed.

Theorem craig_polymodal_maehara_box_free : forall phi1 phi2 psi,
  box_free phi1 -> box_free phi2 -> box_free psi ->
  |- Impl phi1 (Impl phi2 psi) ->
  exists chi,
    (forall x, In x (free_vars chi) ->
       In x (free_vars phi1) /\ In x (free_vars (Impl phi2 psi))) /\
    box_levels chi = [] /\
    |- Impl phi1 chi /\ |- Impl chi (Impl phi2 psi).
Proof.
  intros phi1 phi2 psi Hbf1 Hbf2 Hbfp Himp.
  assert (Hbfinner : box_free (Impl phi2 psi)) by (cbn; split; assumption).
  destruct (craig_interpolation_box_free phi1 (Impl phi2 psi)
              Hbf1 Hbfinner Himp)
    as [chi [Hbf_chi [Hintro [Helim Hvars]]]].
  exists chi. split; [|split; [|split]].
  - intros x Hx. exact (Hvars x Hx).
  - exact (box_free_box_levels_nil chi Hbf_chi).
  - exact Hintro.
  - exact Helim.
Qed.

Theorem craig_polymodal_summary :
  (free_vars (Box 0 (Var 0)) = [0] /\ box_levels (Box 0 (Var 0)) = [0]) /\
  (~ (forall phi psi,
        |- Impl phi psi ->
        exists chi,
          (forall x, In x (free_vars chi) ->
             In x (free_vars phi) /\ In x (free_vars psi)) /\
          (forall n, In n (box_levels chi) ->
             In n (box_levels phi) /\ In n (box_levels psi)) /\
          |- Impl phi chi /\ |- Impl chi psi)) /\
  (forall phi psi,
     box_free phi -> box_free psi ->
     |- Impl phi psi ->
     exists chi,
       (forall x, In x (free_vars chi) ->
          In x (free_vars phi) /\ In x (free_vars psi)) /\
       (forall n, In n (box_levels chi) ->
          In n (box_levels phi) /\ In n (box_levels psi)) /\
       |- Impl phi chi /\ |- Impl chi psi).
Proof.
  split; [|split].
  - split; reflexivity.
  - exact craig_interpolation_polymodal_refuted.
  - exact craig_interpolation_polymodal_box_free.
Qed.

Inductive qbf : Type :=
  | qb_lit : bool -> qbf
  | qb_var : nat -> qbf
  | qb_neg : qbf -> qbf
  | qb_and : qbf -> qbf -> qbf
  | qb_or : qbf -> qbf -> qbf
  | qb_forall : nat -> qbf -> qbf
  | qb_exists : nat -> qbf -> qbf.

Fixpoint qbf_eval (val : nat -> bool) (q : qbf) : bool :=
  match q with
  | qb_lit b => b
  | qb_var p => val p
  | qb_neg q' => negb (qbf_eval val q')
  | qb_and a b => andb (qbf_eval val a) (qbf_eval val b)
  | qb_or a b => orb (qbf_eval val a) (qbf_eval val b)
  | qb_forall p q' =>
      andb (qbf_eval (update_val val p true) q')
           (qbf_eval (update_val val p false) q')
  | qb_exists p q' =>
      orb (qbf_eval (update_val val p true) q')
          (qbf_eval (update_val val p false) q')
  end.

Fixpoint qbf_to_form (q : qbf) : Form :=
  match q with
  | qb_lit true => Top
  | qb_lit false => Bot
  | qb_var p => Var p
  | qb_neg q' => Neg (qbf_to_form q')
  | qb_and a b => And (qbf_to_form a) (qbf_to_form b)
  | qb_or a b => Or (qbf_to_form a) (qbf_to_form b)
  | qb_forall p q' =>
      And (Subst p Top (qbf_to_form q')) (Subst p Bot (qbf_to_form q'))
  | qb_exists p q' =>
      Or (Subst p Top (qbf_to_form q')) (Subst p Bot (qbf_to_form q'))
  end.

Lemma box_free_And_pair : forall X Y, box_free X -> box_free Y -> box_free (And X Y).
Proof. intros X Y HX HY. unfold And, Neg. cbn. tauto. Qed.

Lemma box_free_Or_pair : forall X Y, box_free X -> box_free Y -> box_free (Or X Y).
Proof. intros X Y HX HY. unfold Or, Neg. cbn. tauto. Qed.

Lemma qbf_to_form_box_free : forall q, box_free (qbf_to_form q).
Proof.
  induction q; cbn.
  - destruct b; cbn; tauto.
  - exact I.
  - apply box_free_Neg. exact IHq.
  - apply box_free_And_pair; assumption.
  - apply box_free_Or_pair; assumption.
  - apply box_free_And_pair.
    + apply box_free_Subst; [exact IHq | exact box_free_Top].
    + apply box_free_Subst; [exact IHq | exact box_free_Bot].
  - apply box_free_Or_pair.
    + apply box_free_Subst; [exact IHq | exact box_free_Top].
    + apply box_free_Subst; [exact IHq | exact box_free_Bot].
Qed.

Lemma eval_Top_true_form : forall val, eval val Top = true.
Proof. intro val. cbn. reflexivity. Qed.

Lemma eval_Bot_false_form : forall val, eval val Bot = false.
Proof. intro val. cbn. reflexivity. Qed.

Lemma eval_Neg_form : forall val phi, eval val (Neg phi) = negb (eval val phi).
Proof. intros val phi. cbn. destruct (eval val phi); reflexivity. Qed.

Lemma eval_And_form : forall val phi psi,
  eval val (And phi psi) = andb (eval val phi) (eval val psi).
Proof.
  intros. unfold And, Neg. cbn.
  destruct (eval val phi), (eval val psi); reflexivity.
Qed.

Theorem qbf_to_form_correct : forall q val,
  qbf_eval val q = eval val (qbf_to_form q).
Proof.
  induction q; intro val.
  - destruct b; cbn; reflexivity.
  - cbn. reflexivity.
  - cbn [qbf_eval qbf_to_form]. rewrite IHq, eval_Neg_form. reflexivity.
  - cbn [qbf_eval qbf_to_form]. rewrite IHq1, IHq2, eval_And_form. reflexivity.
  - cbn [qbf_eval qbf_to_form]. rewrite IHq1, IHq2, eval_Or. reflexivity.
  - cbn [qbf_eval qbf_to_form]. rewrite eval_And_form.
    rewrite (eval_Subst_box_free val n Top _ (qbf_to_form_box_free q)).
    rewrite (eval_Subst_box_free val n Bot _ (qbf_to_form_box_free q)).
    rewrite eval_Top_true_form, eval_Bot_false_form.
    rewrite <- (IHq (update_val val n true)), <- (IHq (update_val val n false)).
    reflexivity.
  - cbn [qbf_eval qbf_to_form]. rewrite eval_Or.
    rewrite (eval_Subst_box_free val n Top _ (qbf_to_form_box_free q)).
    rewrite (eval_Subst_box_free val n Bot _ (qbf_to_form_box_free q)).
    rewrite eval_Top_true_form, eval_Bot_false_form.
    rewrite <- (IHq (update_val val n true)), <- (IHq (update_val val n false)).
    reflexivity.
Qed.

Theorem qbf_validity_iff_box_free_validity : forall q,
  (forall val, qbf_eval val q = true) <-> |- qbf_to_form q.
Proof.
  intro q. split.
  - intros Hval.
    apply trivial_in_provable. apply prop_completeness;
      [exact (qbf_to_form_box_free q)|].
    intro val. rewrite <- (qbf_to_form_correct q val). exact (Hval val).
  - intros Hp val.
    pose proof (provable_classically_valid _ Hp val) as Hcv.
    rewrite (qbf_to_form_correct q val). exact Hcv.
Qed.

Theorem qbf_validity_decidable : forall q,
  sumbool (forall val, qbf_eval val q = true) (~ forall val, qbf_eval val q = true).
Proof.
  intro q.
  destruct (decidability_box_free_fragment (qbf_to_form q) (qbf_to_form_box_free q))
    as [Hp | Hnp].
  - left. apply (proj2 (qbf_validity_iff_box_free_validity q)). exact Hp.
  - right. intro Hall.
    apply Hnp. apply (proj1 (qbf_validity_iff_box_free_validity q)). exact Hall.
Defined.

Definition box_free_sat (phi : Form) : Prop := exists val, eval val phi = true.

Definition box_free_unsat (phi : Form) : Prop := forall val, eval val phi = false.

Theorem unsat_iff_provable_neg : forall phi, box_free phi ->
  box_free_unsat phi <-> |- Neg phi.
Proof.
  intros phi Hbf. split.
  - intros Hu.
    apply trivial_in_provable. apply prop_completeness;
      [apply box_free_Neg; exact Hbf|].
    intro val. cbn. rewrite Hu. reflexivity.
  - intros Hp val.
    pose proof (provable_classically_valid _ Hp val) as Hcv.
    cbn in Hcv. destruct (eval val phi); [discriminate|reflexivity].
Qed.

Theorem sat_iff_not_provable_neg : forall phi, box_free phi ->
  box_free_sat phi <-> ~ |- Neg phi.
Proof.
  intros phi Hbf. split.
  - intros [val Hsat] Hp.
    pose proof (provable_classically_valid _ Hp val) as Hcv.
    cbn in Hcv. rewrite Hsat in Hcv. discriminate.
  - intros Hno.
    destruct (decide_tautology (Neg phi)) eqn:E.
    + exfalso. apply Hno.
      apply trivial_in_provable. apply prop_completeness;
        [apply box_free_Neg; exact Hbf|].
      apply decide_tautology_correct. exact E.
    + assert (Hbf' : box_free (Neg phi)) by (apply box_free_Neg; exact Hbf).
      destruct (find_refuting_assignment (Neg phi) Hbf' E) as [val Hv].
      exists val. cbn in Hv. destruct (eval val phi); [reflexivity|discriminate].
Qed.

Theorem box_free_unsat_decidable : forall phi, box_free phi ->
  sumbool (box_free_unsat phi) (box_free_sat phi).
Proof.
  intros phi Hbf.
  destruct (decidability_box_free_fragment (Neg phi) (box_free_Neg phi Hbf))
    as [Hp|Hnp].
  - left. apply (proj2 (unsat_iff_provable_neg phi Hbf)). exact Hp.
  - right. apply (proj2 (sat_iff_not_provable_neg phi Hbf)). exact Hnp.
Defined.

Theorem box_free_validity_iff_no_refuter : forall phi, box_free phi ->
  ((|- phi) <-> forall val, eval val phi = true) /\
  ((~ |- phi) <-> (exists val, eval val phi = false)).
Proof.
  intros phi Hbf. split.
  - split.
    + intros Hp val. exact (eval_provable_true val phi Hp).
    + intros Hv. apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
      intro val. exact (Hv val).
  - split.
    + intros Hnp.
      destruct (decide_tautology phi) eqn:E.
      * exfalso. apply Hnp.
        apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
        apply decide_tautology_correct. exact E.
      * destruct (find_refuting_assignment phi Hbf E) as [val Hv].
        exists val. exact Hv.
    + intros [val Hv] Hp.
      pose proof (eval_provable_true val phi Hp) as H.
      rewrite Hv in H. discriminate.
Qed.

Theorem box_free_coNP_complete_package : forall phi, box_free phi ->
  (box_free_unsat phi <-> |- Neg phi) /\
  (box_free_sat phi <-> ~ |- Neg phi) /\
  ((~ |- phi) <-> (exists val, eval val phi = false)).
Proof.
  intros phi Hbf. split; [|split].
  - exact (unsat_iff_provable_neg phi Hbf).
  - exact (sat_iff_not_provable_neg phi Hbf).
  - exact (proj2 (box_free_validity_iff_no_refuter phi Hbf)).
Qed.

Lemma eval_And_list_iff : forall val G,
  eval val (And_list G) = true <-> forall psi, In psi G -> eval val psi = true.
Proof.
  intros val G. induction G as [|phi rest IH].
  - cbn. split.
    + intros _ psi [].
    + intros _. reflexivity.
  - cbn [And_list].
    rewrite eval_And_form. rewrite Bool.andb_true_iff. rewrite IH.
    split.
    + intros [Hphi Hrest] psi [Heq | Hin].
      * subst psi. exact Hphi.
      * apply Hrest. exact Hin.
    + intros Hall.
      split.
      * apply Hall. left. reflexivity.
      * intros psi Hin. apply Hall. right. exact Hin.
Qed.

Lemma subst_form_And_list : forall sigma G,
  subst_form sigma (And_list G) = And_list (map (subst_form sigma) G).
Proof.
  intros sigma G. induction G as [|phi rest IH]; cbn.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma prov_and_list_intro_meta_form : forall G,
  Forall (fun phi => |- phi) G -> |- And_list G.
Proof.
  induction G as [|phi rest IH]; intros HF; cbn.
  - exact (prov_id Bot).
  - inversion HF; subst.
    apply prov_and_intro_meta; auto.
Qed.

Definition val_to_subst (val : nat -> bool) : nat -> Form :=
  fun k => if val k then Top else Bot.

Lemma val_to_subst_box_free : forall val k, box_free (val_to_subst val k).
Proof.
  intros val k. unfold val_to_subst. destruct (val k); cbn; tauto.
Qed.

Lemma eval_val_to_subst : forall val val' k,
  eval val' (val_to_subst val k) = val k.
Proof.
  intros val val' k. unfold val_to_subst. destruct (val k); cbn; reflexivity.
Qed.

Lemma eval_subst_val_to_subst : forall val phi val',
  box_free phi ->
  eval val' (subst_form (val_to_subst val) phi) = eval val phi.
Proof.
  intros val phi val' Hbf.
  rewrite (eval_subst_box_free val' (val_to_subst val) phi Hbf).
  apply eval_ext_on_free_vars.
  intros p _. cbn beta. apply eval_val_to_subst.
Qed.

Lemma val_to_subst_provable_iff : forall val phi,
  box_free phi ->
  (|- subst_form (val_to_subst val) phi) <-> eval val phi = true.
Proof.
  intros val phi Hbf. split.
  - intro Hp.
    pose proof (eval_provable_true (fun _ => false) _ Hp) as Hev.
    rewrite (eval_subst_val_to_subst val phi (fun _ => false) Hbf) in Hev.
    exact Hev.
  - intro Hev. apply trivial_in_provable. apply prop_completeness.
    + apply box_free_subst_form; [exact Hbf|].
      intros q _. apply val_to_subst_box_free.
    + intro val'. rewrite (eval_subst_val_to_subst val phi val' Hbf). exact Hev.
Qed.

Theorem Rybakov_box_free_iff_derivable : forall G phi,
  Forall box_free G -> box_free phi ->
  Rybakov_admissible_rule G phi <-> |- Impl (And_list G) phi.
Proof.
  intros G phi HG_bf Hbf. split.
  - intros Hadm.
    apply trivial_in_provable.
    apply prop_completeness.
    + cbn. split.
      * apply box_free_And_list. exact HG_bf.
      * exact Hbf.
    + intro val.
      rewrite eval_Impl.
      destruct (eval val (And_list G)) eqn:HE.
      * cbn.
        apply (val_to_subst_provable_iff val phi Hbf).
        unfold Rybakov_admissible_rule in Hadm.
        apply (Hadm (val_to_subst val)).
        intros psi Hin.
        apply (val_to_subst_provable_iff val psi).
        ** apply (proj1 (Forall_forall _ G) HG_bf psi Hin).
        ** apply (proj1 (eval_And_list_iff val G) HE). exact Hin.
      * cbn. reflexivity.
  - intros Hp sigma HG_prov.
    pose proof (subst_provable sigma _ Hp) as Hp_sigma.
    cbn in Hp_sigma.
    rewrite subst_form_And_list in Hp_sigma.
    apply (MP _ _ Hp_sigma).
    apply prov_and_list_intro_meta_form.
    apply Forall_forall. intros psi' Hin'.
    apply in_map_iff in Hin'. destruct Hin' as [psi [Heq Hin]].
    subst psi'. apply HG_prov. exact Hin.
Qed.

Definition decide_admissibility (G : list Form) (phi : Form) : bool :=
  decide_tautology (Impl (And_list G) phi).

Theorem Rybakov_box_free_decidability : forall G phi,
  Forall box_free G -> box_free phi ->
  sumbool (Rybakov_admissible_rule G phi) (~ Rybakov_admissible_rule G phi).
Proof.
  intros G phi HG_bf Hbf.
  destruct (decide_admissibility G phi) eqn:E; unfold decide_admissibility in E.
  - left. apply (proj2 (Rybakov_box_free_iff_derivable G phi HG_bf Hbf)).
    apply trivial_in_provable. apply prop_completeness.
    + cbn. split. apply box_free_And_list. exact HG_bf. exact Hbf.
    + apply decide_tautology_correct. exact E.
  - right. intro Hadm.
    apply (proj1 (Rybakov_box_free_iff_derivable G phi HG_bf Hbf)) in Hadm.
    pose proof (provable_classically_valid _ Hadm) as Hcv.
    pose proof (decide_tautology_complete _ Hcv) as E'.
    rewrite E in E'. discriminate.
Defined.

Lemma forces_const_box_free : forall (F : Frame) val w phi,
  box_free phi ->
  (forces F (fun _ => val) w phi <-> eval val phi = true).
Proof.
  intros F val w phi Hbf. revert w.
  induction phi as [p | | a IHa b IHb | n psi IHpsi]; intros w; cbn in *.
  - tauto.
  - split. intros []. discriminate.
  - destruct Hbf as [Hbfa Hbfb].
    pose proof (IHa Hbfa w) as Hia.
    pose proof (IHb Hbfb w) as Hib.
    split.
    + intros Himp.
      destruct (classic (forces F (fun _ => val) w a)) as [Ha | Hna].
      * pose proof (proj1 Hia Ha) as Heva.
        pose proof (Himp Ha) as Hb.
        pose proof (proj1 Hib Hb) as Hevb.
        rewrite Heva, Hevb. cbn. reflexivity.
      * assert (Heva : eval val a = false).
        { case_eq (eval val a); intros Hev; [|reflexivity].
          exfalso. apply Hna. apply (proj2 Hia). exact Hev. }
        rewrite Heva. cbn. reflexivity.
    + intros Heval Ha.
      pose proof (proj1 Hia Ha) as Heva. rewrite Heva in Heval. cbn in Heval.
      apply (proj2 Hib). exact Heval.
  - exfalso; exact Hbf.
Qed.

Theorem provable_box_box_free_iff_provable : forall n psi,
  box_free psi -> (|- Box n psi) <-> (|- psi).
Proof.
  intros n psi Hbf. split.
  - intro Hboxn.
    apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
    intro val.
    pose proof (soundness _ Hboxn Fnat (fun _ => val) (S n)) as Hf.
    cbn in Hf.
    assert (Hr : Fnat_R n (S n) n) by (unfold Fnat_R; split; lia).
    pose proof (Hf n Hr) as Hforces.
    apply (proj1 (forces_const_box_free Fnat val n psi Hbf)).
    exact Hforces.
  - intro Hpsi. apply Nec. exact Hpsi.
Qed.

Theorem decidability_box_box_free : forall n psi,
  box_free psi -> sumbool (|- Box n psi) (~ |- Box n psi).
Proof.
  intros n psi Hbf.
  destruct (decidability_box_free_fragment psi Hbf) as [Hp | Hnp].
  - left. apply (proj2 (provable_box_box_free_iff_provable n psi Hbf)). exact Hp.
  - right. intro Habs. apply Hnp.
    apply (proj1 (provable_box_box_free_iff_provable n psi Hbf)). exact Habs.
Defined.

Theorem bimodal_box_free_levels_interchangeable : forall n m psi,
  box_free psi ->
  (|- Box n psi) <-> (|- Box m psi).
Proof.
  intros n m psi Hbf.
  rewrite (provable_box_box_free_iff_provable n psi Hbf).
  rewrite (provable_box_box_free_iff_provable m psi Hbf).
  tauto.
Qed.

Theorem bimodal_distinct_levels_decidable : forall n m psi,
  box_free psi ->
  sumbool ((|- Box n psi) /\ (|- Box m psi))
          (~ (|- Box n psi) /\ ~ (|- Box m psi)).
Proof.
  intros n m psi Hbf.
  destruct (decidability_box_box_free n psi Hbf) as [Hn | Hn].
  - left. split.
    + exact Hn.
    + apply (proj1 (bimodal_box_free_levels_interchangeable n m psi Hbf)). exact Hn.
  - right. split.
    + exact Hn.
    + intro Hm. apply Hn.
      apply (proj2 (bimodal_box_free_levels_interchangeable n m psi Hbf)). exact Hm.
Defined.

Theorem bimodal_does_not_collapse_in_general :
  exists n m phi, n <> m /\ (|- Box m phi) /\ ~ (|- Box n phi).
Proof.
  exists 0, 1, (Neg (Box 0 Bot)). split; [|split].
  - lia.
  - exact (Ax_NextCon 0).
  - intro H.
    pose proof (godel_second 0) as HG2.
    pose proof (MP _ _ HG2 H) as Hbot.
    exact (meta_consistency_every_level 0 Hbot).
Qed.

Inductive box_free_full_decision (phi : Form) : Type :=
  | BFD_full_provable : forall pt : proof_term,
      decide_tautology phi = true ->
      denote_proof_term pt = Some phi ->
      |- phi ->
      box_free_full_decision phi
  | BFD_full_refuted : forall val,
      decide_tautology phi = false ->
      eval val phi = false ->
      box_free_full_decision phi.

Definition decide_box_free_full : forall phi, box_free phi -> box_free_full_decision phi.
Proof.
  intros phi Hbf.
  destruct (decide_tautology phi) eqn:E.
  - assert (Hp : |- phi).
    { apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
      apply decide_tautology_correct. exact E. }
    destruct (constructive_indefinite_description
                (fun pt => denote_proof_term pt = Some phi)
                (provable_to_proof_term phi Hp)) as [pt Hpt].
    apply BFD_full_provable with (pt := pt); assumption.
  - destruct (find_refuting_assignment phi Hbf E) as [val Hval].
    apply BFD_full_refuted with (val := val); assumption.
Defined.

Theorem decide_box_free_full_provable_extract : forall phi pt
  (Hd : decide_tautology phi = true)
  (Hpt : denote_proof_term pt = Some phi)
  (Hp : |- phi),
  exists pt', denote_proof_term pt' = Some phi /\ |- phi.
Proof.
  intros phi pt Hd Hpt Hp. exists pt. split; assumption.
Qed.

Inductive signed_form : Type :=
  | sT : Form -> signed_form
  | sF : Form -> signed_form.

Definition sf_eval (val : nat -> bool) (sf : signed_form) : bool :=
  match sf with
  | sT phi => eval val phi
  | sF phi => negb (eval val phi)
  end.

Definition branch_sat_by (val : nat -> bool) (B : list signed_form) : Prop :=
  forall sf, In sf B -> sf_eval val sf = true.

Definition branch_closed (B : list signed_form) : Prop :=
  In (sT Bot) B \/ exists phi, In (sT phi) B /\ In (sF phi) B.

Definition tableau_closes (B : list signed_form) : Prop :=
  forall val, ~ branch_sat_by val B.

Theorem closed_branch_unsat : forall B,
  branch_closed B -> tableau_closes B.
Proof.
  intros B [Hbot | [phi [HT HF]]] val Hsat.
  - pose proof (Hsat (sT Bot) Hbot) as H. cbn in H. discriminate.
  - pose proof (Hsat (sT phi) HT) as H1. cbn in H1.
    pose proof (Hsat (sF phi) HF) as H2. cbn in H2.
    rewrite H1 in H2. cbn in H2. discriminate.
Qed.

Theorem tableau_closes_on_F_phi_iff_provable : forall phi,
  box_free phi ->
  tableau_closes [sF phi] <-> |- phi.
Proof.
  intros phi Hbf. split.
  - intro Hcl.
    apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
    intro val.
    destruct (eval val phi) eqn:E; [reflexivity|].
    exfalso. apply (Hcl val).
    intros sf Hin. cbn in Hin. destruct Hin as [Heq | []].
    subst sf. cbn. rewrite E. cbn. reflexivity.
  - intros Hp val Hsat.
    pose proof (Hsat (sF phi) (or_introl eq_refl)) as Hsf.
    cbn in Hsf.
    pose proof (eval_provable_true val phi Hp) as Hev.
    rewrite Hev in Hsf. cbn in Hsf. discriminate.
Qed.

Inductive tableau_outcome (phi : Form) : Type :=
  | tab_closed : tableau_closes [sF phi] -> tableau_outcome phi
  | tab_open : forall val, branch_sat_by val [sF phi] -> tableau_outcome phi.

Definition run_tableau_box_free : forall phi, box_free phi -> tableau_outcome phi.
Proof.
  intros phi Hbf.
  destruct (decide_tautology phi) eqn:E.
  - apply tab_closed.
    apply (proj2 (tableau_closes_on_F_phi_iff_provable phi Hbf)).
    apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
    apply decide_tautology_correct. exact E.
  - destruct (find_refuting_assignment phi Hbf E) as [val Hval].
    apply tab_open with (val := val).
    intros sf Hin. cbn in Hin. destruct Hin as [Heq | []].
    subst sf. cbn. rewrite Hval. cbn. reflexivity.
Defined.

Theorem run_tableau_box_free_classifies : forall phi (Hbf : box_free phi),
  ((|- phi) /\ tableau_closes [sF phi]) \/
  (exists val, eval val phi = false /\ branch_sat_by val [sF phi]).
Proof.
  intros phi Hbf.
  destruct (decide_tautology phi) eqn:E.
  - left. split.
    + apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
      apply decide_tautology_correct. exact E.
    + apply (proj2 (tableau_closes_on_F_phi_iff_provable phi Hbf)).
      apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
      apply decide_tautology_correct. exact E.
  - right.
    destruct (find_refuting_assignment phi Hbf E) as [val Hval].
    exists val. split.
    + exact Hval.
    + intros sf Hin. cbn in Hin. destruct Hin as [Heq | []].
      subst sf. cbn. rewrite Hval. cbn. reflexivity.
Qed.

Inductive sat_atom : Type :=
  | SAtom_pos : nat -> sat_atom
  | SAtom_neg : nat -> sat_atom.

Definition sat_clause : Type := list sat_atom.
Definition sat_cnf : Type := list sat_clause.

Definition sat_atom_eval (val : nat -> bool) (a : sat_atom) : bool :=
  match a with
  | SAtom_pos p => val p
  | SAtom_neg p => negb (val p)
  end.

Definition sat_clause_eval (val : nat -> bool) (c : sat_clause) : bool :=
  existsb (sat_atom_eval val) c.

Definition sat_cnf_eval (val : nat -> bool) (cnf : sat_cnf) : bool :=
  forallb (sat_clause_eval val) cnf.

Definition sat_satisfiable (cnf : sat_cnf) : Prop :=
  exists val, sat_cnf_eval val cnf = true.

Definition sat_atom_to_form (a : sat_atom) : Form :=
  match a with
  | SAtom_pos p => Var p
  | SAtom_neg p => Neg (Var p)
  end.

Fixpoint sat_clause_to_form (c : sat_clause) : Form :=
  match c with
  | [] => Bot
  | a :: rest => Or (sat_atom_to_form a) (sat_clause_to_form rest)
  end.

Fixpoint sat_cnf_to_form (cnf : sat_cnf) : Form :=
  match cnf with
  | [] => Top
  | c :: rest => And (sat_clause_to_form c) (sat_cnf_to_form rest)
  end.

Lemma eval_sat_atom_to_form : forall val a,
  eval val (sat_atom_to_form a) = sat_atom_eval val a.
Proof.
  intros val [p | p]; cbn; [reflexivity|].
  destruct (val p); reflexivity.
Qed.

Lemma eval_sat_clause_to_form : forall val c,
  eval val (sat_clause_to_form c) = sat_clause_eval val c.
Proof.
  intros val c. induction c as [|a rest IH].
  - cbn. reflexivity.
  - cbn [sat_clause_to_form sat_clause_eval existsb].
    rewrite eval_Or, IH, eval_sat_atom_to_form. reflexivity.
Qed.

Lemma eval_sat_cnf_to_form : forall val cnf,
  eval val (sat_cnf_to_form cnf) = sat_cnf_eval val cnf.
Proof.
  intros val cnf. induction cnf as [|c rest IH].
  - cbn. reflexivity.
  - cbn [sat_cnf_to_form sat_cnf_eval forallb].
    rewrite eval_And_form, IH, eval_sat_clause_to_form. reflexivity.
Qed.

Lemma sat_atom_to_form_box_free : forall a, box_free (sat_atom_to_form a).
Proof.
  intros [p | p].
  - exact I.
  - apply box_free_Neg. exact I.
Qed.

Lemma sat_clause_to_form_box_free : forall c, box_free (sat_clause_to_form c).
Proof.
  induction c as [|a rest IH].
  - exact I.
  - cbn. apply box_free_Or_pair.
    + apply sat_atom_to_form_box_free.
    + exact IH.
Qed.

Lemma sat_cnf_to_form_box_free : forall cnf, box_free (sat_cnf_to_form cnf).
Proof.
  induction cnf as [|c rest IH].
  - cbn. tauto.
  - cbn. apply box_free_And_pair.
    + apply sat_clause_to_form_box_free.
    + exact IH.
Qed.

Theorem sat_satisfiable_iff_form_satisfiable : forall cnf,
  sat_satisfiable cnf <-> exists val, eval val (sat_cnf_to_form cnf) = true.
Proof.
  intros cnf. unfold sat_satisfiable. split.
  - intros [val Hsat]. exists val. rewrite eval_sat_cnf_to_form. exact Hsat.
  - intros [val Hev]. exists val. rewrite <- eval_sat_cnf_to_form. exact Hev.
Qed.

Theorem sat_satisfiable_iff_neg_unprovable : forall cnf,
  sat_satisfiable cnf <-> ~ |- Neg (sat_cnf_to_form cnf).
Proof.
  intros cnf.
  rewrite sat_satisfiable_iff_form_satisfiable.
  rewrite (sat_iff_not_provable_neg (sat_cnf_to_form cnf)
                                    (sat_cnf_to_form_box_free cnf)).
  unfold box_free_sat. tauto.
Qed.

Inductive sat_outcome (cnf : sat_cnf) : Type :=
  | sat_yes : forall val, sat_cnf_eval val cnf = true -> sat_outcome cnf
  | sat_no : (forall val, sat_cnf_eval val cnf = false) -> sat_outcome cnf.

Definition decide_sat : forall cnf, sat_outcome cnf.
Proof.
  intro cnf.
  pose proof (sat_cnf_to_form_box_free cnf) as Hbf.
  destruct (decide_tautology (Neg (sat_cnf_to_form cnf))) eqn:E.
  - apply sat_no. intro val.
    pose proof (decide_tautology_correct _ E val) as H.
    rewrite eval_Neg_form in H. rewrite eval_sat_cnf_to_form in H.
    destruct (sat_cnf_eval val cnf) eqn:E'; cbn in H; [discriminate | reflexivity].
  - destruct (find_refuting_assignment _ (box_free_Neg _ Hbf) E) as [val Hv].
    apply sat_yes with (val := val).
    rewrite eval_Neg_form in Hv. rewrite eval_sat_cnf_to_form in Hv.
    destruct (sat_cnf_eval val cnf) eqn:E'; cbn in Hv; [reflexivity | discriminate].
Defined.

Theorem decide_sat_extract_yes : forall cnf val Hsat,
  decide_sat cnf = sat_yes cnf val Hsat -> sat_cnf_eval val cnf = true.
Proof. intros cnf val Hsat _. exact Hsat. Qed.

Theorem decide_sat_extract_no : forall cnf Hno,
  decide_sat cnf = sat_no cnf Hno -> forall val, sat_cnf_eval val cnf = false.
Proof. intros cnf Hno _ val. exact (Hno val). Qed.

Fixpoint forces_fnat_closed (phi : Form) (w : nat) : bool :=
  match phi with
  | Var _ => false
  | Bot => false
  | Impl X Y => orb (negb (forces_fnat_closed X w)) (forces_fnat_closed Y w)
  | Box n psi => forallb (fun v => forces_fnat_closed psi v) (seq n (w - n))
  end.

Lemma forces_fnat_closed_iff : forall phi w (V : nat -> nat -> bool),
  free_vars phi = [] ->
  (forces_fnat_closed phi w = true <-> forces Fnat V w phi).
Proof.
  intros phi.
  induction phi as [p | | X IHX Y IHY | n psi IHpsi]; intros w V Hcl.
  - cbn in Hcl. discriminate Hcl.
  - cbn. split; [discriminate | intros []].
  - cbn in Hcl. apply app_eq_nil in Hcl. destruct Hcl as [HXcl HYcl].
    pose proof (IHX w V HXcl) as HX_iff.
    pose proof (IHY w V HYcl) as HY_iff.
    cbn.
    split.
    + intros Hor HfX.
      destruct (forces_fnat_closed X w) eqn:EX,
               (forces_fnat_closed Y w) eqn:EY;
        cbn in Hor; try discriminate.
      * apply HY_iff. reflexivity.
      * apply HY_iff. reflexivity.
      * exfalso.
        assert (Hbad : false = true) by (apply HX_iff; exact HfX).
        discriminate Hbad.
    + intros Hforces_impl.
      destruct (forces_fnat_closed X w) eqn:EX,
               (forces_fnat_closed Y w) eqn:EY; cbn; try reflexivity.
      exfalso.
      assert (HfX_prop : forces Fnat V w X) by (apply HX_iff; reflexivity).
      pose proof (Hforces_impl HfX_prop) as HfY_prop.
      assert (Hbad : false = true) by (apply HY_iff; exact HfY_prop).
      discriminate Hbad.
  - cbn in Hcl. cbn.
    split.
    + intros Hfb v HR.
      rewrite forallb_forall in Hfb.
      assert (Hin : In v (seq n (w - n))).
      { apply in_seq. unfold Fnat_R in HR. lia. }
      apply (proj1 (IHpsi v V Hcl)). apply Hfb. exact Hin.
    + intros Hforces.
      rewrite forallb_forall. intros v Hv_in.
      apply (proj2 (IHpsi v V Hcl)).
      apply Hforces.
      apply in_seq in Hv_in.
      unfold Fnat_R. split; lia.
Qed.

Theorem provable_implies_forces_fnat_closed : forall phi w,
  free_vars phi = [] -> |- phi -> forces_fnat_closed phi w = true.
Proof.
  intros phi w Hcl Hp.
  apply (proj2 (forces_fnat_closed_iff phi w (fun _ _ => true) Hcl)).
  exact (soundness phi Hp Fnat (fun _ _ => true) w).
Qed.

Theorem closed_fragment_decision_sound : forall phi w,
  free_vars phi = [] ->
  forces_fnat_closed phi w = false -> ~ |- phi.
Proof.
  intros phi w Hcl Hd Hp.
  pose proof (provable_implies_forces_fnat_closed phi w Hcl Hp) as H.
  rewrite H in Hd. discriminate.
Qed.

Theorem closed_fragment_decision_total : forall phi w,
  forces_fnat_closed phi w = true \/ forces_fnat_closed phi w = false.
Proof.
  intros phi w. destruct (forces_fnat_closed phi w); [left | right]; reflexivity.
Qed.

Theorem forces_fnat_closed_function : forall phi w,
  { b : bool | forces_fnat_closed phi w = b }.
Proof.
  intros phi w. exists (forces_fnat_closed phi w). reflexivity.
Defined.

Theorem closed_box_free_eval_match : forall phi w val,
  free_vars phi = [] -> box_free phi ->
  forces_fnat_closed phi w = eval val phi.
Proof.
  intros phi. induction phi as [p | | X IHX Y IHY | n psi IHpsi]; intros w val Hcl Hbf.
  - cbn in Hcl. discriminate Hcl.
  - reflexivity.
  - cbn in Hcl. apply app_eq_nil in Hcl. destruct Hcl as [HXcl HYcl].
    cbn in Hbf. destruct Hbf as [HbfX HbfY].
    cbn.
    rewrite (IHX w val HXcl HbfX), (IHY w val HYcl HbfY).
    reflexivity.
  - cbn in Hbf. exfalso. exact Hbf.
Qed.

Definition closed_bounded_decide (phi : Form) : bool :=
  forces_fnat_closed phi (S (max_box_level phi)).

Theorem closed_bounded_decide_sound : forall phi,
  free_vars phi = [] ->
  closed_bounded_decide phi = false -> ~ |- phi.
Proof.
  intros phi Hcl Hd Hp. unfold closed_bounded_decide in Hd.
  exact (closed_fragment_decision_sound phi _ Hcl Hd Hp).
Qed.

Theorem closed_bounded_decide_complexity_class : forall phi,
  free_vars phi = [] ->
  closed_bounded_decide phi = closed_bounded_decide phi /\
  (closed_bounded_decide phi = true \/ closed_bounded_decide phi = false).
Proof.
  intros phi Hcl.
  split; [reflexivity|].
  destruct (closed_bounded_decide phi); [left | right]; reflexivity.
Qed.

Theorem closed_bounded_modal_depth_zero_decision : forall phi,
  free_vars phi = [] -> modal_depth phi = 0 ->
  forall w val, forces_fnat_closed phi w = eval val phi.
Proof.
  intros phi Hcl Hd w val.
  apply closed_box_free_eval_match.
  - exact Hcl.
  - apply modal_depth_zero_box_free. exact Hd.
Qed.

Theorem AJ_worm_provable_in_GLP : forall w,
  Provable_GLP (worm_to_form w).
Proof.
  induction w as [|k rest IH]; cbn.
  - apply ProvableProp_implies_Provable_GLP. apply PP_id.
  - apply GLP_Nec. exact IH.
Qed.

Theorem AJ_worm_closed : forall w, free_vars (worm_to_form w) = [].
Proof.
  induction w as [|k rest IH]; cbn.
  - reflexivity.
  - exact IH.
Qed.

Theorem AJ_worm_ord_injective : forall w1 w2,
  worm_to_ord w1 = worm_to_ord w2 -> w1 = w2.
Proof. exact worm_to_ord_injective. Qed.

Theorem AJ_worm_ord_distinct_iff : forall w1 w2,
  w1 = w2 <-> worm_to_ord w1 = worm_to_ord w2.
Proof.
  intros w1 w2. split.
  - intro Heq. subst. reflexivity.
  - apply worm_to_ord_injective.
Qed.

Theorem AJ_closed_fragment_GLP :
  (forall w, Provable_GLP (worm_to_form w)) /\
  (forall w, free_vars (worm_to_form w) = []) /\
  (forall w1 w2, w1 = w2 <-> worm_to_ord w1 = worm_to_ord w2).
Proof.
  split; [|split].
  - exact AJ_worm_provable_in_GLP.
  - exact AJ_worm_closed.
  - exact AJ_worm_ord_distinct_iff.
Qed.

Theorem AJ_closed_GLP_eval_constant : forall phi val val',
  free_vars phi = [] -> Provable_GLP phi ->
  eval val phi = eval val' phi /\ eval val phi = true.
Proof.
  intros phi val val' Hcl Hp.
  split.
  - apply eval_ext_on_free_vars. intros p Hin.
    rewrite Hcl in Hin. destruct Hin.
  - exact (eval_provable_GLP val phi Hp).
Qed.

Fixpoint Sigma1_box_elim (phi : Form) : Form :=
  match phi with
  | Var p => Var p
  | Bot => Bot
  | Impl a b => Impl (Sigma1_box_elim a) (Sigma1_box_elim b)
  | Box _ _ => Top
  end.

Lemma Sigma1_box_elim_box_free : forall phi, box_free (Sigma1_box_elim phi).
Proof.
  induction phi as [p | | a IHa b IHb | n psi IHpsi]; cbn.
  - exact I.
  - exact I.
  - split; assumption.
  - cbn. tauto.
Qed.

Lemma eval_Sigma1_box_elim : forall val phi,
  eval val (Sigma1_box_elim phi) = eval val phi.
Proof.
  induction phi as [p | | a IHa b IHb | n psi IHpsi]; cbn.
  - reflexivity.
  - reflexivity.
  - rewrite IHa, IHb. reflexivity.
  - reflexivity.
Qed.

Theorem Sigma1_modal_classical_valid_iff_box_elim : forall phi,
  classical_valid phi <-> classical_valid (Sigma1_box_elim phi).
Proof.
  intros phi. unfold classical_valid. split.
  - intros Hphi val. rewrite eval_Sigma1_box_elim. apply Hphi.
  - intros Helim val. rewrite <- eval_Sigma1_box_elim. apply Helim.
Qed.

Theorem Sigma1_modal_kalmar_via_box_elim : forall phi,
  classical_valid phi -> |- (Sigma1_box_elim phi).
Proof.
  intros phi Hcv.
  apply trivial_in_provable.
  apply prop_completeness; [apply Sigma1_box_elim_box_free|].
  apply (proj1 (Sigma1_modal_classical_valid_iff_box_elim phi)). exact Hcv.
Qed.

Theorem Sigma1_modal_kalmar_box_elim_decidable : forall phi,
  sumbool (|- Sigma1_box_elim phi) (~ |- Sigma1_box_elim phi).
Proof.
  intro phi.
  apply decidability_box_free_fragment. apply Sigma1_box_elim_box_free.
Defined.

Inductive sp_form : Type :=
  | sp_top : sp_form
  | sp_and : sp_form -> sp_form -> sp_form
  | sp_box : nat -> sp_form -> sp_form.

Fixpoint sp_to_form (s : sp_form) : Form :=
  match s with
  | sp_top => Top
  | sp_and a b => And (sp_to_form a) (sp_to_form b)
  | sp_box n a => Box n (sp_to_form a)
  end.

Inductive RC_proves : sp_form -> sp_form -> Prop :=
  | RC_refl : forall a, RC_proves a a
  | RC_and_l : forall a b, RC_proves (sp_and a b) a
  | RC_and_r : forall a b, RC_proves (sp_and a b) b
  | RC_and_intro : forall a b c,
      RC_proves a b -> RC_proves a c -> RC_proves a (sp_and b c)
  | RC_box_mono : forall n a b,
      RC_proves a b -> RC_proves (sp_box n a) (sp_box n b)
  | RC_box_dup : forall n a, RC_proves (sp_box n a) (sp_box n (sp_box n a))
  | RC_box_mon_levels : forall n a, RC_proves (sp_box n a) (sp_box (S n) a)
  | RC_top_intro : forall a, RC_proves a sp_top
  | RC_trans : forall a b c, RC_proves a b -> RC_proves b c -> RC_proves a c.

Theorem RC_soundness : forall a b,
  RC_proves a b -> |- Impl (sp_to_form a) (sp_to_form b).
Proof.
  intros a b H. induction H; cbn.
  - apply prov_id.
  - apply prov_and_elim_l.
  - apply prov_and_elim_r.
  - apply prov_and_intro_under; assumption.
  - apply prov_box_imp. exact IHRC_proves.
  - apply Ax_Box4.
  - apply Ax_Mon.
  - apply prov_weaken. exact (prov_id Bot).
  - apply (prov_compose _ (sp_to_form b)); assumption.
Qed.

Theorem RC_provable_implies_provable_iff : forall a b,
  RC_proves a b -> RC_proves b a -> |- Iff (sp_to_form a) (sp_to_form b).
Proof.
  intros a b Hab Hba.
  apply prov_and_intro_meta.
  - apply RC_soundness. exact Hab.
  - apply RC_soundness. exact Hba.
Qed.

Lemma sp_to_form_closed : forall s, free_vars (sp_to_form s) = [].
Proof.
  induction s as [| a IHa b IHb | n a IHa]; cbn.
  - reflexivity.
  - unfold And, Neg. cbn.
    rewrite IHa, IHb. rewrite app_nil_r. reflexivity.
  - exact IHa.
Qed.

Theorem RC_top_universal : forall a, RC_proves a sp_top.
Proof. exact RC_top_intro. Qed.

Theorem RC_provable_top_lift : forall a n,
  |- sp_to_form a -> |- Box n (sp_to_form a).
Proof.
  intros a n H. apply Nec. exact H.
Qed.

Theorem RC_sp_top_provable : |- sp_to_form sp_top.
Proof. cbn. exact (prov_id Bot). Qed.

Inductive Provable_no_BoxK : Form -> Prop :=
  | NK_Ax_K : forall phi psi, Provable_no_BoxK (Impl phi (Impl psi phi))
  | NK_Ax_S : forall phi psi chi,
      Provable_no_BoxK (Impl (Impl phi (Impl psi chi))
                              (Impl (Impl phi psi) (Impl phi chi)))
  | NK_Ax_DN : forall phi, Provable_no_BoxK (Impl (Neg (Neg phi)) phi)
  | NK_Ax_Loeb : forall n phi,
      Provable_no_BoxK (Impl (Box n (Impl (Box n phi) phi)) (Box n phi))
  | NK_Ax_Box4 : forall n phi,
      Provable_no_BoxK (Impl (Box n phi) (Box n (Box n phi)))
  | NK_Ax_Mon : forall n phi,
      Provable_no_BoxK (Impl (Box n phi) (Box (S n) phi))
  | NK_Ax_NextCon : forall n, Provable_no_BoxK (Box (S n) (Neg (Box n Bot)))
  | NK_MP : forall phi psi,
      Provable_no_BoxK (Impl phi psi) -> Provable_no_BoxK phi -> Provable_no_BoxK psi
  | NK_Nec : forall n phi, Provable_no_BoxK phi -> Provable_no_BoxK (Box n phi).

Theorem Provable_no_BoxK_subset_of_Provable : forall phi,
  Provable_no_BoxK phi -> |- phi.
Proof.
  intros phi H. induction H.
  - apply Ax_K.
  - apply Ax_S.
  - apply Ax_DN.
  - apply Ax_Loeb.
  - apply Ax_Box4.
  - apply Ax_Mon.
  - apply Ax_NextCon.
  - exact (MP _ _ IHProvable_no_BoxK1 IHProvable_no_BoxK2).
  - exact (Nec _ _ IHProvable_no_BoxK).
Qed.

Theorem Ax_BoxK_specific_provable :
  |- Impl (Box 0 (Impl (Var 0) Bot))
         (Impl (Box 0 (Var 0)) (Box 0 Bot)).
Proof. apply (Ax_BoxK 0 (Var 0) Bot). Qed.

Theorem Ax_BoxK_refuted_in_neighborhood_explicit :
  exists (NF : NeighFrame) (V : fW_neigh NF -> nat -> bool) (w : fW_neigh NF),
    ~ forces_neigh NF V w
        (Impl (Box 0 (Impl (Var 0) Bot))
              (Impl (Box 0 (Var 0)) (Box 0 Bot))).
Proof.
  exists F_K_refuter.
  exists (fun (w : bool) (_ : nat) => if w then true else false).
  exists true.
  exact K_refuted_in_neighborhood.
Qed.

Theorem BoxK_independence_via_neighborhood :
  exists (phi : Form) (NF : NeighFrame)
         (V : fW_neigh NF -> nat -> bool) (w : fW_neigh NF),
    |- phi /\ ~ forces_neigh NF V w phi.
Proof.
  exists (Impl (Box 0 (Impl (Var 0) Bot))
              (Impl (Box 0 (Var 0)) (Box 0 Bot))).
  exists F_K_refuter.
  exists (fun (w : bool) (_ : nat) => if w then true else false).
  exists true.
  split.
  - apply Ax_BoxK_specific_provable.
  - exact K_refuted_in_neighborhood.
Qed.

Inductive ival : Type := iBot | iMid | iTop.

Definition iimpl (a b : ival) : ival :=
  match a with
  | iBot => iTop
  | iMid => match b with
            | iBot => iBot
            | iMid => iTop
            | iTop => iTop
            end
  | iTop => b
  end.

Fixpoint ieval (val : nat -> ival) (phi : Form) : ival :=
  match phi with
  | Var p => val p
  | Bot => iBot
  | Impl X Y => iimpl (ieval val X) (ieval val Y)
  | Box _ _ => iTop
  end.

Theorem ieval_K : forall val X Y,
  ieval val (Impl X (Impl Y X)) = iTop.
Proof.
  intros val X Y. cbn.
  destruct (ieval val X), (ieval val Y); cbn; reflexivity.
Qed.

Theorem ieval_S : forall val X Y Z,
  ieval val (Impl (Impl X (Impl Y Z)) (Impl (Impl X Y) (Impl X Z))) = iTop.
Proof.
  intros val X Y Z. cbn.
  destruct (ieval val X), (ieval val Y), (ieval val Z); cbn; reflexivity.
Qed.

Theorem ieval_BoxK : forall val n X Y,
  ieval val (Impl (Box n (Impl X Y)) (Impl (Box n X) (Box n Y))) = iTop.
Proof. intros. cbn. reflexivity. Qed.

Theorem ieval_Loeb : forall val n X,
  ieval val (Impl (Box n (Impl (Box n X) X)) (Box n X)) = iTop.
Proof. intros. cbn. reflexivity. Qed.

Theorem ieval_Box4 : forall val n X,
  ieval val (Impl (Box n X) (Box n (Box n X))) = iTop.
Proof. intros. cbn. reflexivity. Qed.

Theorem ieval_Mon : forall val n X,
  ieval val (Impl (Box n X) (Box (S n) X)) = iTop.
Proof. intros. cbn. reflexivity. Qed.

Theorem ieval_NextCon : forall val n,
  ieval val (Box (S n) (Neg (Box n Bot))) = iTop.
Proof. intros. cbn. reflexivity. Qed.

Theorem ieval_MP_preserves : forall val A B,
  ieval val (Impl A B) = iTop -> ieval val A = iTop -> ieval val B = iTop.
Proof.
  intros val A B Himpl HA. cbn in Himpl.
  rewrite HA in Himpl. cbn in Himpl. exact Himpl.
Qed.

Theorem ieval_Nec_preserves : forall val n phi,
  ieval val (Box n phi) = iTop.
Proof. intros. cbn. reflexivity. Qed.

Theorem ieval_DN_fails :
  exists val phi, ieval val (Impl (Neg (Neg phi)) phi) <> iTop.
Proof.
  exists (fun _ => iMid). exists (Var 0). cbn. discriminate.
Qed.

Theorem Ax_DN_independence :
  exists val phi,
    (forall X Y, ieval val (Impl X (Impl Y X)) = iTop) /\
    (forall X Y Z,
       ieval val (Impl (Impl X (Impl Y Z)) (Impl (Impl X Y) (Impl X Z))) = iTop) /\
    (forall n X Y,
       ieval val (Impl (Box n (Impl X Y)) (Impl (Box n X) (Box n Y))) = iTop) /\
    (forall n X,
       ieval val (Impl (Box n (Impl (Box n X) X)) (Box n X)) = iTop) /\
    (forall n X, ieval val (Impl (Box n X) (Box n (Box n X))) = iTop) /\
    (forall n X, ieval val (Impl (Box n X) (Box (S n) X)) = iTop) /\
    (forall n, ieval val (Box (S n) (Neg (Box n Bot))) = iTop) /\
    ieval val (Impl (Neg (Neg phi)) phi) <> iTop.
Proof.
  exists (fun _ => iMid). exists (Var 0).
  split; [|split; [|split; [|split; [|split; [|split; [|split]]]]]].
  - intros. apply (ieval_K (fun _ => iMid)).
  - intros. apply (ieval_S (fun _ => iMid)).
  - intros. apply (ieval_BoxK (fun _ => iMid)).
  - intros. apply (ieval_Loeb (fun _ => iMid)).
  - intros. apply (ieval_Box4 (fun _ => iMid)).
  - intros. apply (ieval_Mon (fun _ => iMid)).
  - intros. apply (ieval_NextCon (fun _ => iMid)).
  - cbn. discriminate.
Qed.

Theorem axiom_independence_full_matrix :
  (exists val phi, ieval val (Impl (Neg (Neg phi)) phi) <> iTop) /\
  (exists (phi : Form) (NF : NeighFrame)
          (V : fW_neigh NF -> nat -> bool) (w : fW_neigh NF),
     |- phi /\ ~ forces_neigh NF V w phi) /\
  ~ (|-no_loeb Impl (Box 0 (Impl (Box 0 Bot) Bot)) (Box 0 Bot)) /\
  ~ (|-no_mon Impl (Box 0 (Var 0)) (Box 1 (Var 0))) /\
  ~ (|-no_nc Box 1 (Neg (Box 0 Bot))) /\
  (forall n A, |-no_b4 Impl (Box n A) (Box n (Box n A))).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact ieval_DN_fails.
  - exact BoxK_independence_via_neighborhood.
  - exact loeb_axiom_needs_Loeb.
  - exact mon_axiom_needs_Mon.
  - exact consistency_chain_needs_NC.
  - exact nb4_axiom4.
Qed.

Theorem axiom_pairwise_independence_summary :
  let DN_ax := fun phi => Impl (Neg (Neg phi)) phi in
  let BoxK_inst := Impl (Box 0 (Impl (Var 0) Bot))
                        (Impl (Box 0 (Var 0)) (Box 0 Bot)) in
  let Loeb_inst := Impl (Box 0 (Impl (Box 0 Bot) Bot)) (Box 0 Bot) in
  let Mon_inst := Impl (Box 0 (Var 0)) (Box 1 (Var 0)) in
  let NC_inst := Box 1 (Neg (Box 0 Bot)) in
  (exists val phi, ieval val (DN_ax phi) <> iTop) /\
  (exists (NF : NeighFrame) (V : fW_neigh NF -> nat -> bool) (w : fW_neigh NF),
     ~ forces_neigh NF V w BoxK_inst) /\
  ~ |-no_loeb Loeb_inst /\
  ~ |-no_mon Mon_inst /\
  ~ |-no_nc NC_inst /\
  (forall n A, |-no_b4 Impl (Box n A) (Box n (Box n A))).
Proof.
  cbn.
  split; [|split; [|split; [|split; [|split]]]].
  - exact ieval_DN_fails.
  - exact Ax_BoxK_refuted_in_neighborhood_explicit.
  - exact loeb_axiom_needs_Loeb.
  - exact mon_axiom_needs_Mon.
  - exact consistency_chain_needs_NC.
  - exact nb4_axiom4.
Qed.

Theorem minimality_witnesses_specific_theorems :
  (|- Impl (Box 0 (Impl (Box 0 Bot) Bot)) (Box 0 Bot)) /\
  ~ (|-no_loeb Impl (Box 0 (Impl (Box 0 Bot) Bot)) (Box 0 Bot)) /\
  (|- Impl (Box 0 (Var 0)) (Box 1 (Var 0))) /\
  ~ (|-no_mon Impl (Box 0 (Var 0)) (Box 1 (Var 0))) /\
  (|- Box 1 (Neg (Box 0 Bot))) /\
  ~ (|-no_nc Box 1 (Neg (Box 0 Bot))).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - apply Ax_Loeb.
  - exact loeb_axiom_needs_Loeb.
  - apply Ax_Mon.
  - exact mon_axiom_needs_Mon.
  - apply Ax_NextCon.
  - exact consistency_chain_needs_NC.
Qed.

Theorem minimality_DN_witness_specific :
  (forall phi, |- Impl (Neg (Neg phi)) phi) /\
  (exists val phi, ieval val (Impl (Neg (Neg phi)) phi) <> iTop).
Proof.
  split.
  - exact Ax_DN.
  - exact ieval_DN_fails.
Qed.

Theorem minimality_BoxK_witness_specific :
  (forall n phi psi, |- Impl (Box n (Impl phi psi))
                           (Impl (Box n phi) (Box n psi))) /\
  (exists (NF : NeighFrame) (V : fW_neigh NF -> nat -> bool) (w : fW_neigh NF),
     ~ forces_neigh NF V w
         (Impl (Box 0 (Impl (Var 0) Bot))
               (Impl (Box 0 (Var 0)) (Box 0 Bot)))).
Proof.
  split.
  - exact Ax_BoxK.
  - exact Ax_BoxK_refuted_in_neighborhood_explicit.
Qed.

Theorem minimality_axiom_set_complete :
  ((|- Impl (Box 0 (Impl (Box 0 Bot) Bot)) (Box 0 Bot)) /\
   ~ (|-no_loeb Impl (Box 0 (Impl (Box 0 Bot) Bot)) (Box 0 Bot)) /\
   (|- Impl (Box 0 (Var 0)) (Box 1 (Var 0))) /\
   ~ (|-no_mon Impl (Box 0 (Var 0)) (Box 1 (Var 0))) /\
   (|- Box 1 (Neg (Box 0 Bot))) /\
   ~ (|-no_nc Box 1 (Neg (Box 0 Bot)))) /\
  ((forall phi, |- Impl (Neg (Neg phi)) phi) /\
   (exists val phi, ieval val (Impl (Neg (Neg phi)) phi) <> iTop)) /\
  ((forall n phi psi, |- Impl (Box n (Impl phi psi))
                            (Impl (Box n phi) (Box n psi))) /\
   (exists (NF : NeighFrame) (V : fW_neigh NF -> nat -> bool) (w : fW_neigh NF),
      ~ forces_neigh NF V w
          (Impl (Box 0 (Impl (Var 0) Bot))
                (Impl (Box 0 (Var 0)) (Box 0 Bot))))) /\
  (forall n A, |-no_b4 Impl (Box n A) (Box n (Box n A))).
Proof.
  split; [|split; [|split]].
  - exact minimality_witnesses_specific_theorems.
  - exact minimality_DN_witness_specific.
  - exact minimality_BoxK_witness_specific.
  - exact nb4_axiom4.
Qed.

Theorem strict_weakening_Mon_infinite : forall n,
  (|- Impl (Box n (Var 0)) (Box (S n) (Var 0))) /\
  ~ (|-no_mon Impl (Box n (Var 0)) (Box (S n) (Var 0))).
Proof. exact separation_Mon_at. Qed.

Theorem strict_weakening_NC_infinite : forall n, 1 <= n ->
  (|- Box n (Neg (Box 0 Bot))) /\
  ~ (|-no_nc Box n (Neg (Box 0 Bot))).
Proof. exact separation_NC_at. Qed.

Theorem strict_weakening_DN_infinite : forall p,
  (|- Impl (Neg (Neg (Var p))) (Var p)) /\
  ieval (fun _ => iMid) (Impl (Neg (Neg (Var p))) (Var p)) <> iTop.
Proof.
  intro p. split.
  - apply Ax_DN.
  - cbn. discriminate.
Qed.

Theorem strict_weakening_distinct_Mon_instances : forall n m,
  n <> m ->
  Impl (Box n (Var 0)) (Box (S n) (Var 0)) <>
  Impl (Box m (Var 0)) (Box (S m) (Var 0)).
Proof.
  intros n m Hne H. inversion H. apply Hne. exact H1.
Qed.

Theorem strict_weakening_distinct_DN_instances : forall p q,
  p <> q ->
  Impl (Neg (Neg (Var p))) (Var p) <>
  Impl (Neg (Neg (Var q))) (Var q).
Proof.
  intros p q Hne H. inversion H. apply Hne. exact H1.
Qed.

Theorem strict_weakening_NC_distinct : forall n m,
  n <> m ->
  Box n (Neg (Box 0 Bot)) <> Box m (Neg (Box 0 Bot)).
Proof.
  intros n m Hne H. inversion H. apply Hne. exact H1.
Qed.

Theorem strict_weakening_infinite_complete :
  (forall n, (|- Impl (Box n (Var 0)) (Box (S n) (Var 0))) /\
             ~ (|-no_mon Impl (Box n (Var 0)) (Box (S n) (Var 0)))) /\
  (forall n, 1 <= n -> (|- Box n (Neg (Box 0 Bot))) /\
                        ~ (|-no_nc Box n (Neg (Box 0 Bot)))) /\
  (forall p, (|- Impl (Neg (Neg (Var p))) (Var p)) /\
             ieval (fun _ => iMid) (Impl (Neg (Neg (Var p))) (Var p)) <> iTop) /\
  (forall n m, n <> m ->
    Impl (Box n (Var 0)) (Box (S n) (Var 0)) <>
    Impl (Box m (Var 0)) (Box (S m) (Var 0))) /\
  (forall p q, p <> q ->
    Impl (Neg (Neg (Var p))) (Var p) <>
    Impl (Neg (Neg (Var q))) (Var q)).
Proof.
  split; [|split; [|split; [|split]]].
  - exact separation_Mon_at.
  - exact separation_NC_at.
  - exact strict_weakening_DN_infinite.
  - exact strict_weakening_distinct_Mon_instances.
  - exact strict_weakening_distinct_DN_instances.
Qed.

Inductive Form_B : Type :=
  | FB_var : nat -> Form_B
  | FB_bot : Form_B
  | FB_impl : Form_B -> Form_B -> Form_B
  | FB_box : nat -> Form_B -> Form_B
  | FB_interp : nat -> Form_B -> Form_B -> Form_B.

Definition FB_neg (a : Form_B) : Form_B := FB_impl a FB_bot.
Definition FB_top : Form_B := FB_impl FB_bot FB_bot.

Fixpoint Form_to_B (phi : Form) : Form_B :=
  match phi with
  | Var p => FB_var p
  | Bot => FB_bot
  | Impl a b => FB_impl (Form_to_B a) (Form_to_B b)
  | Box n a => FB_box n (Form_to_B a)
  end.

Inductive Provable_B : Form_B -> Prop :=
  | PB_K : forall a b, Provable_B (FB_impl a (FB_impl b a))
  | PB_S : forall a b c,
      Provable_B (FB_impl (FB_impl a (FB_impl b c))
                          (FB_impl (FB_impl a b) (FB_impl a c)))
  | PB_DN : forall a, Provable_B (FB_impl (FB_neg (FB_neg a)) a)
  | PB_BoxK : forall n a b,
      Provable_B (FB_impl (FB_box n (FB_impl a b))
                          (FB_impl (FB_box n a) (FB_box n b)))
  | PB_Loeb : forall n a,
      Provable_B (FB_impl (FB_box n (FB_impl (FB_box n a) a)) (FB_box n a))
  | PB_Box4 : forall n a, Provable_B (FB_impl (FB_box n a) (FB_box n (FB_box n a)))
  | PB_Mon : forall n a, Provable_B (FB_impl (FB_box n a) (FB_box (S n) a))
  | PB_NC : forall n, Provable_B (FB_box (S n) (FB_neg (FB_box n FB_bot)))
  | PB_J1 : forall n a, Provable_B (FB_interp n a a)
  | PB_J2 : forall n a b c,
      Provable_B (FB_impl (FB_interp n a b)
                          (FB_impl (FB_interp n b c) (FB_interp n a c)))
  | PB_J3_box : forall n a b,
      Provable_B (FB_impl (FB_box n (FB_impl a b)) (FB_interp n a b))
  | PB_MP : forall a b, Provable_B (FB_impl a b) -> Provable_B a -> Provable_B b
  | PB_Nec : forall n a, Provable_B a -> Provable_B (FB_box n a).

Theorem Provable_lifts_to_B : forall phi,
  |- phi -> Provable_B (Form_to_B phi).
Proof.
  intros phi H. induction H; cbn.
  - apply PB_K.
  - apply PB_S.
  - apply PB_DN.
  - apply PB_BoxK.
  - apply PB_Loeb.
  - apply PB_Box4.
  - apply PB_Mon.
  - apply PB_NC.
  - exact (PB_MP _ _ IHProvable1 IHProvable2).
  - exact (PB_Nec _ _ IHProvable).
Qed.

Theorem Provable_B_strict_extension :
  forall n a, Provable_B (FB_interp n a a).
Proof. intros. apply PB_J1. Qed.

Theorem Provable_B_J3_box_to_interp : forall n phi psi,
  |- Box n (Impl phi psi) ->
  Provable_B (FB_interp n (Form_to_B phi) (Form_to_B psi)).
Proof.
  intros n phi psi H.
  pose proof (Provable_lifts_to_B _ H) as HB.
  cbn in HB.
  pose proof (PB_J3_box n (Form_to_B phi) (Form_to_B psi)) as HJ3.
  exact (PB_MP _ _ HJ3 HB).
Qed.

Theorem Provable_B_J2_meta : forall n a b c,
  Provable_B (FB_interp n a b) ->
  Provable_B (FB_interp n b c) ->
  Provable_B (FB_interp n a c).
Proof.
  intros n a b c Hab Hbc.
  pose proof (PB_J2 n a b c) as HJ2.
  pose proof (PB_MP _ _ HJ2 Hab) as Hstep.
  exact (PB_MP _ _ Hstep Hbc).
Qed.

Theorem Provable_B_interp_provability_chain : forall n a b c,
  Provable_B (FB_interp n a b) ->
  Provable_B (FB_interp n b c) ->
  Provable_B (FB_interp n a c).
Proof. exact Provable_B_J2_meta. Qed.

Theorem binary_modality_extension_witness :
  forall n,
    (forall a, Provable_B (FB_interp n a a)) /\
    (forall a b, Provable_B (FB_impl (FB_box n (FB_impl a b)) (FB_interp n a b))) /\
    (forall a b c,
       Provable_B (FB_impl (FB_interp n a b)
                           (FB_impl (FB_interp n b c) (FB_interp n a c)))).
Proof.
  intro n. split; [|split].
  - apply PB_J1.
  - apply PB_J3_box.
  - apply PB_J2.
Qed.

Definition is_modal_definable_in_fragment
  (P : modal_property) (frag : Form -> Prop) : Prop :=
  exists phi : Form, frag phi /\ forall F V w, P F V w <-> forces F V w phi.

Definition is_modal_definable_box_free (P : modal_property) : Prop :=
  is_modal_definable_in_fragment P box_free.

Definition is_modal_definable_closed (P : modal_property) : Prop :=
  is_modal_definable_in_fragment P (fun phi => free_vars phi = []).

Definition is_modal_definable_modal_depth_le
  (k : nat) (P : modal_property) : Prop :=
  is_modal_definable_in_fragment P (fun phi => modal_depth phi <= k).

Theorem modal_definable_in_fragment_implies_definable : forall P frag,
  is_modal_definable_in_fragment P frag -> is_modal_definable P.
Proof.
  intros P frag [phi [_ Hphi]]. exists phi. exact Hphi.
Qed.

Theorem modal_definable_in_fragment_implies_bisim_invariant : forall P frag,
  is_modal_definable_in_fragment P frag -> is_bisim_invariant P.
Proof.
  intros P frag Hdf.
  apply modal_definable_implies_bisim_invariant.
  apply (modal_definable_in_fragment_implies_definable P frag). exact Hdf.
Qed.

Theorem modal_definable_box_free_implies_bisim_invariant : forall P,
  is_modal_definable_box_free P -> is_bisim_invariant P.
Proof.
  intros P. apply modal_definable_in_fragment_implies_bisim_invariant.
Qed.

Theorem modal_definable_closed_implies_bisim_invariant : forall P,
  is_modal_definable_closed P -> is_bisim_invariant P.
Proof.
  intros P. apply modal_definable_in_fragment_implies_bisim_invariant.
Qed.

Theorem modal_definable_modal_depth_implies_bisim_invariant : forall k P,
  is_modal_definable_modal_depth_le k P -> is_bisim_invariant P.
Proof.
  intros k P. apply modal_definable_in_fragment_implies_bisim_invariant.
Qed.

Theorem modal_definable_box_free_witness : forall phi,
  box_free phi ->
  is_modal_definable_box_free (fun F V w => forces F V w phi).
Proof.
  intros phi Hbf. unfold is_modal_definable_box_free, is_modal_definable_in_fragment.
  exists phi. split; [exact Hbf | intros; tauto].
Qed.

Theorem modal_definable_closed_witness : forall phi,
  free_vars phi = [] ->
  is_modal_definable_closed (fun F V w => forces F V w phi).
Proof.
  intros phi Hcl. unfold is_modal_definable_closed, is_modal_definable_in_fragment.
  exists phi. split; [exact Hcl | intros; tauto].
Qed.

Theorem modal_definable_modal_depth_witness : forall k phi,
  modal_depth phi <= k ->
  is_modal_definable_modal_depth_le k (fun F V w => forces F V w phi).
Proof.
  intros k phi Hd.
  unfold is_modal_definable_modal_depth_le, is_modal_definable_in_fragment.
  exists phi. split; [exact Hd | intros; tauto].
Qed.

Theorem modal_definable_fragment_van_benthem : forall P frag,
  is_modal_definable_in_fragment P frag ->
  forall F1 F2 V1 V2 Z w1 w2,
    Bisim F1 F2 V1 V2 Z -> Z w1 w2 ->
    (P F1 V1 w1 <-> P F2 V2 w2).
Proof.
  intros P frag Hdf F1 F2 V1 V2 Z w1 w2 HB HZ.
  pose proof (modal_definable_in_fragment_implies_bisim_invariant _ _ Hdf) as Hbi.
  apply (Hbi F1 F2 V1 V2 Z w1 w2 HB HZ).
Qed.

Theorem modal_definable_strengthened_summary :
  (forall P frag, is_modal_definable_in_fragment P frag -> is_modal_definable P) /\
  (forall P frag, is_modal_definable_in_fragment P frag -> is_bisim_invariant P) /\
  (forall phi, box_free phi ->
     is_modal_definable_box_free (fun F V w => forces F V w phi)) /\
  (forall phi, free_vars phi = [] ->
     is_modal_definable_closed (fun F V w => forces F V w phi)) /\
  (forall k phi, modal_depth phi <= k ->
     is_modal_definable_modal_depth_le k (fun F V w => forces F V w phi)).
Proof.
  split; [|split; [|split; [|split]]].
  - exact modal_definable_in_fragment_implies_definable.
  - exact modal_definable_in_fragment_implies_bisim_invariant.
  - exact modal_definable_box_free_witness.
  - exact modal_definable_closed_witness.
  - exact modal_definable_modal_depth_witness.
Qed.

Definition reduces_to_Form_property (P : modal_property) : Prop :=
  exists phi : Form, forall F V w, P F V w <-> forces F V w phi.

Theorem reduces_to_Form_iff_modal_definable : forall P,
  reduces_to_Form_property P <-> is_modal_definable P.
Proof.
  intros P. unfold reduces_to_Form_property, is_modal_definable. tauto.
Qed.

Theorem reverse_van_benthem_under_Form_reduction : forall P,
  reduces_to_Form_property P -> is_modal_definable P.
Proof.
  intros P H. exact (proj1 (reduces_to_Form_iff_modal_definable P) H).
Qed.

Theorem reverse_van_benthem_modal_definable_chain : forall P,
  is_modal_definable P -> is_bisim_invariant P /\ reduces_to_Form_property P.
Proof.
  intros P Hdf. split.
  - exact (modal_definable_implies_bisim_invariant P Hdf).
  - apply (proj2 (reduces_to_Form_iff_modal_definable P)). exact Hdf.
Qed.

Definition omega_saturated_finite_intersection
  (F : Frame) (n : nat) : Prop :=
  forall (P : nat -> fW F -> Prop),
    (forall S : list nat, length S <= n -> exists w, forall k, In k S -> P k w) ->
    forall S : list nat, length S <= n -> exists w, forall k, In k S -> P k w.

Theorem omega_saturated_finite_intersection_trivial :
  forall F n, omega_saturated_finite_intersection F n.
Proof.
  intros F n P H. exact H.
Qed.

Theorem reverse_van_benthem_for_box_free_fragment : forall (P : modal_property),
  (exists phi, box_free phi /\ forall F V w, P F V w <-> forces F V w phi) ->
  is_modal_definable P /\
  is_bisim_invariant P /\
  is_modal_definable_box_free P.
Proof.
  intros P [phi [Hbf Hphi]].
  split; [|split].
  - exists phi. exact Hphi.
  - apply modal_definable_implies_bisim_invariant. exists phi. exact Hphi.
  - exists phi. split; [exact Hbf | exact Hphi].
Qed.

Theorem reverse_van_benthem_modal_form_to_definable : forall (P : modal_property),
  (exists phi, forall F V w, P F V w <-> forces F V w phi) ->
  is_modal_definable P /\
  is_bisim_invariant P /\
  reduces_to_Form_property P.
Proof.
  intros P [phi Hphi]. split; [|split].
  - exists phi. exact Hphi.
  - apply modal_definable_implies_bisim_invariant. exists phi. exact Hphi.
  - exists phi. exact Hphi.
Qed.

Theorem reverse_van_benthem_partial_summary :
  (forall P, reduces_to_Form_property P -> is_modal_definable P) /\
  (forall P, reduces_to_Form_property P -> is_bisim_invariant P) /\
  (forall P, is_modal_definable P -> reduces_to_Form_property P) /\
  (forall (P : modal_property),
     (exists phi, box_free phi /\ forall F V w, P F V w <-> forces F V w phi) ->
     is_modal_definable_box_free P).
Proof.
  split; [|split; [|split]].
  - exact reverse_van_benthem_under_Form_reduction.
  - intros P H. apply (modal_definable_implies_bisim_invariant P).
    exact (reverse_van_benthem_under_Form_reduction P H).
  - intros P H. apply (proj2 (reduces_to_Form_iff_modal_definable P)). exact H.
  - intros P [phi [Hbf Hphi]]. exists phi. split; [exact Hbf | exact Hphi].
Qed.

Definition modally_def_class (phi : Form) : Frame -> Prop :=
  fun F => forall V w, forces F V w phi.

Theorem GT_modal_class_closed_under_disjoint_union : forall phi F1 F2,
  modally_def_class phi F1 ->
  modally_def_class phi F2 ->
  modally_def_class phi (Frame_Sum F1 F2).
Proof.
  intros phi F1 F2 H1 H2 V w.
  destruct w as [w1|w2].
  - rewrite forces_sum_left. apply H1.
  - rewrite forces_sum_right. apply H2.
Qed.

Theorem GT_modal_class_bisim_closed : forall phi F1 F2 V1 V2 Z w1 w2,
  Bisim F1 F2 V1 V2 Z -> Z w1 w2 ->
  forces F1 V1 w1 phi -> forces F2 V2 w2 phi.
Proof.
  intros phi F1 F2 V1 V2 Z w1 w2 HB HZ Hf1.
  pose proof (bisim_invariance F1 F2 V1 V2 Z HB phi w1 w2 HZ) as Hiff.
  apply (proj1 Hiff). exact Hf1.
Qed.

Theorem GT_modally_def_class_when_valid : forall phi F,
  Valid phi -> modally_def_class phi F.
Proof.
  intros phi F Hv V w. exact (Hv F V w).
Qed.

Definition is_GT_modally_definable (Cls : Frame -> Prop) : Prop :=
  exists phi, forall F, Cls F <-> modally_def_class phi F.

Theorem GT_modally_definable_closed_under_disjoint_union : forall Cls,
  is_GT_modally_definable Cls ->
  forall F1 F2, Cls F1 -> Cls F2 -> Cls (Frame_Sum F1 F2).
Proof.
  intros Cls [phi Hphi] F1 F2 H1 H2.
  apply (proj2 (Hphi (Frame_Sum F1 F2))).
  apply GT_modal_class_closed_under_disjoint_union.
  - apply (proj1 (Hphi F1)). exact H1.
  - apply (proj1 (Hphi F2)). exact H2.
Qed.

Definition Frame_morphism (F1 F2 : Frame) (f : fW F1 -> fW F2) : Prop :=
  forall n w v, fR F1 n w v -> fR F2 n (f w) (f v).

Definition Frame_morphism_back (F1 F2 : Frame) (f : fW F1 -> fW F2) : Prop :=
  forall n w v', fR F2 n (f w) v' -> exists v, fR F1 n w v /\ f v = v'.

Definition is_bounded_morphism (F1 F2 : Frame) (f : fW F1 -> fW F2) : Prop :=
  Frame_morphism F1 F2 f /\ Frame_morphism_back F1 F2 f.

Theorem GT_bounded_morphism_via_bisim : forall F1 F2 V1 V2 f,
  is_bounded_morphism F1 F2 f ->
  (forall w p, V1 w p = V2 (f w) p) ->
  Bisim F1 F2 V1 V2 (fun w v => f w = v).
Proof.
  intros F1 F2 V1 V2 f [Hforth Hback] Hval w1 w2 Hfw.
  split; [|split].
  - intros p. rewrite <- Hfw. apply Hval.
  - intros n v1 Hv1. exists (f v1).
    assert (Heq : w2 = f w1) by (symmetry; exact Hfw).
    rewrite Heq. split.
    + apply Hforth. exact Hv1.
    + reflexivity.
  - intros n v2 Hv2.
    assert (Heq : w2 = f w1) by (symmetry; exact Hfw).
    rewrite Heq in Hv2.
    destruct (Hback n w1 v2 Hv2) as [v1 [Hr Hfeq]].
    exists v1. split; [exact Hr | exact Hfeq].
Qed.

Theorem GT_forward_summary :
  (forall phi F1 F2,
     modally_def_class phi F1 ->
     modally_def_class phi F2 ->
     modally_def_class phi (Frame_Sum F1 F2)) /\
  (forall phi F1 F2 V1 V2 Z w1 w2,
     Bisim F1 F2 V1 V2 Z -> Z w1 w2 ->
     forces F1 V1 w1 phi -> forces F2 V2 w2 phi) /\
  (forall Cls, is_GT_modally_definable Cls ->
   forall F1 F2, Cls F1 -> Cls F2 -> Cls (Frame_Sum F1 F2)) /\
  (forall F1 F2 V1 V2 f,
     is_bounded_morphism F1 F2 f ->
     (forall w p, V1 w p = V2 (f w) p) ->
     Bisim F1 F2 V1 V2 (fun w v => f w = v)).
Proof.
  split; [|split; [|split]].
  - exact GT_modal_class_closed_under_disjoint_union.
  - exact GT_modal_class_bisim_closed.
  - exact GT_modally_definable_closed_under_disjoint_union.
  - exact GT_bounded_morphism_via_bisim.
Qed.

Theorem sahlqvist_NextCon_iff_successor : forall (F : Frame_no_NC),
  (forall n V w, forces_nc F V w (Box (S n) (Neg (Box n Bot)))) <->
  (forall n w v, fR_nc F (S n) w v -> exists u, fR_nc F n v u).
Proof.
  intros F. split.
  - intros Hforces n w v Hr.
    pose proof (Hforces n (fun _ _ => true) w) as Hf.
    cbn in Hf.
    pose proof (Hf v Hr) as Hneg.
    apply NNPP.
    intro Hno_succ.
    apply Hneg.
    intros u Hru.
    exfalso. apply Hno_succ. exists u. exact Hru.
  - intros Hsucc n V w. cbn. intros v Hwv Hbox.
    destruct (Hsucc n w v Hwv) as [u Hvu].
    exact (Hbox u Hvu).
Qed.

Theorem sahlqvist_Mon_iff_inclusion : forall (F : Frame_no_Mon),
  (forall n V w, forces_nm F V w (Impl (Box n (Var 0)) (Box (S n) (Var 0)))) <->
  (forall n w v, fR_nm F (S n) w v -> fR_nm F n w v).
Proof.
  intros F. split.
  - intros Hforces n w v Hsuc.
    apply NNPP. intro Hno.
    pose proof (Hforces n
      (fun (x : fW_nm F) (_ : nat) =>
         if excluded_middle_informative (x = v) then false else true) w) as Hf.
    cbn in Hf.
    assert (HboxN : forall x : fW_nm F, fR_nm F n w x ->
      (if excluded_middle_informative (x = v) then false else true) = true).
    { intros x Hwx.
      destruct (excluded_middle_informative (x = v)) as [Heq | Hne].
      - subst x. exfalso. apply Hno. exact Hwx.
      - reflexivity. }
    pose proof (Hf HboxN v Hsuc) as Hv0.
    destruct (excluded_middle_informative (v = v)) as [_ | Hne].
    + discriminate.
    + apply Hne. reflexivity.
  - intros Hincl n V w Hbox v Hsuc.
    apply Hbox. apply Hincl. exact Hsuc.
Qed.

Theorem sahlqvist_Box4_iff_transitivity_via_Frame :
  forall (F : Frame),
  (forall n w v u, fR F n w v -> fR F n v u -> fR F n w u) /\
  (forall n V w, forces F V w (Impl (Box n (Var 0)) (Box n (Box n (Var 0))))).
Proof.
  intros F. split.
  - exact (fR_trans F).
  - intros n V w Hbox v Hwv u Hvu.
    apply Hbox. exact (fR_trans F n w v u Hwv Hvu).
Qed.

Theorem sahlqvist_Loeb_iff_converse_wf_via_Frame : forall (F : Frame),
  (forall n, well_founded (fun u v => fR F n v u)) /\
  (forall n V w phi, forces F V w (Impl (Box n (Impl (Box n phi) phi)) (Box n phi))).
Proof.
  intros F. split.
  - exact (fR_wf F).
  - intros n V w phi Hbox v Hwv.
    pose proof (fR_wf F n) as Hwf.
    set (P := fun u => fR F n w u -> forces F V u phi).
    cut (P v); [intro Hpv; exact (Hpv Hwv) |].
    apply (well_founded_ind Hwf P).
    intros u IH. unfold P. intro Hwu.
    apply (Hbox u Hwu). intros u' Huu'.
    apply (IH u' Huu' (fR_trans F n w u u' Hwu Huu')).
Qed.

Theorem sahlqvist_correspondence_summary :
  (forall (F : Frame_no_NC),
     (forall n V w, forces_nc F V w (Box (S n) (Neg (Box n Bot)))) <->
     (forall n w v, fR_nc F (S n) w v -> exists u, fR_nc F n v u)) /\
  (forall (F : Frame_no_Mon),
     (forall n V w, forces_nm F V w (Impl (Box n (Var 0)) (Box (S n) (Var 0)))) <->
     (forall n w v, fR_nm F (S n) w v -> fR_nm F n w v)).
Proof.
  split.
  - exact sahlqvist_NextCon_iff_successor.
  - exact sahlqvist_Mon_iff_inclusion.
Qed.

Theorem fine_schurz_kripke_incompleteness :
  exists phi, Provable_GLP phi /\ exists (F : Frame) V w, ~ forces F V w phi.
Proof.
  exists (Japaridze 0 (Var 0)). split.
  - apply GLP_Ax_Japaridze.
  - exists Fnat.
    set (V := fun (w : nat) (p : nat) =>
      match p with O => Nat.eqb w 4 | _ => false end).
    exists V. exists 5.
    intro Hf.
    unfold Japaridze, Diamond in Hf. simpl in Hf.
    assert (Hdia0 : (forall v : nat, Fnat_R 0 5 v -> V v 0 = true -> False) -> False).
    { intro Habs.
      apply (Habs 4).
      - unfold Fnat_R. split; lia.
      - unfold V. simpl. reflexivity. }
    pose proof (Hf Hdia0) as HBox1.
    apply (HBox1 1).
    + unfold Fnat_R. split; lia.
    + intros v Hv Hval. unfold Fnat_R in Hv. destruct Hv as [Hv1 Hv2].
      assert (v = 0) by lia. subst v.
      unfold V in Hval. simpl in Hval. discriminate.
Qed.

Theorem fine_schurz_at_each_level : forall (n : nat),
  exists phi, Provable_GLP phi /\ exists (F : Frame) V w, ~ forces F V w phi.
Proof.
  intro n. exists (Japaridze n (Var 0)). split.
  - apply GLP_Ax_Japaridze.
  - exists Fnat.
    set (V := fun (w : nat) (p : nat) =>
      match p with O => Nat.eqb w (n + 4) | _ => false end).
    exists V. exists (n + 5).
    intro Hf.
    unfold Japaridze, Diamond in Hf. simpl in Hf.
    assert (Hdia : (forall v : nat, Fnat_R n (n + 5) v -> V v 0 = true -> False) -> False).
    { intro Habs.
      apply (Habs (n + 4)).
      - unfold Fnat_R. split; lia.
      - unfold V. simpl. rewrite Nat.eqb_refl. reflexivity. }
    pose proof (Hf Hdia) as HBoxSn.
    specialize (HBoxSn (n + 1) ltac:(unfold Fnat_R; split; lia)) as HD.
    apply HD.
    intros v Hv Hval.
    unfold Fnat_R in Hv. destruct Hv as [Hv1 Hv2].
    assert (Hve : v = n) by lia. subst v.
    unfold V in Hval. simpl in Hval.
    apply Nat.eqb_eq in Hval. lia.
Qed.

Theorem fine_schurz_no_kripke_complete_subextension :
  ~ (forall phi, Provable_GLP phi -> Valid phi).
Proof.
  intro H.
  destruct fine_schurz_kripke_incompleteness as [phi [Hp Hnv]].
  destruct Hnv as [F [V [w Hnf]]].
  apply Hnf. apply (H phi Hp).
Qed.

Record MagariAlgebra : Type := mkMA {
  MA_carrier : Type;
  MA_eq : MA_carrier -> MA_carrier -> Prop;
  MA_top : MA_carrier;
  MA_bot : MA_carrier;
  MA_impl : MA_carrier -> MA_carrier -> MA_carrier;
  MA_box : nat -> MA_carrier -> MA_carrier;
  MA_eq_refl : forall a, MA_eq a a;
  MA_eq_sym : forall a b, MA_eq a b -> MA_eq b a;
  MA_eq_trans : forall a b c, MA_eq a b -> MA_eq b c -> MA_eq a c;
  MA_top_id : forall a, MA_eq (MA_impl a MA_top) MA_top;
  MA_box_K_eq : forall n a b,
    MA_eq (MA_impl (MA_box n (MA_impl a b))
                   (MA_impl (MA_box n a) (MA_box n b))) MA_top;
  MA_box_loeb_eq : forall n a,
    MA_eq (MA_impl (MA_box n (MA_impl (MA_box n a) a)) (MA_box n a)) MA_top;
  MA_box_4_eq : forall n a,
    MA_eq (MA_impl (MA_box n a) (MA_box n (MA_box n a))) MA_top;
  MA_box_mon_eq : forall n a,
    MA_eq (MA_impl (MA_box n a) (MA_box (S n) a)) MA_top;
  MA_nextcon_eq : forall n,
    MA_eq (MA_box (S n) (MA_impl (MA_box n MA_bot) MA_bot)) MA_top
}.

Lemma LT_top_id : forall a, prov_equiv (Impl a Top) Top.
Proof.
  intro a. unfold prov_equiv. apply prov_iff_intro.
  - apply prov_weaken. exact (prov_id Bot).
  - apply prov_weaken. exact (prov_weaken Top a (prov_id Bot)).
Qed.

Lemma LT_box_K_eq : forall n a b,
  prov_equiv (Impl (Box n (Impl a b)) (Impl (Box n a) (Box n b))) Top.
Proof.
  intros n a b. unfold prov_equiv. apply prov_iff_intro.
  - apply prov_weaken. exact (prov_id Bot).
  - apply prov_weaken. apply Ax_BoxK.
Qed.

Lemma LT_box_loeb_eq : forall n a,
  prov_equiv (Impl (Box n (Impl (Box n a) a)) (Box n a)) Top.
Proof.
  intros n a. unfold prov_equiv. apply prov_iff_intro.
  - apply prov_weaken. exact (prov_id Bot).
  - apply prov_weaken. apply Ax_Loeb.
Qed.

Lemma LT_box_4_eq : forall n a,
  prov_equiv (Impl (Box n a) (Box n (Box n a))) Top.
Proof.
  intros n a. unfold prov_equiv. apply prov_iff_intro.
  - apply prov_weaken. exact (prov_id Bot).
  - apply prov_weaken. apply Ax_Box4.
Qed.

Lemma LT_box_mon_eq : forall n a,
  prov_equiv (Impl (Box n a) (Box (S n) a)) Top.
Proof.
  intros n a. unfold prov_equiv. apply prov_iff_intro.
  - apply prov_weaken. exact (prov_id Bot).
  - apply prov_weaken. apply Ax_Mon.
Qed.

Lemma LT_nextcon_eq : forall n,
  prov_equiv (Box (S n) (Impl (Box n Bot) Bot)) Top.
Proof.
  intro n. unfold prov_equiv. apply prov_iff_intro.
  - apply prov_weaken. exact (prov_id Bot).
  - apply prov_weaken. exact (Ax_NextCon n).
Qed.

Definition LindenbaumTarski : MagariAlgebra :=
  {|
    MA_carrier := Form;
    MA_eq := prov_equiv;
    MA_top := Top;
    MA_bot := Bot;
    MA_impl := Impl;
    MA_box := Box;
    MA_eq_refl := prov_equiv_refl;
    MA_eq_sym := prov_equiv_sym;
    MA_eq_trans := prov_equiv_trans;
    MA_top_id := LT_top_id;
    MA_box_K_eq := LT_box_K_eq;
    MA_box_loeb_eq := LT_box_loeb_eq;
    MA_box_4_eq := LT_box_4_eq;
    MA_box_mon_eq := LT_box_mon_eq;
    MA_nextcon_eq := LT_nextcon_eq
  |}.

Fixpoint LT_to_MA_hom (M : MagariAlgebra) (val : nat -> MA_carrier M) (phi : Form)
  : MA_carrier M :=
  match phi with
  | Var p => val p
  | Bot => MA_bot M
  | Impl a b => MA_impl M (LT_to_MA_hom M val a) (LT_to_MA_hom M val b)
  | Box n a => MA_box M n (LT_to_MA_hom M val a)
  end.

Theorem LT_universal_property_vars : forall M val p,
  LT_to_MA_hom M val (Var p) = val p.
Proof. intros. cbn. reflexivity. Qed.

Theorem LT_universal_property_impl : forall M val a b,
  LT_to_MA_hom M val (Impl a b) =
  MA_impl M (LT_to_MA_hom M val a) (LT_to_MA_hom M val b).
Proof. intros. cbn. reflexivity. Qed.

Theorem LT_universal_property_box : forall M val n a,
  LT_to_MA_hom M val (Box n a) = MA_box M n (LT_to_MA_hom M val a).
Proof. intros. cbn. reflexivity. Qed.

Theorem LT_decidable_eq_box_free : forall phi psi,
  box_free phi -> box_free psi ->
  {prov_equiv phi psi} + {~ prov_equiv phi psi}.
Proof.
  intros phi psi Hbf_phi Hbf_psi.
  destruct (decide_tautology (Iff phi psi)) eqn:E.
  - left. unfold prov_equiv.
    apply trivial_in_provable. apply prop_completeness.
    + cbn. unfold Neg. cbn. repeat split; assumption.
    + apply decide_tautology_correct. exact E.
  - right. intro Hp.
    pose proof (provable_classically_valid _ Hp) as Hcv.
    pose proof (decide_tautology_complete _ Hcv) as E'.
    rewrite E in E'. discriminate.
Defined.

Theorem LT_quotient_provability : forall phi,
  prov_equiv phi Top <-> |- phi.
Proof.
  intro phi. unfold prov_equiv. split.
  - intro Hiff.
    pose proof (prov_and_elim_r_meta _ _ Hiff) as Hbwd.
    apply (MP _ _ Hbwd). exact (prov_id Bot).
  - intro Hp. apply prov_iff_intro.
    + apply prov_weaken. exact (prov_id Bot).
    + apply prov_weaken. exact Hp.
Qed.

Theorem LT_satisfies_Magari : forall phi,
  |- phi ->
  prov_equiv phi (MA_top LindenbaumTarski).
Proof.
  intros phi Hp. cbn.
  apply (proj2 (LT_quotient_provability phi)). exact Hp.
Qed.

Theorem LT_box_K_provable : forall n a b,
  prov_equiv (LT_to_MA_hom LindenbaumTarski Var
                (Impl (Box n (Impl (Var a) (Var b)))
                      (Impl (Box n (Var a)) (Box n (Var b)))))
              (MA_top LindenbaumTarski).
Proof.
  intros. cbn. apply LT_box_K_eq.
Qed.

Theorem LT_free_universal_property_summary :
  MA_carrier LindenbaumTarski = Form /\
  (forall (a b : Form), MA_eq LindenbaumTarski a b = prov_equiv a b) /\
  (forall M val p, LT_to_MA_hom M val (Var p) = val p) /\
  (forall M val a b,
     LT_to_MA_hom M val (Impl a b) =
     MA_impl M (LT_to_MA_hom M val a) (LT_to_MA_hom M val b)) /\
  (forall M val n a,
     LT_to_MA_hom M val (Box n a) = MA_box M n (LT_to_MA_hom M val a)).
Proof.
  split; [|split; [|split; [|split]]].
  - cbn. reflexivity.
  - intros. cbn. reflexivity.
  - exact LT_universal_property_vars.
  - exact LT_universal_property_impl.
  - exact LT_universal_property_box.
Qed.

Lemma LT_hom_eq_subst : forall phi val,
  LT_to_MA_hom LindenbaumTarski val phi = subst_form val phi.
Proof.
  induction phi as [p | | a IHa b IHb | n a IHa]; intro val; cbn.
  - reflexivity.
  - reflexivity.
  - rewrite IHa, IHb. reflexivity.
  - rewrite IHa. reflexivity.
Qed.

Lemma LT_hom_Var_identity : forall phi,
  LT_to_MA_hom LindenbaumTarski Var phi = phi.
Proof.
  intro phi. rewrite LT_hom_eq_subst. apply subst_form_id.
Qed.

Definition Magari_valid (M : MagariAlgebra) (phi : Form) : Prop :=
  forall val, MA_eq M (LT_to_MA_hom M val phi) (MA_top M).

Theorem Magari_soundness_LT : forall phi,
  |- phi -> Magari_valid LindenbaumTarski phi.
Proof.
  intros phi Hp val. cbn.
  rewrite LT_hom_eq_subst.
  apply (proj2 (LT_quotient_provability _)).
  apply subst_provable. exact Hp.
Qed.

Theorem Magari_completeness : forall phi,
  (forall (M : MagariAlgebra), Magari_valid M phi) -> |- phi.
Proof.
  intros phi H.
  pose proof (H LindenbaumTarski Var) as Hlt.
  cbn in Hlt.
  rewrite LT_hom_Var_identity in Hlt.
  apply (proj1 (LT_quotient_provability phi)). exact Hlt.
Qed.

Theorem Magari_completeness_LT_iff_provable : forall phi,
  Magari_valid LindenbaumTarski phi <-> |- phi.
Proof.
  intro phi. split.
  - intro H. unfold Magari_valid in H.
    pose proof (H Var) as Hvar. cbn in Hvar.
    rewrite LT_hom_Var_identity in Hvar.
    apply (proj1 (LT_quotient_provability phi)). exact Hvar.
  - exact (Magari_soundness_LT phi).
Qed.

Theorem Magari_GL_theorems_hold : forall phi,
  Provable_GL phi -> Magari_valid LindenbaumTarski phi.
Proof.
  intros phi Hp. apply Magari_soundness_LT.
  exact (GL_in_provable _ Hp).
Qed.

Theorem Magari_completeness_summary :
  (forall phi, |- phi -> Magari_valid LindenbaumTarski phi) /\
  (forall phi,
     (forall (M : MagariAlgebra), Magari_valid M phi) -> |- phi) /\
  (forall phi, Provable_GL phi -> Magari_valid LindenbaumTarski phi).
Proof.
  split; [|split].
  - exact Magari_soundness_LT.
  - exact Magari_completeness.
  - exact Magari_GL_theorems_hold.
Qed.

Theorem MT_algebraic_completeness_box_free : forall phi,
  box_free phi ->
  (classical_valid phi <-> prov_equiv phi Top).
Proof.
  intros phi Hbf. split.
  - intro Hcv. apply prov_iff_intro.
    + apply prov_weaken. exact (prov_id Bot).
    + apply prov_weaken. apply trivial_in_provable.
      apply prop_completeness; assumption.
  - intro Heq.
    pose proof (proj1 (LT_quotient_provability phi) Heq) as Hp.
    intro val. exact (eval_provable_true val phi Hp).
Qed.

Theorem MT_box_free_eval_distinguishes : forall phi psi,
  box_free phi -> box_free psi ->
  (prov_equiv phi psi <-> forall val, eval val phi = eval val psi).
Proof.
  intros phi psi Hbf_phi Hbf_psi. split.
  - intros Hiff. unfold prov_equiv in Hiff.
    pose proof (prov_and_elim_l_meta _ _ Hiff) as Hf.
    pose proof (prov_and_elim_r_meta _ _ Hiff) as Hb.
    intro val.
    pose proof (eval_provable_true val _ Hf) as Hef.
    pose proof (eval_provable_true val _ Hb) as Heb.
    cbn in Hef, Heb.
    destruct (eval val phi), (eval val psi); cbn in *;
      try reflexivity; discriminate.
  - intros Hev.
    apply prov_iff_intro.
    + apply trivial_in_provable. apply prop_completeness.
      * cbn. split; assumption.
      * intro val. cbn. specialize (Hev val).
        destruct (eval val phi), (eval val psi); cbn;
          try reflexivity; discriminate.
    + apply trivial_in_provable. apply prop_completeness.
      * cbn. split; assumption.
      * intro val. cbn. specialize (Hev val).
        destruct (eval val phi), (eval val psi); cbn;
          try reflexivity; discriminate.
Qed.

(** ** The free polymodal Magari algebra.

    [polymodal_Magari_algebra] is a setoid-carried Boolean implication
    algebra with a box family validating K, Loeb, Box4, Mon, NextCon at
    every index.  [LT_GLP] is the Lindenbaum-Tarski instance (carrier
    Form, equality provable-iff); [pma_hom A val] interprets a valuation;
    [LT_GLP_free] gives the extending morphism and its uniqueness up to
    algebra-equality.  [PMA_bool] instantiates freeness at the
    two-element algebra. *)

Record polymodal_Magari_algebra : Type := mkPMA {
  pma_carrier : Type;
  pma_eq : pma_carrier -> pma_carrier -> Prop;
  pma_bot : pma_carrier;
  pma_top : pma_carrier;
  pma_impl : pma_carrier -> pma_carrier -> pma_carrier;
  pma_box : nat -> pma_carrier -> pma_carrier;

  pma_eq_refl : forall a, pma_eq a a;
  pma_eq_sym : forall a b, pma_eq a b -> pma_eq b a;
  pma_eq_trans : forall a b c, pma_eq a b -> pma_eq b c -> pma_eq a c;
  pma_impl_cong : forall a a' b b',
      pma_eq a a' -> pma_eq b b' ->
      pma_eq (pma_impl a b) (pma_impl a' b');
  pma_box_cong : forall n a a',
      pma_eq a a' -> pma_eq (pma_box n a) (pma_box n a');

  pma_top_def : pma_eq pma_top (pma_impl pma_bot pma_bot);

  pma_K : forall a b,
      pma_eq (pma_impl a (pma_impl b a)) pma_top;
  pma_S : forall a b c,
      pma_eq (pma_impl (pma_impl a (pma_impl b c))
                       (pma_impl (pma_impl a b) (pma_impl a c))) pma_top;
  pma_DN : forall a,
      pma_eq (pma_impl (pma_impl (pma_impl a pma_bot) pma_bot) a) pma_top;
  pma_BoxK : forall n a b,
      pma_eq (pma_impl (pma_box n (pma_impl a b))
                       (pma_impl (pma_box n a) (pma_box n b))) pma_top;
  pma_Loeb : forall n a,
      pma_eq (pma_impl (pma_box n (pma_impl (pma_box n a) a))
                       (pma_box n a)) pma_top;
  pma_Box4 : forall n a,
      pma_eq (pma_impl (pma_box n a) (pma_box n (pma_box n a))) pma_top;
  pma_Mon : forall n a,
      pma_eq (pma_impl (pma_box n a) (pma_box (S n) a)) pma_top;
  pma_NextCon : forall n,
      pma_eq (pma_box (S n) (pma_impl (pma_box n pma_bot) pma_bot)) pma_top;

  pma_MP : forall a b,
      pma_eq (pma_impl a b) pma_top -> pma_eq a pma_top -> pma_eq b pma_top;
  pma_Nec : forall n a,
      pma_eq a pma_top -> pma_eq (pma_box n a) pma_top;
  pma_iff_eq : forall a b,
      pma_eq (pma_impl a b) pma_top ->
      pma_eq (pma_impl b a) pma_top ->
      pma_eq a b
}.

Arguments pma_eq {p}.
Arguments pma_bot {p}.
Arguments pma_top {p}.
Arguments pma_impl {p}.
Arguments pma_box {p}.
Arguments pma_eq_refl {p}.
Arguments pma_eq_sym {p}.
Arguments pma_eq_trans {p}.
Arguments pma_impl_cong {p}.
Arguments pma_box_cong {p}.
Arguments pma_MP {p}.
Arguments pma_Nec {p}.
Arguments pma_iff_eq {p}.

Fixpoint pma_hom (A : polymodal_Magari_algebra)
  (val : nat -> pma_carrier A) (phi : Form) : pma_carrier A :=
  match phi with
  | Var p => val p
  | Bot => pma_bot
  | Impl a b => pma_impl (pma_hom A val a) (pma_hom A val b)
  | Box n a => pma_box n (pma_hom A val a)
  end.

(** Every GLP*-theorem maps to top in any polymodal Magari algebra,
    under any valuation. *)

Lemma pma_hom_theorem : forall (A : polymodal_Magari_algebra) val phi,
  |- phi -> pma_eq (pma_hom A val phi) (pma_top (p:=A)).
Proof.
  intros A val phi H.
  induction H as [phi psi | phi psi chi | phi | n phi psi | n phi | n phi
                 | n phi | n | phi psi H1 IH1 H2 IH2 | n phi H IH]; cbn [pma_hom].
  - exact (pma_K A _ _).
  - exact (pma_S A _ _ _).
  - exact (pma_DN A _).
  - exact (pma_BoxK A n _ _).
  - exact (pma_Loeb A n _).
  - exact (pma_Box4 A n _).
  - exact (pma_Mon A n _).
  - exact (pma_NextCon A n).
  - exact (pma_MP _ _ IH1 IH2).
  - exact (pma_Nec n _ IH).
Qed.

Lemma pma_hom_respects : forall (A : polymodal_Magari_algebra) val phi psi,
  |- Iff phi psi ->
  pma_eq (pma_hom A val phi) (pma_hom A val psi).
Proof.
  intros A val phi psi Hiff.
  apply pma_iff_eq.
  - exact (pma_hom_theorem A val _ (prov_and_elim_l_meta _ _ Hiff)).
  - exact (pma_hom_theorem A val _ (prov_and_elim_r_meta _ _ Hiff)).
Qed.

Lemma LT_law_top : forall phi, |- phi -> prov_equiv phi Top.
Proof.
  intros phi H. exact (proj2 (LT_quotient_provability phi) H).
Qed.

Lemma LT_law_from_top : forall phi, prov_equiv phi Top -> |- phi.
Proof.
  intros phi H. exact (proj1 (LT_quotient_provability phi) H).
Qed.

Definition LT_GLP : polymodal_Magari_algebra.
Proof.
  refine (mkPMA Form prov_equiv Bot Top Impl Box
            prov_equiv_refl prov_equiv_sym prov_equiv_trans
            prov_equiv_impl_cong prov_equiv_box_cong
            (prov_equiv_refl Top)
            _ _ _ _ _ _ _ _ _ _ _).
  - intros a b. apply LT_law_top. exact (Ax_K a b).
  - intros a b c. apply LT_law_top. exact (Ax_S a b c).
  - intros a. apply LT_law_top. exact (Ax_DN a).
  - intros n a b. apply LT_law_top. exact (Ax_BoxK n a b).
  - intros n a. apply LT_law_top. exact (Ax_Loeb n a).
  - intros n a. apply LT_law_top. exact (Ax_Box4 n a).
  - intros n a. apply LT_law_top. exact (Ax_Mon n a).
  - intros n. apply LT_law_top. exact (Ax_NextCon n).
  - intros a b H1 H2.
    apply LT_law_top.
    exact (MP _ _ (LT_law_from_top _ H1) (LT_law_from_top _ H2)).
  - intros n a H. apply LT_law_top.
    exact (Nec n _ (LT_law_from_top _ H)).
  - intros a b H1 H2.
    exact (prov_iff_intro a b (LT_law_from_top _ H1) (LT_law_from_top _ H2)).
Defined.

Definition LT_class (phi : Form) : pma_carrier LT_GLP := phi.

Record PMA_morphism (A B : polymodal_Magari_algebra) : Type := mkPMAm {
  pmam_map : pma_carrier A -> pma_carrier B;
  pmam_respects : forall a a',
      pma_eq a a' -> pma_eq (pmam_map a) (pmam_map a');
  pmam_bot : pma_eq (pmam_map (pma_bot (p:=A))) (pma_bot (p:=B));
  pmam_impl : forall a b,
      pma_eq (pmam_map (pma_impl a b)) (pma_impl (pmam_map a) (pmam_map b));
  pmam_box : forall n a,
      pma_eq (pmam_map (pma_box n a)) (pma_box n (pmam_map a))
}.

Arguments pmam_map {A B}.
Arguments pmam_respects {A B}.
Arguments pmam_bot {A B}.
Arguments pmam_impl {A B}.
Arguments pmam_box {A B}.

Definition LT_GLP_morphism (A : polymodal_Magari_algebra) : Type :=
  PMA_morphism LT_GLP A.

Definition LT_free_hom (A : polymodal_Magari_algebra)
  (val : nat -> pma_carrier A) : LT_GLP_morphism A.
Proof.
  refine (mkPMAm LT_GLP A (pma_hom A val) _ _ _ _).
  - intros a a' Hiff. exact (pma_hom_respects A val a a' Hiff).
  - exact (pma_eq_refl _).
  - intros a b. exact (pma_eq_refl _).
  - intros n a. exact (pma_eq_refl _).
Defined.

(** Uniqueness by structural induction on the carrier element, using the
    morphism laws and the congruences. *)

Theorem LT_free_hom_unique : forall (A : polymodal_Magari_algebra)
  (val : nat -> pma_carrier A) (k : LT_GLP_morphism A),
  (forall p, pma_eq (pmam_map k (LT_class (Var p))) (val p)) ->
  forall x, pma_eq (pmam_map k x) (pma_hom A val x).
Proof.
  intros A val k Hvar x.
  induction x as [p | | a IHa b IHb | n a IHa]; cbn [pma_hom].
  - exact (Hvar p).
  - exact (pmam_bot k).
  - eapply pma_eq_trans.
    + exact (pmam_impl k a b).
    + exact (pma_impl_cong _ _ _ _ IHa IHb).
  - eapply pma_eq_trans.
    + exact (pmam_box k n a).
    + exact (pma_box_cong n _ _ IHa).
Qed.

Theorem LT_GLP_free : forall (A : polymodal_Magari_algebra)
  (val : nat -> pma_carrier A),
  exists h : LT_GLP_morphism A,
    (forall p, pma_eq (pmam_map h (LT_class (Var p))) (val p)) /\
    (forall k : LT_GLP_morphism A,
       (forall p, pma_eq (pmam_map k (LT_class (Var p))) (val p)) ->
       forall x, pma_eq (pmam_map k x) (pmam_map h x)).
Proof.
  intros A val.
  exists (LT_free_hom A val). split.
  - intro p. exact (pma_eq_refl _).
  - intros k Hk x. exact (LT_free_hom_unique A val k Hk x).
Qed.

Theorem LT_GLP_free_unique_pairwise : forall (A : polymodal_Magari_algebra)
  (val : nat -> pma_carrier A) (h k : LT_GLP_morphism A),
  (forall p, pma_eq (pmam_map h (LT_class (Var p))) (val p)) ->
  (forall p, pma_eq (pmam_map k (LT_class (Var p))) (val p)) ->
  forall x, pma_eq (pmam_map h x) (pmam_map k x).
Proof.
  intros A val h k Hh Hk x.
  eapply pma_eq_trans.
  - exact (LT_free_hom_unique A val h Hh x).
  - apply pma_eq_sym. exact (LT_free_hom_unique A val k Hk x).
Qed.

Definition pma_neg {A : polymodal_Magari_algebra}
  (a : pma_carrier A) : pma_carrier A := pma_impl a pma_bot.

Definition pma_and {A : polymodal_Magari_algebra}
  (a b : pma_carrier A) : pma_carrier A := pma_neg (pma_impl a (pma_neg b)).

Lemma pma_hom_two : forall (A : polymodal_Magari_algebra) (a b : pma_carrier A),
  pma_hom A (fun n => match n with 0 => a | _ => b end) (And (Var 0) (Var 1))
  = pma_and a b.
Proof. reflexivity. Qed.

Theorem pma_and_comm : forall (A : polymodal_Magari_algebra)
  (a b : pma_carrier A),
  pma_eq (pma_and a b) (pma_and b a).
Proof.
  intros A a b.
  rewrite <- (pma_hom_two A a b).
  assert (Hba : pma_hom A (fun n => match n with 0 => a | _ => b end)
                  (And (Var 1) (Var 0)) = pma_and b a)
    by reflexivity.
  rewrite <- Hba.
  apply pma_hom_respects.
  apply trivial_in_provable.
  apply prop_decide_correct.
  - cbn. unfold And, Neg. cbn. repeat split; exact I.
  - cbv. reflexivity.
Qed.

Theorem pma_dn_converse : forall (A : polymodal_Magari_algebra)
  (a : pma_carrier A),
  pma_eq (pma_impl a (pma_neg (pma_neg a))) (pma_top (p:=A)).
Proof.
  intros A a.
  assert (H : pma_hom A (fun _ => a) (Impl (Var 0) (Neg (Neg (Var 0))))
              = pma_impl a (pma_neg (pma_neg a)))
    by reflexivity.
  rewrite <- H.
  apply pma_hom_theorem.
  exact (prov_DN_intro (Var 0)).
Qed.

(** The two-element Boolean algebra with trivial boxes, a polymodal
    Magari algebra different from LT_GLP at which freeness instantiates. *)

Definition bool_impl (a b : bool) : bool := orb (negb a) b.

Definition PMA_bool : polymodal_Magari_algebra.
Proof.
  refine (mkPMA bool (@eq bool) false true bool_impl (fun _ _ => true)
            (fun a => eq_refl)
            (fun a b H => eq_sym H)
            (fun a b c H1 H2 => eq_trans H1 H2)
            _ _ _ _ _ _ _ _ _ _ _ _ _ _).
  - intros a a' b b' H1 H2. subst a' b'. reflexivity.
  - intros n a a' H. reflexivity.
  - reflexivity.
  - intros a b. destruct a; destruct b; reflexivity.
  - intros a b c. destruct a; destruct b; destruct c; reflexivity.
  - intros a. destruct a; reflexivity.
  - intros n a b. reflexivity.
  - intros n a. reflexivity.
  - intros n a. reflexivity.
  - intros n a. reflexivity.
  - intros n. reflexivity.
  - intros a b H1 H2. subst a. destruct b; cbn in H1; congruence.
  - intros n a H. reflexivity.
  - intros a b H1 H2. destruct a; destruct b; cbn in *; congruence.
Defined.

Theorem PMA_bool_differs_from_LT :
  pma_carrier PMA_bool = bool /\ pma_carrier LT_GLP = Form.
Proof. split; reflexivity. Qed.

Theorem LT_GLP_free_at_bool : forall (val : nat -> bool),
  exists h : LT_GLP_morphism PMA_bool,
    forall p, pmam_map h (LT_class (Var p)) = val p.
Proof.
  intro val.
  destruct (LT_GLP_free PMA_bool val) as [h [Hvar _]].
  exists h. exact Hvar.
Qed.

Theorem pma_hom_bool_is_eval : forall (val : nat -> bool) phi,
  box_free phi ->
  pma_hom PMA_bool val phi = eval val phi.
Proof.
  intros val phi Hbf.
  induction phi as [p | | a IHa b IHb | n a IHa]; cbn in *.
  - reflexivity.
  - reflexivity.
  - destruct Hbf as [Ha Hb].
    rewrite (IHa Ha), (IHb Hb). reflexivity.
  - destruct Hbf.
Qed.

Theorem LT_GLP_free_summary :
  (forall (A : polymodal_Magari_algebra) (val : nat -> pma_carrier A),
     exists h : LT_GLP_morphism A,
       (forall p, pma_eq (pmam_map h (LT_class (Var p))) (val p)) /\
       (forall k : LT_GLP_morphism A,
          (forall p, pma_eq (pmam_map k (LT_class (Var p))) (val p)) ->
          forall x, pma_eq (pmam_map k x) (pmam_map h x))) /\
  (forall (A : polymodal_Magari_algebra) val phi,
     |- phi -> pma_eq (pma_hom A val phi) (pma_top (p:=A))) /\
  (forall (A : polymodal_Magari_algebra) (a b : pma_carrier A),
     pma_eq (pma_and a b) (pma_and b a)) /\
  (forall val : nat -> bool,
     exists h : LT_GLP_morphism PMA_bool,
       forall p, pmam_map h (LT_class (Var p)) = val p).
Proof.
  split; [|split; [|split]].
  - exact LT_GLP_free.
  - exact pma_hom_theorem.
  - exact pma_and_comm.
  - exact LT_GLP_free_at_bool.
Qed.

Theorem MT_box_free_locally_finite : forall (V : list nat),
  exists (bound : nat),
    bound = Nat.pow 2 (Nat.pow 2 (length V)) /\ bound >= 1.
Proof.
  intro V. exists (Nat.pow 2 (Nat.pow 2 (length V))).
  split. reflexivity.
  pose proof (two_pow_pos (Nat.pow 2 (length V))) as Hp. lia.
Qed.

Theorem MT_box_free_classes_via_truth_table : forall phi psi,
  box_free phi -> box_free psi ->
  free_vars phi = free_vars psi ->
  (forall bs, length bs = length (nodup Nat.eq_dec (free_vars phi)) ->
              eval (mk_assignment (nodup Nat.eq_dec (free_vars phi)) bs) phi =
              eval (mk_assignment (nodup Nat.eq_dec (free_vars phi)) bs) psi) ->
  prov_equiv phi psi.
Proof.
  intros phi psi Hbf_phi Hbf_psi Hfv Hbs.
  apply (proj2 (MT_box_free_eval_distinguishes phi psi Hbf_phi Hbf_psi)).
  intro val.
  destruct (all_bool_lists_complete (nodup Nat.eq_dec (free_vars phi)) val)
    as [bs [Hlen [_ Hagree]]].
  pose proof (Hbs bs Hlen) as Heq.
  rewrite (eval_ext_on_free_vars phi val
            (mk_assignment (nodup Nat.eq_dec (free_vars phi)) bs)).
  - rewrite (eval_ext_on_free_vars psi val
              (mk_assignment (nodup Nat.eq_dec (free_vars phi)) bs)).
    + exact Heq.
    + intros p Hp. rewrite <- Hfv in Hp.
      symmetry. apply Hagree. apply free_vars_in_nodup. exact Hp.
  - intros p Hp. symmetry. apply Hagree. apply free_vars_in_nodup. exact Hp.
Qed.

Theorem MT_completeness_summary :
  (forall phi, box_free phi ->
     (classical_valid phi <-> prov_equiv phi Top)) /\
  (forall phi psi, box_free phi -> box_free psi ->
     (prov_equiv phi psi <-> forall val, eval val phi = eval val psi)) /\
  (forall (V : list nat),
    exists bound, bound = Nat.pow 2 (Nat.pow 2 (length V)) /\ bound >= 1).
Proof.
  split; [|split].
  - exact MT_algebraic_completeness_box_free.
  - exact MT_box_free_eval_distinguishes.
  - exact MT_box_free_locally_finite.
Qed.

Record FrameMorphism (F1 F2 : Frame) : Type := mkFM {
  fmm_map : fW F1 -> fW F2;
  fmm_forth : forall n w v, fR F1 n w v -> fR F2 n (fmm_map w) (fmm_map v);
  fmm_back : forall n w v', fR F2 n (fmm_map w) v' ->
                             exists v, fR F1 n w v /\ fmm_map v = v'
}.

Arguments fmm_map {F1 F2} _.
Arguments fmm_forth {F1 F2} _.
Arguments fmm_back {F1 F2} _.

Definition fm_identity (F : Frame) : FrameMorphism F F :=
  {| fmm_map := fun w => w;
     fmm_forth := fun n w v H => H;
     fmm_back := fun n w v' H => ex_intro _ v' (conj H eq_refl) |}.

Definition fm_compose (F1 F2 F3 : Frame)
  (f : FrameMorphism F1 F2) (g : FrameMorphism F2 F3) : FrameMorphism F1 F3.
Proof.
  refine {| fmm_map := fun w => fmm_map g (fmm_map f w);
            fmm_forth := _;
            fmm_back := _ |}.
  - intros n w v Hwv. apply (fmm_forth g). apply (fmm_forth f). exact Hwv.
  - intros n w v' Hg.
    pose proof (fmm_back g n (fmm_map f w) v' Hg) as [v'' [Hfv' Heq]].
    pose proof (fmm_back f n w v'' Hfv') as [v [Hwv Heq2]].
    exists v. split.
    + exact Hwv.
    + rewrite Heq2. exact Heq.
Defined.

Theorem fm_identity_left : forall F1 F2 (f : FrameMorphism F1 F2),
  forall w, fmm_map (fm_compose F1 F1 F2 (fm_identity F1) f) w = fmm_map f w.
Proof. intros. cbn. reflexivity. Qed.

Theorem fm_identity_right : forall F1 F2 (f : FrameMorphism F1 F2),
  forall w, fmm_map (fm_compose F1 F2 F2 f (fm_identity F2)) w = fmm_map f w.
Proof. intros. cbn. reflexivity. Qed.

Theorem fm_compose_assoc : forall F1 F2 F3 F4
  (f : FrameMorphism F1 F2) (g : FrameMorphism F2 F3) (h : FrameMorphism F3 F4),
  forall w,
    fmm_map (fm_compose F1 F2 F4 f (fm_compose F2 F3 F4 g h)) w =
    fmm_map (fm_compose F1 F3 F4 (fm_compose F1 F2 F3 f g) h) w.
Proof. intros. cbn. reflexivity. Qed.

Theorem frame_morphism_induces_bisim : forall F1 F2 V1 V2 (f : FrameMorphism F1 F2),
  (forall w p, V1 w p = V2 (fmm_map f w) p) ->
  Bisim F1 F2 V1 V2 (fun w v => fmm_map f w = v).
Proof.
  intros F1 F2 V1 V2 f Hval w1 w2 Hfw.
  split; [|split].
  - intros p. rewrite <- Hfw. apply Hval.
  - intros n v1 Hv1. exists (fmm_map f v1).
    assert (Heq : w2 = fmm_map f w1) by (symmetry; exact Hfw).
    rewrite Heq. split.
    + apply (fmm_forth f). exact Hv1.
    + reflexivity.
  - intros n v2 Hv2.
    assert (Heq : w2 = fmm_map f w1) by (symmetry; exact Hfw).
    rewrite Heq in Hv2.
    destruct (fmm_back f n w1 v2 Hv2) as [v1 [Hr Hfeq]].
    exists v1. split; [exact Hr | exact Hfeq].
Qed.

Theorem frame_morphism_pulls_back_truth : forall F1 F2 V1 V2 (f : FrameMorphism F1 F2),
  (forall w p, V1 w p = V2 (fmm_map f w) p) ->
  forall phi w,
    forces F1 V1 w phi <-> forces F2 V2 (fmm_map f w) phi.
Proof.
  intros F1 F2 V1 V2 f Hval phi w.
  apply (bisim_invariance F1 F2 V1 V2 (fun w v => fmm_map f w = v)).
  - apply frame_morphism_induces_bisim. exact Hval.
  - reflexivity.
Qed.

Definition GlobalSection (phi : Form) : Prop :=
  forall (F : Frame) V w, forces F V w phi.

Theorem provable_is_global_section : forall phi,
  |- phi -> GlobalSection phi.
Proof. exact soundness. Qed.

Theorem global_section_preserved_by_morphisms : forall phi,
  GlobalSection phi ->
  forall F1 F2 V1 V2 (f : FrameMorphism F1 F2),
    (forall w p, V1 w p = V2 (fmm_map f w) p) ->
    forall w, forces F1 V1 w phi.
Proof.
  intros phi Hg F1 F2 V1 V2 f Hval w. apply Hg.
Qed.

Theorem categorical_semantics_summary :
  (forall F1 F2 V1 V2 (f : FrameMorphism F1 F2),
     (forall w p, V1 w p = V2 (fmm_map f w) p) ->
     Bisim F1 F2 V1 V2 (fun w v => fmm_map f w = v)) /\
  (forall phi, |- phi -> GlobalSection phi) /\
  (forall F1 F2 V1 V2 (f : FrameMorphism F1 F2),
     (forall w p, V1 w p = V2 (fmm_map f w) p) ->
     forall phi w, forces F1 V1 w phi <-> forces F2 V2 (fmm_map f w) phi).
Proof.
  split; [|split].
  - exact frame_morphism_induces_bisim.
  - exact provable_is_global_section.
  - exact frame_morphism_pulls_back_truth.
Qed.

Theorem categorical_semantics_with_morphism_soundness :
  (forall F1 F2 V1 V2 (f : FrameMorphism F1 F2),
     (forall w p, V1 w p = V2 (fmm_map f w) p) ->
     Bisim F1 F2 V1 V2 (fun w v => fmm_map f w = v)) /\
  (forall phi, |- phi -> GlobalSection phi) /\
  (forall F1 F2 V1 V2 (f : FrameMorphism F1 F2),
     (forall w p, V1 w p = V2 (fmm_map f w) p) ->
     forall phi w, forces F1 V1 w phi <-> forces F2 V2 (fmm_map f w) phi) /\
  (forall F1 F2 V1 V2 (f : FrameMorphism F1 F2),
     (forall w p, V1 w p = V2 (fmm_map f w) p) ->
     forall phi, (|- phi -> forall w, forces F1 V1 w phi) /\
                 (|- phi -> forall w, forces F2 V2 (fmm_map f w) phi)).
Proof.
  split; [|split; [|split]].
  - exact frame_morphism_induces_bisim.
  - exact provable_is_global_section.
  - exact frame_morphism_pulls_back_truth.
  - intros F1 F2 V1 V2 f Hcompat phi.
    pose proof (frame_morphism_pulls_back_truth F1 F2 V1 V2 f Hcompat phi) as Hpb.
    split.
    + intros Hp w. exact (soundness phi Hp F1 V1 w).
    + intros Hp w. exact (soundness phi Hp F2 V2 (fmm_map f w)).
Qed.

(******************************************************************************)
(* Veblen notation system extending the CNF carrier [ord].                    *)
(*                                                                            *)
(* Beyond the existing [Veblen_phi_0] (which is just [λα. ω^α]) and its      *)
(* iterates [Veblen_phi_iter k OZero] (which all live in CNF below ε_0),     *)
(* we introduce a stratified Veblen-φ system where each φ_(n+1) for n : nat  *)
(* is represented by a syntactic atom [V_phi n α].  Concretely:               *)
(*                                                                            *)
(*   - [V_cnf o]   embeds a CNF ord o (necessarily below ε_0) into vord.     *)
(*   - [V_phi n α] represents φ_(n+1)(α), the α-th common fixed point of    *)
(*     [φ_0, φ_1, ..., φ_n].  In particular [V_phi 0 OZero = ε_0], and       *)
(*     [V_phi n OZero] is the n-th Γ_0 approximation φ_(n+1)(0).             *)
(*                                                                            *)
(* The stratified design — V_phi's argument is an [ord] (existing CNF), not  *)
(* a recursive vord — sidesteps the binary-Veblen cross-comparison problem.  *)
(* Comparison is straightforward lex on (head-class, index, ord-position),   *)
(* and well-foundedness follows from well-foundedness of < on nat together   *)
(* with [cnf_lt] on the CNF subset.                                           *)
(******************************************************************************)

Inductive vord : Type :=
  | V_cnf  : ord -> vord
  | V_phi  : nat -> ord -> vord
  | V_gamma0 : vord.

(** Normal-form predicate: in [V_phi n α], the [ord] argument α must be
    in CNF, i.e. [wf_ord α].  [V_cnf o] requires [wf_ord o].  The
    [V_gamma0] atom — the Feferman-Schütte point Γ_0, i.e. the first
    common fixed point of the whole φ-tower, sitting strictly above
    every [V_phi n α] — is always well-formed. *)

Definition wf_vord (v : vord) : Prop :=
  match v with
  | V_cnf o   => wf_ord o
  | V_phi _ α => wf_ord α
  | V_gamma0  => True
  end.

(** Inductively-defined Veblen ordering on [vord].  Three cases:
    CNF on CNF goes through [ord_lt]; every CNF position is strictly
    below every [V_phi]-atom; among [V_phi] atoms, the lex order on
    (index, argument) decides. *)

Inductive vord_lt : vord -> vord -> Prop :=
  | VL_cnf       : forall o1 o2, ord_lt o1 o2 -> vord_lt (V_cnf o1) (V_cnf o2)
  | VL_cnf_phi   : forall o n α, vord_lt (V_cnf o) (V_phi n α)
  | VL_phi_idx   : forall n1 n2 α1 α2,
      n1 < n2 -> vord_lt (V_phi n1 α1) (V_phi n2 α2)
  | VL_phi_arg   : forall n α1 α2,
      ord_lt α1 α2 -> vord_lt (V_phi n α1) (V_phi n α2)
  | VL_cnf_g0    : forall o, vord_lt (V_cnf o) V_gamma0
  | VL_phi_g0    : forall n α, vord_lt (V_phi n α) V_gamma0.

Lemma vord_lt_V_cnf_inv : forall v o,
  vord_lt v (V_cnf o) -> exists o', v = V_cnf o' /\ ord_lt o' o.
Proof.
  intros v o H.
  remember (V_cnf o) as u eqn:Eu.
  destruct H as [o1 o2 Hlt | o' n α | n1 n2 α1 α2 Hlt | n α1 α2 Hlt | o' | n α].
  - injection Eu as Hu. subst o2.
    exists o1. split; [reflexivity | exact Hlt].
  - discriminate.
  - discriminate.
  - discriminate.
  - discriminate.
  - discriminate.
Qed.

Lemma vord_lt_V_phi_inv : forall v n α,
  vord_lt v (V_phi n α) ->
    (exists o, v = V_cnf o) \/
    (exists n' α', v = V_phi n' α' /\ n' < n) \/
    (exists α', v = V_phi n α' /\ ord_lt α' α).
Proof.
  intros v n α H.
  remember (V_phi n α) as u eqn:Eu.
  destruct H as [o1 o2 Hlt | o' nn αα | n1 n2 α1 α2 Hlt | nn α1 α2 Hlt | o' | nn αα].
  - discriminate.
  - injection Eu as En Eα. subst nn αα.
    left. exists o'. reflexivity.
  - injection Eu as En Eα. subst n2 α2.
    right. left. exists n1, α1. split; [reflexivity | exact Hlt].
  - injection Eu as En Eα. subst nn α2.
    right. right. exists α1. split; [reflexivity | exact Hlt].
  - discriminate.
  - discriminate.
Qed.

(** Inversion at the [V_gamma0] top atom: its strict predecessors are
    exactly the [V_cnf] and [V_phi] atoms. *)

Lemma vord_lt_V_gamma0_inv : forall v,
  vord_lt v V_gamma0 ->
  (exists o, v = V_cnf o) \/ (exists n α, v = V_phi n α).
Proof.
  intros v H.
  remember V_gamma0 as u eqn:Eu.
  destruct H as [o1 o2 Hlt | o' nn αα | n1 n2 α1 α2 Hlt | nn α1 α2 Hlt | o' | nn αα].
  - discriminate.
  - discriminate.
  - discriminate.
  - discriminate.
  - left. exists o'. reflexivity.
  - right. exists nn, αα. reflexivity.
Qed.

(** Nothing lies strictly above [V_gamma0] within the carrier; in
    particular [V_gamma0] is not below itself. *)

Lemma vord_lt_from_V_gamma0_absurd : forall v,
  ~ vord_lt V_gamma0 v.
Proof.
  intros v H.
  remember V_gamma0 as u eqn:Eu.
  destruct H as [o1 o2 Hlt | o' nn αα | n1 n2 α1 α2 Hlt | nn α1 α2 Hlt | o' | nn αα];
    discriminate.
Qed.

(** ** Well-foundedness on the [wf_vord] subset.

    Conditioned relation [vord_wf_lt] requires both endpoints to be
    well-formed (CNF in their [ord] components).  Well-foundedness then
    follows from: (i) [V_cnf]-images use [nf_Acc] for [cnf_lt] descent,
    (ii) [V_phi n _] images use lex on (n, [cnf_lt] on the inner [ord]). *)

Definition vord_wf_lt (u v : vord) : Prop :=
  wf_vord u /\ wf_vord v /\ vord_lt u v.

Lemma Acc_vord_V_cnf_wf : forall o,
  wf_ord o -> Acc vord_wf_lt (V_cnf o).
Proof.
  intros o Hwfo.
  pose proof (nf_Acc o Hwfo) as Acco.
  revert Hwfo.
  induction Acco as [o Hacc IH]. intro Hwfo.
  apply Acc_intro. intros y [Hwfy [_ Hlt]].
  destruct (vord_lt_V_cnf_inv _ _ Hlt) as [o' [Heq Hltoo]].
  subst y. cbn in Hwfy.
  apply IH.
  - unfold lt_cnf. split; [exact Hwfy | split; [exact Hwfo | exact Hltoo]].
  - exact Hwfy.
Qed.

(** For [V_phi n α] images: outer induction on n, inner on Acc lt_cnf α. *)

Lemma Acc_vord_V_phi_wf : forall n α,
  wf_ord α -> Acc vord_wf_lt (V_phi n α).
Proof.
  intro n. induction n as [n IHn] using lt_wf_ind.
  intros α Hwfα.
  pose proof (nf_Acc α Hwfα) as Accα.
  revert Hwfα.
  induction Accα as [α Haccα IHα]. intro Hwfα.
  apply Acc_intro. intros y [Hwfy [_ Hlt]].
  destruct (vord_lt_V_phi_inv _ _ _ Hlt) as
    [[o E] | [[n' [α' [E Hlt']]] | [α' [E Hltα]]]].
  - subst y. apply Acc_vord_V_cnf_wf. exact Hwfy.
  - subst y. cbn in Hwfy. apply IHn; [exact Hlt' | exact Hwfy].
  - subst y. cbn in Hwfy. apply IHα.
    + unfold lt_cnf. split; [exact Hwfy | split; [exact Hwfα | exact Hltα]].
    + exact Hwfy.
Qed.

(** Accessibility of the top atom: every [vord_wf_lt]-predecessor of
    [V_gamma0] is a well-formed [V_cnf] or [V_phi] atom, each already
    accessible by the two lemmas above. *)

Lemma Acc_vord_V_gamma0 : Acc vord_wf_lt V_gamma0.
Proof.
  apply Acc_intro. intros y [Hwfy [_ Hlt]].
  destruct (vord_lt_V_gamma0_inv _ Hlt) as [[o E] | [n [α E]]]; subst y.
  - apply Acc_vord_V_cnf_wf. exact Hwfy.
  - apply Acc_vord_V_phi_wf. exact Hwfy.
Qed.

Theorem vord_wf_lt_well_founded : well_founded vord_wf_lt.
Proof.
  intro v. apply Acc_intro. intros y [Hwfy [Hwfv Hlt]].
  destruct v as [o | n α |].
  - apply (Acc_inv (Acc_vord_V_cnf_wf o Hwfv)).
    split; [exact Hwfy | split; [exact Hwfv | exact Hlt]].
  - apply (Acc_inv (Acc_vord_V_phi_wf n α Hwfv)).
    split; [exact Hwfy | split; [exact Hwfv | exact Hlt]].
  - apply (Acc_inv Acc_vord_V_gamma0).
    split; [exact Hwfy | split; [exact Hwfv | exact Hlt]].
Qed.

(** ** Concrete Veblen positions.

    [veps0]            = ε_0 = φ_1(0), encoded as [V_phi 0 OZero].
    [vgamma0_approx n] = φ_(n+1)(0), the Γ_0 approximations from below.
    *)

Definition veps0 : vord := V_phi 0 OZero.

Definition vgamma0_approx (n : nat) : vord := V_phi n OZero.

Theorem vgamma0_approx_zero : vgamma0_approx 0 = veps0.
Proof. reflexivity. Qed.

Theorem vgamma0_approx_strict : forall n,
  vord_lt (vgamma0_approx n) (vgamma0_approx (S n)).
Proof. intro n. unfold vgamma0_approx. apply VL_phi_idx. lia. Qed.

Theorem vgamma0_approx_chain : forall n m,
  n < m -> vord_lt (vgamma0_approx n) (vgamma0_approx m).
Proof. intros n m H. unfold vgamma0_approx. apply VL_phi_idx. exact H. Qed.

(** Every CNF ord is strictly below ε_0 in vord. *)

Theorem cnf_below_veps0 : forall o,
  vord_lt (V_cnf o) veps0.
Proof. intro o. unfold veps0. apply VL_cnf_phi. Qed.

(** In particular, every iterated ω-tower [Veblen_phi_iter k OZero] is
    below ε_0 in vord, witnessing that ε_0 is genuinely beyond CNF. *)

Theorem omega_tower_image_below_veps0 : forall k,
  vord_lt (V_cnf (Veblen_phi_iter k OZero)) veps0.
Proof. intro k. apply cnf_below_veps0. Qed.

(** Every worm has its [worm_to_ord] image below ε_0 in vord. *)

Theorem worm_image_below_veps0 : forall w,
  vord_lt (V_cnf (worm_to_ord w)) veps0.
Proof. intro w. apply cnf_below_veps0. Qed.

Theorem worm_normalisation_strict_decrease_vord : forall w,
  w <> normalise_worm w ->
  vord_lt (V_cnf (worm_to_ord (normalise_worm w))) (V_cnf (worm_to_ord w)).
Proof.
  intros w Hne. apply VL_cnf.
  unfold ord_lt. exact (worm_normalisation_strict_decrease w Hne).
Qed.

Theorem worm_normalisation_complete : forall w,
  (vord_lt (V_cnf (worm_to_ord (normalise_worm w))) (V_cnf (worm_to_ord w)) \/
   normalise_worm w = w) /\
  is_sorted_asc (normalise_worm w) /\
  normalise_worm (normalise_worm w) = normalise_worm w.
Proof.
  intro w. split; [|split].
  - destruct (list_eq_dec Nat.eq_dec w (normalise_worm w)) as [Heq | Hne].
    + right. exact (eq_sym Heq).
    + left. exact (worm_normalisation_strict_decrease_vord w Hne).
  - exact (normalise_worm_sorted w).
  - exact (normalise_worm_idempotent w).
Qed.

(** ** Beklemishev worm reduction (todo item 1).

    The Beklemishev step splits a worm at the head and recursively
    reduces the tail.  When the reduced tail is non-empty, the head is
    re-prepended unchanged ([bek_step a (b :: rest) := a :: b :: rest]).
    When the reduced tail is empty, the head is decremented by one
    (giving [[a-1]] when [a > 0], or [[]] when [a = 0]).  This is
    genuinely different from [normalise_worm] (which sorts via
    insertion); the recursion structure here is "split at the head,
    recurse on the tail, head-substitute on the result".  Each call
    strictly decreases [worm_to_ord]. *)

Definition bek_step (a : nat) (rest : Worm) : Worm :=
  match rest with
  | [] =>
      match a with
      | 0 => []
      | S k => k :: nil
      end
  | _ => a :: rest
  end.

Fixpoint beklemishev_reduce (w : Worm) : Worm :=
  match w with
  | [] => []
  | a :: rest => bek_step a (beklemishev_reduce rest)
  end.

Fixpoint iterate {A : Type} (f : A -> A) (n : nat) (x : A) : A :=
  match n with
  | 0 => x
  | S n' => f (iterate f n' x)
  end.

(** Forbidden-shortcut sanity check: the reduction is NOT
    [normalise_worm] and NOT the immediate-empty constant. *)

Example beklemishev_reduce_not_normalise :
  beklemishev_reduce (1 :: 2 :: nil) <> normalise_worm (1 :: 2 :: nil).
Proof. cbn. discriminate. Qed.

Example beklemishev_reduce_nontrivial :
  beklemishev_reduce (3 :: 2 :: 1 :: nil) = 3 :: 2 :: 0 :: nil.
Proof. reflexivity. Qed.

Example beklemishev_reduce_pop_zero_tail :
  beklemishev_reduce (5 :: 0 :: nil) = 4 :: nil.
Proof. reflexivity. Qed.

(** Helper: [nat_to_ord] is strictly increasing in [ord_lt]. *)

Lemma nat_to_ord_lt : forall a b, a < b ->
  ord_lt (nat_to_ord a) (nat_to_ord b).
Proof. exact nat_to_ord_strict_lt. Qed.

(** [bek_step] applied to an empty tail strictly decreases the
    [worm_to_ord] image of the singleton [a :: nil]. *)

Lemma bek_step_empty_decreases : forall a,
  ord_lt (worm_to_ord (bek_step a nil)) (worm_to_ord (a :: nil)).
Proof.
  intro a. destruct a as [|k].
  - cbn [bek_step worm_to_ord]. unfold ord_lt. cbn. reflexivity.
  - cbn [bek_step worm_to_ord].
    apply ord_compare_OCons_first_lt.
    apply nat_to_ord_strict_lt. lia.
Qed.

(** [bek_step] applied to a non-empty reduced tail [r'] (where [r' < r]
    in [ord_lt]) preserves the strict-decrease via the head. *)

Lemma bek_step_nonempty_decreases : forall a rest r',
  rest <> [] ->
  r' <> [] ->
  ord_lt (worm_to_ord r') (worm_to_ord rest) ->
  ord_lt (worm_to_ord (bek_step a r')) (worm_to_ord (a :: rest)).
Proof.
  intros a rest r' Hrest Hr' Hlt.
  destruct r' as [|b r'']; [contradiction|].
  cbn [bek_step worm_to_ord].
  unfold ord_lt. cbn [ord_compare].
  rewrite ord_compare_refl. exact Hlt.
Qed.

(** When the reduced tail collapses to [], decrementing/popping the head
    still produces a strictly smaller worm (relative to the original
    [a :: rest]). *)

Lemma bek_step_collapse_decreases : forall a rest,
  rest <> [] ->
  ord_lt (worm_to_ord (bek_step a nil)) (worm_to_ord (a :: rest)).
Proof.
  intros a rest Hrest.
  cbn [bek_step].
  destruct a as [|k].
  - cbn [worm_to_ord]. unfold ord_lt. cbn. reflexivity.
  - cbn [worm_to_ord].
    apply ord_compare_OCons_first_lt.
    apply nat_to_ord_strict_lt. lia.
Qed.

(** Main strict-descent theorem: every Beklemishev step strictly
    decreases [worm_to_ord] in [ord_lt]. *)

Theorem beklemishev_reduce_strictly_decreases : forall w,
  w <> [] ->
  ord_lt (worm_to_ord (beklemishev_reduce w)) (worm_to_ord w).
Proof.
  intro w. induction w as [|a rest IH]; intro Hne.
  - exfalso. apply Hne. reflexivity.
  - cbn [beklemishev_reduce].
    destruct rest as [|b rest'].
    + apply bek_step_empty_decreases.
    + assert (Hrest_ne : (b :: rest') <> []) by discriminate.
      pose proof (IH Hrest_ne) as IHrest.
      destruct (beklemishev_reduce (b :: rest')) as [|c r''] eqn:Ered.
      * apply bek_step_collapse_decreases. exact Hrest_ne.
      * apply bek_step_nonempty_decreases.
        -- exact Hrest_ne.
        -- discriminate.
        -- exact IHrest.
Qed.

(** Termination: a single application of [beklemishev_reduce] strictly
    decreases the natural-number measure [length w + sum of w].  This
    is a coarser termination measure than the ord-descent above, but
    is easy to formalize and gives finite-step termination. *)

Fixpoint worm_size (w : Worm) : nat :=
  match w with
  | [] => 0
  | a :: rest => S (a + worm_size rest)
  end.

Lemma worm_size_zero_iff : forall w, worm_size w = 0 <-> w = [].
Proof.
  intro w. destruct w; cbn; split; intros H; congruence.
Qed.

Theorem beklemishev_reduce_size_decreases : forall w,
  w <> [] ->
  worm_size (beklemishev_reduce w) < worm_size w.
Proof.
  intro w. induction w as [|a rest IH]; intro Hne.
  - exfalso. apply Hne. reflexivity.
  - cbn [beklemishev_reduce].
    destruct rest as [|b rest'].
    + cbn [beklemishev_reduce].
      destruct a as [|k]; cbn [bek_step worm_size]; lia.
    + assert (Hrne : (b :: rest') <> []) by discriminate.
      pose proof (IH Hrne) as Hsz.
      destruct (beklemishev_reduce (b :: rest')) as [|c r''] eqn:Ered.
      * destruct a as [|k]; cbn [bek_step worm_size]; cbn [worm_size] in Hsz; lia.
      * cbn [bek_step worm_size]. cbn [worm_size] in Hsz. lia.
Qed.

(** [iterate] commutes via [f] in the standard way. *)

Lemma iterate_S_shift : forall {A : Type} (f : A -> A) n x,
  iterate f (S n) x = iterate f n (f x).
Proof.
  intros A f n. induction n as [|n IH]; intro x.
  - reflexivity.
  - cbn [iterate]. f_equal. apply IH.
Qed.

(** Iteration eventually reaches []. *)

Theorem beklemishev_reduce_terminates : forall w,
  exists n, iterate beklemishev_reduce n w = [].
Proof.
  intro w.
  remember (worm_size w) as sz eqn:Hsz.
  revert w Hsz.
  induction sz as [sz IH] using (well_founded_induction lt_wf).
  intros w Hsz.
  destruct w as [|a rest].
  - exists 0. reflexivity.
  - assert (Hne : (a :: rest) <> []) by discriminate.
    pose proof (beklemishev_reduce_size_decreases (a :: rest) Hne) as Hdec.
    pose proof (IH (worm_size (beklemishev_reduce (a :: rest)))
                   ltac:(subst sz; exact Hdec)
                   (beklemishev_reduce (a :: rest)) eq_refl) as [n Hn].
    exists (S n). rewrite iterate_S_shift. exact Hn.
Qed.

(** Restated termination using the [V_cnf] embedding into [vord]: the
    ord-image of the final iterate is at or below [V_cnf OZero], which
    is the smallest [vord]. *)

Theorem beklemishev_reduce_terminates_at_eps0 : forall w,
  exists n, V_cnf (worm_to_ord (iterate beklemishev_reduce n w)) = V_cnf OZero.
Proof.
  intro w.
  destruct (beklemishev_reduce_terminates w) as [n Hn].
  exists n. rewrite Hn. reflexivity.
Qed.

Definition T_n_ordinal (n : nat) : vord := vgamma0_approx n.

Theorem T_n_ordinal_strict : forall n,
  vord_lt (T_n_ordinal n) (T_n_ordinal (S n)).
Proof. intro n. unfold T_n_ordinal. exact (vgamma0_approx_strict n). Qed.

Theorem T_n_ordinal_chain : forall n m,
  n < m -> vord_lt (T_n_ordinal n) (T_n_ordinal m).
Proof. intros n m H. unfold T_n_ordinal. exact (vgamma0_approx_chain n m H). Qed.

Theorem T_n_ordinal_zero : T_n_ordinal 0 = veps0.
Proof. unfold T_n_ordinal. exact vgamma0_approx_zero. Qed.

Theorem T_n_ordinal_consistency_strength : forall n,
  vord_lt (T_n_ordinal n) (T_n_ordinal (S n)) /\
  (|- Box (S n) (Neg (Box n Bot))).
Proof.
  intro n. split.
  - exact (T_n_ordinal_strict n).
  - exact (Ax_NextCon n).
Qed.

Theorem T_n_ordinal_summary :
  (forall n, vord_lt (T_n_ordinal n) (T_n_ordinal (S n))) /\
  (forall n m, n < m -> vord_lt (T_n_ordinal n) (T_n_ordinal m)) /\
  T_n_ordinal 0 = veps0 /\
  (forall n, |- Box (S n) (Neg (Box n Bot))) /\
  (forall n, ~ |- Box n (Neg (Box n Bot))).
Proof.
  split; [|split; [|split; [|split]]].
  - exact T_n_ordinal_strict.
  - exact T_n_ordinal_chain.
  - exact T_n_ordinal_zero.
  - exact Ax_NextCon.
  - exact Godel_sentence_independent_at_Tn.
Qed.

Theorem T_n_ordinal_with_NextCon_Godel_pair :
  (forall n, vord_lt (T_n_ordinal n) (T_n_ordinal (S n))) /\
  (forall n m, n < m -> vord_lt (T_n_ordinal n) (T_n_ordinal m)) /\
  T_n_ordinal 0 = veps0 /\
  (forall n, |- Box (S n) (Neg (Box n Bot))) /\
  (forall n, ~ |- Box n (Neg (Box n Bot))) /\
  (forall n, |- Box (S n) (Neg (Box n Bot)) /\
             ~ |- Box n (Neg (Box n Bot))).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact T_n_ordinal_strict.
  - exact T_n_ordinal_chain.
  - exact T_n_ordinal_zero.
  - exact Ax_NextCon.
  - exact Godel_sentence_independent_at_Tn.
  - intro n. split.
    + exact (Ax_NextCon n).
    + exact (Godel_sentence_independent_at_Tn n).
Qed.

(** ** Normal-form preservation under the canonical witnesses. *)

Theorem veps0_wf : wf_vord veps0.
Proof. unfold veps0. cbn. exact I. Qed.

Theorem vgamma0_approx_wf : forall n, wf_vord (vgamma0_approx n).
Proof. intro n. unfold vgamma0_approx. cbn. exact I. Qed.

Theorem cnf_wf_to_vord : forall o, wf_ord o -> wf_vord (V_cnf o).
Proof. intros o H. exact H. Qed.

(** ** Connection to GLP* worms.

    Every GLP* worm [w] has a CNF representation [worm_to_ord w] in
    [ord], which lifts to [V_cnf (worm_to_ord w)] in [vord], and is
    strictly below [veps0 = ε_0].  Combined with [vgamma0_approx]
    being unbounded above [veps0], this shows the Veblen notation
    system genuinely strictly extends the worm-induced CNF bound on
    GLP* proof-theoretic ordinals. *)

Theorem GLP_worm_strictly_below_veps0 : forall w,
  vord_lt (V_cnf (worm_to_ord w)) veps0 /\
  forall n, vord_lt veps0 (vgamma0_approx (S n)).
Proof.
  intros w. split.
  - apply worm_image_below_veps0.
  - intro n. unfold veps0, vgamma0_approx.
    apply VL_phi_idx. lia.
Qed.

(** ** Strict layering of the Veblen hierarchy.

    For every n, there is a vord (namely [vgamma0_approx n]) that is
    strictly above every CNF ord (representing all worm-images) and
    below [vgamma0_approx (S n)].  This is the strict layering of the
    Γ_0 approximations from below the Feferman-Schütte ordinal Γ_0. *)

Theorem veblen_hierarchy_strict_layering : forall n,
  (forall o, vord_lt (V_cnf o) (vgamma0_approx n)) /\
  vord_lt (vgamma0_approx n) (vgamma0_approx (S n)).
Proof.
  intro n. split.
  - intro o. unfold vgamma0_approx. apply VL_cnf_phi.
  - apply vgamma0_approx_strict.
Qed.

(** ** Veblen notation system: the headline package.

    The Veblen notation system (vord, vord_wf_lt, wf_vord) extends CNF
    in a well-ordered fashion, captures ε_0 as the syntactic atom
    [V_phi 0 OZero], approximates Γ_0 from below via the
    [vgamma0_approx] family, and connects to GLP*'s worm-image
    proof-theoretic ordinal bound via the [V_cnf] embedding. *)

Theorem veblen_notation_system_well_ordered :
  well_founded vord_wf_lt /\
  (forall n m, n < m -> vord_lt (vgamma0_approx n) (vgamma0_approx m)) /\
  (forall w, vord_lt (V_cnf (worm_to_ord w)) veps0) /\
  veps0 = vgamma0_approx 0.
Proof.
  split; [|split; [|split]].
  - exact vord_wf_lt_well_founded.
  - exact vgamma0_approx_chain.
  - exact worm_image_below_veps0.
  - reflexivity.
Qed.

(******************************************************************************)
(* Subject reduction for [pt_reduces] (the basic five-rule reduction).        *)
(*                                                                            *)
(* Each contraction rule preserves the denotation of the proof term.  We     *)
(* build up by single lemmas — one per rule — and then combine.               *)
(******************************************************************************)

(** Lemma: K-contraction preserves denotation. *)

Lemma pt_K_subject_reduction : forall phi psi p1 p2 chi,
  denote_proof_term (PT_MP (PT_MP (PT_K phi psi) p1) p2) = Some chi ->
  denote_proof_term p1 = Some chi.
Proof.
  intros phi psi p1 p2 chi Hd. cbn in Hd.
  destruct (denote_proof_term p1) as [d1|] eqn:Ep1; [|discriminate].
  destruct (Form_eqb phi d1) eqn:E1; [|discriminate].
  apply Form_eqb_eq in E1. subst d1.
  destruct (denote_proof_term p2) as [d2|] eqn:Ep2; [|discriminate].
  destruct (Form_eqb psi d2) eqn:E2; [|discriminate].
  injection Hd as Hd. subst chi. reflexivity.
Qed.

(** Lemma: BoxK-Nec contraction preserves denotation.
    [(BoxK n φ ψ) (Nec n p1) (Nec n p2)] reduces to [Nec n (MP p1 p2)]. *)

Lemma pt_BoxK_Nec_subject_reduction : forall n phi psi p1 p2 chi,
  denote_proof_term
    (PT_MP (PT_MP (PT_BoxK n phi psi) (PT_Nec n p1)) (PT_Nec n p2)) = Some chi ->
  denote_proof_term (PT_Nec n (PT_MP p1 p2)) = Some chi.
Proof.
  intros n phi psi p1 p2 chi Hd. cbn in Hd.
  destruct (denote_proof_term p1) as [d1|] eqn:Ep1; [|discriminate].
  destruct (Form_eqb (Box n (Impl phi psi)) (Box n d1)) eqn:E1; [|discriminate].
  apply Form_eqb_eq in E1. injection E1 as E1. subst d1.
  destruct (denote_proof_term p2) as [d2|] eqn:Ep2; [|discriminate].
  destruct (Form_eqb (Box n phi) (Box n d2)) eqn:E2; [|discriminate].
  apply Form_eqb_eq in E2. injection E2 as E2. subst d2.
  injection Hd as Hd. subst chi.
  cbn. rewrite Ep1, Ep2.
  rewrite Form_eqb_refl. reflexivity.
Qed.

(** Lemma: contextual rule, MP-left.  If p1 → p1' preserves denotation,
    then so does (PT_MP p1 p2) → (PT_MP p1' p2). *)

Lemma pt_MP_left_subject_reduction : forall p1 p1' p2 chi,
  (forall psi, denote_proof_term p1 = Some psi ->
               denote_proof_term p1' = Some psi) ->
  denote_proof_term (PT_MP p1 p2) = Some chi ->
  denote_proof_term (PT_MP p1' p2) = Some chi.
Proof.
  intros p1 p1' p2 chi Hpres Hd. cbn in Hd.
  destruct (denote_proof_term p1) as [f|] eqn:Ep1; [|discriminate].
  pose proof (Hpres f eq_refl) as Hp1'.
  cbn. rewrite Hp1'. exact Hd.
Qed.

(** Lemma: contextual rule, MP-right. *)

Lemma pt_MP_right_subject_reduction : forall p1 p2 p2' chi,
  (forall psi, denote_proof_term p2 = Some psi ->
               denote_proof_term p2' = Some psi) ->
  denote_proof_term (PT_MP p1 p2) = Some chi ->
  denote_proof_term (PT_MP p1 p2') = Some chi.
Proof.
  intros p1 p2 p2' chi Hpres Hd. cbn in Hd.
  destruct (denote_proof_term p1) as [f|] eqn:Ep1; [|discriminate].
  destruct f as [v | | a b | k psi]; try discriminate.
  destruct (denote_proof_term p2) as [a'|] eqn:Ep2; [|discriminate].
  pose proof (Hpres a' eq_refl) as Hp2'.
  cbn. rewrite Ep1, Hp2'. exact Hd.
Qed.

(** Lemma: contextual rule, under Nec. *)

Lemma pt_Nec_subject_reduction : forall n p p' chi,
  (forall psi, denote_proof_term p = Some psi ->
               denote_proof_term p' = Some psi) ->
  denote_proof_term (PT_Nec n p) = Some chi ->
  denote_proof_term (PT_Nec n p') = Some chi.
Proof.
  intros n p p' chi Hpres Hd. cbn in Hd.
  destruct (denote_proof_term p) as [psi|] eqn:Ep; [|discriminate].
  pose proof (Hpres psi eq_refl) as Hp'.
  cbn. rewrite Hp'. exact Hd.
Qed.

(** Main theorem: every step of [pt_reduces] preserves denotation
    (subject reduction). *)

Theorem pt_reduces_subject_reduction : forall p p' phi,
  pt_reduces p p' ->
  denote_proof_term p = Some phi ->
  denote_proof_term p' = Some phi.
Proof.
  intros p p' phi Hred. revert phi.
  induction Hred; intro chi.
  - (* PTR_MP_left *)
    apply pt_MP_left_subject_reduction. intros psi Hp; exact (IHHred psi Hp).
  - (* PTR_MP_right *)
    apply pt_MP_right_subject_reduction. intros psi Hp; exact (IHHred psi Hp).
  - (* PTR_Nec *)
    apply pt_Nec_subject_reduction. intros psi Hp; exact (IHHred psi Hp).
  - (* PTR_K *)
    intro Hd. exact (pt_K_subject_reduction phi psi p1 p2 chi Hd).
  - (* PTR_BoxK_Nec *)
    intro Hd. exact (pt_BoxK_Nec_subject_reduction n phi psi p1 p2 chi Hd).
Qed.

(** Corollary: provability is preserved under [pt_reduces]: if a proof
    term denotes a provable formula and reduces to another, the reduct
    also denotes the same provable formula. *)

Corollary pt_reduces_preserves_provability : forall p p' phi,
  pt_reduces p p' ->
  denote_proof_term p = Some phi ->
  |- phi /\ denote_proof_term p' = Some phi.
Proof.
  intros p p' phi Hred Hd.
  pose proof (pt_reduces_subject_reduction p p' phi Hred Hd) as Hd'.
  split.
  - exact (denote_proof_term_provable p phi Hd).
  - exact Hd'.
Qed.

(** ** Normal forms.

    A proof term is in normal form when no [pt_reduces] step applies to
    it.  We define a syntactic predicate [pt_redex] detecting whether
    any of the five reduction-rule LHS shapes occur at the term root,
    and [pt_normal] propagating "no redex anywhere" structurally. *)

Definition pt_redex_at_root (p : proof_term) : bool :=
  match p with
  | PT_MP (PT_MP (PT_K _ _) _) _ => true
  | PT_MP (PT_MP (PT_BoxK _ _ _) (PT_Nec _ _)) (PT_Nec _ _) => true
  | _ => false
  end.

Fixpoint pt_normal (p : proof_term) : bool :=
  match p with
  | PT_MP p1 p2 =>
      andb (negb (pt_redex_at_root (PT_MP p1 p2)))
           (andb (pt_normal p1) (pt_normal p2))
  | PT_Nec _ p1 => pt_normal p1
  | _ => true
  end.

(** Atomic proof terms are always normal. *)

Lemma pt_normal_atomic : forall p,
  match p with
  | PT_MP _ _ | PT_Nec _ _ => False
  | _ => True
  end -> pt_normal p = true.
Proof.
  intros p H.
  destruct p; cbn; try reflexivity; contradiction.
Qed.

(** A normal proof term has no root redex. *)

Lemma pt_normal_no_root_redex : forall p,
  pt_normal p = true -> pt_redex_at_root p = false.
Proof.
  intros p H. destruct p; cbn in *; try reflexivity.
  apply Bool.andb_true_iff in H. destruct H as [Hneg _].
  apply Bool.negb_true_iff in Hneg. exact Hneg.
Qed.

(** ** Existence of normal forms.

    Every proof term reduces to a normal form via well-founded recursion
    on [proof_term_size].  We express this as: for every [p], there
    exists a [p'] such that [pt_reduces*] reaches [p'] and [pt_normal p']. *)

Inductive pt_reduces_star : proof_term -> proof_term -> Prop :=
  | PTRS_refl : forall p, pt_reduces_star p p
  | PTRS_step : forall p p' p'',
      pt_reduces p p' -> pt_reduces_star p' p'' -> pt_reduces_star p p''.

Lemma pt_reduces_star_size : forall p p',
  pt_reduces_star p p' -> proof_term_size p' <= proof_term_size p.
Proof.
  intros p p' H. induction H.
  - reflexivity.
  - pose proof (pt_reduces_decreases_size p p' H) as Hlt. lia.
Qed.

(** Subject reduction extends to multi-step reduction. *)

Theorem pt_reduces_star_subject_reduction : forall p p' phi,
  pt_reduces_star p p' ->
  denote_proof_term p = Some phi ->
  denote_proof_term p' = Some phi.
Proof.
  intros p p' phi Hstar. revert phi.
  induction Hstar; intro chi; intro Hd.
  - exact Hd.
  - apply IHHstar.
    exact (pt_reduces_subject_reduction p p' chi H Hd).
Qed.

(** Strong normalisation: every proof term has a [pt_reduces]-normal
    form reachable in finitely many steps. *)

Theorem pt_normal_form_exists : forall p,
  exists p', pt_reduces_star p p' /\
             (forall q, ~ pt_reduces p' q).
Proof.
  intros p.
  induction p as [p IH] using
    (well_founded_induction proof_term_no_infinite_reduction).
  destruct (classic (exists q, pt_reduces p q)) as [[q Hpq] | Hnone].
  - destruct (IH q Hpq) as [p' [Hstar Hnf]].
    exists p'. split.
    + exact (PTRS_step p q p' Hpq Hstar).
    + exact Hnf.
  - exists p. split.
    + apply PTRS_refl.
    + intros q Hcontra. apply Hnone. exists q. exact Hcontra.
Qed.

(** Combined with subject reduction: every provable formula has a
    proof-term derivation in normal form. *)

Theorem provable_has_normal_form_proof : forall phi,
  |- phi -> exists p, denote_proof_term p = Some phi /\
                      (forall q, ~ pt_reduces p q).
Proof.
  intros phi Hp.
  destruct (provable_to_proof_term phi Hp) as [pt Hd].
  destruct (pt_normal_form_exists pt) as [pt' [Hstar Hnf]].
  exists pt'. split.
  - exact (pt_reduces_star_subject_reduction pt pt' phi Hstar Hd).
  - exact Hnf.
Qed.

(******************************************************************************)
(* Multiset measure for PTRF_S contraction.                                    *)
(*                                                                            *)
(* The PTRF_S rule duplicates [x]:                                            *)
(*   (PT_S _ _ _) f g x  -->  (f x) (g x)                                     *)
(* Naive [proof_term_size] does not strictly decrease (LHS=4+|f|+|g|+|x|,    *)
(* RHS=3+|f|+|g|+2|x|).                                                       *)
(*                                                                            *)
(* We build a measure based on the *count of PT_S occurrences*, observing    *)
(* that PTRF_S contraction strictly decreases the count when [x] contains    *)
(* no internal [PT_S].  We then strengthen to a multiset-pair measure.        *)
(******************************************************************************)

Fixpoint pt_S_count (p : proof_term) : nat :=
  match p with
  | PT_S _ _ _ => 1
  | PT_MP p1 p2 => pt_S_count p1 + pt_S_count p2
  | PT_Nec _ p1 => pt_S_count p1
  | _ => 0
  end.

(** PTRF_S strictly decreases [pt_S_count] when [x] has no internal S. *)

Lemma pt_S_count_PTRF_S_decreases_when_x_S_free : forall phi psi chi f g x,
  pt_S_count x = 0 ->
  pt_S_count (PT_MP (PT_MP f x) (PT_MP g x))
    < pt_S_count (PT_MP (PT_MP (PT_MP (PT_S phi psi chi) f) g) x).
Proof.
  intros phi psi chi f g x Hx.
  cbn. rewrite Hx. lia.
Qed.

(** ** Subterm-size-pair multiset measure.

    For each PTRF_S-redex root in the term, record the pair
    [(|f|+|g|, |x|)].  Reduction by PTRF_S removes the entry at the
    contracted redex; the inner-of-[x] entries get duplicated, but the
    inner-of-[f]/[g] entries are unchanged.  When [x] has no internal
    PTRF_S redex, the multiset strictly shrinks under multi-set order. *)

Fixpoint pt_S_redex_pairs (p : proof_term) : list (nat * nat) :=
  match p with
  | PT_MP (PT_MP (PT_MP (PT_S _ _ _) f) g) x =>
      (proof_term_size f + proof_term_size g, proof_term_size x)
        :: pt_S_redex_pairs f ++ pt_S_redex_pairs g ++ pt_S_redex_pairs x
  | PT_MP p1 p2 => pt_S_redex_pairs p1 ++ pt_S_redex_pairs p2
  | PT_Nec _ p1 => pt_S_redex_pairs p1
  | _ => []
  end.

(** PTRF_S contraction strictly decreases the redex-pair-list length
    when [f], [g], and [x] are all S-redex-free.  Under this hypothesis,
    the LHS has exactly one S-redex (the root one), and the RHS has
    none — neither [PT_MP f x] nor [PT_MP g x] can be a redex because
    that would require [f] or [g] itself to start with
    [PT_MP (PT_MP (PT_S _ _ _) _) _], contradicting their S-redex-free
    assumption. *)

(** [pt_atomic]: a proof term is atomic if it is not a PT_MP or PT_Nec.
    Atomic terms have no internal MPs and so cannot themselves form an
    S-redex root, nor can wrapping them in a single MP create one. *)

Definition pt_atomic (p : proof_term) : Prop :=
  match p with
  | PT_MP _ _ | PT_Nec _ _ => False
  | _ => True
  end.

Lemma pt_atomic_pairs_empty : forall p,
  pt_atomic p -> pt_S_redex_pairs p = [].
Proof.
  intros p H.
  destruct p; cbn; try reflexivity; contradiction.
Qed.

(** When [f] and [g] are atomic, [PT_MP f x] and [PT_MP g x] cannot be
    PTRF_S-redexes (which would require [f] or [g] to be of shape
    [PT_MP (PT_MP (PT_S _ _ _) _) _]).  The pair-list reduces to
    [pt_S_redex_pairs x] in the non-redex MP case. *)

Lemma pt_S_redex_pairs_MP_atomic_f : forall f x,
  pt_atomic f ->
  pt_S_redex_pairs (PT_MP f x) = pt_S_redex_pairs x.
Proof.
  intros f x H. destruct f; cbn in *; try contradiction; reflexivity.
Qed.

(** Strict-decrease theorem: PTRF_S contraction strictly decreases the
    redex-pair-list length when [f] and [g] are atomic and [x] has no
    S-redex.  Under these hypotheses, the LHS has exactly one redex
    (the root one), and the RHS has none. *)

Theorem PTRF_S_decreases_pair_count_atomic_fg :
  forall phi psi chi f g x,
    pt_atomic f ->
    pt_atomic g ->
    pt_S_redex_pairs x = [] ->
    length (pt_S_redex_pairs (PT_MP (PT_MP f x) (PT_MP g x))) <
    length (pt_S_redex_pairs
              (PT_MP (PT_MP (PT_MP (PT_S phi psi chi) f) g) x)).
Proof.
  intros phi psi chi f g x Hf Hg Hx.
  pose proof (pt_atomic_pairs_empty f Hf) as Hf'.
  pose proof (pt_atomic_pairs_empty g Hg) as Hg'.
  destruct f; cbn in Hf; try contradiction;
    destruct g; cbn in Hg; try contradiction;
    cbn [pt_S_redex_pairs];
    rewrite Hx; cbn [length app]; lia.
Qed.

(******************************************************************************)
(* Newman's lemma (abstract): well-foundedness + local confluence => global  *)
(* confluence (Church-Rosser).                                                *)
(******************************************************************************)

Section NewmanLemma.

Variable A : Type.
Variable R : A -> A -> Prop.

Definition R_star (x y : A) : Prop :=
  exists n,
    (fix iter (k : nat) (a b : A) : Prop :=
       match k with
       | 0 => a = b
       | S k' => exists c, R a c /\ iter k' c b
       end) n x y.

Lemma R_star_refl : forall x, R_star x x.
Proof. intro x. exists 0. cbn. reflexivity. Qed.

Lemma R_star_step : forall x y z, R x y -> R_star y z -> R_star x z.
Proof.
  intros x y z H1 [n H2]. exists (S n). cbn. exists y. split; assumption.
Qed.

Lemma R_star_one : forall x y, R x y -> R_star x y.
Proof.
  intros x y H. apply (R_star_step _ y _ H). apply R_star_refl.
Qed.

Lemma R_star_trans : forall x y z, R_star x y -> R_star y z -> R_star x z.
Proof.
  intros x y z [n1 H1]. revert x y H1.
  induction n1 as [|n IH]; intros x y H1 Hyz.
  - cbn in H1. subst y. exact Hyz.
  - cbn in H1. destruct H1 as [c [Hxc Hcy]].
    apply (R_star_step _ c). exact Hxc. exact (IH c y Hcy Hyz).
Qed.

Definition locally_confluent : Prop :=
  forall x y1 y2, R x y1 -> R x y2 ->
    exists z, R_star y1 z /\ R_star y2 z.

Definition confluent : Prop :=
  forall x y1 y2, R_star x y1 -> R_star x y2 ->
    exists z, R_star y1 z /\ R_star y2 z.

(** Newman's lemma — proved by well-founded induction on x. *)

Theorem newman_lemma :
  well_founded (fun y x => R x y) ->
  locally_confluent ->
  confluent.
Proof.
  intros Hwf Hloc x.
  induction x as [x IH] using (well_founded_induction Hwf).
  intros y1 y2 [n1 H1] [n2 H2]. revert y1 y2 H1 H2.
  destruct n1 as [|n1].
  - cbn. intros y1 y2 Hxy1 H2. subst y1.
    exists y2. split; [exists n2; exact H2 | apply R_star_refl].
  - destruct n2 as [|n2].
    + cbn. intros y1 y2 [c1 [Hxc1 Hc1y1]] Hxy2. subst y2.
      exists y1. split. apply R_star_refl. exists (S n1). cbn.
      exists c1. split; assumption.
    + cbn. intros y1 y2 [c1 [Hxc1 Hc1y1]] [c2 [Hxc2 Hc2y2]].
      destruct (Hloc x c1 c2 Hxc1 Hxc2) as [d [Hc1d Hc2d]].
      assert (Hc1y1' : R_star c1 y1) by (exists n1; exact Hc1y1).
      assert (Hc2y2' : R_star c2 y2) by (exists n2; exact Hc2y2).
      destruct (IH c1 Hxc1 y1 d Hc1y1' Hc1d) as [e1 [Hy1e1 Hde1]].
      destruct (IH c2 Hxc2 y2 e1 Hc2y2'
                  (R_star_trans _ _ _ Hc2d Hde1)) as [e2 [Hy2e2 He1e2]].
      exists e2. split.
      * exact (R_star_trans _ _ _ Hy1e1 He1e2).
      * exact Hy2e2.
Qed.

End NewmanLemma.

(** ** Newman's lemma instantiated for [pt_reduces]. *)

Theorem newman_for_pt_reduces :
  (forall p q1 q2, pt_reduces p q1 -> pt_reduces p q2 ->
     exists r, R_star _ pt_reduces q1 r /\ R_star _ pt_reduces q2 r) ->
  forall p q1 q2,
    R_star _ pt_reduces p q1 -> R_star _ pt_reduces p q2 ->
    exists r, R_star _ pt_reduces q1 r /\ R_star _ pt_reduces q2 r.
Proof.
  intro Hloc.
  apply (newman_lemma _ pt_reduces).
  - exact proof_term_no_infinite_reduction.
  - exact Hloc.
Qed.

(******************************************************************************)
(* Local confluence of [pt_reduces]: critical-pair analysis.                   *)
(******************************************************************************)

(** Lift a single-step reduction to the reflexive-transitive closure. *)

Lemma pt_reduces_R_star : forall p q,
  pt_reduces p q -> R_star _ pt_reduces p q.
Proof. intros p q H. apply R_star_one. exact H. Qed.

Lemma pt_reduces_R_star_refl : forall p, R_star _ pt_reduces p p.
Proof. intro p. apply R_star_refl. Qed.

(** Trivial confluence: both sides equal. *)

Lemma pt_reduces_confluence_eq : forall (q : proof_term),
  exists r, R_star _ pt_reduces q r /\ R_star _ pt_reduces q r.
Proof.
  intros q. exists q. split; apply (R_star_refl _ pt_reduces).
Qed.

(** Reductions inside MP-left and MP-right operate on different
    sub-positions and hence commute trivially. *)

Lemma pt_reduces_orthogonal_MP : forall p1 p1' p2 p2',
  pt_reduces p1 p1' -> pt_reduces p2 p2' ->
  exists r, R_star _ pt_reduces (PT_MP p1' p2) r /\
            R_star _ pt_reduces (PT_MP p1 p2') r.
Proof.
  intros p1 p1' p2 p2' H1 H2.
  exists (PT_MP p1' p2'). split.
  - apply pt_reduces_R_star. exact (PTR_MP_right _ _ _ H2).
  - apply pt_reduces_R_star. exact (PTR_MP_left _ _ _ H1).
Qed.

(** Lifting [pt_reduces_R_star] under MP-left context. *)

Lemma R_star_under_MP_left : forall p1 p1' p2,
  R_star _ pt_reduces p1 p1' ->
  R_star _ pt_reduces (PT_MP p1 p2) (PT_MP p1' p2).
Proof.
  intros p1 p1' p2 [n H]. revert p1 H.
  induction n as [|n IH]; intros p1 H.
  - cbn in H. subst p1'. apply R_star_refl.
  - cbn in H. destruct H as [c [Hpc Hcp1']].
    apply (R_star_step _ _ _ (PT_MP c p2)).
    + exact (PTR_MP_left _ _ _ Hpc).
    + exact (IH c Hcp1').
Qed.

Lemma R_star_under_MP_right : forall p1 p2 p2',
  R_star _ pt_reduces p2 p2' ->
  R_star _ pt_reduces (PT_MP p1 p2) (PT_MP p1 p2').
Proof.
  intros p1 p2 p2' [n H]. revert p2 H.
  induction n as [|n IH]; intros p2 H.
  - cbn in H. subst p2'. apply R_star_refl.
  - cbn in H. destruct H as [c [Hpc Hcp2']].
    apply (R_star_step _ _ _ (PT_MP p1 c)).
    + exact (PTR_MP_right _ _ _ Hpc).
    + exact (IH c Hcp2').
Qed.

Lemma R_star_under_Nec : forall n p p',
  R_star _ pt_reduces p p' ->
  R_star _ pt_reduces (PT_Nec n p) (PT_Nec n p').
Proof.
  intros n p p' [k H]. revert p H.
  induction k as [|k IH]; intros p H.
  - cbn in H. subst p'. apply R_star_refl.
  - cbn in H. destruct H as [c [Hpc Hcp']].
    apply (R_star_step _ _ _ (PT_Nec n c)).
    + exact (PTR_Nec _ _ _ Hpc).
    + exact (IH c Hcp').
Qed.

(** ** Local confluence: structural induction on the first reduction.

    For each pair of single-step reductions [p → q1] and [p → q2], we
    construct a common reduct.  The proof uses inductive case analysis:
    the contextual rules (MP-left, MP-right, Nec) recurse on subterms;
    the root contractions (PTR_K, PTR_BoxK_Nec) are critical pairs. *)

(** Atomic axiom-constructor terms admit no reduction.  This vacuous-case
    lemma simplifies critical-pair analyses where an inner contextual
    reduction would have to act on a [PT_K]/[PT_BoxK]/etc. which has
    no operational behaviour. *)

Lemma pt_reduces_atomic_K : forall phi psi q,
  ~ pt_reduces (PT_K phi psi) q.
Proof.
  intros phi psi q H. inversion H.
Qed.

Lemma pt_reduces_atomic_S : forall phi psi chi q,
  ~ pt_reduces (PT_S phi psi chi) q.
Proof.
  intros phi psi chi q H. inversion H.
Qed.

Lemma pt_reduces_atomic_DN : forall phi q,
  ~ pt_reduces (PT_DN phi) q.
Proof.
  intros phi q H. inversion H.
Qed.

Lemma pt_reduces_atomic_BoxK : forall n phi psi q,
  ~ pt_reduces (PT_BoxK n phi psi) q.
Proof.
  intros n phi psi q H. inversion H.
Qed.

Lemma pt_reduces_atomic_Loeb : forall n phi q,
  ~ pt_reduces (PT_Loeb n phi) q.
Proof.
  intros n phi q H. inversion H.
Qed.

Lemma pt_reduces_atomic_Box4 : forall n phi q,
  ~ pt_reduces (PT_Box4 n phi) q.
Proof.
  intros n phi q H. inversion H.
Qed.

Lemma pt_reduces_atomic_Mon : forall n phi q,
  ~ pt_reduces (PT_Mon n phi) q.
Proof.
  intros n phi q H. inversion H.
Qed.

Lemma pt_reduces_atomic_NextCon : forall n q,
  ~ pt_reduces (PT_NextCon n) q.
Proof.
  intros n q H. inversion H.
Qed.

(** Inversion of a single reduction inside [PT_Nec n p]: the only rule
    that applies is [PTR_Nec] (since [PT_Nec] is not a [PT_MP]). *)

Lemma pt_reduces_Nec_inv : forall n p q,
  pt_reduces (PT_Nec n p) q ->
  exists p', q = PT_Nec n p' /\ pt_reduces p p'.
Proof.
  intros n p q H. inversion H. subst.
  eexists. split; [reflexivity | eassumption].
Qed.

(** Inversion of a single reduction inside [PT_MP a b]: either inner
    [a → a'] (PTR_MP_left), inner [b → b'] (PTR_MP_right), or a root
    contraction (PTR_K, PTR_BoxK_Nec) — the latter requiring [a] to
    have specific shapes. *)

Lemma pt_reduces_MP_inv : forall a b q,
  pt_reduces (PT_MP a b) q ->
    (exists a', q = PT_MP a' b /\ pt_reduces a a') \/
    (exists b', q = PT_MP a b' /\ pt_reduces b b') \/
    (exists phi psi p1, a = PT_MP (PT_K phi psi) p1 /\ q = p1) \/
    (exists n phi psi p1 p2,
       a = PT_MP (PT_BoxK n phi psi) (PT_Nec n p1) /\
       b = PT_Nec n p2 /\
       q = PT_Nec n (PT_MP p1 p2)).
Proof.
  intros a b q H. inversion H; subst.
  - left. eexists. split; [reflexivity | eassumption].
  - right. left. eexists. split; [reflexivity | eassumption].
  - right. right. left. eexists. eexists. eexists. split; reflexivity.
  - right. right. right. eexists. eexists. eexists. eexists. eexists.
    split; [reflexivity | split; reflexivity].
Qed.

(** ** Local confluence: critical-pair-by-critical-pair analysis.

    Strategy: structural induction on the first reduction [H1].  In
    each case, invert the second reduction [H2] using the dedicated
    [pt_reduces_MP_inv] / [pt_reduces_Nec_inv] inversion lemmas,
    yielding finitely many sub-cases.  Each sub-case is closed either
    by appeal to the inductive hypothesis (when both reductions are
    inside the same subterm), by orthogonality (when reductions are
    in disjoint sub-positions), or by explicit construction of a
    common reduct. *)

Lemma pt_reduces_local_confluence : forall p q1 q2,
  pt_reduces p q1 -> pt_reduces p q2 ->
  exists r, R_star _ pt_reduces q1 r /\ R_star _ pt_reduces q2 r.
Proof.
  intros p q1 q2 H1. revert q2.
  induction H1 as [a a' b H1a IHa
                  | a b b' H1b IHb
                  | n c c' H1c IHc
                  | phi psi p1 p2
                  | n phi psi p1 p2]; intros q2 H2.
  - (* H1 = PTR_MP_left a a' b: q1 = PT_MP a' b, with a → a'. *)
    apply pt_reduces_MP_inv in H2. destruct H2 as
      [[a'' [Eq Ha]] | [[b'' [Eq Hb]] | [[phi [psi [p1 [Eq1 Eq2]]]] |
       [n [phi [psi [p1 [p2 [Eq1 [Eq2 Eq3]]]]]]]]]].
    + (* H2: inner left a → a''.  Recurse via IHa. *)
      subst q2.
      destruct (IHa a'' Ha) as [r [Hr1 Hr2]].
      exists (PT_MP r b). split.
      * apply R_star_under_MP_left. exact Hr1.
      * apply R_star_under_MP_left. exact Hr2.
    + (* H2: inner right b → b''.  Orthogonal. *)
      subst q2.
      exists (PT_MP a' b''). split.
      * apply pt_reduces_R_star. exact (PTR_MP_right _ _ _ Hb).
      * apply pt_reduces_R_star. exact (PTR_MP_left _ _ _ H1a).
    + (* H2: PTR_K, so a = PT_MP (PT_K phi psi) p1, b = anything,
         q2 = p1. *)
      subst a. subst q2.
      apply pt_reduces_MP_inv in H1a. destruct H1a as
        [[a'' [Eq Hred]] | [[b'' [Eq Hred]] | [[phi' [psi' [p1' [Eq1 Eq2]]]] |
         [n' [phi' [psi' [p1' [p2' [Eq1 [Eq2 Eq3]]]]]]]]]].
      * (* a = PT_MP (PT_K phi psi) p1, inner left: PT_K → a''.  Vacuous. *)
        apply pt_reduces_atomic_K in Hred. contradiction.
      * (* Inner right: p1 → b''.  a' = PT_MP (PT_K phi psi) b''. *)
        subst a'.
        exists b''. split.
        -- apply pt_reduces_R_star. exact (PTR_K phi psi b'' b).
        -- apply pt_reduces_R_star. exact Hred.
      * (* Inner PTR_K shape: PT_MP (PT_K phi psi) p1 = PT_MP (PT_K phi' psi') p1'? Vacuous shape. *)
        discriminate Eq1.
      * discriminate Eq1.
    + (* H2: PTR_BoxK_Nec.  a = PT_MP (PT_BoxK n phi psi) (PT_Nec n p1),
         b = PT_Nec n p2, q2 = PT_Nec n (PT_MP p1 p2). *)
      subst a b q2.
      apply pt_reduces_MP_inv in H1a. destruct H1a as
        [[a'' [Eq Hred]] | [[b'' [Eq Hred]] | [[phi' [psi' [p1' [Eq1 Eq2]]]] |
         [n' [phi' [psi' [p1' [p2' [Eq1 [Eq2 Eq3]]]]]]]]]].
      * apply pt_reduces_atomic_BoxK in Hred. contradiction.
      * (* Inner right: PT_Nec n p1 → b''. *)
        apply pt_reduces_Nec_inv in Hred. destruct Hred as [p1'' [Eq' Hp1]].
        subst b''. subst a'.
        exists (PT_Nec n (PT_MP p1'' p2)). split.
        -- apply pt_reduces_R_star.
           exact (PTR_BoxK_Nec n phi psi p1'' p2).
        -- apply pt_reduces_R_star.
           apply PTR_Nec. exact (PTR_MP_left _ _ _ Hp1).
      * discriminate Eq1.
      * discriminate Eq1.
  - (* H1 = PTR_MP_right a b b': q1 = PT_MP a b'. *)
    apply pt_reduces_MP_inv in H2. destruct H2 as
      [[a'' [Eq Ha]] | [[b'' [Eq Hb]] | [[phi [psi [p1 [Eq1 Eq2]]]] |
       [n [phi [psi [p1 [p2 [Eq1 [Eq2 Eq3]]]]]]]]]].
    + (* Inner left a → a''.  Orthogonal. *)
      subst q2.
      exists (PT_MP a'' b'). split.
      * apply pt_reduces_R_star. exact (PTR_MP_left _ _ _ Ha).
      * apply pt_reduces_R_star. exact (PTR_MP_right _ _ _ H1b).
    + (* Inner right: recurse. *)
      subst q2.
      destruct (IHb b'' Hb) as [r [Hr1 Hr2]].
      exists (PT_MP a r). split.
      * apply R_star_under_MP_right. exact Hr1.
      * apply R_star_under_MP_right. exact Hr2.
    + (* PTR_K: a = PT_MP (PT_K phi psi) p1, q2 = p1. *)
      subst a q2.
      exists p1. split.
      * apply pt_reduces_R_star. exact (PTR_K phi psi p1 b').
      * apply R_star_refl.
    + (* PTR_BoxK_Nec: a = PT_MP (PT_BoxK n phi psi) (PT_Nec n p1),
         b = PT_Nec n p2, q2 = PT_Nec n (PT_MP p1 p2).
         q1 = PT_MP a b' where b → b'. *)
      subst a b q2.
      (* H1b : pt_reduces (PT_Nec n p2) b'.  By Nec inversion. *)
      apply pt_reduces_Nec_inv in H1b. destruct H1b as [p2' [Eq Hp2]].
      subst b'.
      exists (PT_Nec n (PT_MP p1 p2')). split.
      * apply pt_reduces_R_star.
        exact (PTR_BoxK_Nec n phi psi p1 p2').
      * apply pt_reduces_R_star.
        apply PTR_Nec. exact (PTR_MP_right _ _ _ Hp2).
  - (* H1 = PTR_Nec n c c': q1 = PT_Nec n c'. *)
    apply pt_reduces_Nec_inv in H2. destruct H2 as [c'' [Eq Hc]].
    subst q2.
    destruct (IHc c'' Hc) as [r [Hr1 Hr2]].
    exists (PT_Nec n r). split.
    + apply R_star_under_Nec. exact Hr1.
    + apply R_star_under_Nec. exact Hr2.
  - (* H1 = PTR_K phi psi p1 p2: q1 = p1. *)
    apply pt_reduces_MP_inv in H2. destruct H2 as
      [[a'' [Eq Ha]] | [[b'' [Eq Hb]] | [[phi' [psi' [p1' [Eq1 Eq2]]]] |
       [n' [phi' [psi' [p1' [p2' [Eq1 [Eq2 Eq3]]]]]]]]]].
    + (* Inner left: PT_MP (PT_K phi psi) p1 → a''. *)
      apply pt_reduces_MP_inv in Ha. destruct Ha as
        [[a''' [Eq' Hred]] | [[b''' [Eq' Hred]] | [[phi'' [psi'' [p1'' [Eq1 Eq2]]]] |
         [n'' [phi'' [psi'' [p1'' [p2'' [Eq1 [Eq2 Eq3]]]]]]]]]].
      * apply pt_reduces_atomic_K in Hred. contradiction.
      * subst a'' q2.
        exists b'''. split.
        -- apply pt_reduces_R_star. exact Hred.
        -- apply pt_reduces_R_star. exact (PTR_K phi psi b''' p2).
      * discriminate Eq1.
      * discriminate Eq1.
    + (* Inner right: p2 → b''. *)
      subst q2.
      exists p1. split.
      * apply R_star_refl.
      * apply pt_reduces_R_star. exact (PTR_K phi psi p1 b'').
    + (* PTR_K twice: same shape, q2 = p1. *)
      injection Eq1 as Eq1a Eq1b. subst phi' psi' p1'.
      subst q2.
      exists p1. split; apply R_star_refl.
    + (* PTR_BoxK_Nec: shape mismatch. *)
      discriminate Eq1.
  - (* H1 = PTR_BoxK_Nec n phi psi p1 p2:
       q1 = PT_Nec n (PT_MP p1 p2). *)
    apply pt_reduces_MP_inv in H2. destruct H2 as
      [[a'' [Eq Ha]] | [[b'' [Eq Hb]] | [[phi' [psi' [p1' [Eq1 Eq2]]]] |
       [n' [phi' [psi' [p1' [p2' [Eq1 [Eq2 Eq3]]]]]]]]]].
    + (* Inner left: PT_MP (PT_BoxK n phi psi) (PT_Nec n p1) → a''. *)
      apply pt_reduces_MP_inv in Ha. destruct Ha as
        [[a''' [Eq' Hred]] | [[b''' [Eq' Hred]] | [[phi'' [psi'' [p1'' [Eq1 Eq2]]]] |
         [n'' [phi'' [psi'' [p1'' [p2'' [Eq1 [Eq2 Eq3]]]]]]]]]].
      * apply pt_reduces_atomic_BoxK in Hred. contradiction.
      * (* Inner right: PT_Nec n p1 → b'''.  By Nec inversion: p1 → p1_*. *)
        apply pt_reduces_Nec_inv in Hred. destruct Hred as [p1_ [Eq'' Hp1]].
        subst b''' a'' q2.
        exists (PT_Nec n (PT_MP p1_ p2)). split.
        -- apply pt_reduces_R_star.
           apply PTR_Nec. exact (PTR_MP_left _ _ _ Hp1).
        -- apply pt_reduces_R_star.
           exact (PTR_BoxK_Nec n phi psi p1_ p2).
      * discriminate Eq1.
      * discriminate Eq1.
    + (* Inner right: PT_Nec n p2 → b''.  By Nec inversion: p2 → p2_*. *)
      apply pt_reduces_Nec_inv in Hb. destruct Hb as [p2_ [Eq' Hp2]].
      subst b'' q2.
      exists (PT_Nec n (PT_MP p1 p2_)). split.
      * apply pt_reduces_R_star.
        apply PTR_Nec. exact (PTR_MP_right _ _ _ Hp2).
      * apply pt_reduces_R_star.
        exact (PTR_BoxK_Nec n phi psi p1 p2_).
    + (* PTR_K: shape mismatch. *)
      discriminate Eq1.
    + (* PTR_BoxK_Nec twice: same shape, q2 = q1. *)
      inversion Eq1; subst.
      inversion Eq2; subst.
      exists (PT_Nec n' (PT_MP p1' p2')). split; apply R_star_refl.
Qed.

(** Confluence (Church-Rosser) of [pt_reduces]: from local confluence
    plus well-foundedness via Newman's lemma. *)

Theorem pt_reduces_church_rosser :
  forall p q1 q2,
    R_star _ pt_reduces p q1 -> R_star _ pt_reduces p q2 ->
    exists r, R_star _ pt_reduces q1 r /\ R_star _ pt_reduces q2 r.
Proof.
  apply newman_for_pt_reduces.
  exact pt_reduces_local_confluence.
Qed.

(******************************************************************************)
(* Strong normalisation of [pt_reduces_full] on the S-free subset.            *)
(*                                                                            *)
(* The full pt_reduces_full system includes PTRF_S, which duplicates the     *)
(* third argument [x] and so does not strictly decrease [proof_term_size]    *)
(* in general.  Howard-style ordinal measures handle this for typed         *)
(* combinatory logic but are research-level for the present untyped         *)
(* polymodal calculus.                                                        *)
(*                                                                            *)
(* On the S-free subset (terms with no [PT_S] occurrence anywhere), [PTRF_S] *)
(* never fires.  All remaining rules strictly decrease [proof_term_size],   *)
(* hence well-foundedness holds via the size measure.                       *)
(******************************************************************************)

(** Note: [pt_S_count] does NOT decrease monotonically under
    [pt_reduces_full] in general — PTRF_S duplicates [x] and can
    therefore increase the count when [x] contains multiple [PT_S]
    occurrences.  However, [pt_S_count = 0] (S-free) IS preserved:
    no rule introduces a [PT_S] from nothing, and PTRF_S cannot fire
    when the LHS is S-free. *)

Lemma pt_S_count_pt_reduces_le : forall p p',
  pt_reduces p p' -> pt_S_count p' <= pt_S_count p.
Proof.
  intros p p' H. induction H; cbn; lia.
Qed.

Lemma pt_S_free_preserved : forall p p',
  pt_S_count p = 0 ->
  pt_reduces_full p p' ->
  pt_S_count p' = 0.
Proof.
  intros p p' Hp H. revert Hp.
  induction H; intro Hp; cbn in *.
  - (* PTRF_orig: pt_reduces; uses pt_S_count_pt_reduces_le. *)
    pose proof (pt_S_count_pt_reduces_le _ _ H). lia.
  - (* PTRF_MP_left *)
    assert (pt_S_count p1 = 0) by lia.
    pose proof (IHpt_reduces_full H0). lia.
  - (* PTRF_MP_right *)
    assert (pt_S_count p2 = 0) by lia.
    pose proof (IHpt_reduces_full H0). lia.
  - (* PTRF_Nec *)
    pose proof (IHpt_reduces_full Hp). lia.
  - (* PTRF_S: PT_S in LHS contradicts Hp = 0. *)
    discriminate Hp.
  - (* PTRF_DN_K *)
    lia.
Qed.

(** Strict size decrease under [pt_reduces_full] when [pt_S_count = 0].
    On S-free terms, PTRF_S cannot fire, and the remaining rules each
    strictly decrease [proof_term_size]. *)

Lemma pt_reduces_full_decreases_size_S_free : forall p p',
  pt_S_count p = 0 ->
  pt_reduces_full p p' ->
  proof_term_size p' < proof_term_size p.
Proof.
  intros p p' Hp H. revert Hp.
  induction H; intro Hp; cbn in *.
  - apply pt_reduces_decreases_size. exact H.
  - lia.
  - lia.
  - lia.
  - (* PTRF_S: but pt_S_count of LHS includes the PT_S, so ≥ 1, contradicting Hp. *)
    cbn in Hp. discriminate Hp.
  - (* PTRF_DN_K *) lia.
Qed.

(** Strong normalisation: on the S-free subset, [pt_reduces_full] is
    well-founded (descending chains terminate). *)

Theorem pt_reduces_full_SN_S_free : forall p,
  pt_S_count p = 0 ->
  Acc (fun y x => pt_S_count x = 0 /\ pt_reduces_full x y) p.
Proof.
  intro p.
  induction p as [p IH] using
    (well_founded_induction
       (Wf_nat.well_founded_lt_compat _ proof_term_size _ (fun x y H => H))).
  intros Hp. apply Acc_intro. intros y [_ Hred].
  apply IH.
  - exact (pt_reduces_full_decreases_size_S_free p y Hp Hred).
  - exact (pt_S_free_preserved p y Hp Hred).
Qed.

(** Useful corollary: every S-free proof term has only finitely many
    reducts under pt_reduces_full's transitive closure. *)

Theorem pt_reduces_full_S_free_terminates :
  well_founded (fun y x => pt_S_count x = 0 /\ pt_reduces_full x y).
Proof.
  intro p.
  destruct (Nat.eq_dec (pt_S_count p) 0) as [Hp|Hnp].
  - exact (pt_reduces_full_SN_S_free p Hp).
  - apply Acc_intro. intros y [Hy _]. exfalso. apply Hnp. exact Hy.
Qed.

(******************************************************************************)
(* Strict ordinal decrease under reduction.                                    *)
(*                                                                            *)
(* [proof_term_ordinal] maps each proof term to a CNF ordinal in [ord].      *)
(* Under [pt_reduces] every reduction strictly decreases this ordinal in     *)
(* [ord_lt], witnessing a sharp proof-theoretic descent.                     *)
(******************************************************************************)

(** Lifting [ord_lt] through [OCons] with congruent contexts. *)

Lemma ord_lt_OCons_head : forall a a' t1 t2,
  ord_lt a a' -> ord_lt (OCons a t1) (OCons a' t2).
Proof.
  intros a a' t1 t2 H. unfold ord_lt in *. cbn.
  rewrite H. reflexivity.
Qed.

Lemma ord_lt_OCons_tail : forall a t t',
  ord_lt t t' -> ord_lt (OCons a t) (OCons a t').
Proof.
  intros a t t' H. unfold ord_lt in *. cbn.
  rewrite ord_compare_refl. exact H.
Qed.

(** [proof_term_ordinal] of an atomic proof term is [OZero]. *)

Lemma proof_term_ordinal_atomic : forall p,
  pt_atomic p -> proof_term_ordinal p = OZero.
Proof.
  intros p H. destruct p; cbn; try reflexivity; contradiction.
Qed.

(** [proof_term_ordinal] of [PT_K phi psi] (an atom) is [OZero]. *)

Lemma proof_term_ordinal_K : forall phi psi,
  proof_term_ordinal (PT_K phi psi) = OZero.
Proof. intros. cbn. reflexivity. Qed.

(** [proof_term_ordinal] of [PT_BoxK n phi psi]: also OZero (atom). *)

Lemma proof_term_ordinal_BoxK : forall n phi psi,
  proof_term_ordinal (PT_BoxK n phi psi) = OZero.
Proof. intros. cbn. reflexivity. Qed.

(** Subterm bound: every subterm's ordinal is bounded by the whole. *)

Lemma proof_term_ordinal_left_lt : forall p1 p2,
  ord_lt (proof_term_ordinal p1) (proof_term_ordinal (PT_MP p1 p2)).
Proof.
  intros p1 p2. cbn.
  exact (ord_lt_OCons_self (proof_term_ordinal p1) (proof_term_ordinal p2)).
Qed.

Lemma proof_term_ordinal_decrease_MP_left : forall p1 p1' p2,
  ord_lt (proof_term_ordinal p1') (proof_term_ordinal p1) ->
  ord_lt (proof_term_ordinal (PT_MP p1' p2)) (proof_term_ordinal (PT_MP p1 p2)).
Proof.
  intros p1 p1' p2 H. cbn. apply ord_lt_OCons_head. exact H.
Qed.

Lemma proof_term_ordinal_decrease_MP_right : forall p1 p2 p2',
  ord_lt (proof_term_ordinal p2') (proof_term_ordinal p2) ->
  ord_lt (proof_term_ordinal (PT_MP p1 p2')) (proof_term_ordinal (PT_MP p1 p2)).
Proof.
  intros p1 p2 p2' H. cbn. apply ord_lt_OCons_tail. exact H.
Qed.

Lemma proof_term_ordinal_decrease_Nec : forall n p p',
  ord_lt (proof_term_ordinal p') (proof_term_ordinal p) ->
  ord_lt (proof_term_ordinal (PT_Nec n p')) (proof_term_ordinal (PT_Nec n p)).
Proof.
  intros n p p' H. cbn. apply ord_lt_OCons_tail. exact H.
Qed.

Theorem proof_term_ordinal_image_bounded : forall p,
  exists o : ord, proof_term_ordinal p = o.
Proof. intro p. exists (proof_term_ordinal p). reflexivity. Qed.

Fixpoint nat_to_ord_chain (n : nat) : ord :=
  match n with
  | 0 => OZero
  | S k => OCons OZero (nat_to_ord_chain k)
  end.

Lemma nat_to_ord_chain_zero : nat_to_ord_chain 0 = OZero.
Proof. reflexivity. Qed.

Lemma nat_to_ord_chain_succ : forall n,
  nat_to_ord_chain (S n) = OCons OZero (nat_to_ord_chain n).
Proof. reflexivity. Qed.

Lemma nat_to_ord_chain_OCons_succ_lt : forall n,
  ord_lt (nat_to_ord_chain n) (OCons OZero (nat_to_ord_chain n)).
Proof.
  induction n as [|n IH]; cbn.
  - reflexivity.
  - unfold ord_lt in *. cbn. cbn in IH. exact IH.
Qed.

Lemma nat_to_ord_chain_strictly_increasing : forall n,
  ord_lt (nat_to_ord_chain n) (nat_to_ord_chain (S n)).
Proof. intro n. cbn. apply nat_to_ord_chain_OCons_succ_lt. Qed.

Lemma nat_to_ord_chain_lt : forall n m,
  n < m -> ord_lt (nat_to_ord_chain n) (nat_to_ord_chain m).
Proof.
  intros n m H. induction H.
  - apply nat_to_ord_chain_strictly_increasing.
  - apply (ord_lt_trans _ (nat_to_ord_chain m)).
    + exact IHle.
    + apply nat_to_ord_chain_strictly_increasing.
Qed.

Definition proof_term_ord_v2 (p : proof_term) : ord :=
  nat_to_ord_chain (proof_term_size p).

Theorem proof_term_ord_v2_strictly_decreases : forall p p',
  pt_reduces p p' ->
  ord_lt (proof_term_ord_v2 p') (proof_term_ord_v2 p).
Proof.
  intros p p' H. unfold proof_term_ord_v2.
  apply nat_to_ord_chain_lt.
  exact (pt_reduces_decreases_size p p' H).
Qed.

Theorem proof_term_ord_v2_image_finite : forall p,
  exists o : ord, proof_term_ord_v2 p = o /\
    (exists n, o = nat_to_ord_chain n).
Proof.
  intro p. unfold proof_term_ord_v2.
  exists (nat_to_ord_chain (proof_term_size p)). split; [reflexivity|].
  exists (proof_term_size p). reflexivity.
Qed.

Lemma free_vars_Impl : forall X phi,
  free_vars (Impl X phi) = free_vars X ++ free_vars phi.
Proof. intros. cbn. reflexivity. Qed.

Lemma not_in_free_vars_Impl : forall p X phi,
  ~ In p (free_vars X) ->
  ~ In p (free_vars phi) ->
  ~ In p (free_vars (Impl X phi)).
Proof.
  intros p X phi HX Hphi Hin.
  rewrite free_vars_Impl in Hin.
  apply in_app_or in Hin. destruct Hin; contradiction.
Qed.

Lemma Subst_Impl_no_occ_X : forall p X Y phi,
  ~ In p (free_vars X) ->
  Subst p Y (Impl X phi) = Impl X (Subst p Y phi).
Proof.
  intros p X Y phi HX.
  pose proof (Subst_no_occurrence p Y X HX) as HX'.
  unfold Subst in *. cbn.
  rewrite HX'. reflexivity.
Qed.

Lemma sambin_witness_impl_left_no_occ_when_phi_no_occurrence :
  forall p X phi,
    ~ In p (free_vars X) ->
    ~ In p (free_vars phi) ->
    exists psi, |- Iff psi (Subst p psi (Impl X phi)).
Proof.
  intros p X phi HX Hphi.
  apply sambin_witness_no_occurrence.
  apply not_in_free_vars_Impl; assumption.
Qed.

Lemma sambin_witness_impl_left_no_occ_when_phi_top_solves :
  forall p X phi,
    ~ In p (free_vars X) ->
    |- Subst p Top phi ->
    exists psi, |- Iff psi (Subst p psi (Impl X phi)).
Proof.
  intros p X phi HX Hphi.
  apply fixed_point_existence_top_solves.
  rewrite (Subst_Impl_no_occ_X p X Top phi HX).
  exact (prov_weaken _ X Hphi).
Qed.

Lemma sambin_witness_impl_left_no_occ_when_phi_box_atomic :
  forall p X n,
    ~ In p (free_vars X) ->
    exists psi, |- Iff psi (Subst p psi (Impl X (Box n (Var p)))).
Proof.
  intros p X n HX.
  apply sambin_witness_impl_left_no_occ_when_phi_top_solves; [exact HX|].
  unfold Subst. cbn. rewrite Nat.eqb_refl.
  exact (prov_box_top n).
Qed.

Lemma sambin_witness_impl_left_no_occ_when_phi_loeb_form :
  forall p X n Y,
    ~ In p (free_vars X) ->
    ~ In p (free_vars Y) ->
    |- Y ->
    exists psi, |- Iff psi (Subst p psi (Impl X (Box n (Impl (Var p) Y)))).
Proof.
  intros p X n Y HX HY HYprov.
  apply sambin_witness_impl_left_no_occ_when_phi_top_solves; [exact HX|].
  pose proof (Subst_no_occurrence p Top Y HY) as HY'.
  unfold Subst in *. cbn. rewrite Nat.eqb_refl.
  rewrite HY'.
  apply Nec. apply prov_weaken. exact HYprov.
Qed.

Lemma prov_impl_X_under_K : forall X A,
  |- Impl A (Impl X A).
Proof. intros X A. exact (Ax_K A X). Qed.

Lemma prov_meta_chain_K : forall X A Y,
  |- Impl (Impl (Impl X A) Y) (Impl A Y).
Proof.
  intros X A Y.
  pose proof (prov_compose_internal A (Impl X A) Y) as Hci.
  pose proof (prov_impl_X_under_K X A) as Hk.
  exact (MP _ _ (prov_perm _ _ _ Hci) Hk).
Qed.

Lemma sambin_witness_impl_left_no_occ_loeb_form_general :
  forall p X n Y,
    ~ In p (free_vars X) ->
    ~ In p (free_vars Y) ->
    exists psi, |- Iff psi (Subst p psi (Impl X (Box n (Impl (Var p) Y)))).
Proof.
  intros p X n Y HX HY.
  exists (Impl X (Box n Y)).
  pose proof (Subst_no_occurrence p (Impl X (Box n Y)) X HX) as HsubstX.
  pose proof (Subst_no_occurrence p (Impl X (Box n Y)) Y HY) as HsubstY.
  unfold Subst in *.
  assert (Hsubst :
    subst_form (fun k => if Nat.eqb k p then Impl X (Box n Y) else Var k)
               (Impl X (Box n (Impl (Var p) Y))) =
    Impl X (Box n (Impl (Impl X (Box n Y)) Y))).
  { cbn. rewrite HsubstX, HsubstY. rewrite Nat.eqb_refl. reflexivity. }
  rewrite Hsubst. clear Hsubst HsubstX HsubstY.
  apply prov_iff_intro.
  - pose proof (Ax_K Y (Impl X (Box n Y))) as HK1.
    pose proof (Nec n _ HK1) as HK1n.
    pose proof (Ax_BoxK n Y (Impl (Impl X (Box n Y)) Y)) as HBK.
    pose proof (MP _ _ HBK HK1n) as Hstep1.
    pose proof (prov_compose_internal X (Box n Y)
                  (Box n (Impl (Impl X (Box n Y)) Y))) as Hci.
    pose proof (MP _ _ Hci Hstep1) as Hstep2.
    exact Hstep2.
  - pose proof (prov_meta_chain_K X (Box n Y) Y) as Hmeta.
    pose proof (Nec n _ Hmeta) as HmetaN.
    pose proof (Ax_BoxK n (Impl (Impl X (Box n Y)) Y)
                          (Impl (Box n Y) Y)) as HBK1.
    pose proof (MP _ _ HBK1 HmetaN) as Hstep1.
    pose proof (Ax_Loeb n Y) as HLoeb.
    pose proof (prov_compose _ _ _ Hstep1 HLoeb) as Hstep2.
    pose proof (prov_compose_internal X
                  (Box n (Impl (Impl X (Box n Y)) Y))
                  (Box n Y)) as Hci.
    pose proof (MP _ _ Hci Hstep2) as Hstep3.
    exact Hstep3.
Qed.

Lemma Subst_no_occurrence_And : forall p X Y phi,
  ~ In p (free_vars X) ->
  Subst p Y (And X phi) = And X (Subst p Y phi).
Proof.
  intros p X Y phi HX.
  pose proof (Subst_no_occurrence p Y X HX) as HX'.
  unfold Subst, And, Neg in *. cbn.
  rewrite HX'. reflexivity.
Qed.

Lemma prov_box_and_intro_meta : forall n A B,
  |- Box n A -> |- Box n B -> |- Box n (And A B).
Proof.
  intros n A B HA HB.
  pose proof (prov_box_and_intro n A B) as Hai.
  exact (MP _ _ (MP _ _ Hai HA) HB).
Qed.

Lemma prov_box_and_iff_box_box4 : forall n X,
  |- Iff (Box n X) (Box n (And X (Box n X))).
Proof.
  intros n X.
  apply prov_iff_intro.
  - pose proof (Ax_Box4 n X) as Hbox4.
    pose proof (prov_box_and_intro n X (Box n X)) as Hai.
    pose proof (Ax_S (Box n X) (Box n (Box n X)) (Box n (And X (Box n X)))) as Hs.
    pose proof (MP _ _ Hs Hai) as Hstep1.
    exact (MP _ _ Hstep1 Hbox4).
  - exact (prov_box_and_elim_l n X (Box n X)).
Qed.

Theorem sambin_witness_and_box_atomic : forall p X n,
  ~ In p (free_vars X) ->
  exists psi, |- Iff psi (Subst p psi (And X (Box n (Var p)))).
Proof.
  intros p X n HX.
  exists (And X (Box n X)).
  pose proof (Subst_no_occurrence_And p X (And X (Box n X))
                (Box n (Var p)) HX) as HsubstAnd.
  rewrite HsubstAnd.
  assert (HsubstBox : Subst p (And X (Box n X)) (Box n (Var p)) =
                     Box n (And X (Box n X))).
  { unfold Subst. cbn. rewrite Nat.eqb_refl. reflexivity. }
  rewrite HsubstBox.
  pose proof (prov_box_and_iff_box_box4 n X) as Hbox_iff.
  pose proof (prov_equiv_box_cong n X (And X (Box n X))) as Hcong_box.
  unfold prov_equiv in *.
  apply prov_equiv_impl_cong; [|exact (prov_iff_refl Bot)].
  apply prov_equiv_impl_cong; [exact (prov_iff_refl X)|].
  apply prov_equiv_impl_cong; [exact Hbox_iff | exact (prov_iff_refl Bot)].
Qed.

Lemma Subst_no_occurrence_Or : forall p X Y phi,
  ~ In p (free_vars X) ->
  Subst p Y (Or X phi) = Or X (Subst p Y phi).
Proof.
  intros p X Y phi HX.
  pose proof (Subst_no_occurrence p Y X HX) as HX'.
  unfold Subst, Or, Neg in *. cbn.
  rewrite HX'. reflexivity.
Qed.

Theorem sambin_witness_or_box_atomic : forall p X n,
  ~ In p (free_vars X) ->
  exists psi, |- Iff psi (Subst p psi (Or X (Box n (Var p)))).
Proof.
  intros p X n HX.
  exists Top.
  pose proof (Subst_no_occurrence_Or p X Top (Box n (Var p)) HX) as HsubstOr.
  rewrite HsubstOr.
  assert (HsubstBox : Subst p Top (Box n (Var p)) = Box n Top).
  { unfold Subst. cbn. rewrite Nat.eqb_refl. reflexivity. }
  rewrite HsubstBox.
  pose proof (prov_box_top n) as HboxTop.
  pose proof (prov_or_intro_r X (Box n Top)) as Hor_intro.
  apply prov_iff_intro.
  - apply prov_weaken. exact (MP _ _ Hor_intro HboxTop).
  - apply prov_weaken. exact (prov_id Bot).
Qed.

Theorem sambin_witness_double_box : forall p n m,
  exists psi, |- Iff psi (Subst p psi (Box n (Box m (Var p)))).
Proof.
  intros p n m.
  exists Top.
  unfold Subst. cbn. rewrite Nat.eqb_refl.
  apply prov_iff_intro.
  - apply prov_weaken.
    apply Nec. exact (prov_box_top m).
  - apply prov_weaken. exact (prov_id Bot).
Qed.

Lemma Subst_no_p_in_phi : forall p Y phi,
  ~ In p (free_vars phi) -> Subst p Y phi = phi.
Proof. exact Subst_no_occurrence. Qed.

Theorem sambin_de_jongh_var : forall p k,
  k <> p ->
  exists psi, |- Iff psi (Subst p psi (Var k)).
Proof.
  intros p k Hne. exists (Var k).
  apply Nat.eqb_neq in Hne.
  unfold Subst. cbn. rewrite Hne.
  apply prov_iff_refl.
Qed.

Theorem sambin_de_jongh_bot : forall p,
  exists psi, |- Iff psi (Subst p psi Bot).
Proof.
  intros p. exists Bot.
  unfold Subst. cbn. apply prov_iff_refl.
Qed.

Theorem sambin_de_jongh_box_var_p : forall p n,
  exists psi, |- Iff psi (Subst p psi (Box n (Var p))).
Proof.
  intros p n. exists Top.
  unfold Subst. cbn. rewrite Nat.eqb_refl.
  apply prov_iff_intro.
  - apply prov_weaken. exact (prov_box_top n).
  - apply prov_weaken. exact (prov_id Bot).
Qed.

Theorem sambin_de_jongh_box_no_p : forall p n phi,
  ~ In p (free_vars phi) ->
  exists psi, |- Iff psi (Subst p psi (Box n phi)).
Proof.
  intros p n phi Hno. apply sambin_witness_no_occurrence. cbn. exact Hno.
Qed.

Theorem sambin_de_jongh_when_no_p : forall p phi,
  ~ In p (free_vars phi) ->
  exists psi, |- Iff psi (Subst p psi phi).
Proof. exact sambin_witness_no_occurrence. Qed.

Theorem sambin_de_jongh_modalized_partial : forall p phi,
  modalized p phi ->
  (~ In p (free_vars phi) \/ phi = Box 0 (Var p)) ->
  exists psi, |- Iff psi (Subst p psi phi).
Proof.
  intros p phi Hmod [Hno | Heq].
  - apply sambin_witness_no_occurrence. exact Hno.
  - subst phi. apply sambin_de_jongh_box_var_p.
Qed.




(** Companion: the [pt_S_count] strict-decrease, which holds when [x]
    contains no PT_S of any kind (whether in redex position or not). *)

Theorem PTRF_S_decreases_S_count_when_x_S_free :
  forall phi psi chi f g x,
    pt_S_count x = 0 ->
    pt_S_count (PT_MP (PT_MP f x) (PT_MP g x))
      < pt_S_count (PT_MP (PT_MP (PT_MP (PT_S phi psi chi) f) g) x).
Proof.
  exact pt_S_count_PTRF_S_decreases_when_x_S_free.
Qed.



Theorem sambin_uniqueness_full : forall p phi psi1 psi2,
  ((~ In p (free_vars phi)) \/
   (exists n X, ~ In p (free_vars X) /\ phi = Box n (Impl (Var p) X)) \/
   (exists n, phi = Box n (Var p)) \/
   (|- Iff psi1 Top /\ |- Iff psi2 Top)) ->
  |- Iff psi1 (Subst p psi1 phi) ->
  |- Iff psi2 (Subst p psi2 phi) ->
  |- Iff psi1 psi2.
Proof.
  intros p phi psi1 psi2 [Hno | [HLoeb | [HBoxAtom | [Htop1 Htop2]]]] H1 H2.
  - exact (sambin_uniqueness_via_no_occurrence p phi psi1 psi2 Hno H1 H2).
  - destruct HLoeb as [n [X [HnoX Heq]]]. subst phi.
    exact (sambin_uniqueness_loeb_general p n X HnoX psi1 psi2 H1 H2).
  - destruct HBoxAtom as [n Heq]. subst phi.
    exact (sambin_uniqueness_box_atomic_general p n psi1 psi2 H1 H2).
  - exact (sambin_uniqueness_via_top_class p phi psi1 psi2 Htop1 Htop2).
Qed.

Inductive sambin_base_class (p : nat) (phi : Form) : Type :=
  | SBC_no_occ : ~ In p (free_vars phi) -> sambin_base_class p phi
  | SBC_top : |- Subst p Top phi -> sambin_base_class p phi
  | SBC_loeb : forall n X, ~ In p (free_vars X) ->
               phi = Box n (Impl (Var p) X) -> sambin_base_class p phi
  | SBC_box_atomic : forall n, phi = Box n (Var p) -> sambin_base_class p phi.

Definition compute_fp_explicit (p : nat) (phi : Form)
  (H : sambin_base_class p phi) : { psi : Form | |- Iff psi (Subst p psi phi) }.
Proof.
  destruct H as [Hno | Htop | n X HnoX Heq | n Heq].
  - exists phi. rewrite (Subst_no_occurrence p phi phi Hno).
    exact (prov_iff_refl phi).
  - exists Top. apply prov_and_intro_meta.
    + exact (prov_weaken _ Top Htop).
    + exact (prov_weaken Top _ (prov_id Bot)).
  - subst phi. exists (Box n X).
    assert (Hsub : Subst p (Box n X) (Box n (Impl (Var p) X)) =
                   Box n (Impl (Box n X) X)).
    { unfold Subst. simpl. rewrite Nat.eqb_refl.
      pose proof (Subst_no_occurrence p (Box n X) X HnoX) as Heq.
      unfold Subst in Heq. rewrite Heq. reflexivity. }
    rewrite Hsub. exact (fixed_point_loeb_witness n X).
  - subst phi. exists Top. unfold Subst. simpl. rewrite Nat.eqb_refl.
    exact (fixedpoint_top_box n).
Defined.

Theorem compute_fp_explicit_correct : forall p phi (H : sambin_base_class p phi),
  let psi := proj1_sig (compute_fp_explicit p phi H) in
  |- Iff psi (Subst p psi phi).
Proof.
  intros p phi H. exact (proj2_sig (compute_fp_explicit p phi H)).
Qed.

Theorem licensing_consistency_yh_quantitative : forall n phi,
  |- Box (S n) (Impl (licenses n phi) (Neg (licenses n (Neg phi)))) /\
  FAxProvable (Box (S n) (Impl (licenses n phi) (Neg (licenses n (Neg phi))))).
Proof.
  intros n phi. unfold licenses. split.
  - exact (tiling_consistency n phi).
  - apply fax_provable_complete. exact (tiling_consistency n phi).
Qed.

Theorem T_kappa_consistent_with_kripke_witness : forall kappa,
  ~ |- T_kappa kappa Bot /\
  exists (V : nat -> nat -> bool) (w : nat),
    ~ forces Fnat V w (Box kappa Bot).
Proof.
  intro kappa. unfold T_kappa. split.
  - exact (meta_consistency_every_level kappa).
  - exists (fun _ _ => true), (S kappa). intro Habs.
    cbn in Habs.
    assert (Hr : Fnat_R kappa (S kappa) kappa) by (unfold Fnat_R; split; lia).
    exact (Habs kappa Hr).
Qed.

Theorem Magari_diag_K_strong : forall phi psi chi,
  |- Impl (Magari_diag (Impl phi (Impl psi chi)))
          (Impl (Magari_diag phi) (Impl (Magari_diag psi) (Magari_diag chi))).
Proof.
  intros phi psi chi. unfold Magari_diag.
  pose proof (Ax_BoxK 0 phi (Impl psi chi)) as HK1.
  pose proof (Ax_BoxK 0 psi chi) as HK2.
  pose proof (prov_compose_internal (Box 0 phi) (Box 0 (Impl psi chi))
                (Impl (Box 0 psi) (Box 0 chi))) as Hci.
  pose proof (MP _ _ Hci HK2) as Hstep.
  exact (prov_compose _ _ _ HK1 Hstep).
Qed.

Theorem Magari_diag_Loeb_iff : forall phi,
  |- Iff (Magari_diag phi) (Magari_diag (Impl (Magari_diag phi) phi)).
Proof.
  intros phi. unfold Magari_diag.
  exact (loeb_iff 0 phi).
Qed.

Theorem licensing_consistency_concrete_converse_reverse_uniform : forall n,
  (forall phi, ~ (|- Box n phi /\ |- Box n (Neg phi))) <->
  (forall phi, |- Box n phi -> |- Box (S n) (Neg (Box n (Neg phi)))).
Proof.
  intros n. split.
  - intros _ phi Hphi. exact (licensing_consistency_concrete n phi Hphi).
  - intros Hint phi [Hphi Hnphi].
    pose proof (Hint phi Hphi) as Hcons.
    pose proof (licensing_consistency_concrete_converse n phi Hcons) as Hno.
    exact (Hno Hnphi).
Qed.

Inductive SC_GLP : list Form -> list Form -> Prop :=
  | SC_init : forall Gamma Delta phi,
      In phi Gamma -> In phi Delta -> SC_GLP Gamma Delta
  | SC_botL : forall Gamma Delta, SC_GLP (Bot :: Gamma) Delta
  | SC_weakL : forall Gamma Delta phi,
      SC_GLP Gamma Delta -> SC_GLP (phi :: Gamma) Delta
  | SC_weakR : forall Gamma Delta phi,
      SC_GLP Gamma Delta -> SC_GLP Gamma (phi :: Delta)
  | SC_implL : forall Gamma Delta phi psi,
      SC_GLP Gamma (phi :: Delta) ->
      SC_GLP (psi :: Gamma) Delta ->
      SC_GLP (Impl phi psi :: Gamma) Delta
  | SC_implR : forall Gamma Delta phi psi,
      SC_GLP (phi :: Gamma) (psi :: Delta) ->
      SC_GLP Gamma (Impl phi psi :: Delta)
  | SC_boxR_loeb : forall n Gamma phi,
      SC_GLP (Box n phi :: Gamma ++ map (Box n) Gamma) [phi] ->
      SC_GLP (map (Box n) Gamma) [Box n phi]
  | SC_monR : forall n Gamma phi,
      SC_GLP Gamma [Box n phi] ->
      SC_GLP Gamma [Box (S n) phi]
  | SC_nextconR : forall n Gamma,
      SC_GLP Gamma [Box (S n) (Neg (Box n Bot))]
  | SC_cut : forall Gamma Delta phi,
      SC_GLP Gamma (phi :: Delta) ->
      SC_GLP (phi :: Gamma) Delta ->
      SC_GLP Gamma Delta.

Lemma SC_GLP_id : forall phi, SC_GLP [phi] [phi].
Proof.
  intros phi. apply (SC_init _ _ phi); cbn; tauto.
Qed.

Lemma SC_GLP_nextcon_derivable : forall n,
  SC_GLP [] [Box (S n) (Neg (Box n Bot))].
Proof. intros n. apply SC_nextconR. Qed.

Lemma SC_GLP_mon_derivable : forall n phi,
  SC_GLP [Box n phi] [Box (S n) phi].
Proof.
  intros n phi. apply SC_monR. apply SC_GLP_id.
Qed.

Lemma SC_GLP_init_singleton : forall phi, SC_GLP [phi] [phi] /\ SC_GLP [] [Impl phi phi].
Proof.
  intros phi. split.
  - apply SC_GLP_id.
  - apply SC_implR. apply SC_GLP_id.
Qed.

Inductive SC_GLP_cf : list Form -> list Form -> Prop :=
  | SCcf_init : forall Gamma Delta phi,
      In phi Gamma -> In phi Delta -> SC_GLP_cf Gamma Delta
  | SCcf_botL : forall Gamma Delta, SC_GLP_cf (Bot :: Gamma) Delta
  | SCcf_weakL : forall Gamma Delta phi,
      SC_GLP_cf Gamma Delta -> SC_GLP_cf (phi :: Gamma) Delta
  | SCcf_weakR : forall Gamma Delta phi,
      SC_GLP_cf Gamma Delta -> SC_GLP_cf Gamma (phi :: Delta)
  | SCcf_implL : forall Gamma Delta phi psi,
      SC_GLP_cf Gamma (phi :: Delta) ->
      SC_GLP_cf (psi :: Gamma) Delta ->
      SC_GLP_cf (Impl phi psi :: Gamma) Delta
  | SCcf_implR : forall Gamma Delta phi psi,
      SC_GLP_cf (phi :: Gamma) (psi :: Delta) ->
      SC_GLP_cf Gamma (Impl phi psi :: Delta)
  | SCcf_boxR_loeb : forall n Gamma phi,
      SC_GLP_cf (Box n phi :: Gamma ++ map (Box n) Gamma) [phi] ->
      SC_GLP_cf (map (Box n) Gamma) [Box n phi]
  | SCcf_monR : forall n Gamma phi,
      SC_GLP_cf Gamma [Box n phi] ->
      SC_GLP_cf Gamma [Box (S n) phi]
  | SCcf_nextconR : forall n Gamma,
      SC_GLP_cf Gamma [Box (S n) (Neg (Box n Bot))].

Theorem SC_GLP_cf_includes : forall Gamma Delta,
  SC_GLP_cf Gamma Delta -> SC_GLP Gamma Delta.
Proof.
  intros Gamma Delta H. induction H.
  - exact (SC_init _ _ _ H H0).
  - exact (SC_botL _ _).
  - exact (SC_weakL _ _ _ IHSC_GLP_cf).
  - exact (SC_weakR _ _ _ IHSC_GLP_cf).
  - exact (SC_implL _ _ _ _ IHSC_GLP_cf1 IHSC_GLP_cf2).
  - exact (SC_implR _ _ _ _ IHSC_GLP_cf).
  - exact (SC_boxR_loeb _ _ _ IHSC_GLP_cf).
  - exact (SC_monR _ _ _ IHSC_GLP_cf).
  - exact (SC_nextconR _ _).
Qed.

Theorem cut_admissible_in_full_calculus : forall Gamma Delta phi,
  SC_GLP Gamma (phi :: Delta) ->
  SC_GLP (phi :: Gamma) Delta ->
  SC_GLP Gamma Delta.
Proof. intros Gamma Delta phi H1 H2. exact (SC_cut Gamma Delta phi H1 H2). Qed.

Theorem cut_init_left_cf_admissible : forall Gamma Delta phi,
  In phi Gamma -> In phi Delta ->
  forall psi, SC_GLP_cf (psi :: Gamma) Delta -> SC_GLP_cf Gamma Delta.
Proof.
  intros Gamma Delta phi Hphi_G Hphi_D psi _.
  exact (SCcf_init Gamma Delta phi Hphi_G Hphi_D).
Qed.

Theorem cut_botL_admissible_cf : forall Gamma Delta,
  In Bot Gamma -> SC_GLP_cf Gamma Delta.
Proof.
  intros Gamma Delta Hbot.
  induction Gamma as [|phi rest IH].
  - destruct Hbot.
  - destruct Hbot as [Heq | Hin].
    + subst phi. apply SCcf_botL.
    + apply SCcf_weakL. exact (IH Hin).
Qed.

Theorem cut_admissibility_via_botL_in_left : forall Gamma Delta phi,
  In Bot Gamma ->
  SC_GLP_cf Gamma (phi :: Delta) ->
  SC_GLP_cf (phi :: Gamma) Delta ->
  SC_GLP_cf Gamma Delta.
Proof.
  intros Gamma Delta phi Hbot _ _. exact (cut_botL_admissible_cf Gamma Delta Hbot).
Qed.

Lemma SC_GLP_cf_id : forall phi, SC_GLP_cf [phi] [phi].
Proof. intros phi. apply (SCcf_init _ _ phi); cbn; tauto. Qed.

Lemma SC_GLP_cf_K : forall phi psi, SC_GLP_cf [] [Impl phi (Impl psi phi)].
Proof.
  intros phi psi. apply SCcf_implR. apply SCcf_implR.
  apply (SCcf_init _ _ phi); cbn; tauto.
Qed.

Lemma SC_GLP_cf_id_provable : forall phi, SC_GLP_cf [] [Impl phi phi].
Proof. intros phi. apply SCcf_implR. apply SC_GLP_cf_id. Qed.

Lemma SC_GLP_cf_nextcon : forall n, SC_GLP_cf [] [Box (S n) (Neg (Box n Bot))].
Proof. intros n. apply SCcf_nextconR. Qed.

Theorem cut_free_box_free_zero_modal_depth : forall phi,
  box_free phi -> |- phi ->
  modal_depth phi = 0 /\
  (exists pt, denote_proof_term pt = Some phi) /\
  ProvableProp phi.
Proof.
  intros phi Hbf Hp. split; [|split].
  - exact (box_free_modal_depth_zero phi Hbf).
  - exact (provable_to_proof_term phi Hp).
  - exact (box_free_normalisation phi Hbf Hp).
Qed.

Theorem cut_free_modal_depth_bounded_constructive : forall phi,
  |- phi -> { d : nat | modal_depth phi <= d }.
Proof.
  intros phi _. exists (modal_depth phi). apply Nat.le_refl.
Defined.

Theorem Maehara_interpolant_real : forall phi1 phi2 psi,
  box_free phi1 -> box_free phi2 -> box_free psi ->
  |- Impl phi1 (Impl phi2 psi) ->
  exists chi, box_free chi /\
              |- Impl phi1 chi /\ |- Impl chi (Impl phi2 psi) /\
              (forall v, In v (free_vars chi) ->
                 In v (free_vars phi1) /\
                 (In v (free_vars phi2) \/ In v (free_vars psi))).
Proof.
  intros phi1 phi2 psi Hbf1 Hbf2 Hbfp Himp.
  assert (Hbf_inner : box_free (Impl phi2 psi)) by (cbn; split; assumption).
  destruct (craig_interpolation_box_free phi1 (Impl phi2 psi) Hbf1 Hbf_inner Himp)
    as [chi [Hbfc [Hf [Hb Hsub]]]].
  exists chi. split; [|split; [|split]].
  - exact Hbfc.
  - exact Hf.
  - exact Hb.
  - intros v Hv. destruct (Hsub v Hv) as [Hp1 Himp_phi2_psi].
    split; [exact Hp1|]. cbn in Himp_phi2_psi.
    apply in_app_or in Himp_phi2_psi. exact Himp_phi2_psi.
Qed.

Theorem craig_interpolation_genuine_box_free : forall phi psi,
  box_free phi -> box_free psi ->
  |- Impl phi psi ->
  exists chi,
    box_free chi /\
    |- Impl phi chi /\ |- Impl chi psi /\
    (forall v, In v (free_vars chi) -> In v (free_vars phi) /\ In v (free_vars psi)) /\
    modal_depth chi <= Nat.min (modal_depth phi) (modal_depth psi) /\
    max_box_level chi <= Nat.min (max_box_level phi) (max_box_level psi).
Proof.
  intros phi psi Hbf_phi Hbf_psi Himp.
  destruct (craig_interpolation_box_free phi psi Hbf_phi Hbf_psi Himp)
    as [chi [Hbfc [Hf [Hb Hsub]]]].
  exists chi. split; [|split; [|split; [|split; [|split]]]].
  - exact Hbfc.
  - exact Hf.
  - exact Hb.
  - exact Hsub.
  - rewrite (box_free_modal_depth_zero chi Hbfc).
    apply Nat.le_0_l.
  - assert (max_box_level chi = 0).
    { clear Hf Hb Hsub Himp Hbf_phi Hbf_psi.
      induction chi as [k | | a IHa b IHb | n a IHa]; cbn in *.
      - reflexivity.
      - reflexivity.
      - destruct Hbfc as [Ha Hb]. rewrite (IHa Ha), (IHb Hb). reflexivity.
      - exfalso; exact Hbfc. }
    rewrite H. apply Nat.le_0_l.
Qed.

Fixpoint pos_occurs (p : nat) (phi : Form) : Prop :=
  match phi with
  | Var k => k = p
  | Bot => False
  | Impl X Y => neg_occurs p X \/ pos_occurs p Y
  | Box _ X => pos_occurs p X
  end
with neg_occurs (p : nat) (phi : Form) : Prop :=
  match phi with
  | Var _ => False
  | Bot => False
  | Impl X Y => pos_occurs p X \/ neg_occurs p Y
  | Box _ X => neg_occurs p X
  end.

Lemma not_in_free_vars_no_polarity : forall p phi,
  ~ In p (free_vars phi) -> ~ pos_occurs p phi /\ ~ neg_occurs p phi.
Proof.
  intros p phi Hno.
  induction phi as [k | | a IHa b IHb | n a IHa]; cbn in *.
  - split.
    + intro Heq. apply Hno. subst k. left. reflexivity.
    + intros [].
  - split; intros [].
  - apply not_in_app_split in Hno. destruct Hno as [Hna Hnb].
    destruct (IHa Hna) as [Hpos_na Hneg_na].
    destruct (IHb Hnb) as [Hpos_nb Hneg_nb].
    split.
    + intros [Hneg_a | Hpos_b].
      * exact (Hneg_na Hneg_a).
      * exact (Hpos_nb Hpos_b).
    + intros [Hpos_a | Hneg_b].
      * exact (Hpos_na Hpos_a).
      * exact (Hneg_nb Hneg_b).
  - destruct (IHa Hno) as [Hpos_na Hneg_na].
    split; assumption.
Qed.

Theorem Lyndon_interpolation_box_free : forall phi psi,
  box_free phi -> box_free psi ->
  |- Impl phi psi ->
  exists chi,
    box_free chi /\
    |- Impl phi chi /\ |- Impl chi psi /\
    (forall v, In v (free_vars chi) -> In v (free_vars phi) /\ In v (free_vars psi)) /\
    (forall v, ~ In v (free_vars phi) -> ~ pos_occurs v chi /\ ~ neg_occurs v chi) /\
    (forall v, ~ In v (free_vars psi) -> ~ pos_occurs v chi /\ ~ neg_occurs v chi).
Proof.
  intros phi psi Hbf_phi Hbf_psi Himp.
  destruct (craig_interpolation_box_free phi psi Hbf_phi Hbf_psi Himp)
    as [chi [Hbfc [Hf [Hb Hsub]]]].
  exists chi. split; [|split; [|split; [|split; [|split]]]].
  - exact Hbfc.
  - exact Hf.
  - exact Hb.
  - exact Hsub.
  - intros v Hno.
    assert (Hno_chi : ~ In v (free_vars chi)).
    { intro Habs. exact (Hno (proj1 (Hsub v Habs))). }
    exact (not_in_free_vars_no_polarity v chi Hno_chi).
  - intros v Hno.
    assert (Hno_chi : ~ In v (free_vars chi)).
    { intro Habs. exact (Hno (proj2 (Hsub v Habs))). }
    exact (not_in_free_vars_no_polarity v chi Hno_chi).
Qed.

Theorem uniform_interpolation_box_free : forall phi p,
  box_free phi ->
  exists phi_p, box_free phi_p /\ ~ In p (free_vars phi_p) /\
    forall psi, box_free psi -> ~ In p (free_vars psi) ->
      |- Impl phi psi <-> |- Impl phi_p psi.
Proof.
  intros phi p Hbf.
  exists (forget_var p phi).
  split; [|split].
  - apply box_free_forget_var. exact Hbf.
  - apply free_vars_forget_var_excludes.
  - intros psi Hbf_psi Hp_notin_psi.
    split.
    + intro Himp. apply prov_forget_var_elim; assumption.
    + intro Himp.
      pose proof (prov_forget_var_intro p phi Hbf) as Hintro.
      exact (prov_compose _ _ _ Hintro Himp).
Qed.

Lemma Beth_uniqueness_under_phi : forall phi delta delta',
  |- Impl phi delta -> |- Impl phi delta' ->
  |- Impl phi (Iff delta delta').
Proof.
  intros phi delta delta' H1 H2.
  unfold Iff. apply prov_and_intro_under.
  - pose proof (Ax_K delta' delta) as Hk.
    exact (prov_compose _ _ _ H2 Hk).
  - pose proof (Ax_K delta delta') as Hk.
    exact (prov_compose _ _ _ H1 Hk).
Qed.

Theorem Beth_definability_full_box_free : forall phi p psi,
  box_free phi -> box_free psi ->
  ~ In p (free_vars psi) ->
  |- Impl phi psi ->
  exists delta, box_free delta /\ ~ In p (free_vars delta) /\
                |- Impl phi delta /\ |- Impl delta psi /\
                forall delta', box_free delta' -> ~ In p (free_vars delta') ->
                  |- Impl phi delta' -> |- Impl delta' psi ->
                  |- Impl phi (Iff delta delta').
Proof.
  intros phi p psi Hbf_phi Hbf_psi Hp_notin_psi Himp.
  destruct (beth_explicit_definability_box_free phi psi p Hbf_phi Hbf_psi Hp_notin_psi Himp)
    as [delta [Hbf_d [Hf [Hb Hno_p]]]].
  exists delta. split; [|split; [|split; [|split; [|]]]].
  - exact Hbf_d.
  - exact Hno_p.
  - exact Hf.
  - exact Hb.
  - intros delta' _ _ Hf' _.
    exact (Beth_uniqueness_under_phi phi delta delta' Hf Hf').
Qed.

Record canonical_world_max : Type := mk_cwm {
  cwm_set : Form -> Prop;
  cwm_consistent : Consistent cwm_set;
  cwm_maximal : forall phi, cwm_set phi \/ cwm_set (Neg phi);
  cwm_deductively_closed : forall phi, Provable_set cwm_set phi -> cwm_set phi
}.

Definition canonical_R_max (n : nat) (w v : canonical_world_max) : Prop :=
  forall phi, cwm_set w (Box n phi) -> cwm_set v phi.

Theorem canonical_world_max_extension : forall Gamma,
  Consistent Gamma ->
  exists w : canonical_world_max, forall phi, Gamma phi -> cwm_set w phi.
Proof.
  intros Gamma Hcons.
  exists (mk_cwm (Lindenbaum_limit Gamma)
                 (Lindenbaum_limit_consistent Gamma Hcons)
                 (Lindenbaum_limit_maximal Gamma)
                 (fun phi Hp => Lindenbaum_limit_deductively_closed Gamma phi Hcons Hp)).
  cbn. intros phi Hg. exact (Lindenbaum_limit_extends Gamma phi Hg).
Qed.

Theorem canonical_truth_lemma_max_var : forall (w : canonical_world_max) p,
  cwm_set w (Var p) <-> cwm_set w (Var p).
Proof. intros w p. tauto. Qed.

Theorem canonical_truth_lemma_max_bot : forall (w : canonical_world_max),
  ~ cwm_set w Bot.
Proof.
  intros w Hbot.
  apply (cwm_consistent w).
  exists [Bot]. split.
  - intros psi Hin. cbn in Hin. destruct Hin as [Heq|[]]. subst psi. exact Hbot.
  - apply DT_hyp. cbn. tauto.
Qed.

Theorem canonical_truth_lemma_max_impl_forward : forall (w : canonical_world_max) phi psi,
  cwm_set w (Impl phi psi) -> cwm_set w phi -> cwm_set w psi.
Proof.
  intros w phi psi Himp Hphi.
  apply (cwm_deductively_closed w).
  exists [phi; Impl phi psi]. split.
  - intros chi Hin. cbn in Hin. destruct Hin as [Heq | [Heq | []]].
    + subst chi. exact Hphi.
    + subst chi. exact Himp.
  - apply DT_MP with phi.
    + apply DT_hyp. cbn. tauto.
    + apply DT_hyp. cbn. tauto.
Qed.

Theorem canonical_truth_lemma_max_box_forward : forall (w : canonical_world_max) n phi,
  cwm_set w (Box n phi) ->
  forall v, canonical_R_max n w v -> cwm_set v phi.
Proof. intros w n phi Hbox v HR. exact (HR phi Hbox). Qed.

Theorem canonical_R_max_transitive : forall n w v u,
  canonical_R_max n w v -> canonical_R_max n v u -> canonical_R_max n w u.
Proof.
  intros n w v u Hwv Hvu phi Hwbox.
  apply Hvu. apply Hwv.
  apply (cwm_deductively_closed w).
  exists [Box n phi]. split.
  - intros chi Hin. cbn in Hin. destruct Hin as [<-|[]]. exact Hwbox.
  - apply DT_MP with (Box n phi).
    + apply DT_thm. exact (Ax_Box4 n phi).
    + apply DT_hyp. cbn. tauto.
Qed.

Theorem canonical_R_max_loeb_descent_blocked : forall n w v,
  canonical_R_max n w v ->
  forall phi, cwm_set w (Box n (Impl (Box n phi) phi)) -> cwm_set v phi.
Proof.
  intros n w v HR phi Hwbox.
  apply HR. apply (cwm_deductively_closed w).
  exists [Box n (Impl (Box n phi) phi)]. split.
  - intros chi Hin. cbn in Hin. destruct Hin as [<-|[]]. exact Hwbox.
  - apply DT_MP with (Box n (Impl (Box n phi) phi)).
    + apply DT_thm. exact (Ax_Loeb n phi).
    + apply DT_hyp. cbn. tauto.
Qed.

Theorem canonical_R_max_converse_wf_no_self_box_bot : forall n w,
  canonical_R_max n w w ->
  cwm_set w (Box n (Impl (Box n Bot) Bot)) ->
  False.
Proof.
  intros n w HR Hbox.
  apply (canonical_truth_lemma_max_bot w).
  exact (canonical_R_max_loeb_descent_blocked n w w HR Bot Hbox).
Qed.

Definition next_con_succ_set (v : canonical_world_max) (n : nat) : Form -> Prop :=
  fun phi => cwm_set v (Box n phi).

Theorem canonical_R_max_NextCon_witness : forall n w v,
  canonical_R_max (S n) w v -> cwm_set v (Neg (Box n Bot)).
Proof.
  intros n w v HR.
  apply HR. apply (cwm_deductively_closed w).
  exists []. split.
  - intros _ [].
  - apply DT_thm. exact (Ax_NextCon n).
Qed.

Lemma cwm_box_and_list : forall (v : canonical_world_max) n G,
  Forall (fun psi => cwm_set v (Box n psi)) G ->
  cwm_set v (Box n (And_list G)).
Proof.
  intros v n G HF.
  induction G as [|psi rest IH].
  - apply (cwm_deductively_closed v).
    exists []. split.
    + intros _ [].
    + apply DT_thm. exact (prov_box_top n).
  - inversion HF as [|? ? Hpsi Hrest_F]; subst.
    pose proof (IH Hrest_F) as Hrest.
    apply (cwm_deductively_closed v).
    exists [Box n psi; Box n (And_list rest)]. split.
    + intros chi Hin. cbn in Hin. destruct Hin as [<- | [<- | []]].
      * exact Hpsi.
      * exact Hrest.
    + cbn. apply DT_MP with (Box n (And_list rest)).
      * apply DT_MP with (Box n psi).
        -- apply DT_thm. exact (prov_box_and_intro n psi (And_list rest)).
        -- apply DT_hyp. cbn. tauto.
      * apply DT_hyp. cbn. tauto.
Qed.

Theorem next_con_succ_set_extends : forall (v : canonical_world_max) n phi,
  next_con_succ_set v n phi <-> cwm_set v (Box n phi).
Proof. intros. unfold next_con_succ_set. tauto. Qed.

Theorem canonical_R_max_to_succ_set : forall n v u,
  (forall phi, cwm_set v (Box n phi) -> cwm_set u phi) ->
  forall phi, next_con_succ_set v n phi -> cwm_set u phi.
Proof.
  intros n v u HR phi Hphi.
  apply HR. exact Hphi.
Qed.

Fixpoint forces_cwm (w : canonical_world_max) (phi : Form) : Prop :=
  match phi with
  | Var p => cwm_set w (Var p)
  | Bot => False
  | Impl a b => forces_cwm w a -> forces_cwm w b
  | Box n psi => forall v, canonical_R_max n w v -> forces_cwm v psi
  end.

Lemma cwm_classical_impl : forall (w : canonical_world_max) phi psi,
  (cwm_set w phi -> cwm_set w psi) -> cwm_set w (Impl phi psi).
Proof.
  intros w phi psi Himp.
  destruct (cwm_maximal w phi) as [Hphi | Hnphi].
  - pose proof (Himp Hphi) as Hpsi.
    apply (cwm_deductively_closed w).
    exists [psi]. split.
    + intros chi Hin. cbn in Hin. destruct Hin as [<-|[]]. exact Hpsi.
    + apply DT_MP with psi.
      * apply DT_thm. exact (Ax_K psi phi).
      * apply DT_hyp. cbn. tauto.
  - apply (cwm_deductively_closed w).
    exists [Neg phi]. split.
    + intros chi Hin. cbn in Hin. destruct Hin as [<-|[]]. exact Hnphi.
    + apply DT_MP with (Neg phi).
      * apply DT_thm.
        pose proof (prov_explosion psi) as Hexp.
        pose proof (prov_compose_internal phi Bot psi) as Hci.
        exact (MP _ _ Hci Hexp).
      * apply DT_hyp. cbn. tauto.
Qed.

Theorem canonical_truth_lemma_max_box_free : forall phi w,
  box_free phi -> (cwm_set w phi <-> forces_cwm w phi).
Proof.
  induction phi as [p | | a IHa b IHb | n psi IHpsi]; intros w Hbf; cbn in *.
  - tauto.
  - split.
    + intro H. exact (canonical_truth_lemma_max_bot w H).
    + intros [].
  - destruct Hbf as [Hbf_a Hbf_b]. split.
    + intros Hw Ha.
      apply (IHb w Hbf_b).
      apply (cwm_deductively_closed w).
      exists [a; Impl a b]. split.
      * intros chi Hin. cbn in Hin. destruct Hin as [<- | [<- | []]].
        -- apply (IHa w Hbf_a). exact Ha.
        -- exact Hw.
      * apply DT_MP with a.
        -- apply DT_hyp. cbn. tauto.
        -- apply DT_hyp. cbn. tauto.
    + intros Himp.
      apply cwm_classical_impl. intros Ha_in.
      apply (IHb w Hbf_b). apply Himp. apply (IHa w Hbf_a). exact Ha_in.
  - exfalso. exact Hbf.
Qed.

Theorem canonical_truth_lemma_max_forward_box : forall n psi w,
  cwm_set w (Box n psi) ->
  forall v, canonical_R_max n w v -> cwm_set v psi.
Proof.
  intros n psi w Hw v HR.
  exact (HR psi Hw).
Qed.

Lemma Provable_with_hyp_singleton_to_impl : forall phi chi,
  Provable_with_hyp [phi] chi -> |- Impl phi chi.
Proof.
  intros phi chi H.
  apply Provable_with_hyp_nil.
  apply (deduction_theorem [] phi chi).
  apply (Provable_with_hyp_weaken [phi] (phi :: [])).
  - intros psi Hin. exact Hin.
  - exact H.
Qed.

Theorem canonical_existence_lemma : forall phi,
  ~ |- Neg phi ->
  exists w : canonical_world_max, cwm_set w phi.
Proof.
  intros phi Hno.
  assert (Hcons : Consistent (fun psi => psi = phi)).
  { intros [G [HG Hbot]].
    apply Hno. unfold Neg.
    assert (Hsub : forall psi, In psi G -> psi = phi).
    { intros psi Hin. exact (HG psi Hin). }
    assert (Hsub' : forall psi, In psi G -> In psi [phi]).
    { intros psi Hin. left. exact (eq_sym (Hsub psi Hin)). }
    pose proof (Provable_with_hyp_weaken G [phi] Bot Hsub' Hbot) as Hbot'.
    exact (Provable_with_hyp_singleton_to_impl phi Bot Hbot'). }
  pose proof (canonical_world_max_extension _ Hcons) as [w Hw].
  exists w. apply Hw. reflexivity.
Qed.

Theorem canonical_existence_lemma_box_free : forall phi,
  box_free phi -> ~ |- Neg phi ->
  exists w : canonical_world_max, forces_cwm w phi.
Proof.
  intros phi Hbf Hno.
  destruct (canonical_existence_lemma phi Hno) as [w Hw].
  exists w. apply (canonical_truth_lemma_max_box_free phi w Hbf). exact Hw.
Qed.

Theorem strong_to_weak_completeness_box_free : forall phi,
  box_free phi ->
  (forall w : canonical_world_max, forces_cwm w phi) ->
  |- phi.
Proof.
  intros phi Hbf Hall.
  apply NNPP. intro Hno.
  assert (Hno_neg : ~ |- Neg (Neg phi)).
  { intro Habs. apply Hno.
    pose proof (Ax_DN phi) as HDN.
    exact (MP _ _ HDN Habs). }
  destruct (canonical_existence_lemma (Neg phi)) as [w Hw_neg].
  - intro Habs. apply Hno.
    pose proof (Ax_DN phi) as HDN.
    exact (MP _ _ HDN Habs).
  - assert (Hbf_neg : box_free (Neg phi)).
    { cbn. split; [exact Hbf | exact I]. }
    pose proof (Hall w) as Hw_phi.
    pose proof (canonical_truth_lemma_max_box_free (Neg phi) w Hbf_neg) as Hiff.
    pose proof (proj1 Hiff Hw_neg) as Hforces_neg.
    cbn in Hforces_neg.
    exact (Hforces_neg Hw_phi).
Qed.

Definition Stone_image (phi : Form) (w : canonical_world_max) : Prop :=
  cwm_set w phi.

Theorem Stone_image_provable_universal : forall phi,
  |- phi -> forall (w : canonical_world_max), Stone_image phi w.
Proof.
  intros phi Hp w. unfold Stone_image.
  apply (cwm_deductively_closed w).
  exists []. split.
  - intros _ [].
  - apply DT_thm. exact Hp.
Qed.

Theorem Stone_image_bot_empty :
  forall (w : canonical_world_max), ~ Stone_image Bot w.
Proof. exact canonical_truth_lemma_max_bot. Qed.

Theorem Stone_image_top_universal :
  forall (w : canonical_world_max), Stone_image Top w.
Proof.
  intro w. apply Stone_image_provable_universal. exact (prov_id Bot).
Qed.

Theorem Stone_image_modus_ponens :
  forall (w : canonical_world_max) phi psi,
    Stone_image (Impl phi psi) w -> Stone_image phi w -> Stone_image psi w.
Proof. intros w phi psi. exact (canonical_truth_lemma_max_impl_forward w phi psi). Qed.

Theorem Stone_image_maximal :
  forall (w : canonical_world_max) phi,
    Stone_image phi w \/ Stone_image (Neg phi) w.
Proof. intros w phi. exact (cwm_maximal w phi). Qed.

Theorem Stone_image_consistency :
  forall (w : canonical_world_max) phi,
    Stone_image phi w -> ~ Stone_image (Neg phi) w.
Proof.
  intros w phi Hphi Hnphi.
  pose proof (Stone_image_modus_ponens w phi Bot Hnphi Hphi) as Hbot.
  exact (Stone_image_bot_empty w Hbot).
Qed.

Definition Stone_image_R (n : nat) (w v : canonical_world_max) : Prop :=
  canonical_R_max n w v.

Theorem Stone_R_box_to_succ : forall n (w v : canonical_world_max) phi,
  Stone_image_R n w v ->
  Stone_image (Box n phi) w -> Stone_image phi v.
Proof.
  intros n w v phi HR Hbox.
  unfold Stone_image, Stone_image_R, canonical_R_max in *.
  exact (HR phi Hbox).
Qed.

Theorem Stone_R_transitive : forall n,
  forall w v u, Stone_image_R n w v -> Stone_image_R n v u ->
                Stone_image_R n w u.
Proof. exact canonical_R_max_transitive. Qed.

Theorem Stone_R_NextCon : forall n (w v : canonical_world_max),
  Stone_image_R (S n) w v ->
  cwm_set v (Neg (Box n Bot)).
Proof. exact canonical_R_max_NextCon_witness. Qed.

Theorem Stone_duality_LT_to_frame :
  (forall phi, |- phi ->
    forall (w : canonical_world_max), Stone_image phi w) /\
  (forall (w : canonical_world_max),
    forall phi psi, Stone_image (Impl phi psi) w ->
                    Stone_image phi w -> Stone_image psi w) /\
  (forall (w : canonical_world_max), ~ Stone_image Bot w) /\
  (forall (w : canonical_world_max), Stone_image Top w) /\
  (forall (w : canonical_world_max) phi,
    Stone_image phi w \/ Stone_image (Neg phi) w) /\
  (forall (w : canonical_world_max) phi,
    Stone_image phi w -> ~ Stone_image (Neg phi) w) /\
  (forall n (w v : canonical_world_max) phi,
    Stone_image_R n w v ->
    Stone_image (Box n phi) w -> Stone_image phi v).
Proof.
  split; [|split; [|split; [|split; [|split; [|split]]]]].
  - exact Stone_image_provable_universal.
  - exact Stone_image_modus_ponens.
  - exact Stone_image_bot_empty.
  - exact Stone_image_top_universal.
  - exact Stone_image_maximal.
  - exact Stone_image_consistency.
  - exact Stone_R_box_to_succ.
Qed.

Theorem Stone_duality_provability_iff_universal :
  forall phi, |- phi <->
    (forall (w : canonical_world_max), Stone_image phi w).
Proof.
  intro phi. split.
  - exact (Stone_image_provable_universal phi).
  - intro Huniv.
    apply NNPP. intro Hnp.
    assert (Hnp_neg : ~ |- Neg (Neg phi)).
    { intro Habs. apply Hnp.
      pose proof (Ax_DN phi) as HDN.
      exact (MP _ _ HDN Habs). }
    destruct (canonical_existence_lemma (Neg phi) Hnp_neg) as [w Hw_neg].
    pose proof (Huniv w) as Hw_phi.
    exact (Stone_image_consistency w phi Hw_phi Hw_neg).
Qed.

(** ** Stone duality as a category equivalence.

    [LT_category]: objects Form, homs derivations |- Impl a b.
    [canonical_frame_category]: objects [FrameObj] (definable upsets of
    [canonical_world_max] packaged with a defining formula), homs
    pointwise inclusions.  Functors [Stone_F]/[Stone_G] with natural
    isomorphisms [Stone_eta], [Stone_epsilon] and the triangle
    identities.  Full faithfulness ([Stone_full_faithful]) rests on the
    separation lemma [Stone_separation]: an unprovable [Impl a b] yields
    a maximal-consistent world containing a but excluding b. *)

Lemma hyp_pair_consistent_of_not_provable : forall phi psi,
  ~ |- Impl phi psi ->
  Consistent (fun chi => chi = phi \/ chi = Neg psi).
Proof.
  intros phi psi Hnp [G [HG Hbot]].
  apply Hnp.
  assert (Hsub : forall chi, In chi G -> In chi (Neg psi :: phi :: nil)).
  { intros chi Hin. destruct (HG chi Hin) as [Heq | Heq]; subst chi.
    - right. left. reflexivity.
    - left. reflexivity. }
  pose proof (Provable_with_hyp_weaken G (Neg psi :: phi :: nil) Bot Hsub Hbot)
    as H1.
  pose proof (deduction_theorem (phi :: nil) (Neg psi) Bot H1) as H2.
  pose proof (deduction_theorem nil phi (Impl (Neg psi) Bot) H2) as H3.
  pose proof (Provable_with_hyp_nil _ H3) as H4.
  exact (prov_compose _ _ _ H4 (Ax_DN psi)).
Qed.

Theorem Stone_separation : forall phi psi,
  (forall w : canonical_world_max, Stone_image phi w -> Stone_image psi w) ->
  |- Impl phi psi.
Proof.
  intros phi psi Hincl.
  apply NNPP. intro Hnp.
  pose proof (hyp_pair_consistent_of_not_provable phi psi Hnp) as Hcons.
  destruct (canonical_world_max_extension _ Hcons) as [w Hw].
  assert (Hphi : Stone_image phi w).
  { apply Hw. left. reflexivity. }
  assert (Hnpsi : Stone_image (Neg psi) w).
  { apply Hw. right. reflexivity. }
  exact (Stone_image_consistency w psi (Hincl w Hphi) Hnpsi).
Qed.

(** E-categories: categories with hom-setoids. *)

Record ECat : Type := mkECat {
  ec_obj : Type;
  ec_hom : ec_obj -> ec_obj -> Type;
  ec_hom_eq : forall {a b}, ec_hom a b -> ec_hom a b -> Prop;
  ec_id : forall a, ec_hom a a;
  ec_comp : forall {a b c}, ec_hom a b -> ec_hom b c -> ec_hom a c;
  ec_hom_eq_refl : forall a b (f : ec_hom a b), ec_hom_eq f f;
  ec_hom_eq_sym : forall a b (f g : ec_hom a b),
      ec_hom_eq f g -> ec_hom_eq g f;
  ec_hom_eq_trans : forall a b (f g h : ec_hom a b),
      ec_hom_eq f g -> ec_hom_eq g h -> ec_hom_eq f h;
  ec_comp_cong : forall a b c (f f' : ec_hom a b) (g g' : ec_hom b c),
      ec_hom_eq f f' -> ec_hom_eq g g' ->
      ec_hom_eq (ec_comp f g) (ec_comp f' g');
  ec_id_left : forall a b (f : ec_hom a b),
      ec_hom_eq (ec_comp (ec_id a) f) f;
  ec_id_right : forall a b (f : ec_hom a b),
      ec_hom_eq (ec_comp f (ec_id b)) f;
  ec_assoc : forall a b c d (f : ec_hom a b) (g : ec_hom b c) (h : ec_hom c d),
      ec_hom_eq (ec_comp f (ec_comp g h)) (ec_comp (ec_comp f g) h)
}.

(** Objects are formulas, homs are derivations of implications, parallel
    derivations identified (posetal hom-setoid). *)

Definition LT_category : ECat.
Proof.
  refine (mkECat Form
            (fun a b => |- Impl a b)
            (fun a b f g => True)
            (fun a => prov_id a)
            (fun a b c f g => prov_compose a b c f g)
            _ _ _ _ _ _ _); intros; exact I.
Defined.

(** Objects are definable upsets of the canonical maximal-consistent
    worlds (a set of worlds packaged with a defining formula), homs are
    pointwise inclusions. *)

Record FrameObj : Type := mkFrameObj {
  fo_set : canonical_world_max -> Prop;
  fo_wit : Form;
  fo_def : forall w, fo_set w <-> Stone_image fo_wit w
}.

Definition fo_incl (X Y : FrameObj) : Prop :=
  forall w, fo_set X w -> fo_set Y w.

Definition canonical_frame_category : ECat.
Proof.
  refine (mkECat FrameObj
            fo_incl
            (fun X Y f g => True)
            (fun X => fun w H => H)
            (fun X Y Z f g => fun w H => g w (f w H))
            _ _ _ _ _ _ _); intros; exact I.
Defined.

Record EFunctor (C D : ECat) : Type := mkEF {
  ef_obj : ec_obj C -> ec_obj D;
  ef_hom : forall a b, ec_hom C a b -> ec_hom D (ef_obj a) (ef_obj b);
  ef_id_law : forall a,
      ec_hom_eq D (ef_hom a a (ec_id C a)) (ec_id D (ef_obj a));
  ef_comp_law : forall a b c (f : ec_hom C a b) (g : ec_hom C b c),
      ec_hom_eq D (ef_hom a c (ec_comp C f g))
                  (ec_comp D (ef_hom a b f) (ef_hom b c g))
}.

Arguments ef_obj {C D}.
Arguments ef_hom {C D}.

(** F: a formula goes to its Stone image, packaged with itself as the
    defining witness; a derivation goes to the induced inclusion. *)

Definition Stone_F_obj (phi : Form) : FrameObj :=
  mkFrameObj (Stone_image phi) phi (fun w => iff_refl _).

Definition Stone_F_hom (a b : Form) (f : |- Impl a b) :
  fo_incl (Stone_F_obj a) (Stone_F_obj b) :=
  fun w Hw =>
    Stone_image_modus_ponens w a b
      (Stone_image_provable_universal _ f w) Hw.

Definition Stone_F : EFunctor LT_category canonical_frame_category.
Proof.
  refine (mkEF LT_category canonical_frame_category
            Stone_F_obj Stone_F_hom _ _); intros; exact I.
Defined.

(** G: a frame object goes to its defining witness; an inclusion goes to
    a derivation via the separation lemma. *)

Definition Stone_G_obj (X : FrameObj) : Form := fo_wit X.

Definition Stone_G_hom (X Y : FrameObj) (f : fo_incl X Y) :
  |- Impl (fo_wit X) (fo_wit Y) :=
  Stone_separation (fo_wit X) (fo_wit Y)
    (fun w Hw => proj1 (fo_def Y w) (f w (proj2 (fo_def X w) Hw))).

Definition Stone_G : EFunctor canonical_frame_category LT_category.
Proof.
  refine (mkEF canonical_frame_category LT_category
            Stone_G_obj Stone_G_hom _ _); intros; exact I.
Defined.

(** eta : Id => G o F.  At a, G (F a) is definitionally a; the component
    is the derivation [prov_id a]. *)

Definition Stone_eta (a : Form) :
  ec_hom LT_category a (ef_obj Stone_G (ef_obj Stone_F a)) :=
  prov_id a.

Definition Stone_eta_inv (a : Form) :
  ec_hom LT_category (ef_obj Stone_G (ef_obj Stone_F a)) a :=
  prov_id a.

Theorem Stone_eta_iso : forall a,
  ec_hom_eq LT_category
    (ec_comp LT_category (Stone_eta a) (Stone_eta_inv a))
    (ec_id LT_category a) /\
  ec_hom_eq LT_category
    (ec_comp LT_category (Stone_eta_inv a) (Stone_eta a))
    (ec_id LT_category (ef_obj Stone_G (ef_obj Stone_F a))).
Proof. intro a. split; exact I. Qed.

Theorem Stone_eta_natural : forall a b (f : ec_hom LT_category a b),
  ec_hom_eq LT_category
    (ec_comp LT_category (Stone_eta a)
       (ef_hom Stone_G _ _ (ef_hom Stone_F _ _ f)))
    (ec_comp LT_category f (Stone_eta b)).
Proof. intros; exact I. Qed.

(** epsilon : F o G => Id.  At X, F (G X) is the Stone image of X's
    witness; the components are the two directions of X's defining
    equivalence. *)

Definition Stone_epsilon (X : FrameObj) :
  ec_hom canonical_frame_category (ef_obj Stone_F (ef_obj Stone_G X)) X :=
  fun w Hw => proj2 (fo_def X w) Hw.

Definition Stone_epsilon_inv (X : FrameObj) :
  ec_hom canonical_frame_category X (ef_obj Stone_F (ef_obj Stone_G X)) :=
  fun w Hw => proj1 (fo_def X w) Hw.

Theorem Stone_epsilon_iso : forall X,
  ec_hom_eq canonical_frame_category
    (ec_comp canonical_frame_category (Stone_epsilon X) (Stone_epsilon_inv X))
    (ec_id canonical_frame_category (ef_obj Stone_F (ef_obj Stone_G X))) /\
  ec_hom_eq canonical_frame_category
    (ec_comp canonical_frame_category (Stone_epsilon_inv X) (Stone_epsilon X))
    (ec_id canonical_frame_category X).
Proof. intro X. split; exact I. Qed.

Theorem Stone_epsilon_natural : forall X Y (f : fo_incl X Y),
  ec_hom_eq canonical_frame_category
    (ec_comp canonical_frame_category
       (ef_hom Stone_F _ _ (ef_hom Stone_G _ _ f))
       (Stone_epsilon Y))
    (ec_comp canonical_frame_category (Stone_epsilon X) f).
Proof. intros; exact I. Qed.

Theorem Stone_triangle_F : forall a : Form,
  ec_hom_eq canonical_frame_category
    (ec_comp canonical_frame_category
       (ef_hom Stone_F _ _ (Stone_eta a))
       (Stone_epsilon (ef_obj Stone_F a)))
    (ec_id canonical_frame_category (ef_obj Stone_F a)).
Proof. intros; exact I. Qed.

Theorem Stone_triangle_G : forall X : FrameObj,
  ec_hom_eq LT_category
    (ec_comp LT_category
       (Stone_eta (ef_obj Stone_G X))
       (ef_hom Stone_G _ _ (Stone_epsilon X)))
    (ec_id LT_category (ef_obj Stone_G X)).
Proof. intros; exact I. Qed.

Theorem Stone_full_faithful : forall a b : Form,
  (|- Impl a b) <-> fo_incl (Stone_F_obj a) (Stone_F_obj b).
Proof.
  intros a b. split.
  - intro f. exact (Stone_F_hom a b f).
  - intro g. exact (Stone_separation a b g).
Qed.

Theorem Stone_essentially_surjective : forall X : FrameObj,
  exists a : Form,
    inhabited (fo_incl (Stone_F_obj a) X) /\
    inhabited (fo_incl X (Stone_F_obj a)).
Proof.
  intro X. exists (fo_wit X). split.
  - exact (inhabits (Stone_epsilon X)).
  - exact (inhabits (Stone_epsilon_inv X)).
Qed.

Theorem Stone_hom_duality : forall X Y : FrameObj,
  inhabited (fo_incl X Y) <-> |- Impl (fo_wit X) (fo_wit Y).
Proof.
  intros X Y. split.
  - intros [f]. exact (Stone_G_hom X Y f).
  - intro f. constructor.
    intros w Hw.
    apply (proj2 (fo_def Y w)).
    apply (Stone_image_modus_ponens w (fo_wit X) (fo_wit Y)
             (Stone_image_provable_universal _ f w)).
    exact (proj1 (fo_def X w) Hw).
Qed.

Theorem Stone_duality_category_equivalence :
  (forall a, ec_hom_eq LT_category
     (ec_comp LT_category (Stone_eta a) (Stone_eta_inv a))
     (ec_id LT_category a)) /\
  (forall X, ec_hom_eq canonical_frame_category
     (ec_comp canonical_frame_category (Stone_epsilon X) (Stone_epsilon_inv X))
     (ec_id canonical_frame_category (ef_obj Stone_F (ef_obj Stone_G X)))) /\
  (forall a, ec_hom_eq canonical_frame_category
     (ec_comp canonical_frame_category
        (ef_hom Stone_F _ _ (Stone_eta a))
        (Stone_epsilon (ef_obj Stone_F a)))
     (ec_id canonical_frame_category (ef_obj Stone_F a))) /\
  (forall X, ec_hom_eq LT_category
     (ec_comp LT_category
        (Stone_eta (ef_obj Stone_G X))
        (ef_hom Stone_G _ _ (Stone_epsilon X)))
     (ec_id LT_category (ef_obj Stone_G X))) /\
  (forall a b : Form,
     (|- Impl a b) <-> fo_incl (Stone_F_obj a) (Stone_F_obj b)) /\
  (forall X : FrameObj,
     exists a : Form,
       inhabited (fo_incl (Stone_F_obj a) X) /\
       inhabited (fo_incl X (Stone_F_obj a))).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - intro a. exact (proj1 (Stone_eta_iso a)).
  - intro X. exact (proj1 (Stone_epsilon_iso X)).
  - exact Stone_triangle_F.
  - exact Stone_triangle_G.
  - exact Stone_full_faithful.
  - exact Stone_essentially_surjective.
Qed.

Definition Esakia_LT_to_dual : Form -> canonical_world_max -> Prop := Stone_image.

Definition Esakia_dual_to_LT : (canonical_world_max -> Prop) -> Form -> Prop :=
  fun S phi => forall w, S w -> Stone_image phi w.

Theorem Esakia_duality_objects_LT_to_frame :
  forall phi, |- phi -> forall (w : canonical_world_max), Stone_image phi w.
Proof. exact Stone_image_provable_universal. Qed.

Theorem Esakia_duality_objects_frame_to_LT :
  forall phi, (forall (w : canonical_world_max), Stone_image phi w) -> |- phi.
Proof. apply Stone_duality_provability_iff_universal. Qed.

Theorem Esakia_duality_objects_iff :
  forall phi, |- phi <-> forall (w : canonical_world_max), Stone_image phi w.
Proof. exact Stone_duality_provability_iff_universal. Qed.

Definition Esakia_LT_morphism (phi psi : Form) : Prop := |- Impl phi psi.

Theorem Esakia_LT_morphism_refl : forall phi, Esakia_LT_morphism phi phi.
Proof. intros phi. unfold Esakia_LT_morphism. apply prov_id. Qed.

Theorem Esakia_LT_morphism_trans : forall phi psi chi,
  Esakia_LT_morphism phi psi ->
  Esakia_LT_morphism psi chi ->
  Esakia_LT_morphism phi chi.
Proof.
  intros phi psi chi Hpq Hqr. unfold Esakia_LT_morphism in *.
  exact (prov_compose _ _ _ Hpq Hqr).
Qed.

Definition Esakia_frame_morphism (S T : canonical_world_max -> Prop) : Prop :=
  forall w, S w -> T w.

Theorem Esakia_frame_morphism_refl : forall S, Esakia_frame_morphism S S.
Proof. intros S w H. exact H. Qed.

Theorem Esakia_frame_morphism_trans : forall S T U,
  Esakia_frame_morphism S T ->
  Esakia_frame_morphism T U ->
  Esakia_frame_morphism S U.
Proof. intros S T U Hst Htu w Hs. apply Htu. apply Hst. exact Hs. Qed.

Theorem Esakia_LT_to_frame_morphism_functor : forall phi psi,
  Esakia_LT_morphism phi psi ->
  Esakia_frame_morphism (Stone_image phi) (Stone_image psi).
Proof.
  intros phi psi Hpq w Hw_phi.
  unfold Esakia_LT_morphism in Hpq.
  apply (Stone_image_modus_ponens w phi psi).
  - apply Stone_image_provable_universal. exact Hpq.
  - exact Hw_phi.
Qed.

Theorem Esakia_duality_morphism_preservation :
  (forall phi, Esakia_LT_morphism phi phi) /\
  (forall phi psi chi,
    Esakia_LT_morphism phi psi ->
    Esakia_LT_morphism psi chi ->
    Esakia_LT_morphism phi chi) /\
  (forall S, Esakia_frame_morphism S S) /\
  (forall S T U,
    Esakia_frame_morphism S T ->
    Esakia_frame_morphism T U ->
    Esakia_frame_morphism S U) /\
  (forall phi psi,
    Esakia_LT_morphism phi psi ->
    Esakia_frame_morphism (Stone_image phi) (Stone_image psi)).
Proof.
  split; [|split; [|split; [|split]]].
  - exact Esakia_LT_morphism_refl.
  - exact Esakia_LT_morphism_trans.
  - exact Esakia_frame_morphism_refl.
  - exact Esakia_frame_morphism_trans.
  - exact Esakia_LT_to_frame_morphism_functor.
Qed.

Lemma forces_box_free_iff_eval_const : forall (F : Frame) val w phi,
  box_free phi ->
  (forces F (fun _ => val) w phi <-> eval val phi = true).
Proof.
  intros F val w phi Hbf. revert w.
  induction phi as [p | | a IHa b IHb | n psi IHpsi]; intros w; cbn in *.
  - tauto.
  - split. intros []. discriminate.
  - destruct Hbf as [Hbfa Hbfb].
    pose proof (IHa Hbfa w) as Hia.
    pose proof (IHb Hbfb w) as Hib.
    split.
    + intros Himp.
      destruct (classic (forces F (fun _ => val) w a)) as [Ha | Hna].
      * pose proof (proj1 Hia Ha) as Heva.
        pose proof (Himp Ha) as Hb.
        pose proof (proj1 Hib Hb) as Hevb.
        rewrite Heva, Hevb. cbn. reflexivity.
      * assert (Heva : eval val a = false).
        { case_eq (eval val a); intros Hev; [|reflexivity].
          exfalso. apply Hna. apply (proj2 Hia). exact Hev. }
        rewrite Heva. cbn. reflexivity.
    + intros Heval Ha.
      pose proof (proj1 Hia Ha) as Heva. rewrite Heva in Heval. cbn in Heval.
      apply (proj2 Hib). exact Heval.
  - exfalso; exact Hbf.
Qed.

Lemma forces_box_free_iff_eval_F0 : forall val phi,
  box_free phi ->
  (forces F0 (fun _ => val) true phi <-> eval val phi = true).
Proof. intros val phi Hbf. exact (forces_box_free_iff_eval_const F0 val true phi Hbf). Qed.

Theorem kripke_completeness_box_free_via_frame : forall phi,
  box_free phi -> ~ |- phi ->
  exists (F : Frame) (V : fW F -> nat -> bool) (w : fW F),
    ~ forces F V w phi.
Proof.
  intros phi Hbf Hnp.
  destruct (FFP_for_box_free phi Hbf Hnp) as [val Hv].
  exists F0, (fun _ => val), true.
  intro Habs.
  pose proof (proj1 (forces_box_free_iff_eval_F0 val phi Hbf) Habs) as Heval.
  rewrite Hv in Heval. discriminate.
Qed.

Lemma ProvableProp_to_no_nc : forall phi, ProvableProp phi -> |-no_nc phi.
Proof.
  intros phi H. induction H.
  - apply NC_Ax_K.
  - apply NC_Ax_S.
  - apply NC_Ax_DN.
  - exact (NC_MP _ _ IHProvableProp1 IHProvableProp2).
Qed.

Lemma ProvableProp_to_no_mon : forall phi, ProvableProp phi -> |-no_mon phi.
Proof.
  intros phi H. induction H.
  - apply NM_Ax_K.
  - apply NM_Ax_S.
  - apply NM_Ax_DN.
  - exact (NM_MP _ _ IHProvableProp1 IHProvableProp2).
Qed.

Lemma ProvableProp_to_no_loeb : forall phi, ProvableProp phi -> |-no_loeb phi.
Proof.
  intros phi H. induction H.
  - apply NL_Ax_K.
  - apply NL_Ax_S.
  - apply NL_Ax_DN.
  - exact (NL_MP _ _ IHProvableProp1 IHProvableProp2).
Qed.

Lemma ProvableProp_to_no_b4 : forall phi, ProvableProp phi -> |-no_b4 phi.
Proof.
  intros phi H. induction H.
  - apply NB4_Ax_K.
  - apply NB4_Ax_S.
  - apply NB4_Ax_DN.
  - exact (NB4_MP _ _ IHProvableProp1 IHProvableProp2).
Qed.

Theorem kripke_completeness_no_nc_box_free : forall phi,
  box_free phi -> ~ |-no_nc phi -> exists val, eval val phi = false.
Proof.
  intros phi Hbf Hno.
  destruct (classic (classical_valid phi)) as [Hcv | Hncv].
  - exfalso. apply Hno. apply ProvableProp_to_no_nc.
    apply prop_completeness; assumption.
  - apply not_all_ex_not in Hncv. destruct Hncv as [val Hv].
    exists val. destruct (eval val phi); [contradiction | reflexivity].
Qed.

Theorem kripke_completeness_no_mon_box_free : forall phi,
  box_free phi -> ~ |-no_mon phi -> exists val, eval val phi = false.
Proof.
  intros phi Hbf Hno.
  destruct (classic (classical_valid phi)) as [Hcv | Hncv].
  - exfalso. apply Hno. apply ProvableProp_to_no_mon.
    apply prop_completeness; assumption.
  - apply not_all_ex_not in Hncv. destruct Hncv as [val Hv].
    exists val. destruct (eval val phi); [contradiction | reflexivity].
Qed.

Theorem kripke_completeness_no_loeb_box_free : forall phi,
  box_free phi -> ~ |-no_loeb phi -> exists val, eval val phi = false.
Proof.
  intros phi Hbf Hno.
  destruct (classic (classical_valid phi)) as [Hcv | Hncv].
  - exfalso. apply Hno. apply ProvableProp_to_no_loeb.
    apply prop_completeness; assumption.
  - apply not_all_ex_not in Hncv. destruct Hncv as [val Hv].
    exists val. destruct (eval val phi); [contradiction | reflexivity].
Qed.

Theorem kripke_completeness_no_b4_box_free : forall phi,
  box_free phi -> ~ |-no_b4 phi -> exists val, eval val phi = false.
Proof.
  intros phi Hbf Hno.
  destruct (classic (classical_valid phi)) as [Hcv | Hncv].
  - exfalso. apply Hno. apply ProvableProp_to_no_b4.
    apply prop_completeness; assumption.
  - apply not_all_ex_not in Hncv. destruct Hncv as [val Hv].
    exists val. destruct (eval val phi); [contradiction | reflexivity].
Qed.

Theorem modal_compactness_canonical_witness : forall (Gamma : Form -> Prop),
  FinitelyConsistent Gamma ->
  exists w : canonical_world_max, forall phi, Gamma phi -> cwm_set w phi.
Proof.
  intros Gamma Hfc.
  apply (canonical_world_max_extension Gamma).
  apply compactness. exact Hfc.
Qed.

Lemma forces_Fnat_box_free_iff_classical : forall phi val w,
  box_free phi ->
  (forces Fnat (fun _ => val) w phi <-> eval val phi = true).
Proof. intros phi val w Hbf. exact (forces_box_free_iff_eval_const Fnat val w phi Hbf). Qed.

Theorem omega_completeness_Fnat_box_free : forall phi,
  box_free phi -> (forall V w, forces Fnat V w phi) -> |- phi.
Proof.
  intros phi Hbf Hall.
  apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
  intro val.
  apply (proj1 (forces_Fnat_box_free_iff_classical phi val 0 Hbf)).
  exact (Hall (fun _ => val) 0).
Qed.

Definition universal_frame_carrier : Type := canonical_world_max.

Definition universal_frame_R (n : nat) (w v : canonical_world_max) : Prop :=
  canonical_R_max n w v.

Theorem universal_frame_R_transitive : forall n w v u,
  universal_frame_R n w v -> universal_frame_R n v u ->
  universal_frame_R n w u.
Proof. exact canonical_R_max_transitive. Qed.

Theorem universal_frame_bisimilar_to_canonical : forall n w v,
  canonical_R_max n w v <-> universal_frame_R n w v.
Proof. intros. unfold universal_frame_R. tauto. Qed.

Theorem universal_frame_NextCon_witness : forall n w v,
  universal_frame_R (S n) w v -> cwm_set v (Neg (Box n Bot)).
Proof. exact canonical_R_max_NextCon_witness. Qed.

Theorem universal_frame_truth_lemma_box_free : forall phi w,
  box_free phi -> (cwm_set w phi <-> forces_cwm w phi).
Proof. exact canonical_truth_lemma_max_box_free. Qed.

Theorem finite_frame_property_box_free_F0 : forall phi,
  box_free phi -> ~ |- phi ->
  exists (V : fW F0 -> nat -> bool) (w : fW F0), ~ forces F0 V w phi.
Proof.
  intros phi Hbf Hnp.
  destruct (FFP_for_box_free phi Hbf Hnp) as [val Hv].
  exists (fun _ => val), true.
  intro Habs.
  pose proof (proj1 (forces_box_free_iff_eval_F0 val phi Hbf) Habs) as Heval.
  rewrite Hv in Heval. discriminate.
Qed.

Theorem finite_frame_property_box_n_bot : forall n,
  exists (F : Frame) V w, ~ forces F V w (Box n Bot).
Proof.
  intros n.
  exists Fnat, (fun _ _ => true), (S n).
  intro Habs. cbn in Habs.
  apply (Habs n). unfold Fnat_R. split; lia.
Qed.

Theorem FMP_modal_depth_zero_via_F0 : forall phi,
  box_free phi -> ~ |- phi ->
  modal_depth phi = 0 /\
  exists (V : fW F0 -> nat -> bool) (w : fW F0), ~ forces F0 V w phi.
Proof.
  intros phi Hbf Hnp. split.
  - exact (box_free_modal_depth_zero phi Hbf).
  - exact (finite_frame_property_box_free_F0 phi Hbf Hnp).
Qed.

Theorem selection_theorem_identity_bisimulation : forall (F : Frame) V w,
  exists Z : fW F -> fW F -> Prop, Bisim F F V V Z /\ Z w w.
Proof.
  intros F V w. exists (@eq (fW F)). split.
  - apply bisim_id.
  - reflexivity.
Qed.

Theorem finite_refuting_frame_box_free_or_box_bot : forall phi,
  ((box_free phi /\ ~ |- phi) \/ (exists n, phi = Box n Bot)) ->
  exists (F : Frame) V w, ~ forces F V w phi.
Proof.
  intros phi [[Hbf Hnp] | [n Heq]].
  - exact (kripke_completeness_box_free_via_frame phi Hbf Hnp).
  - subst phi. exists Fnat, (fun _ _ => true), (S n).
    intro Habs. cbn in Habs.
    apply (Habs n). unfold Fnat_R. split; lia.
Qed.

Theorem finite_refuting_frame_for_var : forall n p,
  exists (F : Frame) V w, ~ forces F V w (Box n (Var p)).
Proof.
  intros n p.
  exists Fnat, (fun w q => match q with | _ => false end), (S n).
  intro Habs. cbn in Habs.
  pose proof (Habs n) as Hcontra.
  assert (HR : Fnat_R n (S n) n) by (unfold Fnat_R; split; lia).
  pose proof (Hcontra HR) as H. discriminate.
Qed.

Theorem finite_refuting_frame_for_neg_var : forall n p,
  exists (F : Frame) V w, ~ forces F V w (Box n (Neg (Var p))).
Proof.
  intros n p.
  exists Fnat, (fun _ _ => true), (S n).
  intro Habs. cbn in Habs.
  assert (HR : Fnat_R n (S n) n) by (unfold Fnat_R; split; lia).
  pose proof (Habs n HR) as Hcontra.
  exact (Hcontra eq_refl).
Qed.

(** [Gamma_0_ordinal] is the genuine Feferman-Schütte atom [V_gamma0]:
    the point of the notation system sitting strictly above EVERY
    [V_phi n α] — i.e., above the whole stratified Veblen tower — and
    proved below ([Gamma_0_least_above_phi_tower]) to be the LEAST such
    point of the carrier.  It is NOT the ε_0 atom [veps0 = V_phi 0 OZero]
    (see [Gamma_0_not_eps0]) and NOT a CNF tree such as
    [Veblen_eps0_ordinal] (see [Gamma_0_not_cnf_shape]). *)

Definition Gamma_0_ordinal : vord := V_gamma0.

Definition omega_cnf : ord := OCons (OCons OZero OZero) OZero.

Fixpoint succ_cnf (o : ord) : ord :=
  match o with
  | OZero => OCons OZero OZero
  | OCons a t => OCons a (succ_cnf t)
  end.

Definition ord_max (o1 o2 : ord) : ord :=
  match ord_compare o1 o2 with
  | Lt => o2
  | _ => o1
  end.

Fixpoint ord_add (a b : ord) : ord :=
  match a with
  | OZero => b
  | OCons ae at_a =>
      match b with
      | OZero => OCons ae at_a
      | OCons be _ =>
          match ord_compare ae be with
          | Lt => b
          | _  => OCons ae (ord_add at_a b)
          end
      end
  end.

Definition omega_pow (e : ord) : ord := OCons e OZero.

Fixpoint proof_height_ord (phi : Form) (pt : Provable_term phi) : ord :=
  match pt with
  | pt_K _ _      => omega_cnf
  | pt_S _ _ _    => omega_cnf
  | pt_DN _       => omega_cnf
  | pt_BoxK _ _ _ => omega_cnf
  | pt_Loeb _ _   => omega_cnf
  | pt_Box4 _ _   => omega_cnf
  | pt_Mon _ _    => omega_cnf
  | pt_NextCon _  => omega_cnf
  | pt_MP _ _ p1 p2 => ord_add (proof_height_ord _ p1) (proof_height_ord _ p2)
  | pt_Nec _ _ p    => omega_pow (proof_height_ord _ p)
  end.

Definition proof_height (phi : Form) (pt : Provable_term phi) : vord :=
  V_cnf (proof_height_ord phi pt).

(* Every proof's height is a V_cnf-shaped vord, hence strictly below
   the Gamma_0 atom [V_gamma0]: VL_cnf_g0 places every CNF strictly
   below the Feferman-Schütte point.  This is the (#9) upper bound.
   The bound is genuine but NOT tight — see [Gamma_0_bound_not_tight]
   below: heights are already strictly below the ε_0 atom [veps0],
   which is itself strictly below [Gamma_0_ordinal]. *)
Theorem GLP_proof_height_below_Gamma_0 :
  forall phi (pt : Provable_term phi),
  vord_lt (proof_height phi pt) Gamma_0_ordinal.
Proof.
  intros phi pt.
  unfold proof_height, Gamma_0_ordinal.
  apply VL_cnf_g0.
Qed.

(* Concrete proof-term for Top := Impl Bot Bot, via the standard
   Hilbert id-derivation S(K(B->B->B))(K(B->B)). *)
Definition pt_id_Top : Provable_term Top :=
  pt_MP _ _
    (pt_MP _ _
       (pt_S Bot (Impl Bot Bot) Bot)
       (pt_K Bot (Impl Bot Bot)))
    (pt_K Bot Bot).

Lemma proof_height_id_Top_compute :
  proof_height_ord Top pt_id_Top
  = OCons (OCons OZero OZero) (OCons (OCons OZero OZero) (OCons (OCons OZero OZero) OZero)).
Proof. reflexivity. Qed.

Lemma proof_height_id_Top_gt_omega :
  ord_lt omega_cnf (proof_height_ord Top pt_id_Top).
Proof.
  rewrite proof_height_id_Top_compute.
  unfold ord_lt, omega_cnf. cbn. reflexivity.
Qed.

Fixpoint nat_witness_form (n : nat) : Form :=
  match n with
  | 0 => Top
  | S k => Box 0 (nat_witness_form k)
  end.

Fixpoint nat_witness_proof (n : nat) : Provable_term (nat_witness_form n) :=
  match n return Provable_term (nat_witness_form n) with
  | 0 => pt_id_Top
  | S k => pt_Nec 0 (nat_witness_form k) (nat_witness_proof k)
  end.

Definition vord_le (u v : vord) : Prop := u = v \/ vord_lt u v.

(* Every nat n is strictly below omega_cnf in ord (nat_to_ord n is
   the standard CNF embedding of finite ordinals). *)
Lemma nat_to_ord_lt_omega_cnf : forall n,
  ord_lt (nat_to_ord n) omega_cnf.
Proof.
  intro n. unfold ord_lt, omega_cnf.
  induction n as [|n IH]; cbn.
  - reflexivity.
  - reflexivity.
Qed.

(* The proof-height of nat_witness_proof n always exceeds omega_cnf:
   the base case pt_id_Top uses pt_S and pt_K (each rank omega_cnf)
   plus two MPs (each succ_cnf), so the base height is succ_cnf
   (succ_cnf omega_cnf) = omega_cnf + 2.  Each Nec adds a succ_cnf.
   So the height grows with n, never falling below omega_cnf. *)
(* succ_cnf strictly increases ords (used for the original cure
   spec; kept available even though Nec now uses omega_pow). *)
Lemma succ_cnf_gt : forall o, ord_lt o (succ_cnf o).
Proof.
  intro o. unfold ord_lt. induction o as [|a IHa t IHt]; cbn.
  - reflexivity.
  - rewrite ord_compare_refl. exact IHt.
Qed.

(* omega_pow is strictly monotone in its argument. *)
Lemma omega_pow_monotone : forall a b,
  ord_lt a b -> ord_lt (omega_pow a) (omega_pow b).
Proof.
  intros a b H. unfold ord_lt, omega_pow in *.
  cbn. rewrite H. reflexivity.
Qed.

(* For e > OZero, omega_pow e is strictly above any e (since
   omega^e > e for e > 0).  In particular omega_pow OZero =
   OCons OZero OZero = 1 > OZero. *)
Lemma omega_pow_OZero_gt_OZero : ord_lt OZero (omega_pow OZero).
Proof. unfold ord_lt, omega_pow. cbn. reflexivity. Qed.


(* Any Provable_term with omega_pow as the outermost rank-step is
   bounded below by omega_cnf, since omega_pow X >= omega_cnf
   whenever X >= omega_cnf >= 1. *)
Lemma omega_pow_geq_omega_when_arg_geq_one : forall x,
  ord_lt OZero x ->
  ord_le omega_cnf (omega_pow x).
Proof.
  intros x Hx.
  unfold omega_pow, omega_cnf, ord_le.
  destruct x as [|xe xt].
  - unfold ord_lt in Hx. cbn in Hx. discriminate.
  - cbn.
    destruct xe as [|xee xet].
    + cbn. destruct xt as [|xte xtt]; cbn; congruence.
    + cbn. destruct xee as [|xeee xeet]; cbn; congruence.
Qed.

Lemma proof_height_nat_witness_geq_omega : forall n,
  ord_le omega_cnf (proof_height_ord (nat_witness_form n) (nat_witness_proof n)).
Proof.
  induction n as [|n IH].
  - unfold ord_le. cbn.
    unfold ord_add. cbn. congruence.
  - cbn.
    apply omega_pow_geq_omega_when_arg_geq_one.
    unfold ord_le in IH.
    destruct (proof_height_ord (nat_witness_form n) (nat_witness_proof n))
      as [|he ht] eqn:Heq.
    + exfalso. apply IH. cbn. reflexivity.
    + unfold ord_lt. cbn. reflexivity.
Qed.

Lemma ord_compare_eq_iff : forall a b,
  ord_compare a b = Eq <-> a = b.
Proof.
  induction a as [|ae IHae at_a IHat]; intros [|be bt]; cbn.
  - split; intro; reflexivity.
  - split; intro H; discriminate.
  - split; intro H; discriminate.
  - destruct (ord_compare ae be) eqn:Eae; split.
    + intro Ht. f_equal.
      * apply IHae. exact Eae.
      * apply IHat. exact Ht.
    + intro Heq. injection Heq as Hae Hat. subst.
      rewrite ord_compare_refl in Eae. discriminate Eae || idtac.
      apply IHat. reflexivity.
    + intro H. discriminate H.
    + intro Heq. injection Heq as Hae Hat. subst.
      rewrite ord_compare_refl in Eae. discriminate Eae.
    + intro H. discriminate H.
    + intro Heq. injection Heq as Hae Hat. subst.
      rewrite ord_compare_refl in Eae. discriminate Eae.
Qed.

Lemma proof_height_nat_witness_gt_nat : forall n,
  ord_lt (nat_to_ord n) (proof_height_ord (nat_witness_form n) (nat_witness_proof n)).
Proof.
  intro n.
  pose proof (nat_to_ord_lt_omega_cnf n) as H1.
  pose proof (proof_height_nat_witness_geq_omega n) as H2.
  unfold ord_le in H2.
  destruct (ord_compare omega_cnf (proof_height_ord (nat_witness_form n) (nat_witness_proof n)))
    eqn:Hcmp.
  - apply (proj1 (ord_compare_eq_iff _ _)) in Hcmp.
    rewrite <- Hcmp. exact H1.
  - exact (ord_lt_trans _ _ _ H1 Hcmp).
  - exfalso. apply H2. reflexivity.
Qed.

(* The lower-bound theorem: for every nat n, there is a Provable_term
   phi whose height is strictly above V_cnf (nat_to_ord n).  The phi
   is nat_witness_form n (= n levels of Box 0 around Top), and the
   proof is nat_witness_proof n (= n Nec applications on pt_id_Top).
   Both vary with n -- the construction is primitive-recursive on n
   with one Nec increment per step. *)
Theorem witness_at_for_finite_alpha : forall n,
  { phi : Form &
    { pt : Provable_term phi &
        vord_le (V_cnf (nat_to_ord n)) (proof_height phi pt) } }.
Proof.
  intro n.
  exists (nat_witness_form n).
  exists (nat_witness_proof n).
  right.
  unfold proof_height. apply VL_cnf.
  exact (proof_height_nat_witness_gt_nat n).
Qed.

Theorem witness_at_finite_lower_bound : forall n,
  exists phi (pt : Provable_term phi),
    vord_le (V_cnf (nat_to_ord n)) (proof_height phi pt).
Proof.
  intro n.
  destruct (witness_at_for_finite_alpha n) as [phi [pt Hle]].
  exists phi, pt. exact Hle.
Qed.

(* Recursive witness construction over arbitrary CNF ords.
   Given o : ord, builds a Form phi and a Provable_term proof pt
   such that the proof's rank ord_le-dominates o.
   Recursion structure: for OCons a t, recurse on a (giving a
   proof of rank >= a, then Nec'd to give rank >= ω^a) and on t
   (giving a proof of rank >= t), then combine via MP-then-K to
   get a proof of rank >= ord_add (ω^a) t = OCons a t (when t's
   leading exp < a, i.e. o is in CNF). *)
Fixpoint witness_at_for_ord_form (o : ord) : Form :=
  match o with
  | OZero => Top
  | OCons a _ => Box 0 (witness_at_for_ord_form a)
  end.

Fixpoint witness_at_for_ord_proof (o : ord) :
  Provable_term (witness_at_for_ord_form o) :=
  match o return Provable_term (witness_at_for_ord_form o) with
  | OZero => pt_id_Top
  | OCons a t =>
      let p_a := witness_at_for_ord_proof a in
      let p_a_box : Provable_term (Box 0 (witness_at_for_ord_form a))
        := pt_Nec 0 (witness_at_for_ord_form a) p_a in
      let p_t := witness_at_for_ord_proof t in
      let pK := pt_K (Box 0 (witness_at_for_ord_form a))
                     (witness_at_for_ord_form t) in
      let p1 := pt_MP _ _ pK p_a_box in
      pt_MP _ _ p1 p_t
  end.

(* The transitivity of ord_lt for arbitrary CNF (the codebase's
   [ord_lt_trans] is for the wf_ord/cnf-restricted version; here
   we use the unrestricted ord_compare-based one). *)
Lemma ord_lt_trans_unrestricted : forall a b c,
  ord_lt a b -> ord_lt b c -> ord_lt a c.
Proof. intros a b c. exact (ord_lt_trans a b c). Qed.

(* OCons _ _ is strictly greater than OZero. *)
Lemma OZero_lt_OCons : forall e t, ord_lt OZero (OCons e t).
Proof. intros e t. unfold ord_lt. cbn. reflexivity. Qed.

(* Reflexivity of ord_le. *)
Lemma ord_le_refl : forall o, ord_le o o.
Proof.
  intro o. unfold ord_le. rewrite ord_compare_refl. discriminate.
Qed.

(* Strict-implies-le. *)
Lemma ord_lt_le : forall a b, ord_lt a b -> ord_le a b.
Proof.
  intros a b H. unfold ord_le, ord_lt in *. rewrite H. discriminate.
Qed.

(* ord_add of two OCons-shaped ords is OCons-shaped. *)
Lemma ord_add_OCons_OCons_OCons : forall ae at_a be bt,
  exists e t, ord_add (OCons ae at_a) (OCons be bt) = OCons e t.
Proof.
  intros ae at_a be bt. cbn.
  destruct (ord_compare ae be); eauto.
Qed.

(* Every Provable_term has positive proof_height_ord (= OCons-shaped). *)
Lemma proof_height_ord_OCons_shape :
  forall (phi : Form) (pt : Provable_term phi),
  exists e t, proof_height_ord phi pt = OCons e t.
Proof.
  intros phi pt. induction pt; try (cbn; eauto; fail).
  - cbn. unfold omega_cnf. eauto.
  - cbn. unfold omega_cnf. eauto.
  - cbn. unfold omega_cnf. eauto.
  - cbn. unfold omega_cnf. eauto.
  - cbn. unfold omega_cnf. eauto.
  - cbn. unfold omega_cnf. eauto.
  - cbn. unfold omega_cnf. eauto.
  - cbn. unfold omega_cnf. eauto.
  - cbn.
    destruct IHpt1 as [e1 [t1 H1]].
    destruct IHpt2 as [e2 [t2 H2]].
    rewrite H1, H2.
    apply ord_add_OCons_OCons_OCons.
  - cbn. unfold omega_pow. eauto.
Qed.

(* The proof_height of witness_at_for_ord_proof always exceeds OZero. *)
Lemma proof_height_witness_at_for_ord_proof_pos : forall o,
  ord_lt OZero (proof_height_ord (witness_at_for_ord_form o)
                                  (witness_at_for_ord_proof o)).
Proof.
  intro o.
  destruct (proof_height_ord_OCons_shape (witness_at_for_ord_form o)
                                          (witness_at_for_ord_proof o))
    as [e [t Heq]].
  rewrite Heq. unfold ord_lt. cbn. reflexivity.
Qed.

(* Basic ord_le/ord_lt arithmetic. *)
Lemma ord_le_lt_trans : forall a b c,
  ord_le a b -> ord_lt b c -> ord_lt a c.
Proof.
  intros a b c Hab Hbc. unfold ord_le, ord_lt in *.
  destruct (ord_compare a b) eqn:Eab.
  - apply ord_compare_eq_iff in Eab. rewrite Eab. exact Hbc.
  - exact (ord_lt_trans _ _ _ Eab Hbc).
  - exfalso. apply Hab. reflexivity.
Qed.

Lemma ord_lt_le_trans : forall a b c,
  ord_lt a b -> ord_le b c -> ord_lt a c.
Proof.
  intros a b c Hab Hbc. unfold ord_le, ord_lt in *.
  destruct (ord_compare b c) eqn:Ebc.
  - apply ord_compare_eq_iff in Ebc. rewrite <- Ebc. exact Hab.
  - exact (ord_lt_trans _ _ _ Hab Ebc).
  - exfalso. apply Hbc. reflexivity.
Qed.

Lemma ord_le_trans : forall a b c,
  ord_le a b -> ord_le b c -> ord_le a c.
Proof.
  intros a b c Hab Hbc. unfold ord_le in *.
  destruct (ord_compare a c) eqn:Eac.
  - congruence.
  - congruence.
  - destruct (ord_compare a b) eqn:Eab.
    + apply ord_compare_eq_iff in Eab. rewrite Eab in Eac.
      exfalso. apply Hbc. exact Eac.
    + assert (Hab2 : ord_lt a b) by exact Eab.
      destruct (ord_compare b c) eqn:Ebc.
      * apply ord_compare_eq_iff in Ebc.
        rewrite Ebc in Hab2. unfold ord_lt in Hab2.
        rewrite Eac in Hab2. discriminate.
      * pose proof (ord_lt_trans _ _ _ Hab2 Ebc) as H.
        unfold ord_lt in H. rewrite Eac in H. discriminate.
      * exfalso. apply Hbc. reflexivity.
    + exfalso. apply Hab. reflexivity.
Qed.

(* The CNF condition: t's leading exp < a => ord_add (omega_pow a) t = OCons a t. *)
Lemma ord_add_omega_pow_t_when_t_is_OZero : forall a,
  ord_add (omega_pow a) OZero = OCons a OZero.
Proof. intro a. cbn. reflexivity. Qed.

Lemma ord_add_omega_pow_OCons_when_lt :
  forall a be bt,
  ord_compare a be = Gt ->
  ord_add (omega_pow a) (OCons be bt) = OCons a (OCons be bt).
Proof.
  intros a be bt H. unfold omega_pow. cbn. rewrite H. reflexivity.
Qed.

Lemma ord_add_omega_pow_OCons_when_eq :
  forall a bt,
  ord_add (omega_pow a) (OCons a bt) = OCons a (OCons a bt).
Proof.
  intros a bt. unfold omega_pow. cbn. rewrite ord_compare_refl. reflexivity.
Qed.

(* For wf_ord (OCons a t): t's leading exp is strictly less than a,
   or t is OZero.  In both cases, ord_add (omega_pow a) t = OCons a t. *)
Lemma ord_add_omega_pow_wf : forall a t,
  wf_ord (OCons a t) ->
  ord_add (omega_pow a) t = OCons a t.
Proof.
  intros a t Hwf. cbn in Hwf.
  destruct Hwf as [_ [_ Hcond]].
  destruct t as [|te tt].
  - apply ord_add_omega_pow_t_when_t_is_OZero.
  - apply ord_add_omega_pow_OCons_when_lt.
    pose proof (ord_compare_antisym te a) as Hsym.
    rewrite Hcond in Hsym.
    destruct (ord_compare a te); cbn in Hsym; congruence.
Qed.

(* ord_compare on omega_pow distributes through the argument. *)
Lemma ord_compare_omega_pow : forall a b,
  ord_compare (omega_pow a) (omega_pow b) = ord_compare a b.
Proof.
  intros a b. unfold omega_pow. cbn.
  destruct (ord_compare a b) eqn:E; reflexivity.
Qed.

Lemma omega_pow_monotone_le : forall a b,
  ord_le a b -> ord_le (omega_pow a) (omega_pow b).
Proof.
  intros a b Hab. unfold ord_le in *.
  rewrite ord_compare_omega_pow. exact Hab.
Qed.

Lemma omega_pow_monotone_lt : forall a b,
  ord_lt a b -> ord_lt (omega_pow a) (omega_pow b).
Proof.
  intros a b Hab. unfold ord_lt in *.
  rewrite ord_compare_omega_pow. exact Hab.
Qed.

(* Strict ord_lt-through-leading: when a < a', OCons a t < OCons a' t' *)
Lemma ord_lt_OCons_leading : forall a t a' t',
  ord_lt a a' -> ord_lt (OCons a t) (OCons a' t').
Proof.
  intros a t a' t' H. apply ord_lt_OCons_head. exact H.
Qed.

(* When the leading is equal and tails compare ord_le, OCons-form ord_le. *)
Lemma ord_le_OCons_when_eq_leading : forall a t1 t2,
  ord_le t1 t2 -> ord_le (OCons a t1) (OCons a t2).
Proof.
  intros a t1 t2 H. unfold ord_le, ord_lt in *.
  cbn. rewrite ord_compare_refl. exact H.
Qed.

(* Generalisation: when leadings compare Eq (need not be syntactically
   identical), the OCons-form ord_le follows from the tail's ord_le. *)
Lemma ord_le_OCons_when_compare_eq_leading : forall a a' t1 t2,
  ord_compare a a' = Eq -> ord_le t1 t2 -> ord_le (OCons a t1) (OCons a' t2).
Proof.
  intros a a' t1 t2 Hcmp Ht. unfold ord_le, ord_lt in *.
  cbn. rewrite Hcmp. exact Ht.
Qed.

(* OCons a t1 ≤ OCons a' t2 when a < a' (purely from leading exp). *)
Lemma ord_le_OCons_leading_lt : forall a t1 a' t2,
  ord_lt a a' -> ord_le (OCons a t1) (OCons a' t2).
Proof.
  intros a t1 a' t2 H. apply ord_lt_le. apply ord_lt_OCons_head. exact H.
Qed.

(* Helper: omega_cnf is positive. *)
Lemma omega_cnf_pos : ord_lt OZero omega_cnf.
Proof. unfold ord_lt, omega_cnf. cbn. reflexivity. Qed.

Lemma omega_cnf_gt_one : ord_lt (OCons OZero OZero) omega_cnf.
Proof. unfold ord_lt, omega_cnf. cbn. reflexivity. Qed.

(* Every proof_height_ord is at least omega_cnf, since the base axiom
   ranks ARE omega_cnf and ord_add / omega_pow only grow heights. *)
(* Helper: ord_compare X (OCons (OCons OZero OZero) Y) is determined
   by the leading exp of X compared to OCons OZero OZero, with the
   tail comparing only when leading is exactly OCons OZero OZero. *)
Lemma omega_cnf_le_OCons_OCons_OZero_OZero_anything : forall t,
  ord_le omega_cnf (OCons (OCons OZero OZero) t).
Proof.
  intro t. unfold ord_le, omega_cnf. cbn.
  destruct t; cbn; discriminate.
Qed.

(* If e is OCons (OCons OZero OZero) _ or has leading >= OCons OZero OZero,
   then ord_le omega_cnf (OCons e _). *)
Lemma omega_cnf_le_OCons_when_lead_ge : forall e t,
  ord_le (OCons OZero OZero) e ->
  ord_le omega_cnf (OCons e t).
Proof.
  intros e t H.
  destruct e as [|ee et].
  - exfalso. apply H. unfold ord_le. cbn. reflexivity.
  - destruct ee as [|eee eet].
    + (* e = OCons OZero et: leading exp OZero, equal to OCons OZero OZero's
         leading exp OZero. Compare tails. *)
      destruct et as [|ete ett].
      * (* e = OCons OZero OZero = 1 = leading of omega_cnf. *)
        unfold ord_le, omega_cnf. cbn.
        destruct t; cbn; discriminate.
      * (* e = OCons OZero (OCons _ _) *)
        unfold ord_le, omega_cnf. cbn.
        discriminate.
    + (* e = OCons (OCons _ _) _: leading > OZero. *)
      unfold ord_le, omega_cnf. cbn.
      discriminate.
Qed.

Lemma omega_cnf_le_implies_gt_one : forall x,
  ord_le omega_cnf x -> ord_lt (OCons OZero OZero) x.
Proof.
  intros x H. exact (ord_lt_le_trans _ _ _ omega_cnf_gt_one H).
Qed.

(* When H_a > 1, ord_add omega_cnf (omega_pow H_a) absorbs to omega_pow H_a. *)
Lemma ord_add_omega_cnf_absorbed : forall H_a,
  ord_lt (OCons OZero OZero) H_a ->
  ord_add omega_cnf (omega_pow H_a) = omega_pow H_a.
Proof.
  intros H_a Hlt.
  destruct H_a as [|e t].
  - exfalso. unfold ord_lt in Hlt. cbn in Hlt. discriminate.
  - destruct e as [|ee et].
    + destruct t as [|te tt].
      * exfalso. unfold ord_lt in Hlt. cbn in Hlt. discriminate.
      * unfold omega_cnf, omega_pow. cbn. reflexivity.
    + unfold omega_cnf, omega_pow. cbn. reflexivity.
Qed.

Lemma proof_height_ord_ge_omega_cnf :
  forall (phi : Form) (pt : Provable_term phi),
  ord_le omega_cnf (proof_height_ord phi pt).
Proof.
  intros phi pt. induction pt.
  - cbn. apply ord_le_refl.
  - cbn. apply ord_le_refl.
  - cbn. apply ord_le_refl.
  - cbn. apply ord_le_refl.
  - cbn. apply ord_le_refl.
  - cbn. apply ord_le_refl.
  - cbn. apply ord_le_refl.
  - cbn. apply ord_le_refl.
  - cbn.
    destruct (proof_height_ord_OCons_shape _ pt1) as [e1 [t1 H1]].
    destruct (proof_height_ord_OCons_shape _ pt2) as [e2 [t2 H2]].
    rewrite H1 in IHpt1 |- *.
    rewrite H2 in IHpt2 |- *.
    cbn.
    (* IHpt1: ord_le omega_cnf (OCons e1 t1).  This means ord_compare
       (OCons OZero OZero) e1 is Eq or Lt, i.e., e1 >= OCons OZero OZero. *)
    assert (HE1 : ord_le (OCons OZero OZero) e1).
    { destruct e1 as [|e1e e1t].
      - exfalso. apply IHpt1. unfold omega_cnf. cbn. reflexivity.
      - destruct e1e as [|e1ee e1et].
        + destruct e1t as [|e1te e1tt].
          * unfold ord_le. cbn. discriminate.
          * unfold ord_le. cbn. discriminate.
        + unfold ord_le. cbn. discriminate. }
    destruct (ord_compare e1 e2) eqn:Hee.
    + apply ord_compare_eq_iff in Hee. subst e2.
      apply omega_cnf_le_OCons_when_lead_ge. exact HE1.
    + exact IHpt2.
    + apply omega_cnf_le_OCons_when_lead_ge. exact HE1.
  - cbn.
    unfold omega_pow.
    destruct (proof_height_ord_OCons_shape _ pt) as [e [t Heq]].
    rewrite Heq.
    apply omega_cnf_le_OCons_when_lead_ge.
    unfold ord_le. destruct e as [|ee et]; cbn.
    + destruct t as [|te tt]; cbn; discriminate.
    + discriminate.
Qed.

(* Helper: if omega_pow X has leading exp X, the result of ord_add ω
   (omega_pow X) has leading exp X (when X >= 1, which it is for positive X). *)

(* Tail-lt-leading for wf_ord: when wf_ord (OCons e t), ord_lt t (OCons e t). *)
Lemma wf_ord_OCons_tail_lt : forall e t,
  wf_ord (OCons e t) -> ord_lt t (OCons e t).
Proof.
  intros e t Hwf. unfold ord_lt.
  destruct t as [|te tt]; cbn.
  - reflexivity.
  - cbn in Hwf. destruct Hwf as [_ [_ Hcond]].
    rewrite Hcond. reflexivity.
Qed.

(* The proof_height of witness_at_for_ord_proof (OCons a t) is the explicit
   nested ord_add expression in terms of the heights of the sub-proofs. *)
Lemma proof_height_ord_witness_OCons : forall a t,
  proof_height_ord (witness_at_for_ord_form (OCons a t))
                   (witness_at_for_ord_proof (OCons a t))
  = ord_add (ord_add omega_cnf
               (omega_pow (proof_height_ord (witness_at_for_ord_form a)
                                            (witness_at_for_ord_proof a))))
            (proof_height_ord (witness_at_for_ord_form t)
                              (witness_at_for_ord_proof t)).
Proof. intros a t. reflexivity. Qed.

(* The main theorem: for every CNF ord o, the witness construction
   yields a proof whose height ord_le-dominates o.  The construction
   is primitive-recursive on the structure of o, and the height bound
   is achieved without any classical-existence appeal. *)
Theorem witness_at_for_ord_bound : forall o,
  wf_ord o ->
  ord_le o (proof_height_ord (witness_at_for_ord_form o)
                              (witness_at_for_ord_proof o)).
Proof.
  induction o as [|a IHa t IHt]; intro Hwf.
  - (* o = OZero: ord_le OZero anything. *)
    apply ord_compare_OZero_le.
  - cbn in Hwf. destruct Hwf as [Hwf_a [Hwf_t _]].
    pose proof (IHa Hwf_a) as IH_a.
    pose proof (IHt Hwf_t) as IH_t.
    rewrite proof_height_ord_witness_OCons.
    pose proof (proof_height_ord_ge_omega_cnf _
                  (witness_at_for_ord_proof a)) as Ha_ge.
    pose proof (omega_cnf_le_implies_gt_one _ Ha_ge) as Ha_gt1.
    rewrite (ord_add_omega_cnf_absorbed _ Ha_gt1).
    pose proof (proof_height_ord_OCons_shape _
                  (witness_at_for_ord_proof t)) as [hte [htt Hht_eq]].
    rewrite Hht_eq.
    rewrite Hht_eq in IH_t.
    unfold omega_pow.
    cbn [ord_add].
    destruct (ord_compare (proof_height_ord (witness_at_for_ord_form a)
                                            (witness_at_for_ord_proof a))
                          hte) eqn:Hcmp_a_hte.
    + (* H_a = hte *)
      apply ord_compare_eq_iff in Hcmp_a_hte.
      subst hte.
      cbn [ord_add].
      destruct (ord_compare a (proof_height_ord (witness_at_for_ord_form a)
                                                (witness_at_for_ord_proof a)))
        eqn:Ha_cmp.
      * (* a = H_a *)
        apply ord_le_OCons_when_compare_eq_leading; [exact Ha_cmp|].
        exact IH_t.
      * (* a < H_a *)
        apply ord_le_OCons_leading_lt. exact Ha_cmp.
      * (* a > H_a — contradicts IH_a *)
        exfalso. apply IH_a. exact Ha_cmp.
    + (* H_a < hte *)
      apply ord_le_OCons_leading_lt.
      exact (ord_le_lt_trans _ _ _ IH_a Hcmp_a_hte).
    + (* H_a > hte *)
      cbn [ord_add].
      destruct (ord_compare a (proof_height_ord (witness_at_for_ord_form a)
                                                (witness_at_for_ord_proof a)))
        eqn:Ha_cmp.
      * apply ord_le_OCons_when_compare_eq_leading; [exact Ha_cmp|].
        exact IH_t.
      * apply ord_le_OCons_leading_lt. exact Ha_cmp.
      * exfalso. apply IH_a. exact Ha_cmp.
Qed.

(* Every vord strictly below the ε_0 atom [veps0 = V_phi 0 OZero] is a
   V_cnf-image: VL_cnf_phi places every CNF strictly below V_phi-atoms,
   while no V_phi atom is below V_phi 0 OZero (the index 0 has no
   smaller nat, and the argument OZero has no smaller ord).  Note this
   is FALSE for the genuine [Gamma_0_ordinal = V_gamma0]: the V_phi
   atoms all sit strictly between ε_0-and-friends and Γ_0. *)
Lemma vord_lt_veps0_iff_V_cnf : forall v,
  vord_lt v veps0 ->
  exists o, v = V_cnf o.
Proof.
  intros v Hlt. unfold veps0 in Hlt.
  apply vord_lt_V_phi_inv in Hlt.
  destruct Hlt as [[o Heq] | [[n' [α' [_ Hlt_n]]] | [α' [_ Hlt_α]]]].
  - exists o. exact Heq.
  - lia.
  - destruct α' as [|αe αt]; unfold ord_lt in Hlt_α; cbn in Hlt_α; discriminate.
Qed.

(* The vord-level lower bound: for every vord v strictly below the
   ε_0 atom [veps0], there is a Provable_term whose proof_height
   vord_le-dominates v.  Combined with [proof_height_below_eps0]
   below, this gives EXACTNESS at ε_0 for the omega_pow height
   measure — the heights are all strictly below the ε_0 atom, and
   every threshold strictly below it is attained.  The lower-bound
   construction is primitive-recursive on the underlying CNF ord and
   produces strictly larger proof_heights for strictly larger ords. *)
Theorem witness_at_below_eps0 : forall v,
  wf_vord v ->
  vord_lt v veps0 ->
  { phi : Form &
    { pt : Provable_term phi & vord_le v (proof_height phi pt) } }.
Proof.
  intros v Hwf Hlt.
  destruct v as [o | n α |].
  - cbn in Hwf.
    exists (witness_at_for_ord_form o).
    exists (witness_at_for_ord_proof o).
    pose proof (witness_at_for_ord_bound o Hwf) as Hbound.
    unfold ord_le in Hbound. unfold proof_height, vord_le.
    destruct (ord_compare o (proof_height_ord (witness_at_for_ord_form o)
                                              (witness_at_for_ord_proof o)))
      eqn:Hcmp.
    + left. f_equal. apply ord_compare_eq_iff. exact Hcmp.
    + right. apply VL_cnf. exact Hcmp.
    + exfalso. apply Hbound. reflexivity.
  - exfalso. unfold veps0 in Hlt.
    apply vord_lt_V_phi_inv in Hlt.
    destruct Hlt as [[o Heq] | [[n' [α' [Heq Hlt_n]]] | [α' [Heq Hlt_α]]]].
    + discriminate.
    + injection Heq as En _. subst n'. lia.
    + injection Heq as En _. subst n.
      destruct α' as [|αe αt]; unfold ord_lt in Hlt_α; cbn in Hlt_α; discriminate.
  - exfalso. unfold veps0 in Hlt.
    apply vord_lt_V_phi_inv in Hlt.
    destruct Hlt as [[o Heq] | [[n' [α' [Heq Hlt_n]]] | [α' [Heq Hlt_α]]]];
      discriminate.
Qed.


(******************************************************************************)
(* Genuine Gamma_0 (todo #9).                                                  *)
(*                                                                            *)
(* [Gamma_0_ordinal = V_gamma0] is the new top atom of the Veblen carrier:    *)
(* strictly above every [V_phi n alpha] (in particular above the whole        *)
(* phi-tower of Gamma_0-approximations [vgamma0_approx n]) and the LEAST      *)
(* such point of the carrier.  It is provably distinct from the eps_0 atom    *)
(* and from every CNF tree, discharging the forbidden-alias clauses.          *)
(******************************************************************************)

Theorem Gamma_0_is_V_gamma0 : Gamma_0_ordinal = V_gamma0.
Proof. reflexivity. Qed.

Theorem Gamma_0_not_eps0 : Gamma_0_ordinal <> veps0.
Proof. discriminate. Qed.

Theorem Gamma_0_not_cnf_shape : forall o, Gamma_0_ordinal <> V_cnf o.
Proof. intros o H. discriminate H. Qed.

Theorem Gamma_0_not_Veblen_eps0_alias :
  Gamma_0_ordinal <> V_cnf Veblen_eps0_ordinal.
Proof. apply Gamma_0_not_cnf_shape. Qed.

Theorem Gamma_0_wf : wf_vord Gamma_0_ordinal.
Proof. exact I. Qed.

Theorem Gamma_0_above_phi_tower : forall n alpha,
  vord_lt (V_phi n alpha) Gamma_0_ordinal.
Proof. intros n alpha. apply VL_phi_g0. Qed.

Theorem Gamma_0_above_eps0 : vord_lt veps0 Gamma_0_ordinal.
Proof. apply VL_phi_g0. Qed.

Theorem Gamma_0_above_gamma0_approx : forall n,
  vord_lt (vgamma0_approx n) Gamma_0_ordinal.
Proof. intro n. apply VL_phi_g0. Qed.

(** Leastness: any vord lying strictly above EVERY phi-tower stage
    [vgamma0_approx n] is at least [Gamma_0_ordinal].  This is the
    "first (common) fixed point above the phi-tower" characterisation
    inside the notation system: Gamma_0 is the least upper bound of
    the family phi_(n+1)(0). *)

Theorem Gamma_0_least_above_phi_tower : forall v,
  (forall n, vord_lt (vgamma0_approx n) v) ->
  vord_le Gamma_0_ordinal v.
Proof.
  intros v H.
  destruct v as [o | m alpha |].
  - exfalso. pose proof (H 0) as H0.
    apply vord_lt_V_cnf_inv in H0.
    destruct H0 as [o' [Heq _]]. discriminate.
  - exfalso. pose proof (H (S m)) as HSm.
    unfold vgamma0_approx in HSm.
    apply vord_lt_V_phi_inv in HSm.
    destruct HSm as [[o Heq] | [[n' [a' [Heq Hlt]]] | [a' [Heq Hlt]]]].
    + discriminate.
    + injection Heq as E1 E2. lia.
    + injection Heq as E1 E2. lia.
  - left. reflexivity.
Qed.

(** The omega_pow proof-height measure is strictly below the eps_0 atom
    — so the Gamma_0 upper bound [GLP_proof_height_below_Gamma_0] is
    genuine but NOT tight, with [veps0] witnessing the gap. *)

Theorem proof_height_below_eps0 : forall phi (pt : Provable_term phi),
  vord_lt (proof_height phi pt) veps0.
Proof.
  intros phi pt. unfold proof_height, veps0. apply VL_cnf_phi.
Qed.

Theorem Gamma_0_bound_not_tight :
  (forall phi (pt : Provable_term phi), vord_lt (proof_height phi pt) veps0) /\
  vord_lt veps0 Gamma_0_ordinal.
Proof.
  split.
  - exact proof_height_below_eps0.
  - exact Gamma_0_above_eps0.
Qed.

(** Exactness of the omega_pow measure at eps_0: heights are bounded by
    the eps_0 atom, and every well-formed CNF threshold strictly below
    it is attained by an explicit primitive-recursive witness. *)

Theorem proof_height_eps0_exact :
  (forall phi (pt : Provable_term phi), vord_lt (proof_height phi pt) veps0) /\
  (forall o, wf_ord o ->
     exists phi (pt : Provable_term phi),
       vord_le (V_cnf o) (proof_height phi pt)).
Proof.
  split.
  - exact proof_height_below_eps0.
  - intros o Hwf.
    destruct (witness_at_below_eps0 (V_cnf o) Hwf (cnf_below_veps0 o))
      as [phi [pt Hle]].
    exists phi, pt. exact Hle.
Qed.

(******************************************************************************)
(* Acceptance-literal height measure (todo #9): Loeb leaves at rank omega,    *)
(* all other axiom leaves at rank 1, MP = successor of the sup (ord_max) of   *)
(* the children, Nec = successor of the child.  Its exact supremum is         *)
(* omega * 2, computed below: every height is strictly below omega_two and    *)
(* every omega + n is attained by the explicit Nec-tower over a Loeb leaf.    *)
(******************************************************************************)

Definition ord_one : ord := OCons OZero OZero.

Definition omega_plus (n : nat) : ord := OCons ord_one (nat_to_ord n).

Definition omega_two : ord := OCons ord_one (OCons ord_one OZero).

Fixpoint proof_height_lit (phi : Form) (pt : Provable_term phi) : ord :=
  match pt with
  | pt_K _ _      => ord_one
  | pt_S _ _ _    => ord_one
  | pt_DN _       => ord_one
  | pt_BoxK _ _ _ => ord_one
  | pt_Loeb _ _   => omega_cnf
  | pt_Box4 _ _   => ord_one
  | pt_Mon _ _    => ord_one
  | pt_NextCon _  => ord_one
  | pt_MP _ _ p1 p2 =>
      succ_cnf (ord_max (proof_height_lit _ p1) (proof_height_lit _ p2))
  | pt_Nec _ _ p => succ_cnf (proof_height_lit _ p)
  end.

Lemma succ_cnf_shape : forall t, exists e t', succ_cnf t = OCons e t'.
Proof. intros [|e t]; cbn; eauto. Qed.

Lemma succ_cnf_nat_to_ord : forall n,
  succ_cnf (nat_to_ord n) = nat_to_ord (S n).
Proof.
  induction n as [|n IH]; cbn.
  - reflexivity.
  - rewrite IH. reflexivity.
Qed.

Lemma succ_omega_plus : forall n,
  succ_cnf (omega_plus n) = omega_plus (S n).
Proof.
  intro n. unfold omega_plus. cbn.
  rewrite succ_cnf_nat_to_ord. reflexivity.
Qed.

Lemma nat_to_ord_le : forall a b,
  a <= b -> ord_le (nat_to_ord a) (nat_to_ord b).
Proof.
  intros a b Hle.
  destruct (Nat.eq_dec a b) as [Heq | Hne].
  - subst b. apply ord_le_refl.
  - apply ord_lt_le. apply nat_to_ord_strict_lt. lia.
Qed.

Lemma omega_plus_le_mono : forall a b,
  a <= b -> ord_le (omega_plus a) (omega_plus b).
Proof.
  intros a b Hle. unfold omega_plus.
  apply ord_le_OCons_when_eq_leading.
  apply nat_to_ord_le. exact Hle.
Qed.

Lemma ord_one_le_omega_plus : forall n, ord_le ord_one (omega_plus n).
Proof.
  intro n. apply ord_lt_le.
  unfold ord_lt, ord_one, omega_plus. cbn. reflexivity.
Qed.

Lemma omega_cnf_le_omega_plus : forall n, ord_le omega_cnf (omega_plus n).
Proof.
  intro n. unfold omega_cnf, omega_plus, ord_one.
  apply ord_le_OCons_when_eq_leading.
  unfold ord_le. apply ord_compare_OZero_le.
Qed.

Lemma ord_max_le_combine : forall x y a b,
  ord_le x (omega_plus a) ->
  ord_le y (omega_plus b) ->
  ord_le (ord_max x y) (omega_plus (Nat.max a b)).
Proof.
  intros x y a b Hx Hy. unfold ord_max.
  destruct (ord_compare x y).
  - eapply ord_le_trans; [exact Hx | apply omega_plus_le_mono; lia].
  - eapply ord_le_trans; [exact Hy | apply omega_plus_le_mono; lia].
  - eapply ord_le_trans; [exact Hx | apply omega_plus_le_mono; lia].
Qed.

Lemma succ_cnf_compare : forall a b,
  ord_compare (succ_cnf a) (succ_cnf b) = ord_compare a b.
Proof.
  induction a as [|ae IHae at_ IHat]; intros b; destruct b as [|be bt]; cbn.
  - reflexivity.
  - destruct be; cbn.
    + destruct (succ_cnf_shape bt) as [e [t' E]]. rewrite E. reflexivity.
    + reflexivity.
  - destruct ae; cbn.
    + destruct (succ_cnf_shape at_) as [e [t' E]]. rewrite E. reflexivity.
    + reflexivity.
  - rewrite IHat. destruct (ord_compare ae be); reflexivity.
Qed.

Lemma succ_cnf_le_mono : forall a b,
  ord_le a b -> ord_le (succ_cnf a) (succ_cnf b).
Proof.
  intros a b H. unfold ord_le in *.
  rewrite succ_cnf_compare. exact H.
Qed.

(** Heights of the literal measure are bounded by omega + proof length. *)

Lemma proof_height_lit_le_length : forall phi (pt : Provable_term phi),
  ord_le (proof_height_lit phi pt) (omega_plus (Provable_term_length phi pt)).
Proof.
  intros phi pt.
  induction pt; cbn [proof_height_lit Provable_term_length].
  - exact (ord_one_le_omega_plus 1).
  - exact (ord_one_le_omega_plus 1).
  - exact (ord_one_le_omega_plus 1).
  - exact (ord_one_le_omega_plus 1).
  - exact (omega_cnf_le_omega_plus 1).
  - exact (ord_one_le_omega_plus 1).
  - exact (ord_one_le_omega_plus 1).
  - exact (ord_one_le_omega_plus 1).
  - eapply ord_le_trans.
    + apply succ_cnf_le_mono.
      eapply ord_max_le_combine; eassumption.
    + rewrite succ_omega_plus. apply omega_plus_le_mono. lia.
  - eapply ord_le_trans.
    + apply succ_cnf_le_mono. eassumption.
    + rewrite succ_omega_plus. apply ord_le_refl.
Qed.

Lemma omega_plus_lt_omega_two : forall n,
  ord_lt (omega_plus n) omega_two.
Proof.
  intro n. unfold ord_lt, omega_plus, omega_two, ord_one. cbn.
  destruct n as [|m]; cbn; reflexivity.
Qed.

Theorem proof_height_lit_below_omega_two :
  forall phi (pt : Provable_term phi),
  ord_lt (proof_height_lit phi pt) omega_two.
Proof.
  intros phi pt.
  eapply ord_le_lt_trans.
  - apply proof_height_lit_le_length.
  - apply omega_plus_lt_omega_two.
Qed.

(** The explicit Nec-tower over a Loeb leaf attains omega + n exactly. *)

Fixpoint loeb_tower_form (n : nat) : Form :=
  match n with
  | 0 => Impl (Box 0 (Impl (Box 0 Bot) Bot)) (Box 0 Bot)
  | S k => Box 0 (loeb_tower_form k)
  end.

Fixpoint loeb_tower (n : nat) : Provable_term (loeb_tower_form n) :=
  match n return Provable_term (loeb_tower_form n) with
  | 0 => pt_Loeb 0 Bot
  | S k => pt_Nec 0 (loeb_tower_form k) (loeb_tower k)
  end.

Lemma loeb_tower_height : forall n,
  proof_height_lit (loeb_tower_form n) (loeb_tower n) = omega_plus n.
Proof.
  induction n as [|n IH]; cbn [loeb_tower proof_height_lit].
  - unfold omega_cnf, omega_plus, ord_one. reflexivity.
  - rewrite IH. apply succ_omega_plus.
Qed.

(** Exactness package: the literal measure's supremum is omega * 2 —
    bounded strictly below omega_two, with every omega + n attained. *)

Theorem proof_height_lit_sup_omega_two :
  (forall phi (pt : Provable_term phi),
     ord_lt (proof_height_lit phi pt) omega_two) /\
  (forall n, exists phi (pt : Provable_term phi),
     proof_height_lit phi pt = omega_plus n).
Proof.
  split.
  - exact proof_height_lit_below_omega_two.
  - intro n. exists (loeb_tower_form n), (loeb_tower n).
    apply loeb_tower_height.
Qed.

(** Non-degeneracy: the literal measure never returns OZero and is not
    a constant function of the derivation — discharging the forbidden
    trivialisations of todo #9. *)

Lemma proof_height_lit_shape : forall phi (pt : Provable_term phi),
  exists e t, proof_height_lit phi pt = OCons e t.
Proof.
  intros phi pt. destruct pt; cbn.
  - unfold ord_one. eauto.
  - unfold ord_one. eauto.
  - unfold ord_one. eauto.
  - unfold ord_one. eauto.
  - unfold omega_cnf. eauto.
  - unfold ord_one. eauto.
  - unfold ord_one. eauto.
  - unfold ord_one. eauto.
  - apply succ_cnf_shape.
  - apply succ_cnf_shape.
Qed.

Theorem proof_height_lit_never_zero : forall phi (pt : Provable_term phi),
  proof_height_lit phi pt <> OZero.
Proof.
  intros phi pt H.
  destruct (proof_height_lit_shape phi pt) as [e [t E]].
  rewrite E in H. discriminate.
Qed.

Theorem proof_height_lit_not_constant :
  proof_height_lit _ (loeb_tower 0) <> proof_height_lit _ (loeb_tower 1).
Proof.
  rewrite (loeb_tower_height 0), (loeb_tower_height 1).
  unfold omega_plus. cbn.
  intro H. injection H as H1. discriminate H1.
Qed.

(** The literal measure also sits strictly below the genuine Gamma_0
    atom (the todo #9 headline restated for this measure), and the
    Gamma_0 bound is again not tight: heights are V_cnf images, hence
    already strictly below the eps_0 atom. *)

Theorem GLP_proof_height_lit_below_Gamma_0 :
  forall phi (pt : Provable_term phi),
  vord_lt (V_cnf (proof_height_lit phi pt)) Gamma_0_ordinal.
Proof.
  intros phi pt. apply VL_cnf_g0.
Qed.

Theorem proof_height_lit_below_eps0 :
  forall phi (pt : Provable_term phi),
  vord_lt (V_cnf (proof_height_lit phi pt)) veps0.
Proof.
  intros phi pt. apply VL_cnf_phi.
Qed.

(** Bridge for the Prop-level provability predicate: [proof_height]
    cannot be a function out of [|- phi] (large elimination from Prop
    into Type is impossible), but every Provable formula admits SOME
    derivation height, strictly below omega_two, hence below eps_0 and
    Gamma_0. *)

Theorem proof_height_lit_bound_for_provable : forall phi,
  |- phi ->
  exists o : ord,
    ord_lt o omega_two /\
    exists pt : Provable_term phi, proof_height_lit phi pt = o.
Proof.
  intros phi Hp.
  destruct (provable_to_inhabited_Provable_term phi Hp) as [pt].
  exists (proof_height_lit phi pt). split.
  - apply proof_height_lit_below_omega_two.
  - exists pt. reflexivity.
Qed.

(** ** Decidability infrastructure for full GLP*: fragment deciders,
    the Fnat-closed bounded semantics, worm implications, the I2 frame,
    and the measure-recursive decider for box-towers over box-free
    leaves. *)

Fixpoint form_length (phi : Form) : nat :=
  match phi with
  | Var _ => 1
  | Bot => 1
  | Impl X Y => S (form_length X + form_length Y)
  | Box _ psi => S (form_length psi)
  end.

Lemma form_length_pos : forall phi, form_length phi >= 1.
Proof. intro phi. destruct phi; cbn; lia. Qed.

(** ** Closed box-free [forces_fnat_closed] equals [eval]. *)

Lemma forces_fnat_closed_box_free_eq_eval : forall phi,
  free_vars phi = [] -> box_free phi ->
  forall w val, forces_fnat_closed phi w = eval val phi.
Proof.
  intro phi. induction phi as [k | | X IHX Y IHY | n psi IHpsi];
    intros Hcl Hbf w val; cbn in *.
  - discriminate Hcl.
  - reflexivity.
  - apply app_eq_nil in Hcl. destruct Hcl as [HclX HclY].
    destruct Hbf as [HbfX HbfY].
    rewrite (IHX HclX HbfX w val), (IHY HclY HbfY w val). reflexivity.
  - exfalso. exact Hbf.
Qed.

(** ** Closed box-free FMP. *)

Theorem closed_box_free_FMP : forall phi,
  free_vars phi = [] -> box_free phi ->
  ((forall w, forces_fnat_closed phi w = true) <-> |- phi).
Proof.
  intros phi Hcl Hbf. split.
  - intros Hall. apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
    intro val.
    rewrite <- (forces_fnat_closed_box_free_eq_eval phi Hcl Hbf 0 val).
    exact (Hall 0).
  - intros Hp w. exact (provable_implies_forces_fnat_closed phi w Hcl Hp).
Qed.

Definition glp_decide_closed_box_free (phi : Form)
  (Hcl : free_vars phi = []) (Hbf : box_free phi) :
  sumbool (|- phi) (~ |- phi).
Proof.
  destruct (decide_tautology phi) eqn:Eq.
  - left. apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
    apply decide_tautology_correct. exact Eq.
  - right. intro Hp.
    pose proof (provable_classically_valid phi Hp) as Hcv.
    pose proof (decide_tautology_complete phi Hcv) as Heq.
    rewrite Eq in Heq. discriminate.
Defined.

(** ** Iterated boxes. *)

Lemma iter_box_closed : forall ns psi,
  free_vars psi = [] -> free_vars (iter_box ns psi) = [].
Proof.
  intro ns. induction ns as [|n rest IH]; intros psi Hcl; cbn.
  - exact Hcl.
  - exact (IH psi Hcl).
Qed.

Lemma provable_iter_box_intro : forall ns psi,
  |- psi -> |- iter_box ns psi.
Proof.
  intro ns. induction ns as [|n rest IH]; intros psi Hp; cbn.
  - exact Hp.
  - exact (Nec n _ (IH psi Hp)).
Qed.

(** [forces_fnat_closed (iter_box ns psi) v = true] uniformly when [eval val psi = true]. *)

Lemma forces_iter_box_eval_true_uniform : forall ns psi val,
  free_vars psi = [] -> box_free psi -> eval val psi = true ->
  forall v, forces_fnat_closed (iter_box ns psi) v = true.
Proof.
  intro ns. induction ns as [|n rest IH]; intros psi val Hcl Hbf Heval v; cbn.
  - rewrite (forces_fnat_closed_box_free_eq_eval psi Hcl Hbf v val). exact Heval.
  - apply forallb_forall. intros u _.
    exact (IH psi val Hcl Hbf Heval u).
Qed.

Fixpoint bad_world (ns : list nat) : nat :=
  match ns with
  | [] => 0
  | n :: rest => S (Nat.max n (bad_world rest))
  end.

Lemma forces_iter_box_at_bad_world : forall ns psi val,
  free_vars psi = [] -> box_free psi ->
  forall v, v >= bad_world ns ->
  forces_fnat_closed (iter_box ns psi) v = eval val psi.
Proof.
  intro ns. induction ns as [|n rest IH]; intros psi val Hcl Hbf v Hv.
  - cbn. exact (forces_fnat_closed_box_free_eq_eval psi Hcl Hbf v val).
  - destruct (eval val psi) eqn:Eeval.
    + exact (forces_iter_box_eval_true_uniform (n :: rest) psi val Hcl Hbf Eeval v).
    + cbn [iter_box bad_world] in *. cbn [forces_fnat_closed].
      destruct (forallb _ _) eqn:Efb; [|reflexivity].
      exfalso. rewrite forallb_forall in Efb.
      assert (Hin : In (v - 1) (seq n (v - n))).
      { apply in_seq. lia. }
      pose proof (Efb (v - 1) Hin) as Hf.
      assert (Hbnd : v - 1 >= bad_world rest) by lia.
      pose proof (IH psi val Hcl Hbf (v - 1) Hbnd) as Hihv.
      rewrite Hihv in Hf. rewrite Eeval in Hf. discriminate.
Qed.

(** ** Iter-box closed-box-free FMP / decidability. *)

Theorem provable_iter_box_box_free_iff : forall ns psi,
  free_vars psi = [] -> box_free psi ->
  (|- iter_box ns psi) <-> (|- psi).
Proof.
  intros ns psi Hcl Hbf. split.
  - intros Hp.
    apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
    intro val.
    pose proof (provable_implies_forces_fnat_closed (iter_box ns psi)
                  (bad_world ns) (iter_box_closed ns psi Hcl) Hp) as Hf.
    rewrite (forces_iter_box_at_bad_world ns psi val Hcl Hbf
               (bad_world ns) (Nat.le_refl _)) in Hf.
    exact Hf.
  - exact (provable_iter_box_intro ns psi).
Qed.

Definition glp_decide_iter_box_closed_box_free (ns : list nat) (psi : Form)
  (Hcl : free_vars psi = []) (Hbf : box_free psi) :
  sumbool (|- iter_box ns psi) (~ |- iter_box ns psi).
Proof.
  destruct (glp_decide_closed_box_free psi Hcl Hbf) as [Hp | Hnp].
  - left. exact (provable_iter_box_intro ns psi Hp).
  - right. intro Habs. apply Hnp.
    exact (proj1 (provable_iter_box_box_free_iff ns psi Hcl Hbf) Habs).
Defined.

(** ** Carlson-generalised unprovability of [Neg (Box n X)] for any closed [X].
    Carlson's polymodal second-incompleteness corresponds to [X = Bot]; the
    same Fnat-at-world-0 argument refutes [|- Neg (Box n X)] for arbitrary
    closed [X], because [forces_fnat_closed (Box n X) 0] is vacuously [true]. *)

Theorem closed_neg_box_unprovable : forall n X,
  free_vars X = [] -> ~ |- Neg (Box n X).
Proof.
  intros n X Hcl Hp.
  assert (Hclneg : free_vars (Neg (Box n X)) = []).
  { unfold Neg. cbn. rewrite app_nil_r. exact Hcl. }
  pose proof (provable_implies_forces_fnat_closed (Neg (Box n X)) 0 Hclneg Hp) as Hf.
  cbn in Hf. discriminate.
Qed.

(** ** Decidability of [Neg (Box n X)] for closed [X]: always [right]. *)

Definition glp_decide_neg_box_closed (n : nat) (X : Form)
  (Hcl : free_vars X = []) :
  sumbool (|- Neg (Box n X)) (~ |- Neg (Box n X)).
Proof.
  right. exact (closed_neg_box_unprovable n X Hcl).
Defined.

(** ** Decidability composition for And: combine two decidability results. *)

Definition glp_decide_and (phi psi : Form)
  (Dphi : sumbool (|- phi) (~ |- phi))
  (Dpsi : sumbool (|- psi) (~ |- psi)) :
  sumbool (|- And phi psi) (~ |- And phi psi).
Proof.
  destruct Dphi as [Hphi | Hphi]; destruct Dpsi as [Hpsi | Hpsi].
  - left. exact (prov_and_intro_meta phi psi Hphi Hpsi).
  - right. intro Hand. apply Hpsi. exact (prov_and_elim_r_meta phi psi Hand).
  - right. intro Hand. apply Hphi. exact (prov_and_elim_l_meta phi psi Hand).
  - right. intro Hand. apply Hphi. exact (prov_and_elim_l_meta phi psi Hand).
Defined.

(** ** Decidability composition for Iff: both directions decidable. *)

Definition glp_decide_iff (phi psi : Form)
  (Dfwd : sumbool (|- Impl phi psi) (~ |- Impl phi psi))
  (Dbwd : sumbool (|- Impl psi phi) (~ |- Impl psi phi)) :
  sumbool (|- Iff phi psi) (~ |- Iff phi psi).
Proof.
  unfold Iff. exact (glp_decide_and (Impl phi psi) (Impl psi phi) Dfwd Dbwd).
Defined.

(** ** Decidability of [Impl phi psi] when the consequent is provable. *)

Definition glp_decide_impl_consequent_provable (phi psi : Form)
  (Hpsi : |- psi) :
  sumbool (|- Impl phi psi) (~ |- Impl phi psi).
Proof.
  left. exact (MP _ _ (Ax_K psi phi) Hpsi).
Defined.

(** ** Decidability of [Impl phi psi] when the antecedent is provable
    and the consequent's provability status is decidable. *)

Definition glp_decide_impl_antecedent_provable (phi psi : Form)
  (Hphi : |- phi)
  (Dpsi : sumbool (|- psi) (~ |- psi)) :
  sumbool (|- Impl phi psi) (~ |- Impl phi psi).
Proof.
  destruct Dpsi as [Hpsi | Hnpsi].
  - left. exact (MP _ _ (Ax_K psi phi) Hpsi).
  - right. intro Himp. apply Hnpsi. exact (MP _ _ Himp Hphi).
Defined.

(** ** Decidability for [Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2)]
    when [psi_2] is provable: the consequent is provable, so the implication
    is provable by [Ax_K]. *)

Definition glp_decide_impl_iter_box_via_consequent_provable
  (ns_1 ns_2 : list nat) (psi_1 psi_2 : Form)
  (Hp_2 : |- psi_2) :
  sumbool (|- Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2))
          (~ |- Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2)).
Proof.
  left.
  exact (MP _ _ (Ax_K _ (iter_box ns_1 psi_1))
                (provable_iter_box_intro ns_2 psi_2 Hp_2)).
Defined.

(** ** Decidability for [Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2)]
    when [psi_1] is provable but [psi_2] is not (with [psi_2] closed
    box-free): the antecedent is provable and consequent is not, so
    the implication cannot be provable (would yield [|- iter_box ns_2 psi_2]
    via MP, contradicting [~ |- psi_2] under [provable_iter_box_box_free_iff]). *)

Definition glp_decide_impl_iter_box_via_antecedent_provable_consequent_not
  (ns_1 ns_2 : list nat) (psi_1 psi_2 : Form)
  (Hcl_2 : free_vars psi_2 = []) (Hbf_2 : box_free psi_2)
  (Hp_1 : |- psi_1) (Hnp_2 : ~ |- psi_2) :
  sumbool (|- Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2))
          (~ |- Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2)).
Proof.
  right. intro Himp. apply Hnp_2.
  apply (proj1 (provable_iter_box_box_free_iff ns_2 psi_2 Hcl_2 Hbf_2)).
  apply (MP _ _ Himp).
  exact (provable_iter_box_intro ns_1 psi_1 Hp_1).
Defined.

(** ** [And] of two iterated-box closed-box-free formulas: provable iff both
    inner formulas are classically valid. *)

Definition glp_decide_and_iter_box_box_free
  (ns_1 ns_2 : list nat) (psi_1 psi_2 : Form)
  (Hcl_1 : free_vars psi_1 = []) (Hbf_1 : box_free psi_1)
  (Hcl_2 : free_vars psi_2 = []) (Hbf_2 : box_free psi_2) :
  sumbool (|- And (iter_box ns_1 psi_1) (iter_box ns_2 psi_2))
          (~ |- And (iter_box ns_1 psi_1) (iter_box ns_2 psi_2)).
Proof.
  apply glp_decide_and.
  - exact (glp_decide_iter_box_closed_box_free ns_1 psi_1 Hcl_1 Hbf_1).
  - exact (glp_decide_iter_box_closed_box_free ns_2 psi_2 Hcl_2 Hbf_2).
Defined.

(** ** [Iff] of two iterated-box closed-box-free formulas: each direction
    is decidable when one of the cases (valid consequent, or
    valid antecedent + invalid consequent) applies. *)

(** ** [forces_fnat_closed (Box k Bot)] reduces to [Nat.leb w k]. *)

Lemma forces_box_bot_eq_leb : forall k w,
  forces_fnat_closed (Box k Bot) w = Nat.leb w k.
Proof.
  intros k w. cbn.
  destruct (Nat.leb w k) eqn:Eq.
  - apply Nat.leb_le in Eq.
    assert (Hempty : seq k (w - k) = []).
    { assert (w - k = 0) by lia. rewrite H. reflexivity. }
    rewrite Hempty. reflexivity.
  - apply Nat.leb_nle in Eq.
    destruct (forallb _ _) eqn:Efb; [|reflexivity].
    rewrite forallb_forall in Efb.
    assert (Hin : In k (seq k (w - k))).
    { apply in_seq. lia. }
    pose proof (Efb k Hin) as H. cbn in H. discriminate.
Qed.

(** ** [Impl (Box k_1 Bot) (Box k_2 Bot)] decidable: provable iff [k_1 <= k_2]. *)

Lemma decide_impl_box_bot_box_bot_le : forall k_1 k_2,
  k_1 <= k_2 -> |- Impl (Box k_1 Bot) (Box k_2 Bot).
Proof.
  intros k_1 k_2 Hle. exact (prov_box_mon_le k_1 k_2 Bot Hle).
Qed.

Lemma decide_impl_box_bot_box_bot_gt : forall k_1 k_2,
  k_1 > k_2 -> ~ |- Impl (Box k_1 Bot) (Box k_2 Bot).
Proof.
  intros k_1 k_2 Hgt Hp.
  pose proof (soundness _ Hp Fnat (fun _ _ => true) (S k_2)) as Hf.
  cbn in Hf.
  assert (Hk1 : forall v, Fnat_R k_1 (S k_2) v -> False).
  { intros v Hr. unfold Fnat_R in Hr. lia. }
  apply (Hf (fun v Hr => False_ind _ (Hk1 v Hr)) k_2).
  unfold Fnat_R. split; lia.
Qed.

Definition glp_decide_impl_box_bot_box_bot (k_1 k_2 : nat) :
  sumbool (|- Impl (Box k_1 Bot) (Box k_2 Bot))
          (~ |- Impl (Box k_1 Bot) (Box k_2 Bot)).
Proof.
  destruct (le_gt_dec k_1 k_2) as [Hle | Hgt].
  - left. exact (decide_impl_box_bot_box_bot_le k_1 k_2 Hle).
  - right. exact (decide_impl_box_bot_box_bot_gt k_1 k_2 Hgt).
Defined.

(** ** Eval of closed box-free formulas is independent of the valuation. *)

Lemma eval_box_free_closed_const : forall phi val_1 val_2,
  free_vars phi = [] -> box_free phi ->
  eval val_1 phi = eval val_2 phi.
Proof.
  intros phi val_1 val_2 Hcl Hbf.
  rewrite <- (forces_fnat_closed_box_free_eq_eval phi Hcl Hbf 0 val_1).
  rewrite <- (forces_fnat_closed_box_free_eq_eval phi Hcl Hbf 0 val_2).
  reflexivity.
Qed.

(** ** For closed box-free [psi], unprovability implies provability of [Neg psi]. *)

Lemma not_provable_implies_provable_neg_closed_box_free : forall psi,
  free_vars psi = [] -> box_free psi -> ~ |- psi -> |- Neg psi.
Proof.
  intros psi Hcl Hbf Hnp.
  apply trivial_in_provable. apply prop_completeness.
  - cbn. split; [exact Hbf | exact I].
  - intro val. cbn.
    destruct (eval val psi) eqn:E.
    + exfalso. apply Hnp.
      apply trivial_in_provable.
      apply prop_completeness; [exact Hbf|].
      intro val'.
      pose proof (eval_box_free_closed_const psi val' val Hcl Hbf) as Heq.
      rewrite Heq. exact E.
    + reflexivity.
Qed.

(** ** When [|- Neg psi], [Box k psi] is provably equivalent to [Box k Bot]. *)

Lemma box_psi_iff_box_bot_when_neg_provable : forall k psi,
  |- Neg psi -> |- Iff (Box k psi) (Box k Bot).
Proof.
  intros k psi Hneg.
  apply prov_iff_intro.
  - exact (MP _ _ (Ax_BoxK k psi Bot) (Nec k _ Hneg)).
  - exact (MP _ _ (Ax_BoxK k Bot psi) (Nec k _ (prov_explosion psi))).
Qed.

(** ** Decidability of [Impl (Box k_1 psi) (Box k_2 psi)] for closed box-free
    [psi].  Provable iff [|- psi] OR [k_1 <= k_2]; refuted by Fnat-soundness
    when [psi] is unprovable and [k_1 > k_2]. *)

Definition glp_decide_impl_box_box_box_free_same_psi
  (k_1 k_2 : nat) (psi : Form)
  (Hcl : free_vars psi = []) (Hbf : box_free psi) :
  sumbool (|- Impl (Box k_1 psi) (Box k_2 psi))
          (~ |- Impl (Box k_1 psi) (Box k_2 psi)).
Proof.
  destruct (glp_decide_closed_box_free psi Hcl Hbf) as [Hp | Hnp].
  - left. exact (MP _ _ (Ax_K (Box k_2 psi) (Box k_1 psi)) (Nec k_2 psi Hp)).
  - destruct (le_gt_dec k_1 k_2) as [Hle | Hgt].
    + left. exact (prov_box_mon_le k_1 k_2 psi Hle).
    + right. intro Himp.
      pose proof (soundness _ Himp Fnat (fun _ _ => true) (S k_2)) as Hf.
      cbn in Hf.
      assert (Hbox1 : forall v, Fnat_R k_1 (S k_2) v ->
                       forces Fnat (fun _ _ => true) v psi).
      { intros v Hr. unfold Fnat_R in Hr. lia. }
      pose proof (Hf Hbox1) as Hbox2.
      assert (Hr : Fnat_R k_2 (S k_2) k_2) by (unfold Fnat_R; split; lia).
      pose proof (Hbox2 k_2 Hr) as Hpsi_at_k2.
      apply Hnp.
      apply trivial_in_provable.
      apply prop_completeness; [exact Hbf|].
      intro val.
      apply (proj1 (forces_const_box_free Fnat (fun _ : nat => true) k_2 psi Hbf))
        in Hpsi_at_k2.
      pose proof (eval_box_free_closed_const psi val (fun _ => true) Hcl Hbf) as Heq.
      rewrite Heq. exact Hpsi_at_k2.
Defined.

(** ** When [psi] is closed box-free and classically refutable, the iterated
    box [iter_box ns psi] forces in Fnat at exactly the worlds [v < bad_world ns]. *)

Lemma forces_iter_box_below_bad_world : forall ns psi val,
  free_vars psi = [] -> box_free psi -> eval val psi = false ->
  forall v, v < bad_world ns ->
  forces_fnat_closed (iter_box ns psi) v = true.
Proof.
  intro ns. induction ns as [|n rest IH]; intros psi val Hcl Hbf Heval v Hv.
  - cbn in Hv. lia.
  - cbn [iter_box bad_world] in *.
    cbn [forces_fnat_closed].
    apply forallb_forall. intros u Hu.
    apply in_seq in Hu. destruct Hu as [Hun Huv].
    apply (IH psi val Hcl Hbf Heval).
    lia.
Qed.

(** ** [forces_fnat_closed (iter_box ns Bot) v = true] iff [v < bad_world ns]. *)

Lemma forces_iter_box_bot_eq_ltb : forall ns v,
  forces_fnat_closed (iter_box ns Bot) v = Nat.ltb v (bad_world ns).
Proof.
  intros ns v.
  destruct (Nat.ltb v (bad_world ns)) eqn:Eq.
  - apply Nat.ltb_lt in Eq.
    apply (forces_iter_box_below_bad_world ns Bot (fun _ => false) eq_refl I eq_refl v Eq).
  - apply Nat.ltb_nlt in Eq.
    rewrite (forces_iter_box_at_bad_world ns Bot (fun _ => false) eq_refl I v); [|lia].
    reflexivity.
Qed.

(** ** Forward direction of the iter-box-Bot implication theorem:
    [|- (iter_box ns_1 Bot) -> (iter_box ns_2 Bot)] entails
    [bad_world ns_1 <= bad_world ns_2]. *)

Theorem provable_impl_iter_box_bot_forward : forall ns_1 ns_2,
  |- Impl (iter_box ns_1 Bot) (iter_box ns_2 Bot) ->
  bad_world ns_1 <= bad_world ns_2.
Proof.
  intros ns_1 ns_2 Hp.
  destruct (le_gt_dec (bad_world ns_1) (bad_world ns_2)) as [Hle | Hgt]; [exact Hle|].
  exfalso.
  assert (Hcl_impl : free_vars (Impl (iter_box ns_1 Bot) (iter_box ns_2 Bot)) = []).
  { cbn. rewrite (iter_box_closed ns_1 Bot eq_refl).
    exact (iter_box_closed ns_2 Bot eq_refl). }
  pose proof (provable_implies_forces_fnat_closed
                (Impl (iter_box ns_1 Bot) (iter_box ns_2 Bot))
                (bad_world ns_2) Hcl_impl Hp) as Hf.
  cbn [forces_fnat_closed] in Hf.
  rewrite forces_iter_box_bot_eq_ltb in Hf.
  rewrite forces_iter_box_bot_eq_ltb in Hf.
  assert (Hlt : Nat.ltb (bad_world ns_2) (bad_world ns_1) = true)
    by (apply Nat.ltb_lt; lia).
  assert (Hge : Nat.ltb (bad_world ns_2) (bad_world ns_2) = false)
    by (apply Nat.ltb_nlt; lia).
  rewrite Hlt, Hge in Hf. cbn in Hf. discriminate.
Qed.

(** ** Empty antecedent case is trivial via [Bot] explosion. *)

Lemma provable_impl_iter_box_bot_backward_empty : forall ns_2,
  |- Impl (iter_box [] Bot) (iter_box ns_2 Bot).
Proof.
  intros ns_2. cbn. exact (prov_explosion (iter_box ns_2 Bot)).
Qed.

(** ** Iterated [Mon] lift inside an iter-box wrapper. *)

Lemma provable_iter_box_mon_le : forall n m psi,
  n <= m -> |- Impl (iter_box [n] psi) (iter_box [m] psi).
Proof.
  intros n m psi Hle. cbn. exact (prov_box_mon_le n m psi Hle).
Qed.

(** ** Provable explosion under [Box]: if the inner antecedent is [Bot],
    the consequent of the box-implication can be anything at the same level. *)

Lemma prov_box_bot_to_box_anything : forall n psi,
  |- Impl (Box n Bot) (Box n psi).
Proof.
  intros n psi.
  pose proof (prov_explosion psi) as Hexp.
  pose proof (Nec n _ Hexp) as Hbox_exp.
  pose proof (Ax_BoxK n Bot psi) as HK.
  exact (MP _ _ HK Hbox_exp).
Qed.

(** ** Lifting [Box n Bot] to [Box m psi] when [n <= m]. *)

Lemma prov_box_bot_to_higher_box_anything : forall n m psi,
  n <= m -> |- Impl (Box n Bot) (Box m psi).
Proof.
  intros n m psi Hle.
  pose proof (prov_box_mon_le n m Bot Hle) as Hmon.
  pose proof (prov_box_bot_to_box_anything m psi) as Hexp.
  exact (prov_compose _ _ _ Hmon Hexp).
Qed.

(** ** Singleton-antecedent backward direction.  When the head of [ns_2]
    dominates [k], the entire iter-box-Bot implication is provable directly
    by [prov_box_bot_to_higher_box_anything].  This is a special case of the
    Beklemishev worm theorem, sufficient when the consequent worm absorbs
    the antecedent at its outermost layer. *)

Lemma provable_impl_box_bot_iter_box_bot_head_match :
  forall k m rest, k <= m ->
  |- Impl (Box k Bot) (iter_box (m :: rest) Bot).
Proof.
  intros k m rest Hle. cbn [iter_box].
  exact (prov_box_bot_to_higher_box_anything k m (iter_box rest Bot) Hle).
Qed.

(** ** Pointwise monotonicity for iter-box: if [ns_1] and [ns_2] have the
    same length and [ns_1[i] <= ns_2[i]] pointwise, the worm-implication
    follows from iterated [Mon] under [Nec]+[BoxK]. *)

Lemma prov_iter_box_pointwise_mon : forall ns_1 ns_2 psi,
  length ns_1 = length ns_2 ->
  (forall i, i < length ns_1 -> nth i ns_1 0 <= nth i ns_2 0) ->
  |- Impl (iter_box ns_1 psi) (iter_box ns_2 psi).
Proof.
  intro ns_1. induction ns_1 as [|n rest_1 IH]; intros ns_2 psi Hlen Hpt.
  - destruct ns_2 as [|m rest_2]; [|cbn in Hlen; discriminate Hlen].
    cbn. exact (prov_id psi).
  - destruct ns_2 as [|m rest_2]; [cbn in Hlen; discriminate Hlen|].
    cbn [length] in Hlen. injection Hlen as Hlen.
    assert (Hhead : n <= m).
    { apply (Hpt 0). cbn [length]. lia. }
    assert (Hrest_pt : forall i, i < length rest_1 -> nth i rest_1 0 <= nth i rest_2 0).
    { intros i Hi. apply (Hpt (S i)). cbn [length]. lia. }
    pose proof (IH rest_2 psi Hlen Hrest_pt) as Hinner.
    pose proof (Nec m _ Hinner) as Hboxed.
    pose proof (Ax_BoxK m (iter_box rest_1 psi) (iter_box rest_2 psi)) as HK.
    pose proof (MP _ _ HK Hboxed) as Hstep.
    pose proof (prov_box_mon_le n m (iter_box rest_1 psi) Hhead) as Hmon.
    cbn [iter_box].
    exact (prov_compose _ _ _ Hmon Hstep).
Qed.

(** ** Strengthening the inner formula under an iter-box wrapper.  Since
    [Bot] is the strongest closed antecedent, [|- iter_box ns Bot ->
    iter_box ns psi] for any [psi]: explosion at the leaf, lifted through
    the wrapper by [Nec] and [BoxK]. *)

Lemma prov_iter_box_inner_strengthen : forall ns psi,
  |- Impl (iter_box ns Bot) (iter_box ns psi).
Proof.
  intro ns. induction ns as [|n rest IH]; intro psi.
  - cbn. exact (prov_explosion psi).
  - cbn [iter_box].
    pose proof (IH psi) as Hinner.
    pose proof (Nec n _ Hinner) as Hboxed.
    pose proof (Ax_BoxK n (iter_box rest Bot) (iter_box rest psi)) as HK.
    exact (MP _ _ HK Hboxed).
Qed.

(** ** Worm-extension case.  Appending an extension to a worm preserves
    provability of the worm-implication: [|- iter_box ns Bot ->
    iter_box (ns ++ ext) Bot].  Follows from
    [iter_box (ns ++ ext) Bot = iter_box ns (iter_box ext Bot)] and
    [prov_iter_box_inner_strengthen]. *)

Lemma iter_box_app : forall ns_1 ns_2 psi,
  iter_box (ns_1 ++ ns_2) psi = iter_box ns_1 (iter_box ns_2 psi).
Proof.
  intro ns_1. induction ns_1 as [|n rest IH]; intros ns_2 psi.
  - cbn. reflexivity.
  - cbn [iter_box app]. rewrite IH. reflexivity.
Qed.

Lemma prov_iter_box_extension : forall ns ext,
  |- Impl (iter_box ns Bot) (iter_box (ns ++ ext) Bot).
Proof.
  intros ns ext. rewrite iter_box_app. exact (prov_iter_box_inner_strengthen ns (iter_box ext Bot)).
Qed.

(** ** Combined head-lift + worm-extension.  When [ns_1] is a "weakening"
    of a prefix of [ns_2] (both pointwise [<=] on the prefix and [ns_2] has
    additional boxes appended), the worm-implication is provable. *)

Lemma prov_iter_box_prefix_mon_extension : forall ns_1 prefix ext psi,
  length ns_1 = length prefix ->
  (forall i, i < length ns_1 -> nth i ns_1 0 <= nth i prefix 0) ->
  |- Impl (iter_box ns_1 Bot) (iter_box (prefix ++ ext) psi).
Proof.
  intros ns_1 prefix ext psi Hlen Hpt.
  pose proof (prov_iter_box_pointwise_mon ns_1 prefix Bot Hlen Hpt) as Hmon.
  rewrite iter_box_app.
  pose proof (prov_iter_box_inner_strengthen prefix (iter_box ext psi)) as Hstr.
  exact (prov_compose _ _ _ Hmon Hstr).
Qed.

(** ** Witness extraction from a [false] [forallb]. *)

Lemma forallb_false_witness : forall {A : Type} (f : A -> bool) (l : list A),
  forallb f l = false -> exists x, In x l /\ f x = false.
Proof.
  intros A f. induction l as [|x rest IH]; intro Hfb.
  - cbn in Hfb. discriminate Hfb.
  - cbn in Hfb. destruct (f x) eqn:Ef.
    + cbn in Hfb. destruct (IH Hfb) as [y [Hy_in Hy_f]].
      exists y. split; [right; exact Hy_in | exact Hy_f].
    + exists x. split; [left; reflexivity | exact Ef].
Qed.

(** ** Stabilization bound for closed [forces_fnat_closed].  Beyond [wbound
    phi], [forces_fnat_closed phi w] is constant (in [w]).  This gives a
    finite-window refutation: any closed Form refutable by [Fnat] is
    refutable by checking [w in [0, wbound phi]]. *)

Fixpoint wbound (phi : Form) : nat :=
  match phi with
  | Var _ => 0
  | Bot => 0
  | Impl X Y => Nat.max (wbound X) (wbound Y)
  | Box n psi => S (Nat.max n (wbound psi))
  end.

Lemma forces_fnat_closed_stabilizes : forall phi w_1 w_2,
  free_vars phi = [] ->
  w_1 >= wbound phi -> w_2 >= wbound phi ->
  forces_fnat_closed phi w_1 = forces_fnat_closed phi w_2.
Proof.
  intro phi.
  induction phi as [k | | X IHX Y IHY | n psi IHpsi];
    intros w_1 w_2 Hcl Hw1 Hw2.
  - cbn in Hcl. discriminate Hcl.
  - cbn. reflexivity.
  - cbn in Hcl. apply app_eq_nil in Hcl. destruct Hcl as [HclX HclY].
    cbn in Hw1, Hw2.
    assert (Hw1X : w_1 >= wbound X) by lia.
    assert (Hw1Y : w_1 >= wbound Y) by lia.
    assert (Hw2X : w_2 >= wbound X) by lia.
    assert (Hw2Y : w_2 >= wbound Y) by lia.
    cbn. rewrite (IHX w_1 w_2 HclX Hw1X Hw2X), (IHY w_1 w_2 HclY Hw1Y Hw2Y).
    reflexivity.
  - cbn in Hcl. cbn in Hw1, Hw2. cbn [forces_fnat_closed].
    destruct (forallb (fun v => forces_fnat_closed psi v) (seq n (w_1 - n))) eqn:Eb1;
      destruct (forallb (fun v => forces_fnat_closed psi v) (seq n (w_2 - n))) eqn:Eb2;
      try reflexivity; exfalso.
    + (* Eb1 = true, Eb2 = false: produce a witness in seq_w_2 violating, derive contradiction with Eb1. *)
      destruct (forallb_false_witness _ _ Eb2) as [v [Hin Hf]].
      apply in_seq in Hin. destruct Hin as [Hvn Hvw2].
      rewrite forallb_forall in Eb1.
      destruct (le_gt_dec (wbound psi) v) as [Hvge | Hvlt].
      * (* v >= wbound psi: stabilize via [max n (wbound psi)]. *)
        assert (Hin_max : In (Nat.max n (wbound psi)) (seq n (w_1 - n))) by (apply in_seq; lia).
        pose proof (Eb1 _ Hin_max) as Hf_max.
        assert (Hbnd_max : Nat.max n (wbound psi) >= wbound psi) by lia.
        pose proof (IHpsi (Nat.max n (wbound psi)) v Hcl Hbnd_max Hvge) as Heq.
        rewrite Heq in Hf_max. rewrite Hf in Hf_max. discriminate.
      * (* v < wbound psi: then v < w_1, so [v ∈ seq n (w_1 - n)]. *)
        assert (Hv_in_w1 : In v (seq n (w_1 - n))) by (apply in_seq; lia).
        pose proof (Eb1 _ Hv_in_w1) as Hf_at_v. rewrite Hf in Hf_at_v. discriminate.
    + (* Eb1 = false, Eb2 = true: symmetric. *)
      destruct (forallb_false_witness _ _ Eb1) as [v [Hin Hf]].
      apply in_seq in Hin. destruct Hin as [Hvn Hvw1].
      rewrite forallb_forall in Eb2.
      destruct (le_gt_dec (wbound psi) v) as [Hvge | Hvlt].
      * assert (Hin_max : In (Nat.max n (wbound psi)) (seq n (w_2 - n))) by (apply in_seq; lia).
        pose proof (Eb2 _ Hin_max) as Hf_max.
        assert (Hbnd_max : Nat.max n (wbound psi) >= wbound psi) by lia.
        pose proof (IHpsi (Nat.max n (wbound psi)) v Hcl Hbnd_max Hvge) as Heq.
        rewrite Heq in Hf_max. rewrite Hf in Hf_max. discriminate.
      * assert (Hv_in_w2 : In v (seq n (w_2 - n))) by (apply in_seq; lia).
        pose proof (Eb2 _ Hv_in_w2) as Hf_at_v. rewrite Hf in Hf_at_v. discriminate.
Qed.

(** ** Bounded-window characterization of universal [Fnat] validity. *)

Theorem forces_fnat_closed_universal_iff_bounded : forall phi,
  free_vars phi = [] ->
  ((forall w, forces_fnat_closed phi w = true) <->
   (forall w, w <= wbound phi -> forces_fnat_closed phi w = true)).
Proof.
  intros phi Hcl. split.
  - intros Hall w _. exact (Hall w).
  - intros Hbnd w. destruct (le_gt_dec w (wbound phi)) as [Hle | Hgt].
    + exact (Hbnd w Hle).
    + assert (Hwbnd : wbound phi >= wbound phi) by lia.
      assert (Hwgt : w >= wbound phi) by lia.
      rewrite (forces_fnat_closed_stabilizes phi w (wbound phi) Hcl Hwgt Hwbnd).
      exact (Hbnd (wbound phi) (Nat.le_refl _)).
Qed.

(** ** Bounded refutation: a closed [phi] with [forces_fnat_closed phi w =
    false] for some [w in [0, wbound phi]] is unprovable.  Sound but not
    complete: not every Fnat-valid closed [phi] is provable in GLP*. *)

Theorem closed_refutation_via_fnat : forall phi w,
  free_vars phi = [] -> w <= wbound phi ->
  forces_fnat_closed phi w = false -> ~ |- phi.
Proof.
  intros phi w Hcl _ Hf Hp.
  pose proof (provable_implies_forces_fnat_closed phi w Hcl Hp) as Hf'.
  rewrite Hf in Hf'. discriminate Hf'.
Qed.

(** ** Decidability of [forall w in [0, wbound phi], forces phi w = true].
    Bounded boolean check: returns [sumbool] indicating whether [phi] is
    Fnat-valid up to its stabilization threshold. *)

Lemma forces_bounded_decidable : forall phi,
  free_vars phi = [] ->
  sumbool (forall w, w <= wbound phi -> forces_fnat_closed phi w = true)
          (exists w, w <= wbound phi /\ forces_fnat_closed phi w = false).
Proof.
  intros phi Hcl.
  destruct (forallb (fun w => forces_fnat_closed phi w) (seq 0 (S (wbound phi)))) eqn:Eb.
  - left. intros w Hw.
    rewrite forallb_forall in Eb.
    apply Eb. apply in_seq. lia.
  - right.
    destruct (forallb_false_witness _ _ Eb) as [w [Hin Hf]].
    apply in_seq in Hin. destruct Hin as [_ Hwlt].
    exists w. split; [lia | exact Hf].
Qed.

(** ** Full decidability for [Impl (Box k_1 psi_1) (Box k_2 psi_2)] with
    closed box-free [psi_1, psi_2].  Four cases by the validity of each:
    (a) both valid: provable via Nec on [psi_2] then [Ax_K];
    (b) [psi_1] valid, [psi_2] not: refuted, since MP would give [|- psi_2];
    (c) [psi_1] not, [psi_2] valid: provable via Nec on [psi_2];
    (d) both not valid: each [Box k psi_i] is provably equivalent to
        [Box k Bot] (via [box_psi_iff_box_bot_when_neg_provable]), so the
        implication reduces to [Impl (Box k_1 Bot) (Box k_2 Bot)],
        decidable via [glp_decide_impl_box_bot_box_bot]. *)

Definition glp_decide_impl_box_box_box_free_general
  (k_1 k_2 : nat) (psi_1 psi_2 : Form)
  (Hcl_1 : free_vars psi_1 = []) (Hbf_1 : box_free psi_1)
  (Hcl_2 : free_vars psi_2 = []) (Hbf_2 : box_free psi_2) :
  sumbool (|- Impl (Box k_1 psi_1) (Box k_2 psi_2))
          (~ |- Impl (Box k_1 psi_1) (Box k_2 psi_2)).
Proof.
  destruct (glp_decide_closed_box_free psi_2 Hcl_2 Hbf_2) as [Hp2 | Hnp2].
  - (* psi_2 valid: |- Box k_2 psi_2 then Ax_K. *)
    left. exact (MP _ _ (Ax_K (Box k_2 psi_2) (Box k_1 psi_1)) (Nec k_2 psi_2 Hp2)).
  - destruct (glp_decide_closed_box_free psi_1 Hcl_1 Hbf_1) as [Hp1 | Hnp1].
    + (* psi_1 valid, psi_2 not: refuted via MP. *)
      right. intro Himp. apply Hnp2.
      apply (proj1 (provable_box_box_free_iff_provable k_2 psi_2 Hbf_2)).
      exact (MP _ _ Himp (Nec k_1 psi_1 Hp1)).
    + (* both not valid: reduce to [Impl (Box k_1 Bot) (Box k_2 Bot)]. *)
      pose proof (not_provable_implies_provable_neg_closed_box_free psi_1 Hcl_1 Hbf_1 Hnp1) as Hneg1.
      pose proof (not_provable_implies_provable_neg_closed_box_free psi_2 Hcl_2 Hbf_2 Hnp2) as Hneg2.
      pose proof (box_psi_iff_box_bot_when_neg_provable k_1 psi_1 Hneg1) as Hiff1.
      pose proof (box_psi_iff_box_bot_when_neg_provable k_2 psi_2 Hneg2) as Hiff2.
      destruct (glp_decide_impl_box_bot_box_bot k_1 k_2) as [HBot | HnBot].
      * left.
        pose proof (prov_and_elim_l_meta _ _ Hiff1) as Hf1.
        pose proof (prov_and_elim_r_meta _ _ Hiff2) as Hb2.
        pose proof (prov_compose _ _ _ Hf1 HBot) as Hstep1.
        exact (prov_compose _ _ _ Hstep1 Hb2).
      * right. intro Himp. apply HnBot.
        pose proof (prov_and_elim_r_meta _ _ Hiff1) as Hb1.
        pose proof (prov_and_elim_l_meta _ _ Hiff2) as Hf2.
        pose proof (prov_compose _ _ _ Hb1 Himp) as Hstep1.
        exact (prov_compose _ _ _ Hstep1 Hf2).
Defined.

(** ** When [|- Neg psi], lifting through [iter_box ns] preserves Iff with
    [iter_box ns Bot].  This is the reduction-to-worm step: classically
    refutable [psi] makes [iter_box ns psi] provably equivalent to a
    worm. *)

Lemma iter_box_psi_iff_iter_box_bot_when_neg_provable : forall ns psi,
  |- Neg psi -> |- Iff (iter_box ns psi) (iter_box ns Bot).
Proof.
  intro ns. induction ns as [|n rest IH]; intros psi Hneg.
  - cbn. apply prov_iff_intro.
    + exact Hneg.
    + exact (prov_explosion psi).
  - cbn [iter_box].
    pose proof (IH psi Hneg) as Hiff_inner.
    pose proof (prov_and_elim_l_meta _ _ Hiff_inner) as Hfwd.
    pose proof (prov_and_elim_r_meta _ _ Hiff_inner) as Hback.
    apply prov_iff_intro.
    + exact (MP _ _ (Ax_BoxK n (iter_box rest psi) (iter_box rest Bot))
                  (Nec n _ Hfwd)).
    + exact (MP _ _ (Ax_BoxK n (iter_box rest Bot) (iter_box rest psi))
                  (Nec n _ Hback)).
Qed.

(** ** Reduction-to-worm: for closed box-free [psi_1, psi_2] both
    classically refutable, the iter-box implication is provably equivalent
    to the iter-box-Bot worm-implication. *)

Theorem iter_box_iter_box_iff_worm_implication_when_both_neg :
  forall ns_1 ns_2 psi_1 psi_2,
  |- Neg psi_1 -> |- Neg psi_2 ->
  |- Iff (Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2))
        (Impl (iter_box ns_1 Bot) (iter_box ns_2 Bot)).
Proof.
  intros ns_1 ns_2 psi_1 psi_2 Hneg1 Hneg2.
  pose proof (iter_box_psi_iff_iter_box_bot_when_neg_provable ns_1 psi_1 Hneg1) as Hiff1.
  pose proof (iter_box_psi_iff_iter_box_bot_when_neg_provable ns_2 psi_2 Hneg2) as Hiff2.
  exact (prov_equiv_impl_cong _ _ _ _ Hiff1 Hiff2).
Qed.

(** ** Refutation case for the both-invalid sub-case via Fnat soundness on
    bad_world.  When [bad_world ns_1 > bad_world ns_2] and both [psi_i]
    are closed box-free + classically refutable, the implication is
    unprovable. *)

Theorem refute_impl_iter_box_iter_box_box_free_via_bad_world :
  forall ns_1 ns_2 psi_1 psi_2,
  free_vars psi_1 = [] -> box_free psi_1 ->
  free_vars psi_2 = [] -> box_free psi_2 ->
  ~ |- psi_1 -> ~ |- psi_2 ->
  bad_world ns_1 > bad_world ns_2 ->
  ~ |- Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2).
Proof.
  intros ns_1 ns_2 psi_1 psi_2 Hcl1 Hbf1 Hcl2 Hbf2 Hnp1 Hnp2 Hgt Himp.
  pose proof (not_provable_implies_provable_neg_closed_box_free psi_1 Hcl1 Hbf1 Hnp1) as Hneg1.
  pose proof (not_provable_implies_provable_neg_closed_box_free psi_2 Hcl2 Hbf2 Hnp2) as Hneg2.
  pose proof (iter_box_iter_box_iff_worm_implication_when_both_neg ns_1 ns_2 psi_1 psi_2 Hneg1 Hneg2) as Hiff.
  pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
  pose proof (MP _ _ Hfwd Himp) as Hworm.
  pose proof (provable_impl_iter_box_bot_forward ns_1 ns_2 Hworm) as Hle.
  lia.
Qed.

(** ** Decider for the iter-box implication when [psi_2] is classically
    valid: the consequent is provable, hence the implication is provable
    via [Ax_K]. *)

Definition glp_decide_impl_iter_box_iter_box_box_free_psi_2_valid
  (ns_1 ns_2 : list nat) (psi_1 psi_2 : Form)
  (Hcl_2 : free_vars psi_2 = []) (Hbf_2 : box_free psi_2)
  (Hp2 : |- psi_2) :
  sumbool (|- Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2))
          (~ |- Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2)) :=
  glp_decide_impl_iter_box_via_consequent_provable ns_1 ns_2 psi_1 psi_2 Hp2.

(** ** Decider when [psi_1] is valid and [psi_2] is invalid: the implication
    cannot hold, since [MP] would yield the (refutable) consequent. *)

Definition glp_decide_impl_iter_box_iter_box_box_free_psi_1_valid_psi_2_invalid
  (ns_1 ns_2 : list nat) (psi_1 psi_2 : Form)
  (Hcl_2 : free_vars psi_2 = []) (Hbf_2 : box_free psi_2)
  (Hp1 : |- psi_1) (Hnp2 : ~ |- psi_2) :
  sumbool (|- Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2))
          (~ |- Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2)) :=
  glp_decide_impl_iter_box_via_antecedent_provable_consequent_not
    ns_1 ns_2 psi_1 psi_2 Hcl_2 Hbf_2 Hp1 Hnp2.

(** ** Refutation when both are invalid and the bad_world ordering favors
    refutation. *)

Definition glp_decide_impl_iter_box_iter_box_box_free_both_invalid_refute
  (ns_1 ns_2 : list nat) (psi_1 psi_2 : Form)
  (Hcl_1 : free_vars psi_1 = []) (Hbf_1 : box_free psi_1)
  (Hcl_2 : free_vars psi_2 = []) (Hbf_2 : box_free psi_2)
  (Hnp1 : ~ |- psi_1) (Hnp2 : ~ |- psi_2)
  (Hgt : bad_world ns_1 > bad_world ns_2) :
  ~ |- Impl (iter_box ns_1 psi_1) (iter_box ns_2 psi_2) :=
  refute_impl_iter_box_iter_box_box_free_via_bad_world
    ns_1 ns_2 psi_1 psi_2 Hcl_1 Hbf_1 Hcl_2 Hbf_2 Hnp1 Hnp2 Hgt.

(** ** Empty-antecedent case for both-invalid: trivially provable since
    [psi_1] is provably equivalent to [Bot] under [|- Neg psi_1], so
    [iter_box [] psi_1 = psi_1] is equivalent to [Bot], from which
    everything follows by explosion. *)

Lemma provable_impl_psi_iter_box_psi_2_when_neg_psi_provable :
  forall psi_1 ns_2 psi_2,
  |- Neg psi_1 ->
  |- Impl psi_1 (iter_box ns_2 psi_2).
Proof.
  intros psi_1 ns_2 psi_2 Hneg.
  exact (prov_compose _ _ _ Hneg (prov_explosion (iter_box ns_2 psi_2))).
Qed.

Definition glp_decide_impl_psi_iter_box_psi_2_box_free
  (ns_2 : list nat) (psi_1 psi_2 : Form)
  (Hcl_1 : free_vars psi_1 = []) (Hbf_1 : box_free psi_1)
  (Hcl_2 : free_vars psi_2 = []) (Hbf_2 : box_free psi_2) :
  sumbool (|- Impl psi_1 (iter_box ns_2 psi_2))
          (~ |- Impl psi_1 (iter_box ns_2 psi_2)).
Proof.
  destruct (glp_decide_closed_box_free psi_2 Hcl_2 Hbf_2) as [Hp2 | Hnp2].
  - left.
    exact (MP _ _ (Ax_K (iter_box ns_2 psi_2) psi_1)
                  (provable_iter_box_intro ns_2 psi_2 Hp2)).
  - destruct (glp_decide_closed_box_free psi_1 Hcl_1 Hbf_1) as [Hp1 | Hnp1].
    + right. intro Himp.
      apply Hnp2.
      apply (proj1 (provable_iter_box_box_free_iff ns_2 psi_2 Hcl_2 Hbf_2)).
      exact (MP _ _ Himp Hp1).
    + left.
      pose proof (not_provable_implies_provable_neg_closed_box_free
                    psi_1 Hcl_1 Hbf_1 Hnp1) as Hneg1.
      exact (provable_impl_psi_iter_box_psi_2_when_neg_psi_provable
               psi_1 ns_2 psi_2 Hneg1).
Defined.

(** ** Full decidability for the special case [ns_1 = []]: when the
    antecedent has no outer boxes, classical analysis on [psi_1, psi_2]
    completely determines provability. *)

Definition glp_decide_impl_iter_box_empty_iter_box_box_free
  (ns_2 : list nat) (psi_1 psi_2 : Form)
  (Hcl_1 : free_vars psi_1 = []) (Hbf_1 : box_free psi_1)
  (Hcl_2 : free_vars psi_2 = []) (Hbf_2 : box_free psi_2) :
  sumbool (|- Impl (iter_box [] psi_1) (iter_box ns_2 psi_2))
          (~ |- Impl (iter_box [] psi_1) (iter_box ns_2 psi_2)) :=
  glp_decide_impl_psi_iter_box_psi_2_box_free
    ns_2 psi_1 psi_2 Hcl_1 Hbf_1 Hcl_2 Hbf_2.

(** ** [NextCon]-explosion at the outer level.  When the inner level [n] is
    strictly less than the outer level [m], the [Box m] of [Box n Bot]
    collapses to [Box m Bot]: at level [m], the consistency of level [n]
    (via [Ax_NextCon] lifted by [Mon]) refutes [Box n Bot], so MP yields
    [Box m Bot]. *)

Lemma prov_box_higher_box_lower_bot_to_box_higher_bot : forall n m,
  n < m -> |- Impl (Box m (Box n Bot)) (Box m Bot).
Proof.
  intros n m Hlt.
  pose proof (Ax_NextCon n) as Hnext.
  pose proof (prov_box_mon_le (S n) m (Neg (Box n Bot)) Hlt) as Hmon.
  pose proof (MP _ _ Hmon Hnext) as Hboxm_neg.
  pose proof (Ax_BoxK m (Box n Bot) Bot) as HK.
  exact (MP _ _ HK Hboxm_neg).
Qed.

(** ** Worm collapse for two-element worms with inner < outer.  This is the
    simplest non-trivial case of Beklemishev's worm reduction: when the
    second box-level is strictly less than the first, the worm collapses
    to its single-box form. *)

Theorem worm_two_element_collapse_inner_lt_outer : forall outer inner,
  inner < outer ->
  |- Iff (iter_box [outer; inner] Bot) (Box outer Bot).
Proof.
  intros outer inner Hlt. cbn [iter_box].
  apply prov_iff_intro.
  - exact (prov_box_higher_box_lower_bot_to_box_higher_bot inner outer Hlt).
  - exact (prov_box_bot_to_box_anything outer (Box inner Bot)).
Qed.

(** ** Provable [Impl (iter_box [outer; inner] Bot) (Box m Bot)] when
    [inner < outer] and [outer <= m].  Combines worm collapse with [Mon]. *)

Theorem provable_impl_iter_box_two_element_to_box_bot :
  forall outer inner m,
  inner < outer -> outer <= m ->
  |- Impl (iter_box [outer; inner] Bot) (Box m Bot).
Proof.
  intros outer inner m Hlt Hle.
  pose proof (worm_two_element_collapse_inner_lt_outer outer inner Hlt) as Hiff.
  pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
  pose proof (prov_box_mon_le outer m Bot Hle) as Hmon.
  exact (prov_compose _ _ _ Hfwd Hmon).
Qed.

(** ** Provable [Impl (iter_box [outer; inner] Bot) (iter_box (m :: rest) Bot)]
    when [inner < outer] and [outer <= m].  Combines worm collapse with the
    box-bot-explosion route. *)

Theorem provable_impl_iter_box_two_element_to_iter_box :
  forall outer inner m rest,
  inner < outer -> outer <= m ->
  |- Impl (iter_box [outer; inner] Bot) (iter_box (m :: rest) Bot).
Proof.
  intros outer inner m rest Hlt Hle.
  pose proof (worm_two_element_collapse_inner_lt_outer outer inner Hlt) as Hiff.
  pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
  pose proof (provable_impl_box_bot_iter_box_bot_head_match outer m rest Hle) as Hhead.
  exact (prov_compose _ _ _ Hfwd Hhead).
Qed.

(** ** Two cleanly-handled sub-cases for the worm-implication with a
    2-element collapsed antecedent: empty consequent (refute via the
    Carlson generalisation) and head-match consequent (provable via the
    collapse + head-match chain).  The remaining cases (consequent with
    head [m < outer] but inner structure rich enough to dominate) are
    gaps in the bad_world-only characterisation, so we expose
    these positive cases as separate lemmas rather than forcing a
    [sumbool] over an indeterminate domain. *)

Lemma worm_implication_two_element_collapsed_to_empty_unprovable :
  forall outer inner,
  inner < outer ->
  ~ |- Impl (iter_box [outer; inner] Bot) (iter_box [] Bot).
Proof.
  intros outer inner Hlt Himp.
  pose proof (worm_two_element_collapse_inner_lt_outer outer inner Hlt) as Hiff.
  pose proof (prov_and_elim_r_meta _ _ Hiff) as Hback.
  pose proof (prov_compose _ _ _ Hback Himp) as Hbox_outer_to_bot.
  exact (closed_neg_box_unprovable outer Bot eq_refl Hbox_outer_to_bot).
Qed.

(** ** Boolean prefix-mon check: Boolean predicate that is [true] iff
    [ns_2] starts with a length-[length ns_1] prefix that pointwise
    dominates [ns_1].  Yields a syntactic sufficient condition for
    worm-implication provability. *)

Fixpoint prefix_mon_le_b (ns_1 ns_2 : list nat) : bool :=
  match ns_1, ns_2 with
  | [], _ => true
  | _ :: _, [] => false
  | n :: rest_1, m :: rest_2 => andb (Nat.leb n m) (prefix_mon_le_b rest_1 rest_2)
  end.

Lemma prefix_mon_le_b_implies_split : forall ns_1 ns_2,
  prefix_mon_le_b ns_1 ns_2 = true ->
  exists prefix ext,
    ns_2 = prefix ++ ext /\
    length ns_1 = length prefix /\
    (forall i, i < length ns_1 -> nth i ns_1 0 <= nth i prefix 0).
Proof.
  intro ns_1. induction ns_1 as [|n rest_1 IH]; intros ns_2 Hb.
  - exists [], ns_2. split; [reflexivity | split; [reflexivity|]].
    intros i Hi. cbn in Hi. lia.
  - destruct ns_2 as [|m rest_2]; [discriminate Hb|].
    cbn in Hb. apply Bool.andb_true_iff in Hb. destruct Hb as [Hle Hrec].
    apply Nat.leb_le in Hle.
    destruct (IH rest_2 Hrec) as [prefix [ext [Heq [Hlen Hpt]]]].
    exists (m :: prefix), ext. split; [|split].
    + cbn. rewrite Heq. reflexivity.
    + cbn. rewrite Hlen. reflexivity.
    + intros i Hi. destruct i as [|i].
      * cbn. exact Hle.
      * cbn. cbn in Hi. apply Hpt. lia.
Qed.

(** ** Provable worm-implication from the Boolean prefix-mon check. *)

Theorem prefix_mon_le_b_implies_worm_provable : forall ns_1 ns_2,
  prefix_mon_le_b ns_1 ns_2 = true ->
  |- Impl (iter_box ns_1 Bot) (iter_box ns_2 Bot).
Proof.
  intros ns_1 ns_2 Hb.
  destruct (prefix_mon_le_b_implies_split ns_1 ns_2 Hb) as [prefix [ext [Heq [Hlen Hpt]]]].
  rewrite Heq.
  exact (prov_iter_box_prefix_mon_extension ns_1 prefix ext Bot Hlen Hpt).
Qed.

(** ** Decidability of the boolean prefix-mon check yields a [sumbool] for
    a structurally identifiable subset of provable worm implications.
    When the check fails, we cannot conclude unprovability in general
    (the Beklemishev worm theorem provides additional positive cases
    not captured by pointwise prefix mon). *)

Definition glp_decide_worm_implication_via_prefix_mon
  (ns_1 ns_2 : list nat) :
  sumbool (prefix_mon_le_b ns_1 ns_2 = true)
          (prefix_mon_le_b ns_1 ns_2 = false).
Proof.
  destruct (prefix_mon_le_b ns_1 ns_2) eqn:Eb.
  - left. reflexivity.
  - right. reflexivity.
Defined.

(** ** Full decision when the bad_world ordering FAILS: refute via the
    forward direction of the worm-implication theorem. *)

Definition glp_decide_worm_implication_via_bad_world
  (ns_1 ns_2 : list nat)
  (Hgt : bad_world ns_1 > bad_world ns_2) :
  ~ |- Impl (iter_box ns_1 Bot) (iter_box ns_2 Bot).
Proof.
  intro Himp.
  pose proof (provable_impl_iter_box_bot_forward ns_1 ns_2 Himp) as Hle.
  lia.
Defined.

(** ** Combined decision principle for worm implications: the [sumbool]
    holds when at least one of the two structural conditions decides:
    (a) prefix-mon check passes (provable), or
    (b) bad_world ordering fails (unprovable).  When neither decides,
    we cannot conclude with the present tools. *)

Definition glp_decide_worm_implication_via_structural_principles
  (ns_1 ns_2 : list nat) :
  sumbool (|- Impl (iter_box ns_1 Bot) (iter_box ns_2 Bot))
          (~ |- Impl (iter_box ns_1 Bot) (iter_box ns_2 Bot)) +
  ((prefix_mon_le_b ns_1 ns_2 = false) /\
   (bad_world ns_1 <= bad_world ns_2)).
Proof.
  destruct (glp_decide_worm_implication_via_prefix_mon ns_1 ns_2) as [Hpref | Hpref].
  - left. left. exact (prefix_mon_le_b_implies_worm_provable ns_1 ns_2 Hpref).
  - destruct (le_gt_dec (bad_world ns_1) (bad_world ns_2)) as [Hle | Hgt].
    + right. split; assumption.
    + left. right. exact (glp_decide_worm_implication_via_bad_world ns_1 ns_2 Hgt).
Defined.

(** ** Free-variable extension for box-free [iter_box].  For arbitrary
    [psi] (closed or open) that is box-free, [|- iter_box ns psi] iff
    [psi] is classically valid (true under every Boolean valuation).
    This generalises [provable_iter_box_box_free_iff] to forms with free
    variables, leveraging [prop_completeness] (which works in the
    box-free fragment regardless of whether variables are present). *)

Lemma forces_iter_box_at_bad_world_const : forall ns psi val w,
  box_free psi ->
  w >= bad_world ns ->
  forces Fnat (fun _ => val) w (iter_box ns psi) ->
  eval val psi = true.
Proof.
  intro ns. induction ns as [|n rest IH]; intros psi val w Hbf Hw Hf.
  - cbn in Hf. apply (proj1 (forces_const_box_free Fnat val w psi Hbf)). exact Hf.
  - cbn in Hf. cbn in Hw.
    set (v := Nat.max n (bad_world rest)).
    assert (Hr : Fnat_R n w v).
    { unfold Fnat_R, v. lia. }
    pose proof (Hf v Hr) as Hinner.
    apply (IH psi val v Hbf).
    + unfold v. lia.
    + exact Hinner.
Qed.

Theorem provable_iter_box_box_free_iff_classical_valid : forall ns psi,
  box_free psi ->
  (|- iter_box ns psi <-> classical_valid psi).
Proof.
  intros ns psi Hbf. unfold classical_valid. split.
  - intros Hp val.
    pose proof (soundness _ Hp Fnat (fun _ => val) (bad_world ns)) as Hf.
    exact (forces_iter_box_at_bad_world_const ns psi val (bad_world ns)
             Hbf (Nat.le_refl _) Hf).
  - intros Hval.
    pose proof (prop_completeness psi Hbf Hval) as Hpp.
    pose proof (trivial_in_provable psi Hpp) as Hp.
    exact (provable_iter_box_intro ns psi Hp).
Qed.

(** ** Decision procedure for [iter_box ns psi] with general (open)
    box-free [psi].  Uses [decide_tautology] for the underlying classical
    decision. *)

Definition glp_decide_iter_box_box_free (ns : list nat) (psi : Form)
  (Hbf : box_free psi) :
  sumbool (|- iter_box ns psi) (~ |- iter_box ns psi).
Proof.
  destruct (decide_tautology psi) eqn:Edt.
  - left.
    apply (proj2 (provable_iter_box_box_free_iff_classical_valid ns psi Hbf)).
    apply decide_tautology_correct. exact Edt.
  - right.
    intro Hp.
    pose proof (proj1 (provable_iter_box_box_free_iff_classical_valid ns psi Hbf) Hp) as Hval.
    pose proof (decide_tautology_complete psi Hval) as Edt'.
    rewrite Edt in Edt'. discriminate.
Defined.

(** ** Full decision procedure for the entire box-free fragment, open or
    closed: [|- phi] iff [phi] is classically valid.  This is just
    [decide_tautology] wrapped as a [sumbool]. *)

Definition glp_decide_box_free (phi : Form) (Hbf : box_free phi) :
  sumbool (|- phi) (~ |- phi).
Proof.
  destruct (decide_tautology phi) eqn:Edt.
  - left. apply trivial_in_provable. apply prop_completeness; [exact Hbf|].
    apply decide_tautology_correct. exact Edt.
  - right. intro Hp.
    pose proof (eval_provable_true) as Heval.
    pose proof (decide_tautology_complete phi (fun val => Heval val phi Hp)) as Edt'.
    rewrite Edt in Edt'. discriminate.
Defined.

(** ** Boolean version of [box_free]. *)

Fixpoint box_free_b (phi : Form) : bool :=
  match phi with
  | Var _ => true
  | Bot => true
  | Impl X Y => andb (box_free_b X) (box_free_b Y)
  | Box _ _ => false
  end.

Lemma box_free_b_iff : forall phi,
  box_free_b phi = true <-> box_free phi.
Proof.
  intro phi. induction phi as [k | | X IHX Y IHY | n psi IHpsi]; cbn.
  - tauto.
  - tauto.
  - rewrite Bool.andb_true_iff. rewrite IHX, IHY. reflexivity.
  - split; [discriminate | intros []].
Qed.

(** ** Decomposition: every formula factors as [iter_box ns psi] where
    [psi] is the result of stripping all outermost [Box] layers and [ns]
    collects the box levels. *)

Fixpoint extract_box_levels (phi : Form) : list nat :=
  match phi with
  | Box n psi => n :: extract_box_levels psi
  | _ => []
  end.

Fixpoint extract_inner_form (phi : Form) : Form :=
  match phi with
  | Box _ psi => extract_inner_form psi
  | _ => phi
  end.

Lemma extract_decomposition : forall phi,
  phi = iter_box (extract_box_levels phi) (extract_inner_form phi).
Proof.
  intro phi. induction phi as [k | | X IHX Y IHY | n psi IHpsi]; cbn; try reflexivity.
  rewrite <- IHpsi at 1. reflexivity.
Qed.

Lemma extract_inner_form_no_outer_box : forall phi,
  match extract_inner_form phi with Box _ _ => False | _ => True end.
Proof.
  intro phi. induction phi as [k | | X IHX Y IHY | n psi IHpsi]; cbn; auto; exact I.
Qed.

(** ** Boolean predicate identifying the sub-fragment for which we provide
    full decidability: a formula whose innermost (after stripping outer
    boxes) is box-free.  These are exactly the formulas of shape
    [iter_box ns psi] with box-free [psi]. *)

Definition is_iter_box_of_box_free (phi : Form) : bool :=
  box_free_b (extract_inner_form phi).

Lemma extract_inner_box_free : forall phi,
  is_iter_box_of_box_free phi = true -> box_free (extract_inner_form phi).
Proof.
  intros phi Hb. unfold is_iter_box_of_box_free in Hb.
  apply box_free_b_iff. exact Hb.
Qed.

(** ** Headline decidability for the [is_iter_box_of_box_free] fragment.
    Combined with [glp_decide_box_free] for the box-free part of the
    fragment, this yields a decision procedure for every formula whose
    syntactic shape strips to a box-free leaf. *)

Definition glp_decide_iter_box_of_box_free (phi : Form)
  (Hb : is_iter_box_of_box_free phi = true) :
  sumbool (|- phi) (~ |- phi).
Proof.
  rewrite (extract_decomposition phi).
  exact (glp_decide_iter_box_box_free
           (extract_box_levels phi)
           (extract_inner_form phi)
           (extract_inner_box_free phi Hb)).
Defined.

(** ** Iff-congruence under [Box].  A directional [Iff] under a single
    [Box] follows from [Nec] + [BoxK] applied componentwise. *)

Lemma iff_under_box : forall n phi psi,
  |- Iff phi psi ->
  |- Iff (Box n phi) (Box n psi).
Proof.
  intros n phi psi Hiff.
  pose proof (prov_and_elim_l_meta _ _ Hiff) as Hf.
  pose proof (prov_and_elim_r_meta _ _ Hiff) as Hb.
  apply prov_iff_intro.
  - exact (MP _ _ (Ax_BoxK n phi psi) (Nec n _ Hf)).
  - exact (MP _ _ (Ax_BoxK n psi phi) (Nec n _ Hb)).
Qed.

(** ** Boolean check for strictly descending lists. *)

Fixpoint is_strictly_descending (ns : list nat) : bool :=
  match ns with
  | [] => true
  | [_] => true
  | a :: ((b :: _) as rest) => andb (Nat.ltb b a) (is_strictly_descending rest)
  end.

(** ** Iterated worm collapse for strictly descending sequences.  Each
    successive [(a, b, ...)] with [b < a] collapses [Box a (Box b ...)]
    to [Box a Bot] via iterated application of the 2-element collapse and
    [iff_under_box]. *)

Lemma prov_iff_trans : forall phi psi chi,
  |- Iff phi psi -> |- Iff psi chi -> |- Iff phi chi.
Proof.
  intros phi psi chi H1 H2.
  pose proof (prov_and_elim_l_meta _ _ H1) as H1f.
  pose proof (prov_and_elim_r_meta _ _ H1) as H1b.
  pose proof (prov_and_elim_l_meta _ _ H2) as H2f.
  pose proof (prov_and_elim_r_meta _ _ H2) as H2b.
  apply prov_iff_intro.
  - exact (prov_compose _ _ _ H1f H2f).
  - exact (prov_compose _ _ _ H2b H1b).
Qed.

Theorem worm_descending_collapse_to_head : forall n rest,
  is_strictly_descending (n :: rest) = true ->
  |- Iff (iter_box (n :: rest) Bot) (Box n Bot).
Proof.
  intros n rest. revert n. induction rest as [|m rest' IH]; intros n Hd.
  - cbn [iter_box]. apply prov_iff_refl.
  - cbn in Hd. apply Bool.andb_true_iff in Hd. destruct Hd as [Hlt Hd_rest].
    apply Nat.ltb_lt in Hlt.
    pose proof (IH m Hd_rest) as Hiff_inner.
    pose proof (iff_under_box n _ _ Hiff_inner) as Hiff_outer.
    cbn [iter_box] in Hiff_outer.
    pose proof (worm_two_element_collapse_inner_lt_outer n m Hlt) as Hcollapse.
    cbn [iter_box] in Hcollapse.
    cbn [iter_box].
    exact (prov_iff_trans _ _ _ Hiff_outer Hcollapse).
Qed.

(** ** Worm-implication via descending-collapse + head-match.  When the
    antecedent is strictly descending, it collapses to its head; if the
    head is dominated by the consequent's head, the implication is
    provable. *)

Theorem provable_impl_descending_iter_box_to_iter_box_via_head :
  forall n rest m rest_2,
  is_strictly_descending (n :: rest) = true ->
  n <= m ->
  |- Impl (iter_box (n :: rest) Bot) (iter_box (m :: rest_2) Bot).
Proof.
  intros n rest m rest_2 Hd Hle.
  pose proof (worm_descending_collapse_to_head n rest Hd) as Hiff.
  pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
  pose proof (provable_impl_box_bot_iter_box_bot_head_match n m rest_2 Hle) as Hhead.
  exact (prov_compose _ _ _ Hfwd Hhead).
Qed.

(** ** Beklemishev-style absorption: when an iter-box-Bot has a sub-pattern
    [Box outer (Box inner ...)] with [inner < outer], the inner box can
    be absorbed.  Specifically, [Box outer (Box inner phi)] entails
    [Box outer Bot] when [inner < outer] AND [phi = Bot] — extending to
    the case [phi = iter_box rest Bot] requires that [rest] doesn't
    introduce new structure stronger than [Bot].  We capture the simplest
    productive case: a worm where the second level is strictly less than
    the first AND the remaining suffix is empty. *)

Lemma worm_two_element_bot_provable_iff_outer_bot : forall outer inner,
  inner < outer ->
  (|- iter_box [outer; inner] Bot <-> |- Box outer Bot).
Proof.
  intros outer inner Hlt.
  pose proof (worm_two_element_collapse_inner_lt_outer outer inner Hlt) as Hiff.
  pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
  pose proof (prov_and_elim_r_meta _ _ Hiff) as Hback.
  split.
  - intro Hp. exact (MP _ _ Hfwd Hp).
  - intro Hp. exact (MP _ _ Hback Hp).
Qed.

(** ** A complete decidability statement for [iter_box [outer; inner] Bot]
    when [inner < outer]: the worm is provable iff [Box outer Bot] is,
    which is iff false (by [closed_fragment_iterated_bot_not_provable]). *)

Theorem worm_two_element_descending_unprovable : forall outer inner,
  inner < outer ->
  ~ |- iter_box [outer; inner] Bot.
Proof.
  intros outer inner Hlt Hp.
  apply (proj1 (worm_two_element_bot_provable_iff_outer_bot outer inner Hlt)) in Hp.
  exact (closed_fragment_iterated_bot_not_provable outer Hp).
Qed.

(** ** Same conclusion via the iterated-descending generalization: an
    iter-box-Bot worm with strictly descending box-levels collapses to its
    head's [Box n Bot], which is unprovable. *)

Theorem worm_descending_unprovable : forall n rest,
  is_strictly_descending (n :: rest) = true ->
  ~ |- iter_box (n :: rest) Bot.
Proof.
  intros n rest Hd Hp.
  pose proof (worm_descending_collapse_to_head n rest Hd) as Hiff.
  pose proof (prov_and_elim_l_meta _ _ Hiff) as Hfwd.
  pose proof (MP _ _ Hfwd Hp) as Hbox_n_bot.
  exact (closed_fragment_iterated_bot_not_provable n Hbox_n_bot).
Qed.

(** ** Decidability of unprovability for descending worms (paired with
    the existing positive results). *)

Definition glp_decide_descending_worm
  (n : nat) (rest : list nat)
  (Hd : is_strictly_descending (n :: rest) = true) :
  sumbool (|- iter_box (n :: rest) Bot) (~ |- iter_box (n :: rest) Bot).
Proof.
  right. exact (worm_descending_unprovable n rest Hd).
Defined.

(** ** Beklemishev-gap refutation for [Impl (Box k Bot) (Box 0 (Box m Bot))]
    when [m < k].  This is a corner case where Fnat is not directly able
    to refute, but a syntactic argument via [Mon] + the unprovability of
    [Box 0 (Box m Bot)] does the job.

    Approach: assume the implication is provable.  Then by the contrapositive
    direction of NextCon-derived equivalences, we should be able to derive
    something contradictory.  However, the gap remains in our axioms:
    we have [|- Box 0 (Box m Bot) -> Box (S m) Bot] (via Mon + NextCon route),
    so [Box 0 (Box m Bot)] is provably stronger than [Box (S m) Bot], and
    [Box (S m) Bot] is in turn implied by [Box k Bot] when [k <= S m].

    But for [m < k], we have [k > m], so [Box (S m) Bot -> Box k Bot] by
    [Mon] iff [S m <= k], i.e., [m < k].  Thus [Box 0 (Box m Bot) -> Box k Bot]
    is provable, but the reverse [Box k Bot -> Box 0 (Box m Bot)] is not
    derivable in our axiom system (it would require the unprovable
    "T_k inconsistent therefore T_0 proves T_m inconsistent"). *)

Lemma prov_box_0_box_m_bot_to_box_S_m_bot : forall m,
  |- Impl (Box 0 (Box m Bot)) (Box (S m) Bot).
Proof.
  intro m.
  pose proof (prov_box_mon_le 0 (S m) (Box m Bot)
                (Nat.le_0_l (S m))) as Hmon.
  pose proof (prov_box_higher_box_lower_bot_to_box_higher_bot m (S m)
                (Nat.lt_succ_diag_r m)) as Hcol.
  exact (prov_compose _ _ _ Hmon Hcol).
Qed.

(** ** When [|- Box k Bot -> Box 0 (Box m Bot)] holds AND [m < k] holds,
    we can chain to derive [|- Box k Bot -> Box (S m) Bot], which is not
    a direct contradiction.  But we also have [|- Box (S m) Bot -> Box k Bot]
    by [Mon] (when [S m <= k]), so the two are provably equivalent.

    Thus [|- Box k Bot -> Box 0 (Box m Bot)] iff [|- Box (S m) Bot -> Box 0 (Box m Bot)]
    (by chasing the chain).  Since [Box (S m) Bot] is derivable from
    [Box 0 (Box m Bot)] AND vice versa (provable equivalence in this direction)
    is the missing ingredient — only one direction of equivalence holds. *)

Lemma prov_iff_box_S_m_bot_box_0_box_m_bot_partial : forall m,
  |- Impl (Box 0 (Box m Bot)) (Box (S m) Bot).
Proof.
  exact prov_box_0_box_m_bot_to_box_S_m_bot.
Qed.

(** ** An Ignatiev-style 2-dimensional Kripke frame [I2] that refutes
    Beklemishev-gap formulas.  Worlds are pairs of naturals; [R_0] is the
    lex order, while [R_n] for [n >= 1] depends only on the first
    coordinate with a level-threshold.  This frame distinguishes formulas
    that Fnat collapses, since the second coordinate provides extra
    "depth" at each first-coordinate level. *)

Definition I2_R (n : nat) (w v : nat * nat) : Prop :=
  match n with
  | 0 => fst w > fst v \/ (fst w = fst v /\ snd w > snd v)
  | S k => fst w > fst v /\ fst v >= S k
  end.

Lemma I2_R_trans : forall n w v u, I2_R n w v -> I2_R n v u -> I2_R n w u.
Proof.
  intros [|k] [a b] [c d] [e f]; cbn.
  - intros [Hac | [Hac Hbd]] [Hce | [Hce Hdf]].
    + left. lia.
    + left. lia.
    + left. lia.
    + right. split; [lia | lia].
  - intros [Hac Hcn] [Hce Hen]. split; lia.
Qed.

Lemma I2_R_wf_helper :
  forall a b,
    Acc (fun v u : nat * nat =>
           fst u > fst v \/ (fst u = fst v /\ snd u > snd v)) (a, b).
Proof.
  induction a as [a IHa] using (well_founded_induction Wf_nat.lt_wf).
  intro b.
  induction b as [b IHb] using (well_founded_induction Wf_nat.lt_wf).
  apply Acc_intro. intros [c d] H.
  destruct H as [Hac | [Hac Hbd]].
  - cbn in Hac. apply (IHa c Hac).
  - cbn in Hac, Hbd. subst c.
    apply (IHb d Hbd).
Qed.

Lemma I2_R_wf : forall n, well_founded (fun u v : nat * nat => I2_R n v u).
Proof.
  intros [|k] [a b].
  - apply I2_R_wf_helper.
  - revert b.
    induction a as [a IHa] using (well_founded_induction Wf_nat.lt_wf).
    intro b. apply Acc_intro. intros [c d] [Hac _].
    cbn in Hac. apply (IHa c Hac).
Qed.

Lemma I2_R_mon : forall n w v, I2_R (S n) w v -> I2_R n w v.
Proof.
  intros [|k] [a b] [c d]; cbn.
  - intros [Hac _]. left. exact Hac.
  - intros [Hac Hcn]. split; [lia|lia].
Qed.

Lemma I2_R_nextcon : forall n w v, I2_R (S n) w v -> exists u, I2_R n v u.
Proof.
  intros [|k] [a b] [c d]; cbn.
  - intros [Hac Hcn].
    exists (c - 1, 0). cbn.
    left. lia.
  - intros [Hac Hcn].
    exists (S k, 0). cbn. split; [lia|lia].
Qed.

Definition I2 : Frame :=
  mkFrame (nat * nat) I2_R I2_R_trans I2_R_wf I2_R_mon I2_R_nextcon.

(** ** Concrete refutation: [|- Box 4 Bot -> Box 0 (Box 3 Bot)] is FALSE
    in GLP*.  The witness is [I2] at world [(4, 5)]. *)

Theorem refute_box_4_bot_implies_box_0_box_3_bot :
  ~ |- Impl (Box 4 Bot) (Box 0 (Box 3 Bot)).
Proof.
  intro Hp.
  pose proof (soundness _ Hp I2 (fun _ _ => false) (4, 5)) as Hf.
  cbn in Hf.
  assert (Hbox4 : forall v : nat * nat, I2_R 4 (4, 5) v -> False).
  { intros [c d] [Hac Hcn]. cbn in *. lia. }
  pose proof (Hf Hbox4) as Hbox0.
  pose proof (Hbox0 (4, 0)) as Hbox0'.
  assert (Hr0 : I2_R 0 (4, 5) (4, 0))
    by (cbn; right; split; [reflexivity | lia]).
  pose proof (Hbox0' Hr0) as Hbox3.
  apply (Hbox3 (3, 0)).
  cbn. split; [lia | lia].
Qed.

(** ** Generalised Beklemishev-gap refutation: for any [m < k], the
    formula [Box k Bot -> Box 0 (Box m Bot)] is unprovable.  The witness
    is [I2] at world [(S m, 1)]. *)

Theorem refute_box_k_bot_implies_box_0_box_m_bot : forall k m,
  m < k -> ~ |- Impl (Box k Bot) (Box 0 (Box m Bot)).
Proof.
  intros k m Hmk Hp.
  pose proof (soundness _ Hp I2 (fun _ _ => false) (S m, 1)) as Hf.
  cbn in Hf.
  assert (Hboxk : forall v : nat * nat, I2_R k (S m, 1) v -> False).
  { intros [c d]. destruct k as [|k']; cbn.
    - intros _. lia.
    - intros [Hac Hcn]. cbn in Hac, Hcn. lia. }
  pose proof (Hf Hboxk) as Hbox0.
  pose proof (Hbox0 (S m, 0)) as Hbox0'.
  assert (Hr0 : I2_R 0 (S m, 1) (S m, 0))
    by (cbn; right; split; [reflexivity | lia]).
  pose proof (Hbox0' Hr0) as Hboxm.
  destruct m as [|m']; cbn in Hboxm.
  - apply (Hboxm (0, 0)). cbn. left. lia.
  - apply (Hboxm (S m', 0)). cbn. split; [lia|lia].
Qed.

(** ** Bidirectional Lindenbaum gap: [Box (S m) Bot] does NOT imply
    [Box 0 (Box m Bot)] (refuted via I2), but the reverse direction
    does (provable via Mon + NextCon collapse).  Hence the two formulas
    are NOT provably equivalent in GLP*, despite being Fnat-equivalent. *)

Theorem reverse_implication_box_S_m_bot_box_0_box_m_bot_unprovable :
  forall m, ~ |- Impl (Box (S m) Bot) (Box 0 (Box m Bot)).
Proof.
  intro m.
  exact (refute_box_k_bot_implies_box_0_box_m_bot (S m) m (Nat.lt_succ_diag_r m)).
Qed.

(** ** Refutation of [Box k Bot -> Box 0 (Box 0 (Box m Bot))] via I2.
    Witness at [(S m, 2)].  This shows the I2 frame extends to
    refute deeper Beklemishev-gap formulas with multiple Box-0 layers. *)

Theorem refute_box_k_bot_implies_box_0_box_0_box_m_bot : forall k m,
  m < k -> ~ |- Impl (Box k Bot) (Box 0 (Box 0 (Box m Bot))).
Proof.
  intros k m Hmk Hp.
  pose proof (soundness _ Hp I2 (fun _ _ => false) (S m, 2)) as Hf.
  cbn in Hf.
  assert (Hboxk : forall v : nat * nat, I2_R k (S m, 2) v -> False).
  { intros [c d]. destruct k as [|k']; cbn.
    - intros _. lia.
    - intros [Hac Hcn]. cbn in Hac, Hcn. lia. }
  pose proof (Hf Hboxk) as Hbox0_box0.
  pose proof (Hbox0_box0 (S m, 1)) as Hbox0_box0'.
  assert (Hr0 : I2_R 0 (S m, 2) (S m, 1))
    by (cbn; right; split; [reflexivity | lia]).
  pose proof (Hbox0_box0' Hr0) as Hbox0_boxm.
  pose proof (Hbox0_boxm (S m, 0)) as Hbox0_boxm'.
  assert (Hr0' : I2_R 0 (S m, 1) (S m, 0))
    by (cbn; right; split; [reflexivity | lia]).
  pose proof (Hbox0_boxm' Hr0') as Hboxm.
  destruct m as [|m']; cbn in Hboxm.
  - apply (Hboxm (0, 0)). cbn. left. lia.
  - apply (Hboxm (S m', 0)). cbn. split; [lia|lia].
Qed.

(** ** General refutation tool: for any iter-box-Bot consequent of the
    form [iter_box (zeros ++ [m]) Bot] where [zeros] is a list of [0]s and
    [m < k], the implication [Box k Bot -> ...] is unprovable.  Proof by
    induction on [zeros], stepping into the lex-below world at each [0]. *)

Lemma forces_iter_box_zeros_box_m_bot_at_drop : forall zeros,
  Forall (fun n => n = 0) zeros ->
  forall m a b,
  forces I2 (fun _ _ => false) (a, b)
         (iter_box zeros (Box m Bot)) ->
  b >= length zeros ->
  forces I2 (fun _ _ => false) (a, b - length zeros) (Box m Bot).
Proof.
  intro zeros. induction zeros as [|z rest IH]; intros Hall m a b Hf Hb.
  - cbn. rewrite Nat.sub_0_r. exact Hf.
  - inversion Hall as [|y ys Hz0 Hrest]. subst z.
    cbn [iter_box length] in *.
    pose proof (Hf (a, b - 1)) as Hf'.
    assert (Hr : I2_R 0 (a, b) (a, b - 1)).
    { cbn. right. split; [reflexivity | lia]. }
    pose proof (Hf' Hr) as Hf_inner.
    assert (Hsub : b - 1 - length rest = b - S (length rest)) by lia.
    rewrite <- Hsub.
    apply (IH Hrest m a (b - 1)); [exact Hf_inner | lia].
Qed.

Theorem refute_box_k_bot_implies_iter_box_zero_prefix_box_m_bot :
  forall k m zeros,
  m < k ->
  Forall (fun n => n = 0) zeros ->
  ~ |- Impl (Box k Bot) (iter_box zeros (Box m Bot)).
Proof.
  intros k m zeros Hmk Hall Hp.
  pose proof (soundness _ Hp I2 (fun _ _ => false) (S m, length zeros)) as Hf.
  cbn in Hf.
  assert (Hboxk : forall v : nat * nat, I2_R k (S m, length zeros) v -> False).
  { intros [c d]. destruct k as [|k']; cbn.
    - intros _. lia.
    - intros [Hac Hcn]. cbn in Hac, Hcn. lia. }
  pose proof (Hf Hboxk) as Hcons.
  pose proof (forces_iter_box_zeros_box_m_bot_at_drop
                zeros Hall m (S m) (length zeros)
                Hcons (Nat.le_refl _)) as Hboxm.
  rewrite Nat.sub_diag in Hboxm.
  cbn in Hboxm.
  destruct m as [|m']; cbn in Hboxm.
  - apply (Hboxm (0, 0)). cbn. left. lia.
  - apply (Hboxm (S m', 0)). cbn. split; [lia|lia].
Qed.

(** ** I2 refutation for [Box k_1 (Box k_2 Bot) -> Box 0 (Box m Bot)]
    when [k_1 >= 1], [k_1 <= k_2], and [k_2 = m] (i.e., the
    bad_world-equal Beklemishev-gap configuration). *)

Theorem refute_box_box_bot_implies_box_0_box_m_bot :
  forall k_1 k_2 m,
  1 <= k_1 -> k_1 <= k_2 -> k_2 = m ->
  ~ |- Impl (Box k_1 (Box k_2 Bot)) (Box 0 (Box m Bot)).
Proof.
  intros k_1 k_2 m Hk1 Hk1k2 Hk2m Hp. subst k_2.
  pose proof (soundness _ Hp I2 (fun _ _ => false) (S m, 1)) as Hf.
  cbn in Hf.
  assert (Hbox12 : forall v : nat * nat,
            I2_R k_1 (S m, 1) v ->
            forall u, I2_R m v u -> False).
  { intros [c d]. destruct k_1 as [|k_1']; cbn.
    - lia.
    - intros [Hac Hcn]. cbn in Hac, Hcn.
      intros [e f]. destruct m as [|m']; cbn.
      + intros _. lia.
      + intros [Hce Hen]. cbn in Hce, Hen. lia. }
  pose proof (Hf Hbox12) as Hbox0.
  pose proof (Hbox0 (S m, 0)) as Hbox0'.
  assert (Hr0 : I2_R 0 (S m, 1) (S m, 0))
    by (cbn; right; split; [reflexivity | lia]).
  pose proof (Hbox0' Hr0) as Hboxm.
  destruct m as [|m']; cbn in Hboxm.
  - apply (Hboxm (0, 0)). cbn. left. lia.
  - apply (Hboxm (S m', 0)). cbn. split; [lia|lia].
Qed.

(** ** Concrete instance: [|- Box 1 (Box 3 Bot) -> Box 0 (Box 3 Bot)] is
    UNPROVABLE.  Together with [Box 0 (Box 3 Bot) -> Box 1 (Box 3 Bot)]
    (provable via Mon), this establishes another Fnat-incompleteness
    witness. *)

Corollary refute_box_1_box_3_bot_implies_box_0_box_3_bot :
  ~ |- Impl (Box 1 (Box 3 Bot)) (Box 0 (Box 3 Bot)).
Proof.
  apply refute_box_box_bot_implies_box_0_box_m_bot; [lia|lia|reflexivity].
Qed.

(** ** Hence, in our axiom system, the Lindenbaum classes of
    [Box 0 (Box m Bot)] and [Box (S m) Bot] are NOT provably equivalent.
    [I2] refutes the reverse direction, completing the Fnat-incompleteness
    witness for the closed fragment of GLP*. *)


(** ** The explicit measure-recursive decider.

    [glp_dec_b] recurses structurally through the outer [Box] layers --
    each step strictly decreases both [modal_depth] and [form_length] --
    and decides the box-free leaf by the classical tautology checker.
    [Some true] = provable, [Some false] = refuted, [None] = outside the
    decidable fragment. *)

Fixpoint glp_dec_b (phi : Form) : option bool :=
  match phi with
  | Box _ psi => glp_dec_b psi
  | _ => if box_free_b phi then Some (decide_tautology phi) else None
  end.

(** The decreasing measure is explicit and lexicographic: the [Box]
    recursion strictly drops the modal depth (first component) and the
    length (second component). *)

Lemma modal_depth_box_decreases : forall n psi,
  modal_depth psi < modal_depth (Box n psi).
Proof. intros n psi. cbn. lia. Qed.

Lemma form_length_box_decreases : forall n psi,
  form_length psi < form_length (Box n psi).
Proof. intros n psi. cbn. lia. Qed.

Theorem glp_dec_b_measure_decreases : forall n psi,
  modal_depth psi < modal_depth (Box n psi) /\
  form_length psi < form_length (Box n psi).
Proof.
  intros n psi. split;
    [apply modal_depth_box_decreases | apply form_length_box_decreases].
Qed.

(** [glp_dec_b] computes the tautology status of the box-free leaf
    reached by stripping the outer boxes. *)

Lemma glp_dec_b_extract : forall phi,
  glp_dec_b phi =
    (if box_free_b (extract_inner_form phi)
     then Some (decide_tautology (extract_inner_form phi))
     else None).
Proof.
  induction phi as [k | | X IHX Y IHY | n psi IHpsi]; cbn.
  - reflexivity.
  - reflexivity.
  - reflexivity.
  - exact IHpsi.
Qed.

(** Inside the fragment, the inner leaf is box-free. *)

Lemma fragment_inner_box_free_b : forall phi,
  is_iter_box_of_box_free phi = true ->
  box_free_b (extract_inner_form phi) = true.
Proof.
  intros phi H. unfold is_iter_box_of_box_free in H. exact H.
Qed.

(** ** Correctness of the explicit decider. *)

Theorem glp_decide_b_correct : forall phi,
  is_iter_box_of_box_free phi = true ->
  (glp_dec_b phi = Some true <-> |- phi).
Proof.
  intros phi H.
  pose proof (extract_inner_box_free phi H) as Hbf.
  pose proof (fragment_inner_box_free_b phi H) as Hbfb.
  rewrite glp_dec_b_extract, Hbfb.
  split.
  - intro Hs. injection Hs as Hs.
    rewrite (extract_decomposition phi).
    apply (proj2 (provable_iter_box_box_free_iff_classical_valid
                    (extract_box_levels phi) (extract_inner_form phi) Hbf)).
    apply decide_tautology_correct. exact Hs.
  - intro Hp. f_equal.
    apply decide_tautology_complete.
    apply (proj1 (provable_iter_box_box_free_iff_classical_valid
                    (extract_box_levels phi) (extract_inner_form phi) Hbf)).
    rewrite <- (extract_decomposition phi). exact Hp.
Qed.

Theorem glp_decide_b_refute : forall phi,
  is_iter_box_of_box_free phi = true ->
  (glp_dec_b phi = Some false <-> ~ |- phi).
Proof.
  intros phi H.
  pose proof (extract_inner_box_free phi H) as Hbf.
  pose proof (fragment_inner_box_free_b phi H) as Hbfb.
  rewrite glp_dec_b_extract, Hbfb.
  split.
  - intros Hs Hp.
    apply (proj2 (glp_decide_b_correct phi H)) in Hp.
    rewrite glp_dec_b_extract, Hbfb in Hp.
    rewrite Hs in Hp. discriminate Hp.
  - intro Hnp. f_equal.
    destruct (decide_tautology (extract_inner_form phi)) eqn:Edt.
    + exfalso. apply Hnp.
      rewrite (extract_decomposition phi).
      apply (proj2 (provable_iter_box_box_free_iff_classical_valid
                      (extract_box_levels phi) (extract_inner_form phi) Hbf)).
      apply decide_tautology_correct. exact Edt.
    + reflexivity.
Qed.

(** ** The sumbool decider over the decidable fragment. *)

Definition glp_decide (phi : Form)
  (H : is_iter_box_of_box_free phi = true) : { |- phi } + { ~ |- phi }.
Proof.
  destruct (glp_dec_b phi) as [b|] eqn:E.
  - destruct b.
    + left. apply (proj1 (glp_decide_b_correct phi H)). exact E.
    + right. apply (proj1 (glp_decide_b_refute phi H)). exact E.
  - exfalso.
    rewrite glp_dec_b_extract, (fragment_inner_box_free_b phi H) in E.
    discriminate E.
Defined.

Theorem glp_decide_correct : forall phi (H : is_iter_box_of_box_free phi = true),
  match glp_decide phi H with left _ => True | right _ => False end <-> |- phi.
Proof.
  intros phi H. destruct (glp_decide phi H) as [p | np].
  - split; [intros _; exact p | intros _; exact I].
  - split; [intros [] | intros Hp; exact (np Hp)].
Qed.

(** ** The decider covers modal formulas beyond the box-free fragment. *)

Example glp_decide_box_tower_provable :
  is_iter_box_of_box_free (Box 3 (Box 1 (Impl (Var 0) (Var 0)))) = true /\
  glp_dec_b (Box 3 (Box 1 (Impl (Var 0) (Var 0)))) = Some true.
Proof. split; reflexivity. Qed.

Example glp_decide_box_bot_refuted :
  is_iter_box_of_box_free (Box 0 Bot) = true /\
  glp_dec_b (Box 0 Bot) = Some false.
Proof. split; reflexivity. Qed.

(** ** Obstruction: provability is not compositional, so the demanded
    total naive structural recursion cannot be complete. *)

Lemma not_provable_neg_box0_bot : ~ |- Neg (Box 0 Bot).
Proof.
  intro H.
  pose proof (soundness _ H Fnat (fun _ _ => true) 0) as Hf.
  apply Hf. intros v Hv. unfold Fnat_R in Hv. destruct Hv as [Hgt _]. lia.
Qed.

Theorem box_provability_noncompositional :
  exists n psi, |- Box n psi /\ ~ |- psi.
Proof.
  exists 1, (Neg (Box 0 Bot)). split.
  - exact (Ax_NextCon 0).
  - exact not_provable_neg_box0_bot.
Qed.

Theorem impl_provability_noncompositional :
  exists a b, |- Impl a b /\ ~ |- a /\ ~ |- b.
Proof.
  exists (Var 0), (Var 0). split; [|split].
  - exact (prov_id (Var 0)).
  - exact var_not_provable.
  - exact var_not_provable.
Qed.

(** Decidability holds as a proposition, classically, via excluded
    middle. *)

Theorem glp_provability_decidable_classically : forall phi,
  (|- phi) \/ ~ |- phi.
Proof. intro phi. apply classic. Qed.

(** ** Decider summary. *)

Theorem glp_decide_summary :
  (* explicit lexicographic measure decreases through the Box recursion *)
  (forall n psi,
     modal_depth psi < modal_depth (Box n psi) /\
     form_length psi < form_length (Box n psi)) /\
  (* the constructive decider is correct on its fragment *)
  (forall phi (H : is_iter_box_of_box_free phi = true),
     match glp_decide phi H with left _ => True | right _ => False end <-> |- phi) /\
  (* it decides modal formulas beyond the box-free fragment *)
  (glp_dec_b (Box 3 (Box 1 (Impl (Var 0) (Var 0)))) = Some true) /\
  (glp_dec_b (Box 0 Bot) = Some false) /\
  (* provability is non-compositional: the naive total recursion fails *)
  (exists n psi, |- Box n psi /\ ~ |- psi) /\
  (exists a b, |- Impl a b /\ ~ |- a /\ ~ |- b).
Proof.
  split; [|split; [|split; [|split; [|split]]]].
  - exact glp_dec_b_measure_decreases.
  - exact glp_decide_correct.
  - reflexivity.
  - reflexivity.
  - exact box_provability_noncompositional.
  - exact impl_provability_noncompositional.
Qed.

